export default [{"id":41,"question":"سائل يقول: فضيلة الشيخ عبد العزيز، ما هي مبادئ وأسس الدعوة إلى الله؟ وما هي طرقها؟","title":"ما أهم أسس وطرق الدعوة إلى الله؟","answer":"الجواب: المبادئ معروفة: أولاً: المؤمن يجتهد في نفسه، ويتعلم، ويتبصر، ويتفقه.\nوإذا رزقه الله العلم وتفقه في دينه فإن المبدأ في ذلك: أن يدعو إلى الله بتعليم الناس، وبإرشاد الجاهل وتعليمه، وتوجيهه إلى الخير، وأمره بالمعروف، ونهيه عن المنكر، كما قال تعالى: قُلْ هَذِهِ سَبِيلِي أَدْعُو إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108].\nالمبدأ الأول: أن تتلقى العلم، وأن تتعلم وتتبصر، وتعتني بالقرآن وحفظه وتدبر معانيه، والسنة عن النبي ﷺ، حتى تحفظ منها ما تيسر، وتشتغل على أهل العلم، وتسأل أهل العلم، وتذاكر أهل العلم، حتى تكون على بينة.\nفإذا عرفت ما شرع الله لك، وما أوجب عليك، وما حرَّم عليك، تدعو إلى الله، فتكون ممن قال الله فيهم: وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:3] وممن قال فيهم: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [آل عمران:104]، وممن قال فيهم: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2].\nتنفع نفسك، وتنفع الناس بالحكمة والكلام الطيب، قال تعالى: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125].\nفتدعو إلى الله بالكلام الطيب، وترشد إليه، وتعلم الناس الخير، وتنهاهم عن الشر، هكذا ينبغي لك.","link":"https://binbaz.org.sa/fatwas/2821/ما-اهم-اسس-وطرق-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0014.mp3","categories":["الدعوة والدعاة"]},{"id":51,"question":"سائل آخر يقول: فضيلة الشيخ عبد العزيز بن باز، السلام عليكم ورحمة الله وبركاته:أولاً: أشهد الله أنني أحبك من أجله، وأسأل الله أن يطيل في عمرك وينفع بك جميع المسلمين.ثانيًا: إن أمتنا في الوقت الحالي تحتاج إلى العمل الصادق الدائم وليس إلى كثرة الكلام والخطب؛ فما هي السبل والطرق التي ترى وتقترح أن تقوم بها المراكز في الخارج لتكون الأقلية المسلمة في المجتمعات الغربية قرآنًا يسير على الأرض ويدعو إلى الإسلام الصحيح؟ وجزاكم الله خيرا.","title":"ما النصيحة تجاه دعوة الأقليّات بالخارج؟","answer":"الجواب: أولاً أحبك الله الذي أحببتنا له وجعلنا وإياك وسائر إخواننا وسائر المستمعين من المتحابين في الله عز وجل، فقد صح عن رسول الله عليه الصلاة والسلام، أنه قال يقول الله يوم القيامة: أين المتحابون بجلالي اليوم أظلهم في ظلي يوم لا ظل إلا ظلي وصح عنه عليه السلام أنه قال: سبعة يظلهم الله في ظله يوم لا ظل إلا ظله إمام عادل، وشاب نشأ في عبادة الله، ورجل قلبه معلق بالمساجد، ورجلان تحابا في الله اجتمعا على ذلك وتفرقا عليه، ورجل دعته امرأة ذات منصب وجمال فقال إني أخاف الله، ورجل تصدق بصدقة فأخفاها حتى لا تعلم شماله ما تنفق يمينه، ورجل ذكر الله خاليا ففاضت عيناه متفق على صحته.\nأما السؤال الثاني: فذلك متعيِّن، ولكن الخطب والمحاضرات والمؤلفات والمقالات التي تنشر كلها وسيلة إلى ما ذكرت من العمل؛ فالخطبة والمقالة الجيدة الموفقة إذا نُشرت أو وُزعت  أو أذيعت؛ ينفع الله بها من يشاء، فالله شرع الخطب وشرع الكتب والنصائح؛حتى ينتفع بها الناس، حتى يستعين بها الناس وحتى يفقهوا دينهم وحتى يتشجعوا على ما ينبغي لهم وعلى ما يطلب منهم، والواجب على العلماء وعلى المراكز الإسلامية وعلى الجمعيات الإسلامية وعلى كل من له قدرة في نفع العباد أن يمثل ذلك بالعمل لا بالقول فقط؛ فالقول ينفع في محله، ولكن الأهم العمل، فالقول المشروع مطلوب كذكر الله والأمر بالمعروف والنهي عن المنكر والاستغفار، والدعاء مطلوب، ولكن ما كان يتعلق بالعمل فالمطلوب العمل: كَبُرَ مَقْتًا عِنْدَ اللَّهِ أَنْ تَقُولُوا مَا لَا تَفْعَلُونَ [الصف:3]. فلا بدّ من العمل فيما يتعلق بالعمل من صلاة وصوم وجهاد وحج وزكاة وغير هذا من وجوه العمل، فلا بدّ من القول في محله ولا بد من العمل في محله، ومن صفات المنافقين أنهم يقولون ما لا يفعلون، فلا يجوز للمسلم أن يقول ما لا يفعل، بل يقول ويفعل، يكون صادقًا في قوله صادقًا في عمله، وعلى الحكام المسلمين أينما كانوا أن يُعنوا بأمر الله، فإن الزُّبْدة العظيمة من ولاية الحاكم على المسلمين أن يوجههم إلى دين وأن يلزمهم بأمر الله وأن يعينهم على طاعة الله وأن يمنعهم مما يخالف شرع الله؛ هذه الزبدة المقصودة من الولاية، المقصود من الولايات -سواء كانت الولاية مُلْكية أو رئاسة جمهورية أو إمارة أو غير هذا من الأسماء- المقصود من الولايات إقامة أمر الله في أرض الله، المقصود هو إقامة أمر الله في أرض الله؛ لتوجيه الناس إلى الخير وإلزامهم بما أوجب الله ومنعهم عما حرم الله وإقامة الحدود عليهم فيما أوجب الله إقامته، هذا هو الواجب. ووصيتي لجميع إخواني في كل مكان، في مراكز إسلامية في جمعيات إسلامية في معاهد في مدارس في أي عمل كانوا وفي أي مكان كانوا، وصيتي للجميع أن يتقوا الله وأن يلتزموا بأمر الله وأن يعتنوا بتوجيه عباد الله إلى دين الله وأن يكونوا دعاة خير ودعاة هدى، فقد صح عن رسول الله عليه الصلاة والسلام أنه قال: من دل على خير فله مثل أجر فاعله وقال لعلي  لما بعثه إلى خيبر لدعوة اليهود: فوالله لأن يهدي الله بك رجلا واحدًا خير لك من حمر النعم والله يقول في كتابه العظيم: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ [فصلت:33] ويقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَيُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُولَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71] ويقول سبحانه: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ [آل عمران:104] فجعلهم هم أهل الفلاح، حصره فيهم؛ لعِظَم ما قاموا به من الدعوة والأمر بالمعروف والنهي عن المنكر، وقال : كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنْكَرِ وَتُؤْمِنُونَ بِاللَّهِ [آل عمران:110]. هذا هو واجب المسلمين؛ الدعوة إلى الخير والأمر بالمعروف والنهي عن المنكر أينما كانوا، وبهذا يكون الإنسان من خير الأمة، بهذا يكون المؤمن والمؤمنة من خير الأمة بهذا العمل الجليل؛ الدعوة إلى الله والأمر بالمعروف والنهي عن المنكر والاستقامة على الحق. والله المستعان.","link":"https://binbaz.org.sa/fatwas/2962/ما-النصيحة-تجاه-دعوة-الاقليات-بالخارج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0025.mp3","categories":["الدعوة والدعاة"]},{"id":52,"question":"أحد الإخوة من الفلبين يسأل ويقول: من أساليب  تنصير المسلمين في الفلبين الآن تقديم المساعدات المادية والمعنوية من قبل القساوسة على إمام المسجد وجماعته على أن يسمحوا للقسيسين النصارى إلقاء محاضرة عن خليط من الإسلام والمسيحية، بدلًا من خطبة الجمعة وذلك أسبوعيًّا، و كيف نواجه هذا الأسلوب؟ أفيدونا جزاكم الله خيرًا.","title":"ما النصيحة لمواجهة جهود التنصير بالفلبين؟","answer":"الجواب: الواجب على المسؤولين عن المسلمين - العلماء وغيرهم - أن يحولوا بين هؤلاء وبين ما أرادوا، وأن يبذلوا المساعدة المستطاعة للمسلمين، وأن يَكْفُوهم الحاجة إلى عدوهم، وأن يحذروا مكائد الأعداء، وأن يحثوا المسلمين على الصبر والحرص على البعد عن أعدائهم والاختلاط بأعدائهم والسماع لتوجيهات أعدائهم؛ فإنهم يدعون إلى النار وأهل الإسلام يدعون إلى الجنة. فعلى المؤمن أن يصبر وأن يحتسب وأن يتصبر على ما قد يصيبه من ضعف وحاجة حتى يجد ما يسدّها، وعلى إخوانه المسلمين أن يواسوهم وأن يحسنوا إليهم وأن يتعاونوا في ذلك بكل ما يستطيعون ولو بالقليل؛ فإن القليل مع القليل يكون كثيرًا، إذا بذل هذا مستطاعه والآخر كذلك والآخر كذلك؛ تجمَّع الخير الكثير وانتفع به المحاويج من المسلمين واستغنوا به عن شر أعدائهم ومكائد أعدائهم الذين يتربصون بهم الدوائر، ويبذلون المال الذي يقودهم إلى النار، نسأل الله السلامة. ثم من المهمّات أن على رؤساء الأقليات الإسلامية وعلى أعيانهم أن يكتبوا لمن يرون فيه الخير، وأن يوضحوا حاجة إخوانهم الفقراء، وأن يستعينوا بمن حولهم من رؤساء المراكز الإسلامية والجمعيات الإسلامية؛ حتى يتم التعاون، لا يغفلوا، على الجميع أن يتعاونوا على البر والتقوى وعلى إيجاد المكاسب الطيبة التي تعينهم على طاعة الله في بلادهم، على أن يعتنوا بالمكاسب والصناعة التي تنفعهم بأي عمل ينفعهم؛ حتى يستغنوا عن الحاجة إلى أعدائهم، الرسول يقول عليه الصلاة والسلام في الحديث الصحيح: احرص على ما ينفعك واستعن بالله ولا تعجز رواه مسلم في الصحيح، فعلى المؤمن أن يبذل وسعه في طلب الرزق والحرص على طلب الرزق بالطرق الحلال؛ حتى يستغني عن الحاجة إلى أعداء الله.","link":"https://binbaz.org.sa/fatwas/2963/ما-النصيحة-لمواجهة-جهود-التنصير-بالفلبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0026.mp3","categories":["الدعوة والدعاة","قضايا معاصرة"]},{"id":58,"question":"سماحة الشيخ: يوجد عند طائفة من الناس نظرة غير متفائلة تجاه إخوانهم المستقيمين مما نتج عنه ابتعاد أولئك عن مجتمعات الصالحين، فما السبيل إلى إبعاد هذه الفجوة، وما موقف المستقيمين من هذه النظرة لهم؟","title":"حكم الجفاء والعنف في دعوة الناس","answer":"الجواب: الواجب على الملتزمين أن يتواضعوا وأن يتحروا الأسلوب الحسن والرفق بالناس لاسيما العامة، وأن يخاطبوهم بما يفهمون من الأساليب الواضحة اللينة، مع الرفق في كل الأمور، وألا يتكبروا وألا يستعملوا العنف في الكلام فإن هذا ينفّر من الحق ويبغّض الناس لأهل الحق، فينبغي للمؤمن، ولاسيما الداعية إلى الله وطالب العلم، أن يكون رفيقًا في كل أموره حليمًا متواضعًا في دعوته للناس وتعليمه الناس؛ حتى يقبلوا منه، يقول النبي عليه الصلاة والسلام: من يُحرم الرفق يُحرم الخير كله ويقول عليه الصلاة والسلام: عليكم بالرفق فإنه لا يكون في شيء إلا زانه ولا ينزع من شيء إلا شانه ويقول: يسّروا ولا تعسّروا، وبشّروا ولا تنفّروا. فالتعاظم من الملتزم والتكبر على الناس لأنه هداه الله ووفقه لشيء جهلوه هذا من أسباب حرمانه، من أسباب عدم توفيقه، من أسباب ضلاله بعد الهدى، فالواجب التواضع لله وعدم التكبر على عباد الله وأن يكون في نصيحته وتعليمه وإرشاده متواضعًا حليمًا رفيقًا يخاطب الناس بما يعرفون، وأن يخاطبهم بالأساليب الحسنة اللينة الطيبة، هذا هو الذي ينبغي؛ حتى لا ينفّر عنه إخوانه، وحتى لا يكرهوا موعظته، وحتى لا يتباعدوا عن قرب. رزق الله الجميع التوفيق. س: فضيلة الشيخ: ينظر بعض الشباب الملتزم إلى إخوانه مما يلاحظ عليهم ارتكاب بعض المعاصي الظاهرة نظرة فيها كثير من الجفاء والبعد عن حكمة التوجيه والدعوة إلى الله بأسلوب الداعية الحكيم، فما توجيهكم لهؤلاء، أثابكم الله؟ الشيخ: تقدم الكلام في هذا وأن الواجب عليهم التواضع وأن يخاطبوا الناس بالخطاب الحسن والأسلوب الحسن، وأن يرفقوا، وأن يستعملوا الحلم في كل الأمور وألا يتكبروا على عباد الله؛ بل يجب عليهم يحمدوا الله وأن يشكروه الذي منّ عليهم بالعلم ووفقهم وهداهم فلا يتكبروا بذلك على إخوانهم، ولا تَشْمَخ أنوفهم على إخوانهم تكبرًا وتعاظمًا لأنهم فهموا ما لم يفهموا لا، كان النبي ﷺ في غاية التواضع يعلم الجاهل ويرفق بالجاهل ولا يعنف عليه ولا يشدد، وفيما وقع من أخلاقه ﷺ وما جرى عليه عبرة وعظة لأهل العلم، من ذلك مما جرى في قصة الرجل الذي بال في المسجد فهمّ به الناس فقال: دعوه فلما فرغ من بوله دعاه وقال: إن هذه المساجد لا يصلح فيها شيء من هذا القذر إنما بنيت لذكر الله والصلاة وقراءة القرآن ولم يعنّفه ولم يشدّد عليه، بل علمه ما جهل، ومن ذلك قصة الأعرابي الذي جذبه برداءه حتى أثّر في صفحة عنقه، وقال: أعطني من مال الله الذي عندك، فتبسّم عليه الصلاة والسلام وأمر له بعطاء، ولم يعنّفه عليه الصلاة والسلام، ومن ذلك قصة معاوية بن الحكم لما عطس رجل بقربه في الصلاة فشمته قال: يرحمك الله، فرأى الناس ينظرون إليه فاستنكر ذلك وقال: وأمياه ما شأنهم ينظرون إليّ؟! فجعلوا يسكّتونه، يوصونه بالتسكيت، فسكت، فلما صلى أتى النبي ﷺ فعلمه عليه الصلاة والسلام، قال: والله ما رأيت أحسن تعليمًا منه عليه الصلاة والسلام فما كهرني ولا ضربني ولا شتمني، إلى آخر ما قال، بل علمه وأحسن تعليمه عليه الصلاة والسلام، وبيّن له أن هذه الصلاة لا يصلح فيها شيء من كلام الناس، إنما هي التسبيح والتكبير وقراءة القرآن، فلم يشدّد عليه الصلاة والسلام بل علمه، وكذلك قصة المسيء في صلاته الذي صلى ولم يطمئن فدعاه النبي ﷺ وقال: ارجع فصل فإنك لم تصل ولم يقل: يا خبيث أو يا جاهل أو يا ضال، قال: ارجع فصل فإنك لم تصل فرجع فصلى كما صلى، ثم جاء فسلم على النبي ﷺ فرد عليه السلام وقال: ارجع فصل فإنك لم تصل، فرجع فصلى كما صلى ثم جاء فسلم على النبي ﷺ فرد عليه، ما هجره، رد عليه السلام، وقال: ارجع فصل فإنك لم تصل فقال: والذي بعثك بالحق نبيًّا لا أحسن غير هذا فعلمني فعلمه النبي ﷺ فقال: إذا قمت إلى الصلاة فأسبغ الوضوء ثم استقبل القبلة فكبّر ثم اقرأ ما تيسر معك من القرآن ثم اركع حتى تطمئن راكعًا... الحديث. فلم يشدّد عليه ولم يسبّه ولم يقل: يا جاهل أو يا فاجر أو يا خبيث، أو يا كذا من الألفاظ النابئة لا، بل علّمه وأحسن تعليمه عليه الصلاة والسلام، ففي هذه الوقائع وأشباهها عظة للداعية وذكرى؛ حتى يرفق بالناس، وحتى يستعمل الألفاظ الطيبة، وحتى يبتعد عن كل لفظ يؤذي الناس وينفّرهم من الحق، نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/2969/حكم-الجفاء-والعنف-في-دعوة-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0032.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":62,"question":"فضيلة الشيخ: السلام عليكم ورحمة الله وبركاته، وبعد: فإني أحبكم في الله تعالى كثيرًا، وأرجو من الله تعالى أن يجعلنا وإياكم من المتحابين فيه تعالى آمين.وبعد: فإن لي أخ من أم وأب وهو لا يصلي في المسجد، وليس يسكن معي، وهو يريد الزواج وطلبت مني أمي أن أذهب معه من أجل أن أخطب له فرفضت ذلك قائلا: لا؛ لأنه لا يصلي، ولكن عندما يصلي ويشهد له إمام المسجد في منزله عند ذلك أذهب معه وأخطب له، ولكن يا شيخ الآن أمي لا تكلمني وجميع إخواني وأخواتي لا يكلموني وقاطعوني، والحمد لله على كل حال؟","title":"ما الواجب تجاه الأخ الذي لا يصلي؟","answer":"الجواب: أما الحب في الله، نقول: أحبك الله الذي أحببتنا له، كما تقدم أن الحب في الله من أفضل القربات. وأما ما ذكرت عن أخيك: فالواجب عليك وعلى إخوانك  جميعًا أن تنصحوه، وأن تتصلوا به جميعًا، لا وحدك؛ بل يكون معك غيرك لعله يؤثر عليه ذلك، ولعله يستجيب لداعي الحق؛ لأنك إذا كنت وحدك قد لا يبالي، ولاسيما إذا كان أكبر منك، فالمقصود أنه ينبغي أن تتابع النصيحة وأن يكون معك غيرك من إخوانك الطيبين أو من جيرانك؛ لعله يقبل منكم فيصلي ويحافظ على الصلاة في الجماعة، ثم تنفذ رغبة أمك وإخوانك في مساعدته والذهاب معه إلى الجهة التي يخطب منها بعدما يهديه الله لهذا الأمر ويقبله  منكم ويصلي. أما إذا أصرّ على عدم الصلاة فلا تذهب معه، بل اهجره حتى يتوب إلى الله وحتى يرجع إلى الصواب والحق، ولو غضبت أمك ولو غضب إخوانك؛ لأن الذي لا يصلي كافر في أصح قولي العلماء، مَن ترك الصلاة وتعمد تركها كفر كما قال النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة في أحاديث أخرى كثيرة تدل على ذلك. أما تركه الصلاة بالجماعة فهذا أسهل قد يكون له شبهة لأن بعض العلماء لا يرون وجوب الجماعة فلا بأس، فينبغي لك أن تتصل به مع إخوانك وأن تجتهد في صلاته بالجماعة إذا كان يصلي ولكن لا يصلي في الجماعة، هذا أسهل؛ فعليك أن تتصل به مع إخوانك ومع  غيرهم من جيرانك ومن يساعدك في هذا؛ لعل الله يهديه بأسباب ذلك؛ حتى تجمع بين المصالح كلها بين رضا أمك وإخوانك وبين هداية الله له على يديك وعلى يد إخوانك الذين يصحبونك في دعوته إلى الله ، رزق الله الجميع التوفيق والهداية.","link":"https://binbaz.org.sa/fatwas/2978/ما-الواجب-تجاه-الاخ-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0037.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة","الرقائق"]},{"id":93,"question":"أنا رجلٌ أقوم بالدعوة والإرشاد والأمر بالمعروف والنَّهي عن المنكر، وإنكار المنكرات على الناس، ولكن هناك مَن يتصدَّى لي ويقول: إنَّك تتدخل فيما لا يعنيك، وإنك تُثير فتنةً، فما الحكم في ذلك؟","title":"ما واجب كل مسلم في الدعوة وإنكار المنكر؟","answer":"الجواب: إذا كان عندك علمٌ وتدعو إلى الله على بصيرةٍ فلا تلتفت إلى مَن ثَبَّطك، فادعُ إلى الله، وعلِّم الناس، وَأْمُرْ بالمعروف، وانهَ عن المنكر، مع الحلم والصبر والاحتساب وطيب الكلام، كما قال الله جلَّ وعلا: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ.. [التوبة:71]، وقال سبحانه: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنْكَرِ.. [آل عمران:110]، وقال سبحانه: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ [فصلت:33]، وقال سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ.. [النحل:125].\nفاستمر على ذلك ما دام عندك علمٌ، فاستقم على ذلك، ولا تلتفت إلى مَن ثبَّطك، لكن عليك بالحكمة، وعليك بـ: قال الله ورسوله، ووضع الأشياء في مواضعها، والحلم والصبر، وعدم العجلة في الأمور، وعليك بالرفق وطيب الكلام.","link":"https://binbaz.org.sa/fatwas/3108/ما-واجب-كل-مسلم-في-الدعوة-وانكار-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0070.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":129,"question":"سائلٌ يقول: وظيفتي وطبيعة عملي تستدعي مُخالطة جاليات غير مسلمة ومعاشرتهم، وقد نُفطر معًا في مقر العمل، وقد نبدأهم بالسلام أو التحية، فكيف نُحقق جانب الولاء والبراء مع هؤلاء؟","title":"حكم مخالطة الجاليات غير المسلمة","answer":"الجواب: عليك أن تنصحهم وتدعوهم إلى الله، وتُعاملهم بما تدعو الحاجةُ إليه: سؤالهم عن معاملة، إعطاؤهم معاملة يعملونها، ردّ السلام عليهم إذا سلَّموا هم، ولا تبدأهم أنت، وهكذا. أما اتِّخاذهم أصحابًا وأحبابًا ومُعاشرتهم كأنَّهم مسلمون فلا، ما يجوز هذا، لكن تُعاملهم بما تدعو الحاجة إليه في أنظمة الوظيفة: من معاملة تُعطى إياه، أو تُؤخذ منه، أو يُسأل عنها: أين ذهبت؟ أين جئت؟ ولا بأس أن يُقال: كيف أولادك؟ كيف حالك؟ ما هو ببدءٍ بالسلام، وإذا سلم تقول: وعليكم السلام.","link":"https://binbaz.org.sa/fatwas/3655/حكم-مخالطة-الجاليات-غير-المسلمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0118.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":233,"question":"يقول بأنه أحد الطلبة في السكن الجامعي، ويقول بأنه يُعاني من بعض الطلاب الذين لا يُصلون، وعندما يحين وقتُ الصلاة يقعدون عند التلفاز، بحيث إننا نُصلي ونعود وهم في أماكنهم، يقول: فنرجو من الله ثم من سماحتكم أن تقترحوا حلًّا لهذه المشكلة.","title":"حكم من يسكن مع زملاء لا يصلون","answer":"الجواب: هذه مصيبةٌ عظيمةٌ، فإنَّ الطالب قدوةٌ لزملائه وغيرهم، والواجب أن يكون قمةً في الخير، وأن يكون قدوةً صالحةً لزملائه وغيرهم، والصلاة عمود الإسلام، وهي أعظم الفرائض بعد الشَّهادتين، فالواجب على طلبة العلم وعلى كل مسلمٍ العناية بالصلاة، والاهتمام بها، والحذر من التهاون بها، وعلى إخوانه وزملائه إذا رأوا منه منكرًا أن يُنكروا عليه، وأن ينصحوه، وأن يجتهدوا في استقامته، يقول الله جلَّ وعلا في كتابه المبين: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَيُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُولَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71].\nفالمؤمنون والمؤمنات أولياء يتناصحون، ليسوا بأعداء، بل أولياء يتناصحون، وينصح بعضُهم بعضًا، ويُحذِّر بعضُهم بعضًا من الباطل، لا يحسده، ولا يخونه، ولا يغشه، ولا يكذب عليه، ولا يشهد عليه بالزور، ولا يتركه على منكرٍ، بل يُعلّمه ويُوجهه إلى الخير، ويُنكر عليه المنكر.\nفالمؤمن يُنكر على أخيه وعلى أخته في الله، والمؤمنات كذلك تُنكر على أختها في الله وعلى أخيها في الله إذا رأت منه منكرًا.\nفعلى الطلبة أن يُنكر بعضُهم على بعضٍ إذا رأوا من زملائهم المنكر: من ترك الصلاة، أو التهاون بها، أو شرب المسكر، أو التدخين، أو إسبال الملابس، أو حلق اللحى، أو غير هذا مما يُنكر، فهكذا المؤمنون يتناصحون، ويأمرون بالمعروف، وينهون عن المنكر أينما كانوا: في الكلية، في المطعم، في الطريق، في المسجد، في السفر، في الإقامة، في الطائرة، في القطار، في السيارة، في كل مكانٍ، هكذا المؤمنون والمؤمنات أينما كانوا.\nوبهذا يصلح المجتمع، وبهذا يسلموا من غضب الله وعقابه، أما إذا تساكت الناسُ فقد أحلّوا بأنفسهم عقاب الله، في \"الصحيحين\" عن زينب بنت جحشٍ أم المؤمنين رضي الله عنها: أن النبيَّ عليه الصلاة والسلام دخل عليها ذات يومٍ وهو غضبان يقول: ويلٌ للعرب من شرٍّ قد اقترب، فُتح اليوم من ردم يأجوج ومأجوج مثل هذه وأشار بأصبعيه: الإبهام والوسطى، فقالت له زينب: يا رسول الله، أنهلك وفينا الصَّالحون؟ قال: نعم، إذا كثر الخبث، فبيَّن عليه الصلاة والسلام أنَّ الناس يهلكون إذا كثر فيهم الخبثُ، والخبث هو المُنكر والسعي..... في المعاصي، فإذا وُجد الخبثُ ولم يُنكر عمَّت العقوبة.\nوقال عليه الصلاة والسلام: إنَّ الناس إذا رأوا المنكر فلم يُغيروه أوشك أن يعمَّهم الله بعقابه خرجه الإمام أحمد وغيره بإسنادٍ صحيحٍ من حديث الصديق .\nفالواجب على الأساتذة والموظفين والطلبة -على الجميع- أن يأمروا بالمعروف، وأن ينهوا عن المنكر، هذا هو الواجب على الجميع، لا يخص واحدًا دون واحدٍ، ولا يجوز التواكل، لكن بالحكمة، بالكلام الطيب، بالأسلوب الحسن، بالمُواظبة، فالأستاذ والمدرسة والطالبة والموظفة والموظف والطالب كلهم شُركاء في هذا الأمر، فعلى الجميع أن يأمر بالمعروف، وأن ينهى عن المنكر، وعدم الغفلة، وعدم التساهل؛ حتى يكونوا قدوةً صالحةً لغيرهم في هذا الخير العظيم، وحتى ينفع بعضُهم بعضًا، وحتى يأخذ بعضُهم على يد بعضٍ، وحتى يسود الخيرُ، وحتى يقلَّ الشرُّ.\nهكذا أمر الرسولُ ﷺ، بل هكذا أمر الله عزَّ وجل، وبهذا تصلح المُجتمعات، ويأمن المجتمع من عقاب الله سبحانه وتعالى، ومتى أخلَّ الناسُ بهذا الأمر فهم على خطرٍ عظيمٍ، ولا حول ولا قوة إلا بالله، قال الله عزَّ وجل: لُعِنَ الَّذِينَ كَفَرُوا مِنْ بَنِي إِسْرَائِيلَ عَلَى لِسَانِ دَاوُودَ وَعِيسَى ابْنِ مَرْيَمَ ذَلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ  ۝  كَانُوا لَا يَتَنَاهَوْنَ عَنْ مُنْكَرٍ فَعَلُوهُ لَبِئْسَ مَا كَانُوا يَفْعَلُونَ [المائدة:78- 79]، وأخبر أنَّهم لُعنوا على لسان أنبيائهم بسبب هذا: ذَلِكَ بِمَا عَصَوْا يعني: بسبب عصيانهم واعتدائهم: ذَلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ، ثم فسَّر ذلك بقوله: كَانُوا لَا يَتَنَاهَوْنَ عَنْ مُنْكَرٍ فَعَلُوهُ، فعلى المؤمن وعلى المؤمنة الحذر.","link":"https://binbaz.org.sa/fatwas/4091/حكم-من-يسكن-مع-زملاء-لا-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0243.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":252,"question":"هل يجوز للمرأة المسلمة كثرة الخروج من البيت للدعوة إلى الله تعالى؟","title":"حكم خروج المرأة للدعوة إلى الله تعالى","answer":"الجواب: هذا عملٌ صالحٌ، خروج المرأة للدعوة عمل صالح، وأما قوله: وَقَرْنَ فِي بُيُوتِكُنَّ [الأحزاب:33] فالأمر بالمكث في البيوت عند عدم الحاجة، أما إذا كانت هناك حاجة: كالخروج للوعظ والتَّذكير بين النساء، أو الخروج لشهادة الصلاة مع الرجال لمصلحةٍ رأتها، مع الحجاب والتَّستر؛ فقد خرجت النساء في عهد النبي ﷺ -نساء الصحابة- وصلين مع النبي ﷺ في مسجده ﷺ، مع الحجاب والستر.\nوهكذا خروجها لزيارة والديها أو أقاربها، مع الحجاب والستر، أو عيادة المريض، أو تعزية المُصابين، أو الدعوة إلى الله ، أو أشباه هذا من المقاصد الطيبة، لكن مع مُراعاة ما أمر الله به من الحجاب والستر وعدم التَّبرج وعدم تعاطي أسباب الفتنة.\nوالنساء في حاجةٍ إلى الدعوة كما أنَّ الرجال في حاجةٍ إلى الدعوة، فالكل محتاج إلى الدعوة، ولو نصحت الرجال أيضًا ووعظت الرجال فلا بأس، تقدم أنَّ صوتها ليس بعورةٍ، صوتها في الدَّعوة إلى الله والتَّوجيه إلى الخير وإنكار المنكر ليس بعورةٍ، العورة التَّغنج والخضوع كما تقدَّم.","link":"https://binbaz.org.sa/fatwas/4243/حكم-خروج-المراة-للدعوة-الى-الله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0294.mp3","categories":["الدعوة والدعاة","قضايا المرأة"]},{"id":260,"question":"صاحب السَّماحة، إني أحبُّكم في الله، ما رأي سماحتكم فيمَن يتصدَّى للدعوة إلى الله بغير عُدَّةٍ علميةٍ ولا خبرةٍ؟ وهل من الأمانة نحو الدَّعوة أن يقع هذا؟ وما الطريق الصَّحيح الذي ترونه لإعداد الدُّعاة والقيام بأمانة الدعوة، أثابكم الله؟","title":"حكم من يتصدَّر للدَّعوة بدون علمٍ ولا خبرةٍ","answer":"الجواب: أولًا: أحبَّك الله الذي أحببتنا له، نسأل الله أن يجعلنا جميعًا مُتحابين في جلاله، فقد قال النبيُّ عليه الصلاة والسلام: يقول الله  يوم القيامة: أين المُتحابُّون بجلالي؟ اليوم أُظلّهم في ظلِّي يوم لا ظلَّ إلا ظلي، ويقول جلَّ وعلا: وجبت محبَّتي للمُتحابين فيَّ، والمُتباذلين فيَّ، والمُتجالسين فيَّ، والمُتزاورين فيَّ، نسأل الله أن يجعلنا وإيَّاكم منهم.\nوأما ما يتعلق بالدعوة على غير علمٍ: فهذا لا يجوز، فالواجب على الدَّاعي أن يتأهَّل أولًا، وأن يعدَّ العُدَّة لدعوته، حتى يكون على علمٍ وبصيرةٍ بما يدعو إليه، وبما ينهى عنه، قال الله : قُلْ هَذِهِ سَبِيلِي أَدْعُو إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108]، قال لنبيه: قُلْ يعني: قل يا أيها الرسول للناس، هَذِهِ سَبِيلِي يعني: هذه طريقي، أَدْعُو إِلَى اللَّهِ عَلَى بَصِيرَةٍ يعني: على علمٍ، فلا بد من العلم.\nويقول الله : ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ [النحل:125]، والحكمة هي العلم: قال الله، وقال الرسول، أما أن يتصدَّى للدعوة على جهلٍ وعلى غير بصيرةٍ فهذا لا يجوز، بل يُفسد أكثر مما يُصلح، يقول الله سبحانه: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالْإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لَا تَعْلَمُونَ [الأعراف:33]، فجعل القولَ عليه بغير علمٍ فوق مرتبة الشرك؛ لما يترتب على هذا من الفساد العظيم.\nوقال سبحانه: يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الْأَرْضِ حَلَالًا طَيِّبًا وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ ۝ إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لَا تَعْلَمُونَ [البقرة:168- 169]، فبيَّن سبحانه أنَّ الشيطان يأمر بالسوء والفحشاء، وأن نقول على الله ما لا نعلم.\nفالقول على الله بغير علمٍ هو مما يأمر به الشيطان، ويدعو إليه؛ لعلمه بأنه يترتب عليه من الفساد ما لا يُحصيه إلا الله ، فالدَّاعي الجاهل يُنَفِّر عن الدين، ويُحلّ الحرام، ويُحرّم الحلال، ويدعو إلى ما لا يجوز؛ لجهله، قال سبحانه: وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِ عِلْمٌ إِنَّ السَّمْعَ وَالْبَصَرَ وَالْفُؤَادَ كُلُّ أُولَئِكَ كَانَ عَنْهُ مَسْئُولًا [الإسراء:36]، فالواجب على الدَّاعي إلى الله أن يتَّقي ربَّه، وأن يعد العدَّة قبل ذلك.\nوطريق العلم أن يحضر حلقات العلم، وأن يعتني بطلب العلم، وأن يُعنى بكتاب الله: قراءةً وتدبُّرًا وتعقُّلًا وتفهُّمًا، ويعتني بالسنة -سنة الرسول ﷺ- ويحفظ ما تيسر منها، مع الكتاب العزيز، ويجتهد في فهم الكتاب والسنة، ويسأل أهل العلم عمَّا أشكل عليه، ثم إذا أحسَّ من نفسه أنه تأهَّل لهذا الأمر؛ لأنه كثر علمه بما أمر الله، وبما نهى الله، وعرف ما أوجب الله وما حرَّم الله، كان على هدى في ذلك وعلى بصيرةٍ؛ فيدعو إلى ما أمر الله به ورسوله، وينهى عمَّا نهى الله عنه ورسوله.\nهذا هو الواجب على مَن يريد الدعوة إلى الله ومَن يتصدر لذلك: أن يُعنى بالعلم، والعلم ليس بالتَّمني، يحتاج إلى جهودٍ، إلى صبرٍ، وبهذا يقول ﷺ: مَن سلك طريقًا يلتمس فيه علمًا سهَّل الله له به طريقًا إلى الجنة، ويقول ﷺ: مَن يُرد الله به خيرًا يُفقهه في الدين متفقٌ على صحَّته، هذا دليلٌ على أن الله سبحانه إذا أراد بالعبد خيرًا فقهه في الدين، وجعله يتبصَّر ويتعلم ويعتني بما أوجب الله عليه، وما حرَّم عليه، حتى يعبد ربَّه على بصيرةٍ، ومفهومه أنَّ مَن لم يُوفَّق في الفقه في الدين معناه: أن الله ما أراد به خيرًا، فالخطر عظيم في الإعراض والجهل وعدم المُبالاة.","link":"https://binbaz.org.sa/fatwas/4254/حكم-من-يتصدر-للدعوة-بدون-علم-ولا-خبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0305.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":279,"question":"يُلاحظ على كثيرٍ من الشباب الصالح أنَّ قسمًا منهم اتَّجه إلى طلب العلم وترك الدعوة إلى الله، مع القُدرة على ذلك، والقسم الآخر اتَّجه إلى الدعوة إلى الله وترك طلب العلم، فأيُّهما أفضل؟","title":"كيف يكون الجمع بين طلب العلم والدعوة؟","answer":"الجواب: لا هذا، ولا هذا، الواجب الجمع بينهما، وألا يزال طالبًا وداعيًا إلى الله ، فوقتٌ لهذا، ووقتٌ لهذا، والأمر ممكنٌ، فطالب العلم يعتني بطلب العلم ويتزود، والله قال لنبيه: وَقُلْ رَبِّ زِدْنِي عِلْمًا [طه:114]، وهو نبي الله عليه الصلاة والسلام، فلا يزال طالبُ العلم في طلب العلم، ولو كان في القمة لا بدّ أن يطلب العلم، ولا بدّ أن يجتهد في المُراجعة، وفي المُذاكرة -مذاكرة أهل العلم فيما أشكل عليه- حتى يزداد علمًا، فيجمع بين الأمرين: بين حلقات العلم، بين مطالعة الكتب، بين المُذاكرة مع زملائه وإخوانه، وبين الدَّعوة إلى الله في أهله وجيرانه وبلده وغيرها، فلا ينفرد للدعوة فقط، ولا ينفرد للتعلم فقط، ولكن يجمع بينهما.\nففي أول الطلب وقبل أن يصل إلى درجة أهل العلم الذين يستقلُّون بالبحث يكون همُّه الطلب، وتكون همَّته مصروفة إلى طلب العلم، ويكون وقته على هذا الشيء الذي يكون هو المُقدم، وهو طلب العلم، حتى يزداد علمًا، وحتى يتأهَّل للدعوة، ويتأهل للمُذاكرة ومُراجعة الكتب في أول الطريق، لا يتأهَّل لهذا الشيء، فلا بدّ أن يكون عنده علمٌ بالأصول: أصول الفقه، مصطلح الحديث، معرفة الأحكام الشرعية؛ حتى يتأهل لمُراجعة الأدلة، وترجيح الراجح من مسائل الخلاف، وتزييف الزائف، وحتى يتصدر للدَّعوة إلى الله، وحتى لا يقع في تحليل ما حرَّم الله، أو في تحريم ما أحلَّ الله؛ لقلة علمه.\nفلا بدّ من العناية أولًا وقبل كل شيءٍ بطلب العلم والتَّفقه في الدين، ولا يمنعه هذا أن يدعو إلى الله على حسب علمه في محيطه وما حوله، ثم إذا بلغ مبلغ أهل العلم جدَّ في الدعوة إلى الله ، مع بقائه في طلب العلم، ومع بقائه في أسباب التَّحصيل والمُراجعة والمُذاكرة ومُطالعة الكتب، وتحقيق ما أشكل عليه من مسائل الخلاف، لكنه مشغولٌ بالدعوة أكثر؛ لتأهّله لهذا الشيء، ولكونه حصَّل من العلم ما يجعله أهلًا لأن يُعلِّم، ولأن يدعو إلى الله، ويُرشد الناس إلى الخير.","link":"https://binbaz.org.sa/fatwas/4277/كيف-يكون-الجمع-بين-طلب-العلم-والدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0326.mp3","categories":["العالم والمتعلم","الدعوة والدعاة"]},{"id":363,"question":"لي جيرانٌ لا يُؤدون الصلاة في المسجد، وأنا أحضر مجالسهم وأُخالطهم كثيرًا، حتى على ولائمهم، وذلك من باب النَّصيحة، وأذكر حديثًا أو مناقشة موضوع بيني وبينهم، هل يجوز لي ذلك؟ علمًا بأنَّ بعض المجالس يُشرب بها الدخان، ويكثر فيها الكلام الذي لا فائدةَ فيه، وأنا هدفي من مُخالطتهم النَّصيحة؟","title":"ما الواجب تجاه الجيران الذين لايصلون؟","answer":"الجواب: الواجب على مَن كان له جيرانٌ لا يُصلون أو يتعاطون المسكر أو نحو ذلك من المعاصي: أن ينصحهم، وأن يُحرضهم على تقوى الله، فإنَّ الجار له حقٌّ على جاره، تقدَّم قول النبي ﷺ: مَن كان يؤمن بالله واليوم الآخر فليُحْسِن إلى جاره، فالجار له حقٌّ، والنَّصيحة بالحقِّ تنصحه، وتأمره بالمعروف، وتنهاه عن المنكر، وتجتهد في ذلك، فإذا أصرَّ وأبى ينبغي أن تُقاطعه، ينبغي أن تهجره ولا تأتي إلى دعوته ووليمته، ولا تتخذه جليسًا، وهكذا الجماعة من الجيران إذا لم يقبلوا النَّصيحة وأصرُّوا على ترك الصلاة في المساجد، فهذه علامة النِّفاق، وهذا دليل النفاق، فينبغي هجرهم، وعدم مُجالستهم، وعدم إجابة دعوتهم حتى يستجيبوا لداعي الحقِّ.\nوإذا نصحتهم فالأوْلى والأفضل أن يكون معك غيرُك، يكون معك بعض جيرانك الطيبين، تذهب إليهم ومعك اثنان، ثلاثة، أربعة، تنصحونهم؛ لأنَّ هذا أقرب إلى التأثير، إذا كانت النصيحة من جماعةٍ أقرب إلى التَّأديب للمنصوحين، أما أن تستمر معهم على باطلهم فلا يصلح هذا.\nوقد جاء في حديث ابن مسعودٍ عن النبي ﷺ أنه قال: لما وقعت بنو إسرائيل في المعاصي نهتهم علماؤهم، فلم ينتهوا، فجالسوهم، وواكلوهم، وشاربوهم، فلمَّا رأى الله ذلك منهم ضرب قلوبَ بعضهم ببعضٍ، ثم لعنهم على لسان دواد وعيسى ابن مريم، وأنزل في هذا قوله سبحانه: لُعِنَ الَّذِينَ كَفَرُوا مِنْ بَنِي إِسْرَائِيلَ عَلَى لِسَانِ دَاوُودَ وَعِيسَى ابْنِ مَرْيَمَ ذَلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ ۝ كَانُوا لَا يَتَنَاهَوْنَ عَنْ مُنْكَرٍ فَعَلُوهُ لَبِئْسَ مَا كَانُوا يَفْعَلُونَ [المائدة:78- 79].\nفالواجب على المسلمين التناصح، والتَّعاون على الخير، والتآمر بالمعروف، والتناهي عن المنكر، وإذا رأوا من قريبهم أو جارهم الإصرار على المعصية وعدم الاستجابة تركوه، ولم يتَّخذوه جليسًا، بل هجروه حتى يرعوي.","link":"https://binbaz.org.sa/fatwas/4559/ما-الواجب-تجاه-الجيران-الذين-لايصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0418.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":370,"question":"نرجو من سماحتكم أن تُوضح لنا كيف تكون العلاقةُ والمعاملةُ بين الموظف المسلم وبين الموظفين (من غير المسلمين)، إذا كان هذا الموظفُ المسلم وهؤلاء يعملون في نفس العمل، وفي نفس المؤسسة الحكومية، حيث إن هذا المطلوب منه: أن يتعلم منهم، أن يتعلم منهم ليُرشد مثلهم، وليوجد العمل على الوجه المطلوب؟","title":"ما كيفية معاملة زملاء العمل غير المسلمين؟","answer":"الجواب: الواجب على المؤمن إذا بُلي بهؤلاء أن يتميز بإيمانه، وأن يكون داعيةً إلى الخير، ومُرشدًا إلى الخير، وحريصًا على إيصال الخير إلى مَن حوله من المسلمين وغيرهم، فإذا بُلي بكفرةٍ يعملون معه؛ حرص على نصيحتهم، وعلى دعوتهم إلى الله ، وعلى بيان حقيقة الإسلام لهم بفعله وقوله؛ لعله يكون سببًا لهدايتهم، كما قال النبيُّ عليه الصلاة والسلام: مَن دلَّ على خيرٍ فله مثل أجر فاعله، مَن دعا إلى هُدًى كان له مثل أجور مَن تبعه، لا ينقص ذلك من أجورهم شيئًا، فيكون محافظًا على دينه، قدوةً حسنةً لزملائه في الأمانة، في أداء الأمانة، في النصح، في العمل، بعدم التَّساهل في ذلك، في الإكثار من ذكر الله، والمحافظة على ما أوجب الله عليه؛ حتى يقتدي به مَن حوله من الزملاء من مسلم وكافرٍ.\nوأن يحذر أن يغترَّ بما يُلقون من شُبَهٍ، فليحذر ذلك غاية الحذر، ويكون هو الذي يدعو، وهو الذي يُوَجِّه، وهو الذي يُرشد، ولا مانع من أن يستفيد من ذلك الكافر في طبٍّ أو هندسةٍ أو غير ذلك مما قد يطلبه هذا العامل، مع حذره، ومع ابتعاده عن أسباب الخطر، ومهما أمكن أن يكون في مؤسسةٍ أو دائرةٍ سليمةٍ من أولئك، بعيدةٍ عن الخطر، فهو خيرٌ له إن استطاع، ومتى بُلي بهذا الشيء فليحذر، وليتَّقِ الله، وليكن داعيةً إلى الخير، مُوَجِّهًا إلى الخير، بعيدًا عن خطر المقاربة لهؤلاء والاتِّصال بهم.","link":"https://binbaz.org.sa/fatwas/4625/ما-كيفية-معاملة-زملاء-العمل-غير-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0425.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":428,"question":"سماحة الشيخ، أخبرك بأني أحبّك في الله، سماحة الشيخ، مَن هم الذين يجب عليهم الأمر بالمعروف والنَّهي عن المنكر؟ وما درجات الأمر بالمعروف والنهي عن المنكر؟ مع أمثلةٍ في هذا الزمان.","title":"ما منزلة الأمر بالمعروف وعلى من يجب؟","answer":"الجوب: أما المحبَّة فنقول: أحبَّك الله الذي أحببتنا له، ونسأل الله أن يجعلنا جميعًا من المتحابين في جلاله، وأن يحشرنا مع أولئك الأخيار، يقول النبيُّ ﷺ: يقول الله  يوم القيامة: أين المتحابّون بجلالي؟ اليوم أظلّهم في ظلي يوم لا ظلَّ إلا ظلي أخرجه مسلم في \"الصحيح\"، وفي \"الصحيحين\" من حديث أبي هريرة: سبعة يُظلّهم الله في ظلِّه يوم لا ظلَّ إلا ظله منهم: رجلان تحابَّا في الله، اجتمعا على ذلك، وتفرَّقا عليه، وفي \"موطأ مالك\" بإسنادٍ جيدٍ عن النبي ﷺ قال: وجبت محبتي للمُتزاورين في، والمتجالسين فيَّ، والمتحابّين في، والمتباذلين في، جعلنا الله وإياكم منهم.\nأما ما يتعلق بالأمر بالمعروف والنهي عن المنكر: فهذا له شأنٌ عظيمٌ، وقد سمعتم بعض الشيء في هذا، فالله يقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]، ومن خصال المؤمن ومن صفاته الواجبة؛ لأنَّ المذكور في الآية الصفة الواجبة، فمن صفاته الواجبة وفرائض الله عليه أنه يأمر بالمعروف وينهى عن المنكر، هذا أمرٌ لازمٌ لكل مؤمنٍ، ليس خاصًّا بأحدٍ، وقال : كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنْكَرِ وَتُؤْمِنُونَ بِاللَّهِ [آل عمران:110]، فجعل الأمة كذلك كلها، ثم قدَّم الأمر والنَّهي، قدَّمه على الإيمان.\nهذا يدل على العناية والاهتمام، وعظم المنزلة، الإيمان هو أصل الدين، وأساس الملة، ومع هذا قدَّم عليه -وهو جزء منه- الأمر بالمعروف والنَّهي عن المنكر، شعبة من الإيمان، شعبة من شعب الإيمان، لكن لعظم الأمر وشدَّة الضَّرورة إليه قُدِّم، كما قُدِّم في آية براءة: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ، ثم قال: وَيُقِيمُونَ الصَّلَاةَ [التوبة:71]، فقدَّمه على الصلاة لعظم الأمر وشدة الضَّرورة إلى هذا الواجب العظيم، الذي به صلاح الناس، وردعهم عن الباطل، وإلزامهم بالحقِّ، والأخذ على أيدي السُّفهاء.\nولهذا تقدَّم لكم في الحديث يقول ﷺ: إن الناس إذا رأوا المنكر فلم يُغيروه أوشك أن يعمَّهم الله بعقابه، وفي اللفظ الآخر: يقول ﷺ: يقول الله : مروا بالمعروف، وانهوا عن المنكر قبل أن تدعوني فلا أستجيب لكم، وقبل أن تسألوني فلا أُعطيكم، وقبل أن تستنصروني فلا أنصركم، وفي اللفظ الآخر: لتأمرنَّ بالمعروف، ولتنهونَّ عن المنكر، أو ليوشكنَّ الله أن يُرسل لكم عقابًا من عنده -أو قال: يُنزل عليكم عقابًا من عنده- ثم تدعونه فلا يستجيب لكم.\nوفي حديث ابن مسعودٍ لما ذكر النبيُّ ﷺ قصة بني إسرائيل وأسباب النَّقص الذي دخل عليهم قال: أول ما بدأ النقص في بني إسرائيل أن الرجل منهم كان إذا رأى من الرجل المنكر نهاه عنه وقال: يا هذا، اتَّقِ الله، ثم لا يمنعه ذلك بعد ذلك أن يكون أكيلَه وقعيدَه وشريبَه، فلما رأى الله ذلك منهم ضرب بقلوب بعضهم على بعضٍ، ثم لعنهم، فقال عليه الصلاة والسلام: والذي نفسي بيده، لتأمرنَّ بالمعروف، ولتنهونَّ عن المنكر، ولتأخذنَّ على يد السَّفيه -وفي روايةٍ: على يد الظالم- ثم لتأطُرنَّه على الحقِّ أطرًا -أو قال: تقصرونه على الحقِّ قصرًا- أو ليضربنَّ الله بقلوب بعضكم على بعضٍ، ثم يلعنكم كما لعنهم نسأل الله السلامة.\nفالواجب هو الأمر بالمعروف، والنهي عن المنكر على العموم، لكنه مراتب ثلاثة بيَّنها النبيُّ ﷺ، فقال ﷺ: مَن رأى منكم منكرًا فليُغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه، وذلك أضعف الإيمان.\nويجب على الدولة الإسلامية أن تُقيم طائفةً من الناس في كل بلدٍ لهذا الأمر العظيم، حتى تهتم به، وحتى تُعنى به؛ لقوله سبحانه: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [آل عمران:104]، فهذه الأمة وهذه الطائفة تكون عليها مسؤولية كبرى، ولكنها لا تضع المسؤولية على غيرها، ولا تُلقي المسؤولية على غيرها، بل يبقى الغيرُ عليه أيضًا مسؤولية إذا رأى المنكر لا يقول: هذا على غيري، إذا رآه ولم تُنكره الهيئة المعينة، أو لم يبلغها، وبلغه هو أنكره، أو رفع إليها لتُنكر، المقصود التعاون على إزالة المنكر، وعلى إقامة المعروف.","link":"https://binbaz.org.sa/fatwas/4852/ما-منزلة-الامر-بالمعروف-وعلى-من-يجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0486.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":429,"question":"إنه كما نعرف قد كثرت المُنكرات والمفاسد، وانتشر الخبث في البر والبحر، فهل على المسلم أن يُنكر كلَّ ما يرى من المفاسد أم ماذا عليه؟","title":"هل يجب على المؤمن إنكار كل منكر يراه؟","answer":"الجواب: الواجب على المؤمن أن يُنكر، وإنما جاءت المصيبة العظيمة من التَّساهل، وهذا يقول: هذا على غيري، وهذا يحقر نفسه ولا يرى أنه أهلًا لأن يُنكر، وهذا يخاف أن يُقابَل بما لا ينبغي، وهذه مصيبة عظيمة.\nالرسل عليهم الصلاة والسلام ما خافوا، بذلوا المستطاع، مع أنهم استهزأ بهم الناس، وسخروا بهم، وآذوهم، بل قُتِل بعضُهم، كما سمعت في القرآن: وَيَقْتُلُونَ النَّبِيِّينَ بِغَيْرِ حَقٍّ [آل عمران:21]، في آيات، فلم تمنعهم مخافة الناس من أداء الواجب.\nفالواجب على أهل العلم وعلى المؤمنين التأسِّي بهم، وألا يمنعهم من ذلك خوف الناس، أو قول بعض الناس: عليك بنفسك، اشتغل بنفسك، أو السخرية منه، أو غير هذا مما يفعله الجهلةُ والسُّفهاء، لا، لا يهمّك هذا، اتَّقِ الله، واعمل، فإن قُبِلَ منك فهذا المطلوب، وإن لم يُقبل منك برئت الذمةُ.\nوأنتم تعلمون ما جرى للنبي ﷺ في مكة، ولم يمنعه هذا من الدَّعوة إلى الله، وأُوذي، وهكذا المؤمنون في مكة، وهكذا في كل بلادٍ من حين بعث الله نبيه إلى يومنا هذا، بل من حين نزل آدم في الأرض، فالبلاء حاصلٌ، وقد قصَّ الله علينا ما جرى بين ابنيه: قابيل وهابيل، حتى قتل أحدُهما الآخر.\nفالأمر موجودٌ من عهد آدم إلى يومنا هذا، لا بدّ من إنكار المنكر، ولا بدّ من الصبر، يقول الله عن لقمان يقول لابنه: يَا بُنَيَّ أَقِمِ الصَّلَاةَ وَأْمُرْ بِالْمَعْرُوفِ وَانْهَ عَنِ الْمُنْكَرِ وَاصْبِرْ عَلَى مَا أَصَابَكَ إِنَّ ذَلِكَ مِنْ عَزْمِ الْأُمُورِ [لقمان:17]، والله يقول في كتابه العظيم: وَاصْبِرُوا إِنَّ اللَّهَ مَعَ الصَّابِرِينَ [الأنفال:46]، ويقول عمر : \"وجدنا خير عيشنا بالصبر\"، ويقول عليٌّ : \"الصبر من الإيمان بمنزلة الرأس من الجسد\"، ثم رفع صوته فقال: \"ألا لا إيمان لمن لا صبرَ له\" يعني: لا إيمان كامل، مَن لا يصبر؛ ضعف إيمانه، ووقع في أغلاطٍ.\nومن ذلك مسألة الأمر بالمعروف والنَّهي عن المنكر: في بيتك، في الطريق، حسب الطاقة، إن سمعت الغناء أنكرته، إن رأيت تهاونًا بالصلاة أنكرته، إن رأيت مَن يحلق لحيته أنكرتَ عليه بالحكمة، إن رأيت من يُسبل ثيابه أنكرت عليه، إن رأيتَ مَن يشرب الخمر أو يُدخن أنكرتَ عليه، إن رأيتَ مَن يعقّ والديه أو أحدهما أنكرتَ عليه، وهكذا كل معصيةٍ تعرفها أنها معصية، عندك الدليل، لا تأمر ولا تنهى إلا عن علمٍ، عن بصيرةٍ، فإذا تكلمت عن بصيرةٍ فأنت على خيرٍ، حتى ولو رُدَّ عليك، حتى ولو استُهزئ بك، حتى لو ضُربت أنت، هذا خيرٌ لك؛ أسوة بالأنبياء والأخيار.","link":"https://binbaz.org.sa/fatwas/4853/هل-يجب-على-المومن-انكار-كل-منكر-يراه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0487.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":430,"question":"ما مدى حدود واجب الفرد في مجال الحِسْبة؟ هل هي فرض عينٍ لكل فردٍ؟","title":"هل الحِسْبة فرض على كل مسلم؟","answer":"الجواب: كما تقدم: فرض، فرض، فرض على كلِّ واحدٍ إذا لم يوجد مَن يقوم مقامه، أما إذا وُجد مَن يقوم مقامه صارت في حقِّه سُنةً، لكن أنت في قريةٍ، أو في حيٍّ من الأحياء، أو في قبيلةٍ ما عندك أحدٌ يُنكر المنكر، أنت رأيت المنكر بنفسك، عليك أن تُنكر المنكر حسب الطاقة: إما باليد، أو باللسان، حسب الطاقة، أقل شيءٍ القلبُ، إذا خِفْتَ الضرب والقتل كفى القلب، وإلا فالواجب اليد كالحِسْبة، رجل الحِسْبة حسب التعليمات التي لديه، في الرجل مع أولاده حسب الطاقة، مع زوجته حسب الطاقة، أمير القرية في بلده، في قريته، في قبيلته شيخ القبيلة حسب طاقته، وهكذا كل بحسبه، أما أن تمر بالمنكر وتقول: هذا على الهيئة، الهيئة ما سوّت شيئًا، ولا تعلمه أيضًا، ما هو في جهتها، ولا في حيِّها، مثلًا: ما عندك مركز، أو عندك مركز وغفل، أنت رأيت المنكر: إما أن تُنكر المنكر، وإما أن ترفعه إلى مَن يُنكره إذا عجزت وتقول: جرى كذا، وجرى كذا من المنكرات الظَّاهرة.\nومن هذا ما يتعلق بالصَّلوات: كثير من الناس يعرفون جيرانهم لا يُصلون في مسجدهم، ولا يقولون لهم: لماذا؟ أو يزورونهم، يروح اثنان أو ثلاثة، لا تروح وحدك، وحدك قد يُستهان بك، لكن انظر مَن يتيسر معك من الإخوان: اثنين، ثلاثة، تزورونه، أو في الطريق تُوقفونه: يا فلان، يا عبدالله، اتَّقِ الله، ما نُشاهدك -ما نشوفك- في المسجد، أو نسمع صوت المزامير والأغاني في بيتك، وأنتم جيرانه تسمعونه، تقولون له بالكلام الطيب، وتنصحونه، ولعله يستفيد، فإن لم يستجب في المرة الأولى استجاب في الثانية أو في الثالثة أو في الرابعة، أو ترفعون أمره بعد الإعْذار إلى مَن يقوم عليه، وهكذا، فالغفلة هي المصيبة، والإعراض هو المصيبة.","link":"https://binbaz.org.sa/fatwas/4854/هل-الحسبة-فرض-على-كل-مسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0488.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":431,"question":"ما رأي سماحتكم في الخَيِّرين الذين يدعون الناسَ إلى السُّنة دون أن يُراعوا مقاصد السنة وأسلوب الحكمة وأصول الدعوة إليها، فيكون مردود دعوتهم عكسيًّا، وهم يريدون الخير إن شاء الله؟","title":"ما أهمية وكيفية تحري الحكمة في الدعوة؟","answer":"الجواب: الواجب تحرِّي الحقّ.\nس: حبَّذا لو ذكَّرتُموهم بكلمةٍ جامعةٍ في هذا، بارك الله فيكم.\nالشيخ: الواجب على الدَّاعي إلى الله والآمر والنَّاهي أن يتحرى الوسائل في الإقناع؛ لأن المقصود ما هو أنك قلت وأمرت، المقصود الفائدة، المقصود الحرص على أن يُقبل منك، وعلى أن تنتفع وتنفع. فمن ذلك: الأسلوب الحسن الطيب اللّين، وعدم الاكفهرار. ومن ذلك: أن تكون معك جماعةٌ، ما هو وحدك، قد يحقرونك وحدك، ولكن إن كان معك إخوانٌ لك كان أقربَ إلى النجاح، وأقرب إلى أن يُصغي ويحترم.\nومن ذلك: أن تُعنى بالمسائل الكبيرة قبل الصغيرة: مَن يترك الصلاة، تُعنى بأمر الصلاة قبل كل شيءٍ، مَن يسبّ الدين أو يستهزئ، تُعنى بهذا الأمر؛ لأنَّ هذه ردَّة، تُعنى بهذه الأمور، وتجتهد أنت وإخوانك معه، لعلَّ الله يهديه على يديك، مع الصبر.\nثم: العناية بألا تُنكر منكرًا يتولد عنه ما هو أنكر، يتحرى في الإنكار، ينظر إذا كان هذا الشخص الإنكار عليه يُولّد منكرًا أكبر، وأنت تعرف ذلك؛ فدعه حتى يتيسر الطريق الموصل إلى ألا يكون هذا الإنكار يُحدث منكرًا أكبر. فإن الإنكار تترتب عليه أمور: تارةً يتولد عنه إنكار المنكر وزواله، وهذا واجب. وتارةً يتولد عنه خفَّة المنكر وقلَّته، وهذا واجبٌ. وتارة يتولد عنه وجود منكر أكبر؛ فلا، قال الله تعالى: وَلَا تَسُبُّوا الَّذِينَ يَدْعُونَ مِنْ دُونِ اللَّهِ فَيَسُبُّوا اللَّهَ عَدْوًا بِغَيْرِ عِلْمٍ [الأنعام:108].\nذكر بعضُ أصحاب الشيخ تقي الدين ابن تيمية رحمه الله في وقت التتار في الشام أنهم مرُّوا على أناسٍ يشربون الخمر من التتار، فقال بعضُ أصحاب الشيخ: دعنا ننكر عليهم، قال: لا، لا تُنكر عليهم يقومون يقتلون الناس، هذا لو قاموا إلى الأسواق قتلوا الناسَ، خلّهم في بلائهم أسهل من القتل، أسهل من قتلهم الناس.\nفالمقصود: مراعاة الأمور التي يُخشى منها ما هو أكبر، فطالب العلم والمؤمن البصير يظهر له ما يقتضي الحال؛ إذا تأمَّل يظهر له هل هذا المنكر يزول أو يعقبه ما هو شرٌّ منه أو أخفَّ منه، ينظر ويتأمل، ولا يعجل.\nوقد بسط ابنُ القيم رحمه الله الكلامَ في هذا في مواضع من كتابه \"إعلام الموقعين\"، وهو كتابٌ جيدٌ جديرٌ بالعناية.\nثم مما ينبغي أن يُذكر أيضًا: كثرة الجماعات، وتنوع الجماعات، واختلاف الأساليب، واختلاف الأهداف، يجب على الجماعات الإسلامية كلها، سواء كانت تُسمَّى: سلفية، أو جمعية أنصار السنة، أو الإخوان المسلمين، أو التبليغ، أو غير ذلك من الأسماء، يجب أن يتعاونوا كلّهم في طريق الحقِّ، وأن يكون بينهم من المودة والمحبَّة ما يقتضي إنكار المنكر، والدعوة إلى الخير، وألا يكون بينهم وحشةٌ، بل يجب أن يكونوا متعاونين، ويكون الهدف واحدًا، وهو إقامة أمر الله في أرض الله، والقضاء على المنكرات، وأن يهتموا بالعقيدة قبل كل شيءٍ؛ لأن العقيدة هي رأس المال، وهي أساس السعادة، وأساس الملة، وليحذروا أن يكون بينهم تشاحن، أو أن يقصد أحدُهم القضاء على الآخر، لا، بل يجب أن يكون بينهم التعاون والتواصي بالحقِّ، وأن تكون الأهدافُ صالحةً، هي إقامة أمر الله في أرض الله؛ لتقليل المنكر، ولتكثير الخير، ولتبصير الناس.\nولا يضرّ تنوع الأسماء، المهم العمل، لو كانت الأسماء عشرة أسماء، أو مئة اسم، لكن إذا اتَّحدت الأهدافُ، واتَّحدت الجهود، وتضافرت الجهود على الخير، وصار الهدفُ واحدًا، وهو إقامة شرع الله، وإقامة أمر الله، والقضاء على المنكرات، فلا يضرّ تنوع الأسماء، لكن المصيبة أن تكون كل طائفةٍ ضد الأخرى، وتسبّها، أو تلومها، أو تُحب القضاء عليها، ما يصلح هذا، لا يجوز هذا، هذا منكرٌ.\nيجب على الجماعات الإسلامية بأي اسمٍ كانت: باسم أنصار السنة، باسم الإخوان المسلمين، باسم الجماعة الإسلامية، باسم جماعة التبليغ، باسم جماعة كذا، أي اسمٍ كان ما دام الهدف إسلاميًّا، والمقصود إسلاميًّا؛ يجب أن يتعاونوا، وأن يطرحوا الاختلاف والتَّنابز والإيذاء، بل كل واحدٍ يحرص على إصلاح أخيه، وإذا رأى عنده نقصًا أصلحه بالحكمة، والكلام الطيب، والدلالة على الخير، والتعاون على البر والتقوى، والتزاور، حتى تزول الوحشةُ، وحتى يتَّحد الهدف، وحتى يكون المقصود هو إقامة أمر الله في أرض الله.","link":"https://binbaz.org.sa/fatwas/4855/ما-اهمية-وكيفية-تحري-الحكمة-في-الدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0489.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":433,"question":"نرجو من سماحة الشيخ توضيح دور الحسبة في توجيه النشاط الاقتصادي المُعاصر؟","title":"ما دور الحسبة في توجيه النشاط الاقتصادي؟","answer":"الجواب: هذا مهمٌّ لا شك، وهذا لا يختص به العلماء، كل مَن له بصيرة من عاقلٍ يهتم بهذا الأمر؛ ليحرص على نشر الوعي فيما يتعلق بالاقتصاد، وأن يهتم كلُّ واحدٍ من أهل المال بأن يستخدم ماله فيما ينفع المسلمين: من زراعةٍ، وصناعةٍ، وغير هذا مما ينفع العباد ويُغنيهم عن الخارج، وألا يكون همُّه الفائدة من البنوك التي تمحقه وتمحق علمه ودينه وبركة ماله، بل يحرص على أن يستعمل هذا المال فيما ينفع المسلمين، فيوجد المصانع النافعة، والمزارع النافعة، وكل ما ينفع المسلمين ويُغنيهم عن الاستفادة من الخارج.\nوهذا لا شكَّ أنه يعمّ العلماء وأعيان البلاد وكل مَن له أدنى بصيرة، وعنده أدنى قدرةٍ على العمل أو المال، ينبغي أن يُنبه ويُشجع على الاستفادة من قوته في العمل، والاستفادة من ماله في العمل.\nبعض الناس عنده قوة ولكنه غافل ضعيف، ما يبالي، بل يفرح بأن يسأل الناس في المساجد وغير المساجد، ما عنده انتباه لما أعطاه الله من القوة على العمل.\nوبعض الناس عنده أموال راكدة مُعطَّلة، أو في الربا، هذا بلاءٌ عظيمٌ، ينبغي التنبيه والتَّعاون في هذا.","link":"https://binbaz.org.sa/fatwas/4857/ما-دور-الحسبة-في-توجيه-النشاط-الاقتصادي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0491.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":436,"question":"ما دور المرأة في الحِسْبة؟","title":"ما دور المرأة في الحِسْبة؟","answer":"الجواب: مثل الرجل، المرأة مثل الرجل، عليها النَّصيحة، أما سمعت الله يقول: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ [التوبة:71]؟ ثم قال بعد هذا: يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]..... كلهم، عليها واجبها مع النساء، ومع زوجها، ومع أولادها، ومع جيرانها، ومع كل أحدٍ ترى منه المنكر، حتى ولو رجلًا، إذا رأت في الطريق رجلًا معه منكر تُنكر عليه، أو في البيت: كأخي زوجها، أو عم زوجها، أو أبي زوجها، لكن بالكلام الطيب، بالأسلوب الحسن، بالعبارة التي يُرْجَى منها النَّفع، كالرجل، ولا تقول: أنا امرأةٌ، ما عليَّ، عليها واجبها.","link":"https://binbaz.org.sa/fatwas/4860/ما-دور-المراة-في-الحسبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0494.mp3","categories":["الدعوة والدعاة","قضايا المرأة"]},{"id":438,"question":"انتشر في الوقت الحاضر السُّفور والاختلاط، وبالذات في الأسواق والأماكن العامَّة، فما موقف المُحتسب من ذلك؟ وما الطريق المناسب للقضاء على هذه المُنكرات؟ وما دور المُتطوع في ذلك؟","title":"ما السبيل تجاه مظاهر المنكرات المنتشرة؟","answer":"الجواب: أسباب هذه المنكرات: السُّكوت وعدم التَّعاون، والبحث مع الدولة في هذا جارٍ، نسأل الله أن يُوفِّق الهيئة ويُعينها على أداء الواجب، ولكن السكوت من الناس والتَّغاضي والإعراض هو من أسباب البلاء، يعني: الهيئة ما تعمّ الناس، ما هي شمسٌ تعمّ الناس، أولًا: قلَّة، وثانيًا: الشر كثير، وثالثًا: قد يضعف بعض الأعضاء عن القيام بالواجب؛ لأسبابٍ كثيرةٍ.\nفالواجب التعاون، أنتم سمعتم الآيات: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ [التوبة:71]، مَن الذي يُخرجك من هذه الآية؟ أنت يا فلان، وأنت يا فلان، ما الذي أخرجك من هذه الآية؟ أنت مؤمن؟ حاسب نفسك، وهكذا أمُّك وأختك وزوجتك، مَن الذي أخرجها؟ ليش ترى منكرات في... من يجلسون معها، وفي بيتها، وفي الطريق، ولا تقول لهم شيئًا، ما الذي منعها؟ ولو ردّ عليك، لو قيل: ما عليك منه؟ ماذا يضرُّك؟ أو قيل: أنت يا الذي فيك وفيك ماذا يضرُّك؟ أما سبقك الرسل لهذا؟ أما سبقوك؟ أنت مسبوقٌ، لك أسوة.\nفالسكوت هو البلاء، والإعراض هو البلاء، تجده يرى المرأة الكاشفة ولا يقول شيئًا، يرى المدخن ولا يقول له شيئًا، يرى الحالق ولا يقول له شيئًا، وهكذا ساكت، جنبه أخوه في البيت ما يُصلي، أو جاره ما يُصلي ولا يقول له شيئًا، لماذا سكت؟ تقول: ما هو مطيعني؟ ولو ما أطاعوك قل، لكن لا تكن وحدك، إذا تيسر اذهب أنت واثنان وثلاثة من إخوانك، أحسن لكم، وأنفع لكم، وأقوى للكلمة.\nوماذا يضرُّ إذا ذهبتم جميعًا ونصحتم هذا وهذا؟ أو خرجتم من البيت، أو من المدرسة، أو من المعهد، أو من المسجد جماعة، تجولتُم في السوق للأمر بالمعروف والنَّهي عن المنكر، ما هو واحد، جماعة، حتى يُهابوا، يخرج جماعةٌ، يمتنع السَّفيه من الكلام والفاسق، لكن الواحد قد يُجترئ عليه، لكن إذا كانوا جماعةً –ثلاثة، أربعة- يخرجون لهذا الأمر حسبةً لله من المسجد، من البيت، يأتون جميعًا للسوق الفلاني، والسوق الفلاني، والحارة الفلانية؛ ليُنكروا المنكر، ويدعوا إلى الله، ما المانع؟ الدولة منعت؟ ما تمنع الدولة من هذا، لكن بالحكمة والكلام الطيب والأسلوب الحسن، ما هو بالمضاربة، لا مع النساء، ولا مع الرجال، ولا مع الكافر، حتى الكافر ليس له أن يُظهر شعاره في بلادنا، حتى الكافر يعلم بالإشارة أو بالكلام حتى يفهم، أو إذا تيسر معكم مَن يُجيد اللغة الإنجليزية أو غيرها، يكون معكم في التَّجول حول الإنجليزيين، حول الباكستانيين، حول الهنود، يعني: حول أصحاب اللغات الأخرى.\nالمقصود أنا أنصح دائمًا ألا يكون واحدًا، ما يمشي واحدٌ، يكونوا جماعة، هذا أشجع للقيام بأمر الله، وأهيب عند العاصي، وأقرب إلى النجاح، هذا الذي أنصح به الجميع، لكن لو كان واحدًا يُنكر حسب الطاقة، ولو واحد، لا يقل: أنا واحد، لكن إذا تيسر يكون معه ثانٍ أو ثالث أو رابع أو أكثر يكون هذا أحسن، اثنان ثلاثة أنفع، أربعة أنفع، هكذا في الزيارة لإخوانهم، ينصحونهم، ويُوجهونهم.","link":"https://binbaz.org.sa/fatwas/4862/ما-السبيل-تجاه-مظاهر-المنكرات-المنتشرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0496.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":738,"question":"يقول السَّائل: أنا شابٌّ مسلمٌ والحمد لله، ولكن لي أبٌ لا يُصلي، هل أمكث معه في المنزل أم أهجره وأتركه؟ أفيدوني مأجورين، مع العلم أني طالبٌ أدرس في الثانوية، ولا أملك مالًا ولا دينارًا.","title":"حكم هجر منزل الأب الذي لا يصلي؟","answer":"الجواب: المشروع لك أن تبقى مع والدك، وأن تنصحه كثيرًا، وتعتني به كثيرًا، وتُحسن إليه، ولعلَّ الله يهديه بأسبابك، قال الله جلَّ وعلا في كتابه العظيم: وَوَصَّيْنَا الْإِنْسَانَ بِوَالِدَيْهِ حَمَلَتْهُ أُمُّهُ وَهْنًا عَلَى وَهْنٍ وَفِصَالُهُ فِي عَامَيْنِ أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ ۝ وَإِنْ جَاهَدَاكَ عَلَى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا وَاتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَيَّ [لقمان:14- 15]، فأمر بأن يصاحب الوالدين الكافرين معروفًا، وهما كافران.\nفعليك أن تصحب والدك بالمعروف، وأن تُحسن إليه، وتنصحه كثيرًا، وتُعينه في الخير، ولا تُعينه في الشر، ولا تُقاطعه، ولا تخرج من عنده، بل عليك أن تنصحه كثيرًا وتُعينه في الخير، وتصبر على الأذى حتى يُفرّج الله ؛ لأنَّ الله قال: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا، ولم يزل الصحابةُ  في علاج بعض الصَّحابة الذين لهم آباء وأمهات تأخَّر إسلامهم، لم يزالوا في علاجٍ معه حتى هداهم الله: كأبي هريرة مع أمه، وسعد بن أبي وقاص مع أمه، حتى هداهما الله على يدي ابنيهما.","link":"https://binbaz.org.sa/fatwas/20614/حكم-هجر-منزل-الاب-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0548لي أب لا يصلي هل أمكث معه في المنزل أم أهجره فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":768,"question":"هل إنكار المُنكر مُقتصرٌ على المعنيين من أهل الحِسبة، أم هو عامٌّ لجميع المسلمين؟ وما حكم مَن قال لي وأنا أُنكر عليه: لا تأمر بالمعروف، ولا تنهَ عن المنكر حتى يأذن لك السلطانُ؟","title":"هل إنكار المنكر يقتصر على رجال الحِسبة؟","answer":"الجواب: الشيخ: ليس خاصًّا بالسلطان، ولا خاصًّا بالمعينين، بل هو عامٌّ كما تقدم في الكلمة، الله يقول: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]، فهو فرضٌ على كل مؤمنٍ، وعلى كل مؤمنةٍ حسب الطاقة، لكنه في حقِّ ولاة الأمور، وفي حقِّ مَن عيَّنهم ولاة الأمور، في حقِّهم يكون أشدَّ وجوبًا، وأشد فرضًا، ولكن مثلما تقدَّم لا بدّ من كون الآمر والنَّاهي ذا علمٍ، وذا بصيرةٍ، حليمًا فيما يأمر به، وفيما ينهى عنه، رفيقًا، لا يُسبب مشاكل وفتنًا، بل تكون عنده الرزانة والصَّبر والحلم والرِّفق.\nس: الأخ يسأل عن السلام على مَن أفشى المُنكرات في الأسواق، وعن إنكار كل منكرٍ يُشاهده في السوق، هل يجب عليه الإنكار أم لا؟\nالشيخ: نعم، يُنكر على حسب طاقته، إذا كان يستطيع يُنكر باللسان، وإن كان يستطيع باليد -كأهل الحسبة- يُنكر باليد، ولو كثرت المنكرات لا ييأس، يكون عنده ظنٌّ حسنٌ، وعنده رجاءٌ بالله، ولا يملّ، بل يرجو ما عند الله من المثوبة، وإذا كان معه بعضُ إخوانه يكون أحسن: اثنان، ثلاثة، أربعة، يتعاونون في نصيحة الناس، وإنكار المنكر، والأمر بالمعروف بالرفق والكلام الطيب، يكون هذا أجدى وأنفع من الواحد.","link":"https://binbaz.org.sa/fatwas/20698/هل-انكار-المنكر-يقتصر-على-رجال-الحسبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0596هل أنكار المنكر مقتصر على المعنيين من أهل الحسبة أم هو عام لجميع المسلمين؟ ابن باز.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":775,"question":"يُلاحظ تحمس كثيرٍ من الشباب لإنكار المنكر، ولكنَّهم لا يُحسنون الإنكار، فما نصيحتكم وتوجيهاتكم لهؤلاء؟ وما الطريقة المُثْلَى في إنكار المُنكر؟","title":"ما الطريقة المُثْلى في إنكار المنكر؟","answer":"الجواب: نصيحتي لهم أن يتثبَّتوا في الأمر، وأن يتعلموا أولًا؛ حتى يتيقَّنوا أنَّ هذا معروف، وهذا منكر، حتى يعلموه بالدليل، ثم يكون الإنكار بالرفق والكلام الطيب والأسلوب الحسن، حتى يُقبل منهم، وحتى لا يُفسدوا أكثر مما يُصلحون، فإنه إذا أنكر بالأسلوب الشَّديد والعنيف لم يُقبل منه في الغالب، وأفضى إلى النزاع بينه وبين صاحبه، ثم قد تطول المسألة وترتفع إلى ولاة الأمور، فيُمنع لسوء أدبه، ولسوء تصرفه.\nفالواجب على الدَّاعي إلى الله والآمر بالمعروف والنَّاهي عن المنكر أن يسلك الطريق السوي، بالأسلوب الحسن، بالرفق، بالرحمة، بالعطف، يقول الله : فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لَانْفَضُّوا مِنْ حَوْلِكَ فَاعْفُ عَنْهُمْ وَاسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِي الْأَمْرِ [آل عمران:159]، يقول: هداك الله يا أخي، هداك الله، ما يجوز هذا الكلام، ما يجوز هذا الفعل، يا أخي، اتَّقِ الله، دع هذا.\nوقد قال الله لموسى وهارون عليهما الصلاة والسلام لما بعثهما إلى فرعون اللَّعين الطَّاغية الذي يقول: أنا ربكم الأعلى، ماذا قال لهما؟ قال لهما ما تقرؤونه في كتاب الله: فَقُولَا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى [طه:44].\nهكذا الأسلوب الجيد، مع أن يكون عاملًا بما يقول، يُعرف عنه العلم والعمل، والسيرة الحميدة، والأخلاق الفاضلة، ومع ذلك يرفق في الكلام في الأمر وفي النَّهي جميعًا، حتى تكون آثاره صالحةً، وعاقبة ما يقوم به حميدةً، وحتى يتأسَّى به الآخرون في عمله الطيب، وحتى ينفع الله به الأمَّة، ويكون بالكلام: بالآيات والأحاديث.","link":"https://binbaz.org.sa/fatwas/20691/ما-الطريقة-المثلى-في-انكار-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0588ما هي الطريقة المثلى في إنكار المنكر ؟ ابن باز فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":776,"question":"ما كيفية النَّهي عن المنكر بالقلب؟ هل هو ببُغضه بقلبه ويبقى جالسًا مع  أهل المعصية؟ أو كيف يكون الإنكار بالقلب؟","title":"كيف يكون إنكار المنكر بالقلب؟","answer":"الجواب: مثلما تقدم، يُنكر بقلبه ولا يجلس معهم، إذا جلس معهم كفعل بني إسرائيل ما صار منكرًا، لكن إذا أنكر عليهم لا يُجالسهم في منكرهم، ويكون معهم على منكرهم، بل يُنكر عليهم ذلك، ويبغض المنكر، ويُفارق أهله، ولا يكون جليسًا لهم إلا إذا جاءهم للنُّصح والتَّوجيه والإرشاد والتَّعليم، أو لمصلحةٍ عامَّةٍ للمسلمين، أو نحو ذلك، لا يتّخذهم أصحابًا وأصدقاء وهم على المنكر، على المنكر الظاهر يعني.","link":"https://binbaz.org.sa/fatwas/20689/كيف-يكون-انكار-المنكر-بالقلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0587ما كيفية النهي عن المنكر بالقلب أو كيف يكون الأنكار بالقلب ؟ ابن باز فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":777,"question":"فضيلة الشيخ، سمعتُ من بعض العلماء: أنَّ بعض العلماء عدَّ الأمر بالمعروف والنَّهي عن المنكر ركنًا من أركان الإسلام، فهل هذا صحيحٌ؟","title":"هل الأمر بالمعروف من أركان الإسلام؟","answer":"الجواب: نعم، قاله بعضُ أهل العلم، لكن لم يرد فيه نصٌّ واضحٌ في هذا، وإنما هو من أعظم فرائض الإسلام، فالأركان خمسة معروفة بيَّنها النبيُّ ﷺ، يقول ﷺ: بُني الإسلام على خمسٍ يعني: على خمس دعائم شهادة أن لا إله إلا الله، وأنَّ محمدًا رسول الله، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت، هكذا قال النبيُّ ﷺ، هذه هي الدَّعائم التي نصَّ عليها الرسولُ ﷺ.\nولكنه في الحقيقة دعامة من الدعائم، وفرضٌ من الفروض، لكن لا يُقال: إنه هو السادس؛ لعدم الدليل على ذلك، لكنه دعامة من الدعائم، وفرضٌ من الفروض العظيمة، كما أنَّ الجهاد في سبيل الله دعامةٌ من الدعائم، وهكذا ترك المحارم التي حرَّمها الله على عباده دعامة من الدعائم لا بدّ منها، وفرض من الفروض لا بدّ منها.\nفكل ما أوجب الله علينا؛ علينا أن نستقيم عليه، وكلّ ما حرَّم الله علينا؛ علينا أن نستقيم على تركه، هذا كله من الفرائض، وإذا سميت دعامةً أو ركنًا من أركان الإسلام بمعنى أنه فرضٌ من فروض الإسلام فلا مشاحةَ في الاصطلاح.","link":"https://binbaz.org.sa/fatwas/20686/هل-الامر-بالمعروف-من-اركان-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0586عدَّ بعض العلماء أن الأمر بالمعروف والنهي عن المنكر من أركان الإسلام فهل هذا صحيح.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":796,"question":"كما نعلم في وقتنا الحاضر أنَّ هنالك جهةً مُختصةً مُكلَّفةً من ولي الأمر بالقيام بهذا الأمر –يعني: واجب الأمر بالمعروف والنهي عن المنكر- فهل يسقط بذلك هذا الواجب عن البقية وجزاكم الله خيرًا؟","title":"حكم الأمر بالمعروف لغير رجال الحِسبة","answer":"الجواب: تقدَّم في البحث أنَّ الأمر بالمعروف والنهي عن المنكر فرضٌ على الكفاية، إذا قام به مَن يكفي سقط عن الباقين، وصار في حقِّ الباقين سنةً، فإذا لم يقم به مَن أُسند إليه أثم الجميع؛ لأنه واجب عليهم، فرض كفايةٍ مُوجَّه إلى الجميع، وفرض على الجميع. فإذا كنت في قريةٍ لم ينكر المنكر غيرك، فأنت الواجب عليك أن تُنكره؛ لأن عندك العلم، أو في قبيلةٍ، وإذا كان معك غيرُك فمَن أنكره منكم حصل به الواجب، وإن تركتُموه أثمتم جميعًا، وكل واحدٍ منكم عليه أن يُبادر بأداء الواجب، فمَن أدَّاه منكم سقط عن إخوانه الذين معه، إذا امتثل المُنْكَر عليه وحصل المقصود.","link":"https://binbaz.org.sa/fatwas/20802/حكم-الامر-بالمعروف-لغير-رجال-الحسبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0630حكم الأمر بالمعروف والنهي عن المنكر لغير رجال الحسبة؟ ابن باز فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":797,"question":"ما الشروط الواجب توفرها في الشخص الآمر بالمعروف والناهي عن المنكر؟","title":"ما شروط الآمر بالمعروف الناهي عن المنكر؟","answer":"الجواب: أهمها العلم، أهمها أن يكون عالمًا بما يأمر به، عالمًا بما ينهى عنه. ومن جملة ذلك كما ذكر أهلُ العلم: الحلم والرفق، يكون حليمًا فيما يأمر به وينهاه، رفيقًا في ذلك، لا يستفزّه الغضب، ولا تأخذه العجلة، بل يرفق، ولا يعجل، ولا يغضب، بل يحلم عند المناقشة والبحث والإنكار. فأهم الأمور: العلم، أن يكون على بصيرةٍ فيما يأمر به وينهى عنه، مع الحلم والرفق، وعدم العجلة في الأمور والشدة والغِلْظَة.","link":"https://binbaz.org.sa/fatwas/20800/ما-شروط-الامر-بالمعروف-الناهي-عن-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0629ما هي الشروط الواجب توفرها في الشخص الآمر بالمعروف والناهي عن المنكر؟ ابن باز.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":798,"question":"إنَّ كثيرًا من الشباب يدعونني أن أشترك معهم في الدعوة إلى الله، وهم من جماعةٍ تُسمَّى \"جماعة التبليغ\"، فما رأيكم في ذلك؟ هل أشترك معهم أم لا؟","title":"ما المنهج الصحيح تجاه جماعات الدعوة؟","answer":"الجواب: الجماعة كثيرون، جماعات متنوعة، فلا مانع من الاشتراك معهم في الخير والدعوة إليه، لا في كل شيءٍ، مَن دعاك إلى الخير تشترك في الخير: جماعة التبليغ، أو أنصار السنة، أو جماعة الإخوان المسلمين، أو جماعة المسلمين في قُطْرٍ آخر، أو جماعة الدَّعوة في قُطْرٍ آخر، أو ما أشبه ذلك من الأسماء، أو المركز الإسلامي، أو الاتحاد الإسلامي، أو اتحاد المسلمين، بأي اسمٍ سمّوه، إذا دُعيتَ إلى ذلك فشارك في الخير، ولا تُشارك في الشر، أجبهم إلى ما طلبوا فيما يتعلق بالشرع المطهر، وأنكر عليهم ما خالفوا من الشرع المطهر، واجعل نفسك واسطةَ خيرٍ، وداعيةَ خيرٍ، تحثُّهم على الالتزام بأمر الله، وتُحذرهم من التَّفرق والاختلاف، فلا تكن معهم مطلقًا، ولا عليهم مطلقًا، بل معهم في الخير، وعليهم فيما أخطأوا فيه حتى يهتدوا ويلتزموا.","link":"https://binbaz.org.sa/fatwas/20798/ما-المنهج-الصحيح-تجاه-جماعات-الدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0627المنهج الصحيح في الانضمام إلى الجماعات الإسلامية.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":805,"question":"فضيلة الشيخ، حفظكم الله، لقد قلتُم أنَّ الأمر بالمعروف والنَّهي عن المنكر فرضُ كفايةٍ، ويرى آخرون أن الأمر بالمعروف والنَّهي عن المنكر واجبٌ على كل مسلمٍ ومسلمةٍ بقدر ما أعطاه الله من العلم والاستطاعة، فكيف نُوفِّق بين الرأيين؟","title":"حكم الأمر بالمعروف والنهي عن المنكر","answer":"الجواب: ما في خلاف بين أهل العلم أنه فرض كفايةٍ، ولكنه واجبٌ على المسلم، إذا لم يقم غيره بهذا الواجب تعيَّن عليه، فإذا كنتَ مثلًا في حيٍّ من الأحياء، أو مجتمع من الاجتماعات، فرأيتُ منكرًا: رأيت إنسانًا رفع كأس الخمر ليشرب، فسبقك واحدٌ وأنكره، فأراق صاحبُ الكأس خمره وامتثل وقال: جزاك الله خيرًا، هل بقي لإنكارك محلٌّ أنت؟ ما عاد بقي له محله، زال المنكر، أو تمشي أنت وصاحبٌ لك، فرأى إنسانًا واقفًا بعد الأذان، فسبقك وقال: يا أخي، اتَّقِ الله، الصلاة، الصلاة، فمشى وذهب إلى المسجد، فماذا بقي لإنكارك أنت؟ هل حصل المطلوب أو ما حصل المطلوب؟\nفمَن قال: إنه فرض عينٍ، مراده فرض عينٍ عند عدم وجود مَن أنكر، وأما إذا أنكر زال المحذور، فهو فرض كفايةٍ، معناه: إذا قام به مَن يكفي سقط عن الباقين، فإذا ما قام به وجب عليك: أنتم ثلاثة مررتُم على منكرٍ، ما أنكر الاثنان اللَّذان تظنّهما أفضل منك مثلًا أو أقوى منك؛ تعيَّن عليك، فإذا أنكر أحدُهما لم يتعين على الباقي إذا زال المحذور وحصل المقصود، أما إذا ما زال المحذور يُنكر الثاني والثالث والرابع والخامس حتى يزول المحذور.\nفمَن قال: إنه فرضٌ على كل مسلمٍ، يعني: فرض على كل مسلمٍ عند عدم وجود مَن قام بالواجب هذا، هذا مُراده، فلا معارضة.","link":"https://binbaz.org.sa/fatwas/20791/حكم-الامر-بالمعروف-والنهي-عن-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0621حكم الأمر بالمعروف والنهي عن المنكر؟ ابن باز فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":808,"question":"\"قراءة الفاتحة وتلاوة القرآن في المقابر\" مسألةٌ اختلف فيها الناس، ومنهم مَن ينسب صحَّة جوازها إلى بعض الأئمة: كشيخ الإسلام محمد بن عبدالوهاب في جواز ذلك، فما القول الصحيح في هذه المسألة؟","title":"حكم قراءة الفاتحة وتلاوة القرآن في المقابر","answer":"الجواب: القبور ما هي محل قراءة قرآنٍ، وليست محلًّا للصلاة، ولكنها محلّ للسلام والعبرة والذكرى، فيُسلم عليهم للتذكر والاعتبار والدعاء لهم بالرحمة والمغفرة، ولا يُصلَّى عندهم، ولا يقرأ عندهم، وما جاء في هذا من الأخبار والأحاديث كله لا صحَّة له، وما ورد في كتاب \"تمني الموت\" المنسوب للشيخ محمد بن عبدالوهاب من ذلك هو أمرٌ مشكوكٌ فيه، فالكتاب هذا غير معروفٍ عن الشيخ، وليس من مُؤلَّفاته فيما نعلم، وإنما غلط فيه مَن ظنَّ أنه من مؤلفاته، وليس معروفًا بين علماء الدعوة، ولا بين أحفاد الشيخ، ولم نسمع عنه إلا في هذه الأيام القليلة، فهو مشكوكٌ في نسبته إليه، والذي يظهر ونعلم من سيرته أنه ليس صحيحًا نسبته إليه، وليس من مُؤلفاته، وإنما غلط مَن ظنَّ أنه من مؤلفاته: إما لأنه ظنَّ أنَّ الخطَّ خطه، أو لأسبابٍ أخرى.\nثم على فرض أنه من مؤلفاته: فهو وغيره يُؤخذ من قوله ويُترك، ما وافق الحقَّ أُخذ، وما خالفه تُرك، سواء كان الشيخ محمد بن عبدالوهاب، أو شيخ الإسلام ابن تيمية، أو ابن القيم، أو غيرهم، ليس واحدٌ منهم معصومًا، فإذا غلط واحدٌ منهم في مسألةٍ وجب الأخذ بالدليل، وترك ما غلط فيه، مثل غيره من العلماء، ليس هذا خاصًّا بأحدٍ دون أحد، فالأئمة الأربعة والصحابة والتابعون وغيرهم إنما يُؤخذ من أقوالهم ما وافق الحقَّ، وما خالف الحقَّ من أقوالهم لم يُؤخذ به، وإن كان القائل عظيمًا: كأفراد الصحابة، وأفراد الأئمة الأربعة، وأشباه ذلك، مثلما قال مالكٌ رحمه الله: \"ما منا إلا رادٌّ ومردودٌ عليه، إلا صاحب هذا القبر\" يعني: الرسول ﷺ، ومثلما قال الشافعيُّ رحمه الله: \"أجمع الناسُ على أنَّ مَن استبانت له سنةُ رسول الله ﷺ لم يَجُزْ له أن يدعها لقول أحدٍ من الناس\"، وهكذا قال أبو حنيفة رحمه الله: \"إذا جاء الحديثُ عن رسول الله ﷺ فعلى العين والرأس، وإذا جاء عن الصَّحابة فعلى العين والرأس، وإذا جاء عن التابعين فهم رجالٌ ونحن رجالٌ\" يعني: كلٌّ يلتمس الحقَّ بدليله، وهكذا يقول أحمد رحمه الله لما سُئل: هل نأخذ بقولك؟ قال: \"لا تُقلدني، ولا تُقلد مالكًا، ولا الشافعي، وخذ من حيث أخذنا\"، وقال: \"عجبتُ لقومٍ عرفوا الإسنادَ وصحَّته –يعني: إلى النبي ﷺ- يذهبون إلى رأي سفيان -يعني: الثوري- والله يقول: فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيم [النور:63]\"، فإذا كان مَن أخذ بقول الثوري الإمام المشهور إذا كان مخالفًا للنص يُخشى عليه الفتنة؛ فكيف بمَن دون الثوري بمراتب؟!\nفالمقصود أنَّ أقوال أهل العلم يُحتجُّ لها، ولا يُحتجُّ بها على السنة وعلى الشرع، بل تُعرض أقوال العلماء على الكتاب والسنة، فما وافق الكتابَ والسنةَ فهو الحقُّ، وما خالفها رُدَّ على قائله، وإن كان كبيرًا، وإن كان عظيمًا؛ لأن قول الله أعظم، وسنة رسول الله أعظم.\nوقد صحَّ عن رسول الله عليه الصلاة والسلام أنه قال: اجعلوا من صلاتكم في بيوتكم، ولا تتَّخذوها قبورًا، فإن الشيطان يفرُّ من البيت الذي تُقرأ فيه سورة البقرة، فبين عليه الصلاة والسلام أن القبور ما هي محل صلاةٍ، ولا محل قراءةٍ، وإنما الصلاة في البيوت، والقراءة في البيوت، كما تكون في المساجد: اجعلوا من صلاتكم في بيوتكم، ولا تتَّخذوها قبورًا يعني: لا تجعلوها بمثابة القبور لا يُصلَّى فيها، ولا يُقرأ فيها.\nس: لو مثلًا قال لك: إن قراءة القرآن في المقابر دعاء، فما واجب الردّ عليه؟\nالشيخ: ليس دعاءً، الدعاء تقول: اللهم اغفر لهم، وارحمهم، ما هو تقرأ القرآن.\nس: يعني: ردّ عليك وقال لك: إنَّ الفاتحة دعاء؟\nالشيخ: لا، ما هي بدعاء، الدعاء: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ [الفاتحة:6]، تطلب ربك للحيِّين، أما الميتين فماتوا، ما عاد في هدايةٍ، ليس لهم إلا ما قدَّموا.","link":"https://binbaz.org.sa/fatwas/20837/حكم-قراءة-الفاتحة-وتلاوة-القران-في-المقابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0634حكم قراءة الفاتحة وتلاوة القرآن في المقابر؟ابن باز فتاوى المحاضرات.mp3","categories":["أحكام المقابر","الدعوة والدعاة"]},{"id":815,"question":"ما توقعاتكم للدعوة مُستقبلًا على ضوء الواقع الذي نعيشه اليوم، وبالنظر إلى الشُّرور التي تُكاد للمُسلمين يومًا بعد يوم؟","title":"ما التوقعات المرجوّة لمستقبل دعوة الإسلام؟","answer":"الجواب: كل مؤمنٍ عرف الواقع، وتبصَّر في الواقع، وعرف الناس اليوم، يتوقع كلَّ خيرٍ في المستقبل، ويحسن ظنّه بالله ، ويرجو أن الإسلام ينمو في الشعوب كلها، وأن هذا النشاط الشَّبابي وغير الشبابي يُرجى فيه الخير العظيم، فهناك بحمد الله يقظةٌ في كل مكانٍ: في البلاد العربية، وفي غيرها، حتى في بلاد الغرب: في أمريكا وأوروبا، وحتى في بلاد الروس، حتى في بلاد الصين.\nفالحركة بحمد الله مُنتشرة، واليقظة عظيمة، لكنها مختلفة بالنسبة إلى أقطار الدنيا، فهي تُبَشِّر بالخير، وتدل على خيرٍ، ويظهر منها والحمد لله أن المستقبل للإسلام وأهله، وأن الناس بخيرٍ، مع كثرة أعداء الإسلام وما يكيدون له من المكائد، لكن هذه اليقظة وهذه الحركة الجديدة تُبَشِّر بخيرٍ عظيمٍ، ويُرجى لها نماء كبير، وعاقبة حميدة، ولكنها في حاجةٍ شديدةٍ إلى التَّكاتف والتَّعاون، والقيادة الصالحة، والصبر والمصابرة، وعدم اليأس، وعدم التَّسرع في الأمور، فلا بدّ من صبرٍ ومُصابرةٍ، ولا بدّ من عنايةٍ بالعلم، ومُذاكرةٍ في العلم، ولا بدّ من أناةٍ وعدم عجلةٍ، وتعاون بين الحركات: من جمعيات ومراكز إسلامية ودعاة، لا بدّ من التعاون: وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا [آل عمران:103].\nوالرسول عليه الصلاة والسلام قال: بدأ الإسلام غريبًا، وسيعود غريبًا كما بدأ، فطُوبى للغُرباء؛ الذين يصلحون إذا فسد الناس، وفي اللفظ الآخر: يُصلحون ما أفسد الناسُ، فهؤلاء الغُرباء اليوم يُرجى لهم الخير العظيم في الصلاح والإصلاح.\nوالواجب على كل مسلم –ولا سيما أهل العلم- في كل مكانٍ أن يعضدوا هذه الحركة، وأن يُعينوها  ويدعموها بكل ما يستطيعون: من كلامٍ، ومالٍ، وكتبٍ صالحةٍ، وغير هذا من وجوه الدعم، حتى تنشط وتقوى، مع ترشيد الجاهل، وتعليم مَن حاد عن الصواب، وتنبيه مَن أفرط أو فرَّط، لا بدّ من التعاون؛ لأن بعض الناس قد يحمله حبُّه للخير ونشاطه فيه إلى الغلو والإفراط والزيادة، وبعضٌ آخر قد يحمله ضعفُ إيمانه وقلَّةُ علمه على الجفاء والتَّساهل.\nفيجب على أهل العلم والإيمان التوسط في الأمور، والأخذ بأيدي المسلمين -ولا سيما شبابهم- إلى الطريق الوسط: وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ وَلَا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَنْ سَبِيلِهِ [الأنعام:153]، وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا الآية [البقرة:143]، فلا مع الغُلاة، ولا مع الجفاة، ولكن مع أهل الاعتدال والاستقامة.","link":"https://binbaz.org.sa/fatwas/20846/ما-التوقعات-المرجوة-لمستقبل-دعوة-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0642ما هي توقعاتكم في الدعوة إلى الله مستقبلاً ؟ ابن باز فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":816,"question":"سماحة الشيخ، السلام عليكم ورحمة الله وبركاته، وبعد: نسمع في هذه الأيام أن هناك شبابًا يفهم الإسلام من بعض جوانبه، وكل طائفةٍ تُسمِّي نفسها باسمٍ، أرجو كلمةً توجيهيةً لهؤلاء الشَّباب؟","title":"حكم من يأخذ بعض الإسلام ويترك بعضه","answer":"الجواب: الواجب على الشباب والشِّيب وعلى كل مؤمنٍ ومؤمنةٍ أن يأخذ الإسلام كله، وأن يطلبه كله، لا بعضه، يتفقَّه في الدين ويتبصَّر فيما قاله الله ورسوله، وبما شرعه الله ورسوله، ويستقيم على ذلك، ولا يتمسك ببعض دون بعض، بل يدرس الإسلام كله، ويعتني به كله؛ حتى يفهم ما أمر الله به، ويعمل به، وحتى يعرف ما نهى الله عنه ويجتنبه، وأن يكون الجميعُ متعاونين؛ جميع الجمعيات وجميع الشباب في كل مكانٍ يجب أن يكونوا مُتعاونين على البرِّ والتقوى، لا يؤذي بعضُهم بعضًا، ولا يذمُّ بعضُها بعضًا، ولا يحقر بعضُهم بعضًا، ولا يحسد بعضُهم بعضًا، فيتعاونون: ماذا قال الله؟ ماذا قال رسوله؟ ما معنى الآية؟ ما معنى الحديث؟ ماذا حكم الله في كذا وكذا؟ ما الدليل؟\nثم يأخذون كلام أهل العلم، يستعينون بكلام أهل العلم من الأئمة الكبار في كُتبهم، لا يدَّخرون وسعًا في ذلك، فإنَّ أهل العلم كتبوا وبيَّنوا رحمة الله عليهم، فيستعينون بكتبهم الكبيرة والصَّغيرة، مثل: كتب الموفق ابن قُدامة، والنووي، وشيخ الإسلام ابن تيمية، وابن القيم، وابن كثير، وغيرهم من أهل العلم، يُستعان بالكتب التي وجدت في المذاهب، ولا سيما الكتب التي تعتني بالأدلة: قال الله، وقال رسوله، فيستفيدون منها، وهكذا كتب الحديث وشروحها، هكذا طالب العلم. لكن الصغير يبدأ بالكتب المختصرة، ولا يُدخل نفسَه فيما لا يُحسنه، يبدأ بالكتب المختصرة، ويعتني بحفظ القرآن، ويحفظ كتاب \"التوحيد\"، \"العقيدة الواسطية\"، \"ثلاثة الأصول\"، \"كشف الشبهات\"، \"أصول الإيمان\"، \"فضل الإسلام\"، وأشباه ذلك من الكتب المختصرة؛ حتى يستفيد شيئًا بعد شيءٍ، ولا يدخل مع الناس فيما لا يعلم، وفيما يصعب عليه، بل يعرف قدر نفسه ويقف عند حدِّه.\nولكن يجب على الفاهمين أن يكونوا شيئًا واحدًا، وأن يتعاونوا على البر والتقوى، وألا يتفرَّقوا، وأن يُعين بعضُهم بعضًا على فهم النص، وعلى ما دلَّ عليه، وألا يأنف إذا أرشده أخوه، أو دلَّه أخوه على فائدةٍ، فليقل: جزاك الله خيرًا، فالعلماء الكبار تخفى عليهم المسائل الكثيرة، فإذا أرشدهم أخوهم فرحوا بذلك، كالصحابة، فهم أعلم الناس بعد الأنبياء، وكان بعضُهم يُرشِد بعضًا، ويدل بعضُهم على بعضٍ، والآخر يقول: سمعتُ رسول الله، ويقول: سمعتُ فلانًا عن رسول الله، فيفرحوا بذلك فرحًا عظيمًا، ثم التابعون بعدهم: كابن المسيب، وطاووس، وأبي سلمة ابن عبدالرحمن، والشعبي، وغيرهم، يتعاونون، وهكذا مَن بعدهم: كمالك، وأبي حنيفة، والشافعي، كلٌّ يحتاج إلى علم أخيه، والتعاون مع أخيه.\nفالذي يأنف أن يُرشَد أو ينتقد؛ قد خالف أهل السنة، كل واحدٍ منا له أغلاط، ويفهم أشياء، ويغلط في أشياء، فليفرح بمَن يُعينه ويدله على الخير ويُرشده إلى مسألةٍ خفيت عليه، أو دليلٍ خفي عليه.\nثم ليُجعل التعاون هو الميزان والدَّيدن بين الجميع، لا أن يذهب كل واحدٍ على حدةٍ ويُنافس الآخر ويُعاديه، لا، هذه طريقة أهل البدع من الجهمية والمعتزلة والرافضة وغيرهم، أما أهل السنة لا، أهل السنة يتعاونون فيما بينهم، ويُرشد بعضُهم بعضًا، ويُعين بعضُهم بعضًا، ويكونون جمعيةً واحدةً، ويكون هدفُهم واحدًا، وهو اتِّباع الحقِّ.","link":"https://binbaz.org.sa/fatwas/20854/حكم-من-ياخذ-بعض-الاسلام-ويترك-بعضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0650كلمة توجيهية لمن يأخذ بعض الإسلام ويترك بعضه؟ ابن باز فتاوى المحاضرات.mp3","categories":["العالم والمتعلم","الدعوة والدعاة"]},{"id":838,"question":"ما حكم إزالة منكرٍ يترتب عليه قطع رحم؟","title":"ما حكم إزالة منكرٍ يترتب عليه قطع رحم؟","answer":"الجواب: ما يلزم من إنكار المنكر قطيعة الرحم، إذا كان لا يُصلي تهجره، وهو القاطع هو، لستَ القاطع أنت، هو القاطع؛ لأنه فعل ما يُوجب هجره، وهكذا إذا كان يتعاطى على وليمته بالمُنكرات، فهجرت وليمتَه ولم تُجب دعوتَه؛ لأنه يشرب عليها الخمر، هو القاطع، ما هو أنت القاطع، القاطع مَن فعل المنكر، وليس القاطع مَن هجره، فليس هذا قطيعةً، ولكن طاعةً لله ولرسوله، وإنكارًا للمنكر، وهجرًا لمَن يستحق الهجر.\nوقد هجر النبيُّ ﷺ والمسلمون كعب بن مالك وصاحبيه خمسين ليلةً، وهجره من أقاربه الكثير، وهم أقارب؛ طاعةً لله ولرسوله، فلم يُسَمِّ هذا قطيعة.","link":"https://binbaz.org.sa/fatwas/20873/ما-حكم-ازالة-منكر-يترتب-عليه-قطع-رحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0668ما حكم إزالة منكر يترتب عليه قطع رحم؟ ابن باز فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":868,"question":"كيف يستطيع المسلمُ أن يرجع في دعوته في بيته ويُؤثر فيهم؟","title":"كيف يكون المسلم داعيةً في بيته؟","answer":"الجواب: المقصود أنَّ عليه أن يعمل في بيته بطاعة الله وشرع الله، عليه أن يلزم شرع الله، وأن يكون قدوةً لأهل بيته بالعمل بطاعة الله، والحذر من محارم الله؛ حتى يقتدوا به، فإذا كان صادقًا يلتزم بشرع الله في أعماله وأقواله حتى يتأسَّى به أولادُه وإخوانه وزوجته ونحو ذلك، وإذا خالفوه يُعالج الموضوع بالحكمة، يُعالجه بالكلام الطيب، والأسلوب الحسن. وإذا كان يستطيع أن يُؤدِّب بعضَ أولاده أو زوجته إذا خالفوه فيما أوجب الله أدَّبهم بالتأديب المناسب الخفيف الذي يُعينهم على طاعة الله، ويُعينهم على ترك محارم الله؛ فالإنسان يضرب كما قال النبيُّ ﷺ: واضربوهم عليها لعشرٍ الأولاد، وقال في النساء: واضربوهنَّ، فإذا رأى أنَّ من الحكمة أن يضرب المرأة على أن تُؤدي ما أوجب الله، وأن تدع ما حرَّم الله؛ فله ضربها الضَّرب الخفيف الذي لا يبرح، إذا استطاع ذلك، وظنَّ أنَّ هذا يُفيد، وهكذا مع أولاده إذا استطاع ذلك. لكن أهم الأمور أن يكون قدوةً حسنةً: أن يُسارع في الخيرات، ويستقيم على الطاعات، حتى يُشاهدوا منه الفعل الطيب، والكلام الطيب، حتى يتأسَّوا به.","link":"https://binbaz.org.sa/fatwas/20903/كيف-يكون-المسلم-داعية-في-بيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0698كيف يكون المسلم داعية في بيته؟ ابن باز فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":891,"question":"نرى كثيرًا من الناس يضعون على القبور أجزاء من الخشب والحديد، وبعضهم يضع بلاطًا مُميزًا في منتصف القبر، ويدَّعون أنها علامة، فهل يجوز وضع مثل هذه العلامات؟ وهل يجوز وضع علامة على القبر؟","title":"ما حكم وضع علامات على القبر؟","answer":"الجواب: وضع العلامة جائزٌ: حجر، أو لوح، أو عظم، أو حديدة، أو شيء مما يُعلَّم به القبر؛ لا بأس، قد علَّم النبيُّ ﷺ قبر عثمان بن مظعون بعلامةٍ ، ونصَّ العلماء على ذلك، لكن بشرط ألا يكون في ذلك بناء ولا غلو، بل علامة تُوضَع في القبر، وليس فيها كتابة، لا يكتب على القبور..... لا كتابة، ولا وسم القبيلة؛ لأنها كتابة.","link":"https://binbaz.org.sa/fatwas/20927/ما-حكم-وضع-علامات-على-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0722ما حكم وضع علامات على القبر؟ ابن باز فتاوى المحاضرات.mp3","categories":["أحكام المقابر","الدعوة والدعاة"]},{"id":967,"question":"أنا شابٌّ سلكت طريق الهداية ولله الحمد، ولكني اتَّجهتُ إلى طلب العلم الشرعي، وفجأة تركتُ العلم الشرعي واتَّجهتُ إلى الدعوة، ثم تركتُ الدعوة وجاءتني رغبةٌ بالذهاب إلى الجهاد، وأريد منكم أن تُوضِّحوا لي الطريقة المُثلى لكي أكون شابًّا مُتوازنًا بغير إفراطٍ ولا تفريطٍ، وجزاكم الله خيرًا.","title":"ما النصيحة للشباب لتجنب الإفراط والتفريط؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلَّى الله وسلَّم على رسول الله، وعلى آله وأصحابه ومَن اهتدى بهُداه.\nأما بعد: فإنَّ طلب العلم فرضٌ على جميع المسلمين والمسلمات؛ لأنه لا سبيلَ إلى معرفة العبادة التي خُلق لها الجميع إلا بالعلم، وقد سمعتُم قبل قليلٍ أننا خُلقنا لنعبد الله، كما قال سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]، وهذه العبادة لا نعرفها إلا بالعلم بما قاله الله ورسوله، فطلب العلم مُتعين على الذكور والإناث، على الإنسان أن يتعلم من العلم ما لا يسعه جهله: كيف يعبد ربَّه؟ كيف يُصلي؟ كيف يصوم؟ كيف يُزَكِّي؟ كيف يحج؟ يتعلم ما لا يسعه جهله.\nفإذا مَنَّ الله عليه بالعلم الذي يجب عليه، وصار على بصيرةٍ في دينه، وأحبَّ أن يتفرغ لطلب الدنيا: للتجارة، للصناعة، للزراعة، لا بأس، مع عدم إعراضه عن العلم، بل يتذكر العلم، ويحضر حلقات العلم، ويُشارك مع أهل العلم؛ حتى لا ينسى العلم، وإذا أحبَّ أن يتفرغ للجهاد كذلك، فالجهاد أمره عظيم، وفائدته كبيرة، ومن أفضل الأعمال، بل هو أفضل الأعمال التي يتطوع بها الإنسان. وأما الدَّعوة فلا بد فيها من شرطها: أن يكون على علمٍ، فلا يشتغل بالدعوة إلا إذا كان على علمٍ، على بصيرةٍ بما يدعو إليه، وبما ينهى عنه، على علمٍ بالأدلة الشرعية، قد تفقَّه في ذلك، فحينئذٍ يعمل ما علم، ويدعو إلى الله جلَّ وعلا، كما قال : وَالْعَصْرِ  ۝  إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ  ۝  إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر]، فرتَّب الأمور أربع مراتب: الأول: العلم الذي ينتج عنه الإيمان، فإذا تعلَّم ما يجب عليه وما يلزمه الإيمانُ به: من الإيمان بالله، ورسوله، والفقه في دينه، وعمل، يدعو بعد هذا، قال: وَتَوَاصَوْا بِالْحَقِّ، أولًا: يتعلم ويُؤمن بما أوجب الله عليه، ويتبصَّر في ذلك، ويعمل بما أوجب الله عليه، ثم يشتغل بالدعوة إلى ما علم من دين الله، ويتواصى مع إخوانه بالحقِّ والصبر عليه.","link":"https://binbaz.org.sa/fatwas/21015/ما-النصيحة-للشباب-لتجنب-الافراط-والتفريط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0812اريد منكم أن توضحوا لي الطريقة المثلى لكي أكون شاباً متوازناً بغير أفراط ولا تفريط؟ ابن باز.mp3","categories":["العالم والمتعلم","الدعوة والدعاة"]},{"id":997,"question":"سماحة الشيخ، قصور الأفراح يُعمل فيها حفلات زواج، ويقومون بالصلاة داخل قصر الأفراح، والمسجد يبعد عنهم مئة متر، هل تصح صلاتُهم؟","title":"حكم الصلاة بقصور الأفراح مع قرب المسجد","answer":"الجواب: تصحّ صلاتهم، لكن مع الإثم، يأثمون، صلاتهم صحيحة لكنَّهم آثمون؛ لأنَّهم هجروا المسجد ولم يصلوا مع إخوانهم، فالواجب عليهم أن يُصلوا مع إخوانهم في المسجد، ولم يأمر النبيُّ ﷺ الذين تخلَّفوا بالإعادة، ما أمرهم بالإعادة، لكن توعَّدهم بأن يحرق عليهم بيوتهم، وقال: مَن سمع النِّداء فلم يأتِ فلا صلاةَ له إلا من عذرٍ يعني: صلاة كاملة، وإلا فهي تُجزئ عند أهل العلم، لكن يجب عليهم أن يُصلوا مع الجماعة، وليس لهم الترخص بالصلاة في قصور الأفراح، ولا في مجالسهم، بل عليهم أن يُصلوا في المساجد التي يسمعون أذانها قربهم، يسمعون أذانها، وليس لهم مانعٌ من مرضٍ ولا خوفٍ، يجب أن يُصلوا مع الناس، ولا يُصلون في بيوتهم، ولا في قصور الأفراح، وعلى الدولة أن تعتني بهذا بواسطة الهيئة والإمارات؛ حتى تمنعهم من هذا التَّصرف، وعند وزارة الداخلية في هذا وعند الهيئة في هذا خبرٌ، وعندهم عنايةٌ بهذا الأمر، نسأل الله لهم التَّوفيق.","link":"https://binbaz.org.sa/fatwas/21037/حكم-الصلاة-بقصور-الافراح-مع-قرب-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصلاة داخل قصر الأفراح المسجد قريب.mp3","categories":["صلاة الجماعة","الدعوة والدعاة"]},{"id":1081,"question":"أيّهما نُقدّم: الدَّعوة أم طلب العلم؟","title":"أيهما يُقدَّم: طلبُ العلم أم الدعوة؟","answer":"الجواب:\nقَدِّم طلب العلم والدَّعوة معه، الدعوة ما يمكن أن تُقدّم، الذي ما عنده علمٌ كيف يدعو؟! الذي ما عنده علمٌ جاهل. يُقدّم طلب العلم، والدَّعوة تكون مع ذلك، كلما حصّلتَ علمًا تدعو، إذا عرفت الصلاةَ وأحكامها تدعو إليها على علمٍ، عرفت الزكاة وأحكامها تدعو إليها على علمٍ، عرفت التوحيد وحقيقته والشِّرك وحقيقته تدعو إلى ذلك على علمٍ، وهكذا كلما عرفتَ شيئًا وتبصّرتَ فيه وكنتَ على بينةٍ؛ تدعو إليه على بصيرةٍ. ولا دعوة إلا بعلمٍ، فالعلم هو السابق، والدَّعوة هي التَّابعة.","link":"https://binbaz.org.sa/fatwas/21135/ايهما-يقدم-طلب-العلم-ام-الدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0931أيهما تقدم الدعوة أم طلب العلم؟ ابن باز فتاوى المحاضرات.mp3","categories":["العالم والمتعلم","الدعوة والدعاة"]},{"id":1086,"question":"إننا نجد كثيرًا –وللأسف- من طلبة العلم الشرعي مَن يشغله طلبه للعلم عن إصلاح المُجتمع والدخول فيه، وإذا ناقشته قال: سوف أدعو بعدما أطلب العلم، فما رأيك في هذه المقولة؟","title":"كيف يُجمع بين طلب العلم وإصلاح المجتمع؟","answer":"الجواب:\nالواجب أن يقوم بنصيبه من إصلاح المجتمع، مع العناية بطلب العلم، فلا يمنعه طلبُ العلم من المشاركة في إصلاح المجتمع والتَّوجيه والإرشاد والدَّعوة حسب علمه، ولا يكون هذا الكلام عذرًا في الجملة، وإن كان عذرًا من بعض الوجوه في عدم التَّفرغ لهذا الأمر، لكنه حسب طاقته يعمل، أما التفرغ فيكون بعد الحصول على العلم، وانتهاء المهمة من الطلب الرسمي إلى التنفيذ والعمل، ومع العلم أيضًا؛ لأنه لا يزال طالب العلم في طلب العلم أبدًا، ولو أخذ الدكتوراه، ولو طلب العلم خمسين سنةً فهو لا يزال طالب علم أبدًا حتى يلقى ربَّه، ينبغي له أن يعلم هذا، وما خفي عليه أكثر مما علم.\nفطالب العلم يجب أن يعلم أنه لا يزال في حاجةٍ إلى العلم ولو بلغ ألف عام، ولو عمَّر أكثر من عمر نوح فهو في حاجةٍ إلى طلب العلم، فلا ينبغي أن تمنعه الوظيفة أو درجة علمية من المزيد من طلب العلم، والحرص على مُراجعة العلماء، والمذاكرة، ومراجعة الكتب، وتدبر القرآن؛ ليزداد علمًا.  ولكن مع ذلك يُشارك أيضًا في إصلاح المجتمع حسب طاقته: في طريقه إلى المدرسة، في طريقه إلى الجامعة، في طريقه إلى الصلاة، في طريقه لحاجاته في السوق، في سفره، في السيارة، في الطائرة، في القطار، في السفينة، في الباخرة، ما له عذر أن يقول: أنا طالب علم فقط، عليه أن يُشارك، لكن بالعلم، ما هو بالجهل، عليه أن يُشارك بالعلم، لا يقول بغير علمٍ، إذا كان ما عنده علمٌ لا يتكلم، وما كان فيه علمٌ وبصيرةٌ فليتكلم، ولا يقول: أنا حتى الآن في طلب العلم! كل الناس في طلب العلم، لو كان شيخُ الإسلام ابن تيمية موجودًا الآن فهو طالبٌ للعلم حتى يموت، وهكذا الصحابة في طلب العلم حتى يموتوا، كلٌّ في طلب العلم، ما أحد يستغني عن طلب العلم أبدًا، ولو كان مَن كان في التَّحصيل.\nفالحاصل أنه لا يجوز أن يمنعه طلبُ المزيد من العلم من المشاركة في إصلاح المجتمع، سواء كان في الثانوي، أو في المتوسط، أو في الجامعة، أو في الدراسات العليا، أو في أي قسمٍ، عليه أن يُشارك حسب طاقته: في أهله، في جيرانه، في قراباته، في جُلسائه، في طريقه، في أي مكانٍ يُشارك في طلب العلم، ويُشارك في توجيه الناس إلى الخير، ويُشارك في إصلاح المجتمع، لكن يتحرى الأساليب الطيبة، يتحرى الرفق، يتحرى الكلمات الطيبة، والأسلوب الحسن الذي ينفع ولا يضرّ، الذي يُقرِّب ولا يُنَفِّر، الذي يُسبب دخول العلم على قلب الإنسان وقبوله إيَّاه، وليحذر العنفَ أبدًا أينما كان.","link":"https://binbaz.org.sa/fatwas/21130/كيف-يجمع-بين-طلب-العلم-واصلاح-المجتمع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0926هل هناك تعارض بين طلب العلم وإصلاح المجتمع؟ ابن باز فتاوى المحاضرات.mp3","categories":["العالم والمتعلم","الدعوة والدعاة"]},{"id":1095,"question":"هل المسائل العملية المُشتبهة: كالعُذر بالجهل -ونعوذ بالله من ذلك- يُوجب الخلاف فيها ووقوع الهجر والبغضاء بين أصحاب المُعتقد السَّلفي الواحد؟","title":"حكم التباغض بسبب الخلاف في المُشتبهات","answer":"الجواب:\nالواجب في هذا الأسلوب الحسن، وحُسن الظن، وعدم العنف والشدة، فالكل طالبٌ للحقِّ، والله يقول جلَّ وعلا في كتابه العظيم: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]، ويقول في حقِّ أهل الكتاب: وَلَا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ [العنكبوت:46] وهم كفَّار، نهانا أن نُجادلهم إلا بالتي هي أحسن وهم كفَّار، كيف بإخواننا؟!\nالواجب الجدال بالتي هي أحسن، وحسن الظن، وحمل أخيك على أحسن المحامل، حتى يهتدي، وحتى يقبل الحقَّ، لا تيأس، ولا تهجر، ولكن عليك بالمجادلة بالتي هي أحسن، وحسن الأسلوب، والصبر، والتحمل، وعدم الغضب، حتى يظهر الحقُّ للجميع، والحق ضالَّة المؤمن، وليس من شرط ذلك أن تظهر أنت، عليك بطلب الحقِّ، والجدّ في طلب الحق، سواء غَلبتَ أو غُلبتَ، سواء ظهر الحقُّ على يديك، أو على يد أخيك، عليك بالإخلاص، وأن يكون هدفك ظهور الحقِّ، سواء معك أو مع أخيك.\nهذا هو شأن المؤمن: يحرص على ظهور الحق من طريقه أو من طريق إخوانه، ومتى ظهر الحقُّ خضع له، وأجاب إليه، ولم يتكبَّر، ولم يستمر في باطله، ويلج في باطله.\nومن أهم الأمور: العناية بالأسلوب الحسن، وحسن الظن، وعدم سوء الظن، واختيار الكلمات الطيبة، والصبر على ما قد يقع من أخيك من أذى، أو كلمات نابية، أو غير هذا، حتى تصلوا جميعًا إلى الحقِّ، وأنتم بحمد الله تُريدونه وتطلبونه.\nأما إذا ساءت الأخلاقُ، وساءت الظنون، وساء الكلام، فإنَّ هذا من أسباب ضياع الحقِّ، ومن أسباب الفرقة والاختلاف التي ذمَّها الله وعابها. نسأل الله السَّلامة.","link":"https://binbaz.org.sa/fatwas/21156/حكم-التباغض-بسبب-الخلاف-في-المشتبهات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0952هل المسأئل العلمية المشتبهة يوجب الخلاف فيها ووقوع الهجر والبعضاء؟ابن باز فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1096,"question":"ما دور المسلم فيما يجري من الأحداث العظام على الأرض: بسقوط النظام الشيوعي في أوروبا الشرقية، وحركات التَّحرر في شعوب العالم؟ أليس الوقت مناسبًا لكي ينطلق الدُّعاة من المسلمين لهذا الدين إلى هؤلاء المساكين؟ ولكن كيف؟","title":"ما دور المسلم فيما يجري من أحداث بالعالم؟","answer":"الجواب:\nلا شكَّ أنَّ هذا من نِعَم الله، هذا الانهيار -سقوط الدول الشيوعية- لا شك أنَّ هذا من نعم الله العظيمة، فإنها تتابعت السقوط والانهيار، هذا من رحمة الله جلَّ وعلا، ولا شكَّ أنه يُوجِب على أهل الإسلام الجدّ والنشاط في دعوة أولئك، وشرح الإسلام لهم، ببعث الدعاة، والكتب النافعة، والمصاحف.\nوالمسلمون أولى بهذا من نشاط الآخرين من النصارى وغيرهم، يجب على أهل الإسلام، وعلى ملوك الإسلام، وعلى علماء الإسلام أن ينشطوا في هذا الأمر العظيم.\nونُبشِّركم أنَّ الجهود في هذا إن شاء الله مبذولة منا ومن غيرنا، ونسأل الله أن ينفع بالأسباب، الجهود مبذولة منا، ومن الرابطة، ومن غيرنا من أهل العلم، ونسأل الله أن يُبارك في الأسباب، وأن ينفع بالأسباب.\nوالواجب على كل عالمٍ وكل مَن له قدرة أن يُشارك وأن يُساهم بما أعطاه الله من علمٍ ومالٍ وجاهٍ وغير ذلك، والله لا يُضيع أجر مَن أحسن عملًا .","link":"https://binbaz.org.sa/fatwas/21155/ما-دور-المسلم-فيما-يجري-من-احداث-بالعالم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0951ما دور المسلم فيما يجري من الأحداث العظام على الأرض؟ابن باز فتاوى المحاضرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1129,"question":"لا شكَّ أنَّ من إحياء التراث الإسلامي كما تفضلتم: الدَّعوة إلى الكتاب والسنة، وتبليغها للناس جميعًا، بماذا تنصحون الشباب الإسلامي في هذا العصر؟","title":"ما النصيحة للشباب المسلم في هذا العصر؟","answer":"الجواب:\nننصحهم أولًا بالعناية بالعلم، وأن يكونوا على بصيرةٍ، فإذا حصلت لهم البصيرة فالواجب عليهم الدَّعوة، فإنَّ هذا الدين علمٌ وعملٌ ودعوةٌ وصبرٌ، كما قال : وَالْعَصْرِ  ۝  إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ  ۝  إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر].\nذكر الشيخ محمد رحمه الله في كتابه الصغير \"ثلاثة الأصول\" أنه يجب على المسلم هذه الأربعة: العلم، والعمل، والدعوة، والصبر، والمقصود مَن هو أهلٌ لذلك عليه أن يتعلم ويعمل، ثم عليه أن يدعو ويصبر، كما دلَّت عليه الآية: وَالْعَصْرِ  ۝  إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ  ۝  إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ، فلا بد من بصيرةٍ: قُلْ هَذِهِ سَبِيلِي أَدْعُو إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108]، فيدعو إلى ما يعلم، يعلم الصلاة وأحكامها يدعو إلى الصلاة وأحكامها، يعلم الزكاة مع ذلك يدعو إلى الزكاة وأحكامها، إذا كان على بصيرةٍ: الصيام، الحج، الجهاد، برّ الوالدين، صلة الرحم، يدعو إلى كل ما يعلم على بصيرةٍ، يحذر من الزنا، من اللواط، من شرب الخمر؛ لأنه يعلم أحكام هذه الأشياء: من الربا، من قذف المحصنات.....\nلا يتكلم في شيءٍ إلا عن علمٍ وبصيرةٍ، كما قال الله جلَّ وعلا في كتابه العظيم: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالْإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لَا تَعْلَمُونَ [الأعراف:33]، فجعلها في الذِّروة، جعلها أعلى؛ لأنَّ الآية فيها التَّرقي من الأدنى إلى الأعلى، فأعظم الذنوب الشِّرك، ثم جعل فوقه هنا القول على الله بغير علمٍ؛ لأنَّ الشرك من القول على الله بغير علمٍ، ويدخل في القول على الله بغير علم أشياء كثيرة، فوجب على العبد أن يحذر ذلك.\nوأخبر في سورة البقرة أن الشيطان يدعو إلى هذا ويأمر به، قال سبحانه: يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الْأَرْضِ حَلَالًا طَيِّبًا وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ  ۝  إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لَا تَعْلَمُونَ [البقرة:168- 169]، هذه حال عدو الله، يدعونا إلى الفحشاء والسوء والقول على الله بغير علمٍ، فوجب الحذر من ذلك.","link":"https://binbaz.org.sa/fatwas/21203/ما-النصيحة-للشباب-المسلم-في-هذا-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0999لاشك أن من أحياء التراث الإسلامي الدعوة إلى الله والسنة وتبليغها للناس فماذا تنصون الشباب في ذلك.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1165,"question":"قد يُشاهد الشابُّ في منزله مخالفةً شرعيةً، ويجد صعوبةً في الإنكار، وصعوبةً أشدّ في السُّكوت عن هذه المُخالفة، فهل من توجيهٍ نحو الأسلوب الذي ينبغي أن يسلكه الشابُّ تجاه هذه المُخالفات؟","title":"ما الأسلوب الصحيح للإنكار في البيوت؟","answer":"الجواب:\nلا يجوز للشابِّ، ولا غير الشابِّ، لا يجوز له السُّكوت، بل يُنكر حسب طاقته، سواء كان شابًّا أو فتاةً أو كهلًا أو شيخًا أو عجوزًا، على الجميع الإنكار، والله يقول جلَّ وعلا في كتابه العظيم: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]، فجعل هذا الخُلُق من أخلاق المؤمنين والمؤمنات جميعًا، قال سبحانه: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنْكَرِ [آل عمران:110]، ولعن كفَّار بني إسرائيل لتضييعهم هذا الواجب، فقال سبحانه: لُعِنَ الَّذِينَ كَفَرُوا مِنْ بَنِي إِسْرَائِيلَ عَلَى لِسَانِ دَاوُودَ وَعِيسَى ابْنِ مَرْيَمَ ذَلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ  ۝  كَانُوا لَا يَتَنَاهَوْنَ عَنْ مُنْكَرٍ فَعَلُوهُ [المائدة:78- 79].\nوقال النبيُّ ﷺ: إنَّ الناس إذا رأوا المنكر ولم يُغيِّروه أوشك أن يعمَّهم الله بعقابه خرجه الإمام أحمد بإسنادٍ صحيحٍ عن الصديق ، وقال أيضًا عليه الصلاة والسلام: مَن رأى منكم مُنكرًا فليُغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه، وذلك أضعف الإيمان خرجه مسلمٌ في \"صحيحه\" عن أبي سعيدٍ الخدري .\nفعلى الشابِّ وعلى غيره الإنكار حسب الإمكان، بالأسلوب الحسن، والطريقة المناسبة التي يراها أنجع وأنفع: على أبيه، وعلى أمه، وعلى إخوانه وأخواته، وأخواله وأعمامه، وغيرهم، على أهل بيته بالطريقة التي يراها أنجع، مع الأب لها حال، ومع الأم لها حال، ومع الأخوال والأعمام لها حال، ومع الإخوة لها حال، ومع الزوجة لها حال، ويحرص على أن يكون معه غيرُه من إخوته يُساعدونه إذا هداهم الله، حتى تكون الكلمةُ واحدةً، لكن بالأسلوب الحسن، ولا سيما مع الوالدين، يتأدَّب مع الوالدين، ولا يتكلم إلا بكلامٍ طيبٍ ومعقولٍ؛ لأنَّ الله قال في حقِّ الكافِرَيْنِ: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15]، فكيف بالمسلِمَيْنِ؟!\nيا أبتِ كذا، يا أمي، يا أماه كذا وكذا، هذا لا يجوز، وأنا أخاف عليكما من سخط الله، أخاف عليكما من عقوبة ذلك، فيما يرى من المنكر: كالتَّخلف عن الصَّلوات، سماع الأغاني والملاهي، السَّبّ والشَّتم، إلى غير هذا من المنكرات، ولا يغفل، ولا يسكت، ولكن بالحكمة، والكلام الطيب، والأسلوب الحسن، وتحري الأوقات المناسبة، فإذا أمكن أن يكون معه غيرُه من خالٍ أو خالةٍ، أو عمٍّ أو عمَّةٍ، أو أخٍ يساعد معهم يكون ذلك أنفع.","link":"https://binbaz.org.sa/fatwas/21218/ما-الاسلوب-الصحيح-للانكار-في-البيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1014ما هو الأسلوب الأنسب إذا وجد منكر أو مخالفة في بيته؟ابن باز.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1184,"question":"هل يجوز الجلوس مع أهل المعاصي بقصد دعوتهم إلى الله تعالى وتغيير المُنكر؟","title":"حكم الجلوس مع أهل المعاصي لدعوتهم","answer":"الجواب:\nنعم، إذا جلس بينهم للدَّعوة والتَّوجيه إلى الخير فهذا مأجورٌ ومشكورٌ، النبي كان يمرُّ على القبائل من الكفرة ويدعوهم إلى الله في منى، وهكذا في مكة: يأتي مجالسهم ويدعوهم إلى الله، هذا مأجورٌ، هو جهادٌ إذا كان بهذا القصد.  أما جلوسه معهم للصحبة والتَّلذذ بالأكل والشرب والمضاحكة فلا، أما إذا كان يجلس معهم أو يقف عليهم للدَّعوة والتَّوجيه والإرشاد والكلام الطيب والاحتساب والصبر والأسلوب الحسن؛ فهذا عمل الأنبياء.","link":"https://binbaz.org.sa/fatwas/21248/حكم-الجلوس-مع-اهل-المعاصي-لدعوتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1146هل يجوز الجلوس مع أهل المعاصي بقصد دعوتهم وتغيير المنكر؟ ابن باز فتاوى.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1187,"question":"بعض الإخوة الذين يدعون إلى الله قد يختلفون فيما بينهم في بعض الأمور، فما رأيكم؟","title":"ما الحكم والتوجيه فيما يقع من اختلاف الدعاة؟","answer":"الجواب:\nيدعون إلى الله فيما يتَّفقون عليه، ويدرسون ما أشكل عليهم من جهة الأدلة، أو مع أهل العلم الذين هم أعلم منهم، حتى يتَّفقوا؛ لأنَّ النزاع قد يضرُّ، فيدعون إلى الله فيما اتَّفقوا عليه، ولا يختلفون عند الناس، ويدرسون ما اختلفوا فيه حتى يتَّفقوا، أو يسألون مَن هو أعلم منهم إذا خفيت عليهم الأدلةُ، لعلَّهم ينجحون ويتَّفقون، وفَّق الله الجميع.","link":"https://binbaz.org.sa/fatwas/21245/ما-الحكم-والتوجيه-فيما-يقع-من-اختلاف-الدعاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1149بعض الدعاة يختلفون فيما بينهم فما رأي سماحتكم؟ ابن باز فتاوى.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1194,"question":"يشتكي كثيرٌ من إخواننا المسلمين من بلاد شرق آسيا وشبه القارة الهندية من سُوء معاملة الشباب المُلتزم لهم، وأخشى أن يكون ذلك سبب احتقارهم لهم وعدم احترامهم، مع أنهم مسلمون، وقد نهى النبيُّ ﷺعن ذلك، نرجو من سماحتكم التَّوجيه.","title":"ما النصيحة المناسبة بحُسن الخلق في الدعوة؟","answer":"الجواب:\nالواجب على الدُّعاة إلى الله في أي مكانٍ، سواء كانوا شبابًا أو شيبًا أو كهولًا، الواجب عليهم أن يرفقوا بالناس، وألا يحتقروهم، بل عليهم أن يُعلِّموهم ويُرشدوهم ويرحموهم، لعلهم يقبلون منهم، ولعلهم يهتدون، يقول النبيُّ ﷺ في الحديث الصحيح: مَن يُحْرَم الرفق يُحرم الخير كله، ويقول عليه الصلاة والسلام: إنَّ الرفقَ لا يكون في شيءٍ إلا زانه، ولا يُنزع من شيءٍ إلا شانه، ويقول عليه الصلاة والسلام: اللهم مَن ولي من أمر أمتي شيئًا فرفق بهم فارفق به، اللهم مَن ولي من أمر أمتي شيئًا فشقَّ عليهم فاشقق عليه.\nفالواجب على الدعاة أن يرفقوا بالكافر والعاصي، ولا يعجلوا، ولا يعنفوا، بل بالدَّعوة بالتي هي أحسن، بالرفق، بالحكمة، والدعاء له بالهداية، لعله يستجيب، يقول الله سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]، ويقول سبحانه: وَلَا تُجَادِلُوا أَهْلَ الْكِتَابِ يعني: اليهود والنَّصارى إِلَّا بِالَّتِي هِيَ أَحْسَنُ إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ [العنكبوت:46] يعني: الظالم المتعدي يُعامل بما يستحقّ، أما ما دمت تدعوهم ولم يظلموك فجادل بالتي هي أحسن، وارفق بهم.\nوقال جلَّ وعلا في وصف نبيه محمد ﷺ: فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لَانْفَضُّوا مِنْ حَوْلِكَ [آل عمران:159]، ولما بعث الله موسى وهارون إلى فرعون قال لهما: فَقُولَا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى [طه:44].\nفالواجب على الدُّعاة إلى الله في باكستان، أو في بنغلاديش، أو في الهند، أو في أي مكانٍ، أو في المملكة هنا، أو في أي مكانٍ: الرفق، والكلام الواضح الطيب، والجدال بالتي هي أحسن، والدعاء لهم بالهداية، جاء رجلٌ إلى النبي ﷺ فقال: يا رسول الله، إنَّ دوسًا قد عصت وأبت الإسلام، فادع عليهم، فقال ﷺ: اللهم اهدِ دوسًا وائتِ بهم، اللهم اهدِ دوسًا وائتِ بهم، فهداهم الله وجاءوا إلى المدينة مسلمين؛ فلا بد من الرفق.","link":"https://binbaz.org.sa/fatwas/21238/ما-النصيحة-المناسبة-بحسن-الخلق-في-الدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1156نصيحة للدعاة إلى الله بحسن الخلق؟ ابن باز.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1197,"question":"نلاحظ هذه الأيام تزايد نشاط أعداء الله من العلمانيين وغيرهم لكيد شباب الصَّحوة، ولكن لا بدَّ للشباب من التَّثبت والركود وحساب كل شيءٍ، حتى لا يُستدرجوا إلى ما لا تُحمد عقباه، نرجو من سماحتكم توجيه النَّصيحة إلى إخواننا في ذلك؟","title":"كيف يُنصح الشباب بالتثبت وتجنب الاندفاع؟","answer":"الجواب:\nنعم، يجب على الشباب وغير الشباب، يجب على أهل العلم، وعلى كل مؤمنٍ التَّثبت في الأمور وعدم العجلة، وهكذا يجب على كل مؤمنةٍ التَّثبت في الأمور وعدم العجلة، فإذا رأى ما يُخالف الشرع المطهر أو سمع به أنكره حسب طاقته مع الشخص، ينصحه، المرأة مع المرأة ومع غيرها تنصحها، المرأة تنصح وتأمر بالمعروف وتنهى عن المنكر كالرجل، مع أخيها، ومع أبيها، ومع أولادها، ومع جيرانها، ومع غيرهم، المؤمنون شيءٌ واحدٌ، المؤمنون إخوة: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]، والعَجَلة شرُّها عظيم، وعاقبتها وخيمة، وفي الحديث: العَجَلة من الشيطان، وفي الحديث الصحيح: مَن يُحرم الرفق يُحرم الخير كله.\nفالواجب على مَن رأى شيئًا من المنكر في الطريق أو في السوق أن يُنكره بالكلام الطيب: يا عبدالله، يا أمة الله، هذا لا يجوز، الواجب عليك يا عبدالله كذا، الواجب عليكِ يا أمة الله كذا، هدانا الله وإياكم، وفَّقنا الله وإياكم؛ لأنَّ هذا يُقرّب القلوب ويدعوها إلى القبول، أما: يا فاجر، يا خبيث، يا كذا، هذا يُسبب النّفرة والشَّحناء، وربما أفضى إلى المجادلة والمقاتلة.\nفالواجب على المؤمن والمؤمنة في مثل هذا المقام الرفق والحكمة: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وهي العلم وَالْمَوْعِظَةِ الْحَسَنَةِ الترغيب والترهيب وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] عند الشُّبهة، والجدال بالتي هي أحسن حتى ولو كان كافرًا، بالتي هي أحسن، قال تعالى: وَلَا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ، وأهل الكتاب هم اليهود والنصارى إِلَّا الَّذِينَ ظَلَمُوا [العنكبوت:46]، إلا مَن ظلم وتعدَّى عليك وسبَّك، هذا ترفع بأمره، تشكوه إلى ولاة الأمور حتى يأخذوا حقَّك منه، حتى لا تكون فتنة.\nوالمقصود من هذا كله أن الواجب التناصح، والأمر بالمعروف، والنهي عن المنكر بالحكمة، والكلام الطيب، والأسلوب الحسن، لا بالعنف والشدة، ولا بالألفاظ القبيحة الشنيعة المنفرة.","link":"https://binbaz.org.sa/fatwas/21235/كيف-ينصح-الشباب-بالتثبت-وتجنب-الاندفاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1159نصيحة للشباب المسلم في التثبت والركود في الحكم على الأمور؟ ابن باز.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1274,"question":"عندما يكون الطبيبُ في مكان عمله الذي يستوجب منه علاج المسلم وغير المسلم: كالنَّصارى أو غيرهم، مثلًا في حالة الحرب، مع الخوف من هذا النَّصراني الذي قد يحصل فيما بعد، فما موقف الطبيب المُعالج أمام الله تعالى في ذلك، وفي علاج هذا الذي يبغضه اللهُ ورسولُه، ويبغض اللهَ ورسولَه؟","title":"ما واجب الطبيب تجاه المريض غير المسلم؟","answer":"الجواب:\nالواجب على الطبيب أداء الأمانة، يُعالجه كما يُعالج غيره؛ لأنَّ هذا صار في محلِّ الأمان، ومحل الاستئمان ما هو محل الحرب، إذا كان تبعنا أو دخل عندنا بالأمان: موظف، وطبيب، أو مع المجاهدين الآن، مع الميليشيات التي تُحارب الآن، لو جرى عليه شيءٌ لا بد أن تُعالجه كما تُعالج المريض المسلم، اتَّقِ الله في أداء الأمانة.  وكونه يبغضه الله: هذا إلى الله سبحانه، لكن أنت الآن دخل عندك بالأمان فلا بد أن تُعالجه، إن كان مؤتمنًا، أو مُعاهدًا، أو جاء في رسالةٍ، لو دخل بالأمان برسالةٍ، أو جاء طبيب، أو لأسبابٍ أخرى، ثم أصابه مرضٌ فعالجه بالأمانة، ولا تضرّه بشيءٍ.\nس: ألا ترون أنَّ في مثل هذه الحالة مجالًا للدعوة الإسلامية واستجلابًا للناس؟\nالشيخ: زيادة الدعوة، الدعوة طيبة، كونه يدعوه إلى الله، ويُرغِّبه في الإسلام؛ هذا طيبٌ، مع العلاج، لكن فقط لا يخون الأمانة، لا يُعالجه بشيءٍ يضرُّه، بل يجب أن ينصح له، وهذا من الدعوة إلى الإسلام، كونه ينصح له هذا من الدعوة إلى الإسلام، يستشعر النَّصراني أو غيرُه أنَّ الإسلام ينصح ويُؤدي الواجب لمن اؤتُمن عليه، أو صار في أمانته، أو في عهده، أو في ذمته.","link":"https://binbaz.org.sa/fatwas/21331/ما-واجب-الطبيب-تجاه-المريض-غير-المسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1074ما هو واجب الطبيب المسلم تجاه المريض الغير مسلم؟ ابن باز فتاوى.mp3","categories":["الطب والتداوي","الدعوة والدعاة"]},{"id":1294,"question":"نرى أثناء عملنا كأطباء في العيادات بعض النِّساء المُتبرجات، فهل يجب علينا وجوبًا نصحهنَّ؟","title":"هل يلزم الطبيب نصحُ المُراجِعة المتبرجة؟","answer":"الجواب:\nنعم، يجب عليكم وعلى المدير وجوبًا النُّصح والمنع أيضًا، مَن له قدرة كالمدير عليه المنع، وأن يلبسن لباسًا ليس فيه تبرج، ويتسترن، ويحتجبن، ويعتنين بذلك حتى لا يَفتن ولا يُفتنَّ، هذا واجبٌ، تلبس لباسًا ليس فيه فتنة، وتكون تغطي وجهها: إما بالخمار وإلا بالبرقع، لا يظهر إلا العين، وتكون كذلك مُعتنيةً بيديها، ما يكون فيها ما يفتن الناس، ولا رجليها، أن تكون مستورةً، حتى تكون بعيدةً عن أسباب الفتنة.\nويجب على المسؤول الذي هو المدير ومَن ينوب عنه أن يمنعها من ذلك، وعلى الطبيب أن ينصحها، وأن يحذِّرها من هذا العمل، والله يقول: وَلَا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الْأُولَى [الأحزاب:33]، تبرج الجاهلية:  إبداء بعض المحاسن: من رأسٍ، أو وجهٍ، أو صدرٍ، أو قدمٍ، أو غير هذا.","link":"https://binbaz.org.sa/fatwas/21343/هل-يلزم-الطبيب-نصح-المراجعة-المتبرجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1086نرى نحن الأطباء بعض المتبرجات في العيادات فهل يجب علينا نصحهم؟ ابن باز.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1307,"question":"رجلٌ يقول: أنه يوجد في مجال عمله كفَّار من الهندوس والبوذيين والنَّصارى وغيرهم، فكيف يتعامل معهم في السلام والمُصافحة؟","title":"ما كيفية التعامل مع زميل العمل غير المسلم؟","answer":"الجواب:\nيتعامل معهم على الشريعة: لا يبدؤهم بالسلام، وإذا بدؤوا يردّ عليهم وينصحهم ويُعلِّمهم ويُوجِّههم إلى الخير، لما يسَّر الله له وجودهم يُوجِّههم إلى الخير، يدعوهم إلى الله، ويُعلِّمهم، يقول النبي ﷺ: مَن دلَّ على خيرٍ فله مثل أجر فاعله، ويقول ﷺ: لأن يهدي الله بك رجلًا واحدًا خيرٌ لك من حمر النعم. فإذا سلَّموا ردَّ عليهم، وإذا صافحوه صافحهم، لا يبدؤهم، ويقول له إذا رأى المصلحة في ذلك: كيف أولادك؟ كيف حالك؟ هداك الله، وفَّقنا الله وإياك، وما أشبه ذلك مما يُقربه إلى الخير. لكن لا يتَّخذهم أصحابًا، إنما يدعوهم إلى الله، ويُعلمهم بالكلام الطيب والرفق، والله يقول: وَقُولُوا لِلنَّاسِ حُسْنًا [البقرة:83]، ويقول جلَّ وعلا: فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لَانْفَضُّوا مِنْ حَوْلِكَ [آل عمران:159]، ويقول الله لموسى وهارون لما بعثهما إلى فرعون: فَقُولَا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى [طه:44]، ويقول سبحانه: وَلَا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ [العنكبوت:46]، وهم اليهود والنصارى، فلا بدّ من إحسان القول والرفق؛ حتى يَقْبل الحقّ، أو تُعْذِر إليه وتكون أديتَ ما عليك.","link":"https://binbaz.org.sa/fatwas/21362/ما-كيفية-التعامل-مع-زميل-العمل-غير-المسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1105يوجد في مجال عملي كفار فكيف نتعامل معهم في السلام والمصافحة؟ ابن باز.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1369,"question":"لكل يوم يموت للناس ميت ويجتهد الوُّعاظ في وعظ الناس عند دفنهم حول القبر، ثم يأتي يجتهد شباب هداهم الله أو مشيب وينكرون عليهم ويقولون هذه بدعة، فأصل مشروعيتها ما هو؟","title":"ما دليل مشروعية التذكير عند القبور؟","answer":"الجواب:\nالتذكير عند القبور فعله النبي ﷺ لحديث علي في الصحيحين كان جالسًا عند قبر فوعظ الناس وقال: ما منكم من أحد إلا وقد كتب مقعده من الجنة ومقعده من النار قالوا: يا رسول الله ففيم العمل؟ قال: اعملوا فكل ميسر لما خلق له، أما أهل السعادة فييسروا لعمل أهل السعادة، وأما أهل الشقاوة فييسروا لعمل أهل الشقاوة، ثم تلا قوله تعالى: فَأَمَّا مَنْ أَعْطَى وَاتَّقَى  ۝ وَصَدَّقَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْيُسْرَى  [الليل:5-7] الآيات من سورة والليل إذا يغشى، ذكره ابن كثير عند تفسير هذه الآية. كذلك من حديث البراء بإسناد صحيح عند الترمذي وغيره أنه ﷺ كان جالسًا عند قبر فذَكَّر الناس، وذكر موت الإنسان وخروج روحه وصعوده إلى عليين إن كان مؤمنًا وروحه طيبة، وردها من السماء إذا كان روحها خبيثة. ولأن الناس عند القبر قلوبهم فيها رقة تتأثر بالوعظ والتذكير عند ذكر الموت وتكون صالحة لقبول الذكرى ذلك الوقت.","link":"https://binbaz.org.sa/fatwas/21462/ما-دليل-مشروعية-التذكير-عند-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التذكير عند القبور.mp3","categories":["أحكام المقابر","الدعوة والدعاة"]},{"id":1412,"question":"بعض الجماعات الإسلامية تَدَّعي بأنها ملتزمة بالكتاب والسنة، وكلهم متفرقون؟","title":"ما ضابط الاجتماع وعدم التفرق بين الدعاة؟","answer":"الجواب:\nيُنصحون، على من يعرف حالهم من أهل العلم نُصْحُهم؛ حتى يجتمعوا على الحق. أما يكونوا أحزابًا وفِرَقًا ما يصلح.\nس: ما هو ضابط الاجتماع؟\nج: على الكتاب والسنة، إذا كانت دعوتهم كلهم على الكتاب والسنة لا يختلفون، هذا الضابط.","link":"https://binbaz.org.sa/fatwas/21507/ما-ضابط-الاجتماع-وعدم-التفرق-بين-الدعاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ضابط الاجتماع على الكتاب والسنة.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1424,"question":"إذا كان بعض الناس يخالفون السُّنة هل يجب علينا أن ننصحهم؟ وكيف تكون النصيحة؟","title":"ما كيفية التعامل مع مَن يخالفون السُّنة؟","answer":"الجواب:\nالنصيحة بالرفق، تنصحه بالرفق، تُعَلِّمه، إذا رأيته يسبل إزاره تنصحه، رأيته ما يلعق أصابعه تُعَلِّمه، رأيت يأكل باليسار تُعَلِّمه، رأيته يفعل أشياء أخرى مما لا توافق الشرع تنصحه، لكن بالكلام الطيب والأسلوب الحسن، كما قال ربنا : ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125].\nس: النصيحة هل تكون سرية أو جهرية؟\nج: على حسب الحال، إن كان عند الناس بينك وبينه، وإن كان بينك وبينه ترفع صوتك، وإن كنتم حول الناس تُسِرّ حتى لا تكون سببًا لرد النصيحة؛ حتى يكون أقْبَل للنصيحة.","link":"https://binbaz.org.sa/fatwas/21519/ما-كيفية-التعامل-مع-من-يخالفون-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التعامل مع من يخالفون السنة.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1426,"question":"بعض الشباب ذُهِبَ إليهم ونُصحوا ووُجِّهوا بأن يدعوا إلى توحيد الله ، فغضبوا وحزنوا وضاقت صدورهم بنا، فهل حفظك الله نبقى معهم أم يُتركوا؟","title":"ما كيفية الدعوة الصحيحة لفئة الشباب؟","answer":"الجواب:\nيُعلَّمون ويُنصحون، فالتوحيد هو الأول، فإذا كان المسلمون على التوحيد يُعلمونهم ما يجهلون في صلاتهم، وفي صومهم.  أما إذا كانوا في أناسٍ عندهم شرك فيبدؤون بالتوحيد، يُعلِّمونهم التوحيد أولًا؛ لأن الأعمال ما تصحّ إلا بعد السلامة من الشرك. أما إذا كانوا مثل هذا المجتمع السعودي أو أشباهه –في مجتمع إسلامي طيب- فيدعونهم إلى ما يظنون أنهم قصَّروا فيه، أو يخفى عليهم، ويُنَبِّهونهم عليه إذا كانوا أهل توحيدٍ، يُنَبِّهونهم على الأشياء التي تخفى عليهم: في صلاتهم، في صومهم، في زكاتهم، في حجِّهم، في معاملاتهم، أما إذا كانوا في قومٍ كفار فيُبْدَؤون بالتوحيد، ويُحذِّرونهم من الشرك.\nس:... يقولون: أنتم تُنَفِّروننا وتُنَفِّرون غيرنا؟\nج: الدعوة إلى التوحيد ليست تنفيرًا إذا كانت في مجتمعٍ فيه شرك، هكذا دعا الأنبياء، بدؤوا بالدعوة إلى التوحيد، فالرسول ﷺ بدأ بالدعوة إلى التوحيد، وظلَّ عشر سنين كلها دعوة إلى التوحيد قبل أن تُفرض الصلاة.","link":"https://binbaz.org.sa/fatwas/21521/ما-كيفية-الدعوة-الصحيحة-لفىة-الشباب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعوة إلى الله في المجتمع المسلم.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1438,"question":"إذا كان هناك جماعة في اليمين تدعو إلى الله ، وجماعة أخرى في اليسار تدعو إلى الله ، ولكن اليمنى تَسُبّ اليسرى، واليُسرى تَسُبّ اليمنى، فما العمل عندئذٍ؟","title":"حكم الاختلاف والتفرُّق بين جماعات الدعوة","answer":"الجواب:\nالواجب نصيحتهم حتى يجتمعوا، وتحذيرهم من الفرقة، حتى يتفاهموا ويزول الإشكال، أما التناقض هذا فيُنَفِّر الناس من الدعوة، حتى يقول العامي: \"مَن معه الحقّ؟!\"، هذه فتنة! فالواجب الاجتماع والتعاون وإزالة الخلاف بالطرق الشرعية، فعلى العلماء وأهل الخير أن ينصحوهم ويتوسَّطوا بينهم؛ حتى يزول الخلافُ، وتكون الدعوةُ واحدةً.\nس: هل ينقاد لجماعةٍ دون أخرى؟\nج: إذا كان عنده علمٌ ينقاد للتي معها الحقّ، ويكون معها على الطائفة الأخرى حتى تستجيب.","link":"https://binbaz.org.sa/fatwas/21534/حكم-الاختلاف-والتفرق-بين-جماعات-الدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اختلاف الجماعات الداعية إلى الله وتحذير كل من الأخرى.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1440,"question":"هل الواجب علينا العمل على إلغاء هذه الجماعات التي شتت الشملَ وصارت فوضى؟","title":"ما الموقف الصحيح من الجماعات المختلفة؟","answer":"الجواب:\nالواجب السعي في إلغائهم حتى يكونوا كتلةً واحدةً، وحتى تكون دعوتهم واحدةً، فعلى ولاة الأمور وعلى أهل الحل والعقد أن يتوسَّطوا بالطرق الشرعية حتى تجتمع كلمتُهم، وحتى يزول الخلافُ بينهم؛ لأنَّ الخلاف يضرّ المدعوين: لا يدرون مَن معه الحق؟!\nس: بالنسبة للجماعات التي تنتمي إلى الكتاب والسنة، والذي دخل الشيطانُ بينهم وافترقوا، كلهم يُعادون على حسب جماعتهم، ويُوالون على حسب جماعتهم، ثم يسُبّ بعضُهم البعض؟\nج: مثلما قلنا: الواجب على أهل العلم وعلى القادة أن يحلوا مشاكلهم، وأن يجمعوهم، ويُزيلوا ما بينهم من الإشكال، حتى تكون كلمتهم واحدةً، وإلا فهذا شرٌّ عليهم وعلى غيرهم، والله يقول: وَلَا تَكُونُوا كَالَّذِينَ تَفَرَّقُوا وَاخْتَلَفُوا مِنْ بَعْدِ مَا جَاءَهُمُ الْبَيِّنَاتُ وَأُولَئِكَ لَهُمْ عَذَابٌ عَظِيمٌ [آل عمران:105]، فلا بدّ من الاجتماع، يقول سبحانه: وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا [آل عمران:103]، يجب الاجتماع والتعاون، ويجب على السلطة الحاكمة وعلى أهل العلم أن يبذلوا وسعهم في جمع الفرق، ثنتان أو ثلاث فرق أو أربع يجمعوهم حتى يُزيلوا الخلافَ الذي بينهم، حتى لا تكون شبهةً للجُهَّال.\nس: بالنسبة للاجتماع: كيف في مثل هذه الحالة للإنسان أن ينتمي إليهم؛ لأنَّه يكون هناك بغضٌ فيما بينهم، كل واحدٍ يبغض الثاني؟\nج: يجب أن ينتموا إلى الكتاب والسنة، للإسلام، لا ينتموا لزيدٍ ولا لعمرٍو، يجب أن يكونوا كلهم تبعًا للكتاب والسنة، وخَدَمًا للكتاب والسنة، ولا يتعصَّب لرئيسه، ويرحل لرئيسه، ولا يتشبَّهون بالمنافقين، أو بالخوارج، أو بالمعتزلة، لا، الواجب أن يكون هدفهم اتِّباع الكتاب والسنة، ليس لهم هدفٌ سوى هذا.\nس: أعني يا شيخ: الشخص الفردي من المسلمين إذا حصلت مثل هذه الحالة كيف يكون موقفه؟ هل ينتمي إلى الأولى أم إلى الثانية أم إلى الثالثة أو يكون محايدًا؟\nج: يسأل مَن يطمئن إليه حتى يعرف الحق، يسأل العلماء الذين يطمئن إليهم، ولو بالسفر من بلدٍ إلى بلدٍ، حتى يسأل: مَن الحق معه؟ ما هو الحق؟ ما هو الطريق؟ ما هو السبيل؟ حتى يُدَلَّ على الخير، لا بد أن يسأل.","link":"https://binbaz.org.sa/fatwas/21536/ما-الموقف-الصحيح-من-الجماعات-المختلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الموقف من الجماعات المختلفة والمتفرقة.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1469,"question":"كيف يمكن التوفيق بين هذه الأشياء وما يجري في عالمنا الإسلامي الآن من القتل والضرب والحقد؟","title":"ما علاج غُربة الإسلام وما يقع من فتن؟","answer":"الجواب:\nهذا من غربة الإسلام.\nس: ما العلاج؟\nج: العلاج التناصح، والتعاون على البر والتقوى بين المسلمين، وبين دعاة الحق، وبين أهل العلم، وبين العقلاء، هذا هو الواجب؛ فالله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، ويقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]، ويقول سبحانه: وَالْعَصْرِ ۝ إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ  ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3]. وكان بين الأوس والخزرج دماءٌ عظيمة ووحشة وقتال، فلمَّا هداهم الله للإسلام وتعاونوا على البِرِّ والتقوى؛ أزال ذلك بسبب ما أعطاهم الله من الإيمان والهدى والتقوى، وهكذا بين العرب، فالقبائل يغزو بعضُها بعضًا، ويقتل بعضُها بعضًا، فلمَّا هداهم الله للإسلام وعرفوا تحريم ذلك؛ كفَّ بعضُهم عن بعضٍ. فلا علاج لهذا إلا بالدين، فإذا فقدوا الدين جاءت الكوارث، وجاء البلاء -نسأل الله السلامة-.","link":"https://binbaz.org.sa/fatwas/21566/ما-علاج-غربة-الاسلام-وما-يقع-من-فتن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/غربة الإسلام وعلاجها.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1492,"question":"أُتي برجلٍ شرب الخمر (كيف التعامل معه)؟","title":"كيف يكون التعامل مع شارب الخمر؟","answer":"الجواب:\nكذلك حديث شرب الخمر: إذا شرب يُنصح ويُوضّح ويُوجّه للخير، وألا يعود.  ولا يُلْعَن، ولا يُسبّ، لا يُعان عليه الشيطان، وليقال: هداه الله، اللهم أصلحه، اللهم اهده، اللهم مُنَّ عليه بالتوبة، المسلم أخو المسلم يُحب له الخير، ولما قيل: يا رسول الله، إنَّ دوسًا قد عصت وأبت أن تُسْلِم، قال: اللهم اهدِ دوسًا وائتِ بهم، فالإنسان يدعو لأخيه بالخير، ويدعو له بالتوبة النصوح، ولا يفضحه، ولا يسبه. وإنما سبَّ النبيُّ ﷺ أناسًا أعلنوا شرَّهم على المسلمين: كأبي جهلٍ وجماعةٍ، وكان يقنت في الدعاء عليهم، فإذا ظهر شرُّهم على المسلمين دُعِيَ عليهم.","link":"https://binbaz.org.sa/fatwas/21590/كيف-يكون-التعامل-مع-شارب-الخمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التعامل مع شارب الخمر.mp3","categories":["الدعوة والدعاة","نصائح وتوجيهات"]},{"id":1588,"question":"إنكار المنكر: رجلٌ في سيارةٍ يمرُّ على ناسٍ يُدَخِّنون ويُنكر عليهم وهو ماشٍ؟","title":"كيفية إنكار المنكر ممن رآه أثناء قيادة سيارته","answer":"الجواب:\nجزاه الله خيرًا، يقول: ترى هذا ما يجوز، ترى هذا مُحَرَّم.\nس: لا يؤشِّر لهم؟\nج: لا، يُنبههم ويُوضِّح الأمر، فيقف عليهم ويقول: يا إخواني، ترى هذا ما يجوز، ترى أنَّ الدخان محرَّم، مثلما يقول لهم: الغيبة محرمة، ومثلما يقول لهم: الخمر محرَّم، فيُبَيِّن لهم، ما هو خاطفٌ، لا بدّ أن يثبت ويقف ويُلاحظهم ويُعلِّمهم.","link":"https://binbaz.org.sa/fatwas/21691/كيفية-انكار-المنكر-ممن-راه-اثناء-قيادة-سيارته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإنكار على من يأتي منكرا.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1600,"question":"كيف يدعو الرجلُ والديه؟","title":"كيف يدعو الرجل والديه إن كانا عاصيين؟","answer":"الجواب:\nيا أبتي، يا أماه، يا أبا عبدالله، يا أبا فلان، يا أبتاه، يا أماه، يا أم عبدالله، يا أم محمد.\nس: أبواه عاصيان ويريد دعوتهما للهداية؟\nج: يقول: اتَّقِ الله، افعل كذا، دعْ عنك كذا، وينصح: يا أبتِ إن هذا لا يجوز، مثلما قال إبراهيمُ، فينصح والديه: يا أبتِ افعل كذا، يا أبتِ دَعْ عنك كذا، يا أبتِ حافظ على الصَّلوات، فالصلاة عمود الدين، يا أبتِ احذر الدخان، احذر المُسْكِر، احذر الإسبال، فكلّ هذه محرَّمات، وما أشبه ذلك.\nس: يزعل؟\nج: ولو زعل، لكن بالعبارات الحسنة وباللّطف، قُلْ لهما قولًا لينًا.","link":"https://binbaz.org.sa/fatwas/21704/كيف-يدعو-الرجل-والديه-ان-كانا-عاصيين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيف يدعو الرجل والديه إن كانا عاصيين.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1627,"question":"مَن له رَحِمٌ ويستغيث بالقبور هل يزوره؟","title":"ما حكم صلة وزيارة مَن يستغيث بالقبور؟","answer":"الجواب:\nإذا كان في وقت أمانٍ وليس بيننا وبينهم حربٌ؛ يُعلِّمه الدِّين وينصحه.\nس: رجل مسلم يزور القبورَ له رَحِم؟\nج: ينصحه، لا يتَّخذه صاحبًا، ينصحه ويُعلِّمه الدين.","link":"https://binbaz.org.sa/fatwas/21732/ما-حكم-صلة-وزيارة-من-يستغيث-بالقبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم صلة من يستغيث بالقبور.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1771,"question":"المعاصي المنتشرة مثل: شرب الدخان، لو يهجر الناس لهذه المعصية؟","title":"حكم هجران من يشرب الدخان ونحوه","answer":"الجواب:\nلا، هذه فيها شبهة، الدخان فيه شبهة، لكن يُنصح من باب النصيحة. أما المعاصي الظاهرة :كشرب الخمر، الزنا، اللواط، الشيء الظاهر الذي ما فيه شبهة؛ يُهجر، وإذا رأى المصلحة في عدم الهجر وأنه يتابع النصيحة فلا بأس، فالنبي ﷺ هجر أقوامًا ولم يهجر أقوامًا، فإذا رأى وليُّ الأمر أو طالبُ العلم أو المؤمنُ أنَّ الهجر يزيد الشرَّ لا يهجر، يستمر في النصيحة، ويُحْمَل ما فعله النبيُّ ﷺ على هذا، فالناس الذين تركهم ولم يهجرهم كان ذلك لأنه رأى أنَّ عدم هجرهم أقرب إلى الخير، فإذا كان الهجر ينفع ويُؤَدِّب ويحصل به المطلوب هجر، فعليه أن يُراعي المصالح والمفاسد، ما هو بالهوى.","link":"https://binbaz.org.sa/fatwas/21878/حكم-هجران-من-يشرب-الدخان-ونحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم هجران من يجاهر بالدخان ونحوه.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1866,"question":"مؤاكلة صاحب المنكر ومُشاربته والاستمرار في ذلك مع الاستمرار في الإنكار عليه؟","title":"ضابط مجالسة صاحب المنكر مع الإنكار عليه","answer":"الجواب:\nلا، الواجب على الأقل هجره؛ لأنك إذا واكلته وشاربته ضعف الإنكار، وتساهل معك، ولم يُبالِ؛ لكن مع الإنكار: تَرْك المجالسة.\nس: وإذا كان الإنكارُ في مجلسه دائمًا؟\nج: الإنسان إذا أنكر المنكر لا يكون جليسًا لصاحبه ولا أكيلًا له، أما المجلس العام فلا يضر، في المجلس العام إذا أنكرت المنكر ما يضرك.\nس: إذن الهجر أوْلى؟\nج: إذا اقتضت المصلحة ذلك، وإذا كانت المصلحة تقتضي متابعة الدعوة تُتابع، لكن لا تكون جليسًا له، تتابع الدعوة والإنكار؛ لعل الله ينفع بذلك.\nس: إذن يكون هجرُ العباد لكل حالةٍ بحسبها؟\nج: نعم، بحسب المصلحة الشرعية.\nس: إذا كان في بيتٍ واحدٍ والأب لا ينكر الإنكار المطلوب، مثلًا: مجموعة إخوان بعضهم صالحون؟\nج: الصالح يُنكر على الطالح ولو ما أنكر الأب، الأخ الطيب ينكر على أخيه الذي باشر المعصية، يُنكر عليه ويُوجِّهه إلى الخير.\nس: ولكن بعض الصالحين يستطيعون الانفراد ببيتٍ مستقلٍّ وآخرين لا يستطيعون؟\nج: يُنكر حسب طاقته، ولو بقي في البيت، إذا رأى المصلحة في ذلك.","link":"https://binbaz.org.sa/fatwas/21975/ضابط-مجالسة-صاحب-المنكر-مع-الانكار-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مؤاكلة ومُشاربته صاحب المنكر مع الإنكار عليه.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1870,"question":"كيف يكون الإنكار باللسان؟","title":"كيف يكون الإنكار باللسان واليد؟","answer":"الجواب:\nالإنكار باللسان تقول: اتَّقِ الله، هذا لا يجوز، راقب الله، هذا الإنكار باللسان. وباليد: إذا كانت \"ملاهي\" تكسرها، صورة تكسرها، اجتماع على باطلٍ تُفرِّقه إذا كنت تقدر، مثل صاحب البيت، ومثل رجل الحسبة، ومثل الأمير، فهؤلاء لهم قدرة.","link":"https://binbaz.org.sa/fatwas/21979/كيف-يكون-الانكار-باللسان-واليد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإنكار باللسان كيف يكون.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1872,"question":"إذا أنكر بقلبه ولم ينكر بلسانه ولا بيده، هل يكون بريئًا من الإثم؟","title":"هل يكفي الإنكار بالقلب عن اللسان واليد؟","answer":"الجواب:\nإذا كان عاجزًا عن اليد واللسان بَرِئ، أما إذا كان يقدر ما يبرأ.","link":"https://binbaz.org.sa/fatwas/21981/هل-يكفي-الانكار-بالقلب-عن-اللسان-واليد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يبرأ من أنكر بقلبه ولم ينكر بلسانه ولا بيده.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1874,"question":"كثر حُلَّاق اللحى يمنةً ويسرةً، فهل يُنكر على كلِّ حالق لحيةٍ، أم كل بحسبه؟","title":"كيف يكون الإنكار في حال تفشي المنكر؟","answer":"الجواب:\nأما سمعت الحديث: مَن رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه؟ كل بحسب طاقته، الأمير له شأن، والعالم له شأن، وربّ البيت له شأن، والجيران فيما بينهم لهم شأن، كل على حسب طاقته.","link":"https://binbaz.org.sa/fatwas/21983/كيف-يكون-الانكار-في-حال-تفشي-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإنكار في حال تفشي المنكر.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1878,"question":"ما الفرق بين الدعوة إلى الله والأمر بالمعروف والنهي عن المنكر؟","title":"ما الفرق بين الدعوة والأمر بالمعروف؟","answer":"الجواب:\nكلها دعوة إلى الخير، والأمر بالمعروف والنهي عن المنكر فيه إلزام، وهو أشد وأقوى.","link":"https://binbaz.org.sa/fatwas/21987/ما-الفرق-بين-الدعوة-والامر-بالمعروف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين الدعوة إلى الله والأمر بالمعروف والنهي عن المنكر.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1879,"question":"بالنسبة للكتيب أو الشريط هل يقوم مقام النصيحة المباشرة؟","title":"هل يقوم الكتيب والشريط مقام النصيحة؟","answer":"الجواب:\nنعم، الشريط الطيب ينفع الله به، إذا وزَّعه على الناس من أهل العلم المأمونين، طيب، هذه نصيحة.","link":"https://binbaz.org.sa/fatwas/21988/هل-يقوم-الكتيب-والشريط-مقام-النصيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعدد أساليب الدعوة إلى الله.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1880,"question":"إنكار المنكرات المُعلنة هل يُشترط فيه الإسرار كما يُشترط في النصيحة، أم أنَّ المنكر المُعْلَن يُنكر علنًا دون إسرار؟","title":"ما كيفية إنكار المنكرات العامة المُعْلَنة؟","answer":"الجواب:\nإذا كان بين الناس يُنْكَر علنًا، أما بينك وبين صاحبه الذي كان منه تتكلَّم بينك وبينه، تنصحه، أما إذا فعله عند الناس فيُبَيَّن عند الناس أنَّ هذا منكر ولا يجوز، حتى لا يغتَرَّ به أحدٌ، أما إذا رأيتَه يفعل المنكر فعليك أن تنصحه بينك وبينه، إذا رأيته وحده تقول له: يا عبدالله، هذا منكر. ونحو هذا الكلام الطيب، والأسلوب الحسن، والرفق، كما قال ربك: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]، لكن إذا كان يفعله عند الناس تُبين له أنَّ هذا منكر، وأنه لا يجوز هذا العمل، مثل: مَن يشرب الدخانَ عند الناس، ومَن يشرب الخمر عند الناس، سبَّاب، لعَّان، يُنكر علنًا.\nس: المقصود المنكرات العامة المُعْلَنة، هل تُنكر علنًا؟\nج: نعم تُنكر علنًا، ما دامت مُعلنةً تُنكر علنًا.\nس: ما يُشترط فيها الإسرار؟\nج: يبين للناس أنها مُنكرة، الذي يُجاهر في الأسواق بالمنكرات يُنكر عليه.","link":"https://binbaz.org.sa/fatwas/21989/ما-كيفية-انكار-المنكرات-العامة-المعلنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيفية إنكار المنكرات العامة المعلنة.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1882,"question":"هل هذا (الأمر بالمعروف والنهي عن المنكر) يدخل في أنواع الدعوة إلى الله؟","title":"هل الأمر بالمعروف من الدعوة إلى الله؟","answer":"الجواب:\nلا شكَّ أنَّ من الدعوة إلى الله: الأمر بالمعروف والنهي عن المنكر، فعطفها في قوله جل وعلا: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ .. [آل عمران:104] هذا من عطف الخاص على العام، فالذي يدعو إلى الله، أو يأمر بالمعروف، أو ينهى عن المنكر، ثم يخالف قوله ما يدعو إليه داخل في هذا الوعيد -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21991/هل-الامر-بالمعروف-من-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الأمر بالمعروف والنهي عن المنكر من أنواع الدعوة إلى الله.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":1883,"question":"أيّهما أخفّ: ترك الإنكار على النفس والإنكار على الناس، أم الإنكار على الناس وعدم الإنكار على النفس؟","title":"كيف يكون الإنكار على النفس وعلى الناس؟","answer":"الجواب:\nيجب على المؤمن إنكار المنكر على نفسه وعلى غيره، إذا رأى المنكر يُجاهد نفسه حتى يدع المنكر، ويجاهد غيره في ترك المنكر، يعني: يكون نشيطًا في محاربة المنكر من جهة نفسه حتى يستقيم على الحقِّ، ومن جهة دعوة الناس إلى الخير وإرشادهم وأمرهم بالمعروف ونهيهم عن المنكر، يجمع بين الأمرين.\nس: إذا علم من نفسه نَتَنَها وخُبْثَها وأنه إذا أنكر على الناس لم يُنكر على نفسه؟\nج: يجاهد نفسه، عليه المجاهدة: وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا [العنكبوت:69]، وَلَنَبْلُوَنَّكُمْ حَتَّى نَعْلَمَ الْمُجَاهِدِينَ مِنْكُمْ .. [محمد:31]، لا بدّ من مجاهدة النفس حتى تلتزم أمر الله.\nس: يأمر بالمعروف ثم لا يأمر الناس بصلاة الفجر ويترك صلاة الفجر؟\nج: الباب واحد، أو يأمر الناس بالبعد عن الخمر ويشرب الخمر، أو ينهى الناس عن التدخين ويدخن، أو ينهى الناس عن حلق اللحى ويحلق، الباب واحد، هذا منكر واحد، وفضيحة عليه -نسأل الله العافية- وتشبُّه بأعداء الله من اليهود وأشباههم.\nس: يُجاهد نفسه في تقصيره مع أنه مُقصِّرٌ ويأمر الناس؟\nج: يأمر الناس ولو قصَّر، ويستحي ويجاهد نفسه لعله لا يبرز بشيءٍ منكر، ولا يقل: أنا لا آمر ولا أنهى لأن عندي معصية. لا، يأمر وينهى ولو عنده معصية، ويجاهد نفسه؛ لعل الله يتوب عليه.","link":"https://binbaz.org.sa/fatwas/21992/كيف-يكون-الانكار-على-النفس-وعلى-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في إنكار المنكر على النفس وعلى الناس.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2102,"question":"رجل شُكِيَ أمرُه إلى الهيئة بعد أن دُعي باللين فبعدها أرسل أهله إلى الدَّاعي وقال: إن رفعت الدَّعوى أو الشكوى إلى الهيئة فسترى بماذا يُعاقب. فهل هذا يُترك لأنَّ المنكر سيَؤُول إلى منكرٍ أم يُستمر في الإنكار عليه؟","title":"هل يترك الإنكار على مَن يُخشى أذاه؟","answer":"الجواب:\nلا، يُنصح، عليه النصيحة مع الجماعة جيرانهم، فالجيران لا يسكتون عن حاله، فيتعاونون على نصيحته وتوجيهه إلى الخير حتى لا تقع فتنة..... على كل حال، إذا كان يخشى أو يظن أنه قد يفعل؛ يسقط عنه الواجب، لكن في مثل هذا يكون من جماعةٍ أحسن، لعله ينتبه، ولعله يستفيد، فإذا كان من جماعة فهو أقرب إلى النّجاح.","link":"https://binbaz.org.sa/fatwas/22220/هل-يترك-الانكار-على-من-يخشى-اذاه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا أدى إنكار المنكر إلى منكر أشد.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2208,"question":"إذا لم يكن يعرف حال الجيران هل يعتزلهم ثم يدرس أحوالهم قبل مُخالطتهم؟","title":"حكم مخالطة الجيران إذا لم يُعرف حالهم","answer":"الجواب:\nيدرس أحوال المجتمع وينظر في المصلحة، فإذا اقتضت المصلحةُ وعظهم وتذكيرهم ومخالطتهم فعل ذلك، وإذا رأى أنَّ المصلحة تقتضي اعتزالهم اعتزلهم، فعليه أن ينظر إلى الأمر الذي وقع بالناس، فالناس في حاجةٍ إلى التّوجيه والإرشاد والتعليم، والأمر بالمعروف والنّهي عن المنكر، لكن إذا لم يكن في المسألة حيلة فليعتزل.","link":"https://binbaz.org.sa/fatwas/22331/حكم-مخالطة-الجيران-اذا-لم-يعرف-حالهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مخالطة الجيران إذا لم يكن يعرف حالهم.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2217,"question":"المُتَكَبِّر كيف يتواضع معه المُتواضع؟","title":"كيف يكون التعامل مع المُتَكَبِّر؟","answer":"الجواب:\nيُجاهد نفسه في التّواضع.\nس: أقصد: كيف يتعامل المُتواضع مع المُتكبر؟\nج: ينصحه ويُوجهه إلى الخير.\nس: لكن يستمر في تواضعه حتى مع المُتكبر؟\nج: نعم، مع كلِّ أحدٍ، وينصحه.\nس: بعض الناس إذا نصحته قال: عليك بنفسك؟\nج: ولو، قل له: عليَّ بنفسي، وعليَّ بك، أنا مأمورٌ بك، فالله جلَّ وعلا يقول: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]، فأنا مسؤولٌ عنك.","link":"https://binbaz.org.sa/fatwas/22340/كيف-يكون-التعامل-مع-المتكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التعامل مع المتكبر.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2261,"question":"كيف يكون الجمعُ بين أن يرى منكرًا فينتقم لله ، وأن يُنْكِر بالحكمة واللّين والموعظة الحسنة؟","title":"كيف يُجمع بين الرفق وبين الانتقام لله تعالى؟","answer":"الجواب:\nيُنكر بالحكمة، وهذا من الغضب لله: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]، لا يسكت، أما إذا كان في حقِّ نفسه فلا بأس أن يُسامح ويسكت.","link":"https://binbaz.org.sa/fatwas/22384/كيف-يجمع-بين-الرفق-وبين-الانتقام-لله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع بين الانتقام لله وإنكار المنكر بالحكمة واللين.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2288,"question":"مَن قال: \"إنَّ أشرف وظيفةٍ على وجه الأرض هي وظيفة الرسل، وهي الدَّعوة إلى الله، وليست المراتب وغيرها\"، فهل يُعتبر هذا من إهانة الأمير؟","title":"هل اعتبار الدعوة أشرف وظيفة إهانة للأمير؟","answer":"الجواب:\nلا، ليست إهانةً، فدعوة الرسل لا شكَّ أنها مهمةٌ جدًّا عن الأمراء والعلماء، ودعوة الرسل واجبةٌ على الأمراء والعلماء جميعًا، فهي واجب الجميع.","link":"https://binbaz.org.sa/fatwas/22411/هل-اعتبار-الدعوة-اشرف-وظيفة-اهانة-للامير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أشرف وظيفة وظيفة الرسل الدعوة إلى الله فهل يُعتبر هذا من إهانة الأمير.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2333,"question":"إذا فرح الإنسانُ ببَلْوَى تُصيب مسلمًا بقضاء الله؛ لأنَّه شديد الأذى والتَّمرد والمعاصي؟","title":"حكم الفرح بالبلاء يصيب مسلمًا شديد الأذى","answer":"الجواب:\nهذا ينصح له، ويُوجِّهه إلى الخير، يقول له: اتَّقِ الله، يقول الله: وَالْعَصْرِ ۝ إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر]، ويقول النبيُّ ﷺ: الدين النَّصيحة، فإذا علم من أخيه نَقْصًا نصحه ووجَّهه إلى الخير بالأسلوب الحسن.\nس: إذا كان يرفض كلَّ أنواع النَّصيحة؟\nج: ولو، هذا الذي عليك: النصيحة، فإن قَبِلَ وإلا فقد أدَّيْتَ ما عليك.\nس: وإذا كان يستخدم هذه النّعم في الشر والمعاصي؟\nج: تدعو له بالهداية.","link":"https://binbaz.org.sa/fatwas/22457/حكم-الفرح-بالبلاء-يصيب-مسلما-شديد-الاذى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرح ببلاء أصاب مسلما شديد الأذى والتَّمرد والمعاصي.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2518,"question":"مَنْ له جيران لا يصلون إلا في رمضان؟","title":"ما يفعل مَنْ له جيران لا يصلون إلا برمضان؟","answer":"الجواب: إذا كان له جيران لا يصلون إلا في رمضان أو في بعض الأوقات يُنكر عليهم ويعلّمهم وينصحهم، فإن أبوا يرفع بأمرهم إلى الجهات المختصة –الهيئة- حتى تقوم بالواجب، لكن بعد النصيحة. وإذا تيسر يذهب إليهم مع بعض إخوانه؛ لأن الواحد قد لا يبالون بذلك، إذا كانوا جماعة اثنين ثلاثة يجتمعون ويذهبون وينصحون، قد يكون يعني عملهم أشد أثرًا وأنفع، فيشوف بعض إخوانه يذهب إليهم ينصحهم يوجّههم يخوّفهم من الله حتى يصلوا مع الناس لقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر، وقوله ﷺ للأعمى لما استأذنه قال ليس له قائد يقوده إلى المسجد، فهل له من رخصة يصلي في بيته؟ فقال النبي ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم: قال: فأجب فالواجب على من يسمع النداء أن يجيب، وأن يحضر مع المصلين ويصلي في المسجد مع الناس، ولا يجوز التخلف عن ذلك ولا التشبُّه بأعداء الله المنافقين، لكن من فعل ذلك فقد أعلن المعصية، فلا بدّ ترفع بأمرهم إذا لم تنفع النصيحة، والله يصلح أحوال المسلمين جميعًا.","link":"https://binbaz.org.sa/fatwas/22648/ما-يفعل-من-له-جيران-لا-يصلون-الا-برمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/جيرانه لا يصلون إلا في رمضان.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2545,"question":"إنكار القلب هل يمنع حدوث العقاب العام؟","title":"هل يمنع إنكار القلب حدوث العقاب العام؟","answer":"الجواب: ما يكفي، لا بدّ من إنكاره بالفعل والقول مع القدرة، أما الذي ما يقدر يكفيه القلب.\nس: هذا يمنع العقوبة؟\nالشيخ: عنه هو، العقوبة عنه هو، يعني ما يُعاقب يوم القيامة، لكن تَعُمُّه العقوبات العامة.\nس: الذي يستطيع يغيّر بلسانه وغيّر بقلبه، لو عُذّب هل يشمله العذاب؟\nالشيخ: قد تَعُمُّه العقوبات ويُبعثون على نيّاتهم وعلى أعمالهم الطيبة.\nس: لكن لو كان يستطيع يغيّر هذا المنكر بلسانه؟\nالشيخ: يستحق العقاب، إذا لم يفعل يستحق، نسأل الله العافية.\nس:... الإنكار العلني، القلب ما يكفي؟\nالشيخ: نعم.\nس: القلب ما يكفي؟\nالشيخ: لا، القلب حَدُّه بس النجاة إذا كان عاجزًا.","link":"https://binbaz.org.sa/fatwas/22676/هل-يمنع-انكار-القلب-حدوث-العقاب-العام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يمنع إنكار القلب حدوث العقاب العام.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2690,"question":"إذا كان أحدُ المسلمين أخوه في الله أو قريبه يتهجم عليه دائمًا ويسبُّه ويغلط عليه بدون سبب، فكلما قاطعه ورجع إليه تكرر منه هذا، فهل يستمر في المقاطعة إنْ لم يُجْدِ معه الطِّيب؟","title":"حكم قطيعة القريب المؤذي بعد نصحه","answer":"الجواب: إن تيسرت النصيحة فهو أوْلى، يناصحه لعل الله يهديه، فإذا كان الاتصال به يفضي إلى شر؛ فلا يتصل به والحمد لله، إذا كان رجلًا لئيمًا فاسقًا لا يبالي ولا ينفع معه النصيحة؛ يقطع، الحمد لله، أقل أحواله السُّنِّية.\nس: ولا يعتبر من الشحناء؟\nالشيخ: لا لا، ما فيه شيء، هو الظالم.","link":"https://binbaz.org.sa/fatwas/22829/حكم-قطيعة-القريب-الموذي-بعد-نصحه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قريبه يؤذيه فقاطعه فنصحه فزاد في إيذائه ولم يجدِ معه الطيب.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2750,"question":"رجل أندنوسي يريد الدخول في الإسلام هل يَجِدُّ الأخوة في إدخاله في الإسلام وإنهاء إجراءاته أم يتثبتون من حاله؟","title":"هل يجب التَّحقق من قصد من أراد أن يُسْلِم؟","answer":"الجواب: ينبغي أن يُسارع في مساعدته وتشويقه للإسلام وترغيبه وتسهيل أمره من باب التعاون على البر والتقوى.\nس: ولا يفتش عن النوايا؟\nالشيخ: لا، أمره إلى الله، ينبغي أن يُحمل على أحسن المحامل؛ تشجيعًا للدخول في الإسلام.","link":"https://binbaz.org.sa/fatwas/22898/هل-يجب-التحقق-من-قصد-من-اراد-ان-يسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أراد الدخول في الإسلام فهل يحمل على أحسن المحامل أو يتثبت.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2772,"question":"ضابط إظهار الدين أن إذا قابل من أهل تلك البلاد يقول: أنتم كفار؟","title":"كيف يكون إظهار الدين في بلاد الكفار؟","answer":"الجواب: إظهار الدين: كونه يصلي ويصوم ويدعو إلى الله ويأمر بالمعروف ويعلم الناس الخير، يعلم الناس التوحيد، ويعلم الناس الشرك، وما هو بلزوم يقول للناس: أنتم كفار، يدعو إلى الله وبس ويكفي، هذا إظهار الدين.","link":"https://binbaz.org.sa/fatwas/22920/كيف-يكون-اظهار-الدين-في-بلاد-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ضابط إظهار الدين في بلاد الكفار.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2813,"question":"بعض أشرطة الدعاة مؤثرة وكانت سببًا في هداية عدد كبير بعد سماعهم الشريط، هل يشترك في الأجر موزع الشريط ومحل التسجيلات كمثل الذين يدخلون بالسهم الواحد الجنة؟","title":"مَنْ يدخل في أجر الشريط والوسائل الدعوية؟","answer":"الجواب: الأقرب -والله أعلم- أن صاحب الشريط على أجره، والذي يوزعه على الناس له أجره، كلهم دعاة خير، إذا كان شريطًا صالحًا مفيدًا، فصاحبه على أجر والموزع له مثل الذي ينشر الكتب وينقل المحاضرات إلى الناس، يكتبها ويوزعها على الناس، شركاء في الأجر.","link":"https://binbaz.org.sa/fatwas/22962/من-يدخل-في-اجر-الشريط-والوساىل-الدعوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من كانت هدايته بسبب بعض أشرطة الدعاة المؤثرة فهل يحصل الأجر.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2815,"question":"لكن يكون جُلُّ وقته للعلم إذا كان داعية؟","title":"هل يكون جُلُّ وقت الداعية للعلم؟","answer":"الجواب: حسب التيسير فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] قد يكون عنده حاجة ما عنده مَن يقوم بها، عنده حاجة إلى ما ينفقه على أهله، يكون له وقت للعلم والدعوة والتوجيه، ووقت لطلب الرزق. وطلب الرزق لا يمنع من الدعوة؛ مع البائع ومع المشتري ومع صاحب الدكان، ومع من يمر به ومع من يقف معه، إلى غير ذلك، طلب العلم الحمد لله متيسّر في أي مكان.","link":"https://binbaz.org.sa/fatwas/22964/هل-يكون-جل-وقت-الداعية-للعلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يكون جل وقت الداعية للعلم.mp3","categories":["العالم والمتعلم","الدعوة والدعاة"]},{"id":2816,"question":"الدعوة تكون للأقرب فالأقرب؟","title":"هل تجب الدعوة للأقرب فالأقرب أو عامة؟","answer":"الجواب: مع الأقرب، ومع غيرهم، لكن إذا بدأ بالأقرب هذا من أهم المهمات، لكن لا يمنعه هذا من كونه لا يدعو إلى الله ولو الأبعدين إذا انتهز الفرصة، إذا تيسّر له أن يدعو.","link":"https://binbaz.org.sa/fatwas/22965/هل-تجب-الدعوة-للاقرب-فالاقرب-او-عامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تكون الدعوة للأقرب فالأقرب أو عامة.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":2845,"question":"الآمرون بالمعروف والناهون عن المنكر يعتبرون من المجاهدين؟","title":"هل يُعَدُّ الآمرون بالمعروف مِن المجاهدين؟","answer":"الجواب: ما في شك؛ جِهادٌ عظيم.","link":"https://binbaz.org.sa/fatwas/22998/هل-يعد-الامرون-بالمعروف-من-المجاهدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يعتبر الآمر بالمعروف والناهي عن المنكر مجاهدا.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":3062,"question":"إذا كان منكر يمكن تغييره: كثير من الناس يترك المنكر يقول: أنا ما أبلّغ عن فلان؟","title":"ما حكم تبيلغ ولي الأمر بالمنكر لتغييره؟","answer":"الجواب: إذا كان يستطيع يجب عليه، إذا كان يستطيع تغيير المنكر يجب عليه: لإمرته. أو لأنه هيئة. أو لأنه صاحب البيت.  أو ما أشبه ذلك.","link":"https://binbaz.org.sa/fatwas/23222/ما-حكم-تبيلغ-ولي-الامر-بالمنكر-لتغييره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يبلغ ولي الأمر بالمنكر الذي يمكن تغييره.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":3147,"question":"داعية يتكلم في الدعوة يقول: اجعل الله هو الأول في حياتك، انشغلوا مع الله، اجعل الله هو الأول في اهتماماتك وفي أفكارك، هل عباراته صحيحة؟","title":"حكم التعبيرات المُوهِمة والمُلْتَبِسة في الوعظ","answer":"الجواب: يعني مراقبة الله، يُعَبّر بأحسن، يقول: مراقبة الله والحذر من غضبه، اجعل مراقبة الله، يعني يُصَرّح.\nس: انشغلوا مع الله، ما فيه شيء يا شيخ؟\nالشيخ: المعنى واضح، يعني: بطاعته، وتَرْك معصيته.\nس: جائز اللفظ؟\nالشيخ: ما أعلم فيه شيء، لكن كونه يُوضّح أكثر أحسن، كونه يُبيّن: راقبوا الله، احذروا غضب الله، احذروا معاصيه، يُبيّن أكثر، يُبيّن أوْضَح.","link":"https://binbaz.org.sa/fatwas/23309/حكم-التعبيرات-الموهمة-والملتبسة-في-الوعظ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قول اجعل الله هو الأول في اهتماماتك وفي أفكارك ونحوه.mp3","categories":["الدعوة والدعاة","مسائل متفرقة في العقيدة"]},{"id":3283,"question":"بالنسبة للكفّار الذين يكونون في بلاد المسلمين: مدى إظهار العزة في مقابلهم، هل هو العبوسُ في وجوههم؟","title":"هل مِنْ عِزة المؤمن العبوسُ في وجه الكفّار؟","answer":"الجواب: لا، لا.\nس: أوْ لهم حكم المُسْتأمنين؟\nالشيخ: تَضطرُّهم إلى أضيق الطريق ولا تبدأهم بالسلام بس، هذا يكفي، وإن بدؤوا رددت عليهم.\nس: هل يُعَبِّس في وجوههم؟\nالشيخ: لا، لا يُعَبِّس في وجوههم ولا يُغَيِّر شيئًا، يدعوهم إلى الله، دعوتهم إلى الله من باب الخير، لكن لا يبدأهم، وإذا رأى أن يبدأهم: كيف حالك؟ كيف أنت يا فلان؟ كيف أولادك؟ لعلهم يقبلون إلى الخير ؛ طيب.\nس: لكن مَنْ عُرِف منه الصُّدود؟\nالشيخ: الذي عرف منه الصدود يُنصح فلا يصير خيرًا منك، أنت صِرْ خيرًا منه بالدعوة إلى الله والتوجيه إلى الخير والنصيحة، فأنت على أجر.","link":"https://binbaz.org.sa/fatwas/23447/هل-من-عزة-المومن-العبوس-في-وجه-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من إظهار عزة المؤمن أمام الكفار العبوس في وجوههم.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":3285,"question":"هل من التَّسَتُّر مثلًا إذا رأيت شخصًا يفعل منكرًا ألا تُفَضِّح أمره، أي تسكت عنه؟","title":"متى يُشرع السِّتر أو الكشف عمّن أتى منكرًا؟","answer":"الجواب: إذا كان في صلة خاصة سرية يُسْتَر عليه ويُنْصَح.  أما إذا كان بين الناس فهو الذي فضح نفسه.  أما إذا كان دخلت عليه في بيته أو في محل خاص ورأيته؛ تَسْتُر عليه وتنصحه.","link":"https://binbaz.org.sa/fatwas/23449/متى-يشرع-الستر-او-الكشف-عمن-اتى-منكرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من التستر عدم فضح أمر العاصي.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":3308,"question":"بعض الناس إذا مَرَّ بحَلِيق أو مدخّن لم يسلّم عليه؟","title":"حكم السلام على العصاة والجلوس معهم","answer":"الجواب: المشروع أنه يسلّم ويعلّمه وينصحه ويوجهه إلى الخير، ويعلمه ما جَهِل. س: يعني ما يمنع أنه يسلّم...؟ الشيخ: يسلم، وينصحه من عرفت ومن لم تعرف، يقول: يا أخي ترى هذا ما يجوز، والواجب عليك إعفاء اللحية، الواجب عليك ترك التدخين، ترك شرب المسكر. س: كثرة يا شيخ.. يتيسر له الوقفة مع كل واحد؟ الشيخ: حسب الطاقة، حسب الطاقة. س: لكن السلام؟ الشيخ: الظاهر يسلّم، ولَوْ من عرفت ومن لم تعرف؛ عموم، لأنه قد يكون جاهلًا ما قام عليه الحجة. س: لكن يأثم لو جلس معهم من دون نصح؟ الشيخ: هو الذي يظهر، إذا كان جالس أهل المنكر ولم يَنْهَهُم شريكٌ لهم، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/23474/حكم-السلام-على-العصاة-والجلوس-معهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السلام على العاصي والجلوس معه.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":3537,"question":"بعض الإخوان في الهيئات يقولون: نُشْغَل بإخراج الرجال من السوق حتى تُصلى الجماعة الأصلية، ولو جلسنا نصلي مع الجماعة لبقي السوق مليئًا بالناس، فهل لنا عذر بتأخير الصلاة؟","title":"حكم التأخرعن الجماعة لإخراج الناس للصلاة","answer":"الجواب: معذورون نعم، عليهم أن يقيموا الناس للجماعة ولو فاتتهم الجماعة؛ لأن النبي ﷺ قال: لقد هممت أن آمر بالصلاة فتقام، ثم آمر رجلاً فيؤم الناس..  ثم ينطلق والناس في الصلاة ليهجم عليهم حتى لا يقولوا: صلينا.","link":"https://binbaz.org.sa/fatwas/23719/حكم-التاخرعن-الجماعة-لاخراج-الناس-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يعذر من ترك الجماعة لانشغاله بإخراج الرجال من السوق حتى تصلى الجماعة.mp3","categories":["الدعوة والدعاة","صلاة الجماعة"]},{"id":3921,"question":"إذا كان الإنسان بسبب الأمر بالمعروف والنهي عن المنكر يسبون والديه؟","title":"حكم مَنْ يؤدي أمرُه بالمعروف لسبِّ والديه","answer":"الجواب: ما يضر، الأمر بالمعروف والنهي عن المنكر ولو سبوا، الإثم عليهم.","link":"https://binbaz.org.sa/fatwas/24139/حكم-من-يودي-امره-بالمعروف-لسب-والديه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل تتعلق بحديث إنّ من أكبر الكبائر أن يلعن الرجل والديه..mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":3959,"question":"إذا كان الجار كافرًا لا يصلي؟","title":"هل يُكرم الجار إذا كان لا يصلي؟","answer":"الجواب: ولو، لا يُؤذى، يُدعى إلى الله، ويوجه إلى الخير، ولكن لا يؤذى ما دام أنه في عهد وأمان.\nس: وُجه إلى الخير وأصبح يهزأ بالدين ويسب ويلعن؟\nالشيخ: يرفع أمره إلى ولاة الأمور فيعاقبوه بما يستحق، إذا كان يستهزئ بالدين لا يترك، لكن الكلام.... لا يتكلم فيما يتعلق بالدين، له أمان وله عهد؛ لأن الجيران أقسام: جار مسلم له حقان.  وجار مسلم قريب له ثلاثة حقوق: حق الجوار والإسلام والقرابة. وجار كافر له حق واحد وهو حق الجوار.  أما إذا سب الدين أو خرج منه... يُنقض عهده، يُقتل، على ولي الأمر أن يقتله إذا ظهر منه ما يوجب قتله، لكن هذا إذا كان كافًّا أذاه وله عهد وله أمان ومستأمن فيعطى حقه من جهة الإحسان إليه، وهذا من أسباب دخوله في الإسلام إذا أحسن إليه ورأى من المسلمين إكرام الجار؛ كان هذا من أسباب دخوله في الإسلام وتعظيمه للإسلام ورغبته فيه.","link":"https://binbaz.org.sa/fatwas/24184/هل-يكرم-الجار-اذا-كان-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُكرم الجار إذا كان لا يصلي.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":3961,"question":"إذا رأى منكرًا عند المضيف ينصحه؟","title":"ما الحكم لمن رأى منكرًا عند المضيف؟","answer":"الجواب: ينصحه نعم. إذا رأى منكرًا عنده ينصحه، مثل ما نصح سلمان أبا الدرداء.","link":"https://binbaz.org.sa/fatwas/24188/ما-الحكم-لمن-راى-منكرا-عند-المضيف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم إذا رأى منكرًا عند المضيف.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4003,"question":"هل يجوز للمسلمين مخالطة المشركين واليهود؟","title":"هل يجوز للمسلم مخالطة المشركين واليهود؟","answer":"الجواب: إذا كان للمصلحة، للدعوة.","link":"https://binbaz.org.sa/fatwas/24236/هل-يجوز-للمسلم-مخالطة-المشركين-واليهود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز للمسلمين مخالطة المشركين واليهود.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4004,"question":"بعض العصاة إذا نُصح أو أُمر يقول لمن نصحه: عَلّم في المسجد؟","title":"حكم من لم يقبل النصيحة وكيف يُعامل؟","answer":"الجواب: هذا من جنس عمل المنافقين، يُنكَر عليه، ويُعلّم: لا يجوز لك هذا الكلام، الله يقول سبحانه: وَإِذَا قِيلَ لَهُ اتَّقِ اللَّهَ أَخَذَتْهُ الْعِزَّةُ بِالْإِثْمِ فَحَسْبُهُ جَهَنَّمُ وَلَبِئْسَ الْمِهَادُ [البقرة:206] الواجب أنه يقبل الحق، ويقول: جزاك الله خيرًا، إن شاء الله أو أسأل الله أن يعينني، أسأل الله أن يغفر لي أو يوفقني.  هكذا ينبغي لمن وُعظ، ولا يرد بالكلام السيئ، أو يقول خل عنا دينك، أو رح المسجد علم، كل هذا مكابرة ومصادمة للحق، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24237/حكم-من-لم-يقبل-النصيحة-وكيف-يعامل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بعض أساليب العصاة عند النصيحة.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4104,"question":"الجار إذا نُصح ولم يقبل النُّصح، هل يَنقل من المكان هذا إذا استطاع وإلا يصبر عليه؟","title":"هل الأفضل الانتقال عن جار السوء أم الصبر؟","answer":"الجواب: يعمل بالأصلح؛ إن كان في بقائه في محله خيرٌ فيصبر على نصحه، ويُذكّر الناس، ويدعو إلى الله، وإن كان في انتقاله إلى محلٍّ آخر أصلح انتقل.","link":"https://binbaz.org.sa/fatwas/24344/هل-الافضل-الانتقال-عن-جار-السوء-ام-الصبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في التعامل مع جار السوء.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4113,"question":"إذا رؤي الرجل يعمل بعمل أهل النار، ما يفسّق، أو على ظاهره؟","title":"ما حكم مَنْ رؤي يعمل بعمل أهل النار؟","answer":"الجواب: يُنصح، ينصحه ويدعوه إلى الخير؛ الدين النَّصيحة.","link":"https://binbaz.org.sa/fatwas/24355/ما-حكم-من-روي-يعمل-بعمل-اهل-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم إذا رؤي الرجل يعمل بعمل أهل النار.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4193,"question":"إذا كان يذهب إلى المستشفى لزيارة مريض، ويوجود في المستشفى منكر لا يستطيع إنكاره، هل يذهب؟","title":"حكم الذهاب لمكان به منكر لا يستطيع إنكاره","answer":"الجواب: يذهب له، ينكر حسب طاقته.","link":"https://binbaz.org.sa/fatwas/24450/حكم-الذهاب-لمكان-به-منكر-لا-يستطيع-انكاره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إنكار المنكر حسب الطاقة.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4243,"question":"بعض الناس يستعمل طريقة في الدعوة أنه يدعو إلى فضائل الأعمال، ويترك الدعوة إلى التوحيد يقول يفرِّق بين الناس ؟","title":"ما حكم زعم أن الدعوة للتوحيد تفرِّق الناس؟","answer":"الجواب: لا لا، هذا غلط، هذا من جهله. إذا كان يدعو المشركين يبدأ بالتوحيد، أما إذا كان يدعو المسلمين يرغّبهم في الثبات على الحق وعلى طاعة الله ورسوله ﷺ  والحذر من المعاصي؛ لأنهم موحدون. أما إن كان يدعو أهل الشرك يبدأهم بالدعوة إلى التوحيد وترك الشرك، هذه التي بدأ بها النبي ﷺ وأمر الصحابة أن يبدؤوا بها؛ لأن الشرك أعظم الذنوب، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/24510/ما-حكم-زعم-ان-الدعوة-للتوحيد-تفرق-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من الحكمة الدعوة إلى فضائل الأعمال، وترك الدعوة إلى التوحيد.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4245,"question":"إذا علم أن رجلًا عاصٍ في المعاملات لكن يُشك في شركياته؟","title":"كيفية دعوة شخص يُشك في وقوعه بالشرك؟","answer":"الجواب: يعلمون هذا وهذا، ينهونه عن الشرك ويحذرونه من المعاصي كلها، يحذرونه من الشرك والمعاصي جميعها، هذا وهذا، إن كان عندهم معاصٍ ولكن يُشك في إسلامهم يوضح لهم الإسلام والدعوة إلى التوحيد، ويُبيّن لهم أيضًا الحذر من المعاصي.\nس: يستدرج في الحديث معهم؟\nج: هذا وهذا.","link":"https://binbaz.org.sa/fatwas/24513/كيفية-دعوة-شخص-يشك-في-وقوعه-بالشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في دعوة المدعوين.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4266,"question":"جنود النصارى لا يجلس لدعوتهم للإسلام؟","title":"حكم دعوة المشركين للإسلام وهم بمجلس خمر","answer":"الجواب: واليهود كذلك، كلهم يدعون للإسلام، اليهود والنصارى.\nس: أقصد وقت فرغتهم يجلسون على كراسٍ ويدار بينهم الخمر فهل يُدْعَون أو يُتركون؟\nج: إذا كان ما هناك حيلة إلا هذا الوقت يجيئهم، يبين لهم أن الله خلقهم لعبادته، وأن الله أوجب عليهم اتباع محمد ﷺ وهو خاتم الأنبياء، وأن الله حرم عليهم الخمر، وحرم عليهم الزنا، وحرم عليهم كذا، هذا دين الإسلام. المقصود دعوتهم إلى التوحيد أولًا، أول شيء يدعوهم إلى توحيد الله، واتباع محمد ﷺ، ويبين لهم أن من محاسن الإسلام تحريم هذا الشيء المنكر.","link":"https://binbaz.org.sa/fatwas/24536/حكم-دعوة-المشركين-للاسلام-وهم-بمجلس-خمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دعوة المشركين للإسلام، حال دوران بينهم الخمر.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4298,"question":"جلساء السوء إذا كانوا من الإخوة ومعك في منزل واحد، ماذا يكون في مثل هذه الحالة؟","title":"ما يفعل من ابتُلي بجلساء السوء من الأقارب؟","answer":"الجواب: تدعوهم إلى الله، إن كان عندهم شيء من المعاصي أو الشرك تدعوهم إلى الله، ترشدهم، فإن استقاموا وإلا ابتعد عنهم لا يجروك إلى الباطل.\nس: ترحل من المنزل الذي هم فيه؟\nج: إن كنت تخشى على نفسك أن يجروك إلى باطلهم.\nس: حتى الوالد كذلك؟\nج: حتى الوالد.","link":"https://binbaz.org.sa/fatwas/24571/ما-يفعل-من-ابتلي-بجلساء-السوء-من-الاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/جلساء السوء من الأقارب.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4311,"question":"بعض الناس عندما يحضر إلى المقبرة يقومون بالتذكير على الحاضرين؟","title":"هل يُستحب تذكير الحاضرين في المقبرة؟","answer":"الجواب: ما في بأس، التذكير ما يخالف، النبي ﷺ نصح الناس وهو في المقبرة وهو ينتظر الدفن، نصحهم، بحديث علي في الصحيحين وفي حديث البراء بن عازب في السنن، نصح إذا جلسوا ينتظرون نصحهم طيب.\nس: التذكير في المقابر هل هو سنة أو مستحب؟\nج: مستحب لفعل النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/24585/هل-يستحب-تذكير-الحاضرين-في-المقبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تذكير الحاضرين في المقبرة.mp3","categories":["أحكام المقابر","الدعوة والدعاة"]},{"id":4321,"question":"قوله ﷺ: وتبسمك في وجه أخيك صدقة، هل هذا يدل على أنه لا يبتسم في وجه المشرك ولا الكافر؟","title":"حكم التبسم في وجه الكافر للدعوة","answer":"الجواب: المشرك ينبغي فيه الغلظة والكراهة وإظهار البراءة، أما المودة فبين المسلمين والابتسام والتعاون، فهذا بين المسلمين، أما مع الكفار فالكراهة والبغضاء والعداوة إلا عند رجاء المصلحة؛ كونه يؤلف قلوبهم يدعوهم إلى الله، هذا لا بأس.\nس: هل يبتسم في وجهه لدعوته إلى دين الله لا بأس؟\nج: ما في بأس، ما في بأس للدعوة إلى الله إذا رأى مصلحة في ذلك.","link":"https://binbaz.org.sa/fatwas/24596/حكم-التبسم-في-وجه-الكافر-للدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث وتبسمك في وجه أخيك صدقة.. التبسم في وجه الكافر.mp3","categories":["شروح الحديث","الدعوة والدعاة"]},{"id":4345,"question":"بعض الناس تنكر عليهم ويزيد.. مثلاً مطوّل على المسجل يزيد المسجل، إذا صار يدخن يبخ في وجهك؟","title":"بم يُنصح من يتعرض للأذى عند إنكار المنكر؟","answer":"الجواب: تدعو له بالهداية، بعض الناس سفيه لا يزيده الإنكار إلا شرًّا؛ لكن ينبغي للمؤمن أن يكون أعقل منه، يحلم يصبر، ويقول: الله يهديك، الله يعيذك من الشيطان، حتى يكون خيرًا منه.","link":"https://binbaz.org.sa/fatwas/24620/بم-ينصح-من-يتعرض-للاذى-عند-انكار-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التعرض للأذى والسخرية عند إنكار المنكر.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4361,"question":"هل تجب النصيحة في ذلك؟","title":"كيف تكون النصيحة في البُعد عن الرياء؟","answer":"الجواب: إذا كنت تعلم ما في قلبه فانصحه.\nس: الظاهر أنه دائمًا يعني؟\nج: لا. تنصح عمومًا أنه يجب الحذر من الرياء وبس، ولا تقول هذا يرائي، فأنت لا تعلم ما في قلبه. تقول لإخوانك الذين تخشى عليهم: ترى الرياء ما يجوز، والواجب إخلاص العمل لله؛ في قراءته، في صلاته، في صدقاته، في عيادة المريض، في كل شيء، يقصد وجه الله، من باب التناصح.","link":"https://binbaz.org.sa/fatwas/24638/كيف-تكون-النصيحة-في-البعد-عن-الرياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النصيحة للمرائي.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4400,"question":"هذا رجل معه في العمل يذب عليه الشبه دائما، آخر شبهة يقول: لو تعمل عمل الشيطان، والرسول ﷺ قال: لولا أن أشق على أمتي دائما يذب على هذا الشخص الشبه، ماذا يعمل معه؟","title":"حكم مخالطة مثيري الشٌّبهات","answer":"الجواب: يتركه، يقول له: لا تتكلم معي.\nالطالب: يهجره؟\nالشيخ: إذا كان يتكلم معه بشيء يؤذيه، يقول له: لا تكلم معي يا أخي.\nس: هذا يقول: لو تعمل عمل الشيطان، والرسول ﷺ قال: لولا أن أشق على أمتي؟\nج: لولا أن أشق لأمرتهم بالسواك وأيش فيه؟\nالطالب: الرسول قالها.\nالشيخ: وأيش يقول له؟\nس: قصده في تناقض، لا تقولون لو، وهو قال في الحديث: لولا.\nج: لا، هذا شيء وهذا شيء، هذاك إذا جرى المقدور قال: لو فعلت كذا، لو أتيت الطبيب لكان كذا، لو سافرت كان كذا، هذا الذي ممنوع يقول: قدر الله وما شاء فعل، أما هذا غير لولا أن أشق على أمتي لأمرتهم بالسواك يعني لولا المشقة لفعلت هذا، رحمة الله جل لعباده هذا ما فيه معارضة.\nس: هذا يُهْجَر؟\nج: لا، يُعَلَّم، ويُوَجّهه.","link":"https://binbaz.org.sa/fatwas/24677/حكم-مخالطة-مثيري-الشبهات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مخالطة مثيري الشٌّبه.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4520,"question":"حالق اللحية مظهر للمعصية هل يردّ عليه السلام؟","title":"ما المنكرات التي يُهجر أصحابها؟ وما الضابط؟","answer":"الجواب: هذا منكر ظاهر يستحقّ الهجر، لكن بعد أن يُنصح ويُعلم أنَّ هذا ما يجوز، وأنه منكر، حتى إن بعض الناس يراها لا بأس بهذا؛ لأنهم رأوا الناس قد كثر فيهم هذا الشيء، فقد يشتبه على بعض الناس، لكن يُعلَّم ويُوجَّه ويُبين له الحقّ؛ لأنَّ وقوع الناس في ذلك بكثرةٍ قد يُسبب التباس الأمر على الناس، نسأل الله العافية. س: الهجر على إطلاقه لكل أحدٍ؟ ج: إذا كان فيه مصلحة، أما إذا كانت المصلحة تقتضي عدم هجره لمصلحة المسلمين، ما هو لأجل أن يأكل معه ويشرب معه، لا، بل لمصلحة المسلمين فلا بأس، لا يهجره، بل يُنكره ويُداوم في النَّصيحة. س: إذا كان الهجرُ لا يردعه؟ ج: ولو ما يردعه ما فيه خير أن يُجالس ويُؤاكل، أما إذا كان عدم الهجر فيه مصلحة للمسلمين، مصلحة دينية. يقول ابنُ عبدالقوي رحمه الله: فالمسألة فيها أقوال ثلاثة: الهجر سنة مطلقًا، وقيل: واجبًا مطلقًا، وقيل بالتفصيل: إن ردع وجب، وإن لم يردع لم يجب. س: هذه بلوى عمَّت، فلو هُجر كلُّ رجلٍ حلق لحيته أو عصى يُهجر أغلب الناس؟ ج: على كل حالٍ الواجب [على] الإنسان [أن] يعتني بما هو أصلح، يُجاهد نفسه ويعمل ما هو أصلح، لا لهواه، ولكن للمصلحة الشرعية، وإلا البلاء لا شكَّ أنه عظيم. س: من مصالح المسلمين هدايته؟ ج: يعني: ما هو لأجل محبته، أو لأجل قرابته، أو لأجل كذا، بل للمصالح الإسلامية، مُراعاة للمصالح الإسلامية. س: يعني قصد هدايته وتحبيبه؟ ج: نعم، أو دفع منكرًا منه، أو دفع أذى عن المسلمين، أو نحوها.","link":"https://binbaz.org.sa/fatwas/24800/ما-المنكرات-التي-يهجر-اصحابها-وما-الضابط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رد السلام على حالق لحيته، وهجر أصحاب المنكرات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4813,"question":"من رفض السنة تكبرًا يُدعى عليه؟","title":"هل يجوز الدعاء على من رفض السنة عنادًا؟","answer":"يُدعى له بالهداية، وإن دعا عليه بالعقوبة فكما قال النبي ﷺ: لا استطعت؛ لأنه تكبّر.","link":"https://binbaz.org.sa/fatwas/25213/هل-يجوز-الدعاء-على-من-رفض-السنة-عنادا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يدعا على من رفض السنة عنادًا.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4823,"question":"هل يزول الهجر بالسلام أم بعود الحال إلى ما كان عليه من قبل؟","title":"بماذا يزول هجر المسلم لأخيه؟","answer":"الهجر يزول بالسلام، وكماله بأن تعود الحالة كما كانت أولًا، لكن ظاهر قول النبي ﷺ: خيرهما الذي يبدأ بالسلام يزول عنه.","link":"https://binbaz.org.sa/fatwas/25228/بماذا-يزول-هجر-المسلم-لاخيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بماذا يزول هجر المسلم لأخيه.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4824,"question":"صاحب المعصية هل يجوز هجره أكثر من ثلاثة أيام؟","title":"حكم هجر صاحب المعصية أكثر من ثلاثة أيام","answer":"المعاصي لها شأن، والبدع؛ أن يُهجر حتى يتوب إذا أظهرها، هذه في حقِّ الإنسان مع أخيه، في حقوق الدنيا، حقوق الأخوة، أما إذا أظهر المعاصي فهذا يُهجر حتى يتوب.","link":"https://binbaz.org.sa/fatwas/25229/حكم-هجر-صاحب-المعصية-اكثر-من-ثلاثة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز هجر صاحب المعصية أكثر من ثلاثة أيام.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4828,"question":"إذا كان هناك ميت كثير الفساد، ونُحذر أصحابه الذين بقوا أن انتبهوا مثلًا من أفعال فلان؟","title":"هل يجوز تذكير الناس بفساد من مات؟","answer":"إذا كان الفساد ظاهرًا والمعاصي ظاهرةً؛ لا بأس، النبي ﷺ لما مرّ عليه بجنازةٍ فأثنوا عليها شرًّا قال: وجبت، ما أنكر عليهم، وهذا محمولٌ على أنَّ معاصيه ظاهرة، فالذي معاصيه ظاهرة ما له غيبة، ليس له غيبة.","link":"https://binbaz.org.sa/fatwas/25245/هل-يجوز-تذكير-الناس-بفساد-من-مات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز تذكير الناس بفساد من مات.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4830,"question":"حكم النَّصيحة؟","title":"ما حكم النَّصيحة؟","answer":"واجبة فيما يجب، ومُستحبَّة فيما يُستحب، واجبة في ترك المنكرات، ومُستحبة في المستحبَّات.","link":"https://binbaz.org.sa/fatwas/25250/ما-حكم-النصيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم النَّصيحة.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4835,"question":"النصيحة الواجبة مقيّدة بطلب النصيحة أم ببذلها من دون طلب؟","title":"هل النصيحة مقيدة بطلبها أم تُبذل دون طلب؟","answer":"يقول النبي ﷺ: الدين النصيحة، الدين النصيحة، الدين النصيحة فإذا علمت أن أخاك فعل شيئًا يريد النصح؛ ينبغي أن تنصحه، وإذا استنصحك فانصح له، الأمر آكد. يعني قال: ما تقول في كذا وكذا؟ لا تغشه، وإلا فأنت تبدأه بالنصيحة ولو ما استنصحك، سنة مؤكدة. تبدأه بالنصيحة، إذا رأيته قد يقع في شيء يضره انصحه، أو سلعة ما تناسبه أو مغشوشة، الشيء الذي ترى فيه المصلحة لأخيك تنصحه فيه، وقد تجب، تختلف الأحوال.","link":"https://binbaz.org.sa/fatwas/25261/هل-النصيحة-مقيدة-بطلبها-ام-تبذل-دون-طلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل النصيحة الواجبة مقيدة بطلب النصيحة أم ببذلها من دون طلب.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":4964,"question":"لو كان في شريط يقول مثلًا: قال الله تعالى، مثلًا، يحط قبلها: قال الله تعالى؟","title":"هل يستعيذ المحاضِر للآية أم يكفي \"قال الله\"؟","answer":"الجواب: إذا كان ذكر آية ما في بأس.\nس: يقول: قال الله تعالى، أو يقول: أعوذ بالله من الشيطان الرجيم؟\nالشيخ: قال الله تعالى كذا وكذا، أو يقول: أعوذ بالله من الشيطان، قال الله كذا وكذا، إذا تعوّذ أحسن أفضل فَإِذَا قَرَأْتَ الْقُرْآنَ فَاسْتَعِذْ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ [النحل:98].","link":"https://binbaz.org.sa/fatwas/27664/هل-يستعيذ-المحاضر-للاية-ام-يكفي-قال-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يستعيذ المحاضِر للآية أم يكفي.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5004,"question":"الوالدان عند الإنكار عليهما: ألا يَرِدْ أبدًا التَّعنيف؟","title":"هل يجوز التعنيف في الإنكار على الوالدين؟","answer":"الجواب: لا، باللُّطف، فالله قال في حقِّ الكافِرَيْنِ: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا  [لقمان:15]، وقال في حقِّهما: فَلَا تَقُلْ لَهُمَا أُفٍّ وَلَا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا [الإسراء:23].","link":"https://binbaz.org.sa/fatwas/28763/هل-يجوز-التعنيف-في-الانكار-على-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز التعنيف في الإنكار على الوالدين؟.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5073,"question":"قصور الأفراح يحصل بها بعض المُنكرات، فهل لطلبة العلم زيارتهم ووعظهم وإرشادهم والبيان لهم؟","title":"كيف يكون النصح والإنكار بقصور الأفراح؟","answer":"الجواب: ينبغي استغلال هذه الفرصة، الدُّعاة وأهل العلم يزورون هذه القصور وقت الاجتماع، ويلقوا فيهم النَّصائح والتوجيهات، بسبب الاجتماع الذي يجمع الجمَّ الغفير من الجاهل وطالب العلم من النساء والرجال، اغتنام هذه الفرصة بالتوجيه والتَّذكير والنَّصيحة أمرٌ مطلوبٌ، ينبغي لأهل العلم -ولا سيَّما خواص الدعاة إلى الله- أن يحضروها ويُنبهوا ويعظوا ويُذَكِّروا، وهكذا بقية الاجتماعات، وسائر الاجتماعات إذا أمكن ذلك، فهو فيه خيرٌ عظيمٌ.","link":"https://binbaz.org.sa/fatwas/29383/كيف-يكون-النصح-والانكار-بقصور-الافراح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيف يكون النصح والإنكار بقصور الأفراح؟.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5076,"question":"شخصٌ يدعو ويأمر بالمعروف وينهى عن المنكر، ولكن لا يُسْمَع له، فما نصيحتكم لهذا الشَّخص؟","title":"ما التوجيه لمن ينصح للناس دون استجابة؟","answer":"الجواب: لا يضرُّه ذلك، لكن عليه أن يتحرى الأسلوب النافع؛ لأني أخشى أن يكون عدم النفع من سوء أسلوبه وغِلَظِه وعُنفه، لكن يُغيّر أسلوبه، وينظر في أسباب عدم النَّفع: ليش، لا بدّ أن يحاسب نفسه: إما أنه صاحب معاصٍ، يحتقرونه لأنه صاحب معاصٍ، يقول ولا يعمل، وهذه علَّة عليلة عظيمة، وإما أنه لا يُحسن أسلوب الدَّعوة، وإما لأسبابٍ أخرى، فلينظر، وليُحاسب نفسه، ويتَّقي الله، فلم يُخفق إلا بسبب ذنبٍ من ذنوبه، هذا في الغالب.  وقد لا يُسمع له ولو كان أصلح الناس، لكن يُحاسب نفسه وينظر، فإن وجد شيئًا فليُعالجه، وإن كان ما وجد شيئًا فالحمد لله، ولا يضرُّه ذلك، النبي ﷺ مكث في مكة دهرًا طويلًا -ثلاث عشرة سنة- ما أجاب له إلا القليل، ولا يضرُّه هذا، مثلما سمعتم في حديث ابن عباسٍ: يقول ﷺ: عُرضت عليَّ الأمم، فرأيتُ النبيَّ ومعه الرهيط، كان في رواية مسلم: الرهيط بالتصغير: ثلاثة أو أربعة أو خمسة، والنبي معه الرجل والرجلان، والنبي وليس معه أحدٌ بعض الأنبياء ما أطاعه أحدٌ بالمرة، ما قبلوا منه، بل قتلوه، فيأتي يوم القيامة وحده، ما معه أحدٌ، ما تبعه أحدٌ من أمَّته كلها، ولا يضرُّه، هذا أدَّى ما عليه، والحمد لله.","link":"https://binbaz.org.sa/fatwas/29416/ما-التوجيه لمن-ينصح-للناس-دون-استجابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما التوجيه لمن ينصح للناس دون استجابة؟.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5094,"question":"سائل يقول: فضيلة الشيخ عبد العزيز، ما هي مبادئ وأسس الدعوة إلى الله؟ وما هي طرقها؟","title":"ما مبادئ وأسس الدعوة إلى الله؟","answer":"الجواب: المبادئ معروفة: أولاً: المؤمن يجتهد في نفسه، ويتعلم، ويتبصّر، ويتفقه. وإذا رزقه الله العلم وتفقه في دينه فإن المبدأ في ذلك: أن يدعو إلى الله؛ بتعليم الناس، وبإرشاد الجاهل وتعليمه، وتوجيهه إلى الخير، وأمره بالمعروف، ونهيه عن المنكر، كما قال تعالى: قُلْ هَذِهِ سَبِيلِي أَدْعُو إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108]. المبدأ الأول: أن تتلقى العلم، وأن تتعلم وتتبصّر، وتعتني بالقرآن وحفظه وتدبّر معانيه، والسنة عن النبي ﷺ، حتى تحفظ منها ما تيسر، وتشتغل على أهل العلم، وتسأل أهل العلم، وتذاكر أهل العلم؛ حتى تكون على بينة. فإذا عرفت ما شرع الله لك، وما أوجب عليك، وما حرَّم عليك؛ تدعو إلى الله، فتكون ممن قال الله فيهم: وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:3] وممن قال فيهم: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [آل عمران:104]، وممن قال فيهم: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]. تنفع نفسك، وتنفع الناس بالحكمة والكلام الطيب، قال تعالى: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]. فتدعو إلى الله بالكلام الطيب، وترشد إليه، وتعلم الناس الخير، وتنهاهم عن الشر، هكذا ينبغي لك.","link":"https://binbaz.org.sa/fatwas/29998/ما-مبادى-واسس-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 14.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5100,"question":"سائل آخر يقول: فضيلة الشيخ عبد العزيز بن باز، السلام عليكم ورحمة الله وبركاته:أولاً: أُشهد الله أنني أحبك من أجله، وأسأل الله أن يطيل في عمرك وينفع بك جميع المسلمين.ثانيًا: إن أمتنا في الوقت الحالي تحتاج إلى العمل الصادق الدائم وليس إلى كثرة الكلام والخطب؛ فما هي السبل والطرق التي ترى وتقترح أن تقوم بها المراكز في الخارج لتكون الأقلية المسلمة في المجتمعات الغربية قرآنًا يسير على الأرض ويدعو إلى الإسلام الصحيح؟ وجزاكم الله خيرا.","title":"ما النصيحة للأقليات المسلمة في بلاد الغرب؟","answer":"الجواب: أولاً: أحبك الله الذي أحببتنا له وجعلنا وإياك وسائر إخواننا وسائر المستمعين من المتحابين في الله ، فقد صح عن رسول الله عليه الصلاة والسلام، أنه قال يقول الله يوم القيامة: أين المتحابون بجلالي اليوم أظلهم في ظلي يوم لا ظل إلا ظلي وصح عنه عليه السلام أنه قال: سبعة يظلهم الله في ظله يوم لا ظل إلا ظله إمام عادل، وشاب نشأ في عبادة الله، ورجل قلبه معلق بالمساجد، ورجلان تحابا في الله اجتمعا على ذلك وتفرقا عليه، ورجل دعته امرأة ذات منصب وجمال فقال إني أخاف الله، ورجل تصدق بصدقة فأخفاها حتى لا تعلم شماله ما تنفق يمينه، ورجل ذكر الله خاليا ففاضت عيناه متفق على صحته. أما السؤال الثاني: فذلك متعيّن، ولكن الخطب والمحاضرات والمؤلفات والمقالات التي تنشر كلها وسيلة إلى ما ذكرت من العمل؛ فالخطبة والمقالة الجيدة الموفقة إذا نشرت أو وزعت أو أذيعت ينفع الله بها من يشاء، فالله شرع الخطب وشرع الكتب والنصائح حتى ينتفع بها الناس، حتى يستعين بها الناس وحتى يفقهوا دينهم وحتى يتشجعوا على ما ينبغي لهم وعلى ما يُطلب منهم. والواجب على العلماء وعلى المراكز الإسلامية وعلى الجمعيات الإسلامية وعلى كل من له قدرة في نفع العباد أن يمثل ذلك بالعمل لا بالقول فقط؛ فالقول ينفع في محله ولكن الأهم العمل، فالقول المشروع مطلوب، كذكر الله والأمر بالمعروف والنهي عن المنكر والاستغفار والدعاء مطلوب، ولكن ما كان يتعلق بالعمل فالمطلوب العمل: كَبُرَ مَقْتًا عِنْدَ اللَّهِ أَنْ تَقُولُوا مَا لَا تَفْعَلُونَ [الصف:3] فلا بدّ من العمل فيما يتعلق بالعمل من صلاة وصوم وجهاد وحج وزكاة وغير هذا من وجوه العمل، فلا بدّ من القول في محله ولا بد من العمل في محله، ومن صفات المنافقين أنهم يقولون ما لا يفعلون، فلا يجوز للمسلم أن يقول ما لا يفعل بل يقول ويفعل، يكون صادقًا في قوله صادقًا في عمله، وعلى الحكام المسلمين أينما كانوا أن يُعْنَوا بأمر الله، فإن الزبدة العظيمة من ولاية الحاكم على المسلمين أن يوجههم إلى دين وأن يلزمهم بأمر الله وأن يعينهم على طاعة الله وأن يمنعهم مما يخالف شرع الله، هذه الزبدة المقصودة من الولاية، المقصود من الولايات سواء كانت الولاية مُلكية أو رئاسة جمهورية أو إمارة أو غير هذا من الأسماء، المقصود من الولايات إقامة أمر الله في أرض الله، المقصود هو إقامة أمر الله في أرض الله؛ لتوجيه الناس إلى الخير وإلزامهم بما أوجب الله ومنعهم عما حرم الله وإقامة الحدود عليهم فيما أوجب الله إقامته، هذا هو الواجب. ووصيتي لجميع إخواني، في كل مكان، في مراكز إسلامية، في جمعيات إسلامية، في معاهد، في مدارس، في أي عمل كانوا، وفي أي مكان كانوا، وصيتي للجميع أن يتقوا الله، وأن يلتزموا بأمر الله، وأن يعتنوا بتوجيه عباد الله إلى دين الله، وأن يكونوا دعاة خير ودعاة هدى، فقد صح عن رسول الله عليه الصلاة والسلام أنه قال: من دل على خير فله مثل أجر فاعله وقال لعلي  لما بعثه إلى خيبر لدعوة اليهود: فوالله لأن يهدي الله بك رجلا واحدًا خير لك من حمر النعم والله يقول في كتابه العظيم: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ [فصلت:33] ويقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَيُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُولَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71] ويقول سبحانه: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ [آل عمران:104] فجعلهم هم أهل الفلاح حصره فيهم؛ لعظم ما قاموا به من الدعوة والأمر بالمعروف والنهي عن المنكر وقال : كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنْكَرِ وَتُؤْمِنُونَ بِاللَّهِ [آل عمران:110]. هذا هو واجب المسلمين؛ الدعوة إلى الخير والأمر بالمعروف والنهي عن المنكر أينما كانوا، وبهذا يكون الإنسان من خير الأمة، بهذا يكون المؤمن والمؤمنة من خير الأمة بهذا العمل الجليل، بالدعوة إلى الله والأمر بالمعروف والنهي عن المنكر والاستقامة على الحق، والله المستعان.","link":"https://binbaz.org.sa/fatwas/30008/ما-النصيحة-للاقليات-المسلمة-في-بلاد-الغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 25.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5102,"question":"وصلنا من الأخوات سؤال يقول: يا فضيلة الشيخ إذا أرادت المرأة العمل في مجال الدعوة في المجتمع فما هي الكتب التي تنصحون بقراءتها ومناقشتها بين النساء سواء للمتعلمات أو الجاهلات بشكل مبسط؟","title":"ما الكتب التي يُنصح بها في الدعوة إلى الله؟","answer":"الجواب: أهم شيء القرآن الكريم، تعليم القرآن وما تيسر منه؛ لأنه كتاب الله فيه الهدى والنور: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44] فنصيحتي لأخواتي الدعاة إلى الله من النساء أن يعنين بالقرآن الكريم تفقهًا وتفيقهًا وتعليمًا للنساء، وما يتعلق بالسور القصيرة، وأهم ذلك الفاتحة؛ تعليم الفاتحة ومعانيها؛ لأنها أم القرآن، وفيها: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]  وفيها اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ [الفاتحة:6] هذا من أهم ما يبين معنى الصراط المستقيم ما هو، معنى: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] معنى صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ [الفاتحة:7]. وهكذا ما في كتاب الله من الأحكام والبيان، كل على حسبه، لطالبات العلم شيء، وللعامة من النساء شيء آخر، ثم تعليم العقيدة: ما معنى لا إله إلا الله، ما معنى شهادة أن محمدًا رسول الله؛ حتى يعرفن الله على بصيرة وحتى يعلمن معنى لا إله إلا الله، وأنه لا معبود حق إلا الله؛ فيخلصن العبادة لله وحده من صلاة وصوم وصدقة، وغير ذلك كله لله وحده. ثم تعليم الصلاة: كيف تصلي، والطهارة: كيف تطهر من الجنابة، من الحيض، من النفاس، كيف الطهارة الصغرى من الأحداث التي توجب الطهارة. كيف تصوم، كيف تزكي مالها وحليها، كيف تحج إذا جاء الحج. كيف تطيع والديها، كيف تطيع زوجها وما حق زوجها عليها، إلى غير هذا. ومن الكتب التي تناسب قراءتها: ما ألف في أمر النساء وشأن النساء وما في كتاب الله من شأنهن وما جاءت به السنة بشأنهن في \"بلوغ المرام\" مثلًا كتاب صغير مختصر مفيد، عمدة الحديث في أحاديث الرسول ﷺ، عمدة الفقه للموفق ابن قدامة، \"ثلاثة الأصول\" للشيخ محمد بن عبد الوهاب، \"كتاب التوحيد\"، \"العقيدة الواسطية\"، وما أشبه هذه من الكتب الصغيرة التي تنفعهن وتفيدهن، أو ملخص منها حتى يستفيد منهن العامة والطالبات الصغيرات اللآتي يحتجن إلى ذلك ولم يتعلمن في المدارس. أما من يتعلم في المدارس الطيبة فسوف يستفيد من المنهج الذي عنده والمقررات التي عنده، ولكن لا مانع من الزيادة أن تكون الداعية تزيد الطالبة علمًا وتفقيهًا وتوجيهًا، وتعلم العامية ما يلزمها مما لا يسعها جهله في إخلاص العبادة لله بالصلاة بالطهارة في الزكاة في الصيام كما تقدم، في حق الزوج، في حق الوالدين، في حق الأقارب، في حق الجيران وما أشبه ذلك. ومن أحسن الكتب أيضًا وإن كان مطولًا بعض الطول: \"زاد المعاد في هدي خير العباد\" لابن القيم فإنه كتاب مفيد ونافع، وهكذا \"فتح المجيد شرح  كتاب التوحيد\" كتاب مفيد أيضًا في العقيدة، وهكذا \"آداب المشي إلى الصلاة\" مختصر مفيد في الصلاة وفي الزكاة وفي الصيام للشيخ الإمام محمد بن عبد الوهاب رحمة الله عليه، هذه كتب مختصرة مفيدة.","link":"https://binbaz.org.sa/fatwas/30010/ما-الكتب-التي-ينصح-بها-في-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 27.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5134,"question":"سائل يقول: إنني رجلٌ أقوم بالدعوة والإرشاد والأمر بالمعروف والنَّهي عن المنكر، وإنكار المنكرات على الناس، ولكن هناك مَن يتصدَّى لي ويقول: إنَّك تتدخل فيما لا يعنيك، وإنك تُثير فتنةً، فما الحكم في ذلك؟","title":"ما كيفية مواجهة التثبيط عن الدعوة إلى الله؟","answer":"الجواب: إذا كان عندك علمٌ وتدعو إلى الله على بصيرةٍ فلا تلتفت إلى مَن ثَبَّطك، تدعو إلى الله، تعلِّم الناس، تأْمُرْ بالمعروف، تنهَ عن المنكر، مع الحلم والصبر والاحتساب وطيب الكلام، كما قال الله جلَّ وعلا: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71]، وقال سبحانه: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنْكَرِ [آل عمران:110]، وقال سبحانه: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ [فصلت:33]، وقال سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]. فاستمر على ذلك ما دام عندك علمٌ، فاستقم على ذلك، ولا تلتفت إلى مَن ثبَّطك، لكن عليك بالحكمة، وعليك بقال الله ورسوله، وضع الأشياء في مواضعها، والحلم والصبر، وعدم العجلة في الأمور، وعليك بالرفق وطيب الكلام.","link":"https://binbaz.org.sa/fatwas/30049/ما-كيفية-مواجهة-التثبيط-عن-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 70.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5137,"question":"سائل يقول: ما هي كتب العقيدة الصَّحيحة التي تنصحون طالب العلم باقتنائها وقراءتها؟ وكيف تُوجهون الداعية الذي يدعو أناسًا من أهل البادية من العامَّة الذين يحتاجون إلى تعلم أصول العقيدة؟","title":"ما واجب الدعاة تجاه العامَّة في تعليم العقيدة؟","answer":"الجواب: أعظم كتب العقيدة وأنفعها: كتاب الله \"القرآن\"، فيه الهدى والنور، فنوصي الجميع رجالًا ونساءً، كبارًا وصغارًا: أن يعتنوا بالقرآن، وأن يجتهدوا في حفظه، والإكثار من تلاوته، فهو كتاب العقيدة، وهو كتاب الهُدى، وهو الشافع المفيد النافع، كما قال جلَّ وعلا: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]. وهو الصراط المُستقيم، فنُوصي جميع المسلمين في كلِّ مكانٍ: جميع الرجال والنساء، العرب والعجم، نوصي الجميع بأن يلزموا هذا القرآن، وأن يُعظِّموه ويعملوا به، ويُكثروا من تلاوته أينما كانوا، من المصحف وعن ظهر قلب، وأن يُنفذوا أوامره، وينتهوا عن نواهيه. هو كتاب العقيدة، وهو كتاب العمل، وهو كتاب الهدى، وهو كتاب السَّعادة، فيه كل خير، وفيه الدَّعوة إلى كل خيرٍ، وفيه الدعوة إلى مكارم الأخلاق، ومحاسن الأعمال، وفيه القصص عن الماضين، عن الخير والشر، أخبر عن الماضين من أهل الخير، وعن الماضين من أهل الشر. فعلى المؤمن والمؤمنة أن يأخذوا منه ما دلَّ عليه من الخير، وأن يحذروا ما حذَّر منه من الشر. ثم كتب الحديث: كالصَّحيحين، والسنن، والمسانيد المُعتمدة، فأهل العلم يخرجون الأحاديث، ويُعلِّمون الناس وينشرونها بينهم. ثم كتب العقيدة المعروفة لأئمة أهل السنة والجماعة، الكتب الطيبة المعروفة يُستعان بها، ويُنتفع بها في تعليم الناس الخير، كتب السلف الصالح المعروفة، مثل: كتب شيخ الإسلام ابن تيمية وابن القيم رحمهما الله، وغيرهم من أهل العلم المعروفين بحُسن العقيدة، ومثل كتب الشيخ محمد بن عبدالوهاب رحمه الله، وأئمة الدعوة الإسلامية في نجد، لما يسَّر الله هذه الدَّعوة في القرن الثاني عشر، كتبوا وجمعوا فيها ما ينفع الله به الناس، مثل: كتاب \"التوحيد\"، و\"الثلاثة الأصول\"، و\"كشف الشُّبهات\"، و\"آداب المشي إلى الصلاة\"، ورسائل المشايخ في \"الدرر السنية\"، و\"فتح المجيد شرح كتاب التوحيد\" للشيخ سليمان، هذه الكتب العظمية، و\"العقيدة الواسطية\" لشيخ الإسلام ابن تيمية، و\"التدمرية\"، و\"منهاج السنة\"، و\"الحموية\"، و\"العقيدة الطحاوية\" وشرحها لابن أبي العز، و\"لمعة الاعتقاد\" لصاحب \"المغني\"، إلى غيرها من الكتب الطيبة، كتب السلف الصالح التي تُعين على الخير، وتنشر الحقَّ، وتُعلم الناسَ الخير. فأهل العلم يدلّون عليها ويفيدون الناس منها، لكن أصل الجميع والأصل العظيم \"القرآن\"، يجب على الجميع العناية بالقرآن، فهو الأصل الأول، وهو الذي بيده الهدى والخير. فعلى المسلمين أن يعتنوا بالقرآن أعظم عناية، رجالًا ونساءً، كبارًا وصغارًا، فهو كتاب الله، فيه الهدى والنور، وفيه الدلالة على كل خيرٍ، والتحذير من كل شرٍّ. ثم أحاديث الرسول ﷺ وسنته الصَّحيحة: كالبخاري، ومسلم، وغيرها من الكتب الصَّحيحة التي جمعت في هذا الباب، مثل: \"المنتقى\" و\"بلوغ المرام\" و\"عمدة الأحكام\"، وغيرها من الكتب المُؤلفة في الحديث، والتي اعتنى أهلها بالحديث الصحيح، وبيان ما ضعف منها وما صحَّ، فهذه تنفع الأمة، فعلى طالب العلم أن يعتني بها، ويستفيد منها، ويُعلم الناسَ الخير، يُعلم العامَّة، ويُوصل العامَّة إلى الحقِّ والهُدى والصَّلاح.","link":"https://binbaz.org.sa/fatwas/30052/ما-واجب-الدعاة-تجاه-العامة-في-تعليم-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 73.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5144,"question":"أثابكم الله، يقول هذا السَّائل: عندما يكون الطبيبُ في مكان عمله الذي يستوجب منه علاج المسلم وغير المسلم، كالنصارى أو غيرهم مثلًا في حالة الحرب، مع الخوف من هذا النصراني الذي قد يحصل فيما بعد، فما موقف الطبيب المُعالج أمام الله تعالى في علاج هذا الذي يُبغضه الله ورسوله، ويبغض الله ورسوله؟","title":"ما حكم معالجة الطبيب المسلم لمريض كافر؟","answer":"الجواب: الواجب على الطبيب أن يُعالجه كما يُعالج غيره؛ لأنَّ هذا صار في محلِّ الاستئمان، وليس في محلِّ حربٍ، إذا كان تبعنا أو دخل عندنا بالأمان موظفٌ أو طبيبٌ أو مع المُجاهدين أو مع الميلشيات التي تُحارب الآن، فلو جرى عليه شيءٌ لا بدّ أن تُعالجه كما تُعالج المريض المسلم، وتتقي الله في أداء الأمانة. وكونه يُبغضه الله، فهذا إلى الله ، لكن أنت الآن دخل عندك بالأمان، فلا بدّ أن تُعالجه إذا كان مُؤْتَمَنًا، أو مُعاهدًا، أو جاء برسالة أمانٍ، أو جاء طبيبًا، أو لأسبابٍ أخرى، فإن أصابه مرضٌ فعالجه بالأمانة ولا تضرّه بشيءٍ. س: ألا ترون يا سماحة الشيخ أنَّه في مثل هذه الحالة مجال للدعوة الإسلامية؟ الشيخ: زيادة، الدعوة طيبة، فكونه يدعوه إلى الله ويُرَغِّبه في الإسلام هذا طيبٌ، مع العلاج، فلا يَخُن الأمانةَ ويُعالجه بشيءٍ يضرُّه، بل يجب أن ينصح له، وهذا من الدعوة إلى الإسلام، فكونه ينصح له هذا من الدَّعوة إلى الإسلام، ويستشعر النصراني أو غيره أنَّ الإسلام ينصح ويُؤدي الواجب لمَن اؤتُمِنَ عليه، أو صار في أمانته، أو في عهده، أو في ذمَّته.","link":"https://binbaz.org.sa/fatwas/30059/ما-حكم-معالجة-الطبيب-المسلم-لمريض-كافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 80.mp3","categories":["الطب والتداوي","الدعوة والدعاة"]},{"id":5240,"question":"سؤال يقول: ما مدى حدود واجب الفرد في مجال الحسبة؟ هل هي فرض عينٍ لكل فردٍ؟","title":"ما واجب كل مسلم في الأمر بالمعروف؟","answer":"الجواب: كما تقدم: فرض، فرض، فرض على كلِّ واحدٍ إذا لم يوجد مَن يقوم مقامه، أما إذا وُجد مَن يقوم مقامه صارت في حقِّه سنةً، لكن أنت في قريةٍ، أو في حيٍّ من الأحياء، أو في قبيلةٍ ما عندك أحدٌ يُنكر المنكر، أنت رأيت المنكر بنفسك، عليك أن تُنكر المنكر حسب الطاقة: إما باليد، أو باللسان، حسب الطاقة، أقل شيءٍ القلبُ، إذا خفتَ الضرب والقتل كفى القلب، وإلا فالواجب اليد كالحسبة، رجل الحسبة حسب التعليمات التي لديه، في الرجل مع أولاده حسب الطاقة، مع زوجته حسب الطاقة، أمير القرية في بلده، في قريته، في قبيلته شيخ القبيلة حسب طاقته، وهكذا كل بحسبه، أما أن تمر بالمنكر وتقول: هذا على الهيئة، الهيئة ما سوّت شيئًا، ولا تعلمه أيضًا، ما هو في جهتها، ولا في حيِّها، مثلًا: ما عندك مركز، أو عندك مركز وغفل، أنت رأيت المنكر: إما أن تُنكر المنكر، وإما أن ترفعه إلى مَن يُنكره إذا عجزت وتقول: جرى كذا، وجرى كذا من المنكرات الظَّاهرة. ومن هذا ما يتعلق بالصَّلوات: كثير من الناس يعرفون جيرانهم لا يُصلون في مسجدهم، ولا يقولون لهم: لماذا؟ أو يزورونهم، يروح اثنان أو ثلاثة، لا تروح وحدك، وحدك قد يُستهان بك، لكن انظر مَن يتيسر معك من الإخوان: اثنان، ثلاثة، تزورونه، أو في الطريق تُوقفونه: يا فلان، يا عبدالله، اتَّقِ الله، ما نُشاهدك -ما نشوفك- في المسجد، أو نسمع صوت المزامير والأغاني في بيتك، وأنتم جيرانه تسمعونه، تقولون له بالكلام الطيب، وتنصحونه، ولعله يستفيد، فإن لم يستجب في المرة الأولى استجاب في الثانية أو في الثالثة أو في الرابعة، أو ترفعون أمره بعد الإعذار إلى مَن يقوم عليه، وهكذا، فالغفلة هي المصيبة، والإعراض هو المصيبة.","link":"https://binbaz.org.sa/fatwas/30650/ما-واجب-كل-مسلم-في-الامر-بالمعروف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 488.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5299,"question":"ما حكم الدعاء للكفار والمبتدعة بالهداية والصلاح، وهل هناك خلاف بين أهل العلم في ذلك، وما الراجح في ذلك؟","title":"حكم الدعاء للكفار والمبتدعة بالهداية والصلاح","answer":"الجواب: الهداية مطلوبة من الجميع، طلب الهداية مطلوب من الجميع من الكافر والعاصي وغيرهما، كُلٌّ بحاجة إلى الهداية، وأنت تقرأ في كل ركعة اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ أنت تطلب الهداية وأنت مؤمن، تطلب الهداية والثبات على الحق والمزيد من الهداية، كُلٌّ محتاج للهداية، النبي ﷺ قيل له: إن دوسًا كفرت وعصت قال ﷺ: اللهم اهدْ دوسًا وائت بهم، اللهم اهد دوسًا وائت بهم، ودعا لكثير من الكفرة فهداهم الله. وإذا كان ظالمًا مؤذيًا دُعي عليه بالهلاك أيضًا، يجوز الدعاء عليه بالهلاك والدعاء له بالهداية، هذا جائز وهذا جائز، ولاسيما إذا آذوا الناس وأضروا الناس؛ فهم أوْلى بأن يدعى عليهم بالهلاك لبُعد هدايتهم، وإذا كانوا كفّوا شرهم دُعي لهم بالهداية وأن الله يهديهم للحق وأن الله يبصّرهم.[1]","link":"https://binbaz.org.sa/fatwas/30949/حكم-الدعاء-للكفار-والمبتدعة-بالهداية-والصلاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 019.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5323,"question":"لقد عملت ما يقارب السنة مع الشيعة الرافضة الاثني عشرية في مدينة القطيف، وجرى خلال هذه المدة بعض النقاش حول بعض الاختلاف بين أهل السنة والشيعة، وكنت آتي بأدلة لما أقوله من كتبهم المعتمدة مثل الكافي وما لا يحضره الفقيه، ومن كتب أهل السنة المؤلفة في الشيعة، وكانوا لا يقبلون لحجة أن هذه الكتب مثل الكافي وغيره ليست صحيحة كلها، وكنت أعطيهم من كلام الخميني ولا يردونه، عمومًا سؤاله كالتالي: أنا الآن انتقلت من عندهم واتفقت أنا وأحدهم أن نكمل النقاش عبر المراسلة، فما رأي سماحتكم، وبماذا تنصحونني في هذا الشأن؟","title":"حكم وكيفية الرد على أهل البدع ومجادلتهم","answer":"الجواب: الشيعة من أخبث أهل البدع، وشرهم الرافضة الإمامية، فإنهم ضد الإسلام وضد أصحاب الرسول ﷺ، فهم عندهم من الشرك والكفر وأنواع الشر ما ليس عند غيرهم، من سب الصحابة والغلو في علي وأهل البيت وأنواع الشرك بالله ، فمثلهم لا يحاجهم إنسان إلا بقال الله وقال رسوله، لا بقول فلان وفلان؛ لكن هم وأمثالهم لا بدّ من مقارعة الحجة بالحجة، وباطلهم يُدمغ بالحجة، قال الله وقال رسوله؛ حتى لا يلبّسوا على الناس بقول فلان وفلان. فالواجب أن يُدعَوا إلى الحق من الكتاب والسنة وبما درج عليه سلف الأمة وهم في الغالب لا يستجيبون؛ لأن كفرهم متعمد مثل اليهود، هم أشبه الناس باليهود، يجادلون بالباطل ويجحدون الحق على بصيرة، ولا يستجيبون لداعي الحق عنادًا وكفرًا وضلالًا، نسأل الله العافية.[1]","link":"https://binbaz.org.sa/fatwas/30988/حكم-وكيفية-الرد-على-اهل-البدع-ومجادلتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 043.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5329,"question":"في بعض الأحيان يمر الإنسان بمنكرات يحترق لها القلب ولا يستطيع الإنكار بسبب ضعف المُنْكِر وقوة الفاعل، فما العمل في هذه الحالة؟","title":"ما حكم عدم إنكار المنكر لقوة الفاعل؟","answer":"الجواب: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن: 16] يقول ﷺ: من رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه وذلك أضعف الإيمان إذا كان في بيئة لا يستطيع الإنكار بيده ولا بلسانه فليجتنبها ولا يحضر المنكر، يبتعد وينكر بقلبه، وإذا كان في بيئة يستطيع الإنكار بلسانه أنكر بلسانه، وإذا كان يستطيع أن يغير بيده كأبي الأولاد والسلطان والأمير والهيئة، على حسب صلاحيته، أنكر بيده حسب ما عنده من الصلاحية.[1]","link":"https://binbaz.org.sa/fatwas/30999/ما-حكم-عدم-انكار-المنكر-لقوة-الفاعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 050.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5333,"question":"ما هو العقاب الذي توعد الله به من رأى منكرًا ولم يغيِّره بلسانه وهو قادر على ذلك؟","title":"ما حكم مَنْ رأى منكرًا ولم يغيِّره؟","answer":"الجواب: مثل ما قال الله في سورة المائدة: لُعِنَ الَّذِينَ كَفَرُوا مِنْ بَنِي إِسْرَائِيلَ عَلَى لِسَانِ دَاوُودَ وَعِيسَى ابْنِ مَرْيَمَ ذَلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ ۝ كَانُوا لَا يَتَنَاهَوْنَ عَنْ مُنْكَرٍ فَعَلُوهُ لَبِئْسَ مَا كَانُوا يَفْعَلُونَ [المائدة: 78، 79] موعود باللعن والطرد عن الرحمة، نسأل الله العافية، وفي الحديث الصحيح يقول ﷺ: إن الناس إذا رأوا المنكر ولم يغيّروه أوشك أن يعمّهم الله بعقاب نسأل الله العافية.[1]","link":"https://binbaz.org.sa/fatwas/31005/ما-حكم-من-راى-منكرا-ولم-يغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 055.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5629,"question":"والذي يقول أنَّ الهجر دواء، إذا كان ينفع يُستعمل؟","title":"ما ضابط الهَجْر النافع للعاصي والمبتدع؟","answer":"الجواب: هذا هو؛ إن كان ما ينفع ما يُستعمل، دواء، مثلما هجر النبيُّ الثلاثةَ ونفعهم الله بالهجر، ولم يهجر عبدالله بن أُبي وأصحابه؛ لأنهم لا ينفع فيهم الهجر. س: لكن المُبتدع إذا لم يفد فيه النُّصح والتَّوجيه؟ ج: يُهجر. س: وإذا كان الهجرُ ما يُفيد فيه؟ ج: إذا كان في دولةٍ تقوم فيه بأمر الله، وإلا أنت هذا الذي عليك: إما أن تنصح، وإما أن تهجر، أما إذا كان في دولةٍ تُقيم أمر الله يُرفع أمره إلى الدولة، وأما أنت فلا تفعل: لا تقتل، ولا تضرب. س: يُشرع الهجر؟ ج: حتى يتوبَ، ولو سنة، ولو سنتين، ولو عشر سنين، حتى يتوب، مثلما هجر النبيُّ الثلاثة خمسين ليلةً حتى تاب الله عليهم. س: يعني: الهجر ليس له مدَّة؟ ج: إذا كان في المعاصي والبدع. س: على حسب المصلحة؟ ج: على حسب الهاجر؛ فإذا رأى أنَّ عدم الهجر ينفعهم باشرهم ونصحهم، وإذا رأى أن النَّصيحة لا تُفيدهم هجرهم.[1]","link":"https://binbaz.org.sa/fatwas/31626/ما-ضابط-الهجر-النافع-للعاصي-والمبتدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alsana albaghawi 004.mp3","categories":["قضايا معاصرة","الدعوة والدعاة"]},{"id":5630,"question":"كيف يجمع بين عدم الهجر وبين قول الله : كَانُوا لَا يَتَنَاهَوْنَ عَنْ مُنْكَرٍ فَعَلُوهُ [المائدة:79]؟","title":"ما مدة الهجر الشرعي وكيفيته؟","answer":"الجواب: هذا يُصاحبهم، يتّخذهم أصحابًا له، وأنت ما تتّخذهم أصحابًا، تتصل بهم للدَّعوة، ما هو للصحبة، تتصل بهم للدَّعوة والتوجيه والإرشاد، ما تصحبهم في مُنكراتهم، أما فعل بني إسرائيل فيصحبونهم في مُنكراتهم، ويتركون النَّهي، أما أنت فلا، إذا زرتَه تنهاه، وتأمره بالمعروف، وتنهاه عن المنكر، مرتين، ثلاثًا، لعله يهتدي، من دون أن تتّخذه صاحبًا؛ تأكل معه وتشرب معه. س: الهجر له مدّة؟ ج: حسب اجتهاد الهاجر، ما يتعين. س: لا يقرأ عليه السلام؟ ج: لا يُسلم عليه، ولا يُصافحه ولو مضت سنوات، إذا كان بقي على بدعته وعلى معاصيه الظَّاهرة، نعم. س: هل هناك مدّة معينة للنَّصيحة؟ ج: كلما لقيتَه تنصحه، كلما تيسر تنصحه، فإذا أصرَّ تهجره. س: الهجر في أمر الدنيا ثلاث ليالٍ؟ ج: يهجره في الكلام ثلاثة أيام، فإن هداه الله فالحمد لله، في حقِّه، التقصير في حقِّه، ما هو في حقِّ الله، في حقِّ الإنسان. س: مَن قال أنَّ الهجر في هذا الزمان لا يُفيد؟ ج: غلط، يفيد، إذا هجره أهلُ الخير وأهلُ الحلّ والعقد يُؤثر، وإذا ما أثَّر فالحمد لله برئت ذمَّتُك.[1]","link":"https://binbaz.org.sa/fatwas/31627/ما-مدة-الهجر-الشرعي-وكيفيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alsana albaghawi 005.mp3","categories":["الدعوة والدعاة","التفسير"]},{"id":5677,"question":"بعض الشباب المتمسك بدينه أصبح يحارب حتى في بيوت آبائه؛ لأنهم يحاربون المنكرات التي دخلت البيوت التي أفسدت قلوب الناس، نرجو توجيهكم.","title":"الحث على الصبر في الدعوة إلى الله","answer":"الجواب:\nعليه أن يصبر، على الشباب، وعلى غير الشباب أن يصبر، إذا دخل البلاء البيت عليه أن يصبر، هذا زمان الصبر، وزمان الفتن والمحن، عليه أن يصبر، ويجاهد حسب طاقته، ويسأل الله العون على ذلك. وإذا استطاع أن يستقل بنفسه في بيت وحده إذا لم يستجيبوا له، ولم يطاعوه على إزالة المنكرات، فلا مانع أن يستقل إن استطاع في بيت وحده، وإذا لم يستطع فليجاهد، وليتق الله، ولا يكلف الله نفسًا إلا وسعها، ولا يحضر المنكر. فدرجات إنكار المنكر ثلاث: اليد، ثم اللسان، ثم القلب، الأول بيده إذا استطاع، إذا كان رب البيت هو يستطيع أن يفعل ما يقدر عليه، وإذا كان ليس هو رب البيت، بل مجبور معه آباؤه، معه أبوه وإخوانه الكبار؛ فلينكر ما استطاع بلسانه، فإن لم يستجيبوا؛ أنكر بقلبه، فإن استطاع أن يفارق، ويستقل في بيت فعل ذلك، فهو جهاد هذه الحياة، حياة الجهاد، ودار الجهاد، فلا بدّ من الصبر، ولا بدّ من المجاهدة حسب الطاقة، فاتقوا الله ما استطعتم .  السؤال: يعتبر هذا في الجهاد؟ الجواب: ما في شك، إنكار المنكرات من الجهاد.","link":"https://binbaz.org.sa/fatwas/975/الحث-على-الصبر-في-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_04.mp3","categories":["الدعوة والدعاة"]},{"id":5684,"question":"نحن نسمع هذه المحاضرات القيمة، ولكن ليس بأيدينا حولٌ ولا طول، لكن من للنوادي والمسلسلات والفيديوهات وما ينضم إليها التي أفسدت الدنيا والدين معًا؟","title":"الواجب على المسلم تجاه الفساد","answer":"الجواب:  على طالب العلم أن يبذل وسعه، ويفعل ما يستطيع مع العلماء، ومع ولاة الأمور، ومع من له شأن في هذه المسائل، بالكتابة، والمناصحة، والتوجيه، والصحافة، وفي الخطابة، وفي الاتصالات الخاصة، وهذا هو الواجب، وهذا هو الجهاد في إصلاح وسائل الإعلام، وفي غير ذلك. أما السكوت فليس بعلاج، إنما العلاج الكلام الطيب، والأسلوب الحسن في إنكار المنكر، وفي الدعوة إلى الخير، وفي بيان العلاج، وفي بيان الداء والدواء، تذكر الداء، وأضراره، وخطره، وتذكر معه الدواء حسب علمك، وقد تخطئ وتصيب، والآخر يخطئ ويصيب، فيجتمع الصواب، ويترك الخطأ، فلا وجه للسكوت. بل يجب على طالب العلم أن يكتب، وأن يتكلم بحدود ما شرع الله له في خطبته، في مجتمعاته مع إخوانه، في مدرسته في تعليمه للأولاد إذا كان أستاذًا، في غير ذلك من الوجوه يعلم ما شرع الله، ويعلم ما أمر الله به ورسوله، وينهى عما نهى الله عنه ورسوله، ويناصح، ويكتب إلى المسؤولين حسب علمه، ويتثبت، ولا يقدم إلا على علم يتعلم، ويتفقه، ويشاور أهل العلم حتى يكون على بينة. فإذا كان على بينة، فليكتب، ولينصح، وليوجهه، وليستعن بالله  وقد قال النبي -عليه الصلاة والسلام-: الدين النصيحة، الدين النصيحة وبايع النبي ﷺ جرير بن عبدالله البجلي على النصح لكل مسلم، فالنصح يكون بالكلام، والكتابة، ويكون بالفعل، والعمل الصالح، ويكون بالخطب، ويكون بغير ذلك من وجوه النصح.","link":"https://binbaz.org.sa/fatwas/1005/الواجب-على-المسلم-تجاه-الفساد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_32.mp3","categories":["الدعوة والدعاة"]},{"id":5688,"question":"السؤال الثاني: ما واجب الشباب المسلم في بيته من شأن التلفاز عندما يدخل البيت، ويشاهد أغنية في التلفاز، فهل يذهب إلى التلفاز، ويقفله؟","title":"الواجب على من رأى منكرا في بيته","answer":"الجواب: الواجب على الشباب، وغير الشباب، على الشباب، وعلى الشيب كلهم، الواجب على الجميع إنكار المنكر، ولا يختص هذا بالشباب.  فعلى الرجل والمرأة، والكبير والصغير عليهم جميعًا، وعلى حسب تقواهم لله، وغيرتهم لله يكون الواجب أكبر، فمن عرف دين الله، وعرف ما أوجب الله عليه صار واجبه أكبر، فإذا وجد أغنية قفل التلفاز، أو المذياع، أو الفيديو قفل ذلك إذا استطاع، أو نصح إذا لم يستطع، نصح أهله، ونصح والده، ونصح إخوته، وحثهم على تقوى الله، فإن أجابوا وإلا خرج، ولم يحضر معهم المنكر، هذا هو الواجب عليه.","link":"https://binbaz.org.sa/fatwas/999/الواجب-على-من-راى-منكرا-في-بيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_28.mp3","categories":["الدعوة والدعاة"]},{"id":5693,"question":"نحن نسمع هذه المحاضرات القيمة، ولكن ليس بأيدينا حولٌ ولا طول، لكن من للنوادي والمسلسلات والفيديوهات وما ينضم إليها التي أفسدت الدنيا والدين معًا؟","title":"الواجب على المسلم تجاه الفساد","answer":"الجواب:  على طالب العلم أن يبذل وسعه، ويفعل ما يستطيع مع العلماء، ومع ولاة الأمور، ومع من له شأن في هذه المسائل، بالكتابة، والمناصحة، والتوجيه، والصحافة، وفي الخطابة، وفي الاتصالات الخاصة، وهذا هو الواجب، وهذا هو الجهاد في إصلاح وسائل الإعلام، وفي غير ذلك. أما السكوت فليس بعلاج، إنما العلاج الكلام الطيب، والأسلوب الحسن في إنكار المنكر، وفي الدعوة إلى الخير، وفي بيان العلاج، وفي بيان الداء والدواء، تذكر الداء، وأضراره، وخطره، وتذكر معه الدواء حسب علمك، وقد تخطئ وتصيب، والآخر يخطئ ويصيب، فيجتمع الصواب، ويترك الخطأ، فلا وجه للسكوت. بل يجب على طالب العلم أن يكتب، وأن يتكلم بحدود ما شرع الله له في خطبته، في مجتمعاته مع إخوانه، في مدرسته في تعليمه للأولاد إذا كان أستاذًا، في غير ذلك من الوجوه يعلم ما شرع الله، ويعلم ما أمر الله به ورسوله، وينهى عما نهى الله عنه ورسوله، ويناصح، ويكتب إلى المسؤولين حسب علمه، ويتثبت، ولا يقدم إلا على علم يتعلم، ويتفقه، ويشاور أهل العلم حتى يكون على بينة. فإذا كان على بينة، فليكتب، ولينصح، وليوجهه، وليستعن بالله  وقد قال النبي -عليه الصلاة والسلام-: الدين النصيحة، الدين النصيحة وبايع النبي ﷺ جرير بن عبدالله البجلي على النصح لكل مسلم، فالنصح يكون بالكلام، والكتابة، ويكون بالفعل، والعمل الصالح، ويكون بالخطب، ويكون بغير ذلك من وجوه النصح.","link":"https://binbaz.org.sa/fatwas/1005/الواجب-على-المسلم-تجاه-الفساد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_32.mp3","categories":["الدعوة والدعاة"]},{"id":5698,"question":"السؤال الثاني: ما واجب الشباب المسلم في بيته من شأن التلفاز عندما يدخل البيت، ويشاهد أغنية في التلفاز، فهل يذهب إلى التلفاز، ويقفله؟","title":"الواجب على من رأى منكرا في بيته","answer":"الجواب: الواجب على الشباب، وغير الشباب، على الشباب، وعلى الشيب كلهم، الواجب على الجميع إنكار المنكر، ولا يختص هذا بالشباب.  فعلى الرجل والمرأة، والكبير والصغير عليهم جميعًا، وعلى حسب تقواهم لله، وغيرتهم لله يكون الواجب أكبر، فمن عرف دين الله، وعرف ما أوجب الله عليه صار واجبه أكبر، فإذا وجد أغنية قفل التلفاز، أو المذياع، أو الفيديو قفل ذلك إذا استطاع، أو نصح إذا لم يستطع، نصح أهله، ونصح والده، ونصح إخوته، وحثهم على تقوى الله، فإن أجابوا وإلا خرج، ولم يحضر معهم المنكر، هذا هو الواجب عليه.","link":"https://binbaz.org.sa/fatwas/999/الواجب-على-من-راى-منكرا-في-بيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_28.mp3","categories":["الدعوة والدعاة"]},{"id":5699,"question":"إذا كان الوالد يترك صلاة الفجر، هل يهجره؟","title":"الواجب نحو الوالدين إذا قصرا في الطاعة","answer":"الجواب: ينصحه ويدعوه إلى الخير، الوالد ما هو مثل غيره، حتى لو كافرًا كفرًا أكبر دون هذا أكبر من هذا، الوالد له حق حتى قال الله: وَإِن جَاهَدَاكَ عَلى أَن تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفاً [لقمان:15] فأمر بمصاحبتهما بالمعروف، مع كونهما يجاهدان الولد على الشرك. فالحاصل: أن الوالد والوالدة لهما حق صلتهم، والإحسان إليهم، والرفق بهم، ولو كانوا على معصية وكفر، لكن لا يطاعون في الكفر، إنما الطاعة في المعروف، لكن تحسن إليهما، وترفق بهما، وتدعوهما إلى الله، وتصبر عليهما.  وإذا كان ما يصلي في الجماعة الفجر تنصحه، تقول: صل مع الجماعة بالكلام الطيب، والأسلوب الحسن، تخوفه من الله -جل وعلا- ولو والدك لا تستحي، ولا تحتقر نفسك، تقول له: يا أبتِ هذا كذا، ويا أبتِ الواجب عليك كذا، وأنت يرجى لك الخير -إن شاء الله- بادر إلى صلاة الجماعة، ولا تتساهل تنصحه. السؤال: هؤلاء يقومون يصلون في بيوتهم، ما يحضرون إلى المسجد؟ الجواب: ينصحون، والذي يصلي في بيته أسهل من الذي يتركها.  السؤال: .........؟ الجواب: ولو، لا تعجز؛ أبوك له حق عليك كبير. السؤال: بالنسبة للأقارب؟ الجواب:  الأقارب الحمد لله لك هجرهم إذا ما أطاعوك اهجرهم.","link":"https://binbaz.org.sa/fatwas/991/الواجب-نحو-الوالدين-اذا-قصرا-في-الطاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_20.mp3","categories":["الدعوة والدعاة"]},{"id":5713,"question":"توجد مجلات خليعة قد انتشرت بأيدي الشباب تحمل دعاية للدخان، وتجعل جوائز مغرية، وتحمل دعاية للخلاعة، والمجون، فهل هناك موصد، ورادع ورقابة مخلصة غير الرقابة الحالية؟","title":"خطورة المجلات الخليعة والواجب نحوها","answer":"الجواب: يجب هذا، توجد هذه الأشياء فيجب على الكتاب أن يكتبوا، وأن ينكروا، وعلى العلماء أن يبلغوا، وعلى من وجد شيئًا أن يبلغ أيضًا؛ لأن العالم، والكاتب قد يغفل قد يفوته شيء، فالذي يرى شيئًا، وينبغي أن يكتب فيه، ولا يرى أنه أنكر، ولا بين، ينبغي له أن يكتب لأهل العلم، ويذكرهم حتى ينكروا ذلك، حتى يحصل التعاون بين العالم، والطالب، وبين عيال المسلمين وبين الدولة أيضًا.  فالتعاون واجب بين الدولة، وبين العلماء، وبين أعيان المسلمين في كل مكان في هذه البلاد، وفي غيرها، ولا يجوز السكوت أبدًا، فالناس بخير ما تعاونوا، وكتبوا وتناصحوا ، أما إذا سكتوا فهذا هو عنوان الشر -والعياذ بالله- والبلاء.","link":"https://binbaz.org.sa/fatwas/1025/خطورة-المجلات-الخليعة-والواجب-نحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_47.mp3","categories":["الدعوة والدعاة"]},{"id":5724,"question":"الواجب على العلماء قول الحق، ولا يخافون في الله لومة لائم، فلماذا لا تظهر نتائجهم حيث نرى أن الفساد يزداد؟","title":"واجب العلماء تجاه الفساد","answer":"الجواب: الواجب قول الحق، ولكن ليس من شرطه أن يقبل، وقول الحق بحمد الله يقال ويبين، ولكن ليس كل ما يقال تظهر آثاره، ويستجاب لقائله لأسباب كثيرة.","link":"https://binbaz.org.sa/fatwas/1034/واجب-العلماء-تجاه-الفساد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_56.mp3","categories":["الدعوة والدعاة"]},{"id":5729,"question":"بعض الإخوة يقول: إنه دائمًا يقول للأولاد صلوا صلوا صلوا، وفي مرة من المرات ضربوه، أوسعوه ضربًا حتى حمله بعض الناس إلى بيته وهو مريض؛ بسبب يعني دعوته للأولاد الذين يلعبون الكرة في الشارع؟","title":"توجيه لمن تعرض للضرب بسبب أمره بالمعروف","answer":"الجواب: على كل حال هو مأجور، وله ثواب عظيم، وإن كان قد ضرب فقد قتل بعض الأنبياء، ما هو بس الضرب، بعض الأنبياء قد قتلوا بغير حق، كما قال الله -جل وعلا- قال فيهم سبحانه: وَيَقْتُلُونَ الِّذِينَ يَأْمُرُونَ بِالْقِسْطِ مِنَ النَّاسِ [آل عمران:21]، فله سلف بالأخيار من الأنبياء، والصالحين. ولكن عليه أن يشتكيهم إلى ولاة الأمور، إلى رؤساء الهيئة حتى يعاقبوا، لا يسكت؛ لأنهم إذا تجرؤوا عليك تجرؤوا على غيرك، فلا بدّ من رفع الشكوى إلى ولاة الأمور في هذا الأمر، وإن اتصل بي، أو كتب إلي أنا -إن شاء الله- أقوم باللازم في هذا، وإن تقدم إلى إدارة الهيئة هو ما يقصر إن شاء الله ... هم ما يقصرون في هذا، هذا أمر عظيم .. ما ينبغي السكوت عنه. السؤال: لو راح إلى هيئة الأمر بالمعروف ما تقوم معه؟ الجواب: بلى؛ يقومون معه، يكتب للهيئة، أو للأمير سلمان، أو لوزير الداخلية، أو نائبه، كل هؤلاء -إن شاء الله- يقومون باللازم، لكن لا يتساهل، يتابع الموضوع، ما هو من أجل نفسه، يتابع الموضوع لئلا يعتدوا على غيره. وإلا هو مأجور -إن شاء الله- ولا يضره ذلك.","link":"https://binbaz.org.sa/fatwas/1038/توجيه-لمن-تعرض-للضرب-بسبب-امره-بالمعروف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_60.mp3","categories":["الدعوة والدعاة"]},{"id":5830,"question":"التيمم هل الترتيب بالتيمم بين الوجه، والكفين واجب؟","title":"حكم الترتيب في أعضاء التيمم","answer":"الجواب:  على ظاهر الكتاب العزيز فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ [النساء:43] وفي حديث عمار مسح بوجهه، وكفيه، فالواجب أن يبدأ بالوجه، ثم الكفين.  أما في الجنابة فالأمر واسع، التيمم عن الجنابة أمره واسع، لكن الأفضل يبدأ بالوجه، ثم الكفين حتى في الجنابة، أما في الوضوء فالواجب أن يبدأ بالوجه؛ لأن هذا هو المنصوص عليه في كتاب الله، وهو الذي جاء في بعض الروايات، فتفسر الروايات بعضها بعضًا، وتحمل الروايات على ما دل عليه كتاب الله، وقد قال رسول الله: نبدأ بما بدأ الله به في الصفا، والمروة، فهكذا يبدأ بما بدأ الله به في الوضوء، وفي التيمم، هذا الذي ينبغي للمؤمن.","link":"https://binbaz.org.sa/fatwas/1179/حكم-الترتيب-في-اعضاء-التيمم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_175.mp3","categories":["التيمم","الدعوة والدعاة"]},{"id":5867,"question":"يوجد بعض المجاورين للمساجد، وغير المجاورين، ولا يشهدون الصلاة، فلماذا لا يؤكد على أئمة المساجد المتساهلين بالرفع عنهم إلى الجهة المختصة؟","title":"ما كيفية مناصحة تاركي الصلاة المجاورين للمساجد؟","answer":"الجواب: نسأل الله أن يعينهم هذا كثير، والمنكرات إذا كثرت قل القيام بواجب الإنكار لها، ولكن نسأل الله أن يعين الهيئات، والأئمة على القيام بواجبهم؛ لأن التاركين للصلاة في  الجماعة كثروا جدًا حتى شق على الأئمة تتبعهم، والعناية بهم، وحتى قل أن يوجد من يساعدهم من الهيئات على رد هؤلاء إلى الحق، وعلى قيامهم بأمر الله، فنسأل الله أن يعين المسؤولين، وأن يعيذهم من الكسل، والضعف، وأن يمنحهم التوفيق، والهداية، والشجاعة لإقامة الحق، ونصر الحق، والدعوة إليه، ولا شك أن هؤلاء الذين يدعون الصلاة في الجماعة قد أتوا منكرًا، وشابهوا أعداء الله المنافقين، وأحدثوا حدثًا في الإسلام يضر المسلمين. فالواجب على من له قدرة من آبائهم، وإخوانهم، وجيرانهم أن ينصحهم، وأن يرفع بأمرهم عند الامتناع إلى ولاة الأمور إلى الهيئة؛ لعلها تفعل ما تستطيع في دعوتهم إلى الحق، وإلزامهم بالحق، ووعيدهم إذا تخلفوا بالسجن، والأدب.  ومتى تكاتف الأولياء أولياء الأمور، أي أولياء الأولاد، وأشباههم من آباء، وإخوة كبار، ونحو ذلك، متى تكاتفوا مع الهيئات في هذا، ومع أئمة المساجد يحصل الخير الكثير -إن شاء الله- لكن نسأل الله أن يهديهم؛ حتى ينكروا المنكر، وحتى يرفعوا أمر المتخلفين، وحتى يتساعدوا مع الهيئة في هذا الأمر العظيم.","link":"https://binbaz.org.sa/fatwas/1215/ما-كيفية-مناصحة-تاركي-الصلاة-المجاورين-للمساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_212.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":5981,"question":"بر الوالدين واجب، وقد ورد ذكر بر الوالدين في آيات كثير من القرآن الكريم، ولكن إذا كان أحد الوالدين قاسيًا على ولده، وخرج منه، وقد أخذ الوالد يدعو عليه، هل يعتبر خروجه منه معصية، وعقوقًا لوالديه، أم لا؟","title":"هل يجوز الخروج على الوالد القاسي في معاملته؟","answer":"الجواب: هذا المقام فيه تفاصيل، وتقدم لكم أن الوالد له حق عظيم، والوالدة كذلك، وأنه ينبغي للوالد أن لا يكون  قاسيًا، ولا شديدًا، بل يكون لطيفًا رحيمًا؛ حتى يعين أولاده على بره، ويعينهم على بره بعبارته الطيبة، ولينه، وعدم قسوته.  ولكن بعض الأولاد أيضًا شر، بعض الأولاد شر يدعون إلى الشر، وهكذا بعض الزوجات كما قال الله -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّ مِنْ أَزْوَاجِكُمْ وَأَوْلَادِكُمْ عَدُوًّا لَكُمْ فَاحْذَرُوهُمْ [التغابن:14] وقال: إِنَّمَا أَمْوَالُكُمْ وَأَوْلَادُكُمْ فِتْنَةٌ [التغابن:15] فهم فتنة، يعني اختبار، وامتحان، قد يختبر الله الآباء، والأمهات في أولادهم، فإن نصحوا لهم، ووجّهوهم إلى الخير؛ أثابهم الله، وإن تساهلوا معهم في المعاصي، والسيئات؛ استحقوا العقاب من الله .  والأولاد، والزوجات أيضًا قد يكونون شرًّا، قد تكون الزوجة شرًّا على زوجها، تدعوه إلى الباطل، تدعوه إلى الفساد، والمعاصي، وهكذا الولد قد يكون خبيثًا، يدعو والده إلى الشر، والبلاء، والفساد؛ فيجب على الوالد أن يحذر، وألا ينساق مع أولاده وأن لا ينساق مع زوجاته فيما لا ينبغي، بل ينظر فيما يدعون إليه ويختار الطيب، ولا يختار الخبيث.  إذا دعت الزوجة إلى شيء فلا يسارع إلى إجابتها حتى ينظر النتيجة، وهل هذا شيء يرضي الله، هل هو جائز، وما عاقبته، فيختار من ذلك ما فيه الخير، والعاقبة الحميدة، ولا يضره ذلك.  وهكذا الولد قد يكون شرًا، قد يكون فاسدًا، قد يكون منافقًا، قد يكون كافرًا يتلبس بالإسلام، فليحذر هذا الولد، ولا يأخذ من كلامه، ولا من دعوته، ولا من طلباته إلا ما كان يرضي الله، ومما أباح الله  ومما يرجو فيه العاقبة الحميدة حتى لا يقع في شر مما حذر الله منه. فإذا قال له أبوه، فإذا فعل معه أبوه ما يوجب الخروج، وخرج؛ فلا بأس، إذا كان والده ضيق عليه، وضيق على زوجته، ولم يمكنهما مما ينبغي مما أباح الله لهما لسوء خلق الوالد، فلا ينبغي له، بل يعالج الأمور بالتي هي أحسن، يرفق بوالده ويقول: يا والدي ارفق بنا أرجو أن تفعل كذا، وكذا، وإلا فاسمح لنا أن نخرج من هذا البيت إلى بيت آخر، يخاطبه بالتي هي أحسن، فإن استطاع أن يجلس مع والديه، ويرفق بهما؛ فهذا هو المطلوب، وهذا هو الذي ينبغي له، وإن لم يتيسر ذلك؛ لشدة الوالد، ولأنه يعامله معاملة قاسية تضره في دينه، ودنياه، وربما سببت عليه انحرافه عن الهدى، وربما سببت أيضًا عقوقه لوالده ووقوعه فيما حرم الله؛ فليخرج، وليعامل والديه بالتي هي أحسن، ولو دعوا عليه يرفق بهما، ويعاملهما بالتي هي أحسن، ويجتهد في برهما، وإرضائهما.","link":"https://binbaz.org.sa/fatwas/1355/هل-يجوز-الخروج-على-الوالد-القاسي-في-معاملته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_312.mp3","categories":["الدعوة والدعاة","الآداب والأخلاق"]},{"id":5985,"question":"ما حكم إذا صام الإنسان أيام البيض، وفي أثناء الصوم حلف أحد الأبوين بأن يفطر، فهل يفطر، أم يكمل الصوم؟","title":"حكم طاعة الوالدين في ترك أعمال مستحبة","answer":"الجواب: بر الوالدين واجب، وصوم البيض مستحب، فلا يقدم المستحب على الواجب، إذا كان والداه يعطفان عليه، ويخافان عليه؛ لأنه في وقت شدة الحر، أو ما أشبه ذلك، أو لأنه يعطل أسبابًا تنفعهم، يعطل ما ينفعهم ويحتاجون إليه من حاجات البيت من البيع، والشراء، والحرث، والفلاحة، ونحو ذلك، وهم في حاجة إلى ذلك. فالمقصود: إذا كان قصدهما خيرًا، وطيبًا فليجبهما، ولا يصم النافلة؛ لأن النافلة مستحبة، وبرهما واجب، والواجب مقدم على المستحب. السؤال: إذا كان المقصود العاطفة على الابن؟ الجواب: ولو ولو ، إذا كان الصوم يشوش عليهما، وربما أفضى إلى أن يقطعاه، ويغضباه عليه فليتق الله.","link":"https://binbaz.org.sa/fatwas/1356/حكم-طاعة-الوالدين-في-ترك-اعمال-مستحبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_313.mp3","categories":["الدعوة والدعاة","الآداب والأخلاق"]},{"id":6000,"question":"ما رأي فضيلتكم في عدم تحرك العلماء، وقول لكلمتهم في وسائل الإعلام، وتوجيه المسلمين، وكذلك عزل العلماء عن الحكام؟","title":"دعوة للعلماء باستغلال وسائل الإعلام لنشر العلم","answer":"الجواب:  كل هذا مثل ما تقدم يجب على العالم أن يبذل وسعه، وقد وقع بحمد الله الكثير من هذا الشيء، كثير من أهل العلم قد بينوا، وأوضحوا، وكتبوا، وبينوا في الإذاعة، والتلفاز، والصحف، بينوا الكثير، ولكن أين المستفيد؟ لا من العامة، ولا من الخاصة. ولكن ليس هو على المستوى الأكمل، بل الحاجة تدعو إلى أكثر من ذلك، ندعو إلى أن بقية أهل العلم يقومون أيضًا، وهذه الأمور فرض كفاية، متى قام بها من يكفي في إيضاح الحق؛ كفى، ولكن إذا حصل .. الكثير، وتتابع العلماء في كل مكان على الدعوة إلى الله، وعلى ... صار ذلك أنفع للناس، وأكمل في هداية الناس، وتنبيههم.","link":"https://binbaz.org.sa/fatwas/1399/دعوة-للعلماء-باستغلال-وساىل-الاعلام-لنشر-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_354.mp3","categories":["الدعوة والدعاة"]},{"id":6018,"question":"ما حكم قراءة الفاتحة في الصلاة السرية، والجهرية مع ذكر الترجيح لديكم؟","title":"حكم قراءة الفاتحة في الصلاة السرية والجهرية","answer":"الجواب:  قراءة الفاتحة فرض على الإمام، والمنفرد، النبي -عليه الصلاة والسلام- قال: لا صلاة لمن لم يقرأ بفاتحة الكتاب وقال -عليه الصلاة والسلام-: من صلى صلاة لم يقرأ فيها بفاتحة الكتاب؛ فهي خداج، فهي خداج غير تمام هذا الذي عليه جمهور أهل العلم، فرض على الإمام، والمنفرد.  لكن اختلفوا في المأموم هل تجب عليه، أم لا؟ على أقوال ثلاثة: قال بعضهم: تجب على المأموم في السرية، دون الجهرية، وقال بعضهم: تجب عليه مطلقًا في السرية، والجهرية، وقال بعضهم: لا تجب لا في السرية، ولا في الجهرية، فهذه أقوال ثلاث، أرجحها فيما يظهر من الأحاديث الوجوب مطلقًا، هذا أظهرها، ولا ينبغي تركها للمأموم، كما أنه لا يتركها الإمام، والمنفرد، بل يقرأها المأموم، ولو على قراءة الإمام، يقرأها في نفسه، ثم ينصت، والظهر، والعصر، والمغرب، والعشاء، والفجر في السرية ظاهر، وفي الجهرية يقرأها بعد الإحرام، بعد الفاتحة بحسب ما تيسر له مع الإمام.","link":"https://binbaz.org.sa/fatwas/1375/حكم-قراءة-الفاتحة-في-الصلاة-السرية-والجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_333.mp3","categories":["القراءة في الصلاة","الدعوة والدعاة"]},{"id":6026,"question":"ما حكم قراءة الفاتحة في الصلاة السرية، والجهرية مع ذكر الترجيح لديكم؟","title":"حكم قراءة الفاتحة في الصلاة السرية والجهرية","answer":"الجواب:  قراءة الفاتحة فرض على الإمام، والمنفرد، النبي -عليه الصلاة والسلام- قال: لا صلاة لمن لم يقرأ بفاتحة الكتاب وقال -عليه الصلاة والسلام-: من صلى صلاة لم يقرأ فيها بفاتحة الكتاب؛ فهي خداج، فهي خداج غير تمام هذا الذي عليه جمهور أهل العلم، فرض على الإمام، والمنفرد.  لكن اختلفوا في المأموم هل تجب عليه، أم لا؟ على أقوال ثلاثة: قال بعضهم: تجب على المأموم في السرية، دون الجهرية، وقال بعضهم: تجب عليه مطلقًا في السرية، والجهرية، وقال بعضهم: لا تجب لا في السرية، ولا في الجهرية، فهذه أقوال ثلاث، أرجحها فيما يظهر من الأحاديث الوجوب مطلقًا، هذا أظهرها، ولا ينبغي تركها للمأموم، كما أنه لا يتركها الإمام، والمنفرد، بل يقرأها المأموم، ولو على قراءة الإمام، يقرأها في نفسه، ثم ينصت، والظهر، والعصر، والمغرب، والعشاء، والفجر في السرية ظاهر، وفي الجهرية يقرأها بعد الإحرام، بعد الفاتحة بحسب ما تيسر له مع الإمام.","link":"https://binbaz.org.sa/fatwas/1375/حكم-قراءة-الفاتحة-في-الصلاة-السرية-والجهرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_333.mp3","categories":["القراءة في الصلاة","الدعوة والدعاة"]},{"id":6028,"question":"ما عرفنا معنى الإنكار بالقلب؟","title":"كيفية إنكار المنكر بالقلب","answer":"الجواب:","link":"https://binbaz.org.sa/fatwas/1434/كيفية-انكار-المنكر-بالقلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_371.mp3","categories":["الدعوة والدعاة"]},{"id":6048,"question":"هل قراءة آية إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ [الأحزاب:56] في كل خطبة بدعة؟ وهل آية إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ [النحل:90] حيث إن الخطباء يداومون على قراءة هذه الآيات؟","title":"حكم مداومة الخطيب على: {إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ}","answer":"الجواب: ما أعلم شيئًا في هذا؛ لأن هذا حث على الصلاة على النبي ﷺ ودعوتهم إلى الصلاة على النبي -عليه الصلاة والسلام- لأن الآية جامعة: إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ [النحل:90]، آية جامعة فيها خير عظيم، وتنبيه للمسلمين، فهذا من الوعظ.","link":"https://binbaz.org.sa/fatwas/1459/حكم-مداومة-الخطيب-على-ان-الله-وملاىكته-يصلون-على-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_388.mp3","categories":["الدعوة والدعاة","صلاة الجمعة"]},{"id":6059,"question":"السؤال الأول:هل دعوة غير المسلمين للدخول في الإسلام واجبة على المسلمين؟ وكيف يمكن تطبيق ذلك؟","title":"حكم دعوة غير المسلمين إلى الإسلام","answer":"الجواب: نعم، الدعوة إلى الله لغير المسلمين واجبة وَادْعُ إِلَى رَبِّكَ [الحج:67] هذا إلى غير المسلمين، المسلمين  قد دخلوا في الإسلام، لكن يحتاجون إلى مزيد من الخير، وأما الكافر فهو أشد الناس حاجة إلى هذا، وأعظمهم حاجة إلى أن يدعى، وأن يبصر بلغته التي يعرفها، أو بالترجمة إذا كنت لا تعرف لغته.  فالمشركون من عباد الأوثان، ومن النصارى، ومن غيرهم حتى اليهود إذا أمكن أن يدعوا إلى الله، دعوا إلى الله، حتى الشيوعيين إذا أمكن بالحكمة، والكلام الطيب هذا مطلوب، فجميع أهل الأرض من جميع الكفرة كلهم يجب أن يدعوا إلى الله، إذا تمكن الداعي إلى الله، وصار عنده القدرة على ذلك، وجبت الدعوة إلى الله لهؤلاء الذين هم ... كما يدعى المسلم إلى الله فيما جهل، أو فيما تكاسل فيه.","link":"https://binbaz.org.sa/fatwas/1470/حكم-دعوة-غير-المسلمين-الى-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_400.mp3","categories":["الدعوة والدعاة"]},{"id":6060,"question":"هل الإنسان إذا رأى منكرًا، أو شيئًا يستطيع أن يغيره، ولكنه يخشى على نفسه، فهل تبرأ ذمته؟","title":"حكم من رأى منكراً ولم يغيره خوفاً على نفسه","answer":"الجواب: إذا كان لا يستطيع ينكر بالقول هذا ما يصلح، هذه المجلة دعها عنك، هذه فيها شر، هذا الكتاب لا تطالع الكتاب، رأيت الكتاب الفلاني، ترشده بالكلام الطيب، رأيت معه مجلة خبيثة تنفعه: عندك مجلة المجتمع، مجلة كذا،  مجلة الدعوة، ترشده إلى المجلات الطيبة، إذا رأيت معه جريدة رديئة تقول له: دع هذه عنك، رأيت معه كتابًا يضر تنصحه من ذلك. هكذا المؤمن، ولا يكلف نفسه ما لا يطيق، ولا يضاربه، ولا يفعل شيئًا يجر على نفسه شرًا؛ ولكن بالكلام الطيب كما أمر الله بذلك، يدعو إلى الله بالحكمة، الحكمة، العلم، والموعظة الحسنى، وجادلهم بالتي هي أحسن .. إلا الذين ظلموا إذا ظلم المدعو؛ جاز أن يخاطب بالعنف، والشدة، فمثل ما سمعتم من المشايخ، اللين له محل، والشدة لها محل، فالأصل هو اللين، والأصل هو الرفق، والحكمة، فمن حرم الرفق؛ فقد حرم الخير كله، هذا هو الأصل في الدعوة، والتعليم، لكن إذا تعدى المدعو الحدود، وتجاوزها، وظلم؛ فإنه يخاطب بالذي يليق به من الشدة، والتقريع، والتوبيخ، وقد يحتاج إلى تأديبه إذا أساء القول، وأساء العمل، وقدر على تأديبه حتى يتقوم، وحتى يصلح هذا مطلوب.","link":"https://binbaz.org.sa/fatwas/1471/حكم-من-راى-منكرا-ولم-يغيره-خوفا-على-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_401.mp3","categories":["الدعوة والدعاة"]},{"id":6061,"question":"يلاحظ أن هناك ندرة فيمن يزور المساجد في أنحاء البلاد، يدعو إلى الله، وهذا لا تخفى أهميته؛ لأن أكثر الناس لا يأتي إلى أمثال هذه الندوات، وإنما يحتاج إلى أن يأتيه الدعاة في المساجد المختلفة، كما كان يحدث فيما مضى، ويزداد هذه أهمية في الأيام التي كثرت فيها الفتن والمضلات، نرجو تعليق سماحتكم على هذا الموضوع، وجزاكم الله خير الجزاء؟","title":"نصيحة للدعاة بالسعي في دعوة الناس وإرشادهم","answer":"الجواب: هذا حق، وواجب -كما تقدم- في جميع مساجد الدنيا، حق على العلماء، نسأل الله أن يكثرهم، حق عليهم أن يسعوا في الأرض، والدعوة إلى الله، ويسألهم الناس في المساجد، وفي غير المساجد، في الاجتماعات الأخرى، والندوات التي تعقد خارج المساجد، هذه يجب على العلماء أن ينتهزوا الفرصة في كل مكان للدعوة إلى الله  وإرشاد الناس إلى الخير؛ حتى يكثر الخير، وحتى يقل الشر.  هذا واجب على الجميع كما تقدم، وعلى من ولي هذه الأمور أن يسعى في هذا الأمر، وأن يجتهد في إيصال الخير إلى الناس في كل مكان، نسأل الله أن يعيننا على كل خير.","link":"https://binbaz.org.sa/fatwas/1472/نصيحة-للدعاة-بالسعي-في-دعوة-الناس-وارشادهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_402.mp3","categories":["الدعوة والدعاة"]},{"id":6079,"question":"إن مناخنا اليوم قد عمته البلوى، والفساد، والبدع، والمنكرات؛ فكيف نصلح هذا المناخ؟ وإلى متى، ونحن نضع رؤوسنا في التراب؟","title":"ضرورة الدعوة إلى الله","answer":"الجواب: المناخ محل العمل، ومحل الدعوة، ومحل التوجيه، فالواجب على من عنده علم أن يبذل له في الخطابة، والكتابة، والمحاضرات حتى يسعى في نشر دين الله، وحتى يقوم بنصيبه من ذلك، ولا يضع رأسه في التراب، ولا يخفي نفسه، بل الواجب على كل من لديه علم أن يعمل، ويجتهد، ويقول الحق، وينشر الحق.  وقد وجد -بحمد الله الآن- من يقوم بهذا، ومن يسعى لهذا في دول كثيرة، وفي أماكن كثيرة، يسعون لنشر دين الله، ويتعلمون، ويتفقهون في كليات لا تعلم الدين، بل تعلم الهندسة، وتعلم الطب، وتعلم كذا وكذا، فظهر بين طلابها طلاب أخيار، ينشدون دين الله، وينصرون الحق، ويدعون إليه، فضلًا عن الطلاب الذين يكونون في الكليات الأخرى من جهة الشريعة، وأصول الدين، وكليات الدعوة إلى غير ذلك. وهناك آخرون ليسوا في كليات، بل تعلموا في المساجد، وتعلموا من أهل العلم، وقرؤوا كتاب الله، ودرسوا ما تيسر من سنة رسول الله -عليه الصلاة والسلام- وحضروا حلقات العلم، فاستفادوا، وكان لهم نشاط كبير في الدعوة إلى الله  وتوجيه الناس إلى الخير، وهم يزيدون بحمد الله، ويكثرون.","link":"https://binbaz.org.sa/fatwas/1497/ضرورة-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_427.mp3","categories":["الدعوة والدعاة"]},{"id":6135,"question":"أحد الإخوة يقول: إن بعض خطباء المساجد ليسوا -مضمون سؤاله يعني-: هم ليسوا على المستوى المطلوب بما يقوموا به من هذا العمل الخطير، ويعتمدون على ديوان ابن نباتة، بينما هناك كثير من رجال العلم يتمنون أن تتاح لهم الفرصة لأداء الخطبة، ولو بدون مكافأة، فما رأي سماحتكم في ذلك؟","title":"الشروط الواجب توافرها في الخطيب","answer":"الجواب: على كل حال يوجد من أئمة المساجد، وخطباء الجمع من ليس تتوفر فيه القدرة على الخطب المفيدة الكافية، ولكن هذا كما قال ربنا : فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ويقول الناس على ما جاء في الأحاديث... فليس كل مكان... فيه العلماء الذين لهم الميزة، ولهم القدرة على الخطبة الكافية، ولهذا يحتاج الناس إلى طالب في الثانوي، بعض الأحيان طالب في المتوسط، وبعض الأحيان الذي إنما حضر جلسات العلماء، فيستفاد منه، ويولى الخطبة للحاجة، يعني لشدة الحاجة، ولعدم من يقوم مقامه.  فهذه المسائل الإمامة، والخطابة على كل حال يعتنى فيها بالأفضل، فالأفضل، ويلتمس فيها الأفضل، فالأفضل، حسب الطاقة، ولا يجب أن يكون من أكبر العلماء على حسب ما تيسر؛ لأن العلماء قد يتأخر كثير منهم عن الخطابة لأسباب كثيرة، وقد يكون بعضهم بعيد عن محل الخطابة، وإن كانت السيارات متيسرة، بحمد الله. ليس الناس كلهم سواء في الرغبة في الخطابة، والحرص عليها، وإلا فوزارة الحج، والأوقاف تلتمس، وتطلب من عنده كفاية يتقدم حتى .. فهم يطلبون من يقبل على ذلك، ويستجيبون من مصر، ومن غير مصر، من يتولى ذلك عند الحاجة. فالحاصل أن كثيرًا من إخواننا ليس عندهم النشاط بالقيام في خطب الجمعة، وبإمامة المساجد، وكثير منهم لا يود ذلك، ويرى أنها تحبسه ... عن الأسفار، وعن كذا، وعن كذا، فلهذا لا تجده يوافق على الإمامة، والخطابة لهذه الأسباب التي أشير إليها، والذي يريد ذلك، ويوافق على ذلك مشكور، ومأجور، يكتب إلى الأوقاف أنه مستعد لهذا، أو يكتب لي، أو إلى من شاء من المشايخ، ونتوسط له، وندعو له، ونشكره أيضًا، ويعطى معاشًا أيضًا.","link":"https://binbaz.org.sa/fatwas/1598/الشروط-الواجب-توافرها-في-الخطيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_492.mp3","categories":["صلاة الجمعة","الدعوة والدعاة"]},{"id":6183,"question":"وآخر يسأل ما حكم نوم العصر؟","title":"حكم النوم بعد العصر","answer":"الجواب: لا نعلم فيه شيئًا، نوم العصر لا نعلم فيه شيئًا ولا حرج فيه، كل الأوقات لا نعلم فيها شيء، إلا المغرب كره النوم قبلها -عليه الصلاة والسلام- كان يكره النوم قبلها÷ أي قبل العشاء، والحديث بعدها. أما العصر، والظهر، والضحى، والصبح فليس فيه شيء، لكن يتحرى الإنسان الأوقات المناسبة إذا تيسر له الظهر، فهو أفضل من العصر، وإن تيسر له القيلولة قبل الظهر فهو أفضل، لكن بسبب الأعمال اليوم، كثير من الناس لا يحصل له قائلة، ولا ظهر؛ فلم يبق عنده إلا بعد العصر. وإذا نام أول النهار؛ فلا بأس، ولكن إذا تيسر له ألا ينام قبل النهار، بل يجلس، ويذكر الله، ويقرأ القرآن، أو في طلب العلم حتى ترتفع الشمس، ثم ينام بعد طلوعها قليلًا، يكون هذا أولى من نومه بعد الصلاة مباشرة، ولا حرج في ذلك، والحمد لله.","link":"https://binbaz.org.sa/fatwas/1641/حكم-النوم-بعد-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_532.mp3","categories":["الدعوة والدعاة","الآداب والأخلاق"]},{"id":6353,"question":"نرجو إفادتنا عن كيفية تبليغ الرسول ﷺ الرسالة إلى الجن، حيث إننا نؤمن أنه أرسل إلى الجن، والإنس معًا؟","title":"كيفية تبليغ الرسول صلى الله عليه وسلم الرسالة إلى الجن","answer":"الجواب: بلغهم مثل ما بلغ الإنس فيما سمعنا، بلغهم دعوة الله، وأرشدهم إلى ما خلقوا له من طاعة الله، وتوحيده. أما تفاصيل التكاليف فلا نعلم عنها شيئًا، والأصل أن التكاليف واحدة لنا ولهم، هذا هو الأصل من صلاة، وصوم، وحج، وغير ذلك التكاليف واحدة، القرآن للجميع، قد خاطبهم الله في سورة الرحمن في آيات كثيرات، بعد كل آية يقول: فَبِأَيِّ آلَاء رَبِّكُمَا تُكَذِّبَانِ خاطب الجن، والإنس، فالأصل أنهم مثلنا مكلفون بالصلوات، وصيام رمضان، وبالحج، وبغير ذلك. أما إن كان هناك شيء خاص لهم فلا نعلم، ما نعلم إلا ما بلغت به الإنس، وهو رسول الله إلى جميع الجن، والإنس، أما كيف بلغهم؟ وكيف خاطبهم؟ هذا لم نبلغ به، والأصل أنه خاطبهم، وبلغهم بما بلغنا، هذا هو الأصل.","link":"https://binbaz.org.sa/fatwas/1910/كيفية-تبليغ-الرسول-صلى-الله-عليه-وسلم-الرسالة-الى-الجن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_694.mp3","categories":["الدعوة والدعاة"]},{"id":6358,"question":"هل في المنقول شفعة؟ وهل للجار شفعة إذا لم يكن هناك بينهما طريق مشترك؟","title":"الشفعة في المنقول وفي الجار الذي ليس له شركة","answer":"الجواب: هذه... عند العلماء، والشيء المنقول الصحيح فيه شفعة، ولكن فيه خلاف بين العلماء، وحكم القاضي يزيل الخلاف، إذا نظر فيها القاضي، ورأى الشفعة، وعدم الشفعة؛ فهذا إليه يجتهد فيما آتاه الله من العلم، ويعمل بما يترجح عنده من القولين، وأحد القولين: أنه لا شفعة لمنقول، والثاني فيه شفعة. وأما الجار الذي ليس له شركة، فلا شفعة له، يعني جار مجرد الطريق العابر الواسع، فهذا لا شفعة له، أما إن كان بينهما طريق خاص، قد يسد بينهم، وبين الجوارين، أو الثلاثة، والأربعة فبينهما شفعة على تفاصيل عند أهل العلم، يعرفها القضاة، ويحكم فيها القضاة.","link":"https://binbaz.org.sa/fatwas/1916/الشفعة-في-المنقول-وفي-الجار-الذي-ليس-له-شركة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_700.mp3","categories":["الدعوة والدعاة","الآداب والأخلاق"]},{"id":6432,"question":"السؤال الأول:أحد الإخوة يقول: العلماء تحدثوا إلى الناس فهم مؤتمنون على قولهم، ومن ضمن ما قالوا: إننا في دولة تشجع على الأمر بالمعروف، وتعزز الآمرين، فهل لك أن تقول لي: ما دور تلك الهيئات، وما موقفها من المنكرات الظاهرة؟ أليس النساء يخرجن متبرجات، ومع أجانب يتكرر هذا المشهد كل يوم، فأين الأمر بالمعروف، والنهي عن المنكر، إلى آخر ما ورد بسؤاله الطويل؟!","title":"الأمر بالمعروف والنهي عن المنكر مسئولية الجميع","answer":"الجواب: بسم الله الرحمن الرحيم، اللهم صل، وسلم على رسوله، وعلى آله وأصحابه، أما بعد: فلا شك أن سؤال هذا السائل وارد، وأن المنكرات موجود الكثير منها، وأن المقام يحتاج إلى عناية تامة، وإلى جهود مكثفة من المسؤولين؛ للقضاء على هذه الشرور التي برزت بين الناس، بسبب كثرة الاختلاط، ووجود من لا يؤمن بالله، واليوم والآخر بين الناس، بسبب اختلاط الكفار بالمسلمين، والعصاة بغيرهم، وغلبة الجهل، وضعف الوازع الإيماني، والسلطاني، كثرت الشرور.  ولا شك أن الواجب على الهيئات واجب عظيم، وأنها مسؤولة عن تقصيرها في إزالة المنكرات، وأن على ولاة الأمور أن يحاسبوها، وأن يساعدوها؛ حتى تقوم بواجبها، وهي لا شك تبذل شيئًا من الواجب، ولكن الواجب عليها أكبر، فالواجب أن تحرض، وتساعد، وتعان من ولاة الأمور، ومن أعيان المسلمين بالزيارة للمسؤولين عن الأمر بالمعروف، والنهي عن المنكر، وتشجيعهم، وبيان ما قد يقع في بعض الحارات، أو في بعض الأحياء من الشرور التي تحتاج إلى تعاون. فإن رؤساء المراكز ليس عندهم علم الغيب، وليس عندهم القدرة الكافية في إزالة هذه المنكرات، ولكن هم في حاجة إلى التعاون من الأهالي، وسكان الأحياء، يزورون المركز، ويساعدون في القضاء على الشرور، ويشرحون له ما قد يقع عندهم مما قد يخفى عليه، وهكذا رئيس الهيئة المسؤول في كل بلد يزار، ويعاون على إنكار المنكر، وعلى القضاء على الفساد، ويشجع، ويبلغ عما قد يخفى عليه، هذا كله من باب التعاون على البر، والتقوى، والتواصي بالحق، والصبر عليه.  وعلى أيضًا العلماء أن يقوموا بواجبهم مع ولاة الأمور؛ ليعززوا جانب الأمر بالمعروف، والنهي عن المنكر، ويساعدوه بما قد يحتاج إليه، أو ينقصه من الرجال، أو غير هذا. إذا تعاون هؤلاء، وهؤلاء؛ كثر الخير، وانتشر الحق، واختفى الباطل، أو أكثره، وإذا تساهل الناس، وتغافلوا، وجعلوا الأمر على غيرهم، والحبل على غيرهم، ولم يساعدوا ولاة الأمور، ولم يساعدوا القائمين بالأمر بالمعروف، والنهي عن المنكر؛ فإن هذا يسبب انتشار الباطل، وكثرة الشر.  فالواجب على الجميع في كل حي، وفي كل بلد، وفي كل قرية أن يساعدوا الهيئات، وأن يكونوا في صف الهيئات، وأن يبلغوهم ما قد يقع، وأن يعينوهم على إزالة الشر حسب الطاقة، والإمكان، فولاة الأمور -ولله الحمد- عندهم استجابة لنداء الحق، فإذا بلغوا ما يجب، ووضح لهم الأمر؛ فهم يساعدون على إزالة الشر، وعلى إقامة الحق. والنقص لا بدّ منه، لا في هؤلاء، ولا في هؤلاء، ولكن على الجميع التعاون على البر والتقوى، وعلى إزالة النقص، أو تخفيفه، لا من ولاة الأمور، ولا من القائمين على الهيئة، ولا من عامة الناس، وأعيان الأمة، لا بدّ من التعاون، لا بدّ من التعاون في كل شيء، ولا بدّ من التواصي بالحق.","link":"https://binbaz.org.sa/fatwas/2147/الامر-بالمعروف-والنهي-عن-المنكر-مسىولية-الجميع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_795.mp3","categories":["الدعوة والدعاة"]},{"id":6461,"question":"وآخر يقول: أنا في بيئة ينتشر فيها كثير من المنكرات، ولم أر من يقوم بذلك لا سرًا، ولا جهرًا، ولم أدر هل إذا قمت بالأمر بالمعروف يتأتى علي شيء في ذلك أي مفاسد، وأنا مصر على القيام بالأمر بالمعروف، سواء كان في المساجد، أم للأفراد، فما هي الوسائل التي أتخذها؟ أرجو أن توضحوا لي ذلك؟","title":"واجب من أقام في بيئة فيها منكرات لم تنكر","answer":"الجواب:  عليك أن تقوم بذلك ما دمت في البيئة التي لا تقوم بالواجب، ولم تر أحدًا قام بالواجب، فعليك أن تقوم بالواجب إذا كنت على علم، وعلى بصيرة أن هذا الذي ترك واجبًا يجب فعله، أو هذا الذي فعل منكرًا يجب أن ينكر، إذا كنت على بصيرة فأنكر قُلْ هَذِهِ سَبِيلِي أَدْعُو إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108] فتعلم أولًا، وتفقه في الدين، وانظر الأدلة، ثم قم بالواجب من الإنكار، والدعوة، والتبصير بالحكمة، والكلام الطيب، والسيرة الحميدة، وأن تبدأ بنفسك قبل غيرك؛ حتى يقتدى بك في الخير، ولا يصيبك الكسل، والضعف كما أصاب كثيرًا من الناس، بل اصبر، وصابر، واسأل ربك العون، والتوفيق. وعليك بالحكمة، والأسلوب الحسن، والصبر، والمصابرة، وتحري الأوقات المناسبة في تذكير الناس، ودعوة الناس، وبيان ذلك الشيء فيما رأيت من مجتمعك، أو بيتك، أو قبيلتك، أو غير ذلك.","link":"https://binbaz.org.sa/fatwas/2200/واجب-من-اقام-في-بيىة-فيها-منكرات-لم-تنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_825.mp3","categories":["الدعوة والدعاة"]},{"id":6484,"question":"البعض من جيران المصلين، وجيران المسجد لا يحضرون صلاة الجماعة، وخاصة صلاة الفجر، وقد نصحت من حولي، ولم يستجيبوا للنصيحة، وأخبرت إمام المسجد بذلك، فقال: لم يعمم علينا بالرفع عن المتخلفين عن صلاة الجماعة، فنأمل من الغيورين وضع حد لهذه المشكلة؟","title":"دورنا نحو المتخلفين عن صلاة الجماعة وخاصة صلاة الفجر","answer":"الجواب: على كل حال ينبغي المتابعة في هذا، والحرص على النصيحة مع المتخلفين، ومع الإمام بمناصحتهم، والاتصال بهم من الجماعة من الجيران؛ ليذكروهم، ويعظوهم؛ لعلهم يهتدون، ويرعوون، فيجيبون إلى هذا الواجب، ولعل الأئمة يعانون في تفقد الناس لصلاة الفجر، فإن هذا قد ينشطهم، وقد يشجعهم على الحضور، وهكذا الهيئات قد تعينهم على هذا الأمر.  فالحاصل: أن هذا يجب فيه التعاون بين الجميع، بين الإمام، والمؤذن، والجماعة، والهيئة، إذا رأوا من جماعة، أو إنسان كسلًا في هذا الأمر في الفجر، أو في غير الفجر، في الظهر، والعصر، والمغرب، والعشاء، إذا تفقدوا أحوال جماعتهم، وتعاونوا على البر، والتقوى؛ هدى الله بهم الكثير، بالزيارة، يجتمع اثنان، أو ثلاثة، أو أربع، يزورون من رأوه يتخلف، يزورونه، ويذكرونه، ويقولون: يا فلان اتق الله، هذا أمر يلزمك فيه أن تؤدي الواجب، وألا تفتح باب الشر، وباب الكسل، سواء كان الإمام، أو من الجماعة.  هذا من باب التعاون على البر والتقوى، وأكثر ما يقع هذا في صلاة الفجر؛ لأن الناس يسهرون في الغالب، وإذا سهر؛ ثقل عليه أن يقوم لصلاة الفجر، ولا حول ولا قوة إلا بالله، فالمصيبة العظيمة السهر على التلفاز، أو على غيره، فإذا سهر؛ صعب عليه أن يقوم لصلاة الفجر، وهذه من علامات النفاق، نعوذ بالله، ونسأل الله السلامة. ولكن مع هذا كله يجب أن يناصح من الإمام، والمؤذن، والجماعة، لا من الواحد فقط، إذا راح جماعة ينصحونه، ثلاثة أربعة، فلعله يستحي، ولعله يرتدع، أما الواحد فقد لا يبالي به، وقد يقابله بالكلام غير اللائق، وقد لا يرفع به رأسًا، لكن إذا كانوا جماعة يتكلمون عليه، أو يزورونه، أو يقابلونه في الطريق، ويتكلمون معه، هذا من باب التعاون على البر، والتقوى.","link":"https://binbaz.org.sa/fatwas/2222/دورنا-نحو-المتخلفين-عن-صلاة-الجماعة-وخاصة-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_842.mp3","categories":["الدعوة والدعاة","صلاة الجماعة"]},{"id":6566,"question":"كيف تريدونا أن نعالج البيت، والمجتمع خرب، سواء المدرسة، أو الشارع، أو أجهزة الإعلام! نأمل الإجابة الشافية على ذلك؟","title":"عدم اليأس في محاربة المنكرات","answer":"الجواب:\n\nلا ينبغي اليأس يا أخي، لا ينبغي اليأس، جاهد، وأبشر، ولا تيأس إِنَّ اللَّهَ مَعَ الَّذِينَ اتَّقَوْا وَالَّذِينَ هُمْ مُحْسِنُونَ [النحل:128] وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] عليك بالجهاد، وعدم اليأس، اصبر، وصابر حتى تنجح -إن شاء الله- ولو في الأكثر، ولو في الأغلب.","link":"https://binbaz.org.sa/fatwas/2420/عدم-الياس-في-محاربة-المنكرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_947.mp3","categories":["الدعوة والدعاة"]},{"id":6575,"question":"أنا مسلم مؤهل شرعًا للقيام بالأمر بالمعروف، والنهي عن المنكر، والحمد لله، ولكن هناك شروط داخل المملكة هنا تمنع ذلك لغير السعوديين، ولعل ذلك احتياطًا للأمن، وهو المصدور، ولكن أريد أن أبرأ ذمتي، فماذا أفعل؟","title":"شروط النهي عن المنكر","answer":"الجواب:\n\nما فيها شروط غير ما سمعت، إذا كنت بصيرًا بأمر الله تعرف المعروف من المنكر، فاتق الله، وقل ما تعلم، وليس في هذا منع من الدولة، ولا غير الدولة، الإنسان ينكر المنكر، ويأمر بالمعروف، هذا مأجور عليه من الدولة، وغير الدولة.\n\nالسؤال: يقصد المساجد يعني؟\n\nالجواب: الدعوة غير الأمر بالمعروف والنهي عن المنكر، الدعوة، والخطب غير هذا، أما كونه يقوم خطيبًا هذا يحتاج إلى إذن، يحتاج إلى بطاقة التي يعطاها الدعاة؛ لأن بعض الناس قد يقوم خطيبًا، وهو لا يحسن الخطابة، ولا يعرف؛ فيضر الناس.\n\nفكونه يأمر بما يعرف من الخير، وينهى عما يعرف من الشر، هذا عام للناس كلهم، السعودية، وغير السعودية، إذا رأى من يتعاطى الخمر؛ نهاه، وقال: هذا محرم، هذا منكر، إذا رأى من يجلس عند المسجد، أو في الطرقات وقد أذن المؤذن يقول له: اتق الله، الصلاة، من يمنعه من هذا؟ لا الدولة، ولا غيرها، هذا غلط، إنما الذي فيه الكلام كونه يقوم خطيبًا واعظًا مذكرًا للناس، هذا الذي إذا أرادت الدولة أن يكون معه بطاقة من المسؤولين حتى يعرف أنه أهل لهذا الأمر حتى لا يضل الناس بجهله.","link":"https://binbaz.org.sa/fatwas/2416/شروط-النهي-عن-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_943.mp3","categories":["الدعوة والدعاة"]},{"id":6617,"question":"ما حكم من إذا دعوتهم إلى ترك محرم، أو إلى فعل شيء حلال قالوا: لو كان كما قلت؛ لما وجد في هذه البلد برضا الدولة؟","title":"سكوت الدولة عن بعض المنكرات لا يعني إقرار تلك المنكرات","answer":"الجواب: هذا غلط، هذه حجة باطلة، أولًا أن الدولة ما تعلم الغيب، ما تعلم كل شيء في البلد، وفي الدولة. والأمر الثاني: الدولة ما هي معصومة، ما هي معصومة، ما تقر إلا حقًا، قد تخطئ وتصيب، الدولة مثل العلماء يخطئون، ويصيبون، فوجود الشيء في البلد في الرياض، أو في غير الرياض، أو في المملكة كلها ما هو دليل على أنه مباح، أو أنه جائز، توجد فيها المعاصي، وتوجد فيها الطاعات مثل غيرها. المقصود: أن هذا الاحتجاج غلط، الدولة لا تعلم الغيب، والدولة غير معصومة، والمنكرات موجودة، فالواجب إنكار المنكر، والنهي عما حرم الله. وأما الاحتجاج بأن ما وجد في المملكة فهو حلال، هذا غلط، هذه حجة أهل الهوى إذا أنكرت عليهم قالوا: لو كان محرمًا ما أقرته الدولة، موجود هذا... الدولة ما أقرته، هذا هو الموجود، ومحرم، والخمر موجود بين الناس، والدولة تحاربه، ولكنه موجود، والزنا موجود، والدولة تحاربه، وتقيم الحدود على من فعله.  والمقصود: أن وجود المعاصي في بلاد السعودية ما هو بدليل على أنها حلال، المعاصي ربما توجد، وحتى في عهد النبي توجد ﷺ ولكن الواجب إنكار المنكر، إنكار ما حرم الله، والدعوة إلى ما أمر الله، والواجب إنكار ما ظهر من المنكر، والقضاء عليه، وإقامة الحدود.","link":"https://binbaz.org.sa/fatwas/2441/سكوت-الدولة-عن-بعض-المنكرات-لا-يعني-اقرار-تلك-المنكرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_968.mp3","categories":["الدعوة والدعاة"]},{"id":6686,"question":"ما حكم زيارة المريض إذا كان لا يصلي؟","title":"حكم زيارة المريض إذا كان لا يصلي","answer":"الجواب: زيارة المريض الذي لا يصلي لا تنبغي زيارته إلا إذا كان لقصد الدعوة، أما إن كان يزوره للتحبب، وإظهار أنه صاحبه، وأنه صديقه لا، أما إذا زاره ليدعوه إلى الله، ويذكره بالحق الذي عليه؛ لعله يموت على الإسلام، لعله يتوب، فهذا طيب، فقد زار النبي ﷺ خادمًا له يهوديًا، وهو مريض، فدعاه النبي ﷺ إلى الإسلام، فهداه الله على يديه، وأسلم، وقال: الحمد لله الذي أنقذه بي من النار. المقصود: إذا زار المريض الذي لا يصلي، أو مشرك معروف بالشرك، أو ما أشبه ذلك من أنواع الكفر، إذا زاره للدعوة إلى الله، لعل الله يهديه على يديه قبل أن يموت، هذا محسن، وله أجره في هذا، أما أن يزوره على أنه صديق، وحبيب، ورفيق لا للدعوة إلى الله، هذا لا يجوز، فهو ليس بصديق، ولا برفيق، ما دام يترك الصلاة يجب أن يهجر، ولا تقبل له دعوة، ولا يزار، ولا تجاب دعوته، ولا يدعى إلى الولائم، بل يهجر بين المسلمين لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر خرجه الإمام أحمد، وأهل السنن بإسناد صحيح، ورواه مسلم في الصحيح عن جابر  عن النبي ﷺ أنه قال: بين الرجل، وبين الكفر، والشرك ترك الصلاة نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/2540/حكم-زيارة-المريض-اذا-كان-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1035.mp3","categories":["الدعوة والدعاة"]},{"id":6745,"question":"إذا دخل المأموم مع الإمام، وهو لا يحسن قراءة الفاتحة؟","title":"حكم صلاة من لا يحسن الفاتحة وحكم إمامته","answer":"الجواب: عليه أن يتعلم قبل ذلك الفاتحة، أمرها عظيم، وهي ركن من أركان الصلاة، عليه أن يتعلمها، فإذا كان عجز، ولم يتعلم؛ يجب التكبير، والتهليل، والتحميد، كما أمر النبي ﷺ بذلك، من عجز؛ يحمد الله، ويهلله، ويكبره: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، بدل الفاتحة إذا عجز عنها. السؤال: المأموم دخل مع الإمام، والإمام لا يحسن القراءة، حكم صلاة المأموم وراء إمام لا يحسن؟ الجواب: الإمام الذي ما يحسن الفاتحة، هذا يختلف، إذا كان اللحن يخل بالمعنى؛ يفتح عليه، وإن كان اللحن لا يخل بالمعنى؛ فالأمر في هذا واسع، فإذا قال: الحمدَ لله رب العالمين هذا ما يضر، أو قال الرحمنَ الرحيم، أو الرحمنُ الرحيم لا يضر، أما إذا لحن في المعنى إذا قال: إياكِ نعبد وإياكِ نستعين -الخطاب للمرأة- ينبهه، يقول إياكَ، ينبه فيعتدل، أو قال أنعمتُ عليهم؛ ينبهه، يقال: أنعمتَ أو قال: أنعمتِ عليهم؛ ينبه، فإن اعتدل، وإلا لا يجوز. السؤال: وإن تعمد قال: إياك نعبد وإياك نستعين عمدًا؟ الجواب: يعلم، إذا ما نفع؛ يعزل، يوجه .. القائمين على المسجد، إذا كان المسجد خاصًا؛ يعزله، أو الأوقاف -مكتب الأوقاف- ويبين له أن هذا الإمام لا يجيد الفاتحة. السؤال: لكنه إمام راتب؟ الجواب: ولو أنه إمام راتب، يبدل بغيره، إذا كان اللحن يغير المعنى؛ ينبه المسؤولون. السؤال: .. الجواب: ينبه المسؤولون؛ حتى يعزلوه. السؤال: .. الجواب: الله يهديهم، لو قام كل واحد ... من لم يقم بالواجب يُنبه، ويُجاهد؛ حتى يستقيم.","link":"https://binbaz.org.sa/fatwas/2620/حكم-صلاة-من-لا-يحسن-الفاتحة-وحكم-امامته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1116.mp3","categories":["صلاة الجماعة","الدعوة والدعاة"]},{"id":6778,"question":"هناك من يرى أن المناصحة في الدين في منكر انتشر، وأصبح سائدًا عند أكثر الناس غلو في الدين، ويقول: لا تشددوا؛ فيشدد الله عليكم، فما هو الغلو الحقيقي؟ وما رأيكم سماحتكم فيما يفعله أكثر الناس في تقليد الآخرين، وإذا نُصح؛ قال يفعله الناس؟","title":"الرد على من يقول بأن إنكار المنكر من التشدد","answer":"الجواب: أولًا: من زعم أن إنكار المنكر أنه من التشديد في الدين هذا غلط، هذا قلب للحقائق، بل التشديد في الدين الذي يبتدع، ويزيد في الدين، ويوسوس، أو يأتي بعبادات ما أنزل الله بها من سلطان، أو يكرر العبادة وسوسة منه، أو لا يصوم، أو يصوم النهار، ويقوم الليل ولا يفطر، هذا هو التشديد، أما من أمر بالمعروف، ونهى عن المنكر، فهذا ليس مشددًا، بل هذا مصلح، وناصح لله، ولعباده.","link":"https://binbaz.org.sa/fatwas/2642/الرد-على-من-يقول-بان-انكار-المنكر-من-التشدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1138.mp3","categories":["الدعوة والدعاة"]},{"id":6790,"question":"عفوًا... تقودنا إلى نقطة في المحاضرة وردت، نسأل الله أن يهدي المسلمين إلى الخير أجمعين، وأن يجزي فضيلة العالمين عنا خيرًا، النقطة التي تتعلق بهذه النقطة التي أثرتها هي: هل يجوز للمسلم أن يضع يده في يد غير المسلم، أو من ادعى الشيوعية القومية.. أو غيره بغية تقريبه إلى الخير؛ لأن العالمين الفاضلين لم يوضحا هذه النقطة بما فيه الكفاية؟","title":"حكم تحالف المسلم مع أصحاب الفكر الشيوعي والقومي وغيرهم","answer":"الجواب: هذا فيه تفصيل، أما وضع ... وأصحاب، وأنهم يعفى عن كفرهم، وضلالهم، لا، إما أن يدعوا إلى الإسلام، ويقربوا للإسلام، أو يوضع بيننا وبينهم حد من جهة الهدنة، إلى وقت ما؛ لعلهم يرجعون، لعلهم يستقيمون، هذا لا بأس به، مثل ما عقد النبي ﷺ حدًا بينه وبين كفرة قريش، هدنة يوم الحديبية لمدة عشر سنين لوضع الحرب، الكافرون على كفرهم، والمسلمون على إسلامهم، حتى يتمكن المسلمون من الاتصال بالمسلمين، ومعرفة القرآن، والسنة، وحتى يتمكنوا من السفر إلى بلاد الخير؛ ليسمعوا، ويستفيدوا من الحق، فهذا من باب المهادنة، الوفاء بالعهد؛ حتى يتمكن الناس من الخير، وحتى يتمكن أولئك الآخرون من سماع الخير، ومن النظر فيه؛ لعلهم يهتدون، أما اتخاذهم أصحابًا، واتخاذهم أولياء، لا يجوز اتخاذهم أصحابًا ولا أولياء، كل الكافرين هم أعداء.  السؤال: والشطر الثاني من السؤال: وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا [آل عمران:103] هل هذه؟  الجواب: هذه للمسلمين. الطالب: فقط؟ الجواب: نعم، لا للكفار. الطالب: ما هو لكل الناس..؟ الجواب: لا، لا، المؤمنون مأمورون بالاعتصام بحبل الله جميعًا، ولا يتفرقوا، ولهذا قال: وَلَا تَنَازَعُوا فَتَفْشَلُوا وَتَذْهَبَ رِيحُكُمْ[الأنفال:46].","link":"https://binbaz.org.sa/fatwas/2668/حكم-تحالف-المسلم-مع-اصحاب-الفكر-الشيوعي-والقومي-وغيرهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1165.mp3","categories":["الدعوة والدعاة"]},{"id":6812,"question":"هل العلم، والتفقه في الدين شرط يلزم توفره فيمن يدعو إلى الله؟ وما رأيكم فيمن يجعلون العلم أحد برامج دعوتهم، ثم يلمزون، ويحتقرون العلماء، وطلبة العلم صراحة، وإشارة، ويقولون: إنهم جالسون يقرؤون الكتب، والأمة تحترق، وتموت على غير الدين؟","title":"العلم الذي يجب توافره في الداعية","answer":"الجواب: ليس من شرط الدعوة إلى الله أن يستكمل الإنسان العلم كله، وأن يجتهد في معرفة كل الأمور، لا، يدعو إلى الله حسب علمه، فإذا علم مسألة؛ دعا إليها، علم مسألتين دعا إليهما، ثلاث دعا إليها، وهكذا يتعلم، ويتفقه في الدين، ويعتني بالعلم؛ حتى يتبصر.  لكن إذا علم شيئًا في دين الله، في شرع الله، مثل الصلاة، يعرف الصلاة، وأنها فرض، وأنها عمود الإسلام، وأن الواجب على الرجال أداؤها في الجماعة، وأن الطهارة لها شرط، ولا بد منها، يدعو إلى هذا الذي علم، يعرف أن الزنا حرام، يعرف أن الخمر حرام، ما يحتاج إلى أن يتعلم في الأمور الأخرى حتى يأمر بهذا، وينهى عن هذا، لا، هذه أمور ظاهرة معروفة، ولو أن الإنسان في الابتدائي، أو في المتوسط، أو في الثانوي، يعني شيء معروف يلتزمه المؤمن، ويدعو إليه، والمعروف أنه محرم، يحذره، وينهى الناس عنه.  وما يشتبه عليه لا يعجل فيه، ما ليس عنده فيه علم ما يشتبه عليه لا يعجل، لا يتكلم فيه، بل يقول: لا أدري، حتى يتعلم، حتى يتبصر، لكن الأمور التي تعلمها، وعرفها عرف الصلاة، وأنها حق، وأنها دين، وأنها عمود الإسلام؛ يدعو إليها، وينكر على من تركها، عرف الزكاة، وأنها حق المال؛ يدعو إلى ذلك، عرف صيام رمضان، وأنه حق، وأنه من أركان الإسلام؛ يصوم، ويأمر الناس بالصوم، وينكر على من ترك الصيام. تعرف بر الوالدين، وأنه حق، وأن العقوق حرام، وكبيرة؛ فينكر على عق والديه، ويأمره بالبر، يعرف أن شهادة الزور حرام؛ ينكر على من يشهد الزور، ويكذب، يعرف أن الزنا حرام؛ ينكر على من يتعاطى الزنا، ووسائله، يعرف أن الخمر حرام، ينكر على من يشرب الخمر، هكذا يسير المؤمن، يعني يعمل بما علم، وما لم يعلم يتوقف حتى يتعلم.","link":"https://binbaz.org.sa/fatwas/2689/العلم-الذي-يجب-توافره-في-الداعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1187.mp3","categories":["الدعوة والدعاة"]},{"id":6816,"question":"إذا الداعية دعا إلى الإسلام، وإلى الصلاة، وقام سب الدين، وسب الرسول، وسب الله؟ من الذي سب الدين؟ المدعو؟ المدعو.","title":"كيفية التعامل مع من سب الله أو دينه أو رسوله","answer":"الجواب: أولًا: ينصحه، يبين له أن هذا كفر، وضلال، والحاضرون ينصحونه، ويتكلمون عليه، ويبينون خطأه، فإن تاب، وإلا يرفع بأمره إلى من ينفذ فيه الأمر، إذا كان في بلد فيها من يحكم بشرع الله.  فإذا كان ما فيها حكم بشرع الله يرفع إلى من جعل له الأمر في مثل حتى يؤدبه، حتى يسجنه، يعني لا يعجلوا في الأمور، بل ينصحونه أولًا، يتكلمون عليه كلامًا شديدًا؛ إذا أصر على باطله، ويتوعدونه بالرفع عنه إلى ولاة الأمور؛ لعله يرجع إلى الصواب، لعله يرجع إلى الحق، لأن سب الدين ردة عن الإسلام، نعوذ بالله.  سب الرسول ردة عن الإسلام، سب الرسول تنقص ردة عن الإسلام، وسب الدين كذلك ردة عن الإسلام، لو قال: الرسول ﷺ ما يفهم هذه الأمور، ما يعرف هذه الأمور، أو قال: الرسول بدوي ما يعرف هذه الأمور، أو كذا؛ هذا ردة عن الإسلام، كفر أكبر -نعوذ بالله-. أو قال: الشريعة ما تصلح لهذا الدين، ما تصلح لهذا العصر، شريعة الإسلام ما تصلح لهذا العصر، تصلح لعصر مضى، هذا ردة عن الإسلام -نعوذ بالله-.","link":"https://binbaz.org.sa/fatwas/2692/كيفية-التعامل-مع-من-سب-الله-او-دينه-او-رسوله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1190.mp3","categories":["الدعوة والدعاة","نواقض الإسلام"]},{"id":6832,"question":"إن تحديد الأمر بالمعروف، والنهي عن المنكر بأناس فرغوا لذلك لا شك أن هذا سيئ، وخطأ، ولكن السؤال هل هؤلاء على علم بالكتاب، والسنة، أم لا؟ والشيء الثاني: هل هو أن الوظيفة التي يقومون بها هي الأمر بالصلاة، مع أن الأمر هو أشمل بكثير من ذلك، نرجو توضيح ذلك؟","title":"عدم اقتصار الأمر بالمعروف بجهة معينة","answer":"الجواب: لهم واجب، عليهم أن يأمروا بالمعروف، وأن ينهوا عن المنكر في كل شيء، لا في أمر الصلاة، وحدها، الواجب على الهيئات جميعًا كما عينوا في هذا الأمر أن يأمروا بالمعروف من حيث هو، وينهوا عن المنكر من حيث هو، ولا يختص بالصلاة، بل يأمرون بالمعروف من حيث الصلاة، ومن جهة الزكاة، ومن جهة الصيام، ومن جهة سائر الأمور التي أمر الله بها -جل وعلا-. وهكذا ينهون عن المنكر من جميع الوجوه، من جميع المعاصي، ووسائلها، لكن نسأل الله أن يمنحهم النشاط، والقوة، ثم هو لا يختص بهم، الأمر بالمعروف لا يختص بالمفرغين، هذا واجب على الجميع، ما هو خاص بالمفرغين، الله يقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ، وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71] فالأمر بالمعروف، والنهي عن المنكر واجب على المؤمنين جميعًا، المفرغ، وغير المفرغ، والذي يأخذ معاشًا، والذي ما يأخذ معاشًا واجبهم جميعًا أن يقوموا بهذا الأمر، وليس خاصًا بالموظفين فقط، لا، قال الرسول ﷺ: من رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه، وذلك أضعف الإيمان رواه مسلم في الصحيح، هذا عام للجميع.  \nوقال -عليه الصلاة والسلام-: ما بعث الله من نبي لأمة قبلي إلا كان له من أمته حواريون، وأصحاب، يأخذون بسنته، ويقتدون بأمره، ، ثم إنها تخلف من بعدهم خلوفًا يقولون ما لا يفعلون، ويفعلون ما لا يؤمرون، فمن جاهدهم بيده؛ فهو مؤمن، ومن جاهدهم بلسانه؛ فهو مؤمن، ومن جاهدهم بقلبه؛ فهو مؤمن، وليس وراء ذلك من الإيمان حبة خردل.  فالواجب على المؤمن أن يكون نشيطًا في هذا الأمر، ولا يكل الأمر إلى الهيئات، لا، هذا نقص عظيم، وخطر كبير، الواجب على الجميع أن يكونوا جنودًا لله  وأن يكونوا أمارين بالمعروف، نهائين عن المنكر في جميع الأحوال، لا للوظيفة، ولا بالأمر الرسمي، ولا بالمعاش، بل بالأمر الأزلي من جهة الله بأمر الله، ورسوله، فأمر الله، ورسوله فوق الجميع، فوق جميع الوظائف، فوق جميع الأوامر، في كل مكان، في البر، والمدن، وفي القرى، وفي الطائرة، وفي السيارة، وفي القطار، وفي المسجد، وفي كل مكان، يكون عندهم النية الصالحة، والحسبة، والنشاط في الخير، مع مراعاة الرفق، والأسلوب الحسن، مع مراعاة الحلم، والصبر، والأسلوب الحسن في إنكار المنكر، والدعوة إلى الخير، لعله ينجو، لعله يوفق، لعله يقبل منه.","link":"https://binbaz.org.sa/fatwas/2711/عدم-اقتصار-الامر-بالمعروف-بجهة-معينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1210.mp3","categories":["الدعوة والدعاة"]},{"id":6835,"question":"هل ترون أن الأمر بالمعروف، والنهي عن المنكر كاف في إبعاد المنكر؟ أقصد أن الكلام الكثير الذي نسمعه في الخطب، وغيرها في المساجد أنها ليست كافية، ما لم توجد الكتب الصالحة، والتطبيق العملي من العلماء، والعاملين في ميادين الدعوة؛ حتى يعرف الناس الحق، فما تعليق سماحتكم؟","title":"القدوة الصالحة من أسباب قبول النصيحة","answer":"الجواب: الطرق لإزالة المنكر كثيرة، لكن الدعوة إلى الله، والأمر بالمعروف، والنهي عن المنكر من ذلك، قد يهدي الله به من يشاء . ومن ذلك القدوة الحسنة، فالآمر، والناهي يتخلق بالأخلاق الفاضلة، ويتباعد عما حرم الله، هو صاحب البيت يتأدب بالآداب الشرعية، ويكون قدوة صالحة، الزوج قدوة صالحة، الأب قدوة صالحة، الولد قدوة صالحة لإخوانه الآخرين، وهكذا أعضاء الهيئة، وهكذا الآمرين بالمعروف يتحرون الخير، ويتأسون بالرسول ﷺ ويسارعون إلى الخيرات، ويتباعدون عن الشر، كل هذا من أعظم الأسباب في نجاح الأمر بالمعروف، والنهي عن المنكر. وهكذا الوازع السلطاني، كون الوازع السلطاني يحصل من ولاة الأمور إذا عجز الآمر الناهي؛ ساعدهم ولاة الأمور بالضرب على أيدي المفسدين، وعقابهم بالسجن، وبالضرب، وبالإبعاد، وبغير هذا من وجوه التعزير \"إن الله يزع بالسلطان ما لا يزع بالقرآن\" كما قال عثمان . فلا بد من تكاتف هذه الأمور، وتعاون هذه الأمور، ولا يغني بعضها عن البعض الآخر، كل واحد منها جزء من الواجب، وجزء من أسباب الإصلاح،  وجزء من أسباب الخير، لكن لا يكفي وحده، بل لا بد من التكاتف في هذا الأمر العظيم، من الخواص، ومن العامة، ولا بد من القدوة الحسنة من الآمر، والناهي، وصاحب البيت، ومن ولاة الأمور، ولا بد من الوازع، تقام الحدود على أصحاب المنكرات، وتقام التعزيرات على أصحاب المنكرات حسب ما يرى ولي الأمر، وحسب ما ترى المحاكم في.. الرادع، إذا كانت المعصية دون الحد، وعلى كل حال لا بد من تكاتف القضاة، والعلماء، وولاة الأمور، وسائر من يقوم بهذا الأمر من كل وجه، ومن كل طريق يعين على إخفاء الرذيلة، وعلى إظهار الحق.","link":"https://binbaz.org.sa/fatwas/2712/القدوة-الصالحة-من-اسباب-قبول-النصيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1211.mp3","categories":["الدعوة والدعاة"]},{"id":6918,"question":"... بين أحد الأعمام، وابن أخيه، حتى إنه وصل المقام إلى مقاطعة عمه تمامًا، حيث لا يرد عليه السلام، وهذا الوضع منذ مدة طويلة تزيد على السنتين، فقد حاول العم الإصلاح، ولكن ابن الأخ يصر على مقاطعته، علمًا بأنه شاب طيب، وملتزم بمبادئ الدين، ولكن مع هذا لا زال يقاطع عمه، فما رأي فضيلتكم في هذا؟ وما هي العقوبة المترتبة على ذلك؟","title":"حكم هجر أحد الأقارب","answer":"الجواب: ينظر في العم، إذا كان العم قد أتى معاصي ظاهرة، أو بدعًا ظاهرة معروفة؛فولد أخيه معذور إذا قطعه، وإذا هجره حتى يتوب.  أما إذا كان العم لا جرم له، ولكنها أمور نفسية، وأمور تتعلق بالدنيا؛ فلا يجوز للولد أن يقطعه، ولا يجوز أن يهجره أكثر من ثلاثة أيام، الهجر ثلاثة أيام، فأقل في أمور الدنيا، ويلزمه صلته بعد ذلك، والسلام عليه، والقيام بحقه؛ لأن العم بمنزلة الأب، فلا يجوز له أن يقطعه، ولا أن يهجره إلا إذا كان ذلك من أجل إظهار المعاصي، وإظهار البدع، فهذا لا بأس بهجره؛ حتى يتوب إلى الله من ذلك.","link":"https://binbaz.org.sa/fatwas/2848/حكم-هجر-احد-الاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1296.mp3","categories":["الدعوة والدعاة","الآداب والأخلاق"]},{"id":6957,"question":"أنا شاب أحب الله، وأولياءه الصالحين، ولما من الله علي بالهداية قمت بإطلاق لحيتي، وتقصير ثوبي، والمحافظة على تعليم دين الإسلام، لكني مع ذلك أجد مضايقات من جماعتي، ومن أقاربي وأجد سخرية، واستهزاء، فماذا أرد عليهم، أفيدوني جزاكم الله خيرًا؟","title":"الصبر درع الداعية عند الاستهزاء به وأذيته","answer":"الجواب: عليك بالصبر، الرسل -عليهم الصلاة والسلام- وجدوا سخرية من قوهم، وآذاهم قومهم.. فَاصْبِرْ كَمَا صَبَرَ أُولُو الْعَزْمِ مِنَ الرُّسُلِ[الأحقاف:35] عليك بالصبر، والله يقول -جل علا-: إِنَّمَا يُوَفَّى الصَّابِرُونَ أَجْرَهُمْ بِغَيْرِ حِسَابٍ [الزمر:10]. ويقول النبي ﷺ: ما أعطي أحد عطاء خيرًا وأوسعَ من الصبر فالرسل أفضل الناس، وأكرمهم على الله، ومع هذا آذاهم قومهم، واستهزؤوا بهم، بل قتلوهم، قتلوا بعضهم. فالداعي إلى الله، والمؤمن أينما كان لا يضعف، ولا يكسل، فلو كانت الدنيا يعطاها المؤمن بلا شوك، وبلا أذى، تسهل له الأمور، تكون على مطالبه؛ ما بقي كافر في الدنيا، كان كل الناس أسلموا، كل الناس ما عصوا، فلا بد من ابتلاء، وامتحان. الله يقول: وَنَبْلُوكُمْ بِالشَّرِّ وَالْخَيْرِ فِتْنَةً وَإِلَيْنَا تُرْجَعُونَ [الأنبياء:35] ويقول سبحانه: وَبَلَوْنَاهُمْ بِالْحَسَنَاتِ وَالسَّيِّئَاتِ لَعَلَّهُمْ يَرْجِعُونَ[الأعراف:168] ويقول سبحانه: الَّذِي خَلَقَ الْمَوْتَ وَالْحَيَاةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا [الملك:2] فلا بد من الابتلاء والامتحان أَحَسِبَ النَّاسُ أَنْ يُتْرَكُوا أَنْ يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ [العنكبوت:2].","link":"https://binbaz.org.sa/fatwas/2887/الصبر-درع-الداعية-عند-الاستهزاء-به-واذيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1335.mp3","categories":["الدعوة والدعاة"]},{"id":7097,"question":"لقد أدركتْ فئةٌ من الناس أضرار الإعلام، وخاصة ما يندرج تحت المسهلات أو الملهيات السخيفة، ولكن يا شيخ ما هو البديل لنا ولهؤلاء الفئة؟ ولماذا لا يتم هناك تعديل تام في نشر الموضوعات بصورة تخدم الإسلام؟","title":"البديل الإسلامي لوسائل الإعلام الضارة","answer":"الجواب:\n\nالبديل موجود، لكن نسأل الله أن يسهل من يضعه في محله على الوجه الذي ينبغي، وعلى الوجه الذي ينفع الناس، فالحمد لله البرامج التي تنفع الناس كثيرة، والمجال واسع في التاريخ الإسلامي، في السيرة النبوية، فيما يحتاجه المسلم في يومه وليلته، في أحكام الشرع، في العبادات والمعاملات، وغير ذلك بصور جذابة وواضحة، وأساليب مفيدة بينة.\n\nوهكذا فيما يتعلق بالصناعات، وما يحتاجه المسلمون كل ذلك ممكن أن توضع فيه برامج كثيرة تقع، وتحل محل البرامج الأخرى التي فيها ضرر، وإذا قصد الناس الإصلاح وبذلوا الجهد في طلب الإصلاح؛ يسر الله أمرهم، وأعانهم كما قال : وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] إِنْ تَتَّقُوا اللَّهَ يَجْعَلْ لَكُمْ فُرْقَانًا [الأنفال:29] فالمهم قصد الإصلاح، والحرص عليه، وبذل المستطاع، وبذلك يحصل كل خير.","link":"https://binbaz.org.sa/fatwas/3118/البديل-الاسلامي-لوساىل-الاعلام-الضارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1485.mp3","categories":["الدعوة والدعاة"]},{"id":7098,"question":"هل علماؤنا أدوا واجبهم الإعلامي نحو مواطنيهم؟ولماذا لم يساهم كثير منهم في وسائل الإعلام المرئي والمسموع؟ وهل الكشف في العمل به مكروه، أو محرم؟","title":"حكم مساهمة العلماء في وسائل الإعلام","answer":"الجواب:\n\nهذا تختلف فيه آراء أهل العلم، منهم من يرى جواز الدخول فيه، ومنهم من يتوقف عن ذلك من أجل الصور، فلهذا كثر من يتوقف عن ذلك، فهو محل اجتهاد، ومحل اختلاف بين أهل العلم في جواز الدخول في ذلك، والبروز في الشاشة لإلقاء الكلمات والتوجيه.\n\nفمنهم من فعل ذلك، ورأى أن هذا فيه مصلحة، وأنه يغتفر في جنبه ما يتعلق بالتصوير.\n\nومنهم من توقف في ذلك، ولهذا المساهمون في الوسائل المسموعة والمقروءة أكثر من المساهمين في المرئية من أجل هذا الأمر الذي سمعت -وهو مسألة التصوير- والذي نعتقده: أن من ساهم في ذلك بقصد الإصلاح، ورد الشبهات، وإظهار الحق أنه جائز له ذلك، ومعفو عنه فيما يقع من التصوير من أجل المصلحة العظمى.\n\nوالقاعدة الشرعية المعروفة في الشرع المطهر: أنه يجب تحصيل أعلى المصلحتين، وأعلى المصالح، ولو بتفويت الدنيا منهما أو منها، ويجب تعطيل كبرى المفسدتين، وكبرى المفاسد، ولو بارتكاب أدناهما، أو أدناها، هذه قواعد شرعية معلومة.\n\nوكما يجوز للإنسان أن يأخذ التابعية التي يحتاج إليها، حفيظة النفوس، ولو بالصورة لحاجته إلى ذلك، فحاجة المسلمين إلى بروز العلماء في التلفاز للنصيحة، والتوجيه أعظم من حاجة الرجل إلى التابعية ونحوها، ونسأل الله أن يوفق العلماء لما فيه صلاحهم وصلاح المسلمين، نسأل الله أن يوفقنا وإياهم جميعًا لما فيه صلاحنا، وصلاح أمتنا، وصلاح المسلمين جميعًا.","link":"https://binbaz.org.sa/fatwas/3119/حكم-مساهمة-العلماء-في-وساىل-الاعلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1486.mp3","categories":["الدعوة والدعاة"]},{"id":7099,"question":"هل يجوز لشخص مجالسة الذين يشربون الدخان، ولو كانوا أقاربه، وهذا الشخص قد نصحهم ولم يستمعوا له؟ فهل يجوز مجالستهم؟ أفيدونا جزاكم الله خيرًا؟","title":"حكم مجالسة أهل المعاصي","answer":"الجواب:\n\nالواجب على من جالس أهل المعاصي أن ينصحهم، وأن يوجههم إلى الخير، وأن يعينهم على طاعة الله، ويذكرهم بالله، فإذا لم يستجيبوا له؛ شرع له هجرهم، إلا أن يكون اتصاله بهم أنفع وأكثر خيرًا، وأقل شرًا، فليفعل ما هو الأصلح.\n\nفقد يكون الهجر بعض الأحيان يزيد الشر شرًا، فإذا كان عدم هجره له، واتصاله بهم في بعض الأحيان، وإعادة النصيحة مما يقلل شرهم، ومما يكثر خيرهم؛ فعل ذلك، فليفعل ما هو الأصلح.","link":"https://binbaz.org.sa/fatwas/3113/حكم-مجالسة-اهل-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1481.mp3","categories":["الدعوة والدعاة"]},{"id":7100,"question":"عندي جيران لا أراهم يخرجون إلى المساجد للصلاة مع الجماعة، ما أدري هل هم لا يصلون؟","title":"نصيحة الجيران الذين لا يصلون جماعة في المسجد","answer":"الجواب: \n\nانصحهم.\n\nالسؤال: يصلون في بيوتهم، وقد نصحتهم، فيقول: إني أصلي في البيت، ولا أدري ما أعمل معهم، فنرجو النصيحة إلى أمثال هؤلاء من مكانكم، جزاكم الله خيرًا؟\n\nالجواب: الواجب على من يعرف من جيرانه عدم الصلاة في المساجد أن يتصل بهم هو وبعض إخوانه، لا يكون وحده، هو وبعض إخوانه أنفع، يأخذ اثنين أو ثلاثة من إخوانه جماعة يذهبون إلى جارهم، أو جيرانهم وينصحونهم: ما رأيناكم في المساجد! ما نراكم يا إخوانلماذا؟ الواجب أن تحضروا مع إخوانكم، في الحديث: من سمع النداء فلم يجب؛ فلا صلاة له إلا من عذر. \n\nوقد استأذن النبي ﷺ رجلًا أعمى قال: يا رسول الله هل لي من رخصة أن أصلي في بيتي، وأنا رجل أعمى، ليس لي قائد يلائمني إلى المسجد؟ فقال له المصطفى -عليه الصلاة والسلام-: هل تسمع النداء بالصلاة؟ قال: نعم. قال: فأجب وهو أعمى، ما عنده قائد يلائمه، ومع هذا يقال له: أجب، فكيف بحال البصير الصحيح!\n\nالمقصود: الواجب على الإخوان الذين حولهم جيران، لا يشهدون الصلاة أن ينصحونهم بنصيحة جماعية؛ لأن الواحد قد يحتقرونه، أو يتكبرون عليه، أو يقابلونه مقابلة رديئة، لكن إذا كان جماعة يكون أقرب إلى النجاح، ثلاثة أربعة خمسة يذهبون يزورن الشخص، أو يقابلونه في الطريق، ينصحونه حتى تكون النصيحة لها ثمرة كبيرة -إن شاء الله- والزيارة إلى البيت في الوقت المناسب تكون جيدة، جئناك يا أخي للدعوة لإنقاذك، وإنقاذ ذمتنا، وبراءة ذمتنا.\n\nوهكذا غير الصلاة إذا علموا من جارهم شيئًا واضحًا من المنكر نصحوه، ولا يسكتون عن الباطل، لا يرضون لأخيهم بالنار، ولا بطاعة الشيطان، المؤمن للمؤمن كالبنيان يشد بعضه بعضًا وشبك بين أصابعه -عليه الصلاة والسلام-.\n\nوقال أيضًا -عليه الصلاة والسلام- في الحديث الصحيح: مثل المؤمنين في توادهم وتراحمهم وتعاطفهم كمثل الجسد إذا اشتكى منه عضو تداعى له سائر الجسد بالسهر والحمى.\n\nهكذا المسلمون إذا اشتكت عينه التألم يعم بدنه كله، والنوم يذهب، والسهر يعم، وهكذا اشتكت رجلك، أو يدك، أو غير ذلك، فهكذا أخوك المؤمن، ولاسيما جيرانك، وأقاربك هم في أشد الحاجة إلى النصيحة، والتألم لهم حتى ينشطوا في الحق، وحتى يدعوا الباطل إذا رأوا من إخوانهم النشاط والنصيحة.","link":"https://binbaz.org.sa/fatwas/3120/نصيحة-الجيران-الذين-لا-يصلون-جماعة-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1487.mp3","categories":["الدعوة والدعاة"]},{"id":7101,"question":"لقد أدركتْ فئةٌ من الناس أضرار الإعلام، وخاصة ما يندرج تحت المسهلات أو الملهيات السخيفة، ولكن يا شيخ ما هو البديل لنا ولهؤلاء الفئة؟ ولماذا لا يتم هناك تعديل تام في نشر الموضوعات بصورة تخدم الإسلام؟","title":"البديل الإسلامي لوسائل الإعلام الضارة","answer":"الجواب:\n\nالبديل موجود، لكن نسأل الله أن يسهل من يضعه في محله على الوجه الذي ينبغي، وعلى الوجه الذي ينفع الناس، فالحمد لله البرامج التي تنفع الناس كثيرة، والمجال واسع في التاريخ الإسلامي، في السيرة النبوية، فيما يحتاجه المسلم في يومه وليلته، في أحكام الشرع، في العبادات والمعاملات، وغير ذلك بصور جذابة وواضحة، وأساليب مفيدة بينة.\n\nوهكذا فيما يتعلق بالصناعات، وما يحتاجه المسلمون كل ذلك ممكن أن توضع فيه برامج كثيرة تقع، وتحل محل البرامج الأخرى التي فيها ضرر، وإذا قصد الناس الإصلاح وبذلوا الجهد في طلب الإصلاح؛ يسر الله أمرهم، وأعانهم كما قال : وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] إِنْ تَتَّقُوا اللَّهَ يَجْعَلْ لَكُمْ فُرْقَانًا [الأنفال:29] فالمهم قصد الإصلاح، والحرص عليه، وبذل المستطاع، وبذلك يحصل كل خير.","link":"https://binbaz.org.sa/fatwas/3118/البديل-الاسلامي-لوساىل-الاعلام-الضارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1485.mp3","categories":["الدعوة والدعاة"]},{"id":7103,"question":"قرأنا لأحد الكتاب في كتاب النصائح الإسلامية: بأنه لا يجوز للعلماء الخروج في التلفزيون، أو غيره؛ لأنه إعانة لأهل الباطل، فما مدى صحة قولهم؟","title":"حكم ظهور العلماء في التلفاز وغيرها من وسائل الإعلام","answer":"الجواب:\n\nالخروج في التلفاز إذا كان أراد به نصر الحق؛ نرجو ألا يكون عليه حرج -إن شاء الله- إذا خرج في التلفاز، أو ندوة في التلفاز للحق، تنصر الحق؛ لأن التلفاز عمت به البلوى، الآن يشاهده الناس في كل مكان. \n\nفإذا ما ظهر فيه أهل الحق؛ صار يظهر فيه أهل الباطل فقط، فينتشر الباطل، فإذا ظهر دعاة الحق، وكلمات الحق في التلفاز، ونشرت؛ فهذا مما ينفع الله به الناس، فمن ظهر فيه لقصد الحق، ولقصد القضاء على الباطل، ودعوة الناس إلى الخير، نرجو ألا يكون حرج عليه للضرورة.","link":"https://binbaz.org.sa/fatwas/3131/حكم-ظهور-العلماء-في-التلفاز-وغيرها-من-وساىل-الاعلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1490.mp3","categories":["الدعوة والدعاة"]},{"id":7109,"question":"من أراد الخروج لإعلاء كلمة الله في بلدان العالم، كيف يتم له ذلك؟ وهل يجب أن تتوفر شروط ذلك؟ وما هي الشروط، أقصد الخروج بنفسي، وترك من أعول لله  بعد أن وفرت لهم ما يحتاجون إليه؟","title":"شروط الداعية الخارج للدعوة في بلدان العالم","answer":"الجواب:\n\nإذا كان من أهل العلم والبصيرة والاتزان، معروفًا بالخير، ويعرف نفسه بالقوة على الدعوة إلى الله، عنده علم؛ فلا بأس أن يخرج خروجًا لا يضر أهله، يخرج أوقاتًا معينة، ويرجع للدعوة إلى الله  حتى لا يهمل أهله، فيقوم عليهم، وحتى يؤدي حقهم، فيجمع بين المصلحتين.\n\nوإذا كان معه إخوان له يساعدونه، يذهبون جميعًا، ويرجعون جميعًا، أولى من الذهاب لوحده إذا كان عنده علم وبصيرة واتزان، ومضى عليه من السن ما يجعله من الثابتين الذين لا يخشى عليهم الفساد والفتنة في البلاد التي فيها الشر.\n\nالسؤال: العوام؟\n\nالجواب: العوام ما يصلح، ما يذهبون إلى بلاد الكفر، العوام في بلادهم فقط يسمعون الفائدة بس.\n\nالسؤال: يروحون أوربا يا شيخ؟\n\nالجواب: لا، ما يروحون لا، ما يجوز يروحون، ما يروح إلا العلماء فقط، العلماء المعروفون بالعلم والفضل والبصيرة، أما العامة لا يجوز.","link":"https://binbaz.org.sa/fatwas/3138/شروط-الداعية-الخارج-للدعوة-في-بلدان-العالم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1496.mp3","categories":["الدعوة والدعاة"]},{"id":7114,"question":"لا يخفى على سماحتكم النشاط الذي قامت به الشيعة في التذكير بالدين، فإنه في هذا الوقت قد ازداد نشاطهم وخاصة في إندونيسيا وماليزيا وتايلند والفلبين، وخاصة في أفريقيا التي كانت خالية من التشيع، فقد بلغ أعداد الشيعة في القارة الإفريقية بمئات الألوف، وتركوا السنة في هذه الدول التي ذكرناها، وقد ازداد نشاطهم بتذكير التشيع في العديد من الدول التي لا نستطيع حصرها، لذا فإن دور العلماء بالدعوة، والإرشاد في تبيين عقيدة الشيعة، وما هم فيه من الخبث، ونحيطكم أن العديد ممن يخدعون المسلمين يعلنون الدعاية لهم، ويقولون: لا فرق بيننا وبينهم، هذا هو السبب في تحويل السنة إلى شيعة، وإن دعوتهم قد بدأت تستشري بين الناس بطريقة سرية، نرجو من سماحتكم الجواب، وتخصيص محاضرات تبين عقيدة الشيعة، والسلام عليكم.","title":"الواجب نحو ازدياد نشاط الشيعة في دعوتهم","answer":"الجواب:\n\nهذا الذي ذكره السائل قد بلغنا، وعلم وانتشر، وعرف من أمر الشيعة الرافضة التي يقال لها: الطائفة الاثنا عشرية، ويقال لها: الجعفرية، ويقال لها: الإمامية، ولاسيما بعدما تولى قيادة هذه الدولة الخميني، فإنه انتشر شرهم، وظهر في أماكن كثيرة.\n\nوقد تنبه الدعاة إلى الله، والعلماء الذين هم يعتبرون علماء من أهل السنة، قد تنبهوا لهذا الأمر، ولم يزالوا يحاربون هذا التشيع، وينبهون الناس على خطره، وأنه بدعة نكراء، ووسيلة إلى الشرك بالله، وإلى سب الصحابة -رضي الله عنهم وأرضاهم- وإلى عبادة الحسين، وإلى رجوع الوثنية -والعياذ بالله- فهذا أمر معلوم، والعلماء المعروفون منتبهون لهذا الأمر، وهكذا الدعاة، والتابعون لدار الإفتاء، والتابعون للرابطة، عندهم العلم بهذا، وعندهم بحمد الله من النشاط ما نرجو أن ينفع الله به الأمة.\n\nوالواجب على علماء السنة، وعلى الدعاة إلى توحيد الله، والدعاة إلى السنة في كل مكان، سواء كانوا موظفين، أو غير موظفين، الواجب عليهم أن يضاعفوا من جهودهم في الدعوة إلى السنة، وفي إنكار البدع كلها، ولاسيما بدعة .. وأن يكونوا حريصين على ذلك في خطب الجمعة، وفي سائر خطبهم، وفي جميع أحوالهم، ولاسيما في البلاد التي يكون فيها وجود لهم، ودعوة لهم في تلك البلاد، من طريق السفارات، أو من طرق أخرى؛ لأن هذا هو الطريق الذي يتقى به شرهم، وينبه به المسلمون على هذه البدعة الشنعاء، ولا شك أن الواجب أن تضاعف الجهود منا ومن غيرنا في ذلك. \n\nودعوة الشيعة الخمينية الرافضية الإمامية الجعفرية دعوة شنيعة؛ فإنها تدعو إلى شر كثير، تدعو إلى سب الصحابة، ولعن الصديق وعمر وعثمان، وأن دولتهم باطلة، وأنهم ظالمون، وأنهم ظلموا عليًّا، إلى غير ذلك، ويسبون غالب الصحابة، ويفسقون الكثير منهم، ويكفرون البعض، فهم بين تكفير وتفسيق للصحابة، وإذا كان الصحابة الذين نقلوا السنة، ونقلوا الشرع فساقًا، أو كفارًا، فكيف تكون الشريعة حينئذ؟! وهذا من أعظم البلاء والفساد في الأرض، نعوذ بالله.\n\nوهكذا دعوتهم إلى أن أئمة أهل البيت وعلى رأسهم علي أنهم يعلمون الغيب، وأنهم معصومون، وأنه يجوز أن يدعون من دون الله، وأن يستغاث بهم، وأن ينذر لهم، ويطلب منهم المدد والعون والغوث، كل هذا شرك بالله  وكفر أكبر.\n\nفالواجب على أهل العلم أن يتبينوا أمرهم، وأن يكونوا على بصيرة من أمرهم أينما كانوا حتى يوضحوا للناس هذا البلاء، وحتى يذكرهم به؛ حتى لا يكثر شرهم في أفريقيا، ولا في غيرها، وهكذا في المنطقة الشرقية فيها من يوجد هناك في القطيف وغيره، ويوجد في المدينة بعض الشيء من ذلك. \n\nفالواجب على العلماء أن يبينوا هذا الأمر، وأن يدعوا من حولهم إلى اتباع السنة وتعظيمها، وألا ينقادوا وراء علماء الشيعة الضالين في هذا الأمر الخطير -نسأل الله العافية-. \n\nالسؤال: نسمع أن مساجد السنة حولت إلى حسينيات، والدكتور علي عبدالواحد وأخوه يدعون..؟\n\nالجواب: نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/3143/الواجب-نحو-ازدياد-نشاط-الشيعة-في-دعوتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1501.mp3","categories":["الدعوة والدعاة"]},{"id":7151,"question":"أرى في المجتمع نساء أجنبيات يظهرن وجوههن في أجمل زينة، فهل يجوز أن نلعنها لقوله: تخرج المرأة زانية وتعود زانية؟","title":"حكم لعن المرأة المتبرجة","answer":"الجواب:\n\nليس لك أن تلعنها، ولكن تدعو لها بالهداية، وتنكر عليها المنكر، ولا تلعنها، لا تعن عليها الشيطان، لكن تدعوها إلى الخير، وتنكر عليها المنكر، وتقول: يا أمة اتقي الله، تستري، احتجبي، وتدعو لها بالهداية، وإن كان معها زوج، أو ولي تنصحه، هكذا ينبغي للمؤمن. \n\nالسؤال: إذا كانت كافرة؟\n\nالجواب: ولو كافرة، يؤمر وليها بأن يحجبها في بلاد المسلمين، ويطلب من ولاة الأمور كذلك؛ حتى لا تضر المجتمع، وحتى لا يتأسى بها المسلمات.","link":"https://binbaz.org.sa/fatwas/3178/حكم-لعن-المراة-المتبرجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1536.mp3","categories":["الدعوة والدعاة","الأخلاق المذمومة"]},{"id":7181,"question":"أناس يعتقدون هذا الاعتقاد الذي ذكر في المحاضرة، وقد بينا لهم الحق، لكن لم يقتنعوا، هل يجوز مجالستهم؟ وإذا ماتوا، هل يستغفر لهم؟ وإذا ماتوا عن جهالة هل يستغفر لهم أيضًا؟","title":"حكم مجالسة أهل البدع ومخالطتهم","answer":"الجواب:\n\nإنما عليك البيان، المؤمن والعالم وطالب العلم عليه البيان والدعوة إلى الله، والإرشاد والتوجيه، أما كون المدعو يقبل، ويرضى، ويهتدي فهذا إلى الله  يقول الله : لَيْسَ عَلَيْكَ هُدَاهُمْ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [البقرة:272]، وقال : إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ [القصص:56] يخاطب النبي ﷺ إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [القصص:56].\n\nفالدعاة عليهم البلاغ والبيان والنصيحة، والله يهدي من يشاء، وإذا دعوتهم إلى الخير، إلى التوحيد والإيمان والسنة، وترك البدع، فلم يستجيبوا؛ فقاطعهم، لا تكن صاحبًا لهم، قاطعهم، واهجرهم، ولا تدعهم إلى بيتك، ولا تجب دعوتهم حتى يدعوا ما هم عليه من الباطل؛ لأنك إذا صحبتهم ودعوتهم، وأجبت دعوتهم؛ أظهرت الرضا بأعمالهم.\n\nفلا ترضى بأعمالهم، لكن النصيحة، استمر فيها، النصيحة والدعوة والتوجيه، وإرسال من ترى أنهم يقدرون ترسله إليهم؛ لعله يدعوهم إلى الله، ولعلهم يستجيبون.","link":"https://binbaz.org.sa/fatwas/3224/حكم-مجالسة-اهل-البدع-ومخالطتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1568.mp3","categories":["الدعوة والدعاة"]},{"id":7209,"question":"إن من ينظر إلى مجهودكم الكريم لا يملك إلا أن يقول: جزاكم الله خير الجزاء، أنت وجميع المشايخ الذين تفرغوا للعلم وتدريسه، وتعلمون فضيلتكم أن بلدنا تستقدم للعمل عندنا من جميع الجنسيات، وتعلمون أن فيهم كثرة لا يدينون دين الإسلام، وسؤالي الآن: ماذا دبرنا لهؤلاء من النصح والدعوة والإرشاد؟ومقابل هذا السؤال يخطر في بالي اقتراح أن يكون قيد التنفيذ -فيعلم الله أنني ناصح لكم- ماذا لو استقدمنا مترجمين لجميع اللغات الموجودة عندنا -أقصد العمال الذين يعملون عندنا- وأحضرنا من المترجمين من يترجم لهم، وقام المشايخ عندنا بالمحاضرات، والتعريف الإسلامي في مقر تواجدهم، فكثير من هؤلاء لا يعلمون عن الإسلام إلا اسمه، فلماذا لا تستغل هذه الظاهرة؟إذا كان لا بد من استقدام هؤلاء المشركين، أو أصحاب الديانات المختلفة، يجب أن يكون هناك مجهود من عندنا لدعوة هؤلاء، ولأن يهدي الله بك رجلًا واحدًا خير لك من حمر النعم.","title":"كيفية دعوة العمال غير المسلمين","answer":"الجواب:\n\nوهذا واقع أيها السائل، وقد -بحمد الله- هيئنا له ما يلزم، وأكدنا على الدعاة، ووضع له برنامج في جميع المملكة لدعوتهم، وتوجيههم إلى الخير بواسطة المترجمين، والكتب المترجمة أيضًا توزع بينهم.\n\nونسأل الله أن يعيننا على الكمال والتمام، وأن ينفع بذلك، وأن يهدي جميع المسلمين وغير المسلمين للدخول في الحق، والثبات عليه.","link":"https://binbaz.org.sa/fatwas/3259/كيفية-دعوة-العمال-غير-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1588.mp3","categories":["الدعوة والدعاة"]},{"id":7218,"question":"نرجو من سماحتكم بمناسبة هذا الجمع الكريم أن توجهوا كلمة، ونصيحة لمن اتخذ التمثيل، والقصص الخيالية سبيلاً إلى الدعوة إلى الله، لأن كثيرًا من الشباب الصالح -جزاهم الله خيرًا- يفعلون هذا الآن؟","title":"حكم التمثيل والقصص الخيالية لغرض دعوي","answer":"الجواب:\n\nقد سبق منا غير مرة أن التمثيل لا يصلح، وأنه كذب، كون الإنسان يمثل نفسه أنه عمر بن الخطاب، أو أنه أبو جهل، أو أنه أبو لهب، أو أنه فلان، أو أنه فلان، لا يصح، الواجب أن تكون الدعوة والتعليم والتوجيه على الطريقة التي سلكها العلماء، وسلكها أصحاب النبي ﷺ وأتباعهم.\n\nيقوم المعلم، أو المرشد، أو الواعظ فيذكر بالله، وبحقه، ويحذر من غضبه، ولا يحتاج أن يقول: أنا فلان، وأنا فلان، يمثل نفسه بأنه فلان، أو فلان؛ لأن هذا كذب، ولو كان قصد خيرًا.\n\nوكذلك إحداث القصص التي لا أساس لها، يخشى أن تكون من الكذب، ينبغي له أن يوضح للناس ما هو واضح، وما هو بين من أمر الخير، وما هو بين من أمر الشر؛ حتى يحذروا الشر، وحتى يرغبوا في الخير بالآيات والنصوص التي جاءت عن رسول الله -عليه الصلاة والسلام-.\n\nيعني يكفي المؤمن في تعليمه وفي وعظه وتذكيره ما كفى الأولين، مع البعد عن الكذب الذي هو التمثيل، أو القصص التي لا أساس لها .. قصص غير واقعة، جرى كذا، وجرى كذا، فلان صار له كذا، وصار له كذا، وهو ما له حقيقة، فلانة صار لها كذا، وصار لها كذا، وهي ما لها حقيقة. أخشى أن يكون هذا من الكذب الذي نهى الله عنه. \n\nيقول النبي ﷺ: ويل للذي يحدث فيكذب ليضحك به القوم، ويل له، ثم ويل له هكذا الذي يحدث ليزجر القوم، أو ليعظ القوم فيكذب، أخشى عليه من هذا، هذا هو الذي ظهر لي.","link":"https://binbaz.org.sa/fatwas/3267/حكم-التمثيل-والقصص-الخيالية-لغرض-دعوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1595.mp3","categories":["الأخلاق المذمومة","الدعوة والدعاة"]},{"id":7235,"question":"ما حكم مجالسة من لم يصلوا، بالرغم من أنهم أقارب لنا؟ ونفس السؤال ما حكم زيارة القبور؟","title":"حكم مجالسة أقارب لا يصلون ودعاء الموتى","answer":"الجواب:\n\nهذا له تعلق بالمحاضرة، وكذلك السؤال الذي قبله متعلق بالشيعة، له تعلق بالمحاضرة. \n\nأما أقاربك الذين لا يصلون، هؤلاء الواجب مقاطعتهم، وألا تزورهم، وألا يزوروك، وألا تدعهم إلى وليمة، وألا تقبل دعوتهم إلى وليمة، بل عليك أن تقاطعهم؛ حتى يهديهم الله، ويصلوا؛ لأن ترك الصلاة منكر عظيم، بل كفر، وضلال كما قال النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر وقال -عليه الصلاة والسلام-: بين الرجل وبين الكفر والشرك ترك الصلاة.\n\nفالواجب عليك أن تقاطعهم، وأن تبتعد عنهم، إلا إذا قبلوا النصيحة، فعليك أن تنصح، وتبين لهم أنهم قد فعلوا منكرًا عظيمًا، وكفرًا بواحًا، وشرًّا مستطيرًا.\n\nفعليك أن تنصحهم، وتبين لهم خطأ ما وقعوا فيه، وأنه منكر عظيم، وأنه كفر وضلال، لعل الله يهديهم بأسبابك، وعليك أيضًا أن تحرض من له كلمة يقدرونها منه، أن ينصحهم، ويوجههم إلى الخير، فإن أجابوا؛ فالحمد لله، وإلا فوجبت مقاطعتهم، وهجرانهم حتى يتوبوا من هذا العمل السيئ. \n\nأما زيارة القبور لطلب الموتى، والاستغاثة بالموتى هذا كفر أكبر، هذا شرك أكبر، الذي يزور الموتى كالذي يزور الحسين في مصر، أو عبدالقادر في العراق، أو غيرهم، يسألونهم قضاء الحاجات، أو المدد، المدد هذا كفر أكبر.\n\nوهكذا في أي بلاد من يزور الموتى لطلب الحاجات منهم، وشفاء المرضى، أو المدد، أو العون هذا كفر أكبر، هذا دين المشركين الأولين -نعوذ بالله- هذا دين قريش الكفار، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/3302/حكم-مجالسة-اقارب-لا-يصلون-ودعاء-الموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1627.mp3","categories":["الدعوة والدعاة","حكم الصلاة وأهميتها"]},{"id":7248,"question":"لي أخ من الأب يسكن في بيت مستقل، وأود أن أصله، ولكن إذا جلست معه؛ بدأ يتكلم في هذا، ويذم في ذاك من أفراد العائلة؛ لأنه تعب نفسيًّا ويعزو تعبه ومرضه إلى هؤلاء الناس الذين يذكرهم بسوء، مع العلم أنني أحاول أن يبتعد عن هذا الطريق، ولكنه يصر على ذلك، فما هو رأي فضيلتكم، هل أتركه بدون زيارة، أو أقلل الزيارة، أم ماذا أفعل؟","title":"حكم قطع زيارة القريب العاصي","answer":"الجواب:\n\nتزوره وتنصحه، وتساعده على أمور دنياه ودينه حسب طاقتك، ولا تقطع زيارته لأن هذه طبيعة الإنسان، من يسلم من الغيبة؟ قل من يسلم، فإن أكثر الناس يتفكهون بالغيبة، فعل فلان كذا، وقال فلان كذا، وفلان فيه كذا، وفلان فيه كذا، لكن تنصحه، تقول له: اتق الله، هذا يا أخي لا يجوز، هذا حرمه الله، الله يقول: وَلَا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12]، ترد عن عرض إخوانك في الغيب.\n\nيقول النبي ﷺ: من رد عن عرض أخيه في الغيب رد الله عن وجهه النار يوم القيامة تجتهد في الرد عن عرض الناس، وتنصح له بالكلام الطيب، والأسلوب الحسن، ولعلك -إن شاء الله- تؤثر عليه بالتكرار، تؤثر عليه إن شاء الله، الحبل الذي هو حبل بتكرار مروره على الحجر يؤثر في الحجر، تكرار النصيحة والكلام الطيب معه بصدر منشرح، وبكلام طيب، وأسلوب طيب يؤثر -إن شاء الله- ويكون له الأجر العظيم.","link":"https://binbaz.org.sa/fatwas/3313/حكم-قطع-زيارة-القريب-العاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1637.mp3","categories":["الدعوة والدعاة"]},{"id":7255,"question":"لي أخ من الأب يسكن في بيت مستقل، وأود أن أصله، ولكن إذا جلست معه؛ بدأ يتكلم في هذا، ويذم في ذاك من أفراد العائلة؛ لأنه تعب نفسيًّا ويعزو تعبه ومرضه إلى هؤلاء الناس الذين يذكرهم بسوء، مع العلم أنني أحاول أن يبتعد عن هذا الطريق، ولكنه يصر على ذلك، فما هو رأي فضيلتكم، هل أتركه بدون زيارة، أو أقلل الزيارة، أم ماذا أفعل؟","title":"حكم قطع زيارة القريب العاصي","answer":"الجواب:\n\nتزوره وتنصحه، وتساعده على أمور دنياه ودينه حسب طاقتك، ولا تقطع زيارته لأن هذه طبيعة الإنسان، من يسلم من الغيبة؟ قل من يسلم، فإن أكثر الناس يتفكهون بالغيبة، فعل فلان كذا، وقال فلان كذا، وفلان فيه كذا، وفلان فيه كذا، لكن تنصحه، تقول له: اتق الله، هذا يا أخي لا يجوز، هذا حرمه الله، الله يقول: وَلَا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12]، ترد عن عرض إخوانك في الغيب.\n\nيقول النبي ﷺ: من رد عن عرض أخيه في الغيب رد الله عن وجهه النار يوم القيامة تجتهد في الرد عن عرض الناس، وتنصح له بالكلام الطيب، والأسلوب الحسن، ولعلك -إن شاء الله- تؤثر عليه بالتكرار، تؤثر عليه إن شاء الله، الحبل الذي هو حبل بتكرار مروره على الحجر يؤثر في الحجر، تكرار النصيحة والكلام الطيب معه بصدر منشرح، وبكلام طيب، وأسلوب طيب يؤثر -إن شاء الله- ويكون له الأجر العظيم.","link":"https://binbaz.org.sa/fatwas/3313/حكم-قطع-زيارة-القريب-العاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1637.mp3","categories":["الدعوة والدعاة"]},{"id":7285,"question":"هل التورية من آفات اللسان، ومن الكذب، أم لا؟ وهل إذا طلب من الشخص التحدث في موضوع ما، فتكلم فيه، وأطال، وتكلم بما هو في الحديث، وأطال فيه، فهل هذه من آفات اللسان؟","title":"حكم كثرة الكلام لإيضاح الحق","answer":"الجواب:\n\nالكلام الذي ينفع الناس، ويوضح الحق، وليس فيه كذب، هذا ليس من آفات اللسان، هذا حق، إذا شرح مسألة مهمة، أو آية يشرحها للناس، أو يفسرها، أو حديثًا يفسره للناس، ويوضح معناه بقدر الحاجة، فهذا من فضائل اللسان، ومما يؤجر عليه الإنسان.\n\nوإنما يكون من آفات اللسان إذا أكثر الكلام بدون فائدة، وأضاع الوقت على الناس، هذا يكون الثرثرة، أما إذا تكلم بقدر الحاجة، وأوضح للناس، وبين للناس الحكم الشرعي، أو صحة الحديث، أو بطلان الحديث، وأنه مكذوب على الرسول ﷺ أو بين لهم معنى الآية، وشرحها لهم بقدر الحاجة، هذا مأجور.","link":"https://binbaz.org.sa/fatwas/3349/حكم-كثرة-الكلام-لايضاح-الحق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1670.mp3","categories":["الدعوة والدعاة"]},{"id":7289,"question":"إذا كان الإنسان يحس أن عنده نقص في دينه، فهل يأمر بالمعروف وهو مقصر، وأحيانًا يخاف من الرياء ولا يوجد عنده علم يبلغه، أن يأمر بالمعروف؟","title":"حكم من يأمر بالمعروف وينهى عن المنكر وعنده تقصير","answer":"الجواب:\n\nبسم الله الرحمن الرحيم، اللهم صل وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد:\n\nفلا شك أن الشيطان يرغب كثيرًا في تثبيط الناس عما أوجب الله عليهم من الأمر بالمعروف والنهي عن المنكر بأنواع الشبه، والتأويلات، فتارة يأتيه من جهة أنك عندك تقصير، ولست بكامل، فكيف تأمر وتنهى! وتارة يأتيه فيقول له: أخشى أن تكون مرائيًا بهذا الأمر، وكل هذا من مكائد الشيطان، فليس من شرط الآمر والناهي أن يكون كاملًا، بل عليه أن يأمر بالمعروف الذي يعرفه، وينهى عن المنكر، ولو كان عنده نقص، ولو كان عنده بعض السيئات.\n\nلكن عليه أن يجاهد نفسه، وأن يتقي الله  ويحرص على استكمال ما أوجب الله، وترك ما حرم الله، ولكن لا يمنعه ذلك من أن يأمر وينهى على بصيرة، لا يأمر إلا على بصيرة، عن علم، كما قال الله -جل وعلا-: قُلْ هَذِهِ سَبِيلِي أَدْعُو إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108] فإذا رأى في بيته، أو من إخوانه من يتكاسل عن الصلاة، هذا أمر واضح، ما يحتاج إلى علم كثير، الصلاة معلومة عند الجميع، فعليه أن يأمره بالمعروف ويقول: يا أخي اتق الله، صل مع المسلمين، حافظ عليها، بالأساليب الحسنة وتخويفه من عقاب الله، ومن مرض قلبه.\n\nأعظم العقوبات أن يصاب القلب بالموت، نعوذ بالله، أعظم العقوبات أن يصاب قلب العاصي بالموت، فلا يعرف معروفًا ولا ينكر منكرًا، ولا يهتم بخير، وقد يصاب بالمرض الشديد الخطير.\n\nفأنت يا أخي عليك أن تأمر وتنهى وإن كنت عندك بعض التقصير، وكذلك لا تقل أخاف من الرياء لا، مر بالمعروف، وانه عن المنكر، وعلم الخير، وادع إلى الخير، وسل ربك العافية، واجتهد في الإخلاص لله، وحارب ما قد يقع من هواجس الرياء، حارب ذلك، واعزم، وصمم على الإخلاص لله، وأبشر بالخير.","link":"https://binbaz.org.sa/fatwas/3357/حكم-من-يامر-بالمعروف-وينهى-عن-المنكر-وعنده-تقصير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1678.mp3","categories":["الدعوة والدعاة"]},{"id":7290,"question":"آمل إرشادي -جزاكم الله خيرًا- فيما يلي تنفيذًا لأمر الله بالأمر بالمعروف، والنهي عن المنكر، فإنني في كل حياتي أحاول ذلك، ولا أتركه، ولكن سبب لي ذلك مشاكل كثيرة في عملي، وفي سكني، ومع جيراني، وكثير من الناس صرح لي بأن دعوتي ينقصها اللين والحكمة، وقد حاولت مرارًا وتكرارًا أن ألين من دعوتي، ولكن لم أستطع، بل تأخذني الحمية أحيانًا لأن أنفعل بطريقة غير حليمة، فماذا أفعل، وماذا تنصحونني؟","title":"بيان ما يجب على الآمر بالمعروف والناهي عن المنكر","answer":"الجواب:\n\nالأذى لا بد منه، يقول الله -جل وعلا- عن لقمان: يَا بُنَيَّ أَقِمِ الصَّلَاةَ وَأْمُرْ بِالْمَعْرُوفِ وَانْهَ عَنِ الْمُنْكَرِ وَاصْبِرْ عَلَى مَا أَصَابَكَ إِنَّ ذَلِكَ مِنْ عَزْمِ الْأُمُور [لقمان:17] فلا بد من الصبر، والله يقول: وَاصْبِرُوا إِنَّ اللَّهَ مَعَ الصَّابِرِينَ [الأنفال:46]، وَاصْبِرْ وَمَا صَبْرُكَ إِلَّا بِاللَّهِ [النحل:127].\n\nفمن قام لله يأمر وينهى، ويدعو إلى الله لا بد أن يناله بعض الشيء كما نال الرسل -وهم أفضل الناس عليهم الصلاة والسلام- وهكذا أتباعهم ينالهم نصيبهم من الأذى، فلا بد من الصبر، فعليك أن تصبر وأن تجاهد نفسك بالعبارات الحسنة، والأسلوب الحسن وعدم الانفعال حتى تكون الدعوة، وحتى يكون الأمر والنهي في محل القبول، وحتى لا يعظم الأذى.","link":"https://binbaz.org.sa/fatwas/3358/بيان-ما-يجب-على-الامر-بالمعروف-والناهي-عن-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1679.mp3","categories":["الدعوة والدعاة"]},{"id":7291,"question":"لنا أقرباء، وأنساب، ورحم يتهاونون في أداء الصلاة، هل يجوز لنا قطيعتهم، علمًا أننا نبادر بالنصح في ذلك؟ نرجو من سماحتكم التفضل بالإجابة على هذا، وجزاكم الله خير الجزاء.","title":"حكم صلة الأرحام المتهاونين بالصلاة","answer":"الجواب:\n\nهنا نقطة كثيرًا ما ننبه عليها، وهي أن الواجب على المؤمن أن يبلغ ما سمع من الخير، هذه ينبغي أن تكون على بالنا دائمًا التبليغ التبليغ، كل يبلغ من ورائه، من أقاربه، وأهل بيته، وأصحابه، وجلسائه ما يسمعه من العلم والفائدة؛ حتى تعم الفائدة، وينتشر العلم في باب صلة الرحم، وغير ذلك.\n\nكان النبي ﷺ إذا حدث أصحابه وذكرهم يقول: فليبلغ الشاهد الغائب، فرب مُبَلَّغ أوعى من سامع ويقول: بلغوا عني ولو آية عليه الصلاة والسلام، ولما خطب الناس يوم عرفة في حجة الوداع قال: وأنتم تسألون عني فما أنتم قائلون؟ قالوا: نشهد أنك قد بلغت ونصحت وأديت، فقال: اللهم اشهد، اللهم اشهد وقال: فليبلغ الشاهد الغائب!. \n\nفعلى إخواننا الذين يسمعون الفائدة في أي مكان من جهة معتمدة أن يبلغوا ما سمعوا من الخير لأهليهم وقراباتهم وجلسائهم على حسب ضبطهم الفائدة، لا يبلغ إلا بعد الضبط والعناية حتى لا يقول على من نقل عنهم ما لم يقولوا، الواجب أن ينتبه وأن يبلغ ما سمع بعد حفظه، وبعد تأكده مما سمع حتى يبلغ الخير، ويكون شريكًا في ذلك.\n\nوالرسول يقول ﷺ: من دل على خير؛ فله مثل أجر فاعله فائدة عظيمة: من دل على خير فله مثل أجر فاعله، وهو حديث صحيح، خرجه الإمام مسلم في صحيحه، وفي اللفظ الآخر يقول ﷺ: من دعا إلى هدى؛ كان له من الأجر مثل أجور من تبعه، لا ينقص ذلك من أجورهم شيئًا ينبغي التبليغ والدعوة إلى الخير من كل من سمع الخير، وحفظه، وتيقنه.\n\nوأما سؤال الأخ عمن له إخوة، أو أقارب لا يصلون، أو كفرة فهؤلاء لهم شأنهم في الصلة، ليسوا مثل المسلمين، ولكن يوصلون، ويحسن إليهم من غير الزكاة؛ لعل الله يهديهم بأسباب ذلك، ولعل الله يقرب قلوبهم إلى الخير بأسباب ذلك. \n\nقال الله -جل وعلا-: لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ [الممتحنة:8] أخبر سبحانه أنه لا ينهانا عن وصل من لم يقاتلنا أن نبرهم ونحسن إليهم، وثبت في الصحيح أن أم أسماء بنت أبي بكر -رضي الله عنها- وفدت إليها في المدينة في الصلح الذي بين النبي ﷺ وبين أهل مكة، وهي مشركة، وفدت إليها ترغب المال، ترغب الصلة، فاستأذنت أسماء النبي -عليه الصلاة والسلام- في أن تصلها، فقال النبي: صليها. \n\nوكان عمر  يهدي إلى أخ له في مكة وهو مشرك في الهدنة التي حصلت بين النبي ﷺ وبين أهل مكة، فإذا كان لك أقارب كفار؛ فلا مانع، والأفضل أن تهدي إليهم، وتحسن إليهم؛ لعلهم يهتدون، ولعلهم يستجيبون لدعوة الإسلام.\n\nوهكذا إذا كان لك أخ لا يصلي، أو يتعاطى الخمور، أو يتعاطى المعاصي الأخرى؛ فإنك مع دعوته إلى الله ومع إرشاده إلى الخير ومع إنكار المنكر عليه؛ لا بأس أن تصله، إذا كان فقيرًا، لا بأس أن تصله بشيء من المال؛ تقريبًا لقلبه، ودعوة له إلى الإسلام. \n\nفإذا أصر على ما يفعل من الباطل؛ فالمشروع لك أن تهجره إذا كان هجره يرجى فيه الفائدة والخير، أما إن كان هجره لا يزيده إلا شرًا؛ فإنك تستمر في نصيحته والإنكار عليه؛ لعل الله يهديه بأسبابك مع صلته إن كان فقيرًا ومواساته، فإن المال له أثره في القلوب، والإحسان إلى الناس يؤثر في قلوبهم، الله -جل وعلا- يقول: وَأَحْسِنُوا إِنَّ اللَّهَ يُحِبُّ الْمُحْسِنِين [البقرة:195]، ويقول: إِنَّ رَحْمَتَ اللَّهِ قَرِيبٌ مِنَ الْمُحْسِنِينَ [الأعراف:56].\n\nويقول الشاعر:\n\n\n\t\n\t\t\n\t\t\tأحسن إلى الناس تستعبد قلوبهم\n\t\t\tفطالما استعبد الإنسان إحسانًا","link":"https://binbaz.org.sa/fatwas/3359/حكم-صلة-الارحام-المتهاونين-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1848.mp3","categories":["الدعوة والدعاة"]},{"id":7294,"question":"أبي لا يُقيم الصلاة في المسجد، ولا في البيت، فهل إذا أمرته بإقام الصلاة ولم يصل، هل يجب علي أن أخرج من البيت، أم لا؟","title":"كيفية نصيحة الأب الذي لم يصلِّ","answer":"الجواب: عليك أن تنصحه دائمًا، وتجتهد في نصيحته بالأسلوب الحسن، والكلام الطيب، وينبغي أن لا تخرج؛ لأن وجودك عنده من أسباب هدايته، قال الله -جل وعلا- في المشركين الوالدين: وَإِنْ جَاهَدَاكَ عَلَى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] فأمر الله ولد المشركين أن يصاحبهما في الدنيا معروفًا، ولم يأمره بالخروج عنهما.  فأنت تصاحبه في الدنيا معروفًا، بالكلام الطيب، وقضاء حاجته الجائزة، طعامه وشرابه وكسوته، وتنصح له دائمًا، تدعو له في سجودك، وفي آخر صلاتك، وفي كل وقت أن الله يهديه، وأن الله يمن عليه بالتوفيق، وأن يشرح قلبه للإيمان، ولا تخرج عنه، لكن بالأساليب الحسنة، بالكلام الطيب، واللين؛ لعل الله أن يهديه بأسبابك. ثم أيضًا تحرص على الناس الطيبين الذين يعرفهم، ويقدرهم؛ حتى يأتوا إليه، وحتى ينصحوه، ويساعدوك على أسباب الهداية.","link":"https://binbaz.org.sa/fatwas/3372/كيفية-نصيحة-الاب-الذي-لم-يصل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1690.mp3","categories":["الدعوة والدعاة"]},{"id":7295,"question":"في المثال الذي ذكره فضيلة الشيخ المنيعي عن قول الله تعالى: لُعِنَ الَّذِينَ كَفَرُوا مِنْ بَنِي إِسْرَائِيلَ [المائدة:78] الآية عن بني إسرائيل، هل يعني ذلك أنني إذا نهيت شخصًا عن منكر ما، ثم لم ينته، فهل يعني ذلك أن أمتنع عن مؤاكلته، والعيش معه حتى ينتهي عن منكره مهما كان هذا المنكر بسيطًا، نرجو توضيح ذلك؟","title":"حكم هجر من لم ينته عن المنكر","answer":"الجواب: نعم هذه من عقوبة بني إسرائيل، الإنسان إذا رأى أخاه على المنكر؛ فعليه أن يستمر معه في النصيحة والتوجيه، ولا يتخذه مع ذلك صديقًا، ولا جليسًا، ولا أكليًا وهو على منكره، هذه هي التي وقعت في بني إسرائيل، بل يجتهد في إزالة المنكر بالنصيحة والتوجيه، وإذا لم يؤد ذلك إلى المطلوب؛ هجره، شرع له هجره، والهجر للعلماء فيه أقوال ثلاثة: أحدها: أنه مستحب مطلقًا. والثاني: واجب مطلقًا. والثالث: التفصيل، إن رأى أنه مؤثر، وأنه يردعه عن المنكر؛ هجره، وإن رأى أن الهجر يزيده شرًا، ويزيده بعدًا من الهدى؛ لم يهجره، واستعمل النصيحة والإنكار معه دائمًا من دون هجر. وهذا القول الوسط هو أقربها، وأظهرها في الدليل، والنبي ﷺ هجر قومًا وترك آخرين، هجر قومًا رأى ﷺ أنه يؤثر عليهم الهجر، كما هجر كعب بن مالك، وصاحبيه، وغيرهم؛ لأنه رأى أن هذا يؤثر عليهم، ويسبب هدايتهم وانتباههم، وعدم عودهم إلى ما أنكر عليهم. وترك آخرين: كعبدالله بن أبي سلول، وجماعة من المنافقين؛ لأنه رأى في هجرهم خطرًا على المسلمين، فترك هجرهم واستعمل معهم التعليم والنصيحة؛ رجاء أن يهديهم الله، وأن يسلم الناس من شرهم، فأنت مع من تبتلى به هكذا، إن رأيت أن هجره، وعدم الجلوس معه، وعدم الاتصال به أنفع؛ فافعل ذلك، وإن رأيت أن الاتصال به بعض الأحيان، وزيارته بعض الأحيان، والاجتماع به بعض الأحيان أقرب إلى إنكار المنكر، وإلى هدايته فافعل ذلك، لا تقطعه بالكلية، إذا رجوت أنه يزول المنكر بهذه الزيارة، وأن هجره بالكلية قد يزيده شرًا، ويبعده من الهدى، فاستعمل ما تراه أصلح، لا من أجل دنياك وشهواتك لا، بل من أجل مصلحة الدين، ومسألة الدين، رزق الله للجميع التوفيق والهداية. السؤال: وإن كان قريبًا؟ الجواب: وإن كان قريبًا نعم، قريبًا أو بعيدًا.","link":"https://binbaz.org.sa/fatwas/3365/حكم-هجر-من-لم-ينته-عن-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1684.mp3","categories":["الدعوة والدعاة"]},{"id":7296,"question":"في المثال الذي ذكره فضيلة الشيخ المنيعي عن قول الله تعالى: لُعِنَ الَّذِينَ كَفَرُوا مِنْ بَنِي إِسْرَائِيلَ [المائدة:78] الآية عن بني إسرائيل، هل يعني ذلك أنني إذا نهيت شخصًا عن منكر ما، ثم لم ينته، فهل يعني ذلك أن أمتنع عن مؤاكلته، والعيش معه حتى ينتهي عن منكره مهما كان هذا المنكر بسيطًا، نرجو توضيح ذلك؟","title":"حكم هجر من لم ينته عن المنكر","answer":"الجواب: نعم هذه من عقوبة بني إسرائيل، الإنسان إذا رأى أخاه على المنكر؛ فعليه أن يستمر معه في النصيحة والتوجيه، ولا يتخذه مع ذلك صديقًا، ولا جليسًا، ولا أكليًا وهو على منكره، هذه هي التي وقعت في بني إسرائيل، بل يجتهد في إزالة المنكر بالنصيحة والتوجيه، وإذا لم يؤد ذلك إلى المطلوب؛ هجره، شرع له هجره، والهجر للعلماء فيه أقوال ثلاثة: أحدها: أنه مستحب مطلقًا. والثاني: واجب مطلقًا. والثالث: التفصيل، إن رأى أنه مؤثر، وأنه يردعه عن المنكر؛ هجره، وإن رأى أن الهجر يزيده شرًا، ويزيده بعدًا من الهدى؛ لم يهجره، واستعمل النصيحة والإنكار معه دائمًا من دون هجر. وهذا القول الوسط هو أقربها، وأظهرها في الدليل، والنبي ﷺ هجر قومًا وترك آخرين، هجر قومًا رأى ﷺ أنه يؤثر عليهم الهجر، كما هجر كعب بن مالك، وصاحبيه، وغيرهم؛ لأنه رأى أن هذا يؤثر عليهم، ويسبب هدايتهم وانتباههم، وعدم عودهم إلى ما أنكر عليهم. وترك آخرين: كعبدالله بن أبي سلول، وجماعة من المنافقين؛ لأنه رأى في هجرهم خطرًا على المسلمين، فترك هجرهم واستعمل معهم التعليم والنصيحة؛ رجاء أن يهديهم الله، وأن يسلم الناس من شرهم، فأنت مع من تبتلى به هكذا، إن رأيت أن هجره، وعدم الجلوس معه، وعدم الاتصال به أنفع؛ فافعل ذلك، وإن رأيت أن الاتصال به بعض الأحيان، وزيارته بعض الأحيان، والاجتماع به بعض الأحيان أقرب إلى إنكار المنكر، وإلى هدايته فافعل ذلك، لا تقطعه بالكلية، إذا رجوت أنه يزول المنكر بهذه الزيارة، وأن هجره بالكلية قد يزيده شرًا، ويبعده من الهدى، فاستعمل ما تراه أصلح، لا من أجل دنياك وشهواتك لا، بل من أجل مصلحة الدين، ومسألة الدين، رزق الله للجميع التوفيق والهداية. السؤال: وإن كان قريبًا؟ الجواب: وإن كان قريبًا نعم، قريبًا أو بعيدًا.","link":"https://binbaz.org.sa/fatwas/3365/حكم-هجر-من-لم-ينته-عن-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1684.mp3","categories":["الدعوة والدعاة"]},{"id":7301,"question":"هناك بعض الناس إذا أمرتهم ونهيتهم قال أحدهم: أنا حر، ما لك دخل، ولا أنت داخل معي القبر، نرجو توضيح ذلك، وحدود الحرية المسموح بها على ضوء قوله تعالى: لَا إِكْرَاهَ فِي الدِّينِ [البقرة:256].وكذلك بعض الناس إذا أمرتهم، أو نهيتهم عن منكر، كبعض وسائل الإعلام وغيرها، قال: لو فيه شيء ما جابته الدولة، وغير ذلك؟","title":"حكم من أُمر بمعروف فقال أنا حر","answer":"الجواب: هذا غلط، قوله: أنا حر هذا غلط، هذه كلمة شيطانية لا تجوز، ليس بحر في ترك ما أوجب الله، أو فعل ما حرم الله، حر في التصرف في ماله، وبيعه وشرائه، إذا كان رشيدًا؛ فهو حر في هذه الأمور، أما في ركوب معاصي الله أو في ترك ما أوجب الله؛ فليس بحر، بل يجب عليه التقييد بالدين، وأن يلتزم بالدين، وأن لا يخالف ما شرعه الله، وعلى إخوانه الإنكار عليه إذا تعدى الحدود، فترك الواجبات، أو بعض الواجبات، أو ركب بعض المحارم ليس بحر، بل يجب الإنكار عليه، ويجب أن يتقيد بشرع الله، يقول الله سبحانه: تِلْكَ حُدُودُ اللَّهِ فَلَا تَعْتَدُوهَا [البقرة:229]. ويقول في المعاصي: تِلْكَ حُدُودُ اللَّهِ فَلَا تَقْرَبُوهَا [البقرة:187] فالمؤمن مأمور، المسلم مأمور بأن يلزم الحدود، ولا يتجاوز الحدود، ويتقيد بشرع الله، ويتباعد عن محارم الله، أما قوله: أنا حر، ما أنت معي في القبر، هذا غلط، هذا الكلام من مكائد الشيطان، يود الشيطان أن كل واحد يقول هذا؛ حتى لا يقبل من أخيه نسأل الله العافية. وكذلك قول بعض الناس: لو كان هذا منكر لما دخل في البلاد، أو لما أقرته الدولة هذا غلط، ليست الدولة معصومة، قد يقع منها ما يقع من غيرها من الخطأ والزلل، قد يدخل الشيء خفية عليها، وقد يوجد بين الناس ما لم تسمح به الدولة.  فالمقصود: أن الدولة ليست ميزانًا، الميزان: ما قال الله ورسوله، الدولة قد تخطئ، وقد تغلط، وقد تعصي، وليست معصومة، وليست حجة في حل ما حرم الله، ولا في إسقاط ما أوجب الله، هذا ما يقوله إلا جاهل لا يعرف الشرع، الشرع: قال الله، قال رسوله، وليس ما قالت: الدولة الفلانية، أو الدولة الفلانية.","link":"https://binbaz.org.sa/fatwas/3368/حكم-من-امر-بمعروف-فقال-انا-حر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1686.mp3","categories":["الدعوة والدعاة"]},{"id":7302,"question":"اتهمنا أخا لنا في الله ببعض المحرمات، ولكي نتأكد منه اجتمعنا مرة في منزل مع بعض إخواننا في الله، وحدث أن جاء ذلك الرجل الذي كنا نعده مستقيمًا، ولكن سمعنا من بعض الناس اتهامه ببعض المحرمات، فعندما جاء إلينا بدأنا نتكلم عن بعض هذه المحرمات، وبعد ذلك نتكلم معه لنختبره هل تأثر بهذا الكلام أم لا؟ ونستعمل بعض التشبيهات والتورية، ورأينا أن وجهه تغير بعض الشيء، وبعد ذلك لم يأت إلينا، وكنا نقصد من ذلك التأكد من نسبة هذه الأشياء إليه، وفي نفس الوقت نصيحته، ولكنه يبدو أنه لم يقبل كلامنا؛ لأننا نستعمل هذه التشبيهات، والتورية، والنصيحة على مسمع من المجلس الذي يضمنا، هل نحن مخطئون أم مصيبون في طريقتنا هذه في الأمر بالمعروف والنهي عن المنكر أرشدونا جزاكم الله خيرًا؟","title":"كيفية نصيحة من ظُن به السوء","answer":"الجواب:  على كل حال الواجب على أهل العلم، وعلى الإخوان فيما بينهم التناصح والتعاون على البر والتقوى، وإذا أمكن أن ينصح الإنسان بخلوة مع نفسه ما دام ما أعلن، فينبغي أن ينصح في نفسه، وأن يتصل به من بعض إخوانه في نفسه من غير شهرة بين الناس؛ لأنه لما سمع الكلام ظن أنه مقصود؛ فلهذا تغير.  فالمقصود: أن مثل هذا ما دام الرجل لم يعلن المعاصي، ولم تظهر منه؛ فينبغي أن تكون نصيحته سرًّا بينك وبينه؛ حتى لا يظن أنه متهم بين الناس، وأنه معروف بالمنكر بين الناس، وهو لم يفعل ذلك، ولم يعلنه، ولم يظهره، ولكن إنما هي تهمة وظن قد يكون ظن سوء، فينبغي للمؤمن في مثل هذه الأمور أن تكون نصيحته سرية بينه وبين أخيه؛ لعل الله ينفعه بذلك، فإن النصيحة السرية لها أثر عظيم. أما إذا أظهر المنكر ينكر عليه جهرة لا بأس، إذا عرف بهذا المنكر، تأخر عن الصلوات، أو تعاطى المسكرات جهرة، حلق لحيته -حلق اللحية معروف ظاهر- وما أشبه ذلك، الشيء الظاهر ينكر ظاهرًا، أما ما يظن ظنًا فينبغي أن تكون بينك وبينه، وأن تستعمل العبارات الحسنة: إني أخشى كذا، وقد بلغني كذا، تقول له العبارات المناسبة. فينبغي لك إن كنت تفعل هذا الشيء أن تقلع منه، وأن تحذره يا أخي، وأن تخاف ربك وتراقبه، وما أشبه هذا من الكلام الذي يكون محل عناية، ولعله يؤثر عليه أثرًا كبيرًا؛ لأنك نصحته سرًا وخلوت به، وزرته في محله أو في محل خاص ترجو أن الله ينفع بذلك، أما الإعلان مع عدم ظهور المعاصي، وعدم ظهور البدع؛ فهذا يخشى منه الرد الذي لا يناسب، يعني يخشى منه العكس.","link":"https://binbaz.org.sa/fatwas/3362/كيفية-نصيحة-من-ظن-به-السوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1681.mp3","categories":["الدعوة والدعاة"]},{"id":7325,"question":"إذا كانت وظيفة كل مسلم الأساسية هي الدعوة إلى الله تعالى؛ اقتداء برسول الله ﷺ وصحابته، فما نصيحتكم للعلماء بالمناصرة، ومعاونة جماعة الدعوة المحتسبة؛ لأنه في حالة تقاعسنا عن هذه الدعوة؛ كان ذلك على حساب نشاط المنصرين ودعاة الباطل وسببًا لغضب الله وحلول النقم والبلايا؟","title":"وجوب الدعوة إلى الله","answer":"الجواب:  تقدم في هذا المكان غير مرة أن الواجب على العلماء التعاون في هذا الأمر، وأن الواجب على كل عالم، وكل من لديه علم أن يدعو إلى الله  وينشر الدين، ويصبر على ذلك، ولو من دون أجرة، ولو من دون مكافأة، المكافأة عند الله  كان الصحابة -رضي الله عنهم وأرضاهم- يدعون إلى الله من دون مكافأة، وهكذا الرسل -عليهم الصلاة والسلام- يدعون إلى الله من دون أجر قُلْ لَا أَسْأَلُكُمْ عَلَيْهِ أَجْرًا [الأنعام:90]، إِنْ أَجْرِيَ إِلَّا عَلَى اللَّهِ [سبأ:47].  هكذا العلماء وأهل الخير عليهم أن يدعو إلى الله في أي مكان، حسب ما عندهم من العلمن ويناصروا الحقن ويساعدوا إخوانهم الدعاة في كل مكان؛ حتى ينصر الحق، وحتى تجتمع الكلمة، وحتى يتعلم الجاهل، وحتى يرشد الضال، أما التقاعس هذا ليس من الدين، بل هو مما يزينه الشيطان، ويدعو إليه الشيطان، فلا يجوز التقاعس عن الدعوة إلى الله من أهل العلم. يجب عليهم أن يدعو إلى الله في كل مكان، سواء كانوا قضاة أو مدرسين، أو لا قضاة ولا مدرسين، لكن عندهم علم، عليهم أن يبذلوا وسعهم حسب الطاقة فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] في بلادهم وفي غير بلادهم، مع إخوانهم الدعاة يشجعونهم وينصرونهم ويتفاهمون معهم ويتذاكرون معهم في كل ما قد يخفى؛ حتى تكون الدعوة متعاضدة واحدة، متعاونين متناصرين متفاهمين، وإذا غلط واحد منهم نبهه الآخر، وتفاهم معه الآخر؛ حتى تزول الوحشة، وحتى يحصل التعاون، وحتى تصلح الأخطاء، وتزال الأخطاء، هكذا الواجب على العلماء.","link":"https://binbaz.org.sa/fatwas/3406/وجوب-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1719.mp3","categories":["الدعوة والدعاة"]},{"id":7329,"question":"إذا كانت وظيفة كل مسلم الأساسية هي الدعوة إلى الله تعالى؛ اقتداء برسول الله ﷺ وصحابته، فما نصيحتكم للعلماء بالمناصرة، ومعاونة جماعة الدعوة المحتسبة؛ لأنه في حالة تقاعسنا عن هذه الدعوة؛ كان ذلك على حساب نشاط المنصرين ودعاة الباطل وسببًا لغضب الله وحلول النقم والبلايا؟","title":"وجوب الدعوة إلى الله","answer":"الجواب:  تقدم في هذا المكان غير مرة أن الواجب على العلماء التعاون في هذا الأمر، وأن الواجب على كل عالم، وكل من لديه علم أن يدعو إلى الله  وينشر الدين، ويصبر على ذلك، ولو من دون أجرة، ولو من دون مكافأة، المكافأة عند الله  كان الصحابة -رضي الله عنهم وأرضاهم- يدعون إلى الله من دون مكافأة، وهكذا الرسل -عليهم الصلاة والسلام- يدعون إلى الله من دون أجر قُلْ لَا أَسْأَلُكُمْ عَلَيْهِ أَجْرًا [الأنعام:90]، إِنْ أَجْرِيَ إِلَّا عَلَى اللَّهِ [سبأ:47].  هكذا العلماء وأهل الخير عليهم أن يدعو إلى الله في أي مكان، حسب ما عندهم من العلمن ويناصروا الحقن ويساعدوا إخوانهم الدعاة في كل مكان؛ حتى ينصر الحق، وحتى تجتمع الكلمة، وحتى يتعلم الجاهل، وحتى يرشد الضال، أما التقاعس هذا ليس من الدين، بل هو مما يزينه الشيطان، ويدعو إليه الشيطان، فلا يجوز التقاعس عن الدعوة إلى الله من أهل العلم. يجب عليهم أن يدعو إلى الله في كل مكان، سواء كانوا قضاة أو مدرسين، أو لا قضاة ولا مدرسين، لكن عندهم علم، عليهم أن يبذلوا وسعهم حسب الطاقة فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] في بلادهم وفي غير بلادهم، مع إخوانهم الدعاة يشجعونهم وينصرونهم ويتفاهمون معهم ويتذاكرون معهم في كل ما قد يخفى؛ حتى تكون الدعوة متعاضدة واحدة، متعاونين متناصرين متفاهمين، وإذا غلط واحد منهم نبهه الآخر، وتفاهم معه الآخر؛ حتى تزول الوحشة، وحتى يحصل التعاون، وحتى تصلح الأخطاء، وتزال الأخطاء، هكذا الواجب على العلماء.","link":"https://binbaz.org.sa/fatwas/3406/وجوب-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1719.mp3","categories":["الدعوة والدعاة"]},{"id":7347,"question":"بعد أن منَّ الله علي بنعمة التوحيد في هذه البلاد في الثلاث سنوات الأخيرة، وبإذن الله بعد أن أخذت نصيبًا من العلم النافع في علوم التوحيد وغيره من العبادات؛ وجدت السفر قريبًا -إن شاء الله- إلى بلادي ومسقط رأسي هناك، وكعادة أهل المنطقة، والبلاد يكون هناك الوالدان والأشقاء، وبنات العم، وبنات العمات في استقبالي، وفي نيتي بعد الوصول إلى الأهل هناك أن أقوم بدعوة التوحيد بين الأهل الأقربين خاصة، وأهل المنطقة عامة، فهل يجوز لي أن أصافح هؤلاء القريبات لي من بنات العم، والعمات عند استقبالهم لي، علمًا بأنهم جميعهم يجهلون التوحيد الصحيح، أم لا أصافحهم؟ مع جهلهم التوحيد، وأخشى أن يرفضوا قبول هذه الدعوة مع أنها أساس الدين.","title":"حكم مصافحة الأجنبية ترغيباً في الدعوة إلى الله","answer":"الجواب: الواجب على طالب العلم أن يبذل ما لديه من العلم، وأن يدعو إلى الله في البلاد التي تحتاج إليه، وليس فيه من يقوم مقامه، ويحرص على اللين والرفق، والكلام الطيب، والأسلوب الحسن في إبلاغ الدعوة، وإذا كان أهل بلده يجهلون أشياء من أحكام الله تقدم إليهم، وبين لهم أحكام الله وأرشدهم، ولو وجد بعضهم في نفسه شيئًا فإن العادات التي تخالف الشرع لا يجوز احترامها، وهل عودي الرسل إلا بالعادات المخالفة، الرسل لم يعادوا إلا بالعادات المخالفة، فلا بد من الصبر.  وإذا كان الأمر كذلك؛ فتقدم إليهن قبل ذلك، اكتب إليهن الآن قبل أن تذهب إليهم، اكتب إليهم، وقل لهم: إن من عادة بلادنا كذا وكذا، وإني أوصيكم بترك ذلك، وعدم فعل ذلك؛ حتى يعلمن ذلك وأنت في البلد قبل أن تسافر إليهم، وإذا وصلت إليهم؛ فقل لهم قبل السلام عليهن يا أخواتي ويا بنات عمي ويا كذا ويا كذا، تقول لهم: لقد تعلمت وعلمت أن هذا لا يجوز، والسلام يكون بغير مصافحة هذا مع بنات العم والخال ونحو ذلك. أما مع أخواتك وعماتك وخالاتك فلا بأس، إنما هذا في غير المحارم: كبنت العم، وبنت الخال، وبنت الخالة، والجيران، تسلم عليهم، لكن من دون مصافحة، كيف حالكم؟ كيف أولادكم؟ تحييهم، وترحب بهم، وتسأل عن أحوالهم، لكن من دون مصافحة.  ثبت عنه ﷺ أنه قال: إني لا أصافح النساء لما قدمت إليه بعض النساء يدها قال: إني لا أصافح النساء مع ما أعطاه الله من الإيمان والحكمة والعصمة -عليه الصلاة والسلام- وقالت عائشة -رضي الله عنها-: \"والله ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام -عليه الصلاة والسلام-\".  فالمقصود: أن المؤمن يتأسى بالنبي ﷺ ولا يتطلب رضا الناس من أجل أمر آخر، الله يهدي من يشاء، ويضل من يشاء، عليك أن تعلم ما عليك إن اهتدوا؛ فلهم ولك الأجر، وإن أبوا؛ فقد أديت ما عليك، ليس عليك إلا البلاغ كما هو دأب الرسل -عليهم الصلاة والسلام-.","link":"https://binbaz.org.sa/fatwas/3424/حكم-مصافحة-الاجنبية-ترغيبا-في-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1733.mp3","categories":["الدعوة والدعاة"]},{"id":7358,"question":"بعد أن منَّ الله علي بنعمة التوحيد في هذه البلاد في الثلاث سنوات الأخيرة، وبإذن الله بعد أن أخذت نصيبًا من العلم النافع في علوم التوحيد وغيره من العبادات؛ وجدت السفر قريبًا -إن شاء الله- إلى بلادي ومسقط رأسي هناك، وكعادة أهل المنطقة، والبلاد يكون هناك الوالدان والأشقاء، وبنات العم، وبنات العمات في استقبالي، وفي نيتي بعد الوصول إلى الأهل هناك أن أقوم بدعوة التوحيد بين الأهل الأقربين خاصة، وأهل المنطقة عامة، فهل يجوز لي أن أصافح هؤلاء القريبات لي من بنات العم، والعمات عند استقبالهم لي، علمًا بأنهم جميعهم يجهلون التوحيد الصحيح، أم لا أصافحهم؟ مع جهلهم التوحيد، وأخشى أن يرفضوا قبول هذه الدعوة مع أنها أساس الدين.","title":"حكم مصافحة الأجنبية ترغيباً في الدعوة إلى الله","answer":"الجواب: الواجب على طالب العلم أن يبذل ما لديه من العلم، وأن يدعو إلى الله في البلاد التي تحتاج إليه، وليس فيه من يقوم مقامه، ويحرص على اللين والرفق، والكلام الطيب، والأسلوب الحسن في إبلاغ الدعوة، وإذا كان أهل بلده يجهلون أشياء من أحكام الله تقدم إليهم، وبين لهم أحكام الله وأرشدهم، ولو وجد بعضهم في نفسه شيئًا فإن العادات التي تخالف الشرع لا يجوز احترامها، وهل عودي الرسل إلا بالعادات المخالفة، الرسل لم يعادوا إلا بالعادات المخالفة، فلا بد من الصبر.  وإذا كان الأمر كذلك؛ فتقدم إليهن قبل ذلك، اكتب إليهن الآن قبل أن تذهب إليهم، اكتب إليهم، وقل لهم: إن من عادة بلادنا كذا وكذا، وإني أوصيكم بترك ذلك، وعدم فعل ذلك؛ حتى يعلمن ذلك وأنت في البلد قبل أن تسافر إليهم، وإذا وصلت إليهم؛ فقل لهم قبل السلام عليهن يا أخواتي ويا بنات عمي ويا كذا ويا كذا، تقول لهم: لقد تعلمت وعلمت أن هذا لا يجوز، والسلام يكون بغير مصافحة هذا مع بنات العم والخال ونحو ذلك. أما مع أخواتك وعماتك وخالاتك فلا بأس، إنما هذا في غير المحارم: كبنت العم، وبنت الخال، وبنت الخالة، والجيران، تسلم عليهم، لكن من دون مصافحة، كيف حالكم؟ كيف أولادكم؟ تحييهم، وترحب بهم، وتسأل عن أحوالهم، لكن من دون مصافحة.  ثبت عنه ﷺ أنه قال: إني لا أصافح النساء لما قدمت إليه بعض النساء يدها قال: إني لا أصافح النساء مع ما أعطاه الله من الإيمان والحكمة والعصمة -عليه الصلاة والسلام- وقالت عائشة -رضي الله عنها-: \"والله ما مست يد رسول الله يد امرأة قط، ما كان يبايعهن إلا بالكلام -عليه الصلاة والسلام-\".  فالمقصود: أن المؤمن يتأسى بالنبي ﷺ ولا يتطلب رضا الناس من أجل أمر آخر، الله يهدي من يشاء، ويضل من يشاء، عليك أن تعلم ما عليك إن اهتدوا؛ فلهم ولك الأجر، وإن أبوا؛ فقد أديت ما عليك، ليس عليك إلا البلاغ كما هو دأب الرسل -عليهم الصلاة والسلام-.","link":"https://binbaz.org.sa/fatwas/3424/حكم-مصافحة-الاجنبية-ترغيبا-في-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1733.mp3","categories":["الدعوة والدعاة"]},{"id":7368,"question":"سؤالي هو كما تعلمون أن أبناء المسلمين اليوم يختلطون بالكفار في أماكن العمل، وفي أماكن الدراسة، وفي كل مكان، ونحن نعلم أنه يجب على المسلم أن لا يبدأ الكافر بالسلام، وأن يضطره إلى أضيق الطريق، إلا أن هناك بعض الجهلة تجدهم يسارعون بالسلام على الكفار، والضحك معهم، وتناول الطعام على مائدتهم، بل إن هناك من يخاطب الكفار بقوله: يا أخي، وعندما نقول لهؤلاء: إنه من الواجب علينا أن نبغض هؤلاء الكفار، ونبتعد عنهم؛ يحتجون بقولهم: إن الإسلام دين لين، وسماحة، ويقولون: نحن نريد أن نبين للكفار السماحة الإسلامية حتى يدخلوا في الإسلام، فهل قولهم هذا من الصواب؟ وكيف ندعو هؤلاء الكفار الذين في بلاد المسلمين؟","title":"حكم التساهل في معاملة الكافرين بحجة سماحة الدين","answer":"الجواب: مثل ما سمعت يقول الله -جل وعلا-: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]، ويقول سبحانه: وَلَا تُجَادِلُوا أَهْلَ الْكِتَابِ وهم اليهود والنصارى وَلَا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ [العنكبوت:46].  فإذا خاطبهم بالتي هي أحسن، ودعاهم إلى الله، وأرشدهم يا أبا فلان، أو يا فلان، يا أبا زيد، يا أبا عبدالله، يا أبا حباب، يا أبا فلان، لكن لا يقول: يا سيدي، ولا يقول: يا أخي، يقول: يا أبا فلان، أو يا فلان، أو نحو ذلك من العبارات التي لا يكون فيها غضاضة، فيدعوه إلى الله، ويرشده، ويعلمه، ونحو ذلك؛ لأن هذا هو الواجب، هذا هو الطريق السوي.  النبي ﷺ قال لسعد بن عبادة لما زاره يعوده في مرضه، وكان عبدالله بن أبي قد تكلم بكلام قبيح على النبي ﷺ لما مر على جماعة وفيهم عبدالله بن أبي، وأرشدهم النبي ﷺ ودعاهم إلى الله، وتلا عليهم القرآن؛ قام عبدالله بن أبي وتكلم، وخمر وجهه، وقال: لا تغبروا علينا، لما وجد غبار الدابة، وقال: يا فلان لا أحسن ما تقول، فإن كان حقًا؛ فلا تغشانا في محلاتنا، واجلس في بيتك حتى يأتيك من تقص عليه، فقام بعض الصحابة وقال: لا يا رسول الله، بل اغشنا به في محلاتنا، وادعنا فإنا نحب أن نسمع منك، فقام لهؤلاء أنصار، ولهؤلاء أنصار، حتى كادت أن تقع فتنة كبيرة، فهدأهم النبي وسكنهم -عليه الصلاة والسلام- ثم لما وصل إلى سعد بن عبادة أخبره قال: أشعرت بما فعل أبو الحباب؟! ما قال الخبيث، الكافر الذي فيه ما فيه؟ قال: أما شعرت ما فعل أبو الحباب؟ يعني عبدالله بن أبي، كان رأسًا في الخزرج، فقال: يا رسول الله إنه لا تعجل عليه، ارفق به، فإن هذا الرجل كان أهل المدينة قد أجمعوا على ترأسه، على تتويجه أن يكون ملكًا عليهم، فلما جاء الله بك؛ بطل هذا الأمر، وحرم هذا الأمر، ولهذا شرق بالدعوة، وعظم عليه الأمر، وأبغض هذه الدعوة بسبب ما فاته من الرياسة، فرفق به النبي ﷺ ولم يقل له ..... ما لا فيه الخبيث، بل قال: ما فعل أبو الحباب، ولم يزل يرفق به حتى مات على نفاقه -نسأل الله العافية-.","link":"https://binbaz.org.sa/fatwas/3447/حكم-التساهل-في-معاملة-الكافرين-بحجة-سماحة-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1753.mp3","categories":["الدعوة والدعاة"]},{"id":7369,"question":"هل لكم أن تبينوا لنا بالتفصيل ماذا يجب علينا كمسلمين تجاه الكفار الذين يعملون معنا في بلادنا؟","title":"واجب المسلمين تجاه الكافرين العاملين في بلادهم","answer":"الجواب: نعم ننصحك بأن تدعوهم إلى الله، وترشدهم إلى الخير، وترفق بهم، ولا تكثر السب، والشتم والعنف، عليك بالرفق والحكمة والكلام الطيب والدعوة إلى الله  وأن تنصح في عملك، وأن تكون خيرًا منهم، وأنصح منهم في عملك حتى يؤثرك الناس عليهم، إذا نصح المسلمون؛ وجودوا العمل، وأتقنوا العمل، قدمهم الناس على الكفار، فإذا أساء المسلم، وغش في عمله قد يقدمون عليه الكافر، إذا رأوا نصح الكافر. فعلى المسلم أن ينصح في عمله، وألا يكون غشاشًا ولا خائنًا وأن يجتهد في العمل حتى يؤثره المسلمون على أعداء الله الذين يستقدمون للعمل، وإذا كنت معهم؛ فانصح لهم، وادعهم إلى الله، ووجههم إلى الخير، وتعاون معهم في الخير، لا في الشر.","link":"https://binbaz.org.sa/fatwas/3453/واجب-المسلمين-تجاه-الكافرين-العاملين-في-بلادهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1757.mp3","categories":["الدعوة والدعاة"]},{"id":7373,"question":"ما هي نصيحتكم لإخوانكم المسلمين تجاه الغزو الفكري الذي يداهمنا هذه الأيام في المجلات، والصحف، ومحلات الفيديو الفاسدة، ماذا يجب علينا فعله؟ هل السكوت عن ذلك نأثم عليه؟ ماذا نفعل جزاكم الله خيرًا؟","title":"واجب المسلم تجاه الأفكار الهدامة","answer":"الجواب:  الواجب على المسلمين في كل مكان، وفي كل عصر محاربة الأفكار الهدامة، والصحف الهدامة، والكتب الهدامة، والأشخاص الهدامين في كل مكان، وفي كل عصر، في هذا العصر وقبله وبعده، هكذا شرع الله للعباد أن يجاهدوا، ولا يتأخروا عن الجهاد في سبيل الحق، ونصر الدين والدعوة إلى الله  كما قال سبحانه: وَجَاهِدُوا فِي اللَّهِ حَقَّ جِهَادِهِ هُوَ اجْتَبَاكُمْ [الحج:78]، وقال سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ [النحل:125]، وقال سبحانه: قُلْ هَذِهِ سَبِيلِي أَدْعُو إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108]، وقال سبحانه: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا [فصلت:33]. فعلى أهل العلم، وعلى أهل الخير، وعلى كل من له قدرة أن يجاهد بقلمه ولسانه واتصالاته، فيتصل بأصحاب الصحف والمسؤولين وبوزير الإعلام والمسؤولين الآخرين، وبوزارة الداخلية، وأمراء البلاد والعلماء، والمحاكم، كلهم يبذل وسعه فيما يستطيع من الدعوة إلى الله، وتبصير الناس بالخير، وحثهم عليه حتى يقل الشر، ويكثر الخير، لا من جهة الصحافة، ولا من جهة الفيديو، ولا من جهة الأشرطة، إذا وجدت أشرطة رديئة؛ نبه عليها، كل واحد على ثغر، روي عن النبي ﷺ أنه قال: كل رجل على ثغر من ثغور الإسلام فليتق الله وفي اللفظ الآخر: الله الله أن يؤتى الإسلام من جهته.  المقصود: أن المسلمين على ثغور، كل واحد على ثغر في أي بلد، وفي أي قرية، وفي أي قبيلة حتى يؤدي ما عليه، ولاسيما من كان له كلمة تسمع، كالعالم، وأمير البلد، وشيخ القبيلة، والقاضي، والأعيان المعروفين في البلد، كل منهم عليه نصيبه من الدعوة إلى الله، والتذكير بالله، والاتصال بالمسؤولين إذا رأى شيئًا يضر المسلمين، سواء كان ذلك الشيء منشورًا في صحيفة، أو في شريط، أو في غير ذلك من وجوه الشر، يسعى حسب طاقته، لكن بالحكمة، والكلام الطيب، والأسلوب الحسن، وعدم العجلة في الأمور، أو العنف في الأمور؛ لأن العنف والشدة قد تضيع الفائدة، وقد يحصل بها العكس. ولكن مثل ما قال الله : ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]، وقال سبحانه: فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لَانْفَضُّوا مِنْ حَوْلِكَ [آل عمران:159] فليرفق وليجتهد في إزالة الشر، والنصيحة فيه على الطريقة القويمة، التي يحصل بها المطلوب من دون أن يلقى المتكلم شيئًا يضره، أو يكسله عن الأمر والنهي.","link":"https://binbaz.org.sa/fatwas/3472/واجب-المسلم-تجاه-الافكار-الهدامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1776.mp3","categories":["الدعوة والدعاة"]},{"id":7377,"question":"إذا كان لي أخ يدعو إلى النصيحة، ولكنه كان مفرطًا ومشددًا، ثم انقلب على عقبيه، وأصبح نادرًا أن يصلي، فأخذ أهلي منه موقفًا حادًا، وأصبحوا لا يتحملون أي واحد يقوم لهم بالنصيحة، خاصة الإخوة الكبار، وعندما أنصحهم يقولون علي بالألفاظ القبيحة، ويؤذونني، وبعض الأحيان يقوم بعضهم بالاعتداء علي، فما رأيكم هل أصبر عليهم، أم ماذا أفعل؟ وهل أنا برئ مما يعملون؟","title":"ضرورة الصبر عند نصح الأقارب أو من انتكس بعد التزامه","answer":"الجواب: عليك الصبر، قد صبر الرسل -عليهم الصلاة والسلام- وعلى رأسهم نبينا محمد ﷺ قال الله تعالى: فَاصْبِرْ كَمَا صَبَرَ أُولُو الْعَزْمِ مِنَ الرُّسُلِ وَلَا تَسْتَعْجِلْ لَهُمْ [الأحقاف:35] فقد صبر محمد ﷺ وآذوه وسبوه وخنقوه ووضعوا السلى على ظهره إلى غير هذا مما فعل الأعداء، فما جزع وما نكل عن الدعوة إلى الله، بل صبر، قال تعالى: فَاصْدَعْ بِمَا تُؤْمَرُ وَأَعْرِضْ عَنِ الْمُشْرِكِينَ [الحجر:94]، وقال: وَاصْبِرْ وَمَا صَبْرُكَ إِلَّا بِاللَّهِ وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِمَّا يَمْكُرُونَ [النحل:127].  فعلى المؤمن أن يصبر، وعليك أن تجاهد، لكن بالحكمة، بالكلام الطيب، لا بالشدة، وأخوك الذي انتكس لا تيأس منه، انصحوه لعل الله يرده إلى الصواب، انصحوه أنت وإخوانك ورفقاؤك، لا تكن وحدك يكون معك اثنان، ثلاثة، أربعة من الطيبين؛ حتى تأتوا إليه، وحتى تلاحظوه، وتوجهوه إلى الخير بالكلام الطيب، والحكمة، وهكذا إخوانك، وأهل بيتك، لا تيأس ولا تجزع، وإن أوذيت. لو كان كل واحد يؤذى يترك؛ تركت الدعوة، لا بد من الصبر على النصيحة والدعوة، وإن أوذي الإنسان في ذلك، فله أسوة عظيمة في أفضل الخلق وهم الرسل -عليهم الصلاة والسلام- فأنت تصبر، وتحتسب، لا مع أخيك، ولا مع أهل بيتك، ولكن بالكلام الطيب، والأسلوب الحسن، لا بالعنف، ولا بالشدة، ولا بالسب، ولا بالتعيير، لا، بالكلام الطيب، بالآيات القرآنية، والأحاديث النبوية، والأسلوب الحسن، لعلك تنفع.","link":"https://binbaz.org.sa/fatwas/3473/ضرورة-الصبر-عند-نصح-الاقارب-او-من-انتكس-بعد-التزامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1777.mp3","categories":["الدعوة والدعاة"]},{"id":7378,"question":"من أحق بالنصيحة المسلم، أم الكافر؟ وأحيانًا ننصح فلا يستجاب لنا، فهل نستمر في النصح، أم نترك ذلك؟ وكيف أبدأ بالنصيحة، وكيفية طريقة ذلك؟","title":"أولى الناس بالنصيحة","answer":"الجواب: الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه. أولى الناس بالنصيحة المسلمون حتى يستكمل إيمانهم، وحتى يستوفوا ما يجب عليهم؛ لأن في صلاحهم صلاح الناس، وبحسن سمعتهم وسيرتهم يكون ذلك أقرب إلى دخول الناس في الإسلام، وكلما ساءت سمعة المسلمين، وساءت أخلاقهم، وساءت أعمالهم؛ صار في هذا تنفير لغيرهم من الدخول في الإسلام، فالنصيحة للمسلمين وتوجيههم إلى الخير، والحرص على إزالة أخطائهم، وأغلاطهم، والحرص على ظهور سيرتهم الحميدة، واختفاء جميع ما يخالف الشرع المطهر، كل هذا من أهم المهمات، فإخوانك أولى النصيحة بنصيحتك، وأحقهم بنصيحتهم، وأحقهم بذلك أهل بيتك، وأقرب الناس إليك حسب الإمكان والطاقة. ولكن من حيث النفع العام فولاة الأمور أولى الناس بالنصيحة لمن يستطيع ذلك؛ لأن نصيحتهم، تأثرهم ينفع الله بهم الأمة كلها، فمن كان يستطيع ذلك؛ فهو أولى الناس بالنصيحة، وأهمهم بأن ينصح ولاة الأمور توجيهًا وإرشادًا وحثًا على الخير، ثم الأهم في الأهم في المسؤولية. ولكن أهل بيتك لهم خصوصية في البداءة بهم كما قال ﷺ: يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنْفُسَكُمْ وَأَهْلِيكُمْ نَارًا [التحريم:6]، وقال سبحانه : وَأْمُرْ أَهْلَكَ بِالصَّلَاةِ وَاصْطَبِرْ عَلَيْهَا [طه:132] فيقوم المؤمن بهذا وهذا، ولاسيما المسؤولون من العلماء، وأهل المسؤولية في الدولة، النصيحة عليهم في المسؤولين، وفي أهل بيتهم أهم المهمات، ثم بعد ذلك الدعوة إلى الله في الكفار، ونصيحتهم وتوجيههم إلى الخير، وبيان ما خلقوا له من طاعة الله وعبادته لعلهم يهتدون.  وعليك أن تصبر، وتستمر في النصح، وليس عليك الهداية، الله يقول -جل وعلا-: لَيْسَ عَلَيْكَ هُدَاهُمْ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [البقرة:272]، ويقول لنبيه ﷺ: إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [القصص:56]. فالواجب على أهل العلم، وأهل الإيمان، وعلى كل مسلم، وعلى كل مسلمة النصيحة حسب الطاقة، وليس عليه أن يهتدي الناس وأن يقبلوا، وإذا لم يقبل منك أخوك المنصوح، أو غيره من الكفرة، فليس لك أن تجبن وتضعف، بل عليك أن تصبر وتحتسب وتستمر في الخير، يقول النبي ﷺ: من دل على خير فله مثل أجر فاعله ويقول ﷺ لعلي  لما بعثه إلى خيبر إلى اليهود: لأن يهدي الله بك رجلًا واحدًا خير لك من حمر النعم. فالمؤمن في دعوته إلى الله، ونصيحته لعباد الله على خير عظيم، وعلى أجر عظيم، فليحتسب، وليصبر، فإن نفع الله بنصيحته؛ فهذا هو المطلوب، وإلا وجب له الأجر، وباء ذاك المنصوح بالإثم الذي لم يقبل.","link":"https://binbaz.org.sa/fatwas/3468/اولى-الناس-بالنصيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1772.mp3","categories":["الدعوة والدعاة"]},{"id":7388,"question":"أقدم لسماحتكم هذه الوجيزة مستفتيًا عن حكم الإرشاد في المقبرة، وذلك أن يقوم شخص من بين الحضور في المقبرة، أو بيت الميت بالإرشاد والدعوة إلى الله، وإن كان جائزًا فما الدليل على جوازه من السنة، أفيدونا جزاكم الله خيرًا؟","title":"حكم الوعظ والإرشاد عند المقبرة","answer":"الجواب: الإرشاد مطلوب في جميع الأوقات، والنصيحة في جميع الأوقات ليس لها حد محدود، النصيحة والإرشاد مطلوب في المقابر، وفي البيوت، وفي المساجد، وفي المجتمعات، في الطائرة، وفي السيارة، وفي القطار، وفي المركبات الفضائية، وفي كل مكان، النصيحة مطلوبة في كل وقت. وثبت عن النبي ﷺ أنه كان ذات يوم في المقبرة عند قبر ينتظرون دفنه عند الميت، فشرع ينصحهم -عليه الصلاة والسلام- ويعلمهم، ويقول -عليه الصلاة والسلام-: إن الميت إذا حضره أجله؛ نزل إليه ملائكة بيض الوجوه إذا كان مؤمنًا بيض الوجوه معهم كفن من الجنة، وحنوط من الجنة، فيجلسون منه مد البصر، فإذا خرجت روحه وقبضها ملك الموت؛ لم يدعها في يده حتى يأخذوها منه، ويضعوها في ذلك الحنوط، وذلك الكفن ثم ذكر حال الكافر وروحه، والملائكة سود الوجوه من جهته إلى غير ذلك . ذكر في مجلس آخر أيضًا في مقبرة حين جاء ولم يتم حفر القبر، ولم يدفن الميت، جلس مع أصحابه، وقال لهم وهو عند القبر: ما منكم من أحد إلا وقد كتب مقعده من الجنة ومقعده من النار قالوا: يا رسول الله ففيم العمل إذا كانت مقاعدنا معلومة من الجنة والنار ففيم العمل، يعني: فلماذا نعمل؟ ألا نتكل على كتابنا، وندع العمل؟ فقال -عليه الصلاة والسلام-: اعملوا فكل ميسر لما خلق له، أما أهل السعادة فييسرون لعمل أهل السعادة، وأما أهل الشقاوة فييسرون لعمل أهل الشقاوة، ثم تلا قوله تعالى:  فَأَمَّا مَنْ أَعْطَى وَاتَّقَى  ۝ وَصَدَّقَ بِالْحُسْنَى  ۝  فَسَنُيَسِّرُهُ لِلْيُسْرَى  ۝  وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى ۝ وَكَذَّبَ بِالْحُسْنَى  ۝ فَسَنُيَسِّرُهُ لِلْعُسْرَى [الليل:5-10]  فهذا يدل على أن الإرشاد والنصيحة والتوجيه عند المقبرة أمر مطلوب، ولا بأس به؛ لأن الناس عند المقبرة عندهم قلوب مقبلة، وعندهم شيء من اللين لمشاهدة الميت، والمقابر، فهم حريون بأن يتأثروا، وهكذا في البيوت إذا عزى المصابين، إذا جاءهم وزارهم وعزاهم، يذكرهم ويعظهم، ويقول: هذه سنة الله في عباده، الموت حق، ومن لم يمت اليوم مات غدًا، الطريق ماشٍ، وينصح، ويقول لهم: أبشروا واصبروا وصابروا والله يقول: وَبَشِّرِ الصَّابِرِينَ [البقرة:155] وما أشبه ذلك من الوعظ، والتذكير. السؤال: أحد الإخوان قام وخطب فوق القبر، وكثير من الإخوان أنكروا عليه، وقالوا ما يجوز؟ الجواب: الذي نعلم أنه مشروع تذكير الناس على حسب الحال، إن كان المكان يعني المدة طويلة؛ بسط، وإن كان الناس مشغولين؛ خفف، لكن إذا كان الناس جالسين ينتظرون، والقبر لم يكمل، بعض الأحيان يكون القبر يحتاج إلى حفر، وإلى تحسين، وإلى إصلاح، فيجلسون، ويستمعون، وتارة قد يكون جهز كل شيء، فإذا ذكرهم؛ ولو قليلًا، ولو بكلمات قليلة؛ يكون أنفع، تأسيا بالنبي -عليه الصلاة والسلام-. السؤال: لكن يا شيخ فعل هذا جائز؟ الجواب: مشروع، ومن قال: لا، يراجع السنة هي حاكمة على الجميع.","link":"https://binbaz.org.sa/fatwas/3471/حكم-الوعظ-والارشاد-عند-المقبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1775.mp3","categories":["أحكام المقابر","الدعوة والدعاة"]},{"id":7402,"question":"من الملاحظ أن بعض الأجانب -هدانا الله وإياهم وجميع المسلمين- يأتون بنسائهم وبناتهم وهن متبرجات متعطرات، يمشين في الأسواق وفي الشوارع بما يؤدي إلى الفتنة والتقليد الأعمى، فهل من كلمة جزاكم الله خيرًا؟","title":"الإنكار على نساء الأجانب المتبرجات","answer":"الجواب: أما سمعت الله يقول: وَلَا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الْأُولَى [الأحزاب:33]، فالمسلمون عليهم أن ينكروا التبرج على نسائهم، وعلى غير نسائهم، ليس للكفار أن يظهروا شعائرهم في بلاد المسلمين، ليس للكفار أن يظهروا أخلاقهم الذميمة وأعمالهم الذميمة في بلد المسلمين، وقد سبق في الكلمة أن الواجب على الجميع المشاركة في الإنكار، وأن جميع المسلمين هيئة، وهكذا المسلمات هيئة، كلهم هيئة من جهة الله، الله جعلهم هيئة وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ [التوبة:71] أليس المراد الرجال والنساء وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71] كلهم.  فإذا رأيت هؤلاء النسوة من الكافرات تكلم على الرجال معهم ولو أبوا، لكن الكثرة تغلب، إذا كثر الإنكار أثر بإذن الله مع الهيئة، مساعدة مع الهيئة، هذا لا يجوز أن تخرج كاشفة وأن تخرج متعرية في أسواق المسلمين، يقول النبي ﷺ: صنفان من أهل النار لم أرهما، رجال بأيديهم سياط كأذناب البقر يضربون بها الناس، ونساء كاسيات عاريات مائلات مميلات رؤوسهن كأسنمة البخت المائلة لا يدخلن الجنة ولا يجدن ريحها هذا يقوله النبي ﷺ رواه مسلم في الصحيح، ما رآهما، ولكن هذين الصنفين وجدا وهما موجودان الآن خصوصًا صنف النساء، وقد يقع صنف الرجال في بعض الأحيان الذي يضربون بغير حق، لكن المقصود هنا صنف النساء الذي كثر شره. فإذا وجد العاملات والكافرات يكثر هذا الشر، فيجب التعاون على الكلام الطيب، والنصيحة الطيبة، وتقليل الشر، وتكثير الخير بالأساليب الحسنة، بالأساليب المفيدة،. وأنا أعتقد وكل عاقل يعتقد أن كثرة الإنكار عليهم من هذا ومن هذا، ومن هذا يومًا واليوم الآخر، والثالث، والرابع، والليل، والنهار من أسباب زوال هذا الشيء، لكن السكوت والإعراض هو المصيبة، كل واحد يقول: هذا على الهيئة، والهيئة إذا قصرت برأت؟ ما نبرأ، الهيئة إذا قصرت أو عجزت صارت قليلة عجزت، علينا نصيب، على كل مسلم وعلى كل مسلمة نصيبهما من النهي عن المنكر والدعوة إلى الخير بالأساليب التي تنفع ولا تضر، لا بالعنف والمضاربات، لكن بالكلام الطيب والمؤثر، قال الله وقال رسوله، قال الله كذا، قال رسوله كذا، يا عبدالله كذا اتق الله، يا عبدالله هداك الله، أعاذك الله من شر نفسك والشيطان، كلمات طيبة تؤثر ولا تفتح باب شر.","link":"https://binbaz.org.sa/fatwas/3492/الانكار-على-نساء-الاجانب-المتبرجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1796.mp3","categories":["الدعوة والدعاة"]},{"id":7417,"question":"من الملاحظ أن بعض الأجانب -هدانا الله وإياهم وجميع المسلمين- يأتون بنسائهم وبناتهم وهن متبرجات متعطرات، يمشين في الأسواق وفي الشوارع بما يؤدي إلى الفتنة والتقليد الأعمى، فهل من كلمة جزاكم الله خيرًا؟","title":"الإنكار على نساء الأجانب المتبرجات","answer":"الجواب: أما سمعت الله يقول: وَلَا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الْأُولَى [الأحزاب:33]، فالمسلمون عليهم أن ينكروا التبرج على نسائهم، وعلى غير نسائهم، ليس للكفار أن يظهروا شعائرهم في بلاد المسلمين، ليس للكفار أن يظهروا أخلاقهم الذميمة وأعمالهم الذميمة في بلد المسلمين، وقد سبق في الكلمة أن الواجب على الجميع المشاركة في الإنكار، وأن جميع المسلمين هيئة، وهكذا المسلمات هيئة، كلهم هيئة من جهة الله، الله جعلهم هيئة وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ [التوبة:71] أليس المراد الرجال والنساء وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71] كلهم.  فإذا رأيت هؤلاء النسوة من الكافرات تكلم على الرجال معهم ولو أبوا، لكن الكثرة تغلب، إذا كثر الإنكار أثر بإذن الله مع الهيئة، مساعدة مع الهيئة، هذا لا يجوز أن تخرج كاشفة وأن تخرج متعرية في أسواق المسلمين، يقول النبي ﷺ: صنفان من أهل النار لم أرهما، رجال بأيديهم سياط كأذناب البقر يضربون بها الناس، ونساء كاسيات عاريات مائلات مميلات رؤوسهن كأسنمة البخت المائلة لا يدخلن الجنة ولا يجدن ريحها هذا يقوله النبي ﷺ رواه مسلم في الصحيح، ما رآهما، ولكن هذين الصنفين وجدا وهما موجودان الآن خصوصًا صنف النساء، وقد يقع صنف الرجال في بعض الأحيان الذي يضربون بغير حق، لكن المقصود هنا صنف النساء الذي كثر شره. فإذا وجد العاملات والكافرات يكثر هذا الشر، فيجب التعاون على الكلام الطيب، والنصيحة الطيبة، وتقليل الشر، وتكثير الخير بالأساليب الحسنة، بالأساليب المفيدة،. وأنا أعتقد وكل عاقل يعتقد أن كثرة الإنكار عليهم من هذا ومن هذا، ومن هذا يومًا واليوم الآخر، والثالث، والرابع، والليل، والنهار من أسباب زوال هذا الشيء، لكن السكوت والإعراض هو المصيبة، كل واحد يقول: هذا على الهيئة، والهيئة إذا قصرت برأت؟ ما نبرأ، الهيئة إذا قصرت أو عجزت صارت قليلة عجزت، علينا نصيب، على كل مسلم وعلى كل مسلمة نصيبهما من النهي عن المنكر والدعوة إلى الخير بالأساليب التي تنفع ولا تضر، لا بالعنف والمضاربات، لكن بالكلام الطيب والمؤثر، قال الله وقال رسوله، قال الله كذا، قال رسوله كذا، يا عبدالله كذا اتق الله، يا عبدالله هداك الله، أعاذك الله من شر نفسك والشيطان، كلمات طيبة تؤثر ولا تفتح باب شر.","link":"https://binbaz.org.sa/fatwas/3492/الانكار-على-نساء-الاجانب-المتبرجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1796.mp3","categories":["الدعوة والدعاة"]},{"id":7424,"question":"ما هو دور المرأة في الدعوة إلى الله؟ هل يجوز لها أن تخرج دعوة إلى الله خارج حدود منزلها وبلدها؟","title":"دور المرأة في الدعوة إلى الله","answer":"الجواب: عليها نصيبها حسب طاقتها، عليها نصيبها من الدعوة إلى الله، والأمر بالمعروف والنهي عن المنكر في حدود قدرتها، في منزلها ومع أخواتها في الله، وفي بلدها، وفي طريقها، وفي سوقها، وفي كل مكان تستطيع إنكار المنكر والدعوة إلى الله بالحكمة والموعظة الحسنة، مع التزام الحجاب، التزام ما شرع الله بحقها، وفي الأسفار مع المحرم إن كان هناك سفر لا بد أن تكون مع محرمها، فالأمر عام: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة:71].  وهكذا قوله سبحانه: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ [فصلت:33] عام، فالمسألة عامة، لكن كل على قدر حاله، الرجل على قدر حاله، والمرأة على قدر حالها فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].","link":"https://binbaz.org.sa/fatwas/3516/دور-المراة-في-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1820.mp3","categories":["الدعوة والدعاة","قضايا المرأة"]},{"id":7431,"question":"أنا أعمل في عمل أكثره من النصارى، والعمل الذي أعمل فيه يوجد فيه حوالي ثلاثمائة رجل نصراني، وأنا على اتصال معهم، وأريد أن أدعوهم إلى الإسلام، ولكن لا أعرف لغتهم، أرجو من سماحتكم إعطائي كتبًا باللغة الإنجليزية لأوزعها عليهم؟","title":"حكم العمل مع النصارى وكيفية دعوتهم إلى الإسلام","answer":"الجواب: الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، أما بعد:  فطلب الكتب ليس هنا، طلب الكتب في محله في دار الإفتاء في محل العمل، ولا بأس أن يعطى كتب لهؤلاء، لعل الله يهديهم بأسباب ذلك بلغتهم، ولكن من عمل معهم؛ فعليه أن يحذر أن يتخذهم أصدقاء وأصحابًا، ونحو ذلك، ولكن يدعوهم إلى الله، ويرغبهم في الخير، هذا أمر مطلوب؛ لعل الله أن يهديهم به، أو يهدي بعضهم، وقد سمعتم فيما تقدم قول النبي ﷺ لعلي : لأن يهدي الله بك رجلًا واحدًا خير لك من حمر النعم وقال ﷺ: من دل على خير فله مثل أجر فاعله. فمن بلي بهؤلاء في أي عمل نصارى أو غير نصارى أو بوذيين أو غيرهم؛ فليحرص على دعوتهم إلى الله، وأن يكون في إسلامه مثال خير، يكون المسلم الذي يمثل الخير في إسلامه بمحافظته على الصلوات، ومن صدقه في الحديث، ومن أدائه الأمانة، ومن نصحه للمسلمين، ومن بعده عن الغش والخيانة، إلى غير هذا من أخلاق المسلمين الطيبة، حتى يكون قدوة صالحة إذا رآه أعداء الله، ورأوا أخلاقه العظيمة، وصفاته الحميدة؛ كان هذا من أسباب دعوتهم إلى الله بالفعل.","link":"https://binbaz.org.sa/fatwas/3525/حكم-العمل-مع-النصارى-وكيفية-دعوتهم-الى-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1829.mp3","categories":["الدعوة والدعاة"]},{"id":7438,"question":"كيف يكون نصيحة المعاند، أقصد بعدما عرف الحق وأصبح يكره أن يسمع النصيحة، كيف يكون حال الناصح، وإذا سكت هل يأثم؟","title":"كيفية التعامل مع مكابر يأبى النصيحة","answer":"الجواب: يقول الله -جل وعلا-: وَلَا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ [العنكبوت:46] فالظالم المعاند جزاؤه آخر، إذا نصح وكرر عليه وعولج ولم ينفع؛ جزاؤه أمر آخر، وهو التأديب، يرفع إلى ولاة الأمور حتى يؤدب على حسب حاله، بالسجن أو بالضرب أو بغير هذا مما يستحقه، على حسب معصيته، النصيحة أولًا، التوجيه أولًا، فإذا عاند وكابر، ولم يرض بالنصيحة؛ انتقل معه إلى أمر آخر بما شرع الله من العقاب، على حسب ما يراه ولي الأمر، أو يحال إلى المحكمة، فتراه المحكمة من ضرب أو سجن أو تغريم او قتل أو غير هذا، نعم.","link":"https://binbaz.org.sa/fatwas/3524/كيفية-التعامل-مع-مكابر-يابى-النصيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1828.mp3","categories":["الدعوة والدعاة"]},{"id":7455,"question":"وآخر يقول: ما هي نصيحة سماحتكم لأئمة المساجد الذين يرون بعض المجاورين لا يشهدون الصلاة مع الجماعة، ولا ينصاحونهم، ولا يرفعون عنهم، فما هي نصيحتكم؟","title":"نصيحة الشيخ ابن باز لمن عنده أهلية الدعوة إلى الله","answer":"الجواب:  ومما يتعلق بالسابق أن من عنده أهلية ينبغي له أن يتقدم إلى المسؤولين؛ حتى يعطى بطاقة؛ حتى لا يتعرض له بسوء، يعطى بطاقة أنه صالح للدعوة، وحتى يأخذ البطاقة التي تعينه على هذا الأمر إذا كان من أهل العلم، سواء إلى الرئاسة العامة للإفتاء والدعوة، أو إلى وزارة العدل؛ لأنها أهلية لذلك، أو إلى الرئاسة العامة للأمر بالمعروف والنهي عن المنكر؛ حتى يعطى بطاقة تعينه على هذا الأمر.","link":"https://binbaz.org.sa/fatwas/30202/نصيحة-الشيخ-ابن-باز-لمن-عنده-اهلية-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_825_2.mp3","categories":["الدعوة والدعاة"]},{"id":7561,"question":"سؤاله الأخير يقول: هناك مجلات دينية مشهود لها بالأمانة والإصلاح ولكن عيبها أنها تحتوي على صور، وقد فتح الله علي بمبلغ وفير فأحببت أن أحصل على أعداد وفيرة منها، ولكن تذكرت أن الملائكة لا تدخل بيتاً فيه صورة، وأنا الآن في حيرة من أمري فأرشدوني وفقكم الله؟","title":"حكم شراء المجلات الدينية المحتوية على الصور","answer":"الجواب: الذي يظهر أن المجلات المفيدة ينبغي أن تشترى وتوزع بين الناس لعظم فائدتها، ولا يمنع من ذلك ما فيها من الصور، مثل مجلة المجتمع، مثل مجلة الدعوة.. وأشباهها، مجلة البلاغ، هذه مجلات نافعة ومفيدة، فلا ينبغي أن يتوقف في شرائها من أجل الصور، بل يشريها ويوزعها على المحتاجين لها، ويستفيد منها، والصور لا تمنع دخول الملائكة في مثل هذا فإنها مغطاة، هذه صورة مغطاة تغطى بالأوراق التي عليها، فهي تشبه الصور التي تغطى بخرقة فوقها، وتشبه الصور التي في الفراش الذي يوطأ ويمتهن والوسائد، فلا تمنع إن شاء الله من دخول الملائكة، لكن على سبيل الاحتياط ينبغي له أن يضع على الرءوس البوية، يعني: يمسحها بالبوية حتى تزول أحكام الصور؛ يعني زال الرأس زال حكم الصورة، ولا سيما إذا كانت على الغلاف، هذه مكشوفة، إذا كانت على الغلاف ينبغي طمسها، يجعل فوقها قرطاسة بالشمع، أو فوق الرأس قرطاسة بالشمع، أو يزيل الرأس بالحبر الذي يزيل معالم الرأس، أو بشيء من البوية ويزول الحكم. نعم.\nوفي الحقيقة: أن هذا الشيء الذي ذكره السائل مؤلم، ما كان ينبغي لهذه المجلات الطيبة أن تستعمل الصور؛ لأن التصوير محرم، والرسول ﷺ شدد في ذلك وقال: كل مصور في النار، وقال: أشد الناس عذاباً يوم القيامة المصورون، وقال لـعلي: لا تدع صورة إلا طمستها، فما كان ينبغي لهؤلاء الذين يصدرون هذه المجلات الطيبة ما كان ينبغي لهم أن يضعوا الصور، فنصيحتي لهم جميعاً أن لا يضعوها، وأن يتركوا الصور، فتكون هذه المجلات سليمة طيبة بعيدة عن هذا التيار الذي وقع فيه الناس، هذه نصيحتي لإخواني في الدعوة، وفي مجلة المجتمع، والبلاغ وغيرها، نصيحتي لهم جميعاً أن لا يضعوا فيها صوراً، وكذلك إذا كتبوا فيها مقالاً لأحد أن لا يضعوا صورته إلا بإذنه حتى لو أذن لا ينبغي أن يصوروه على الصحيح، حتى لو أذن لا يصورونه، وأنا أحرج كل من نقل عني مقالاً أن يضع صورتي، أنا لا أسامحه، ولا أبيحه أن يضع صورتي، كل من كتب عني أنا أحرجه أن يضع صورتي، ولا أرضى بذلك؛ لأني أعتقد أنه لا يجوز التصوير مطلقاً، فأنا أقول لكل من نقل عني في أي مجلة أو في أي جريدة: لا أبيحه ولا أسامحه أن يضع صورتي، هذا الذي أقوله لإخواني جميعاً، وأنصح به إخواني جميعاً، وأبلغهم إياه من طريق هذا المنبر أني لا أرضى أن توضع صورتي مع أي مقال أو فتوى تنشر عني، هذا اعتقادي، وإن كان التصوير قد يحتاجه بعض الناس مثل التابعية، والجواز، ورخصة القيادة، هذا شيء آخر، قد يقال: إن صاحبها في ضرورة أو مكره فيعفى عنه إن شاء الله؛ لأنه مضطر إلى التابعية ونحوها، لكن نقل المقالات في الصحف ليس هناك ضرورة إلى وضع صورة صاحبها، صاحب المقال معروف وإن لم توضع صورته. نعم.\nالمقدم: هذه الرسالة من المرسل إبرهيم حسين الحويطي من جدة البريد المركزي، في الحقيقة لم يضمن رسالته أسئلة وإنما هي استشارة، يقول في هذه الرسالة الأخ إبراهيم حسين الحويطي من جدة: هل بالإمكان مراسلة البرنامج وعرض ما لديهم من استفسارات حول ما يهمهم من أمور دينية ويخشى من عدم تمكننا من قراءة خطه، وفعلاً الخط رديء للأسباب التي ذكرها، ولكن على الأخ إبراهيم اختصار السؤال ما أمكن، أو الطلب من أحد أقاربه أو أصدقائه كتابة أسئلته لنتمكن من عرضها على الوجه الذي يريد، ونحن مستعدون ونرحب به وبأسئلته، وفي الحقيقة أنا جلست ليلة كاملة لإخراج هذه الكلمات البسيطة.","link":"https://binbaz.org.sa/fatwas/4565/حكم-شراء-المجلات-الدينية-المحتوية-على-الصور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_014/01406.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":7576,"question":"الرسالة الأخيرة في هذا اللقاء وردتنا من إحدى المدرسات، وهي المرسلة (ن) عبد الحق من مكة من المسفلة، تقول: أنا فتاة أقوم بعمل التدريس في أحد المدارس، وإني على وعي بالأمور الدينية بعض الشيء، وعندما ألتقي بالطالبات في حصص الفراغ أقوم بتوجيههن وإرشادهن، ولكني عندما أنتهي من الحديث أقول في نفسي: يمكن أن أقول شيء ولا أفعله، وإنني خائفة من ذلك ولكني والحمد لله أؤدي واجباتي نحو الله على أكمل وجه، فهل أستمر في دعوتي أم لا؟ وقد علمت من رسول الله ﷺ: من يكتم علماً يعلمه يلجم بلجام من نار، ولكم جزيل الشكر؟","title":"ترك الداعي الدعوة بحجة عدم عمله بما يقول","answer":"الجواب: الأخت السائلة، البنت الكريمة السائلة، أنت على خير عظيم، فإن توجيه الطالبات وإرشادهن إلى الخير أمر مطلوب وفيه خير عظيم، ولا تخافي أنك قد تتأخري عن شيء مما دعوت الطالبات إليه، فالشيطان يبذل جهوده الخبيثة في التثبيط عن الخير وعن الدعوة إلى الخير، ويقول للإنسان: إنك قد تدعو إلى هذا ولا تفعل، ليثبطه، وليس كل داعي أو كل داعية يكون كاملاً ويفعل كل شيء، لكن عليه الاجتهاد وعليه الحرص أن يكون من أسبق الناس إلى ما يدعو إليه، وأن يكون من أبعد الناس عما ينهى عنه، ولكن ليس معنى هذا أنه إذا كان عنده شيء من قصور يتأخر، لا، عليه أن يتقدم ويدعو إلى الله ويرشد، سواء كان ذكراً أو أنثى، على المؤمن وعلى المؤمنة أن يجد في هذا الأمر، بالنصيحة، والتوجيه للطلاب والطالبات، ولغيرهن من غير الطالبات أيضاً من نساء البيت، نساء الجيران، وعند الاجتماعات المناسبة في الأعراس وغيرها تكون مؤمنة مرشدة معلمة، وهكذا المؤمن عند اجتماعه بإخوانه في أي مناسبة، أو في البيت أو في المسجد يكون مرشداً على حسب ما عنده من العلم، ولا يغتر بالشيطان ولا يخدعه الشيطان، ليحذر أن يخدعه الشيطان بأن يقول له: اسكت، فإنك قد تدعو إلى شيء ولا تفعل، وقد تنهى عن شيء وتفعل، فإن هذا من تثبيط الشيطان، ولكن ليجتهد وليحرص على أن يكون من السابقين إلى ما يدعو إليه، وعليه أن يكون من المتباعدين عما ينهى عنه ويستعين بالله ويسأله التوفيق، وليستمر في عمله الصالح ودعوته الراشدة، وهكذا المؤمنة المرأة الطالبة والأستاذة عليهما أن تستمرا في الدعوة والتوجيه، وأن تستعينا بالله على العمل بما يرضيه ، والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/4582/ترك-الداعي-الدعوة-بحجة-عدم-عمله-بما-يقول ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_017/01703.mp3","categories":["البدع والمحدثات","الدعوة والدعاة"]},{"id":7634,"question":"سماحة الشيخ! هذه رسالة وردتنا من الموصل من حي المثنى بالجمهورية العراقية تقول المسلمة: إن عائلتها يتكلمون في أعراض الناس بحق وبغير حق، وتقوم بمحاولة منعهم من ذلك، إلا أنهم يردون عليها بكلمات نابية، ويطلبون منها الابتعاد عنهم مما يثير أعصابها، ثم تزوج أخوها، وأصبحت زوجته تهين والدتها ولا تساعدها في المنزل، وتشارك في إهانة الناس في الكلام فيهم، فماذا تفعل هذه الفتاة المسلمة تجاه والديها وزوجة أخيها؟","title":"الواجب تجاه من يعيش في بيئة غير صالحة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: \nفهذه السائلة نرجو لها خيراً كثيراً؛ لأن إنكار المنكر مما شرعه الله لعباده؛ ولأن ذلك من صفات المؤمنين والمؤمنات، كما قال الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]، ولا شك أن الكلام في أعراض الناس والغيبة للناس من المنكرات، قال الله جل وعلا: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] فالغيبة: ذكرك أخاك بما يكره، ولما سئل النبي عن ذلك عليه الصلاة والسلام قال: إن كان في أخيك ما تقول فقد اغتبته، وإن لم يكن فيه فقد بهته.\nوالخلاصة: أنها مأجورة على إنكارها، وأن هذا هو الواجب عليها إذا حضرت، وقد قال النبي ﷺ في الحديث الآخر: من رد عن عرض أخيه بالغيب رد الله عن وجهه النار يوم القيامة، فإنكار المنكر على من فعله أمر لازم على الرجال والنساء جميعاً، وعليها أن تجتهد وأن تسأل الله لهم الهداية، وتخاطبهم بالتي هي أحسن، تنصح لهم، وتذكر لهم أن هذا فيه خطر وأن هذا من أسباب غضب الله، وأشباه ذلك من الكلام، لعل الله أن يهديهم، وهكذا مع زوجة أخيها التي تهين الوالدة وتتكلم في الأعراض تنصحها أيضاً، وتقول لها: اتق الله، وراقبي الله؛ لعل الله يهديها بأسبابها، هكذا أيها الأخت السائلة ينبغي أن تفعلي هذا، استقيمي على إنكار المنكر واصبري، فلا بد من الصبر كما قال لقمان لابنه: يَا بُنَيَّ أَقِمِ الصَّلاةَ وَأْمُرْ بِالْمَعْرُوفِ وَانْهَ عَنِ الْمُنكَرِ وَاصْبِرْ عَلَى مَا أَصَابَكَ إِنَّ ذَلِكَ مِنْ عَزْمِ الأُمُورِ [لقمان:17] فالآمر الناهي لا بد له من أذى، ولا بد له من أن يسمع ما يكره، فعليه أن يصبر، وقد وصف الله الرابحين في كتابه الكريم بأنهم صبر، فقال جل وعلا: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3] هذه صفات الرابحين، صفات أهل الإيمان والصدق: إيمان صادق، وعمل صالح، وتواصٍ بالحق، وتواص بالصبر. نعم.","link":"https://binbaz.org.sa/fatwas/4688/الواجب-تجاه-من-يعيش-في-بيىة-غير-صالحة ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_026/02601.mp3","categories":["البدع والمحدثات","الدعوة والدعاة"]},{"id":7740,"question":"أيضاً في سؤاله الأخير يقول عباس عبد الفتاح: لماذا لا يحدث اجتماع مثلاً بين العلماء جميعاً وشرح وجه الحقيقة حتى يغير ما يحدث في جميع البلدان الإسلامية من هذه العادات؟","title":"مقترح باجتماع علماء الأمة على إنكار بدعة الموالد","answer":"الجواب: قد جرى اجتماعات كثيرة وبحث هذا الموضوع في اجتماعات كثيرة ولكن لا تزال العقول تختلف في فهمها، ولا يزال من ينظر في المسائل العلمية يحصل بينهم خلاف في وجهة النظر، بعضهم يستحسنها لأن فيها دراسة لسيرة النبي ﷺ وبعضهم يقول: لأن فيها يعني فرصة لتوعية الناس وتعليمهم بعض أمور الدين، وبعضهم يحتج بأشياء أخرى ولكن من نظر في الأدلة الشرعية عرف أن هذه الأمور التي يحتج بها لا وجه لها وأن الواجب منع هذه الاحتفالات، وفي الإمكان أن يعلم الناس أحكام الشرع في المجالس العلمية والحلقات العلمية وفي دراسة السيرة النبوية من دون حاجة إلى هذه الاحتفالات، فليست هذه الاحتفالات هي الوسيلة للتعليم بل هناك وسائل أخرى من الإذاعة والصحافة والحلقات العلمية التي يوضح فيها أحكام الشرع وتوضح فيها سيرة النبي عليه الصلاة والسلام من دون حاجة إلى هذه البدع.","link":"https://binbaz.org.sa/fatwas/4939/مقترح-باجتماع-علماء-الامة-على-انكار-بدعة-الموالد ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_034/03404.mp3","categories":["البدع والمحدثات","الدعوة والدعاة"]},{"id":7817,"question":"يقول: ما الكتب التي تنصحونني بالتزود منها في التفسير وفي التوحيد وفي الفقه؟","title":"أهم ما ينصح بقراءته من الكتب","answer":"الجواب: أعظمها القرآن، نوصيك بالقرآن الكريم، الإكثار من قراءة القرآن وتدبر معانيه، وهو أصل كل خير، هو أصدق كتاب، وهو المرجع في كل شيء، نوصيك بالقرآن والعناية به، والإكثار من تلاوته، وتدبر معانيه.\nثم كتب الحديث مثل عمدة الحديث لـعبد الغني بلوغ المرام للحافظ ، المنتقى لـابن تيمية كتب جيدة نافعة على أبواب الفقه تنفعك، كتب العقيدة مثل كتاب التوحيد لشيخ الإسلام : محمد بن عبد الوهاب ، كشف الشبهات ثلاثة الأصول هذه كتب جيدة أيضاً نافعة، ومثل العقيدة الواسطية لشيخ الإسلام: ابن تيمية في العقيدة التدمرية الحموية كلها كتب مفيدة له رحمه الله في العقيدة، وفي الفقه مثل زاد المستقنع للحجاوي عمدة الفقه للموفق ، فهذه كتب مفيدة ....، نسأل الله لنا ولكم التوفيق. نعم.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/5199/اهم-ما-ينصح-بقراءته-من-الكتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05117.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":7820,"question":"هذه رسالة طويلة من مستمع للبرنامج (ش. م) مصري ومقيم بتبوك، كتب مجموعة من الأسئلة يقول: سماحة الشيخ حفظكم الله: ما الشروط التي يجب أن تتوفر في الناس الذين يتعرضون للفتيا ويفتون؟ وهل يجوز للإنسان أن يفتي نقلاً من العلماء الموثوق في علمهم، نرجو أن تحدثونا في هذا الموضوع مأجورين يا سماحة الشيخ؟","title":"الشروط الواجب توافرها في المفتي","answer":"الجواب: الفتوى إنما تجوز للعالم الذي يعرف قال الله قال رسوله، وليس له أن يفتي بمجرد رأيه.\nفالواجب على المؤمن أن يفتي عن علم عن بصيرة بما قاله الله ورسوله، فإذا كان ليس عنده علم يسأل أهل العلم الذين يطمئن إليهم ويعرفهم ويسألهم عما أشكل عليه، ولا يتخبط ولا يقل بغير علم؛ لأن الله قال: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [الأعراف:33] جعله فوق الشرك القول على الله بغير علم.\nوذكر عن الشيطان أنه يأمر بالسوء والفحشاء إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [البقرة:169].\nفالواجب على المسلم أن لا يقول على الله إلا بعلم، فإذا كان ما عنده علم يسأل أهل العلم، وليس له الكلام في دين الله في حرام أو حلال أو واجب إلا ببصيرة وعلم قال الله قال رسوله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/5196/الشروط-الواجب-توافرها-في-المفتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05114.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":7839,"question":"أخونا يسأل ويقول: بماذا نحارب الجهل والأمية؟ وهل هما شيئان مختلفان، أم أن لكل واحد منهما حد معين، وما هو؟ جزاكم الله خيرا.","title":"وسائل محاربة الجهل والأمية والفرق بينهما","answer":"الجواب: الجهل والأمية يحاربان بالعلم بالتعلم والتفقه في الدين والتدبر للقرآن الكريم، وحضور مجالس العلم، وسؤال أهل العلم، بهذا يحارب الجهل وتحارب الأمية، كون المؤمن والمؤمنة يتدبران القرآن ويكثران من قراءة القرآن بالتدبر والتعقل والاستفادة، وكذلك بمراجعة أحاديث الرسول صلى الله عليه وسلم والعناية بما ذكره أهل العلم في تفسير القرآن، وفي بيان الأحاديث وما دلت عليه، وهكذا بحضور مجالس العلم وحلقات العلم، وهكذا بصحبة الأخيار من أهل العلم، وهكذا بسؤال أهل العلم كما قال الله سبحانه: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43]، وروي عنه عليه الصلاة والسلام أنه قال لما أفتى قوم بجهل، قال: ألا سألوا إذ لم يعلموا، إنما شفاء العي السؤال، بهذا تحارب الجهالة وتحارب الأمية.\nوالجهل أعم من الأمية، كل أمي قد يكون جاهلاً، ولكن ليس كل جاهل أمياً فالجهل أعم، فقد يكون متعلماً وليس بأمي ولكن يجهل مسائل كثيرة، تخفى عليه مسائل كثيرة، فدواء ذلك التعلم والتفقه في الدين حتى يزول الجهل، وقد يكون عالماً بالصلاة جاهلاً بالزكاة، وقد يكون عالماً بالصلاة والزكاة جاهلاً بأحكام الصيام، وقد يكون عالماً بالعقيدة والصلاة والزكاة والصيام لكنه جاهل بأحكام الحج، وقد يكون عالماً بالعبادات لكنه جاهل بأحكام المعاملات جاهل بأحكام الطلاق والنكاح إلى غير هذا.\nفالعلم يتبعض والجهل يتبعض، فدواء الجهل مطلقاً دواؤه التعلم والتفقه في الدين، ودواء الأمية كذلك التعلم والتفقه في الدين، نعم.\nالمقدم: إذاً وصف أمة الإسلام بأنها أمية يكون ماذا لو تكرمتم شيخ عبد العزيز؟\nالشيخ: هذا هو الأصل فيهم، الأصل في هذه الأمة أنها أمية.\nالمقدم: الأصل الأصل.\nالشيخ: أي عدم العلم، هذا هو الأصل ونبينا صلى الله عليه وسلم أمي؛ لأنه ما كان عنده علم قبل أن يوحى إليه عليه الصلاة والسلام، ما كان يقرأ ولا يكتب، كما قال الله عز وجل: وَمَا كُنْتَ تَتْلُوا مِنْ قَبْلِهِ مِنْ كِتَابٍ وَلا تَخُطُّهُ بِيَمِينِكَ إِذًا لارْتَابَ الْمُبْطِلُونَ [العنكبوت:48]، فما كان قارئاً، وما كان شاعراً، وما كان يخط، حتى علمه الله وأنزل عليه هذا الكتاب العظيم، فالأمي الذي نسب لأمه، يعني: بقي على الجهل ليس عنده علوم وليس عنده كتابة، فإذا تعلم العلم لم يكن أمياً، وإذا كان يكتب العلم وينقل المسائل العلمية ويحسن الكتابة لم يكن أميا، وإنما الأمي الذي لا يحسن القراءة ولا يحسن الكتابة حتى يستفيد من علمه الذي علمه أو مما يكتبه عن العلماء، فكان النبي ﷺ مثلما قال الله: وَوَجَدَكَ ضَالًّا فَهَدَى [الضحى:7]، جاهلاً بالعلوم التي جاء بها الوحي، لم يكن عنده علم بما شرع الله له في كتابه العظيم، ولم يكن عنده علم بعلوم الأولين المرسلين، ولم يكن يكتب ويخط حتى جاءه هذا الخير العظيم والوحي العظيم عليه الصلاة والسلام، فكل إنسان لم يتعلم ولم يكتب يقال له: أمي، والأمة العربية هكذا كان الغالب عليها أنها أمية لا تكتب ولا تقرأ، هذا الغالب على أمة محمد ﷺ، نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/5223/وساىل-محاربة-الجهل-والامية-والفرق-بينهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_052/05204.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":7883,"question":"أيضاً لديه سؤال آخر يقول: ما حكم الأمر بالمعروف والنهي عن المنكر على الخاصة والعامة، أي: هل يعذر بقية المسلمين إذا لم يأمروا بالمعروف وينهوا عن المنكر؛ لأنهم لا يأخذون على ذلك أجراً؟","title":"ما حكم الأمر بالمعروف والنهي عن المنكر على العامة؟","answer":"الجواب: هذه مسألة عظيمة يجب على أهل الإسلام أن يعنوا بها وأن يعظموها كما عظمها الله ألا وهي: الأمر بالمعروف والنهي عن المنكر، قد بين الله سبحانه وتعالى أن من صفات المؤمنين الأمر بالمعروف والنهي عن المنكر وهذا ليس خاصاً بالرجال دون النساء ولا بالنساء دون الرجال بل على الجميع، وليس خاصاً بأهل الحسبة الذين لهم مرتبات وهم عينوا في هذا الشيء، لا. بل يهم الجميع، لكنه على الحسبة وعلى الأعيان من الأمراء والعلماء والقادرين أشد وجوباً وأعظم مسئولية، ولكن الأمر عام للجميع للعلماء والعامة والصغير والكبير من المكلفين والأمراء والقضاة كل منهم عليه واجبه وعليه قسطه من هذا الأمر، قال الله سبحانه وتعالى في كتابه العظيم: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُوْلَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71]، فذكر سبحانه أن من صفات المؤمنين والمؤمنات الأمر بالمعروف والنهي عن المنكر.\nهذا واجب من الواجبات ومن أخلاق المؤمنين والمؤمنات، فيجب عليهم ألا يتساهلوا فيه، بل يجب عليهم أن يأمروا بالمعروف وينهوا عن المنكر كما ذكر الله هذا من صفاتهم وقال : كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ [آل عمران:110].\nوذم الله كفار بني إسرائيل ولعنهم على عصيانهم واعتدائهم وعدم التناهي عن المنكر، فقال جل وعلا: كَانُوا لا يَتَنَاهَوْنَ عَنْ مُنكَرٍ فَعَلُوهُ لَبِئْسَ مَا كَانُوا يَفْعَلُونَ [المائدة:79]، بعدما ذكر أنه لعن كفار بني إسرائيل على لسان داود وعيسى بن مريم ثم قال: ذَلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ [المائدة:78]، ثم فسر العصيان والاعتداء بقوله: كَانُوا لا يَتَنَاهَوْنَ عَنْ مُنكَرٍ فَعَلُوهُ لَبِئْسَ مَا كَانُوا يَفْعَلُونَ [المائدة:79]، فذمهم وعابهم ولعن كفارهم الذين فعلوا هذا المنكر وتساهلوا فيه.\nفوجب على المسلم أن يحذر صفات الكفرة، وألا يكون على أخلاقهم بل يكون بعيداً من أخلاق الكافرين ويكون أماراً بالمعروف نهاء عن المنكر حتى يسلم من العقوبة العامة والخاصة.\nوقال جل وعلا في آية أخرى: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَأُوْلَئِكَ هُمُ الْمُفْلِحُونَ [آل عمران:104]، والنبي عليه الصلاة والسلام قال: إن الناس إذا رأوا المنكر فلم يغيروه أوشك أن يعمهم الله بعقابه، هذا وعيد عظيم يدل على أن الناس إذا تساهلوا في الأمر بالمعروف والنهي عن المنكر عمهم العقاب، والعقاب قد يكون في القلوب بطمسها والختم عليها ومرضها والإعراض عن الحق، وقد يكون بعقوبات أخرى من تسليط أعداء، من خروج المياه، من أمراض عامة، من عقوبات متعددة متنوعة بسبب التساهل بهذا الواجب العظيم.\nوالخلاصة أن هذا أمر عظيم، الأمر بالمعروف والنهي عن المنكر أمر عظيم، واجب مقدس، فرض على المسلمين، إذا قام به من يكفي في البلد أو القرية سقط عن الباقين، أما إذا لم يقوم به من يكفي وجب على الباقين وأثموا بتركه، وإذا كنت في محل في قرية أو في بلد أو في مسجد أو في حارة فيها منكر ظاهر ولم ينكر وجب عليك إنكاره وألا تتساهل فيه؛ لأنه لم يوجد من ينكره ويقوم مقامك.\nفالواجب عليك أن تنكر المنكر أينما كنت حسب طاقتك كما قال النبي ﷺ: من رأى منكم منكراً فليغيره بيده فإن لم يستطع فبلسانه فإن لم يستطع فبقلبه وذلك أضعف الإيمان خرجه مسلم في الصحيح، هذا يدل على أنه مراتب، وأنه واجب عل كل مسلم، وأنه ينكره حسب طاقته بيده، ثم لسانه، ثم قلبه، والإنكار بالقلب يكون بالتغير والتمعر والكراهة ومفارقة المجلس الذي فيه المنكر إذا لم يستجيبوا لنهيه وإنكاره هكذا يكون المؤمن، وقد قال عليه الصلاة والسلام: إن الناس إذا رأوا المنكر فلم يغيروه أوشك أن يعمهم الله بعقابه، وقال: لتأمرن بالمعروف ولتنهون عن المنكر أو ليوشكن الله أن يعمكم بعقاب من عنده، وقال أيضاً عليه الصلاة والسلام: يقول الله جل وعلا: يا أيها الناس! مروا بالمعروف وانهوا عن المنكر قبل أن تدعوني فلا أستجيب لكم وقبل أن تسألوني فلا أعطيكم وقبل أن تستنصروني فلا أنصركم، هذا يدل على الخطورة العظيمة.\nونحن في عصر تساهل فيه أكثر الناس، وضعفت فيه الغيرة وفشي فيه المنكر وقل الإنكار، فواجب على المسلم ألا يتخلق بهذا الخلق وألا يغتر بالناس، وهكذا المسلمة في بيتها ومع أولادها ومع جيرانها يجب أن تكون غيورة لله عز وجل، تنكر المنكر على بنتها وأختها وخادمتها ومن حولها ومن ترى في الأسواق وفي غير الأسواق، تنكر المنكر بيدها أو لسانها حسب طاقتها، على أولادها تنكر المنكر بيدها تزيل المنكر، على أهل بيتها من خدم وغيرهم، وفي غير ذلك تنكر بلسانها حسب الطاقة، كالرجل سواء، كل منهما عليه واجبه من الإنكار باليد ثم اللسان ثم القلب، وبهذا تصلح الأمور، وتصلح المجتمعات، ويظهر فيها الخير وتسود فيها الفضائل وتقل فيها الرذائل، لكن إذا تساهل الناس ورأوا المنكرات ولم يغيروها انتشرت الرذائل وقلت الفضائل، وضعف جانب الأمر والنهي؛ بسبب التساهل وخشي من العقوبات العامة والخاصة على الجميع، ولا حول ولا قوة إلا بالله.\nالمقدم: شكراً! أثابكم الله.","link":"https://binbaz.org.sa/fatwas/5352/ما-حكم-الامر-بالمعروف-والنهي-عن-المنكر-على-العامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_058/05803.mp3","categories":["الدعوة والدعاة"]},{"id":8023,"question":"أيضاً تقول: إن الله عز وجل أمرنا بصلة الرحم، ولكن أقاربي غير متدينين ولا يصلون وغير متحجبين، كذلك أمي وأخواتي وإخواني ووالدتي، وإنني والحمد لله مسلمة ومتحجبة ولا أتصل بأي أجنبي ولا أخرج من البيت، وأعمل دائماً على حل مشاكل البيت وتبيين فوائد الإسلام والسنة النبوية لأهلي، ولكن دون فائدة، فهل.. تقول: فهل أحرجهم أو أبتعد عنهم، أفيدوني جزاكم الله خيراً؟","title":"نصيحة لمن تعيش في بيئة غير ملتزمة","answer":"الجواب: أيها الأخت في الله! أنت مشكورة على هذا العمل الطيب، وعلى هذه المناصحة وعلى التزام حكم الإسلام في الحجاب وغيره فجزاك الله خيراً وبارك فيك وثبتنا وإياك على الحق، فنوصيك بتقوى الله والصبر والمصابرة على دين الله، ونوصيك أيضاً بالعناية بالقرآن والإكثار من تلاوته وتدبر معانيه، والعناية بالسنة المطهرة وتدبر معانيها مثل بلوغ المرام للحافظ ابن حجر كتاب جيد، وعمدة الحديث للشيخ عبد الغني بن سرور المقدسي كتاب جيد في الحديث.. منتقى الأخبار للمجد ابن تيمية كتاب جيد.. رياض الصالحين للنووي رحمه الله كتاب جيد نوصيك بالمطالعة لهذه الكتب المفيدة، كذلك كتاب التوحيد للشيخ محمد بن عبد الوهاب وفتح المجيد لحفيده الشيخ عبد الرحمن بن حسن كتاب جيد، هذه الكتب وما أشبهها مفيدة ونافعة، وهكذا كتاب الإيمان لشيخ الإسلام ابن تيمية كتاب مفيد، اقتضاء الصراط المستقيم له أيضاً مفيد، والعقيدة الواسطية له أيضاً مفيدة، ونوصيك بالصبر على نصيحة الوالدة والأخوات والأقارب تنصحينهم بالكلام الطيب والأسلوب الحسن؛ لأن الله يقول جل وعلا: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] وهذا من ذلك، ولو جرى بعض الشيء من الأذى أو الاستهزاء لا يهمك، اصبري وصابري، وقد قال النبي ﷺ الدين النصيحة، قيل: لمن يا رسول الله؟ قال: لله، ولكتابه، ولرسوله، ولأئمة المسلمين وعامتهم وفي الصحيحين عن جرير بن عبد الله البجلي رضي الله عنه قال: بايعت النبي ﷺ على إقام الصلاة، وإيتاء الزكاة، والنصح لكل مسلم.\nفأنت -أيها الأخت في الله- اصبري وصابري، وللوالدة وللأقارب حق عليك وأعظم الحق: النصيحة، فانصحيهم دائماً بالأسلوب الحسن، وبالأوقات المناسبة من جهة العناية بالصلاة والمحافظة عليها.. من جهة الحجاب.. من جهة عدم الخلوة بالأجنبي إذا المرأة وحدها وما أشبه ذلك.. من جهة الوصية بتقوى الله في جميع الأمور.. من جهة تعلم القرآن الكريم والعناية به.. إلى غير ذلك، أنت على خير إن قبلوا منك فهذا هو المطلوب، وإن لم يقبلوا فقد أديت ما عليك ولا تيأسي أبداً، نسأل الله لنا ولك التوفيق والهداية، ونسأل الله لأقاربك التوفيق والهداية وصلاح الحال.","link":"https://binbaz.org.sa/fatwas/5623/نصيحة-لمن-تعيش-في-بيىة-غير-ملتزمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_078/07802.mp3","categories":["الدعوة والدعاة","قضايا المرأة"]},{"id":8047,"question":"هذه رسالة وردتنا من المرسلة سهيلة عبد المجيد تقول: إنني متزوجة ولي أربعة أطفال وإنني سعيدة مع زوجي كثيراً، ولكن زوجي من النوع الذي يأخذ المشروب في بعض الأيام، ولا أقدر أمنعه عن هذا، ومع هذا أخلاقه جيدة مع الناس، ولكني أنا أخاف الله، ولا أريد زوجي أن يفعل ما حرم الله، وأنتم يا فضيلة الشيخ أرجو أن ترشدونا إلى الخير، وأفيدونا أفادكم الله وجزيتم عنا خيراً؟","title":"واجب المرأة تجاه زوجها المتعاطي للخمر","answer":"الجواب: الذي يتعاطى الشراب من الأزواج يجب أن ينصح ويخوف من الله ، ويبين له سوء عاقبة ما فعل، فإن الخمر من أعظم الكبائر، وقد ثبت عن رسول الله ﷺ: أنه لعن الخمر، وشاربها، وساقيها، وحاملها والمحمولة إليه، وعاصرها ومعتصرها، وبايعها ومشتريها، وآكل ثمنها، فهي خبيثة تسلب العقول، وتسبب فساداً كبيراً في المجتمع وفي الأسر، وقد ثبت عنه عليه السلام أيضاً أنه قال: إن على الله عهداً لمن مات وهو يشرب الخمر أن يسقيه من طينة الخبال قيل: يا رسول الله! وما طينة الخبال؟ قال: عصارة أهل النار، أو قال: عرق أهل النار.\nفأنت أيها الأخت في الله! انصحيه وتكلمي معه كثيراً في هذا الأمر، وكذلك لو اتصلت بمن له أهمية عنده وتقدير، ينصحه كأبيه وعمه أو نحو ذلك، إذا كانوا يعلمون حاله ينصحونه كثيراً لعل الله يهديه، أما النكاح فلا يبطل بذلك، النكاح صحيح وأنت زوجته وإن كان عاصياً، لكن لك الفسخ، إذا أصر على هذا المنكر، فلك الفسخ، لك الاتصال بالمحكمة، والمحكمة تفسخ النكاح؛ لأن هذا عيب، وخطره كبير على الزوجة وعلى الأسرة، فللزوجة إذا أصر زوجها على شرب مسكر، لها أن تطالب بالفسخ فسخ النكاح، والمحكمة تفسخها تفسخ نكاحها إذا ثبت لديها ذلك نسأل الله الهداية للجميع. نعم.","link":"https://binbaz.org.sa/fatwas/5840/واجب-المراة-تجاه-زوجها-المتعاطي-للخمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_081/08106.mp3","categories":["الدعوة والدعاة"]},{"id":8109,"question":"بارك الله فيكم. سماحة الشيخ! أخونا يتيح لنا فرصة السؤال عن هذه الأشياء التي لم يعد لها وجود تقريباً -سماحة الشيخ- كالرق مثلاً، وكالسفر على الدواب كالجمال والحمير والخيل وهكذا، ثم عن مثل الإقط وزكاة الفطر، هذه الأشياء تكاد ينعدم التعامل بها سماحة الشيخ، وفقهنا لا زال يذكر هذه الأشياء، ماذا يقول سماحة الشيخ عن مثل هذه الأشياء؟","title":"هل من حاجة إلى الكلام في الرق وركوب الخيل والحمير؟","answer":"","link":"https://binbaz.org.sa/fatwas/5905/هل-من-حاجة-الى-الكلام-في-الرق-وركوب-الخيل-والحمير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_102/10204.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8141,"question":"يقول أيضاً: ما رأيكم في كتاب: \"في فصول الدين والأدب\" من تأليف إبراهيم السليمان؟الشيخ: أيش؟ إبراهيم السليمان الطامي كتاب: في فصول الدين والأدب؟","title":"تقييم كتاب: في فصول الدين والأدب","answer":"الجواب: لم أطلع عليه ولا أعلم عنه شيئاً.","link":"https://binbaz.org.sa/fatwas/5945/تقييم-كتاب-في-فصول-الدين-والادب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_089/08903.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8170,"question":"يقول بعض الناس: إن قراءة الكتب وحدها لا تنفع ولابد أن تقرأ على شيخ فهل هذا صحيح أم لا؟","title":"حكم أخذ العلم من الكتب دون الرجوع إلى العلماء","answer":"الجواب: نعم إذا كان الشخص عامياً وليس عنده أدوات العلم ولم يتعلم ما يؤهله لمطالعة الكتب فإنه لا يستفيد الفائدة المطلوبة قد يستفيد إذا كان يفهم العربية قد يستفيد وإذا كان بلغته قد يستفيد إذا كان يفهم كما يستفيد من كلام الله إذا قرأ القرآن يستفيد باللغة التي يفهمها، لكن ما يستفيد الفائدة الكاملة العظيمة إلا إذا تعلم على أهل العلم المعروفين بالخير والعقيدة الصالحة والطريقة السلفية التي يتبعون فيها السلف الصالح وهم أصحاب النبي ﷺ وأتباعهم بإحسان، هذا العالم يبصرك ويرشدك إلى ما قد يخفى عليك من كتاب الله ومن سنة رسوله عليه الصلاة والسلام ويعينك على الفهم الصواب، أما وحدك فقد تغلط كثيراً ولا سيما إذا كنت لم تتعلم الأصول التي تهتدي بها إلى فهم النصوص ولم تجالس أهل العلم، أما الذي قد جالس العلماء وحضر حلقات العلم واستفاد فإنه يمكن أن يطالع ويستفيد، فنوصيك أن تجمع بين هذا وهذا، تطالع الكتب التي تفهمها تتدبر القرآن وتعتني بقراءة القرآن بالتدبر والتعقل وتسأل أهل العلم عما أشكل عليك، ولا تثق بنفسك بل عليك أن تسأل أهل العلم المعروفين بالاستقامة بالفضل والديانة والعبادة وصحة المعتقد هذا هو الذي ينبغي لك.\nالمقدم: بارك الله فيكم.\nالمقدم: حبذا سماحة الشيخ لو ذكرتم الأشياء التي تؤهله للاستفادة من القراءة دون أن يكون عنده أحد، أو دون أن يكون له شيخ كما يقول؟\nالشيخ: يراجع كتب التفسير، تفسير القرآن الكريم ويعرف أصول أهل العلم وأصول الفقه يطالعها ومصطلح الحديث حتى يستفيد، وبكل حال لا يستفيد الفائدة المطلوبة إلا بعالم يبصره، لابد، لأن هذه أصول وقواعد تحتاج إلى بعض الشرح بعض البيان، فكونه يستقل بنفسه من أول وهلة هذا لا يتم به المطلوب وإن كان حاذقاً وإن كان عربياً لكنه محتاج إلى أن يعرف المصطلحات بواسطة أهلها العارفين بها، لكن لا يمتنع من تدبر القرآن ولا يمتنع من حفظ الأحاديث وقراءة الكتب المفيدة فإنه لابد يستفيد بعض الفائدة، لكن لا يكتفي بهذا، ننصحه أن لا يكتفي بل يطلب العلم في حلقات العلم وفي مدارس العلم الموثوقة الطيبة، ومن طريق زيارة العلماء في بيوتهم ومساجدهم للسؤال والتبصر هكذا يكون طالب العلم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/5968/حكم-اخذ-العلم-من-الكتب-دون-الرجوع-الى-العلماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10407.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8171,"question":"ما حكم من يتعلم لكي يأخذ الشهادة أو يصير عالماً إلى غير ذلك؟","title":"وجوب تصحيح النية في طلب العلم","answer":"الجواب: إذا كان يتعلم للدنيا ليتوظف أو ليقال: إنه عالم فهذا خاسر، ما يستفيد من العلم الفائدة التي تنفعه في الآخرة، أما إذا تعلم ليستفيد ويعرف حكم الله ويعرف ما شرع الله له وليتوظف أيضاً وينتفع في أمور دنياه فلا بأس، فإن العلم يجره إلى هذا وهذا، ولكن قد يتعلم ليتوظف أو ليقال له: عالم ثم يهديه الله ويرجع إلى الصواب، مثل ما قال بعض السلف: (تعلمنا العلم لغير الله فأبى أن يكون إلا لله).\nفينبغي له أن يتعلم ولو ساءت نيته لا يترك العلم يتعلم ويجتهد ويحضر مع العلماء ويسأل ربه أن يحسن نيته، يضرع إلى الله أن الله يعينه على إصلاح النية وأن يقصد بعلمه وجه الله ، والله سبحانه وتعالى جواد كريم إذا صدق في الدعاء يجيب الله دعوته ويحسن حاله فتكون النية بعد ذلك صالحة لا ييئس ولا يترك العلم. نعم.","link":"https://binbaz.org.sa/fatwas/5970/وجوب-تصحيح-النية-في-طلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10408.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8184,"question":"تقول أنا معلمة وقد قمت بواجبي في التعليم ابتغاء رضا الله فلم أقصر فيه أو أتهاون عن بعض ولكن قد تعتريني بعض المشكلات، فمثلاً: الطالبة تكون غير مجتهدة أو لم تؤد واجبها فأنا بطبيعة الحال أقوم بضربها حتى لا تكرر هذا الإهمال فما حكم ضرب الطالبات لتأديبهن؟ وما صحة قول رسول الله ﷺ: العصا لمن عصى، نسبت هذا إلى الرسول صلى الله عليه وسلم! أرجو أن تفيدوها سماحة الشيخ؟","title":"حكم ضرب المعلم للطالب على إهماله","answer":"الجواب: لا شك أن الواجب على المعلمة تحري أسباب نجاح الطالب والطالبة، فإذا كانت الطالبة تقصر وتتساهل في أداء واجبها فعليك أن تنصحيها وتوجيهها وإذا لم ينفع النصح ولم تتأثر بالكلام فلا مانع من تأديبها التأديب الذي يعينها على أداء الواجب من دون خطر تأديب ليس فيه خطر لا جرح ولا كسر ولكنه تأديب يحصل به المقصود من تشجيعها على العمل وتنشيطها على العمل وأنت مأجورة في ذلك كما يؤدب الإنسان ولده على الصلاة قال النبي ﷺ مروا أبناءكم بالصلاة لسبع واضربوهم عليها لعشر.\nفالضرب للتأديب وكما يؤدب الرجل زوجته للقيام بحقه أو بحق الله سبحانه لا بأس بهذا فهذا من هذا الباب تأديب الطالب وتأديب الطالبة عند وجود التقصير منهما أو التساهل أمر مطلوب وهو في مصلحتهما لكن مع مراعاة عدم الخطر في ذلك، وأما قولك في الحديث: «العصا لمن عصى» فهذا فليس بحديث وليس بوارد عن النبي ﷺ وإنما هذا من كلام العامة.\nالمقدم: بارك الله فيكم. سماحة الشيخ عن تربية المعلم للتلاميذ يدور حديث وحديث في الصحافة وفي وسائل الإعلام وكانت نتيجة ذلك الحديث أن ذهبت هيبة المعلم وأصبح في مكان خوف من قبل بعض الطلبة الذين لم يؤدبوا كما يجب لعل لسماحة الشيخ رأي في هذا وفق لشرع الله؟\nالشيخ: وما هو الحديث؟\nالمقدم: الحديث أن تلك الصحافة أو وسائل الإعلام تلك لا ترى أن يقوم المعلم بضرب الطالب إطلاقاً.\nالشيخ: يعني يخوضون في هذا.\nالسائل: يخوضون في هذا حتى أن الطلبة قرأوا هذا فأصبح المعلم بدون شخصية أمام تلاميذه.\nالشيخ: لا، هذا خطأ من الصحافة هذا خطأ من الخائضين بل ينبغي لمن يتكلم في هذا الشأن أن ينصح الطلبة والطالبات وأن يقول لهم عليهم أن يتقوا الله وعليهم أن يؤدوا الواجب وعليهم أن يعينوا الأستاذ ويعينوا المدرسة على ما ينفعهما على ما ينفع الطلبة على هذا ..... ينبغي، وعلى المعلم وعلى المدرسة أن يقوم بالواجب من التأديب عند تمرد الطالب أو الطالبة وعند عدم اكتراث الطالب والطالبة بما يوجهه إليه الأستاذ أو المدرسة هذا هو الواجب على من يتكلم في الصحافة أن يكون مع هؤلاء ومع هؤلاء.\nينصحوا الطلبة والطالبات ويأمروا الجميع بتقوى الله والعناية بالطلب والحرص على أداء الواجب وأن يقوم بما وكل إليه وأن يعد ما ينبغي أن يعده وأن يحرص ويبذل بوسعه وعلى المعلم وعلى المعلمة أن ينظرا في ذلك فإذا ظهر لهما من الطالب أو من الطالبة أنهما مقصران وأنهما لم يبذلا الواجب فإنهما يؤدبان أما لو كان الأمر بخلاف ذلك يعني كان الطالب مغفل ما فيه حيله أو المطلوب يعجز عنه مثله لصغر سنه وعدم تحمل هذا الشيء فينبغي لهم أن يقدروا ذلك وأن ينصحوا الجهات المختصة بأن تخفف هذا المقرر وتعوض عنه مقرراً آخر أو تحذف ما يشق على الطالب ولا يتحمله الطالب لأن الطالب له قدرة محدودة فلابد من كون المعلم أو المعلمة ينظران في هذا الأمر فلا يحملان الطالب ما لا يحتمل ولا يحملا الطالبة ما لا تحتمل ولكن يكونان مع الطالبة في الأمر الموافق ومع الطالب في الأمر الموافق ويقومان عليه في الأمر الذي يريان أنه مقصر فيه هذا هو الواجب لا هذا ولا هذا، لا الغلو في الأمر حتى يؤدب كل أحد ولا التقصير حتى لا يؤدب كل أحد ولكن من استحق التأديب يؤدب.\nومن كان لا يقوى وليس مثله يقوى فهو يعني يعامل بطرق أخرى من النصيحة أو العناية بالجهات المختصة حتى تخفف وتزيل العقبة التي لا يتحملها هذا الطالب أو هذه الطالبة المقصود المعلم طبيب والمعلمة طبيبة لابد أن ينظرا في الأمر فيؤدبا حيث يكون التأديب في محله ويتوقفا عن التأديب حيث لا يكون في محله. نعم.","link":"https://binbaz.org.sa/fatwas/5991/حكم-ضرب-المعلم-للطالب-على-اهماله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_106/10607.mp3","categories":["العالم والمتعلم","تربية الأولاد","الدعوة والدعاة"]},{"id":8223,"question":"أختنا تقول: إنها تقتني بعض الكتب، وذكرت منها: الإسراء والمعراج، ورياض الصالحين، ورجال حول الرسول ﷺ، وترغب أن تتفضلوا بدلالتها على كتب أخرى تفيدها في شئون دينها لو تكرمتم سماحة الشيخ؟","title":"كتب ينصح باقتنائها","answer":"الجواب: أما رياض الصالحين فهو كتاب نفيس وطيب، ونوصي بأن يقتنيه كل أحد لما فيه من الفائدة العظيمة، أما الإسراء والمعراج فهو كتاب ليس بشيء ولا ينبغي اقتناؤه ولا يعتمد عليه، وأما ما يتعلق برجال حول الرسول ﷺ فلم أقرأه ولا أستطيع أن أحكم عليه، ولكن نوصي أختنا المرأة السائلة نوصيها بكتب أخرى.. كتاب الصحيحين، صحيح البخاري ومسلم يكونان عندها؛ لأنهما كتابان عظيمان وهما أصح الكتب بعد كتاب الله، ونوصيها بتفسير ابن كثير ؛ فإنه كتاب عظيم مفيد، ونوصيها بزاد المعاد لـابن القيم في هدي خير العباد كتاب عظيم ومفيد، ونوصيها بفتح المجيد للشيخ عبد الرحمن بن حسن حفيد الشيخ محمد بن عبد الوهاب ، مع كتاب التوحيد مع العقيدة الواسطية وشرحها للهراس أو غيره، كل هذه كتب مفيدة. نعم.\nالمقدم: طيب. بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6035/كتب-ينصح-باقتناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_096/09608.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8264,"question":"سماحة الشيخ! ودعوتم أيضاً إلى الاستفادة من وسائل الإعلام بما فيها تلك الوسائل التي فيها التصوير، لكن بعض الدعاة إلى الله لا زالوا يتحرجون من تلكم الصورة، ماذا يقول سماحة الشيخ؟","title":"استغلال وسائل الإعلام في الدعوة إلى الله","answer":"الجواب: نعم، هذا لا شك أن فيهم من يتحرج من ذلك وهو التصوير لأجل الإذاعة في التلفاز ومن نشر العلم في التلفاز، وهذا يختلف بحسب ما أعطى الله للناس من العلم والإدراك والبصيرة والنظر في العواقب، فمن شرح الله صدره واتسع ...... علمه ليعمل في التلفاز ويبلغ رسالات الله فله أجره وله ثوابه عند الله، ومن اشتبه عليه الأمر ولم ينشرح صدره لذلك فنرجو أن يكون معذوراً.\nأما أنا فأعتقد أن من شرح الله صدره لذلك وأعانه الله على ذلك فإن هذه المصلحة العظمى وهي نشر الدين وتوجيه الناس إلى الخير يغتفر في جنبها ما يقع من تصويره لهذا الأمر، كونه يصور من أجل هذا الأمر فإنها مفسدة جزئية تنغمر في جنب المصلحة العظمى التي هي تبليغ الناس رسالات الله، وتعليم الناس شرع الله وتوجيه الناس إلى الخير حتى لا يخلو المجال لأهل الباطل وحتى لا يتسع لأهل الباطل أفق دعواتهم إلى باطلهم، ونسأل الله السلامة والتوفيق. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6078/استغلال-وساىل-الاعلام-في-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_099/09902.mp3","categories":["الدعوة والدعاة"]},{"id":8304,"question":"سؤاله الثاني يقول: إن والدتي عندما تقرأ آيات من كتاب الله غيباً؛ لأنها لا تعرف القراءة ولا الكتابة إنما حفظت بعض الآيات من القرآن الكريم في صغرها، وعندما تقرأ الآن تخطئ في كثير من المرات، فمثلاً: في آية الكرسي تقول: وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ فتزيد الواو، وفي قوله تعالى: وَلاَ يَؤُودُهُ حِفْظُهُمَا فتزيد فيها واو، فنعلمها ولكن بدون جدوى، هل تمتنع من القراءة أم ماذا نفعل؟","title":"هل تمتنع من القراءة من لا تحسن الحفظ؟","answer":"الجواب: لا تمتنع، لكن علموها علموها واجتهدوا واصبروا، كونوا صابرين معلمين مرشدين معينين لها على الخير، فهي مجتهدة وطالبة للخير، وقد قال النبي ﷺ في الحديث الصحيح: الماهر في القرآن مع السفرة الكرام البررة، والذي يقرأ القرآن وهو عليه شاق ويتتعتع فيه وهو عليه شاق له أجران فالمتتعتع قد يغير حرفاً، وقد يبدل حرفاً، يريد الخير، فعليك أن تعلمها وأن تحسن إليها، وأن تصبر وتكرر عليها الألفاظ بأسلوب حسن برفق وتواضع حتى تقتنع وحتى يذل لسانها لهذا الأمر، وحتى تدع زيادة الواو، هذه الزيادة سهلة سقوطها سهل، لكن عليك أن تصبر لا تعنف ولا تشدد، فعليك بالحلم والصبر وعند ذلك يزول الخطأ إن شاء الله. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6123/هل-تمتنع-من-القراءة-من-لا-تحسن-الحفظ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_201/201006.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8333,"question":"لدي كتاب يسمى (ضياء الصالحين) فيه جميع الصلوات والتسابيح والأدعية.. إلى آخره لجميع الأيام والشهور، ولكل يوم توجد صلاة اليوم والليلة وأنا أصليها جميعها دون استثناء، فهل ما جاء في هذا الكتاب صحيح؟ وهل صلاتي صحيحة، أفيدونا أفادكم الله؟","title":"تقييم كتاب: ضياء الصالحين","answer":"الجواب: لا أعرف هذا الكتاب، ولا أدري عما فيه، والذي فيه يعرض على ما جاءت به الشريعة، يعرض على أحاديث النبي ﷺ فإن وافق ما جاء في الأحاديث من صفة الصلوات فلا بأس، فإن كثيراً من الناس قد يجمع أحاديث لا تصح عن النبي صلى الله عليه وسلم، إما موضوعة وإما ضعيفة.\nفإذا رأيت إرساله نظرنا فيه، والآن أقول لك: إن هذا الكتاب وأشباهه يعرض على الكتب الصحيحة كـالبخاري ومسلم صحيح البخاري وصحيح مسلم ، والكتب الأخرى الصحيحة كـأبي داود والنسائي والترمذي وابن ماجة يعني ما صح فيها، وهكذا رياض الصالحين فيه الأحاديث الصحيحة والضعيف فيه قليل، فهذا الكتاب الذي لديك تعرض الأحاديث التي فيه على الأحاديث الصحيحة، وما أشكل عليك تبينينه لأهل العلم حتى يجيبوك عنه، الحديث الفلاني والحديث الفلاني حتى يستطيع أهل العلم أن يجيبوك على سؤالك. نعم.","link":"https://binbaz.org.sa/fatwas/6146/تقييم-كتاب-ضياء-الصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_111/11104.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8340,"question":"سماحة الشيخ! لعله من تحصيل الحاصل أن أنبه إلى السنة الحسنة التي اتبعتها الرئاسة العامة لإدارات البحوث العلمية والإفتاء والدعوة والإرشاد في المملكة وهي: إعلان التلفونات حتى يتصل الناس بمن يريدون استفتاءه عن أمر من الأمور.","title":"حكم استحباب الإعلان عن هواتف العلماء والإدارات العلمية للاستفتاء","answer":"الشيخ: صحيح هذا طيب.\nالمقدم: لعل استحسان هذا في الرئاسة أيضاً يجعله معمولاً به في جهات أخرى؟\nالشيخ: إعلام التلفون طيب، لأن الناس يحتاجون إلى هذا في أوقات لا يتيسر لهم سماع مثل برنامج نور على الدرب، أو ما تيسر لهم إرسال السؤال أو ما أشبه ذلك.\nفالحاصل أنه يعرض للناس حاجات يحتاجون فيها إلى تلفونات العلماء حتى يسألوهم وهذا طيب.\nالمقدم: بارك الله فيكم، إذاً هذا تدعون إلى أن يكون سنة في كل بلدان المسلمين؟\nالشيخ: نعم، ونحن نعلن بهذا أيضاً؛ لأنه ينبغي أن تعلنوه للناس ونعلن الآن تلفون المنزل: (4534444).\nالمقدم: طيب.\nالشيخ: نعم.\nالمقدم: بارك الله فيكم، هذا بالنسبة لبيت سماحة الشيخ عبد العزيز بن باز في الرياض؟\nالشيخ: نعم.\nالمقدم: جزاكم الله خيراً.\nالشيخ: ويوجد تلفون آخر: (4351421) هذا التلفون الآخر: (4351421).\nالمقدم: حزاكم الله خيراً.\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/6157/حكم-استحباب-الاعلان-عن-هواتف-العلماء-والادارات-العلمية-للاستفتاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_112/11203.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8406,"question":"منعاً للأحاديث الدنيوية في المساجد، هل يصح أن نستمع إلى برنامج نور على الدرب بدلاً من أحاديث بعض المصلين الفارغة؟","title":"حكم استماع برنامج نور على الدرب في المسجد","answer":"الجواب: الاستماع لهذا البرنامج فيه خير عظيم، وفيه مصالح جمة، وقد يسر الله للمسلمين هذا البرنامج يستفيدون منه حلقة علمية عظيمة، يستفيد منها الرجال والنساء وهم في بيوتهم، وفي مجالسهم، وعلى أسرتهم، فهي من نعم الله العظيمة، وهي حجة قائمة على الناس، هذا البرنامج حجة قائمة وصل إليهم في بيوتهم، وفي سياراتهم، وفي طائراتهم، وفي كل مكان، فالواجب على المسلمين أن يستفيدوا من هذا البرنامج، وأن يحمدوا الله ويشكروه على ما يسره لهم سبحانه وتعالى، وكان الناس يسعون للعلم من أماكن بعيدة إلى المساجد، وإلى العلماء في بيوتهم يطلبون العلم، وربما سافر الرجل من بلاد بعيدة إلى العالم يطلب منه فائدة، وسافر جابر بن عبد الله إلى الشام في حديث واحد، وسافر غيره إلى مصر في حديث واحد، وهم أصحاب النبي عليه الصلاة والسلام، فأنت يا عبد الله! وأنت يا أمة الله! يسر الله لكما هذا البرنامج من الأثير وأنتم في بيوتكم، أنتم في فرشكم، أنتم في مساجدكم، في أي مكان، هذه نعمة من الله عظيمة، فأنا أوصي وأنصح كل مسلم وكل مسلمة أن يستفيد من هذا البرنامج، وأن يسأل عما أشكل عليه، من طريق هذا البرنامج، وهذه نعمة من الله عظيمة يسرها للمسلمين، فأسأل الله أن يوفق القائمين على هذا البرنامج لإصابة الحق، وأن يعينهم على إبلاغ رسالة الله وأمره ونهيه للأمة في كل مكان، وأن يوفق المسلمين في كل مكان إلى أن يستمعوا هذا البرنامج ويستفيدوا منه، وإذا أشكل على أحد من ذلك شيء وتوقف في شيء فليعد السؤال، ويسأل أهل العلم في أي مكان حتى يطمئن، رزق الله الجميع التوفيق والهداية. نعم.\nالمقدم: سؤال أخينا لو تكرمتم سماحة الشيخ بالنسبة للاستماع إلى البرنامج في المساجد؟\nالشيخ: لا بأس الفتح، بالراديو في المسجد لسماع هذا البرنامج، أو لسماع العلم غير هذا البرنامج لا بأس به، فإذا جاءت الموسيقى أو جاء شيء لا يرضى يقفل، يقفل عما لا يرضى، ويفتح عن أهل العلم والقرآن ونحو ذلك.\nالمقدم: طيب، طيب.","link":"https://binbaz.org.sa/fatwas/6290/حكم-استماع-برنامج-نور-على-الدرب-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11712.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8478,"question":"أختنا أيضاً تقول: إني أخاف كثيراً من الرياء وأحذره إلى درجة أنني أحياناً لا أستطيع أن أنصح بعض الناس أو أنهاهم عن أمور معينة، مثل الغيبة أو عدم لبس الحجاب الساتر تماماً فأخشى أن يكون ذلك رياءً مني، وأخشى أيضاً أن يظنوا هم ذلك فلا أنصحهم بشيء، كذلك أقول في نفسي: إنهم أناس متعلمون ولا يحتاجون إلى تعليم وليسوا في حاجة إلى نصح، وترجو التوجيه سماحة الشيخ؟","title":"نصيحة لمن ترك الدعوة خوفاً من الرياء","answer":"الجواب: هذا من مكائد الشيطان فإن الشيطان له مكائد يخذل بها الناس عن الدعوة إلى الله، وعن الأمر بالمعروف والنهي عن المنكر، ومن ذلك: أن يوهمهم أن هذا من الرياء، أو أن هذا يخشى أن يعده الناس رياء فلا ينبغي لك أيها الأخت في الله أن تلتفتي إلى هذا، بل الواجب أن تنصحي لإخوانك وأخواتك إذا رأيت من أحد منهم تقصيراً في الواجب أو ارتكاباً للمحرم كالغيبة والنميمة، وعدم التستر عند الرجال الأجانب من جهة المرأة ونحو ذلك، ولا تخافي من الرياء، أخلصي لله واصدقي مع الله وأبشري بالخير واتركي خدع الشيطان ووساوسه والله يعلم ما في قلبك من القصد والإخلاص لله سبحانه وتعالى والنصح لعباده.\nولا شك أن الرياء شرك ولا يجوز، لكن لا يجوز للمؤمن ولا للمؤمنة أن يدع ما أوجب الله عليه من الدعوة والأمر بالمعروف والنهي عن المنكر خوفاً من الرياء، بل عليه أن يحذر الرياء وعليه أن يقوم بالواجب من الدعوة إلى الله ومن الأمر بالمعروف والنهي عن المنكر في أوساط الرجال وأوساط الإناث، كل في حاجة الرجل في حاجة والمرأة في حاجة، كما أن الرجل يأمر بالمعروف وينهى عن المنكر فهكذا المرأة تأمر بالمعروف وتنهى عن المنكر، وقد بين الله ذلك في كتابه العظيم حيث قال سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُوْلَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71] فهذا فيه الحث للجميع وأن من واجبات الإيمان الأمر بالمعروف والنهي عن المنكر في حق الجميع الرجال والنساء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6515/نصيحة-لمن-ترك-الدعوة-خوفا-من-الرياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_125/12505.mp3","categories":["الدعوة والدعاة"]},{"id":8490,"question":"تسأل سماحة الشيخ عن الطالبات في الصف الأول والثاني والثالث وتقول: إنهن لا يؤدين الصلاة كما ينبغي؟","title":"ضرورة التوجيه والإرشاد عند تعليم الطلاب","answer":"الجواب: لا بد من التعليم لا بد من التوجيه للطالبات والطلبة جميعاً، .. على المعلم وعلى المعلمة التوجيه والإرشاد ليس المقصود التعليم فقط، مع التعليم أمر آخر، وهو التوجيه والإرشاد والتربية الصالحة فالمعلم يعلم الأولاد الصلاة ويعلمهم الأخلاق الفاضلة، ويحذرهم من الأخلاق الذميمة كالكذب والرياء والغيبة والنميمة والسب والشتم ونحو ذلك، فهكذا المعلمة تعلم الطالبات الأخلاق الفاضلة، وتحثهن على الصلاة وتحثهن على الأمانة وعلى حفظ اللسان عما لا ينبغي، هكذا ينبغي للمعلمة وهكذا ينبغي للمعلم، أن يكون تعليم معه إرشاد ومعه توجيه قولي وعملي. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6549/ضرورة-التوجيه-والارشاد-عند-تعليم-الطلاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_126/12604.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8565,"question":"يسأل ثانياً فيقول: عندما أقرأ القرآن أخطئ ولا أجيد القراءة في بعض الكلمات الصعبة، فما الحكم في ذلك؟","title":"حكم من يقرأ القرآن ويخطئ في بعض الكلمات","answer":"الجواب: يتعلم، عليك -أيها السائل- أن تتعلم وتجتهد، تقرأ على من هو أعلم منك، وتتهجى الكلمات، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: الماهر بالقرآن مع السفرة الكرام البررة، والذي يقرأ القرآن وهو عليه شاق ويتتعتع فيه له أجران، يعني: لا يجيده جداً، بل يتتعتع، له أجران هذا فضل من الله عز وجل، إذا اجتهدت في تعلم القرآن وحرصت على ذلك، فأنت لك أجران، ولكن من الحرص ومن أسباب الإجادة للقرآن أن تقرأه على من هو أعلم منك، وأن تجتهد في ذلك، وأن تذاكر فيه مع زملائك الطيبين حتى تقوى قراءتك، وحتى تمهر فيه.\nوبكل حال فأنت مأجور، لكن ينبغي لك أن لا تبقى على الجهالة، بل ينبغي لك أن تتعلم من إخوانك الطيبين، من بعض القراء الجيدين، تدرس عليهم وتقرأ عليهم حتى تستفيد وحتى تزول العلة التي بك، وعدم إتقان القراءة. نعم.","link":"https://binbaz.org.sa/fatwas/6651/حكم-من-يقرا-القران-ويخطى-في-بعض-الكلمات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_207/20713.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8569,"question":"يسأل ثانياً فيقول: عندما أقرأ القرآن أخطئ ولا أجيد القراءة في بعض الكلمات الصعبة، فما الحكم في ذلك؟","title":"حكم من يقرأ القرآن ويخطئ في بعض الكلمات","answer":"الجواب: يتعلم، عليك -أيها السائل- أن تتعلم وتجتهد، تقرأ على من هو أعلم منك، وتتهجى الكلمات، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: الماهر بالقرآن مع السفرة الكرام البررة، والذي يقرأ القرآن وهو عليه شاق ويتتعتع فيه له أجران، يعني: لا يجيده جداً، بل يتتعتع، له أجران هذا فضل من الله عز وجل، إذا اجتهدت في تعلم القرآن وحرصت على ذلك، فأنت لك أجران، ولكن من الحرص ومن أسباب الإجادة للقرآن أن تقرأه على من هو أعلم منك، وأن تجتهد في ذلك، وأن تذاكر فيه مع زملائك الطيبين حتى تقوى قراءتك، وحتى تمهر فيه.\nوبكل حال فأنت مأجور، لكن ينبغي لك أن لا تبقى على الجهالة، بل ينبغي لك أن تتعلم من إخوانك الطيبين، من بعض القراء الجيدين، تدرس عليهم وتقرأ عليهم حتى تستفيد وحتى تزول العلة التي بك، وعدم إتقان القراءة. نعم.","link":"https://binbaz.org.sa/fatwas/6651/حكم-من-يقرا-القران-ويخطى-في-بعض-الكلمات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_207/20713.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8591,"question":"سماحة الشيخ! إذا ابتلي الإنسان بمثل من ذكر في الرسائل والدة لا تصلي، أو أخت، أو حتى أنساب أو إخوة، كيف يتصرف؟","title":"ما الواجب تجاه من يترك الصلاة من الأقارب؟","answer":"الجواب: الواجب نصيحتهم وتخويفهم من الله عز وجل تحذيرهم من مغبة أعمالهم الخبيثة، فإن تابوا فالحمد لله وإلا وجب هجرهم، لا يزارون ولا تجاب دعوتهم، ولا يدعون إلى وليمة ولا غيرها بل يهجرون حتى يتوبوا إلى الله، هكذا ذكر أهل العلم، يجب هجرهم؛ لأنهم أتوا منكراً عظيماً حتى يوفق الله ولاة الأمور لإقامة الحد عليهم باستتابتهم، فإن تابوا وإلا وجب على ولي الأمر قتلهم، وهذا لا إشكال فيه وهو الذي عليه جمهور أهل العلم، أن من لم يتب يقتل، إذا ترك الصلاة واستتيب ولم يتب فإنه يقتل لقوله سبحانه: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5] فدل على أن الذي لا يصلي لا يخلى سبيله؛ ولقوله ﷺ: إني نهيت عن قتل المصلين فدل على أن من لا يصلي لا يترك بل يقتل إذا لم يتب، في أدلة كثيرة دلت على هذا المعنى. نعم.\nأما الوالدة فلها شأن، الوالدة والوالد لهما شأن، يجتهد في نصيحتهما ولكن لا يهجرهما، الوالدان لهما حق عظيم ولو كانا كافرين؛ لأن الله قال جل وعلا في حق الوالدين الكافرين: وَإِنْ جَاهَدَاكَ عَلى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُمَاثم قال بعدها: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] فأمر بمصاحبتهما في الدنيا معروفاً مع أنهما كافران، وما ذاك إلا لعظم حق الوالدين، فالولد إذا كان أبوه لا يصلي أو أتى بكفر آخر أو أمه كذلك فإنه ينصحهما كثيراً ولا يقطعهما بل يحسن إليهما، ويجتهد في دعوتهما إلى الخير والإسلام والاستقامة لعل الله يهديهما بأسبابه، وبكل حال يتلطف معهما، ويحسن إليهما ويدعوهما إلى الخير، حتى يموتا أو يهديهما الله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6697/ما-الواجب-تجاه-من-يترك-الصلاة-من-الاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_128/12802.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":8629,"question":"هذه رسالة وردتنا من السائل: نفيع نافع الصحفي من وادي غران، يقول: أسأل عن تنوير المقباس من تفسير ابن عباس، ما صحة نسبته إليه ؟","title":"ما صحة نسبة كتاب: تنوير المقباس لابن عباس؟","answer":"الجواب: لم أقرؤه ولم يحصل لي دراسة له، فلا أحكم عليه بشيء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6768/ما-صحة-نسبة-كتاب-تنوير-المقباس-لابن-عباس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_211/21109.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8701,"question":"هنا رسالة وصلت إلى البرنامج من إحدى الأخوات تقول: (ع.ع) من جمهورية مصر العربية وتقيم في وادي الدواسر، أختنا تقول: إنها كانت تعمل ممرضة في وحدة مدرسية أنكرت منكراً رأته في عملها فكان سبباً لطردها من العمل، وكان سبباً لتعاستها ولمتاعب نفسية وأصبحت أيضاً تنهى أولادها عن أن ينكروا أي منكر، وترجو التوجيه؟","title":"الحث على الصبر في الأمر بالمعروف والنهي عن المنكر","answer":"الجواب: لا شك أن هذا غلط كبير بل الواجب عليها إنكار المنكر ولا يضرها كونها طردت أو استغني عنها فقد أرضت ربها جل وعلا وفعلت ما ينبغي لها والأمور بيد الله سبحانه وتعالى، ولهذا يقول ﷺ: من رأى منكم منكراً فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه وذلك أضعف الإيمان والله يقول في كتابه العظيم سبحانه وتعالى: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] ويقول جل وعلا: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنََ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللَّهِ [آل عمران:110].\nفإذا فعلت ذلك طاعة لله والتماساً لمرضاته فإن العاقبة تكون حميدة، ولا يضرها ما فعله، سوف يغنيها الله عن ذلك وسوف يكسبها ما يغنيها عما طردت عنه وما أقيلت منه، فالله هو الرزاق جل وعلا وبيده الخير كله سبحانه وتعالى وهو القائل : وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3] وهو القائل سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4].\nفعلى المؤمن وعلى المؤمنة تقوى الله جل وعلا، وعلى المدرسة والطبيبة تقوى الله، وعلى كل مؤمن تقوى الله في إنكار المنكر والدعوة إلى الخير بالحكمة والكلام الطيب، وليس لها أن تنهى أولادها عن إنكار المنكر بل توصيهم بإنكار المنكر والأمر بالمعروف ولكن بالحكمة، بالكلام الطيب والأسلوب الحسن لا بالشدة والعنف والغلظة، ولا بالفعل بل بالقول؛ لأنه لا يستطيع الفعل إلا أولوا الأمر ومن فوض له هذا الأمر، أو الإنسان في بيته مع أهله قد يستطيع ذلك بالفعل، أما مع الناس يكفي أن ينكر باللسان ويقول: يا أخي اتق الله هذا لا يجوز هذا منكر، إذا كان يعرف ذلك، إذا كان عنده علم، أما إذا كان ما عنده علم فليس له الإنكار، إنما ينكر من عنده علم أن هذا منكر وأن هذا نهى الله عنه سبحانه وتعالى، نعم. الله المستعان.","link":"https://binbaz.org.sa/fatwas/6848/الحث-على-الصبر-في-الامر-بالمعروف-والنهي-عن-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_131/13108.mp3","categories":["الدعوة والدعاة"]},{"id":8747,"question":"له سؤال ثالث وأخير يقول فيه: يسمي بعض الناس عندنا العلماء في المملكة العربية السعودية بالوهابية، فهل ترضون بهذه التسمية؟ وما هو الرد على من يسميكم بهذا الاسم؟","title":"التعريف بدعوة الشيخ محمد بن عبد الوهاب رحمه الله","answer":"الجواب: نعم هذا لقب مشهور هذا اللقب مشهور لعلماء التوحيد لعلماء نجد، ينسبونهم إلى الشيخ الإمام محمد بن عبد الوهاب رحمة الله عليه؛ لأنه دعا إلى الله  في النصف الثاني من القرن الثاني عشر واجتهد في إيضاح التوحيد وبيان الشرك للناس، حتى هدى الله به الجم الغفير، ودخل الناس في توحيد الله وتركوا ما هم عليه من أنواع الشرك الأكبر، من عبادة أهل القبور ومن البناء على القبور وعبادة الأشجار والأحجار والغلو في الصالحين، فصارت دعوته دعوة تجديدية إسلامية عظيمة نفع الله بها المسلمين في الجزيرة العربية وفي غيرها، رحمه الله رحمة واسعة، وصار أتباعه ومن دعا بدعوته ونشأ على هذه الدعوة في نجد يسمى بالوهابي، وكان هذا اللقب علماً على أهل التوحيد، كل من دعا إلى توحيد الله ونهى عن الشرك وعن التعلق بالقبور أو التعلق بالأشجار والأحجار وأمر بالإخلاص لله سموه وهابياً، فهو لقب شريف عظيم يدل على أن من لقب به من أهل التوحيد ومن أهل الإخلاص لله، وممن ينهى عن الشرك بالله وعن عبادة القبور والأشجار والأحجار والأصنام والأوثان. هذا هو أصل هذه التسمية وهذا اللقب.\nهو نسبة إلى الشيخ الإمام محمد بن عبد الوهاب بن سليمان بن علي التميمي الحنبلي الداعي إلى الله  رحمه الله رحمة واسعة، فقد نشأ في نجد وتعلم في نجد ثم سافر إلى مكة والمدينة وأخذ عن علمائها من أهل السنة ثم رجع إلى نجد فرأى ما الناس فيه من الجهل وعبادة القبور والغلو فيها والشرك بالله  ودعاء الأموات والاستغاثة بهم والبناء على قبورهم، فدعا إلى الله وأرشد الناس ونهاهم عن الشرك، وبين لهم أن التوحيد هو حق الله جل وعلا على عباده وأنه الذي دعت إليه الرسل عليهم الصلاة والسلام، وبين لهم معنى، لا إله إلا الله وأن معناها: لا معبود حق إلا الله، فهي نفي وإثبات تنفي الإلهية عن غير الله وتثبت العبادة لله وحده سبحانه وتعالى، كما قال : ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ [الحج:62].\nقال سبحانه: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] قال : وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَسُولٍ إِلَّا نُوحِي إِلَيْهِ أَنَّهُ لا إِلَهَ إِلَّا أَنَا فَاعْبُدُونِ [الأنبياء:25] قال سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] قال : فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ [غافر:14] قال سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5]\nفالشيخ رحمه الله محمد بن عبد الوهاب قام بهذه الدعوة في النصف الثاني من القرن الثاني عشر وكان ذلك في العيينة وهي بلدة قريبة من الرياض دعا إلى الله فيها ونشر التوحيد وصارت عنده حلقة عظيمة في التعليم، ثم انتقل لأسباب معروفة إلى الدرعية وتلقاه أميرها محمد بن سعود وبايعه على الدعوة إلى الله عز وجل وعلى نشر الإسلام في الدرعية وما حولها، فنفع الله بذلك وتعاون الشخصان الشيخ محمد بن عبد الوهاب والشيخ محمد بن سعود جد العائلة المالكة الآن، فتعاونا في سبيل الدعوة وكان ذلك في عام ثمان وخمسين ومائة وألف في عام ألف ومائة وثمان وخمسين، هذا بدء الدعوة في الدرعية بعد أن انتقل من العيينة فانتشر الإسلام هناك وأزيلت القباب التي على القبور وانتشر التوحيد بين الناس وعرفوا حقيقة معنى: لا إله إلا الله، ثم قامت دولة آل سعود في بقية الجزيرة وانتشر أمر التوحيد في أطراف الجزيرة، فنفع الله بهذه الدعوة نفعاً عظيماً وظهر بها الحق وانتصر بها أهل التوحيد وصارت علماً لأهل التوحيد في كل مكان، ثم انتشر هذه الدعوة أيضاً في اليمن وفي جهات كثيرة من الهند وغير الهند والشام والعراق ومصر، وتلقاها أئمة الهدى وعلماء الحق بالقبول، وساعدوا الشيخ محمد رحمه الله ودعوا بدعوته وخالفه آخرون ممن غلب عليهم الجهل أو غلب عليهم التقليد لآبائهم وأسلافهم أو غلب عليهم الهوى والتعصب لما هم عليه، لئلا يقول الناس: ليش ما علمتونا ليش ما نبهتمونا؟ فعادوا هذه الدعوة وكتبوا كتابات باطلة، ولكن نصر الله الدعوة وأهلها واستقام أمر التوحيد في الجزيرة وانتشر أمر الله بحمد الله، فصار أتباع هذه الدعوة ومن يدعو إلى توحيد الله من علماء التوحيد من علماء نجد يلقب بالوهابي، فهو لقب معروف شريف وليس بالمستنكر بل هو لقب لأهل التوحيد والإيمان، لأهل الدعوة إلى الله عز وجل وهكذا انتشر هذا اللقب.\nإذا رأوا من يدعو إلى الله ويبين حقيقة التوحيد وينهى عن الشرك في أفريقيا أو في الشام أو في اليمن أو في جهات أخرى، إذا رآه بعض الغلاة وبعض المنحرفين، قالوا: هذا وهابي حتى ينفروا الناس عن دعوته وحتى يظن الناس أن هذه الدعوة دعوة باطلة أو دعوة مخالفة لشرع وهو غلط قبيح ومنكر بل هي حقيقة ما دعا إليه الرسول ﷺ، فإن الرسول ﷺ دعا إلى توحيد الله، وهكذا الرسل جميعاً كلهم دعوا إلى توحيد الله ونشروا دين الله عليهم الصلاة والسلام، كما قال تعالى: وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولًا أَنِ اُعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ [النحل:36].\nفهذه دعوة الرسل عليهم الصلاة والسلام جميعاً وهي دعوة نبينا وإمامنا وسيدنا محمد بن عبد الله عليه الصلاة والسلام، هو دعا إلى توحيد الله وقام في مكة بالدعوة، وصار المشركون يسمون من أجاب دعوته صابي كما يقال للموحد الآن وهابي.\nفمن أجاب دعوة محمد ﷺ في مكة قال له: صابي، وهكذا بعد ما هاجر لكن الله نصر الدعوة وأيد نبيه محمد ﷺ، وانتشرت الدعوة في مكة وفيما حولها ثم هاجر عليه الصلاة والسلام إلى المدينة وانتصرت الدعوة وقام سوق الجهاد وصارت المدينة معقل الإسلام ومدينة الإسلام والعاصمة الأولى للإسلام والحمد لله.\nوالمقصود من هذا كله أن هذه الدعوة وهذا اللقب لقب لمن دعا إلى توحيد الله، من دعا إلى توحيد الله وأنكر الشرك يسميه بعض الجهلة وهابي لجهلهم بالحقيقة وعدم علمهم بالحقيقة، والحقيقة هي ما ذكرنا أنها دعوة عظيمة إلى توحيد الله وإلى اتباع رسول الله ﷺ وعدم التقليد الأعمى والتعصب الأعمى وعدم البدع والخرافات وعدم الشرك والتعلق بالأموات والأشجار والأحجار أو بالأنبياء والصالحين أو بالأصنام فهذه الدعوة تحارب هذا الشرك، وتدعو إلى توحيد الله والإخلاص له والإيمان بمعنى: لا إله إلا الله وتحقيقها، وتحقيق اتباع الرسول ﷺ والتمسك بسنته وطريقه والاستقامة على ذلك.\nهذه هي دعوة الشيخ محمد رحمه الله. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6899/التعريف-بدعوة-الشيخ-محمد-بن-عبد-الوهاب-رحمه-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_216/21604.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8748,"question":"هذه رسالة من المرسل: (م. ق. ل) من جيزان يقول: هناك رجل طالب علم يصلي ويصوم ويتصدق، لكن مع الأسف قد هجر أمه فهل صلاته وصومه وصدقته تنفعه، وهو هاجر لأمه لا يلتفت إليها وهي مؤمنة تصلي وتصوم ونحن نعرفها بذلك؟","title":"نصيحة لطالب علم عاق لوالدته","answer":"الجواب: على كل حال هجره لأمه منكر وعقوق عظيم يجب عليه التوبة إلى الله من ذلك، وعليه أن يرجع إلى برها والإحسان إليها والأخذ بخاطرها واستسماحها، هذا الواجب عليه، وليس له أن يبقى على الهجر وعلى العقوق بل هذا منكر عظيم وكبيرة عظيمة، يجب عليه تركها واستسماح والدته وطلب رضاها والتوبة إلى الله من ذلك ﷺ.\nأما صلاته وصومه وعباداته فلا تبطل بل عباداته صحيحة وأعماله صحيحة، إذا أداها على الوجه الشرعي ولكن يكون إيمانه ضعيفاً، يكون إيمانه ناقصاً بهذه المعصية، فإن المعاصي عند أهل السنة تنقص الإيمان وتضعف الإيمان ولكن لا تكفر صاحبها، إنما يكفر عند الخوارج ، الذين يكفرون بالذنوب وهم ظلمة فجرة في هذا قد أخطئوا وغلطوا عند أهل السنة والجماعة .\nوأما أهل السنة فيقولون: لا، المعصية تنقص الإيمان ولكن لا يكون صاحبها كافراً ولا مخلداً في النار، بل هو عاصي ومعصيته تنقص إيمانه تضعف إيمانه، تسبب غضب الله عليه وعلى خطر منها من دخول النار، ولكن لا يكون كافراً حتى ولو دخل النار لا يخلد فيها، هكذا أهل التوحيد -عند أهل السنة والجماعة - لا يخلدون في النار إذا دخلوها بمعاصيهم.\nفالحاصل أن هجر أمه معصية وكبيرة وعقوق، ولكن لا يكون ذلك من أسباب كفره ولا بطلان عمله، إلا إذا استحل ذلك، ورأى أن عقوق الوالدين حلال هذا يكون كافر -نعوذ بالله- من استحل عقوق الوالدين وأنه حلال أو استحل الربا ورأى أنه حلال أو استحل الزنا ورأى أنه حلال، هذا يكون كافر مرتد عن الإسلام إلا أن يكون مثله يجهل كالبعيد عن الإسلام الذي نشأ في بلاد بعيدة عن الإسلام يعلم فإذا بين له أن هذا مما فرضه الله بر الوالدين مما فرضه الله، وأن عقوقهما مما حرم الله إذا علم وبين له ثم أصر يكون كافراً نعوذ بالله.\nالمقدم: هذا طالب علم يا شيخ!\nالشيخ: إذا كان طالب علم على كل حال تكون كبيرته أشد، نسأل الله العافية.\nالمقدم: جزاكم الله خير وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6902/نصيحة-لطالب-علم-عاق-لوالدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_216/21607.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8847,"question":"من حائل هذه هي الرسالة الثانية لأحد الإخوة من هناك يقول: (ع.ش.ح) أخونا مهتم ببعض الفتاوى التي تطبعها بعض المجلات، والواقع أخذ صورة من تلك المجلة وبعث بها، ويرجو أن تتفضلوا بمناقشة ما ورد من فتاوى في تلك المجلة، رأي سماحة الشيخ في هذا؟","title":"الفتاوى التي تطبعها بعض المجلات","answer":"الشيخ: لا مانع، نطلع عليها إن شاء الله ونجيبه.\nالمقدم: بارك الله فيكم، إذًا: لا داعي لعرضها في البرنامج هنا؟\nالشيخ: لا داعي. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7002/الفتاوى-التي-تطبعها-بعض-المجلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_165/16504_02.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8854,"question":"من جمهورية تشاد رسالة وصلت إلى البرنامج من الأخ فيزاني محمد من مدينة أبشا فيما يبدو، أخونا رسالته كلها ثناء وتقدير على هذا البرنامج، ويسأل عدة أسئلة عن البرنامج الذاتي من بينها أسئلة حول طباعة البرنامج، هل أخذتم بذلك أو لا؟","title":"مقترح بطباعة برنامج نور على الدرب","answer":"الجواب: سيطبع إن شاء الله، ستطبع الجوابات التي فيه من جميع المشايخ وسوف تنظم إن شاء الله وتوزع. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7009/مقترح-بطباعة-برنامج-نور-على-الدرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_166/16611.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":8900,"question":"من البصرة الأخت سميحة عمار تسأل مجموعة من الأسئلة من بينها سؤال عن أخت لها تقول: إنها في العقد الخامس من عمرها، ولها ابن لشدة حبها له تتغاضى كثيرًا عن مخالفاته لأمر دينه ولأمور تتعلق بالأخلاق، وتقول: إن ذلك شأن كثير من الوالدات وبعض الآباء وترجو التوجيه في هذا لو تكرمتم؟","title":"وجوب الأمر بالمعروف والنهي عن المنكر للقريب والبعيد","answer":"الجواب: الواجب على المسلم أن يتقي الله في نفسه وفي أهل بيته وفي جيرانه وفي كل المسلمين، وذلك بدعوتهم إلى الله وأمرهم بالمعروف ونهيهم عن المنكر وأن لا تأخذه في الله لومة لائم ، هذا هو الواجب على كل مسلم، فلا يدع الأمر بالمعروف والنهي عن المنكر من أجل قرابة قريب أو محبة شخص بل من حبه له ومن صلته له الحقيقية التي يؤجر عليها أن يأمره بالمعروف وينهاه عن المنكر، كما قال : وَإِذَا قُلْتُمْ فَاعْدِلُوا وَلَوْ كَانَ ذَا قُرْبَى [الأنعام:152] فالواجب على المؤمن أن يتقي الله ويؤدي الحق الذي عليه وإن كان مع القريب، يقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا كُونُوا قَوَّامِينَ بِالْقِسْطِ شُهَدَاءَ لِلَّهِ وَلَوْ عَلَى أَنفُسِكُمْ أَوِ الْوَالِدَيْنِ وَالأَقْرَبِينَ إِنْ يَكُنْ غَنِيًّا أَوْ فَقِيرًا فَاللَّهُ أَوْلَى بِهِمَا [النساء:135].\nفالواجب على المؤمن أن ينكر المنكر وأن يأمر بالمعروف مع الأقرباء وغيرهم، وأن ينصح قريبه وغير قريبه، وإذا كان قريبًا له فمن أهم المهمات أن ينصحه وأن يوجهه هذا أعظم من صلته بالمال فإذا كان يصله بالمال ويؤجر على صلة الرحم فكونه يصله بتوجيهه إلى الخير وتعليمه الخير وأمره بالمعروف ونهيه عن المنكر هذا أهم من صلة المال، وهذا ينفعه في الدنيا والآخرة، فليس لهذه المرأة ولا لغيرها أن تدع الأمر بالمعروف والنهي عن المنكر لحبها لولدها أو ابن أخيها أو ابن أختها أو غيرهم بل يجب أن تأمر بالمعروف وتنهى عن المنكر بالطرق التي تراها مفيدة ومجدية، وبالأساليب الحسنة حتى تنجح إن شاء الله في عملها.\nالمقدم: إذًا: من التربية الحسنة من الرأفة بالأبناء إنكار المنكر عليهم ..؟\nالشيخ: نعم.. نعم، لكن بالأساليب التي تراها مفيدة لا بالعنف والشدة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7056/وجوب-الامر-بالمعروف-والنهي-عن-المنكر-للقريب-والبعيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_168/16802.mp3","categories":["العالم والمتعلم","تربية الأولاد","الدعوة والدعاة"]},{"id":8935,"question":"حياكم الله، شيخ عبدالعزيز! أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من دولة الكويت الديوان الأميري وباعثها أخونا: فايز موسى أبو شيخة أخونا نص رسالته كما يلي: فضيلة الشيخ: عبد العزيز بن باز المحترم. السلام عليكم ورحمة الله وبركاته.بعد حمد الله الحمد الكثير، والصلاة والسلام على حبيبنا محمد صلى الله عليه وسلم أضع بين يديكم ما يلي:إنني أستمع إلى برنامجكم نور على الدرب من فترة ليست بالقليلة ثم وجدت نفسي متابعاً له بشكل منتظم، ثم وجدت ما فيه من علم نافع لا حدود له في شتى مجالات العلوم الشرعية التي لا يستغني عنها أحد، واتضح لي أن عدداً قليلاً جداً هو من يتابع هذا البرنامج في الإذاعة أو يجد الحماس للاستماع إلى الأشرطة لأسباب متعددة، بينما يمكنه إذا توفر ذلك في كتاب أن يعود إليه بسهولة وفي أي وقت وعلى أي موضوع.وعليه: فقد بادرت بكتابة الفتاوى بعد تسجيلها بدقة وأمانة وتكون لدي الآن مجموعة كبيرة من الفتاوى للعلماء الأفاضل في السعودية، وحرصاً مني على أن لا تبقى هذه الفتاوى على أوراق دفاتري فإني على استعداد لطبعها وتوزيعها بحيث تصل إلى كثيرين وبسعر رمزي، وإنني على ثقة بعون من الله من صحة ما كتبته ودقته؛ لأنها أمانة علمية في النقل وعلى استعداد لعرضه على فضيلتكم الآن وقبل الطبع النهائي، أو عرضها على أحد العلماء الموثوق بهم هنا في الكويت.المهم: أن هذه المعلومات القيمة والفتاوى الشرعية التي تحوي الفائدة العظيمة تتوزع إلى مناطق تنتشر فيها البدع والمحدثات البعيدة عن السنة فتعمل بها إلى ما يعيدها للحق إن شاء الله وبعونه.إن لنا أملًا كبيرًا في الله ثم بكم للموافقة على طبع هذه الفتاوى حتى يعم العلم وتتوسع المعرفة ويكون لكم إن شاء الله ولبقية العلماء الثواب الكبير ولنا ولمن يساهم بالنشر والتوزيع.كما أكرر عهدي بأن يكون ما يطبع هو ما قيل على ألسنة فضيلتكم موضوعاً متكاملاً وفتاوى دقيقة، إنني أخشى الله سبحانه وتعالى وأعلم عاقبة الأخطاء في هذا العمل؛ ولذلك سأكون حريصاً على تعدد المراجعة.أكرر دعائي لله  كما دعوته من قبل أن يتم هذا العمل وأن يمنحكم الصحة والعافية، ويوفقنا لمتابعة هذه الفتاوى والقدرة على إتمامها حتى نلقى الله تعالى بعلم ينتفع به، والله يجعل فيكم الخير الدائم والبركة. إن أملي بالله ثم بكم أن تتكرموا بالرد كتابة وفي البرنامج حتى يكون عملنا صحيحاً مع العلم بأنني لن أقدم على طباعة شيء إذا رفضتم ذلك ولم توافقوا عليه؟","title":"طلب الإذن بطبع فتاوى نور على الدرب","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإني أشكر السائل على همته العالية ورغبته في العلم، وأسأل الله لك يا أخي المزيد من كل خير وأن يمنحنا وإياك العلم النافع والعمل الصالح، ثم أخبرك أنه ليس عندي مانع من طبع ما يتعلق بي من الفتاوى التي تنشر من طريق هذا البرنامج؛ لأن في ذلك منفعة إن شاء الله للجميع، ولكني أقول: إنه لابد من إرسالها إلي حتى تراجع حذراً من شيء من الخطأ، فإذا رأيتم إرسالها إلي قبل الطبع فهذا هو الذي أرى وبعد ذلك نعيدها إليكم إن شاء الله في وقت قريب، حتى نطمئن إلى صحة الموجود وعدم الخطأ، مع العلم أيضاً بأني عازم على طبع جميع الفتاوى التي تصدر من طريق هذا البرنامج والفتاوى الأخرى التي قد صدرت وتصدر منا في جهات أخرى ومن طرق أخرى، كالفتاوى التي تصدر منا كتابياً في الصحف وغيرها أو للسائلين من طريق الكتابة، وهكذا ما يصدر منا من المؤلفات الصغيرة التي نكتبها في بعض المواضيع، كل هذا سوف يجمع وسوف ينشر إن شاء الله للمسلمين، والآن نحن ساعون في ذلك والمجلد الأول سوف يصدر قريباً ويوزع إن شاء الله، والمجلد الثاني في الطريق إن شاء الله، وهكذا بقية الفتاوى سوف تصدر إن شاء الله تباعاً مطبوعة توزع على المسلمين من طريق دار الإفتاء ومن طريق البيت جميعاً، ولكن لا مانع عندي من طبع أيضاً ما يصدر من هذا البرنامج بواسطة إخواننا في الله، لكن بعد العناية وبعد إرساله إلي لمراجعته، وفق الله الجميع. نعم.","link":"https://binbaz.org.sa/fatwas/7093/طلب-الاذن-بطبع-فتاوى-نور-على-الدرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_144/14401.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9024,"question":"يوجد عندي كتاب اسمه: نصيحة المسلمين بأحاديث سيد المرسلين، ما رأي سماحتكم في هذا الكتاب؟","title":"حكم كتاب: (نصيحة المسلمين بأحاديث سيد المرسلين)","answer":"","link":"https://binbaz.org.sa/fatwas/7182/حكم-كتاب-نصيحة-المسلمين-باحاديث-سيد-المرسلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14717.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9026,"question":"أختكم في الإسلام (أ) من بلاد غامد بالجرشي تسأل مجموعة من الأسئلة تقول في سؤال لها: ما حكم الفتاة إذا رأت بنات جنسها يرتدين الملابس التي تصف أجسادهن هل تنكر عليهن أم ماذا تتصرف؟","title":"وجوب الأمر بالمعروف والنهي عن المنكر على الرجل والمرأة","answer":"الجواب: نعم، عليها أن تنكر على من رأته يتعاطى المنكر، مثل غيرها من الرجال والنساء؛ لأن الله يقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]، فإذا رأت من زميلاتها أو غير زميلاتها ملابس شفافة تبين العورة وجب عليها الإنكار بالكلام الطيب والنصيحة الطيبة، أو رأت منهن تساهلاً في الحجاب أو رأت منهن تساهلاً في الصلاة، أو رأت منهن غير هذا من المنكرات فإنها تنكر عليهن وتدعوهن إلى الخير، هكذا يجب على المؤمن والمؤمنة جميعاً، والناس بخير ما داموا يأمرون بالمعروف وينهون عن المنكر، فإذا ضيعوا هذا الواجب عمتهم العقوبات ولا حول ولا قوة إلا بالله، ولهذا يقول ﷺ: إن الناس إذا رأوا المنكر فلم يغيروه أوشك أن يعمهم الله بعقابه، وهذا فرض على المؤمنين أن يأمروا بالمعروف وينهوا عن المنكر، وهكذا المؤمنات لقوله سبحانه وتعالى: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ [التوبة:71] الآية، فالواجب على جميع النساء سواء كن طالبات أو مدرسات أو غير ذلك، الواجب عليهن أن يتقين الله وأن يأمرن بالمعروف وينهين عن المنكر كالرجال سواء بسواء. نعم.","link":"https://binbaz.org.sa/fatwas/7184/وجوب-الامر-بالمعروف-والنهي-عن-المنكر-على-الرجل-والمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14719.mp3","categories":["الدعوة والدعاة"]},{"id":9027,"question":"عندي كتيب صغير اسمه: تعليم الصلاة من تأليف الشيخ: محمد محمود الصواف أخذت منه بعض الأدعية في السجود وبعد التشهد وكذلك بعد الصلاة، فهل هذا الكتيب من الكتب الموثوق بها؟ أفتونا جزاكم الله خيراً.","title":"تقييم كتاب (تعليم الصلاة) للصواف","answer":"الجواب: الكتاب هذا قرأت بعضه وجملة منه، وهو كتاب فيما اطلعت عليه منه كتاب جيد ومفيد، ودار الإفتاء توزعه؛ لأن مؤلفه معروف لدينا بالعلم والفضل والنصح، فهو كتاب إن شاء الله مفيد ولهذا وزعناه لما بلغنا عنه من الفائدة الكبيرة للرجال والنساء. نعم.","link":"https://binbaz.org.sa/fatwas/7185/تقييم-كتاب-تعليم-الصلاة-للصواف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14720.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9053,"question":"شيخ عبدالعزيز الناس بين متفائل ومتشائم تجاه ما وسموه بالصحوة الإسلامية، لعل لسماحتكم من كلمة في هذا المقام تجاه هذا الموضوع؟","title":"الطريق الصحيح للصحوة الإسلامية","answer":"الجواب: الواجب التفاؤل، الواجب التفاؤل وحسن الظن بالله هذا هو الواجب، يقول الله  فيما صح عن رسوله ﷺ، يقول سبحانه: أنا عند ظن عبدي بي، وأنا معه إذا دعاني وفي صحيح مسلم عن جابر  عن النبي عليه الصلاة والسلام أنه قال: لا يموتن أحد منكم إلا وهو يحسن ظنه بالله فالواجب حسن الظن بالله مع السعي الجاد ومع العمل في نصر دين الله وإقامة شرع الله وأن يحاسب كل واحد نفسه في أداء حق الله وترك معاصي الله والوقوف عند حدود الله، وأن يعين حكومته في كل خير، يكون أمينًا في وظيفته، يؤدي الأمانة، وينصح للأمة، ويحافظ على الحق، ويسارع إلى الصلاة ويؤديها في وقتها مع الجماعة، وهكذا جميع أمور الإسلام، كل واحد مسئول حتى يساعد الأمة في رجوعها إلى دين الله وإقامتها لشريعة الله، وحتى يعين دولته على ذلك.\nويجب أيضًا على كل أسرة وعلى كل جماعة أن تتعاون في هذا في ترك ما حرم الله وفي أداء ما أوجب الله وفي التبشير بذلك والتعاون على ذلك، هذا هو واجب المسلمين، والله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2]، ويقول سبحانه: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3]، هؤلاء هم الرابحون الذين آمنوا بالله ورسوله إيمانًا صادقًا فعبدوه وحده وأخلصوا له العبادة وحكموا شريعته وعملوا بما أوجب عليهم وتركوا ما حرم الله عليهم، وتواصوا بذلك وتناصحوا في ذلك، وتواصوا بالصبر على ذلك، هؤلاء هم الرابحون، هؤلاء هم السعداء في الدنيا والآخرة.\nوهذا هو الواجب على جميع المؤمنين وعلى جميع المؤمنات أن يتواصوا بالحق، وأن يتناصحوا وأن يتعاونوا على البر والتقوى وأن يصبروا على ذلك حتى الموت، كما قال الله سبحانه لنبيه عليه الصلاة والسلام: وَاعْبُدْ رَبَّكَ حَتَّى يَأْتِيَكَ الْيَقِينُ [الحجر:99]، ويقول سبحانه للمؤمنين جميعًا: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ ۝ وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلا تَفَرَّقُوا [آل عمران:102-103]، ويقول النبي ﷺ: إن الله يرضى لكم ثلاثًا: أن تعبدوه ولا تشركوا به شيئًا، وأن تعتصموا بحبل الله جميعًا ولا تفرقوا رواه مسلم في الصحيح، زاد في رواية أخرى: وأن تناصحوا من ولاه الله أمركم.\nفالمؤمنون واجب عليهم التناصح والتعاون، وهكذا النساء المؤمنات يجب عليهن التناصح والتعاون فيما بينهن ومع الرجال ومع أهليهن فالواجب مشترك، يقول الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُوْلَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71]، ويقول سبحانه: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللَّهِ [آل عمران:110].\nفالواجب على الجميع في كل مكان وفي كل زمان التعاون على الخير، والتواصي بالحق، والتواصي بالصبر رجالًا ونساءً، كبارًا وصغارًا، عربًا وعجمًا، هذا واجب على الجميع أن يتعاونوا على البر والتقوى أينما كانوا وأن يتواصوا بالحق كتابة ومشافهة وبكل طريق، رزق الله الجميع التوفيق والهداية، نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.\nإذًا هذا هو الطريق الصحيح الذي يراه الشيخ عبدالعزيز بن باز للصحوة الإسلامية؟\nالشيخ: هذا هو الطريق الصحيح، وهذا الذي ويراه المسلمون يراه أهل الحق وأهل العلم أن الواجب ......... ... واليقظة والإعانة لمن قام بها والشكر له على ذلك والتوجيه والدعم حتى يكثر الخير ويقل الشر.\nالمقدم: جزاكم الله خيرًا، واستجاب لدعوتكم.","link":"https://binbaz.org.sa/fatwas/7205/الطريق-الصحيح-للصحوة-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_178/17805.mp3","categories":["الدعوة والدعاة"]},{"id":9093,"question":"الأخت جوهرة عبدالرحمن أيضاً تقول: أرجو من سماحتكم أن تدلوني على الكتب المفيدة النافعة في الدين والدنيا، وأن تدلوني على المكتبة الموجود فيها هذه الكتب أو ترسلوا لي إذا تكرمتم شيئاً من هذه الكتب جزاكم الله خيراً؟","title":"الدلالة على الكتب النافعة","answer":"الجواب: الكتب النافعة كثيرة؛ ومنها بل أعظمها وأهمها: كتاب الله سبحانه، هو أهم الكتب وأعظمها، فيه الهدى والنور، وفيه الدعوة إلى كل خير، وفيه بيان مكارم الأخلاق ومحاسن الأعمال، وفيه بيان ما أوجب الله وبيان ما أعد الله لأهله من الخير، وبيان ما حرم الله وما أعد لأهله من العقوبة، فأعظم كتاب وأشرف كتاب وأنفع كتاب هو كتاب الله العظيم القرآن، ثم كتب السنة الصحيحة كـالبخاري ومسلم وما بعدهما من كتب السنن المعروفة كـأبي داود والترمذي والنسائي وابن ماجة وسنن الدارمي ، ومسند أحمد رحمه الله، وموطأ مالك ، هذه الكتب من أنفع الكتب، لكن بالنسبة إلى طلبة العلم الذين لم يتمكنوا من العلم وطالبات العلم في المتوسط والثانوي هؤلاء لهم كتب ينبغي أن يحفظوها أولاً حتى تكثر علومهم وحتى يتأهلوا للكتب العظيمة الكبيرة التي تحتاج إلى مزيد عناية وعلم بما قاله أهل العلم في شأنها، مثل كتاب التوحيد للشيخ الإمام محمد بن عبد الوهاب رحمه الله هذا كتاب عظيم في العقيدة، ومثل الثلاثة الأصول ينبغي أن يحفظ من الطلبة والطالبات طلبة المتوسطة والابتدائي كذلك حتى يكون عندهم أساس في العقيدة، كذلك العقيدة الواسطية لشيخ الإسلام ابن تيمية كتاب عظيم مختصر لكنه مهم في العقيدة، كتاب بلوغ المرام للحافظ ابن حجر في الحديث، كتاب عمدة الحديث للشيخ عبد الغني بن سرور المقدسي في الحديث مهم، الأربعون النووية وتكميلها لـابن رجب الجميع خمسون حديثاً كتاب جيد ومهم نافع، في الفقه عمدة الفقه للموفق ابن قدامة كتاب جيد في الفقه الشرعي في الفقه الإسلامي، وهو في الفقه الحنبلي لكنه يعين على معرفة الفقه الإسلامي بالأدلة الشرعية، دليل الطالب للشيخ مرعي بن يوسف الحنبلي ، مختصر المقنع المسمى: زاد المستقنع للحجاوي ، هذه الكتب في الفقه مختصرة، ومن الكتب النافعة المفيدة لطلبة العلم وللعامة جميعاً: رياض الصالحين للنووي رحمه الله، الوابل الصيب لـابن القيم رحمه الله، هذه كتب مفيدة، زاد المعاد في هدي خير العباد لـابن القيم رحمه الله، هذه الكتب وأشباهها فيها نفع كبير. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7253/الدلالة-على-الكتب-النافعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_150/15004.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9112,"question":"هل من السنة الوعظ في المقبرة لجمع المشيعين؟","title":"حكم وعظ المشيعين للجنازة في المقبرة","answer":"الجواب: إذا تيسير ذلك فهو حسن إذا تيسر وعظهم وتيسر من يصغي له ويستفيد فهو مستحب، بل ثبت عن النبي ﷺ أنه وعظ الناس في المقبرة لما أتوا إلى قبر ولما يلحد وجلس مع أصحابه ذكرهم عليه الصلاة والسلام وبين لهم حال العبد إذا وضع في قبره وسألوه عن القدر قالوا: وهل نعمل في أمر مضى أو في أمر مستأنف؟ فقال: في أمر مضى، فقالوا: يا رسول الله كيف العمل ونحن قد فرغ من أمرنا؟ فقال عليه الصلاة والسلام: اعملوا فكل ميسر لما خلق له، أما أهل السعادة فييسر لعمل أهل السعادة، وأما أهل الشقاوة فييسر لعمل أهل الشقاوة، ثم تلا قوله سبحانه: فَأَمَّا مَنْ أَعْطَى وَاتَّقَى ۝ وَصَدَّقَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْيُسْرَى ۝ وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى ۝ وَكَذَّبَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْعُسْرَى [الليل:5-10].\nالمقصود أنه ﷺ ذكرهم وتلا عليهم بعض الأحاديث عليه الصلاة والسلام، فإذا تيسر تذكير الحاضرين ووعظهم فلا بأس بذلك حسن إن شاء الله. نعم","link":"https://binbaz.org.sa/fatwas/7272/حكم-وعظ-المشيعين-للجنازة-في-المقبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_179/17906.mp3","categories":["الدعوة والدعاة","أحكام المقابر"]},{"id":9114,"question":"والدي حلف يمين على عدم إدخال الفيديو في البيت، ونظرًا لحالتي فقد أدخلت الفيديو دون علمه، ما الحكم، انصحوني جزاكم الله خيرًا؟","title":"حكم مخالفة الابن لأبيه في عدم إدخال الفيديو البيت","answer":"الجواب: أولًا: أنت عاصٍ في هذا الحال؛ لأن الواجب عليك طاعة والدك في المعروف، وهذا من المعروف والفيديو لا يأتي بخير لا يأتي إلا بالشر؛ لأن الغالب على الفيديو أن يكون فيه الصور الخليعة والأغاني والملاهي، فليس لك أن تدخله حتى ولو كان سليمًا عليك أن تطيع والدك، من باب سد الذريعة، فأنت عاصٍ بهذا وعليك التوبة إلى الله وإخراج الفيديو، والوالد ليس عليه كفارة؛ لأنه لم يعلم، لكن أنت العاصي وأنت الذي عليك التوبة إلى الله وإخراج الفيديو من البيت طاعة لأبيك وحذرًا من شر الفيديو؛ لأنه في الغالب لا يسلم من أن يكون فيه ما يغضب الله من الصور الخليعة والكلام المحرم والأغاني المنكرة ونحو ذلك، نسأل الله لنا ولك الهداية.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/7274/حكم-مخالفة-الابن-لابيه-في-عدم-ادخال-الفيديو-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_179/17908.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة","الدعوة والدعاة"]},{"id":9145,"question":"السؤال الثاني في رسالة الأخ هيثم سالم حيدرة من اليمن الديمقراطي عدن يقول فيه: يقوم بعض الشباب عندنا باتباع السنة مثل: جلسة الاستراحة في الصلاة وغيرها من الأفعال، ولكن كل ذلك يولد نزاعاً من قبل بعض الشيوخ في المسجد مع الشباب، فهل ترون أن نترك السنة ونكسب هؤلاء أفضل، أم العكس؟ أم ماذا أفيدونا أفادكم الله؟","title":"حكم ترك السنة النافلة لمصلحة الدعوة","answer":"الجواب: المحافظة على السنة أمر مطلوب، ولكن السنة سنتان: فريضة ونافلة، أما الفريضة فلا بد منها، وذلك أن تصلي كما صلى النبي ﷺ تطمئن في ركوعك وسجودك وتقرأ الفاتحة، هذا أمر لا بد منه وفريضة، أما النوافل مثل: سنة الاستراحة، مثل: وضع اليدين على الصدر.. وضع اليمنى على اليسرى على الصدر وما أشبه ذلك من السنن، هذه إن فعلها الإنسان لإحياء السنة هذا مطلوب وأفضل، وإن تركها تأليفاً لجماعته الذين لم يعرفوا هذه السنة ولم يطمئنوا إليها لجهلهم أو لتقليدهم حتى يكسبهم في أداء الفرائض وترك المحارم فهذا حسن؛ لأن تحصيل الفرائض مقدم، وترك المحارم أمر مقدم على النوافل، فالمؤمن الداعي إلى الله يعمل الأصلح، فيجتهد في توجيه الناس إلى ما أوجب الله عليهم وتحذيرهم مما حرم الله عليهم، ويحرص على ما يؤلف قلوبهم ويرغبهم في الخير، فإذا اطمأنوا وعرفوا أن عنده النصح واطمأنوا إلى تعليمه وتوجيهه في إمكانه بعد ذلك أن يرشدهم إلى السنن التي قد تخفى عليهم من جنس جلسة الاستراحة فإنها سنة على الأرجح، وبعض أهل العلم لا يراها سنة وإنما يراها في حق المريض والعاجز، ولكن الصواب أنها سنة وهي جلسة بعد الأولى من الرفع في الصلاة وبعد الثالثة في الرباعية، وبعد الأولى في كل صلاة جلسة خفيفة، ثم ينهض إلى الثانية وإلى الرابعة، فإذا فعلها فهي سنة كما ثبت ذلك من حديث مالك بن الحويرث وأبي حميد الساعدي ، وإن ترك ذلك تأليفاً لجماعته وقومه وما أشبهها من السنن التي ليست واجبة فلا حرج كما تقدم.\nوالخلاصة: أن الداعي إلى الله ينظر الأصلح، ويحرص على اكتساب قومه وجماعته وأهل بلده في أداء الفرائض وترك المحارم، وإن تركوا بعض السنن، فالأهم كل الأهم حفظهم للفرائض وعنايتهم بها وابتعادهم عن المحارم، أما تركهم بعض السنن فلا يضرهم ذلك، وفي إمكانهم بعد الطمأنينة إلى الداعي وبعد معرفتهم لنصحه واطمئنانهم إليه وثقتهم به، في إمكانهم بعد هذا أن يقبلوا منه ما خالف عادتهم. والله المستعان. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7302/حكم-ترك-السنة-النافلة-لمصلحة-الدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_230/23005.mp3","categories":["الدعوة والدعاة"]},{"id":9199,"question":"رسالة مطولة باعثها أحد الإخوة المستمعين من السودان يقول: إنه مقيم في ليبيا، أخونا يقول: إن له رغبة شديدة في التفقه في الدين، وأن يتعلم التفسير وتجويد القرآن الكريم، ويرجو من سماحة الشيخ التوجيه حيال هذه الأمور جزاكم الله خيرا.","title":"نصيحة لمن أراد التفقه في الدين","answer":"الشيخ: وهو في ليبيا؟\nالمقدم: نعم، هو مقيم في ليبيا وسوداني الأصل واسمه علي أحمد آدم.\nالشيخ: هذا عمل طيب ورغبة طيبة، ينبغي له أن يسارع إلى ذلك ويبادر بذلك وإذا وجد في ليبيا من علماء السلف الصالح المعروفين بالخير من يتفقه عليهم فالحمد لله، فإن لم يجد في ليبيا من يقوم بذلك شرع له أن ينتقل عنها إلى محل آخر يجد فيه علماء الشرع حتى يتفقه عليهم، وحتى يتعلم عليهم كتاب الله وتجويده.\nفالحاصل: إنه إن وجد في ليبيا من يحصل به المقصود فالحمد لله يبادر ويقرأ عليهم ويتعلم ويستفيد ويتفقه، فإن لم يجد انتقل إلى غير ليبيا حتى يجد من يتعلم عليهم علوم الشرع المطهر ويتعلم عليهم علوم القرآن وتجويد القرآن ويقول النبي ﷺ: من يرد الله به خيرًا يفقهه في الدين، ويقول ﷺ: من سلك طريقًا يلتمس فيه علمًا سهل الله له به طريقًا إلى الجنة، فطلب العلم من أهم الأمور، ومن أفضل العبادات وهو واجب على كل مسلم أن يتعلم ما لا يسعه جهله كل مسلم عليه أن يتعلم ما لا يسعه جهله فيما أوجب الله عليه وما حرم عليه. نعم.\nالمقدم: هل تنصحونه بكتب معينة سماحة الشيخ؟\nالشيخ: نعم، ننصحه أولًا بكتاب الله، ننصحه أن يتعلم كتاب الله ويتحفظه ويكثر من تلاوته وتدبر معانيه مع من تيسر من إخوانه الطيبين هناك، فإن كتاب الله هو أصل كل خير، هو ينبوع الهدى كما قال الله : إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، وقال سبحانه: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]، قال : كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29]، وقال سبحانه: أَفَلا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا [محمد:24]، وقال جل وعلا: وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ [الأنعام:155].\nفنوصي جميع المسلمين بالعناية بكتاب الله والإقبال عليه والإكثار من تلاوته والعناية بحفظه وتدبر معانيه والعمل بذلك، هذا هو المشروع للجميع وتعلمه وتعليمه فرض كفاية على المسلمين.\nثم يشرع للمؤمن أن يلتمس أهل العلم والبصيرة حتى يتفقه عليهم، وحتى يسألهم عما أشكل عليه من كتاب الله وسنة رسوله عليه الصلاة والسلام.\nثم ننصح بعد ذلك بكتب الحديث الصحيح، كالصحيحين فإنهما أعظم كتاب بعد كتاب الله عز وجل.\nثم السنن الأربع: سنن أبي داود و الترمذي و النسائي و ابن ماجه فإنها كتب عظيمة وهي كتب السنة وإن كان فيها بعض الأحاديث الضعيفة لكنها كتب عظيمة وغالب ما فيها أحاديث صحيحة وفي إمكان طالب العلم أن يعرف ما فيها من الضعيف بالطرق التي رسمها أهل هذا العلم، أو بسؤال أهل العلم العارفين بهذا، ومثل: رياض الصالحين كتاب جيد مفيد غالبه أحاديث صحيحة، ومثل منتقى الأخبار للمجد ابن تيمية كتاب جليل، ومثل: بلوغ المرام للحافظ ابن حجر كتاب جيد مفيد، ومثل: عمدة الحديث للشيخ عبدالغني المقدسي ، هذه كتب عظيمة في الحديث ينبغي للمؤمن أن يعتني بها حسب طاقته. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7359/نصيحة-لمن-اراد-التفقه-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_181/18108.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9211,"question":"صدرت فتوى من سماحة الشيخ عبدالعزيز بن عبدالله بن باز، أيضًا هذا السؤال من أخينا الطالب في الثانوية عمر ماجد محمد سعيد من الأردن، يقول أيضًا في سؤاله الثاني: صدرت فتوى من سماحة الشيخ عبدالعزيز بن عبدالله بن باز حفظه الله وبارك فيه، وكان معنى تلك الفتوى بأن من كان عنده شرائط ما يسمى بالفيديو وعليها مواد خليعة خبيثة وتاب إلى الله تعالى فإنه يسجل عليها الطيب الجيد وذلك يزيل ما بها من الخبث، والاستفسار هو: ما المقصود بالطيب، هل هو حلقات العلم والدروس الشرعية وتلاوة القرآن، فإن كان هذا هو المقصود، فهل يدخل ذلك في نطاق التصوير المحرم أم لا؟ فإن كان داخلًا في هذا النطاق فكيف يجوز استعماله؟ وإن لم يكن داخلًا فما الأدلة الشرعية على ذلك؟وأخيرًا: أرجو من سماحة الشيخ عبدالعزيز أن يتفضل بإيضاح عنوانه كاملًا لعلنا نسأله عن أمور أخرى.","title":"حكم تسجيل المحاضرات والدروس على أشرطة الفيديو","answer":"الجواب: المقصود: أن الأشرطة التي فيها شيء لا ينبغي.. قد سجل فيها شيء لا ينبغي لا حاجة إلى إتلافها، بل يسجل عليها الشيء الطيب حتى لا تتلف هذا المال بغير فائدة والنبي نهى عن إضاعة المال عليه الصلاة والسلام، فيسجل عليها ما ينفع الناس، الأشرطة التي تحتاج إلى تصوير الشريط الفيديو إذا دعت الحاجة إلى ذلك وسجل عليها من الندوات النافعة والمحاضرات النافعة ما ينفع الناس فلا حرج في ذلك من باب تقديم المصلحة العظيمة على ما في التصوير من المضرة والمنكر.\nفالمقصود من هذا كله: أن إيجاد فيديو ينفع الناس قد سجل فيه وقد جعل فيه من العلوم النافعة والمحاضرات المفيدة والندوات الصالحة خير من تركه وإتلافه بدون فائدة، هذا المقصود: أن يسجل عليه بدل الشيء الرديء ما ينفع الناس من محاضرات صالحة وندوات صالحة وأشباه ذلك مما ينفع الناس، هذا هو المقصود.\nوأما العنوان: فالعنوان معروف: الرياض .. الرئاسة العامة لإدارات البحوث العلمية والإفتاء والدعوة والإرشاد، هذا هو العنوان، الرئيس العام لإدارات البحوث العلمية والإفتاء والدعوة والإرشاد.. الرياض. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7371/حكم-تسجيل-المحاضرات-والدروس-على-اشرطة-الفيديو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_182/18203.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9256,"question":"هنا رسالة وصلت إلى البرنامج من أحد الإخوة يقول: (ص. ع .أ.) من السودان أخونا يقول: عندنا في السودان إذا مات شخص يجتمع الناس بعد الدفن، و هل يجوز للداعية أن يذهب إليهم ويدعوهم إلى الإسلام وينكر عليهم فعلهم هذا، وهذا الداعي يذهب بنية الدعوة إلى الله ويبين الحق من الباطل وهو لا يجالسهم ولا يأكل عندهم بل إنما قصده يبلغ دعوة الله لكونهم مجتمعين ثم ينصرف ولا يجالسهم، أسأل هذا لأن بعض الإخوة لا يرون الذهاب بقصد الدعوة؛ لأنهم في منكر أرجو التوضيح بالتفصيل جزاكم الله خيراً؟","title":"حكم حضور الدعاة في التجمعات المخالفة للشرع لدعوتهم","answer":"الجواب: ذهاب الدعاة إلى المجتمعات المخالفة للشرع للدعوة والتوجيه أمر مطلوب؛ لأنها فرصة ينبغي أن تستغل، وكان النبي ﷺ يمر على مجامع الكفرة في منى فيدعوهم إلى الله ويطلب منهم أن يؤووه حتى يبلغ رسالات الله، وذهب مرة إلى سعد بن عبادة يعوده في المدينة وهو مريض فمر على مجتمع فيه اليهود وفيه بعض الكفرة من الوثنيين وفيه بعض المسلمين فوقف عندهم ودعاهم إلى الله  ورغبهم في الخير، فالدعاة إذا زاروا بعض المجتمعات المنحرفة كالذين يجتمعون بعد موت الميت يقيمون مأتماً عند أهل الميت يعلمهم يقول: هذا ما يجوز، أهل الميت لا يقيمون للناس مأتماً ولا طعاماً، ولا يجمعون الناس، ولكن إذا بعث إليهم جيرانهم طعاماً أو أقاربهم طعاماً فلا بأس بهذا، كما فعله النبي ﷺ لما جاء نعي ابن عمه جعفر بن أبي طالب يوم مؤتة أمر أهله أن يبعثوا لأهل جعفر طعام وقال: إنه أتاهم ما يشغلهم، هذا لا بأس به بل هو مشروع، أما كون أهل الميت يقيمون مأتماً يقيمون طعاماً للناس يجمعونهم، هذا لا يجوز هذا من عمل الجاهلية.\nكذلك الاجتماعات على المولد، مثل الاحتفال بالمولد في أي مكان فيأتيهم الدعاة ويقولون: هذا الاحتفال لا يجوز، وليس في الشريعة موالد يحتفل بها، ولم يشرع هذا النبي ﷺ لا في مولده ولا في مولد غيره، ولم يفعله الخلفاء الراشدون مع نبيهم عليه الصلاة والسلام ولا بقية الصحابة ولا التابعون ولا أتباعهم بإحسان حتى ينتبه الناس لهذه البدع ويحذروها، فهذا كله لا بأس به، إنما المنكر أن يحضر معهم للمشاركة فقط، أما إذا حضر لا للمشاركة بل للدعوة والتوجيه والإرشاد ثم ينصرف فهذا مأجور غير مأزور، والله المستعان. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7418/حكم-حضور-الدعاة-في-التجمعات-المخالفة-للشرع-لدعوتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_153/15305.mp3","categories":["الدعوة والدعاة"]},{"id":9306,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الكويت خيطان الجديدة، باعثها أحد الإخوة من هناك يقول: (ر. ع. س) أخونا يشكو من أخ له ويقول: إنه يقترف بعض المعاصي وقد نصحه كثيراً إلا أن الأمر آل به إلى المجاهرة، ويرجو من سماحة الشيخ التوجيه في هذا الموضوع لو تكرمت؟","title":"موقف الناصح من العاصي الرافض للنصيحة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفإن الواجب على المسلمين فيما بينهم هو التناصح والتعاون على البر والتقوى، والتواصي بالحق كما قال الله  في كتابه المبين: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ شَدِيدُ الْعِقَابِ [المائدة:2]، وقال سبحانه: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3]، وقال النبي الكريم عليه الصلاة والسلام: الدين النصيحة، قيل: لمن يا رسول الله؟ قال: لله ولكتابه ولرسوله ولأئمة المسلمين وعامتهم، خرجه الإمام مسلم في صحيحه.\nهاتان الآيتان مع الحديث الشريف كلها تدل على وجوب التناصح والتعاون على الخير والتواصي بالحق.\nفإذا رأى المسلم من أخيه تكاسلاً عما أوجب الله، أو ارتكاباً لما حرم الله وجب نصحه، وجب أمره بالمعروف ونهيه عن المنكر حتى يصلح المجتمع وحتى يظهر الخير وحتى يختفي الشر، كما قال الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]، وقال النبي الكريم عليه الصلاة والسلام: من رأى منكم منكراً فليغيره بيده فإن لم يستطعع فبلسانه فإن لم يستطع فبقلبه وذلك أضعف الإيمان خرجه الإمام مسلم في صحيحه.\nفأنت أيها السائل ما دمت نصحته ووجهته إلى الخير ولكنه ما زاده ذلك إلا إظهاراً للمعصية فينبغي لك هجره وعدم اتخاذه صاحباً ولا صديقاً، وينبغي لك أن تشجع غيرك من الذين قد يؤثرون عليه وقد يحترمهم أكثر على نصيحته ودعوته إلى الله لعل الله ينفعه بذلك، وإن رأيت أن الهجر يزيده شراً وأن اتصالك به أنفع له في دينه وأقل لشره فلا تهجره؛ لأن الهجر يقصد منه العلاج فهو دواء، فإذا كان لا ينفع بل يزيد الداء داءً فأنت تعمل ما هو الأصلح من الاتصال به وتكرار النصيحة والأمر بالمعروف والنهي عن المنكر من غير اتخاذه صاحباً ولا صديقاً لعل الله أن ينفعه بذلك، وهذا هو أحسن ما قيل في هذا من كلام أهل العلم رحمهم الله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7463/موقف-الناصح-من-العاصي-الرافض-للنصيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_155/15501.mp3","categories":["الدعوة والدعاة"]},{"id":9331,"question":"ننتقل إلى رسالة وصلت إلى البرنامج من أحد الإخوة يقول: صلاح عبدالرحيم أحمد سوداني، أخونا يقول: إذا كان لدي أخ أصم وأبكم وهو لا يسمع ولا يتكلم كما هو معلوم، وطبعاً لا يعرف شيئاً عن الصلاة ولا الصوم ولا الزكاة ولا يعرف شيئاً عن أحكام الإسلام، ولا يعرف شيئاً من القرآن كيف يكون التوجيه والحالة هذه؟","title":"كيفية تعليم الأصم الأبكم أحكام الإسلام","answer":"الجواب: هذا لابد، يعني: يفعل معه ما يعلم به عقله من إشارة إذا كان يبصر ...... الناس وقت الصلاة حتى ينظر أعمالهم، ويكتب له إن كان يكتب، يعلم الكتابة لعله يستفيد من الكتابة حتى يعرف عقله أنه يعي أو يفهم، فإذا كان يعي ويفهم بالكتابة والإشارة فهو مكلف بحسب ما وصل إلى علمه، إذا كان لا ينطق ولا يسمع فقد يفهم بالإشارة أو بالكتابة إن تيسرت الكتابة حتى يعمل بما أوجب الله ويترك ما حرم الله من طريق الكتابة أو من طريق الإشارة هذا إذا كان يعقل، أما إذا كان ما يعقل ظهر من حاله أنه لا يعقل فلا حرج عليه؛ لأنه غير مكلف، رفع القلم عن ثلاثة منهم: الصغير حتى يبلغ، والمعتوه حتى يفيق، فإذا كان معتوهاً لا عقل له فلا شيء عليه. نعم.\nالمقدم: إذاً يكفي من مثل هذا التقليد، يعلمونه التقليد وهو كافي؟\nالشيخ: يعلمونه حسب الإمكان، بالمكاتبة، بالإشارة، بالشيء الذي يستطيعون، وقد يعوض هذا الجنس فهماً عظيماً بالإشارات، إذا فقد حاسة السمع وحاسة الكلام قد يعوض بإذن الله هذا مشاهد معروف من أولئك الذين يبتلون بهذا عندهم فهم عظيم للإشارات، ونحن نعرف من هذا ناساً يعملون ويكدحون ويحصلون أموالاً بالإشارة ويصلوا مع الناس ويصوموا مع الناس وكانوا من خيرة الناس كله بالإشارة أو بالكتابة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7484/كيفية-تعليم-الاصم-الابكم-احكام-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_155/15505.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9356,"question":"أختنا تقول: إنها قادرة على شراء الكتب وتوزيعها في سبيل الله، فهل هناك قائمة تنصحونها بشرائها لتقوم بتوزيعها؟","title":"كتب ينصح بتوزيعها","answer":"الجواب: نعم، الكتب من أهم القربات، توزيعها من أهم القربات، الكتب النافعة المفيدة وهي داخلة في قول النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له وهو حديث صحيح، فإذا اشترى الإنسان الكتب الطيبة ووزعها أو جعلها في المكتبات العامة للمسلمين فهذا عمل صالح وصدقة جارية.\nومن أحسنها فيما نعلم: كتاب التوحيد للشيخ محمد بن عبد الوهاب، كتاب الثلاثة الأصول، وكشف الشبهات، وآداب المشي إلى الصلاة، وزاد المعاد لـابن القيم في هدي خير العباد، فتح المجيد للشيخ عبد الرحمن بن حسن، تيسير العزيز الحميد للشيخ سليمان بن عبد الله، وكلاهما حفيد للشيخ محمد بن عبد الوهاب، الصحيحان البخاري ومسلم، سنن أبي داود، سنن الترمذي، سنن النسائي، سنن ابن ماجة، سنن الدارمي ، موطأ مالك ، مسند أحمد، كل هذه كتب عظيمة شراؤها وتسبيلها للمسلمين في المكتبات العامة أو توزيعها على طلبة العلم كل ذلك نافع، كله طيب، ....فتاوى شيخ الإسلام ابن تيمية ، الدرر السنية فتاوى أئمة الدعوة الإسلامية في نجد، كل هذه كتب عظيمة نافعة، اقتضاء الصراط المستقيم مخالفة أصحاب الجحيم لشيخ الإسلام ابن تيمية ، العقيدة الواسطية لشيخ الإسلام ابن تيمية ، الرسالة الحموية لشيخ الإسلام ابن تيمية ، الرسالات النورية لشيخ الإسلام ابن تيمية ، كلها كتب عظيمة مفيدة نافعة، فهذه الكتب وأشباهها شراؤها وتوزيعها طيب، هكذا شرح الطحاوية لـابن أبي العز كتاب مفيد نافع. نعم.\nالمقدم: من كتب التفسير لو تكرمتم؟\nالشيخ: من كتب التفسير تفسير ابن كثير ، تفسير ابن جرير ، تفسير البغوي ، تفسير الشوكاني ، تفسير القرطبي ، كل هذه كتب مفيدة نافعة، شراؤها وتوقيفها وتسبيلها أمر مهم ونافع للمسلمين. نعم.\nالمقدم: من المؤلفات في العصر الحديث مثلاً؟\nالشيخ: فيه مؤلفات في العصر الحديث كذلك فيه مؤلفات نافعة منها: مؤلفات أخينا العلامة الشيخ عبد الله بن حميد رحمه الله ..........وأخينا الشيخ حمود التويجري وبعض المؤلفات التي لنا يعرفها الناس.\nفيه كتب أخرى قد لا تحضرني الآن من إخواننا المعروفين مثل بعض مؤلفات الشيخ صالح بن فوزان كذلك مفيدة ونافعة، والذي يريد أن يشتري ويوزع ينبغي له أن يستشير بعض العلماء حتى يعني: يكون على بصيرة فيما يشتري وفيما يوزع أو يكتب عليه وقف في المكتبات، يعني: ينبغي له أن يستشير حتى يكون على بينة فيه؛ لأن بعضها الآن قد غاب عني. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7520/كتب-ينصح-بتوزيعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_156/15604.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9373,"question":"الواقع سماحة الشيخ المبتدئ في القراءة قد يقع على شيء من هذا، فبما تنصحونه والحالة هذه؟","title":"نصيحة للمبتدئ في طلب العلم إذا أشكل عليه شيء","answer":"الشيخ: نعم.\nالمقدم: المبتدئ في الاطلاع على كتب أهل العلم قد يقع على شيء من هذا، وربما يقع في حيرة.\nالشيخ: يسأل أهل العلم إذا اشتبه عليه القارئ، وطالب العلم المبتدي إذا مر عليه شيء من الأحاديث واشتبه عليه أمرها أو بعض الآيات يسأل أهل العلم الذين عنده ولو سافر إليهم، يسأل أهل العلم الذين بلغه عنهم أنهم أهل علم وأهل بصيرة، ويطمئن إليهم يسألهم، بالمكاتبة.. بالمشافهة.. بالهاتف.. بغير هذا من طرق الاتصال، والمقام يحتاج إلى عناية، الله يقول: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43]. نعم. \nالمقدم: ذكرتم السفر وهذا دليل على أهمية التوضيح فيما يتعلق بأمور ديننا؟\nالشيخ: نعم، ولو بالسفر، قد سافر جمع من الصحابة من بلد إلى بلد من المدينة إلى مصر وإلى الشام من أجل بعض الأحاديث رضي الله عنهم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7537/نصيحة-للمبتدى-في-طلب-العلم-اذا-اشكل-عليه-شيء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/18611.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9388,"question":"شيخ عبدالعزيز أمامي رسالتان: الأولى من خمس صفحات من الحجم المتوسط، والثانية من صفحتين من الحجم الكبير، كل ما في الرسالتين بحث عن السبيل الأمثل للدعوة إلى الله، وعن السبيل الأمثل للأمر بالمعروف والنهي عن المنكر:الرسالة الأولى: من أخت رمزت إلى اسمها تقول: امرأة متدينة، أما الرسالة الثانية فهي من الأخ: (ع. ع. ع) من جدة، الرسالتان يذكر مرسلوها أنهم يلاحظون بعض الأخطاء من المسلمين ويتألمون كثيراً لما يرون، ويتمنون أن لو في أيديهم شيء لتغيير المنكر ويرجون التوجيه. سنخصص بقية هذه الحلقة سماحة الشيخ لو تكرمتم في الطريق الأمثل للأمر بالمعروف وللدعوة إلى الله لو تكرمتم فماذا تبدءون؟","title":"ما السبيل الأمثل في الدعوة إلى الله والأمر بالمعروف؟","answer":"الجواب: الله  قد بين طريق الدعوة وماذا ينبغي للداعي، فقال : قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ أَنَا وَمَنِ اتَّبَعَنِي [يوسف:108] فالداعي إلى الله يجب أن يكون على علم وعلى بصيرة فيما يدعو إليه وفيما ينهى عنه حتى لا يقول على الله بغير علم، ويجب الإخلاص في ذلك لأن الله قال: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ [يوسف:108]، لا إلى مذهب ولا إلى رأي فلان أو فلان، ولكنه يدعو إلى الله يريد ثوابه، يريد مغفرته، يريد صلاح الناس، فلابد أن يكون عن إخلاص ولابد أن يكون عن علم، وقال : ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] فهذا بيان كيفية الدعوة وأنها تكون بالحكمة، يعني: بالعلم، قال الله وقال رسوله، سمي العلم حكمة؛ لأنه يردع عن الباطل ويعين على إثبات الحق، ويكون مع العلم موعظة حسنة وجدال بالتي هي أحسن عند الحاجة إلى ذلك.\nبعض الناس قد يكفيه بيان الحق بأدلته؛ لأنه يطلب الحق فمتى ظهر له قبله، وقد يكون في غير حاجة إلى الموعظة، وبعض الناس قد يكون عنده شيء من التوقف شيء من الجفا فيحتاج إلى موعظة، فالداعي إلى الله يعظ ويقيم الأدلة ويذكر إذا احتاج إلى ذلك مع الجفاة ومع الغافلين ومع المتساهلين حتى يقنعوا وحتى يلتزموا بالحق.\nوقد يكون المدعو عنده شيء من الشبه فيجادل في ذلك ويريد كشف الشبهة، فالداعي إلى الله يوضح له الحق بأدلته، ويزيح الشبه بالأدلة الشرعية، لكن بكلام طيب وأسلوب حسن ورفق لا بعنف وشدة، حتى لا يبقى للمبطل أو للمنهي أو المدعو لا يبقى له شبهة، يزيحها حسب الطاقة، يزيحها بالأدلة حسب الطاقة، قال الله : فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لانْفَضُّوا مِنْ حَوْلِكَ [آل عمران:159] وقال الله لما بعث موسى وهارون إلى فرعون: فَقُولا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى [طه:44] ويقول ﷺ: إن الرفق لا يكون في شيء إلا زانه ولا ينزع من شيء إلا شانه ويقول ﷺ: من يحرم الرفق يحرم الخير كله فالداعي إلى الله عليه أن يتحرى ويرفق ويجتهد في الإخلاص لله وفي علاج الأمور بالطريقة التي رسمها الله بالحكمة والموعظة الحسنة والجدال بالتي هي أحسن، وأن يكون في هذا كله على علم على بصيرة على هدى حتى يقنع الطالب للحق، وحتى يزيل الشبهة لمن عنده شبهة، وحتى يلين القلوب لمن عنده جفاء أو قسوة أو إعراض، يلين القلوب بالدعوة إلى الله والموعظة الحسنة والتوجيه إلى الخير وبيان ما له عند الله من الخير إذا قبل الحق وما عليه من الخطر إذا رد الحق، إلى غير هذا من وجوه الموعظة.\nوأما أصحاب الحسبة الذين يأمرون بالمعروف وينهون عن المنكر فكذلك يجب أن يلزموا الآداب الشرعية فيما يلتزمه الداعي إلى الله، فعليهم بالرفق وعدم العنف، إلا إذا دعت الحاجة إلى هذا من الظلمة والمكابرين والمعاندين، أما غيرهم فمثل ما للداعي ينكر المنكر بالرفق والحكمة ويأمرون بالمعروف بالرفق والحكمة ويقيمون الأدلة على ذلك حتى يقنع صاحب المنكر وحتى ينتبه وحتى يلتزم بالحق، وذلك على حسب الاستطاعة، كما قال عليه الصلاة والسلام: من رأى منكم منكراً فليغيره بيده فإن لم يستطع فبلسانه فإن لم يستطع فبقلبه وذلك أضعف الإيمان رواه مسلم ، والله يقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] ويقول سبحانه: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَأُوْلَئِكَ هُمُُ الْمُفْلِحُونَ [آل عمران:104] ويقول سبحانه: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللَّهِ([آل عمران:110].\nوقد توعد من ترك ذلك وأعرض عن ذلك ولعنهم على لسان داود وعيسى بن مريم بسبب عصيانهم واعتدائهم وعدم تناهيهم عن المنكر، حيث قال سبحانه في كتابه العظيم في سورة المائدة: عِنَ الَّذِينَ كَفَرُوا مِنْ بَنِي إِسْرَائِيلَ عَلَى لِسَانِ دَاوُدَ وَعِيسَى ابْنِ مَرْيَمَ ذَلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ  ۝ كَانُوا لا يَتَنَاهَوْنَ عَنْ مُنكَرٍ فَعَلُوهُ لَبِئْسَ مَا كَانُوا يَفْعَلُونَ [المائدة: 78 - 79] فالأمر عظيم.\nفيجب على أهل الإيمان وعلى أهل القدرة من الولاة والعلماء وغيرهم من أعيان المسلمين الذين عندهم قدرة وعندهم علم أن ينكروا المنكر وأن يأمروا بالمعروف، وليس هذا خاصاً بطائفة معينة وإن كانت الطائفة المعينة عليها واجبها وعليها العبء الأكبر لكن لا يلزم من ذلك إهمال غيرها ، بل يجب على غيرها أن يساعدوها وأن يكونوا معها في إنكار المنكر والأمر بالمعروف حتى يكثر الخير ويقل الشر، ولاسيما إذا كانت الطائفة المعينة لم تغطي المطلوب ولم يحصل بها المقصود بل الأمر أوسع والشر أكثر فإن مساعدتها واجبة بكل حال، أما لو قامت بالمطلوب وحصل بها الكفاية فهذا معلوم أنه فرض كفاية، يعني: الأمر بالمعروف والنهي عن المنكر فرض كفاية.\nفإذا حصل بالمعينين أو المتطوعين المسئولين المطلوب من إزالة المنكر والأمر بالمعروف صار في حق الباقين سنة، أما منكر ليس له من يزيله إلا أنت؛ لأنك الموجود في القرية أو في القبيلة أو في الحي ليس فيها من يأمر بالمعروف سواك فإنه يتعين عليك إنكار المنكر والأمر بالمعروف مادمت أنت الذي علمته وأنت الذي تستطيع إنكاره فإنه يلزمك، فمتى وجد معك غيرك صار فرض كفاية، من قام به منكما أو منكم حصل به المقصود، فإن تركتم جميعاً أثمتم جميعاً.\nفالحاصل أنه فرض على الجميع فرض كفاية متى قام به من المجتمع أو من القبيلة أو من أهل القرية أو المدينة من يكفي سقط عن الباقين، وهكذا الدعوة إلى الله، ومتى ترك الجميع أثموا وصار الإثم عاماً لهم؛ لأنهم قصروا في الواجب ولم يقوموا به، ومتى قام به من يكفي دعوة وتوجيهاً وإنكاراً للمنكر صار في حق الباقين سنة عظيمة؛ لأن المشاركة في الخير مطلوبة. نعم.\nالمقدم: سماحة الشيخ تركزون على العلم بطريق الدعوة إلى الله، وبطريق الأمر بالمعروف والنهي عن المنكر، لعل سماحة الشيخ يحدد العلم الذي ينبغي أن يتعلمه من يريد الدعوة إلى الله على بصيرة ويريد الأمر بالمعروف والنهي عن المنكر على الطريقة الشرعية؟\nالشيخ: لابد من العلم، والعلم قال الله وقال رسوله، العلم أن يعتني بالقرآن الكريم وبالسنة المطهرة، يعرف ما أمر الله به وما نهى الله عنه، ويعرف طريقة الرسول صلى الله عليه وسلم في دعوته إلى الله وإنكاره للمنكر وطريقة أصحابه رضي الله عنهم وأرضاهم، يكون متبصراً في هذا، بمراجعة كتب الحديث الشريف، مع العناية بالقرآن الكريم، مع مراجعة كلام العلماء في هذا الباب فقد أوسعوا الكلام رحمة الله عليهم وبينوا ما يجب.\nفالذي ينتصب لهذا الأمر يجب عليه أن يعنى بهذا الأمر حتى يكون في ذلك على بصيرة من كتاب الله ومن سنة رسوله عليه الصلاة والسلام حتى يضع الأمور في مواضعها، فيضع الدعوة إلى الخير في موضعها والنهي عن المنكر في موضعها، وهكذا إنكار المنكر والأمر بالمعروف يكون في موضعه على بصيرة على علم، حتى لا يقع منه إنكار المنكر بما هو أنكر منه، وحتى لا يقع منه الأمر بالمعروف على وجه يوجد منكراً أكثر من هذا الأمر الذي دعا إليه.\nالمقصود: أنه لابد من علم حتى يضع الأمور في مواضعها، وحتى إذا أنكر المنكر نفع ذلك ولم يترتب عليه ما هو أنكر، وحتى إذا دعا إلى المعروف يرجى أن يحصل المعروف أو على الأقل لا يترتب عليه منكر يكون أكبر منه وأعظم وأشر من ترك هذا المعروف. نعم.\nالمقدم: أختنا صاحبة الرسالة التي رمزت إلى اسمها بالمستمعة المؤمنة المتدينة تقول: إذا رأت من أقاربها أحداً يرتكب بعض المنكرات كيف يكون موقفها؟\nالشيخ: عليها أن تنكر المنكر بالأسلوب الحسن، والكلام الطيب، والرفق والعطف على صاحب المنكر؛ لأنه قد يكون جاهلاً، قد يكون شرس الأخلاق عند الإنكار عليه بشدة يزداد شره، فعليها أن تنكر المنكر على أختها في الله وعلى أخيها في الله لكن بالأسلوب الحسن والكلام الطيب وذكر الدليل، قال الله وقال رسوله، مع الدعاء له بالتوفيق والهداية، هكذا يكون عندها وعند الرجل من الحكمة والبصيرة والتحمل ما يجعل الذي ينكر عليه يتقبل ما ينفر ولا يعاند، يعني: يجتهد الداعي ويجتهد المنكر يجتهد في استعمال الألفاظ التي يرجى من ورائها قبول الحق. نعم.\nالمقدم: إذا كان المنكر الذي تراه هذه الأخت هو الاختلاط وعدم الحجاب كيف تنصحونها شيخ عبد العزيز ؟\nالشيخ: تنصحهم تقول لأختها في الله: الواجب عليك كذا، عدم الاختلاط، الواجب عليك عدم السفور، التحجب عن الرجال الذين ليسوا محارم، قال الله تعالى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] قال الله تعالى: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] الآية، وهكذا تخاطبهم بالآيات والنصوص، يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ [الأحزاب:59] يا أختي في الله! الأمر عظيم، فإن السفور يترتب عليه كذا وكذا، والاختلاط بالرجال يترتب عليه كذا وكذا، فالواجب علينا جميعاً أن نحذر ما حرم الله، وأن نتعاون على البر والتقوى، وأن نتواصى بالحق ونتناصح، وهكذا .... تكون عبارات حسنة. نعم.\nالمقدم: مقاطعة مرتكب الخطيئة يا شيخ عبد العزيز ! ما موقف الداعية منها، ولاسيما إذا كان من الأقارب؟\nالشيخ: هذا فيه تفصيل، مقاطعة صاحب المنكر وهجره فيه تفصيل:\nيشرع هجره ومقاطعته إذا أعلن المنكر وأصر ولم ينفع فيه النصح، شرع لقريبه أو جاره أو غيرهم هجره وعدم إجابة دعوته وعدم السلام عليه حتى يتوب إلى الله من هذا المنكر، هكذا فعل النبي ﷺ والصحابة لما تخلف كعب بن مالك الأنصاري وصاحباه عن غزوة تبوك بغير عذر شرعي، أمر النبي ﷺ بأن لا يكلموا ويهجروا، فهجروا جميعًا وتركوا جميعًا، لا يسلم عليهم ولا يدعون لوليمة ولا يرد عليهم السلام إذا سلموا، حتى تابوا فتاب الله عليهم.\nأما إن كان هجر الشخص قد يترتب عليه ما هو أنكر؛ لأنه ذو شأن في الدولة أو ذو شأن في القبيلة تترك هجره ويعامل بالتي هي أحسن ويرفق به حتى لا يترتب على هجره ما هو أشر من فعله وما هو أقبح من عمله، والدليل على هذا: أنه ﷺ لم يعامل عبد الله بن أبي بن سلول رأس المنافقين لم يعامله مثلما عامل الثلاثة، بل تلطف به ولم يهجره ولم يزل يرفق به؛ لأنه رئيس قومه، ويخشى من قتله أو سجنه أو هجره فتنة للجماعة في المدينة، فلهذا كان النبي ﷺ يرفق به حتى مات على نفاقه، نسأل الله العافية.\nوهنا مواضع أخرى جرت له صلى الله عليه وسلم مع بعض الناس لم يهجرهم بل رفق بهم عليه الصلاة والسلام حتى هداهم الله. نعم.\nالمقدم: إذاً الرفق هو ما يدعو إليه الشيخ عبد العزيز ؟\nالشيخ: نعم.\nالمقدم: بارك الله فيكم.\nالشيخ: يهجر إذا كان الهجر أصلح، ويترك الهجر إذا كان الترك أصلح مع إنكار المنكر ومع إظهار كراهة المنكر وأن صاحبه ليس صديقاً ولا صاحباً ولكن من أجل كذا وكذا ترك الهجر، ولكن بالكلام الطيب والحكمة والإنكار السري والوصية عليه من خواصه لعله يستجيب إلى غير هذا من وجوه النصيحة ووجوه الإنكار الرافض.","link":"https://binbaz.org.sa/fatwas/7552/ما-السبيل-الامثل-في-الدعوة-الى-الله-والامر-بالمعروف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_157/15706.mp3","categories":["الدعوة والدعاة"]},{"id":9389,"question":"مع مطلع هذه الحلقة سماحة الشيخ نعود إلى رسالة إحدى الأخوات المستمعات تقول: امرأة متدينة، وأيضاً إلى رسالة أحد الإخوة المستمعين من جدة، سبق أن عرضنا بعض ما في هذه الرسائل ولاسيما رسالة الأخ (ع. ع. ع) من جدة، هاتان الرسالتان يهتم صاحباها بأمر الدعوة إلى الله وتفضلتم وبينتم بعض الأوجه في الحلقة التي سبقت هذه الحلقة، وبودي أن تتكرموا سماحة الشيخ في هذه الحلقة بعرض ما ينبغي للداعية أن يفعله تجاه ثقافته، مم يستمد ثقافته حتى تكون دعوته مؤثرة ومستجابة بإذن الله؟","title":"بعض الأمور التي تعين الداعي إلى الله في دعوته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن الدعوة إلى الله  من أهم المهمات ومن أفرض الفرائض، والناس في أشد الحاجة إليها، كل مجتمع في أشد الحاجة إليها سواء كان مجتمعاً مسلماً أو مجتمعاً كافراً، فالمجتمع المسلم في حاجة إلى تنبيهه على ما قد يقع من أغلاط ومنكرات حتى يتدارك ما وقع منه من الخطأ وحتى يستقيم على طاعة الله ورسوله وحتى ينتهي عما نهى الله عنه ورسوله، والكافر يدعى إلى الله ويبين له أن الله خلقه لعبادته وأن الواجب عليه الدخول في الإسلام والالتزام بما جاء به نبي الهدى محمد عليه الصلاة والسلام؛ ولكن الداعي إلى الله يلزمه أمور لابد من مراعاتها حتى تكون دعوته ناجحة وحتى تكون لها العاقبة الحميدة؛ أعظمها وأهمها: العلم، فلابد أن يكون عنده علم والعلم إنما يؤخذ من كتاب الله العظيم وسنة رسوله الأمين عليه الصلاة والسلام، كما قال الله : قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108] قال أهل العلم: معناه على علم؛ لأن العالم بالنسبة إلى المعلومات كالبصير بالنسبة إلى المرئيات فهو يعلم كيف يأمر؟ كيف ينهى؟ كيف يدعو إلى الله؟ كما أن الرائي المبصر يرى ما أمامه حتى يتجنب ما يضره من حفر وأشواك ونحو ذلك.\nفالحاصل أن الداعي إلى الله يلزمه أن يعتني بالعلم وأن تكون ثقافته ثقافة إسلامية مستخرجة ومستنبطة من كتاب الله ومن سنة رسوله عليه الصلاة والسلام، ويستعين بكتب أهل العلم المعروفين بالاستقامة والعلم والفضل وحسن العقيدة حتى يكون على بصيرة فيما يدعو إليه وعلى بصيرة فيما ينهى عنه، هذا هو الواجب على جميع الدعاة، ثم أمر آخر هو أن يتحرى في دعوته وأن لا يعجل وأن يرفق في دعوته، لابد من كونه يتحرى في دعوته حتى يضع الأمور في مواضعها، فإن كان المدعو ممن يفهم العلم وممن يمكن أن يستجيب من دون حاجة إلى موعظة ولا جدال وضح له الحق ودله عليه بالأدلة الشرعية وبالكلام الطيب والرفق والأسلوب الحسن فإذا تقبل ذلك انتهى الموضوع وحصل المطلوب، فإن كان ممن لديه جفاء وإعراض وغفلة وعدم مبالاة نصحه ووعظه بالتي هي أحسن وذكره بالله لعله يستجيب، لعله ينقاد للحق، فإن كان ذا شبه وذا مجادلة رفق به وجادله بالتي هي أحسن حتى يزيل شبهته وحتى يوضح الحق الذي أشكل عليه وحتى لا تبقى له شبهة يتشبث بها في ترك الحق أو في الاستمرار على الباطل، وهذه المعاني كلها قد تضمنها قوله سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] ومما يلزمه: الإخلاص لله وأن يحذر الرياء وأن يكون في دعوته يقصد وجه الله والدار الآخرة، لا رياء الناس ولا حمد الناس ولا قصد مدحهم له أو قصد عرض من الدنيا، فالمؤمن إنما يريد وجه الله والدار الآخرة، ولهذا قال سبحانه: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ [يوسف:108] قال سبحانه: وَمَنْْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ [فصلت:33] وهناك أمر آخر وهو أيضاً تحري الألفاظ المناسبة والرفق في الكلام وعدم الغلظة إلا عند الضرورة إليها، كما قال تعالى: وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]، وقال: وَلا تُجَادِلُواا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ [العنكبوت:46] وهم كفار؛ يهود ونصارى وَلا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ إِلَّاا الَّذِينَ ظَلَمُوا مِنْهُمْ [العنكبوت:46] فلابد من عنايته بالجدال بالتي هي أحسن عند الحاجة والرفق، كما قال عليه الصلاة والسلام: إنن الرفق لا يكون في شيء إلا زانه ولا ينزع من شيء إلا شانه وقال ﷺ: من يحرم الرفق يحرم الخير كله فعلى المؤمن في دعوته الرفق والأسلوب الحسن حتى يستجاب له وحتى لا يقابل بالرد أو بالأسلوب الذي لا يناسب الداعي إلى الله ، فإن بعض الناس عند الشدة قد يقابل بالسب والشتم والكلام الرديء الذي يزيد الطين بلة، ولكن متى كان الداعي إلى الله رفيقاً حكيماً ذا أسلوب صالح فإنه لن يعدم إن شاء الله قبول دعوته أو على الأقل المقابلة الحسنة والكلام الطيب من المدعو الذي يرجى من ورائه أن يتأثر بالدعوة، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/7553/بعض-الامور-التي-تعين-الداعي-الى-الله-في-دعوته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_158/15801.mp3","categories":["الدعوة والدعاة"]},{"id":9390,"question":"بارك الله فيكم. هل من كتب معينة ينصح بها سماحة الشيخ عبدالعزيز كل من يود أن يعمل في مجال الدعوة إلى الله؟","title":"كتب ينصح بها للداعية إلى الله","answer":"","link":"https://binbaz.org.sa/fatwas/7554/كتب-ينصح-بها-للداعية-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_158/15802.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9391,"question":"لو أذنتم لي سماحة الشيخ عن المرأة والدعوة إلى الله، ماذا تقولون؟","title":"المرأة وواجبها في الدعوة إلى لله","answer":"الجواب: هي كالرجل عليها واجبها في الدعوة إلى الله وإنكار المنكر فإن التعاليم تعم الجميع والقرآن يعم الجميع والسنة تعم الجميع وكلام أهل العلم يعم الجميع، فعليها أن تدعو إلى الله وأن تأمر بالمعروف وأن تنهى عن المنكر بالآداب الشرعية التي تطلب من الرجل وعليها مع ذلك ألا يحملها ما تقوم به من دعوة وإرشاد وإنكار المنكر على جزع أو قلة صبر لاحتقار بعض الناس لها أو سبهم لها أو سخريتهم بها أو نحو ذلك، بل عليها أن تتحمل وعليها أن تصبر ولو رأت من بعض الناس ما قد يكون نوعًا من السخرية أو من الاستهزاء أو الاحتقار، ثم عليها أيضًا أن ترعى أمرًا آخر وهو أن تكون مثالًا في العفة والحجاب عن الرجال الأجانب وأن تبتعد عن التبرج والاختلاط المذموم، بل تكون دعوتها مع العناية والبعد عن كل ما ينكر عليها، فإن دعت الرجال دعتهم وهي محتجبة من دون خلوة، وإن دعت النساء دعتهم بحكمة وأن تكون نزيهة في أخلاقها وسيرتها حتى لا يعترضوا عليها ويقولوا: ما بدأت بنفسها ؟ لماذا ما بدأت بنفسها؟ وهكذا البعد عن اللباس الذي قد تفتن الناس به وإظهار المحاسن فيما يتعلق بدعوتها للرجال، بل تكون بعيدة عن كل أسباب الفتنة، عند الرجال بعيدة عن أسباب الفتنة بل ملتزمة بالحجاب والبعد عن أسباب الفتنة من إظهار محاسن أو تكسر في صوت يطمع فيها أو غير هذا مما قد ينكر عليها بل تكون عندها العناية الكاملة بالدعوة إلى الله على وجه لا يضر دينها ولا يضر سمعتها، وهكذا مع النساء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7555/المراة-وواجبها-في-الدعوة-الى-لله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_158/15803.mp3","categories":["الدعوة والدعاة","قضايا المرأة"]},{"id":9392,"question":"إذا كان المدعو أو إذا كان المدعوات متأثرين بثقافات معينة أو بمجتمعات معينة ما هو السبيل الأمثل لدعوتهم؟","title":"كيفية دعوة المتأثرين بثقافات معينة","answer":"الجواب: يبين لهم ما في المناهج التي تأثروا بها والطرق التي تأثروا بها والبيئات التي تأثروا بها، يبين لهم أن هذه البيئات أو هذه الطرق أو هذه الجمعيات أو هذه الآثار التي اكتسبتموها من كذا وكذا ينقصها كذا وكذا وعليكم أن تعرضوها على الميزان على كتاب الله وسنة الرسول عليه الصلاة والسلام، فما حصلتم من كذا أو تعلمتم من كذا أو تخلقتم به بسبب البيئة أو بسبب الاختلاط بآل فلان أو آل فلان عليكم أن تعرضوا ذلك على الميزان على كتاب الله وسنة الرسول ﷺ، مثل ما يعرض العلماء مسائل الفقه على الأدلة، فما وافق الشرع وجب أن يبقى وما خالف الشرع وجب أن يطرح ولو كان من خلق الآباء والجيران والأسلاف والمشايخ وغير ذلك، المهم أن يبقى الخلق الصالح الذي دل عليه كتاب الله وسنة الرسول عليه الصلاة والسلام، وأن لا يتعصب لسيرة أبيه أو جده أو بيئته أو بيئة بلده أو ما أشبه ذلك، بل يكون عنده الحكم الذي لا يجوز أن يخالف هو ما دل عليه كتاب الله وسنة الرسول عليه الصلاة والسلام أو إجماع الأمة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7557/كيفية-دعوة-المتاثرين-بثقافات-معينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_158/15804.mp3","categories":["الدعوة والدعاة"]},{"id":9393,"question":"أعود مرة أخرى إلى المرأة والدعوة إلى الله شيخ عبدالعزيز، هل من سبيل سيتحقق مستقبلاً أو هو قيد الدراسة لتهيئة الفرصة أمام المرأة الداعية إلى الله؟","title":"الحث على تهيئة الفرصة للداعيات إلى الله","answer":"الجواب: لا أعلم مانعًا من ذلك، متى وجدت المرأة الصالحة لهذا فينبغي أن تعان وأن توظف وأن يطلب منها أن تقوم بإرشاد بنات جنسها، لأن النساء في حاجة إلى مرشدات من جنسهن، فإن وجود المرأة بين النساء قد يكون أنفع في تبليغ الدعوة وتبليغ الحق من الرجل، وقد تستحي المرأة من الرجل وقد لا تسأله عن مهماتها، قد يمنع مانع من سماعها لكلامه لكن مع المرأة التي هي من جنسها تخالطها وتعرف ما عندها قد تتأثر بهذا أكثر، وقد تعاقدنا مع جماعة كثيرة من النساء للعمل في الدعوة. نعم.\nالمقدم: إذاً الباب مفتوح أمام المرأة الصالحة ذات العقيدة السليمة وذات العلم وذات الحكمة، الباب مفتوح أمامها.\nالشيخ: في الداخل والخارج. نعم.\nالمقدم: بارك الله فيكم، إذاً هذه بمثابة دعوة يوجهها سماحة الشيخ عبد العزيز لمن تجد في نفسها الكفاءة للدعوة إلى الله وللأمر بالمعروف والنهي عن المنكر أن تتقدم أيضاً رسمياً.\nالشيخ: في الداخل والخارج. نعم.\nالمقدم: بارك الله فيكم. وجزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7558/الحث-على-تهيىة-الفرصة-للداعيات-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_158/15805.mp3","categories":["الدعوة والدعاة","قضايا المرأة"]},{"id":9394,"question":"إذاً الإحساس تجاه الأمر بالمعروف والنهي عن المنكر هذا ينبئ عن أشياء وأشياء، لعل لسماحة الشيخ من كلمة حول هذا؟","title":"ضرورة الدعوة إلى الله","answer":"الجواب: لاشك أن أهل الخير وأن أصحاب الغيرة لدين الله يتأثرون كثيرًا مما وجد في المجتمعات اليوم من كثرة الشرور والمذاهب الهدامة والأفكار المنحرفة في غالب الدنيا، فلهذا يحرصون على وجود من يدعو إلى الله ومن ينكر المنكر من أهل العلم والبصيرة والغيرة لله  حتى لا تكثر الشرور وحتى لا يتفاقم الأمر وحتى لا يحصل للمسلمين ضرر أكثر، وهناك بحمد الله يقظة في هذا العصر وفي آخر العصر الماضي في آخر القرن الرابع عشر وفي هذا القرن، هناك ولله الحمد يقظة وعناية من كثير من الشباب وغير الشباب في جميع الدنيا في خارج المملكة وفي الدول المجاورة وفي أفريقيا وفي آسيا.. كإندونيسيا وماليزيا والهند وباكستان، وهكذا أوروبا وهكذا أمريكا، هناك بحمد الله حركة ويقظة لتبليغ دعوة الله وفي تبصير الناس بالدين وفي السؤال عما أشكل عليهم، هذا أمر عرفناه من مدة طويلة في آخر القرن السابق وفي هذا القرن، وعرفه أيضًا أهل العلم المشغولون بهذا الأمر فإنهم يحسون بنشاط كبير في غالب الدنيا ومكاتبات ومؤلفات، كل ذلك بحمد الله يبشر بخير.\nنسأل الله أن يوفق المسلمين لما فيه رضاه وأن يمنحهم الفقه في الدين وأن يكثر بينهم دعاة الهدى، وأن يوفقهم لقبول الحق وإيثاره على ما سواه إنه خير مسئول، كما نسأله سبحانه أن يصلح قادة المسلمين في كل مكان وأن يصلح لهم البطانة وأن يعينهم على إيثار الحق والدعوة إليه وعلى تحكيم شريعة الله في عباد الله، فهي والله الطريق الوحيد والطريق الأمثل لصلاح الأمة ونجاتها في الدنيا والآخرة، وتحكيم الشريعة في شئون المسلمين هو الطريق الذي تحصل به سعادتهم ونجاتهم وحل مشاكلهم والقضاء على ما بينهم من الفساد ومنع المنكر وإقامة المعروف وزجر المبطل عن باطله، فنسأل الله أن يوفق قادة المسلمين للالتزام بها وتحكيمها والحذر مما يخالفها إنه خير مسئول.","link":"https://binbaz.org.sa/fatwas/7559/ضرورة-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_158/15806.mp3","categories":["الدعوة والدعاة"]},{"id":9395,"question":"شيخ عبدالعزيز بعض الرسائل التي تصل إلى هذا البرنامج يعبر أصحابها بعبارات تدل على التألم والاحتراق بل وربما الحسرة في بعض الأحيان، لعل لسماحة الشيخ من توجيه حول إحساس الداعية ؟","title":"حث الدعاة على الصبر وعدم اليأس","answer":"الجواب: وهذا مثل ما تقدم؛ لأن مشاهدة صاحب الغيرة وصاحب العلم للمنكرات الكثيرة وقلة المنكرين لها وفشوها في غالب المجتمعات، لاشك أنه يؤلم المؤمن ولاشك أنه يجد منه ..... في قلبه وحسرة في قلبه لكونه يعجز عن إنكار هذا المنكر والقضاء عليه فيتألم لذلك، حتى بلغنا عن بعض السلف أنه كان إذا رأى المنكر يبول دماً من شدة ما يقع في قلبه من التألم.\nفالحاصل أن أصحاب الغيرة وأصحاب العلم والفضل يتألمون كثيراً مما يشاهدونه من المنكرات وهم عاجزون عن إنكارها والقضاء عليها، ويفرحون إذا وجد من ينكرها ويستطيع الدعوة إلى تركها، فهذا لاشك أنه يبشر بالخير ولكن نبشرهم أنهم على خير وأنه ينبغي لهم أن لا ييأسوا وأن لا يقنطوا وأن يستمروا في إنكار المنكر حسب طاقتهم وأنه لا يكفي مجرد التألم بل لابد مع التألم من إنكار المنكر بالطرق التي شرعها الله باليد عند القدرة ثم اللسان عند القدرة ثم القلب كراهة المنكر وعدم المجالسة لأهله، هكذا يكون المؤمن أينما كان ولا ييئس أبداً، فالله يقول: وَلا تَيْئَسُوا مِنْ رَوْحِ اللَّهِ إِنَّهُ لا يَيْئَسُ مِنْ رَوْحِ اللَّهِ إِلَّا الْقَوْمُ الكَافِرُونَ [يوسف:87].\nفالواجب على المؤمن وعلى طالب العلم وعلى المؤمنة وعلى طالبة العلم أن يبذل كل منهم ما استطاع في هذا السبيل وأن لا ييئس بل يكون أينما كان آمراً بالمعروف ناهياً عن المنكر داعياً إلى الله  مرشدًا لعباد الله بما أعطاه الله مما علمه الله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ولو هدى الله على يده واحداً كان خيرًا عظيمًا ولو هدى الله على يديها امرأة واحدة كان خيرًا عظيمًا، فقد ثبت عن رسول الله عليه الصلاة والسلام أنه قال لـعلي بن أبي طالب أمير المؤمنين  لما بعثه إلى خيبر ليدعو اليهود -سكان خيبر ذاك الوقت- إلى الإسلام، قال له ﷺ: فوالله لأن يهدي الله بك رجلاً واحداً خير لك من حمر النعم يبين له أن ليس المقصود قتالهم وليس المقصود أخذ أموالهم وليس المقصود سبي ذرياتهم ونسائهم، لا، المقصود دعوتهم إلى الله، المقصود إخراجهم من الظلمات إلى النور، المقصود هدايتهم حتى يدخلوا في الإسلام حتى يسلموا من النار، ولهذا يقول سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ لِتُخْرِجَ النَّاسَ مِنَ الظُّلُمَاتِ إِلَى النُّورِ [إبراهيم:1] ما أنزل ليحرقهم أو ليقتلهم، أنزل ليخرجهم ليدلهم على الخير، فهذا هو المطلوب من الدعوة وهو المطلوب من الرسل، لكن عند المعاندة وعند عدم الإجابة من المدعوين ينتقل حينئذ المسلمون معهم إلى الأمر الآخر إلى القتال حتى يردوهم إلى الحق بالقوة وحتى يخلصوا ذرياتهم ونساءهم من هذا الإثم حتى يدخلوهم في الإسلام وحتى يستعينوا بأموالهم وما أعطاهم الله على دين الله وإقامته وعلى دعوة الآخرين إلى الله عز وجل، فالقتال ليس المقصود بالقصد الأول إنما هو المقصود بالقصد الثاني، فإذا تيسر دعاؤهم إلى الخير وهدايتهم وإقبالهم على الحق وقبولهم له هذا هو المطلوب، فإذا عاندوا وكابروا شرع قتالهم حينئذ حتى يدخلوا في الإسلام أو يؤدوا الجزية إن كانوا من أهل الكتاب أو من المجوس كما جاءت به السنة ودل عليه الكتاب العظيم.\nفالمقصود من هذا كله: أن الدعوة إلى الله هي الأساس الأول وأن الصبر عليها من أهم المهمات، وأن الشخص الواحد إذا هداه الله على يد الإنسان خير له من الدنيا وما عليها وأن له مثل أجره كما قال ﷺ: من دل على خير فله مثل أجر فاعله هذه غنيمة عظيمة تجعل الداعي إلى الله وتجعل المجاهدين يشمرون عن ساعد الجد ويصبرون على الأذى حتى يدركوا هذا المطلب العظيم. نعم.\nالمقدم: جزاكم الله خيراً. السؤال الأخير في هذه الحلقة سماحة الشيخ كما تفضلتم وبينتم أن طريق الدعوة طريق معين وله زاد معين، هذا الألم وتلكم الحسرة التي توقف الداعية في وسط الطريق، هل ترضونها من الداعية أم له توجيه معين؟\nالشيخ: لا يجوز أن يقف في الطريق بل الواجب أن لا ييأس وأن يكون واسع البال كثير الصبر حتى يدرك إن شاء الله ما أراد أو يموت على ذلك، هكذا يجب، الله يقول: وَلا تَيْئَسُوا مِنْ رَوْحِ اللَّهِ [يوسف:87] ويقول: لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ [الزمر:53] ويقول جل وعلا: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ [الزمر:53]، فالواجب على الداعي والآمر بالمعروف والناهي عن المنكر أن لا يقف في الطريق وأن لا ييأس وأن لا يقنط، بل يكون عنده حسن الظن بالله وعنده الرجاء وعنده الصبر العظيم؛ حتى يدرك مطلوبه أو يموت في الطريق، أما الوقوف فلا، ولهذا يقول الله عز وجل لنبيه ﷺ: وَاعْبُدْ رَبَّكَ حَتَّى يَأْتِيَكَ الْيَقِينُ[الحجر:99] وهو رسول الله، ويقول الله : يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ [آل عمران:102] فلابد من الصبر، ويقول سبحانه: إِنَّمَا يُوَفَّى الصَّابِرُونَ أَجْرَهُمْ بِغَيْرِ حِسَابٍ [الزمر:10] ويقول النبي ﷺ: ومن يتصبر يصبره الله، وما أعطي أحد عطاء خيراً وأوسع من الصبر فهذه نصيحتي لكل داعي ولكل مجاهد ولكل آمر بالمعروف وناه عن منكر ولكل مرشد ومعلم ولأشباههم النصيحة للجميع هو الاستمرار في الطريق الطيب والصبر على ذلك والصبر على الأشواك التي قد تؤذي، والصبر على كل ما قد يعوق عن الطريق أو يقف في الطريق من سائر العقبات حتى يبلغ المؤمن والداعي إلى الله مراده أو يموت دون ذلك والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/7560/حث-الدعاة-على-الصبر-وعدم-الياس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_158/15807.mp3","categories":["الدعوة والدعاة"]},{"id":9457,"question":"وهذه رسالة وردت إلى البرنامج من الأخ بخيت أحمد الأمين من السودان، يقول في رسالته: أريد منكم أن تفيدوني علمًا عن دعوة الإخوان المسلمين، وهل هناك اختلاف بين دعوتهم ودعوة جماعة أنصار السنة، أفيدونا أفادكم الله؟","title":"الفرق بين دعوة الإخوان المسلمين وجماعة أنصار السنة","answer":"الجواب: الإخوان المسلمون وأنصار السنة كلاهما من الدعاة إلى الله، وكلاهما نرجو لهما الخير، ولكن أنصار السنة فيما نعلم أنشط منهم في إيضاح التوحيد وبيان حقيقة الشرك، وأكثر منهم عناية بهذا الأمر، فكانوا معروفين في مصر وفي السودان بالعناية ببيان التوحيد والتحذير من الشرك والتعلق بالأموات والاستغاثة بأهل القبور.\nوأما الإخوان المسلمون فليس لهم نشاط واضح في بيان التوحيد وبيان عقيدة أهل السنة والجماعة ، وإنما دعوتهم عامة إلى الإسلام، وهذا لا يكفي، بل يجب على الإخوان المسلمين وعلى غيرهم من الدعاة أن يكون نشاطهم تفصيليًا، وأن يعنوا بالعقيدة الصحيحة، وأن يوضحوها للناس حتى يخرج مدعي الإسلام من عقيدة الكفر إلى العقيدة الصحيحة، فإنه قد يدعي الإسلام وقد يتكلم به ويصلي مع الناس وهو مع ذلك يعبد الأموات ويستغيث بـالبدوي أو بـالحسين أو بالشيخ عبدالقادر أو بفلان وفلان، ويسأله المدد والغوث إذا مر بقبورهم، وهذا كفر أكبر نعوذ بالله من ذلك، وقد يكون عندهم طريقة من طرق الصوفية خبيثة، فالواجب البيان والإيضاح.\nفـأنصار السنة في هذا الباب أنشط وأكمل للدعوة وأقوى في هذا الأمر، والإخوان المسلمون يمدحون على نشاطهم في الدعوة الإسلامية العامة، ويرجى لهم المزيد من التوفيق، لكن يؤخذ عليهم فيما بلغني وفيما أعلم يؤخذ عليهم عدم العناية بالتفصيل فيما يتعلق بالعقيدة وفيما يتعلق بالبدع التي يتعاطاها بعض الناس.\nفالواجب عليهم أن يغيروا من سيرتهم، وأن يجتهدوا في إيضاح العقيدة الصحيحة، وأن يدعوا إلى توحيد الله والإخلاص له، وينبهوا على دعوة الأموات والاستغاثة بهم وأنها شرك وكفر، وأن يوضحوا أيضًا الطرق الصوفية الخبيثة المنكرة التي في بلادهم، وأن الواجب على الناس جميعًا أن يتبعوا طريق النبي ﷺ ويسيروا على سيرته، وأن يحذروا الطرق الموجهة المخالفة لسيرته عليه الصلاة والسلام، وإن فعلها من فعلها من الأكابر، فإن العبرة بالحق لا بالناس، العبرة بالحق الذي جاء به المصطفى ﷺ ودرج عليه صحابته المرضيون، وإن كانوا ضعفاء وإن كانوا فقراء، ولا عبرة بمن خالف الحق وإن كانوا من الأكابر والرؤساء والعظماء والأغنياء، لا، لا ينبغي النظر إلى هذا، بل ينبغي النظر إلى العمل والحقيقة والعقيدة فيشجع أهل العقائد الصحيحة ويدعى لهم بالتوفيق، وينشطون على الثبات على ما هم عليه، ويدعى أهل العقائد المنحرفة وإن كانوا كبارًا لا يستحيا منهم ولا يداهنون، يدعون إلى الحق، ويوضح لهم ما هم فيه من الخطأ في العقيدة أو في الأخلاق أو في البدع التي يؤيدونها، هذا هو الواجب على أنصار السنة ، وعلى الإخوان المسلمين وعلى جميع الدعاة إلى الله جل وعلا الواجب عليهم أن ينصحوا لله ولعباده، وأن يوضحوا العقيدة الصحيحة، وأن يبينوا حقيقة التوحيد الذي دعت إليه الرسل عليهم الصلاة والسلام، وأن ينبهوا على الشرك الذي أنكرته الرسل وحذروا منه، وأن لا يداهنوا الناس في هذا الأمر، وأن لا يكون همهم كثرة الناس، لا، المهم وجود الحقيقة ولو كانوا قليلين، المهم أن تكون الدعوة صافية نقية، وأن يكون أهلها مستقيمين على الحق ثابتين عليه ولو كانوا قليلين، فالقليل مع الصدق والإخلاص أنفع بكثير من الكثيرين مع الضعف والجهل وقلة البصيرة أو قلة الصدق والإخلاص ولا حول ولا قوة إلا بالله. نعم.","link":"https://binbaz.org.sa/fatwas/7615/الفرق-بين-دعوة-الاخوان-المسلمين-وجماعة-انصار-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_191/19106.mp3","categories":["الدعوة والدعاة"]},{"id":9460,"question":"السؤال الثاني للمستمع (ر. ع. ف) سوداني مقيم في المملكة، يقول فيه: لي والد يشرب الخمر والعياذ بالله، ولقد تحدثت معه عدة مرات، وشرحت له بأن الدين يحرم ذلك، هذا بالإضافة إلى الأضرار المادية والمعنوية التي تلحق بنا، ولكن والدي لم يترك شرب الخمر حتى دخلت معه في جدال مرير، وهجرني وأمرني بالخروج عن منزله، وعلى هذا تركت المنزل، أفيدوني هل في عملي هذا مع والدي ما يخالف الدين الإسلامي؟","title":"رفق الولد في نصيحته لوالده","answer":"الجواب: النصيحة لوالدك حق، وهو من أولى الناس بنصيحتك، ومن أولى الناس بإحسانك في دينه ودنياه، ولكن ليس لك العنف والشدة حتى ولو كان كافرًا فكيف بمسلم يتعاطى بعض المعاصي؟!\nوالواجب عليك أن تصبر على ما تلقى من سوء خلقه، وأن تستمر في نصيحته، وأن تصله بالإحسان بالمال والمعروف، إن كنت قادرًا وهو ذو حاجة، وأن تدعو الله له بالليل والنهار والسر والجهار بالهداية والتوفيق حتى يترك ما هو عليه من تعاطي الخمر، ولا تنزع يدًا من طاعته ولا من الاتصال به، بل أحسن إليه واتصل به ولو هجرك، وتحبب إليه بالكلام الطيب والأسلوب الحسن؛ لعل الله يهديه بك، أما سمعت يقول : وَإِنْ جَاهَدَاكَ [لقمان:15] قبلها يقول: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14] ثم قال بعده: وَإِنْ جَاهَدَاكَ [لقمان:15] يعني: الوالدان الكافران، وَإِنْ جَاهَدَاكَ عَلى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا وَاتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَيَّ [لقمان:15] الآية.\nفأمر بأن يصاحبا في الدنيا معروفًا مع أنهما يجاهدان ولدهما على الشرك، ومع هذا يؤمر بالإحسان إليهما وشكرهما والصبر على ذلك، ويتبع سبيل الحق، هذا هو الواجب عليك مع الوالدين المشركين ومع العاصيين من باب أولى.\nفاتق الله يا أخي، وارجع إلى الإحسان إلى والدك، وانصح له وتحمل ما قد يقول لك من الكلام السيئ، وادع الله له بالهداية صادقًا في سجودك وبغير هذا من أحوالك، لعل الله يهديه بأسبابك، وأحسن إليه بالمال إن كان فقيرًا وأنت تقدر، وهذا كله فيه خير لك، ومما يرضي الله سبحانه وتعالى، والوالد ليس مثل الناس الآخرين، لا بل له شأن آخر، فاتق الله في والدك، وأحسن إليه وارجع إلى مناصحته والاستمرار في المشورة عليه لكن بالأسلوب الحسن لا بالعنف ولا بالشدة، بل: يا والدي! هداك الله، يا والدي هذا أمر خطير، يا والدي! هذا حرمه الله، يا والدي! هذا فيه من المضار كذا وكذا في الأوقات المناسبة، في الأوقات التي تراه أكثر قبولًا لنصحيتك، ثم استعن بالله على ذلك واسأله أن يهديه وأن يعينك عليه، وأن يشرح صدره للحق، وهكذا تستعين بمن له قدرة على مساعدتك من أقاربك ومن أصدقاء والدك، يأتون إليه وينصحونه بالأساليب الحسنة، ويساعدونك في هذا الخير العظيم.\nهذا هو الذي أنصحك به، وأسأل الله لك ولوالدك الهداية والتوفيق.","link":"https://binbaz.org.sa/fatwas/7618/رفق-الولد-في-نصيحته-لوالده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_191/19108.mp3","categories":["الدعوة والدعاة"]},{"id":9504,"question":"يسأل أيضاً ويقول: كيف تكون معاملة الجار إذا كان تاركاً للصلاة وغير ملتزم بتعاليم الدين الإسلامي الحنيف؟","title":"كيفية التعامل مع الجار التارك للصلاة","answer":"الجواب: ينصح ويُوجَّه إلى الخير، ويُعلَّم، وينكر عليه ما يفعل من التخلف عن الصلوات؛ لأن هذا شأن المؤمن، المؤمن أخو المؤمن ينصحه، ويأمره بالمعروف وينهاه عن المنكر، ويصبر على الأذى في ذلك، فإن نجح وهدى الله جاره فالحمد لله، وإلا استحق أن لا تجاب دعوته وأن لا يسلم عليه، وأن لا يرد عليه السلام من باب الإنكار؛ لأن هذا الهجر نوع من التعزير نوع من التأديب، ونوع من الإنكار إذا لم تنفع الموعظة والنصيحة، وإذا كان في البلد هيئة للأمر بالمعروف والنهي عن المنكر أو أمير صالح يعين على الخير يرفع بأمره إلى أولئك. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7673/كيفية-التعامل-مع-الجار-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_243/24307.mp3","categories":["الدعوة والدعاة"]},{"id":9548,"question":"وأولى رسائل هذه الحلقة وردت من المرسل عبدالقادر عبدالله موسى من السودان يقيم في الكويت، الأخ عبدالقادر يقول في رسالته: يوجد إمام مسجد في إحدى القرى من الذين يزورون القباب ويسألون أصحابها الأموات النفع وجلب المصالح، وكذلك يلبس الحجب ويتبرك بالحجارة التي على الأضرحة،  هل تجوز الصلاة خلفه وإذا كانت الإجابة بالنفي، فماذا نفعل مع العلم أن هناك..، يعني أنه ليس هناك مسجد آخر أفيدونا أفادكم الله؟","title":"حكم الصلاة خلف من يدعو الأموات ويتمسح بقبورهم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فمن شرط الإمامة أن يكون الإمام مسلماً، واختلف العلماء: هل يشترط أن يكون عدلاً أم تصح خلف الفاسق على قولين لأهل العلم، والصواب أنها تصح خلف الفاسق إذا كان مسلماً، ولكن لا ينبغي أن يولى مع وجود غيره، بل ينبغي لولاة الأمور أن يتحروا في الإمام أن يكون مسلماً عدلاً طيب السيرة حسن العمل؛ لأنه يقتدى به، أما من كان يزور القبور ليدعو أهلها من دون الله ليستغيث بهم ليتمسح بقبورهم، ليسألهم شفاء المرضى والنصر على الأعداء فهذا ليس بمسلم، هذا مشرك لأن دعاء الأموات والاستغاثة بالأموات والنذر لهم من أنواع الكفر بالله، فلا يجوز أن يتخذ إماماً ولا أن يصلى خلفه، وإذا لم يجد المسلمون مسجداً آخر صلوا قبله أو بعده، صلوا في المسجد الذي يصلي فيه لكن بعده أو قبله، فإن تيسر عزله، وجب عزله، وإن لم يتيسر فإن المسلمين ينتظرون صلاة هؤلاء ثم يصلون بعدهم، أو يتقدمونهم إذا دخل الوقت ويصلون قبلهم إذا أمكن ذلك، فإن لم يمكنهم صلوا في بيوتهم: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].\nوينبغي أن يعلم هذا الإمام ويرشد إلى الحق لأنه في حاجة إلى الدعوة إلى الله، والمسلم ينصح للمسلمين وينصح لغيرهم يدعو إلى الله، كما ثبت عن النبي صلى الله عليه وسلم أنه قال لـعلي  لما بعثه إلى خيبر: فوالله لأن يهدي الله بك رجلاً واحداً خير لك من حمر النعم، وقال عليه الصلاة والسلام: من دل على خير فله مثل أجر فاعله، والله يقول سبحانه: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ [فصلت:33]، وقال سبحانه: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ أَنَا وَمَنِ اتَّبَعَنِي [يوسف:108] الآية، وقال سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]، فهذا الإمام يدعى إلى الله، يوجه إلى الخير، يعلم أن عمله باطل وأنه شرك بالأساليب الحسنة، بالرفق والحكمة، لعله يهتدي، لعله يقبل الحق، فإن لم يتيسر ذلك فيتصل بالمسئول عن المسجد من أوقاف، أو غير أوقاف ويبين لهم أن هذا الإمام لا يصلح، وأن الواجب عزله وأن يولى في المسجد رجل موحد مؤمن مسلم حتى لا يتفرق الناس عن المسجد وحتى لا يصلي بهم إنسان كافر، هذا هو الواجب على المسلمين أن يتعاونوا في هذا الخير وأن ينصحوا لولاة الأمور، وأن ينصحوا لهذا الإمام الجاهل لعله يهتدي. نعم.\nالمقدم: بارك الله فيكم، وجزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7702/حكم-الصلاة-خلف-من-يدعو-الاموات-ويتمسح-بقبورهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_246/24601.mp3","categories":["صلاة الجماعة","الدعوة والدعاة"]},{"id":9616,"question":"الرسالة التالية وصلت من المستمع عبدالله سلام العمراني من المنطقة الشمالية لمدينة البدع يقول الأخ عبدالله في رسالته:هل يقصد بقول الله تعالى: هَلْ يَسْتَوِي الَّذِينَ يَعْلَمُونَ وَالَّذِينَ لا يَعْلَمُونَ [الزمر:9] وقوله ﷺ: العلماء ورثة الأنبياء علماء الطب أو الكيمياء أو غيرهم أم يقصد فقط علماء الشريعة أفيدونا حفظكم الله ورعاكم؟","title":"علماء الشريعة هم المعنيون بكلام الله ورسوله","answer":"الجواب: المقصود بالآيات التي في العلم أو الأحاديث التي في العلم كلها عند أهل العلم كتب الشريعة؛ علوم الكتاب والسنة هي التي فيها الفضل العظيم والخير الكثير، وأما ما يتعلق بعلوم الطب والهندسة والاختراع والجيولوجيا وأشباه ذلك علوم لها أهلها وعلى حسب مقاصدهم تكون حكمهم؛ فمن تعلم الهندسة أو الطب لينفع المسلمين وأن يغنيهم عن أعدائهم فهذا مأجور على حسب نيته، وهكذا من تعلم اختراع شيء من آلات الحرب لينفع المسلمين أو تعلم الجيولوجيا أو شبه ذلك لينفع المسلمين قصده نفع المسلمين فهذا له أجره، ولا يكون حكمه حكم علماء الشريعة لكن يكون له أجر على نيته، أما من تعلمه للدنيا ومقاصد الدنيا؛ ليأكل يتوظف يعيش فهذا مباح لا له ولا عليه، لأنه مأمور بالكسب مأمور بطلب الرزق لكن ما يكون كمن تعلمها ليأكل الحلال ويستغني عن الحاجة إلى الناس أو ينفع المسلمين ليغنيهم عن أعدائهم هذه النية تختلف، فمن تعلمها لنفع المسلمين فله أجر ومن تعلمها ليستغني بها عن الحرام ويكسب الحلال فله أجر، ومن تعلمها لا لقصد إلا لمجرد ليعيش ويأكل ويشرب ما همه حلال ولا غيره ولا همه نفع المسلمين ولا غيرهم وإنما تعلمها لمصالحه الدنيوية فقط الدنيوية فقط فهذا ...... أنه مباح فقط. نعم.","link":"https://binbaz.org.sa/fatwas/7774/علماء-الشريعة-هم-المعنيون-بكلام-الله-ورسوله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_193/19312.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9712,"question":"هذه رسالة وصلت إلى البرنامج من المستمع عبدالسلام عبدالله محمد من الجمهورية العربية اليمنية من لواء تعز، الرسالة تحمل سؤالين: يقول الأخ عبدالسلام في سؤاله الأول: لي عم أخ لأبي منفرد عن الأسرة وله متجر بجانب متجره والجامع قريب منا ونسمع الأذان معًا في كل وقت ولكنه لا يذهب إلى الصلاة ولا يصل الرحم، وفوق هذا فهو يختلي بامرأة أجنبية غريبة عنه وفي منزل آخر غير منزله، والإسلام يدعو للنصيحة لقول الرسول ﷺ: إنما الدين النصيحة، فأنا أكره أعماله هذه وأكره أن أتكلم معه ولا أرد عليه السلام علمًا بأنه جاري في الدكان كما ذكرت، فهل علي إثم بهذا أفتونا مأجورين وجزاكم الله خير الجزاء؟","title":"دورنا تجاه من يتهاون في الصلاة ويختلي بالأجنبية","answer":"الجواب: الواجب عليك النصيحة مثل ما فعلت، تنصح له وترشده إلى الخير وتخوفه من الله  وتقول له: يا فلان! اتق الله، عليك أن تؤدي الصلاة في الجماعة أنت تسمع النداء، والرسول عليه السلام يقول: من سمع النداء فلم يأت فلا صلاة له إلا من عذر، وقد جاءه رجل أعمى فقال: يا رسول الله! ليس لي قائد يلائمني إلى المسجد فهل لي من رخصة أن أصلي في بيتي؟ فقال له النبي عليه الصلاة والسلام: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب، فلم يرخص له في ترك الجماعة وهو كفيف ليس له قائد يلائمه فكيف بحال البصير المعافى ؟ تنصح له وتبين له ما جاءت به السنة، وكذلك قطيعته للرحم تنصح له فيها وهكذا خلوته بالأجنبية تنصحه وتنكر عليه، فإذا أصر على المخالفة والعناد فهجره حق هجره حق وأنت مصيب في هجره؛ لأنه قد تظاهر بالمعصية ومن تظاهر بها ولم يقبل النصيحة استحق أن يهجر. نعم.","link":"https://binbaz.org.sa/fatwas/7864/دورنا-تجاه-من-يتهاون-في-الصلاة-ويختلي-بالاجنبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_195/19504.mp3","categories":["الدعوة والدعاة"]},{"id":9742,"question":"أولى رسائل هذه الحلقة وردت من المستمع (ف. ع. م. ص) يقول في رسالته: أنا رجل متزوج وبعد زواجي بحوالي ست سنوات، سافرت إلى بلد أخرى من أجل السعي والبحث عن الرزق، وكنت أصلي وأصوم ولله الحمد، ولكن لعب بي الشيطان ومارست العادة السرية؛ لأنني بعيد عن زوجتي، وبعد هذا قلت: هذا عمل حرام ولا بد أن أتركه، فبدأت أصلي وأصوم وقلت: حلفت علي الطلاق بالثلاث لا أفعل هذا العمل مرة ثانية، وكانت نيتي الطلاق، وبعد فترة لعب بي الشيطان مرة ثانية فوقعت في هذا الأمر، ثم رجعت عنه، ف هل هذا الطلاق واقع علي أم لا، مع العلم أن زوجتي لم تسمعه، أفيدوني أفادكم الله؟","title":"حكم الحلف بالطلاق مع قصد الطلاق","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن العادة السرية التي يعتادها بعض الناس محرمة، وفيها أضرار كثيرة وهي الاستمناء، وقد قال الله عز وجل في وصف المؤمنين: وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ ۝ إِلَّا عَلَى أَزْوَاجِهِمْ أوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ ۝ فَمَنِ ابْتَغَى وَرَاءَ ذَلِكَ فَأُوْلَئِكَ هُمُ الْعَادُونَ [المؤمنون:5-7].\nوهذه العادة الخبيثة هي غير ما أباح الله من إتيان الزوجة والسرية، فتكون محرمة وتكون من العدوان الذي بينه الله سبحانه في هذه الآية، قد بين الأطباء العارفون بهذه العادة مضرتها العظيمة وشرها الكثير.\nفالواجب على كل مؤمن أن يحذرها غاية الحذر.\nأما ما ذكره السائل من تعليقه الطلاق على العودة، فإذا كان يقصد مثل ما قال: إيقاع الطلاق، فإنه يقع طلقة واحدة؛ لعوده إليها؛ لأنه طلاق معلق على شرط يقصد منه الوقوع فوقعت بذلك طلقة واحدة على الصحيح؛ لأنه ثبت من حديث ابن عباس رضي الله عنهما عن النبي ﷺ ما يدل أن إيقاع الثلاث بلفظ واحد يعتبر طلقة واحدة.\nولك أيها السائل! مراجعتها بعدما عاودت هذه العادة الخبيثة؛ لأنه طلاق رجعي.\nأما إذا كنت لم تطلقها قبل هذا طلقتين، أما إن كنت طلقتها قبلها طلقتين فهذه تكون الثالثة ولا رجعة، نسأل الله للجميع الهداية.\nالمقدم: وبالنسبة سماحة الشيخ لما قاله: بأن زوجته لم تسمع هذا الطلاق؟\nالشيخ: ولو ما سمعت، ماله تعلق، سماعها وعدم سماعها سواء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7908/حكم-الحلف-بالطلاق-مع-قصد-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25601.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة","الدعوة والدعاة"]},{"id":9879,"question":"يقول أيضاً قرأت في كتيب صغير اسمه: الحصن الحصين من كلام رب العالمين، أن من يقرأ هذه الآية لا يموت في يومه وفيه سبع آيات يقول عنها إنها المنجيات ثم ذكر بسم الله الرحمن الرحيم: لَقَدْ جَاءَكُمْ رَسُولٌ مِنْ أَنفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُمْ بِالْمُؤْمِنِينَ رَءُوفٌ رَحِيمٌ [التوبة:128] إلى آخر الآية، فما حكم ذلك؟","title":"التعريف بما يحويه كتيب الحصن الحصين","answer":"الجواب: ليس بصحيح، هذا ليس بصحيح، والحصن الحصين يجمع أحاديث ضعيفة وأحاديث غير صحيحة، فلا يعتمد على ما يذكر بل لا بد من المراجعة، مراجعة الأحاديث في كتب الأصول ومراجعة كلام أهل العلم فيها، حتى يعلم طالب العلم صحتها. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8053/التعريف-بما-يحويه-كتيب-الحصن-الحصين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_264/26410.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9902,"question":"نختم هذه الرسالة بهذا السؤال، يقول السائل: سماحة الشيخ كيف يكون البر بالأقارب وإذا كانوا هؤلاء الأقارب من المتساهلين في الشرع ، وأصحاب بدع، فهل يجوز لي أن أقاطعهم ما داموا على هذه الصفة؟ جزاكم الله خيرًا.","title":"حكم صلة الأقارب إذا كان لديهم معاصٍ أو بدع","answer":"الجواب: تعمل بالأصلح، إذا كانت الزيارة والسلام عليهم فيها فائدة بإزالة المنكر، وإسداء المعروف فافعل ذلك، وإن كانت الزيارة لا تؤثر شيئًا، والمنكرات ظاهرة فهم يستحقون الهجر، سنة، لكن إذا رجوت أن ينفع الله بزيارتك فإنك تزورهم وتنصحهم وتوجههم إلى الخير ، يقول ﷺ في الحديث الصحيح: لأن يهدي الله بك رجلًا واحداً خير لك من حمر النعم ويقول ﷺ: من دل على خير فله مثل أجر فاعلهفأنت على خير، إذا طمعت في هدايتهم فافعل، نعم.","link":"https://binbaz.org.sa/fatwas/8070/حكم-صلة-الاقارب-اذا-كان-لديهم-معاص-او-بدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27314.mp3","categories":["الدعوة والدعاة"]},{"id":9946,"question":"هذا السائل محمد علوي قايد يماني الجنسية يسأل أيضاً ويقول: لي أخ من أبي وأمي لا يصلي وقد نصحته وبينت له ما وعد الله به قاطع الصلاة في الدنيا وفي الآخرة، وما يحل به من عذاب في القبر ولم يستجب للنداء، وقد أمضى معي في الغربة حوالي أربع سنوات وأنا أنصحه ولكن بدون فائدة، و هل يجوز لي مقاطعته؟ وهل يجوز رد السلام عليه؟ وهل إذا قاطعته وكانت هذه المقاطعة سبب في غضب والدتي علي، هل علي في ذلك إثم؟ ويسأل عن الأكل والشرب معه إلى آخره؟","title":"حكم مقاطعة الأخ التارك للصلاة بعد نصحه","answer":"الجواب: قد أحسنت في نصيحته والاستمرار في ذلك، أما كونه استمر في مقاطعة الصلاة ولم يوفق لقبول النصيحة، فهذا إلى الله  هو الذي يهدي من يشاء ويضل من يشاء، فعليك أن تدعو له كثيراً بالهداية وهكذا الوالدة تدعو له بالهداية: أن الله يهديه ويرده إلى الصواب، في السجود في آخر الصلاة، في أوقات الإجابة مثل: آخر الليل مثل: بين الأذان والإقامة لعل الله يهديه ولعل الله يستجيب دعاءك ودعاء الوالدة، أما المقاطعة فالواجب مقاطعته ما دام لم يقبل فالواجب هجره ومقاطعته، لعله يستفيد من هذا الهجر ولعل الله يهديه بذلك، ولا تتخذه جليساً يكون أكيلك أو شريبك ولا تجب دعوته إذا كان في بيت آخر إذا دعاك، بل تظهر له المقاطعة والبغضاء حتى يهديه الله عز وجل، وهكذا الوالدة عليها أن تنكر عليه وعليها أن تبغضه في الله، وعليها أن تقاطعه حتى يهديه الله؛ لأن ترك الصلاة كفر أكبر في الصحيح من قولي العلماء، يقول النبي ﷺ: رأس الأمر الإسلام وعموده الصلاة ويقول النبي أيضاً عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، ويقول عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة فالصلاة عمود الإسلام من أضاعها أضاع دينه نسأل الله العافية. ويقول النبي ﷺ لما ذكر الصلاة يوماً قال: من حافظ عليها كانت له نوراً وبرهاناً ونجاة يوم القيامة، ومن لم يحافظ عليها لم يكن له نور ولا برهان ولا نجاة، وحشر يوم القيامة مع فرعون وهامان وقارون وأبي بن خلف وهؤلاء من صناديد الكفار ومن أخبث الكفار. فبين ﷺ أن من ضيع الصلاة يحشر مع هؤلاء الكفرة نسأل الله العافية، فالمقصود أن الواجب عليك وعلى الوالدة النصيحة وقد بذلت منك النصيحة، وعلى الوالدة أن تبذل النصيحة وبعد ذلك لا بد من مقاطعة ولا بد من إعلان البغضاء له، حتى يعرف أنكما تبغضانه في الله وأنكما تقاطعانه في هذا الأمر، لعل الله يهديه ويمن عليه بالتوبة ولا مانع من النصيحة بعد ذلك بين وقت وآخر بالكلام أو بالتلفون أو بالبرقيات والكتابة أو نحو ذلك لا مانع أن يستمر المؤمن في النصيحة، لكن مع البغضاء في الله ومع الهجر في الله، كما قال الله : قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِي إِبْرَاهِيمَ وَالَّذِينَ مَعَهُ إِذْ قَالُوا لِقَوْمِهِمْ إِنَّا بُرَآءُ مِنْكُمْ وَمِمَّا تَعْبُدُونَ مِنْ دُونِ اللَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ الْعَدَاوَةُ وَالْبَغْضَاءُ أَبَدًا حَتَّى تُؤْمِنُوا بِاللَّهِ وَحْدَهُ [الممتحنة:4] فترك الصلاة كفر وضلال نسأل الله العافية، نسأل الله له الهداية ونسأل الله أن يعينك والوالدة على كل خير، وأن ينفع بنصيحتكما وأن يقبل دعواتكما له حتى يهديه الله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8117/حكم-مقاطعة-الاخ-التارك-للصلاة-بعد-نصحه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_267/26709.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":9950,"question":"هذا السائل محمد علوي قايد يماني الجنسية يسأل أيضاً ويقول: لي أخ من أبي وأمي لا يصلي وقد نصحته وبينت له ما وعد الله به قاطع الصلاة في الدنيا وفي الآخرة، وما يحل به من عذاب في القبر ولم يستجب للنداء، وقد أمضى معي في الغربة حوالي أربع سنوات وأنا أنصحه ولكن بدون فائدة، و هل يجوز لي مقاطعته؟ وهل يجوز رد السلام عليه؟ وهل إذا قاطعته وكانت هذه المقاطعة سبب في غضب والدتي علي، هل علي في ذلك إثم؟ ويسأل عن الأكل والشرب معه إلى آخره؟","title":"حكم مقاطعة الأخ التارك للصلاة بعد نصحه","answer":"الجواب: قد أحسنت في نصيحته والاستمرار في ذلك، أما كونه استمر في مقاطعة الصلاة ولم يوفق لقبول النصيحة، فهذا إلى الله  هو الذي يهدي من يشاء ويضل من يشاء، فعليك أن تدعو له كثيراً بالهداية وهكذا الوالدة تدعو له بالهداية: أن الله يهديه ويرده إلى الصواب، في السجود في آخر الصلاة، في أوقات الإجابة مثل: آخر الليل مثل: بين الأذان والإقامة لعل الله يهديه ولعل الله يستجيب دعاءك ودعاء الوالدة، أما المقاطعة فالواجب مقاطعته ما دام لم يقبل فالواجب هجره ومقاطعته، لعله يستفيد من هذا الهجر ولعل الله يهديه بذلك، ولا تتخذه جليساً يكون أكيلك أو شريبك ولا تجب دعوته إذا كان في بيت آخر إذا دعاك، بل تظهر له المقاطعة والبغضاء حتى يهديه الله عز وجل، وهكذا الوالدة عليها أن تنكر عليه وعليها أن تبغضه في الله، وعليها أن تقاطعه حتى يهديه الله؛ لأن ترك الصلاة كفر أكبر في الصحيح من قولي العلماء، يقول النبي ﷺ: رأس الأمر الإسلام وعموده الصلاة ويقول النبي أيضاً عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، ويقول عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة فالصلاة عمود الإسلام من أضاعها أضاع دينه نسأل الله العافية. ويقول النبي ﷺ لما ذكر الصلاة يوماً قال: من حافظ عليها كانت له نوراً وبرهاناً ونجاة يوم القيامة، ومن لم يحافظ عليها لم يكن له نور ولا برهان ولا نجاة، وحشر يوم القيامة مع فرعون وهامان وقارون وأبي بن خلف وهؤلاء من صناديد الكفار ومن أخبث الكفار. فبين ﷺ أن من ضيع الصلاة يحشر مع هؤلاء الكفرة نسأل الله العافية، فالمقصود أن الواجب عليك وعلى الوالدة النصيحة وقد بذلت منك النصيحة، وعلى الوالدة أن تبذل النصيحة وبعد ذلك لا بد من مقاطعة ولا بد من إعلان البغضاء له، حتى يعرف أنكما تبغضانه في الله وأنكما تقاطعانه في هذا الأمر، لعل الله يهديه ويمن عليه بالتوبة ولا مانع من النصيحة بعد ذلك بين وقت وآخر بالكلام أو بالتلفون أو بالبرقيات والكتابة أو نحو ذلك لا مانع أن يستمر المؤمن في النصيحة، لكن مع البغضاء في الله ومع الهجر في الله، كما قال الله : قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِي إِبْرَاهِيمَ وَالَّذِينَ مَعَهُ إِذْ قَالُوا لِقَوْمِهِمْ إِنَّا بُرَآءُ مِنْكُمْ وَمِمَّا تَعْبُدُونَ مِنْ دُونِ اللَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ الْعَدَاوَةُ وَالْبَغْضَاءُ أَبَدًا حَتَّى تُؤْمِنُوا بِاللَّهِ وَحْدَهُ [الممتحنة:4] فترك الصلاة كفر وضلال نسأل الله العافية، نسأل الله له الهداية ونسأل الله أن يعينك والوالدة على كل خير، وأن ينفع بنصيحتكما وأن يقبل دعواتكما له حتى يهديه الله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8117/حكم-مقاطعة-الاخ-التارك-للصلاة-بعد-نصحه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_267/26709.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":9989,"question":"له سؤال ثالث أيضًا يقول فيه: وردت الأدلة على الأجر في قراءة القرآن الكريم، فهل هناك أجر في قراءة الأحاديث النبوية أفيدونا بارك الله فيكم؟","title":"فضل تعلم كتاب الله وسنة رسوله","answer":"الجواب: نعم، قراءة العلم كلها فيها أجر، تعلم العلم وطلب العلم من طريق القرآن من طريق السنة فيها أجر عظيم، فالعلم يؤخذ من الكتاب ويؤخذ من السنة، يقول النبي ﷺ: خيركم من تعلم القرآن وعلمه، وجاء في قراءة القرآن أحاديث كثيرة، منها قوله ﷺ: اقرءوا القرآن فإنه يأتي شفيعاً لأصحابه يوم القيامة رواه مسلم ، وقال ذات يوم عليه الصلاة والسلام: أيحب أحدكم أنن يذهب إلى بطحان -وادٍ في المدينة يقال له: بطحان- فيأتي بناقتين عظيمتين في غير إثم ولا قطيعة رحم؟ فقالوا: كلنا يحب ذلك يا رسولل الله! قال: لأن يذهب أحدكم إلى المسجد فيتعلم آيتين من كتاب الله خير له من ناقتين عظيمتين وثلاث خير من ثلاث، ومن أربع ومن أعدادهن من الإبل أو كما قال عليه الصلاة والسلام، فهذا يدل على فضل تعلم القرآن وقراءة القرآن، حديث ابن مسعود: من قرأ حرفًا من القرآن فله حسنة والحسنة بعشر أمثالها، هكذا السنة إذا تعلمها المؤمن، قرأ الأحاديث ودرسها يكون له أجر عظيم لأن هذا من تعلم العلم، يقول النبي ﷺ: من سلك طريقًا يلتمس فيه علمًا سهل الله له به طريقًا إلى الجنة، فهذا يدل على أن دراسة العلم وحفظ الأحاديث والمذاكرة فيها من أسباب دخول الجنة والنجاة من النار، هكذا قوله ﷺ: من يرد الله به خيرًا يفقهه في الدين متفق عليه، فالتفقه في الدين يكون من طريق الكتاب ويكون من طريق السنة، فالتفقه في السنة من الدلائل على أن الله أراد بالعبد خيراً، كما أن التفقه في القرآن دليل على ذلك، والأدلة في هذا كثيرة والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8157/فضل-تعلم-كتاب-الله-وسنة-رسوله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_275/27503.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9991,"question":"تسأل أختنا مع من يسأل عن كتاب رياض الصالحين؟","title":"التعريف بكتاب رياض الصالحين","answer":"الجواب: رياض الصالحين كتاب عظيم نفع الله به الأمة، والظاهر -والله أعلم- أن مؤلفه ألفه عن نية صالحة رحمة الله عليه، وعن قصد صالح ولعله سأل الله  فأجاب الله دعوته أن ينفع به العباد فنفع الله به العباد، فكل بلاد تستعمل هذا الكتاب فيما بلغنا يدرسونه في البيوت وفي المساجد وينتفع به الناس، فهو كتاب عظيم والحديث الضعيف فيه قليل، فهو كتاب ننصح بقرءاته في المساجد وفي المجالس لما فيه من الفائدة الكبيرة، نسأل الله أن يعفو عن مؤلفه وأن يضاعف مثوبته وأن ينفع بهذا الكتاب المسلمين كما نفع به سابقاً. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8170/التعريف-بكتاب-رياض-الصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_300/30007.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":9994,"question":"أيضاً تسأل عن كتاب الدعاء المستجاب ودعاء الرسول ﷺ؟","title":"التعريف بكتاب الدعاء المستجاب","answer":"الجواب: كتاب الدعاء المستجاب كتاب فيه أحاديث ضعيفة وموضوعة لا ننصح به، بل ننصح بتركه وعدم الاعتماد عليه. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8171/التعريف-بكتاب-الدعاء-المستجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_300/30008.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10035,"question":"يقول: ماذا أفعل مع بعض أفراد البيت الذين لا يصلون، مثل أخي أو زوجة أخي أو أخي زوجتي؟ ماذا أفعل تجاههم إذا لم تنفع فيهم النصيحة؟","title":"ما يفعل من ابتُلي بأقارب لا يصلون","answer":"الجواب: الواجب الاستمرار في النصيحة وأن تنصحهم لأن الصلاة عمود الإسلام من تركها كفر نعوذ بالله من ذلك، فالواجب أن تنصح لهم وأن تجتهد في ذلك حسب الطاقة ولا تضعف ولا تدع النصيحة ولعل الله أن يهديهم بأسبابك، والذي لا يقبل ويعني قد تابعت النصيحة ولم يقبل يستحق أن يهجر حتى لا يسلم عليه ولا يرد عليه السلام ولا تقبل دعوته للطعام ولا يدعى للطعام، يستحق أن يهجر لأن الصلاة عمود الإسلام من تركها كفر نعوذ بالله من ذلك.\nفالواجب عليك أن تناصحهم وأن تستمر في النصيحة والذي لا يقبل النصيحة ويستمر في باطله يستحق أن يهجر، وإذا كنت تستطيع أن تؤدبه لكونه زوجة أو ولد أدبته حتى يستقيم حتى يصلي وحتى تصلي وتقوم بالواجب، وأما زوجة أخيك أو زوجة أبيك أو نحوهما ممن لا تستطيع تأديبه فهذا على أخيك وعلى أبيك أن يقوما بالواجب، على أخيك أن يؤدب زوجته حتى تستقيم وحتى تصلي، وعلى أبيك كذلك وهكذا عمك وهكذا جيرانك تنصحهم وتدعوهم إلى القوة في هذا الأمر، والنشاط في هذا الأمر لعل الله يهديهم بأسباب النشاط والقوة والتوجيه والتأديب من الزوج لزوجته تأديباً ينفعها ويعينها على طاعة الله ولا يسبب خطراً، والله جل وعلا أمر بالتعاون على البر والتقوى قال سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] وقال جل وعلا: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71].\nهذا من باب الأمر بالمعروف والنهي عن المنكر، وقال سبحانه: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3].\nالتواصي بالحق والتناصح أمر واجب أمر لازم، وهكذا الأمر بالمعروف والنهي عن المنكر أمر لازم مع الزوجة مع زوجة الأب مع زوجة الأخ مع الأخوات، مع البنات، لكن من تستطيع تأديبها تأدبها كالزوجة والبنت والولد تؤدب الجميع أدباً يردعهن عن، يردع الزوجة عن التساهل بالصلاة، يردع الولد يردع البنت، كما قال النبي ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر.\nفالأولاد يضربون إذا تخلفوا عن الصلاة وهم أبناء عشر يضربون على ذلك، سواءً كانوا ذكوراً أو إناثاً لأن هذا مما يعينهم على طاعة الله ومما يسبب لهم المبادرة إلى الحق، فعلى وليهم أن يأمرهم بذلك ويضرب من بلغ عشراً على ذلك ضرباً غير مبرح ضرباً يعينهم على طاعة الله، ضرباً يشجعهم على الخير ولا يكون فيه خطر.\nوهكذا له أن يضرب المرأة يؤدبها إذا تساهلت وإذا خاف نشوزها ضربها فكيف إذا تركت الصلاة، ترك الصلاة أعظم فإذا لم يجد فيها النصح والتوجيه والدعوة إلى الخير فله أن يضربها ويؤدبها ضرباً غير مبرح، حتى تصلي حتى تقوم بهذا الواجب العظيم، فإن أصرت ولم تستقم وجب فراقها لأن من ترك الصلاة كفر، ترك الصلاة كفر أكبر نعوذ بالله من ذلك، فالتي لا تصلي تكون كافرة -نعوذ بالله- يجب فراقها بالكلية، وهكذا الزوج الذي لا يصلي وامرأته تصلي لا تبقى معه بل يجب أن تفارقه وأن تطلب الطلاق لأنه لا يجوز بقاؤها معه وهو لا يصلي، يقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، ولقوله عليه الصلاة والسلام: رأس الأمر الإسلام وعموده الصلاة.\nفالحاصل أن الصلاة أمرها عظيم وهي عمود الإسلام، فلابد من التأديب عليها من الزوج لزوجته من الوالد لولده والأخ لأخيه الذي الصغير حتى يستقيموا على الصلاة، حتى ولو كانوا دون البلوغ كابن عشر وثنتي عشرة من الأولاد والإخوة، يؤدبون ويعلمون ويوجهون للخير، والزوجة يجب أن تؤدب على هذا الأمر العظيم حتى تستقيم حتى تحافظ على الصلاة، فإذا أصرت على ترك الصلاة فحينئذ يجب أن يفارقها، كما أنه إذا أصر زوجها على ترك الصلاة يجب أن تتركه وتذهب إلى أهلها حتى يتوب توبة صادقة أو يفرق بينهما الحاكم الشرعي، نسأل الله للجميع الهداية، ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8199/ما-يفعل-من-ابتلي-باقارب-لا-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_301/30103.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":10042,"question":"أرجو من سماحتكم إرشادي إلى الكتب الموثوق بها في كل من الموضوعات التالية: العقيدة؟","title":"كتب ينصح بقراءتها في العقيدة","answer":"الجواب: أعظم كتاب وأشرف كتاب وأصدق كتاب في العقيدة وغيرها كتاب الله القرآن، فعليك بكتاب الله أكثر من تلاوته تدبر معانيه وحفظ ما تيسر منه والمذاكرة مع زملائك ومع أستاذك في ذلك حتى تستفيد العلم العظيم، قال تعالى في كتابه العظيم: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] قال سبحانه: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44] وقال: وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ [الأنعام:155] فهو كتاب الله العظيم فيه الهدى والنور والشفاء، فالزم كتاب ربك وأكثر من تلاوته وتدبر معانيه أَفَلا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا [محمد:24].\nثم كتب الحديث الشريف كالصحيحين فإنهما أعظم كتاب بعد القرآن، إذا كنت طالب علم تعتني بالصحيحين تطالعهما وتقرأ فيهما وتذاكر فيهما مع الأساتذة ومع الزملاء وهكذا بقية السنن الأربع كـأبي داود والترمذي والنسائي وابن ماجة ومسند أحمد وسنن الدارمي، هذه كتب مفيدة عظيمة إذا كنت تستطيع أن تقرأ فيها وأن تستفيد منها، ولكن أعظمها الصحيحان، ومثل رياض الصالحين كتاب مفيد جيد، بلوغ المرام تستفيد منه تحفظه إذا تيسر للحافظ ابن حجر، عمدة الحديث للعلامة الحافظ عبدالغني بن عبدالواحد المقدسي كتاب عظيم مفيد في الحديث.\nوفي العقيدة: العقيدة الواسطية.. التدمرية.. الحموية.. كتاب التوحيد للشيخ محمد بن عبدالوهاب رحمه الله ثلاثة الأصول، كشف الشبهات، كل هذه كتب مفيدة، لمعة الاعتقاد للموفق ابن قدامة رحمه الله، الطحاوية كتاب جيد وإن كان فيه مواضع قليلة قد علقنا عليها ووضح أيضًا ما فيها شارح الطحاوية ابن أبي العز كل هذه كتب طيبة وشرح ابن أبي العز للطحاوية كتاب جيد أيضًا، وهكذا كتب ابن القيم الصواعق المرسلة، اجتماع الجيوش الإسلامية، زاد المعاد، حادي الأرواح.. كل هذه كتب مفيدة في العقيدة وغيرها.\nوهكذا كتب شيخ الإسلام ابن تيمية رحمه الله الفتاوى المعروفة وهكذا كتاب الإيمان له أيضًا مع ما تقدم من كتبه الثلاثة التدمرية.. الحموية.. العقيدة الواسطية.. كل هذه كتب عظيمة مفيدة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8211/كتب-ينصح-بقراءتها-في-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_332/33210.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10081,"question":"المستمع سالم محمد سالم من جمهورية مصر العربية سوهاج بعث يقول: أنا أقوم بتحذير ونصح أهلي وبعض المسلمين من الانزلاق في البدع والخرافات، كزيارة أهل الأضرحة وذهاب النساء إلى القبور وإقامة بدعة المأتم كاستئجار المقرئين للميت، ثم جاءني بعض الطلبة وقال: إنك تقوم بما يقوم به المفتي، والرسول عليه أفضل الصلاة والسلام يقول: أجرؤكم في الفتوى أجرؤكم على النار، أو كما ورد عن الرسول ﷺ، هل صحيح ما قاله صاحبي جزاكم الله خيراً؟","title":"حكم من نهى عن نصح الناس لحديث: «أجرؤكم على الفتيا»","answer":"الجواب: الواجب على المسلم أن يدعو إلى الله  وأن يوضح لإخوانه المسلمين ما يجب عليهم وما يحرم عليهم، وأن يأمرهم بالمعروف وينهاهم عن المنكر إذا كان عنده علم وعنده بصيرة؛ لأن الله أمر بهذا أمر عباده المسلمين بالدعوة إلى الله، وأمرهم بالأمر بالمعروف والنهي عن المنكر، وأمرهم بالتعاون على البر والتقوى، قال الله : وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، وقال سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَر [التوبة:71]، قال : ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]، فإذا كان عند المسلم أو المسلمة علم وبصيرة فإن عليهما الدعوة إلى الله، وتبصير الناس بما يجب عليهم وما يحرم عليهم، كما يدعون إلى الله الكفار ويرشدونهم إلى دين الإسلام ويوضحون لهم محاسنه وأحكامه.\nفهكذا مع إخوانه المسلمين يدعونهم إلى الله الرجال والنساء يدعونهم إلى الله وينصحونهم ويوجهونهم إلى الخير، وأعظم ذلك ما يتعلق بالكفر والشرك والعقيدة، كونه ينصح عباد القبور الذين يدعون الموتى ويعكفون على الأضرحة ويسألون الميت قضاء الحاجة أو شفاء المريض أو رد الغائب أو ما أشبه ذلك، يعني هذا من الكفر بالله هذا من عبادة الأوثان وهذا من شرك الجاهلية، وهكذا زيارة القبور للنساء والرسول ﷺ نهى عن زيارة القبور للنساء ولعن زائرات القبور، فإذا نصحهم لله وقال: هذا لا يجوز لكن، لا تزوروا القبور فقد أحسن، وهكذا النهي عن زيارة أهل البدع والعمل بما يقولون، إلا إذا كانوا يزوروهم لينصحهم ليدعوهم إلى الله ويعلمهم شر ما هم عليه من البدع إذا كان عنده علم، فهذا مأجور هذا من الجهاد في سبيل الله، كونه يأمر المعروف وينهى عن المنكر ويزور أهل البدع للدعوة إلى الله وتعليمهم الحق وإنكار البدعة عليهم بالطرق المناسبة لعل الله أن يهديهم على يديه، هذا مأجور وهذا من الجهاد في سبيل الله، والذي ينهاهم عن ذلك قد أخطأ، الذي ينهى أهل العلم على أن يدعوا إلى الله فقد أخطأ وغلط، بل هذا واجب أهل العلم أن يدعوا إلى الله وأن يعلموا الناس الخير وأن يرشدوهم إلى طاعة الله ورسوله، وأن يحذروهم من البدع وأهلها، وأن يأمروهم بتوحيد الله والإخلاص له، وأن يحذروهم من الشرك بالله الذي هو عمل الجاهلية وعمل عباد الأوثان.\nأما حديث: أجرؤكم على الفتيا أجرؤكم على النار، فهو حديث مرسل ليس بثابت عن النبي ﷺ، بل هو مرسل رواه الدارمي عن عبيد الله بن أبي جعفر عن النبي ﷺ، وعبيد الله بن أبي جعفر هذا تابعي ليس بصحابي فهو مرسل، يقول عبيد الله رحمه الله عن النبي عليه السلام أنه قال: أجرؤكم على الفتيا أجرؤكم على النار، وهذا لو صح المراد منه التحذير من الفتوى بغير علم، أما الفتوى بعلم فهي واجبة، على الناس أن يبينوا على أهل العلم أن يبينوا وأن يدعوا إلى الله جل وعلا، وقد بعث الله الرسل دعاة يبينون الحق وهكذا أتباعهم من العلماء هم خلفاء الرسل عليهم أن يبينوا الحق وأن يفتوا بالحق، أما من ليس عنده علم فليس له أن يتكلم إلا عن علم، قال الله جل وعلا في كتابه العظيم: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [الأعراف:33]، فجعل قوله عليه بغير علم فوق مرتبة الشرك، لعظم خطره ولأن الشرك من القول على الله بغير علم وقال سبحانه وتعالى في كتابه الكريم أيضاً: يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الأَرْضِ حَلالًا طَيِّبًا وَلا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ ۝ إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [البقرة:168-169]، فأخبر سبحانه أن الشيطان يغر الناس بالقول عليه بغير علم.\nفالواجب الحذر من القول على الله بغير علم، وقد حرمه الله وحذر منه وأخبر أنه في مرتبة فوق الشرك وأخبر أنه مما يأمر به الشيطان، فالواجب على أهل العلم أن يبينوا وأن يتبصروا، وعلى الدعاة إلى الله المفتين أن لا يتكلموا إلا عن علم وأن لا يفتوا إلا عن علم لهذه الآيات الكريمات ولغيرها من الأدلة الدالة على تحريم القول على الله بغير علم، والله المستعان.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8239/حكم-من-نهى-عن-نصح-الناس-لحديث-اجروكم-على-الفتيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_304/30402.mp3","categories":["الدعوة والدعاة"]},{"id":10111,"question":"مستمع يقول: المرسل (خضر . س. ع)، يقول: إن له أخ لا يصلي وغير ملتزم بشرع الله، وقد نصحته كثيرًا لكنه لا يسمع، وجهوني كيف أتصرف والحال ما ذكرت جزاكم الله خيرا.الجواب: عليك أن تستمر في النصيحة وتجتهد في ذلك، والله هو الذي يهدي من يشاء؟الشيخ: تعيد سؤاله تعيد، أعد السؤال.المقدم: لي أخ لا يصلي وغير ملتزم بشرع الله، وقد نصحته كثيراً لكنه لا يسمع، وجهوني كيف أتصرف معه جزاكم الله خيرا؟","title":"ماذا يفعل من ابتُلي بأخ لا يصلي؟","answer":"الشيخ: عليك أن تنصحه لله، وأن تجتهد في ذلك وتبين له ما يجب على المؤمن، وأن الصلاة فريضة وأنها عمود الإسلام وأن تركها كفر لعله يستجيب، أنت وإخوانك وأعمامك فإن لم يستفد ولم يقبل فارفعوا أمره إلى الهيئة، أو إلى إمارة البلد إن كان ما في هيئة حتى تقيم عليه الأمر، وحتى يستتاب فإن تاب وإلا قتل، لا يجوز بقاءه، بل يجب أن يستتاب فإن تاب وإلا قتل، الذي لا يصلي يقتل كافر نسأل الله العافية، الرسول ﷺ يقول: نهيت عن قتل المصلين، والله يقول: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5]، فدل على أن الذي ما يتوب من ترك الصلاة لا يخلى سبيله بل يقتل، هذه جريمة عظيمة، ترك الصلاة جريمة عظيمة، بل كفر وضلال، فإذا لم يقبل النصح فالواجب رفع أمره إلى الهيئة أو إلى المحكمة أو إلى الإمارة حتى يحال للمحكمة إن تاب وإلا قتل. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8282/ماذا-يفعل-من-ابتلي-باخ-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_277/27706.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":10178,"question":"تقول عن نفسها وعن والدها: والدي دائماً يترك صلاة العشاء، وأحياناً كثيرة يترك صلاة العصر، وأنا أستحي أن أخبره بهذا، فهل علي إثم؟","title":"حكم من يمنعه الحياء من النصح","answer":"الجواب: نعم؛ الواجب عليك تنبيهه والإنكار عليه بالكلام الطيب واللطف، لقول الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] ولقوله سبحانه: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللَّهِ [آل عمران:110] ولقوله سبحانه: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَأُوْلَئِكَ هُمُ الْمُفْلِحُونَ [آل عمران:104] فهذه الآيات العظيمات كلها تدل على وجوب إنكار المنكر من الولد على والده والوالد على ولده، والأخ على أخيه والمسلم على أخيه، هذا عام، يجب على الجميع التآمر بالمعروف والتناهي عن المنكر، لكن الولد مع والده يكون باللطف والكلام الطيب والحرص على أن يتأثر الوالد بالنصيحة، ولا مانع أيضاً من الاستعانة ببعض الأقارب والأصدقاء الذين يجلهم تارك الصلاة حتى ينصحوه حتى يوجهوه، حتى يعينوه على نفسه وعلى شيطانه، وهكذا كل آمر وناهي يتوخى الأسلوب المناسب ولو كان غير ولد، يتوخى الأسلوب المناسب الذي يرجو أن ينفع الله به، فالشدة في محلها واللين في محله، الأسلوب الحسن هو المطلوب، وإذا عاند تارك الصلاة استعمل معه الأسلوب الشديد إذا كان الآمر والناهي له سلطة له قوة، فيستعمل معه الأسلوب الشديد والعقاب أيضاً إذا استطاع العقاب حتى يستقيم، ويقول النبي ﷺ في الحديث الصحيح: من رأى منكم منكراً فليغيره بيده فإن لم يستطع فبلسانه فإن لم يستطع فبقلبه وهذا عام يعم الولد والوالد والأخ والخال والعم إلى غير ذلك.\nفالواجب على الولد أن يعتني بوالده وينصح له في الصلاة وغيرها بتحري الأسلوب الطيب المؤثر الذي يرجو من ورائه أن ينتفع والده بذلك، وألا يتكبر عليه وألا ينفر من الحق، وسوف يعينه الله إذا صدق وأخلص لله، سوف يعينه الله على أبيه، ويعين المرأة على أبيها، كل من الذكر والأنثى عليه أن يجاهد في هذا السبيل مع الوالد ومع الأخ ومع الخال ومع العم وهكذا، مع الصديق والجار ونحو ذلك، والله ولي التوفيق. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8347/حكم-من-يمنعه-الحياء-من-النصح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_308/30808.mp3","categories":["الدعوة والدعاة"]},{"id":10185,"question":"مستمع بعث برسالة مطولة بعض الشيء هو مهيوب أحمد حسن، يقول: أفيدكم أنني أتابع هذا البرنامج من عام ستة وسبعين للميلاد، وقد استفدت منه كثيراً، وأسألكم في هذه الرسالة سؤالين:الأول: ما هو رأيكم في السيرة لـابن هشام ؟","title":"تقييم كتاب سيرة ابن هشام","answer":"الجواب: كتاب جيد ومفيد، كتاب عظيم ومفيد، لكن في أخباره ما هو صحيح وما هو ضعيف، ولكنه كتاب مفيد، وهو مختصر السيرة لابن إسحاق رحمه الله، وفيه فوائد كثيرة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8365/تقييم-كتاب-سيرة-ابن-هشام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_309/30907.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10208,"question":"تقول عن نفسها: أصحو مبكرة دومًا لصلاة الفجر، وأحيانًا تفوت علي الصلاة، ولكن في الأوقات التي أقوم فيها للصلاة لا أقوم بإيقاظ زوجي للصلاة بل يظل نائمًا حتى مواعيد العمل وبعدها يصلي، هل في ذلك إثم علي؟","title":"حكم المرأة التي لا توقظ زوجها لصلاة الفجر","answer":"الجواب: نعم، إثم عليكما جميعًا عليك وعليه، عليك أن توقظيه وأن تتقي الله في ذلك وتعينيه على الخير، وعليه أن يقوم ويصلي في الوقت مع المسلمين في المساجد، وليس له أن ينام حتى وقت العمل هذا منكر، بل كفر إذا تعمد هذا كفر؛ لأنه تعمد ترك الصلاة في وقتها، تعمد إخراجها عن وقتها نعوذ بالله من ذلك.\nفالواجب عليك إيقاظه ونصيحته والحرص في ذلك، والواجب عليه أن يتقي الله وأن يقوم في الوقت، وأن يصلي مع المسلمين في المسجد، هذا هو الواجب على الجميع، والله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، ويقول سبحانه: وَالْمُؤْمِنُونََ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]، ويقول النبي ﷺ: من رأى منكم منكراً فليغيره بيده، فإن لم يستطع فبلسانه وأنت تستطيعين باللسان ولو غضب ولو كره أيقظيه ولو غضب، قولي: اتق الله الصلاة الصلاة، أعينيه على الخير، فإن لم يستقم فاطلبي الفراق اخرجي عنه إلى أهلك فارقيه؛ لأن هذا معناه تعمد ترك الصلاة في وقتها نعوذ بالله، ومن تعمد تركها في وقتها عمداً كفر بذلك في أصح أقوال أهل العلم؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، ومن تعمد تركها حتى تطلع الشمس عمدًا كفر بذلك على الصحيح.\nفالواجب عليك أن تتقي الله وأن تعينيه على الخير فإن أجاب وإلا فارقيه، واذهبي لأهلك واتركيه وامنعيه من نفسك، نسأل الله العافية والسلامة، نسأل الله لنا وله الهداية.\nالمقدم: اللهم آمين، جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8379/حكم-المراة-التي-لا-توقظ-زوجها-لصلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_278/27806.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":10215,"question":"يقول: هل يمكن لكل مسلمٍ أن يكون داعياً للخير، ويقوم بتوجيه الناس، ذلكم أني أرى بعض الناس يعترض على من يفعل ذلك، ويقول: أنت لست عالماً، فالتزم الصمت؟ فهل الذي يدعو إلى الله هم العلماء فقط، جزاكم الله خيراً؟","title":"عدم حصر الدعوة في فئة معينة ومن هو العالم","answer":"الجواب: كل من عنده علم يدعو إليه، إذا كان عنده علم وبصيرة في شيء يدعو إليه، ولو كان ليس من العلماء، لكن في حدود علمه، مثل ما يحذر من الزنا، الزنا معروف، يحذر من اللواط، يحذر من الخمر، يدعو من يشرب الخمر إلى التوبة إلى الله، هذا ما يحتاج علماء، هذا معروف عند العامة والخاصة، يحذر من الغيبة والنميمة، يحث الناس على الصلاة في الجماعة في المساجد، يحث الناس على بر الوالدين، وصلة الرحم وعدم العقوق، هذه أمور معلومة للخاص والعام، لكن المسائل التي تخفى عليه، وليس عنده فيها علم لا يتكلم فيها، ما يجوز له أن يتكلم في شيء لا يعلمه. نعم.\nالمقدم: جزاكم الله خيراً، سماحة الشيخ هل في الإمكان أن تتفضلوا بتوضيح من هو العالم؟\nالشيخ: العالم هو الذي عنده معرفة جيدة بكلام الله، وكلام رسوله ﷺ، ومعرفة المعنى من كلام الله، وكلام رسوله ﷺ؛ لأنه درس على أهل العلم، وتبصر وتفقه في الدين، وعرف بذلك، واشتهر بين المسلمين بعلمه وفضله، لا بمجرد الدعوى، بل اشتهر بين المسلمين وبين أهل العلم بعلمه وفضله، فهذا يقال له: عالم، ويقال للجماعة: علماء، إذا عرفوا بعلمهم العظيم، بالقرآن العظيم، والسنة المطهرة، وعرفهم الناس بذلك من أهل العلم، ودلوا عليهم، وأرشدوا إليهم، وبهذا يكون العامة على بصيرة في هذه الأشياء، إذا سمعوا ذلك من أهل العلم الذين يعرفونهم؛ أن فلان من أهل العلم، وأنه يحسن أن يؤخذ بفتواه، وأن يستفاد منه. نعم.","link":"https://binbaz.org.sa/fatwas/8409/عدم-حصر-الدعوة-في-فىة-معينة-ومن-هو-العالم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_310/31016.mp3","categories":["الدعوة والدعاة"]},{"id":10219,"question":"يقول: هل يمكن لكل مسلمٍ أن يكون داعياً للخير، ويقوم بتوجيه الناس، ذلكم أني أرى بعض الناس يعترض على من يفعل ذلك، ويقول: أنت لست عالماً، فالتزم الصمت؟ فهل الذي يدعو إلى الله هم العلماء فقط، جزاكم الله خيراً؟","title":"عدم حصر الدعوة في فئة معينة ومن هو العالم","answer":"الجواب: كل من عنده علم يدعو إليه، إذا كان عنده علم وبصيرة في شيء يدعو إليه، ولو كان ليس من العلماء، لكن في حدود علمه، مثل ما يحذر من الزنا، الزنا معروف، يحذر من اللواط، يحذر من الخمر، يدعو من يشرب الخمر إلى التوبة إلى الله، هذا ما يحتاج علماء، هذا معروف عند العامة والخاصة، يحذر من الغيبة والنميمة، يحث الناس على الصلاة في الجماعة في المساجد، يحث الناس على بر الوالدين، وصلة الرحم وعدم العقوق، هذه أمور معلومة للخاص والعام، لكن المسائل التي تخفى عليه، وليس عنده فيها علم لا يتكلم فيها، ما يجوز له أن يتكلم في شيء لا يعلمه. نعم.\nالمقدم: جزاكم الله خيراً، سماحة الشيخ هل في الإمكان أن تتفضلوا بتوضيح من هو العالم؟\nالشيخ: العالم هو الذي عنده معرفة جيدة بكلام الله، وكلام رسوله ﷺ، ومعرفة المعنى من كلام الله، وكلام رسوله ﷺ؛ لأنه درس على أهل العلم، وتبصر وتفقه في الدين، وعرف بذلك، واشتهر بين المسلمين بعلمه وفضله، لا بمجرد الدعوى، بل اشتهر بين المسلمين وبين أهل العلم بعلمه وفضله، فهذا يقال له: عالم، ويقال للجماعة: علماء، إذا عرفوا بعلمهم العظيم، بالقرآن العظيم، والسنة المطهرة، وعرفهم الناس بذلك من أهل العلم، ودلوا عليهم، وأرشدوا إليهم، وبهذا يكون العامة على بصيرة في هذه الأشياء، إذا سمعوا ذلك من أهل العلم الذين يعرفونهم؛ أن فلان من أهل العلم، وأنه يحسن أن يؤخذ بفتواه، وأن يستفاد منه. نعم.","link":"https://binbaz.org.sa/fatwas/8409/عدم-حصر-الدعوة-في-فىة-معينة-ومن-هو-العالم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_310/31016.mp3","categories":["الدعوة والدعاة"]},{"id":10239,"question":"أخيرًا يسأل ويقول: ما هي أفضل كتب الفقه التي يمكن الاعتماد عليها؟","title":"أفضل كتب الفقه المعتمدة","answer":"الجواب: كتب الفقه كثيرة، ولكن من أحسنها: المغني لـابن قدامة لـموفق الدين ابن قدامة عبدالله بن أحمد بن قدامة ، ... كتاب جيد مفيد يذكر فيه الخلاف والأدلة، شرح المهذب للنووي وتتمته، الفروع لـابن مفلح في المذهب الحنبلي، والإقناع والمنتهى في المذهب الحنبلي، والروض المربع في المذهب الحنبلي وحاشيته .. له حاشية جيدة للشيخ عبدالرحمن بن قاسم رحمه الله، وفي كتب أخرى في المذاهب الأخرى؛ كالمدونة في مذهب مالك رحمه الله، ومثل فتح القدير في المذهب الحنفي، كل هذه كتب مفيدة، لكن ينبغي للمؤمن أن يعتني بالدليل ويحرص على الكتب التي فيها الدليل، وبيان الراجح من الخلاف، وإذا كان طالب علم لا يستطيع أن يفهم هذه الأمور فيسأل أهل العلم عما أشكل عليه، ويحفظ الكتب المختصرة مثل: عمدة الحبيب في الحديث، ومثل بلوغ المرام حتى يستعين بذلك على معرفة الدليل، ومتن الزاد .... الحنابلة، أو متن الدليل أو العمدة أو العمدة للموفق في الفقه، أو ما أشبهها من الكتب المختصرة من كتب المذاهب الأخرى، حتى يستعين بها على معرفة المسائل الفقهية ومراجعة أدلتها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8410/افضل-كتب-الفقه-المعتمدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_335/33511.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10301,"question":"المستمع الطيب عبدالرحمن بعث برسالة ضمنها سؤالين: في أحدها يقول: أنا بحمد الله مسلم، وأواصل أداء صلواتي الخمس، أسكن مع جماعة، لكن هناك بعضاً منهم سامحهم الله يتناولون الخمر في داخل الغرفة، علماً بأنني أصلي فيها وأتناول الطعام معهم، فهل تجوز صلاتي وتناول طعامي جزاكم الله خيراً؟","title":"السكن مع من يقترف الكبائر كشرب الخمر أو غيره","answer":"الجواب: الحمد لله الذي وفقك للاستقامة، ونوصيك بأن تجتهد في نصيحة هؤلاء الذين يشربون الخمر، وتدعو لهم بالتوفيق والهداية، وتوصي إخوانك أيضاً أن يساعدوك في نصيحتهم، حتى يتوبوا من هذا العمل السيئ ومن هذه الكبيرة العظيمة.\nوصلاتك في الحجرة لا يضر وإن فعلوا فيها ذلك، صلاتك فيها النافلة لا حرج في ذلك، وأكلك معهم إذا كان ذلك على سبيل توجيههم إلى الخير والنصيحة لهم هذا كله طيب، أما إذا أبوا وشربوا الخمر وأنت حاضر، لا، لا تجلس معهم، ولا تأكل معهم على مائدة يدار عليها الخمر .\nأما إذا كنت تنصحهم ولا يشربون الخمر وأنت حاضر، توجههم إلى الخير وتنصحهم، ولكن لا يشربون الخمر وأنت حاضر، لكنك تعلم أن بعضهم يشرب الخمر فلا يمنعك ذلك من الجلوس معهم ونصيحتهم والأكل معهم، حتى يهدي الله من كان يشرب الخمر منهم، وحتى يرجع إلى الصواب بأسبابك إن شاء الله.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8464/السكن-مع-من-يقترف-الكباىر-كشرب-الخمر-او-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_312/31204.mp3","categories":["الدعوة والدعاة"]},{"id":10316,"question":"يوجد معي أخي وهو أكبر مني سنًّا ولا يصلي، وأحاول معه أكثر من مرة في أن يصلي وهو يقول: كثير من الناس لا يصلون، ماذا أفعل معه لإرغامه حتى يصلي، مع العلم أنه يعمل في كل شيء حتى في المسكن يعمل معي، أرجو إرشادي جزاكم الله خيرًا؟","title":"ما النصيحة لمن ابتُلي بأخ أكبر منه لا يصلي؟","answer":"الجواب: عليك أن تستمر في نصيحته والاستعانة أيضًا بخواص إخوانك الطيبين حتى ينصحوه معك، مع سؤال الله جل وعلا أن يهديه، تسأل ربك أن يهديه في صلاتك وفي آخر الليل وفي غير ذلك من الأوقات تسأل الله أن يهديه، وأن يشرح صدره للحق وأن يعينه على جهاد نفسه وشيطانه، ولا تيئس بل اجتهد في نصيحته لعل الله يمن عليك بالهداية، فإن أصر فابتعد عنه وقاطعه في الله واهجره في الله، لعل الله ينفع بذلك أيضًا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8487/ما-النصيحة-لمن-ابتلي-باخ-اكبر-منه-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_338/33803.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":10337,"question":"أخيراً يسأل ويقول: كيف يستطيع المرء أن يتعلم تفسير الأحلام، وهل توجد كتب صحيحة في هذا المجال؟","title":"مصادر تعلم تفسير الأحلام","answer":"الجواب: يتعلمها من كتب العلماء التي ذكرت الأحاديث عن النبي ﷺ في الرؤيا وتفسيرها، مثل كتاب ابن القيم في إعلام الموقعين ذكر جملة من ذلك رحمه الله في الرؤيا، وفي كتب أخرى مؤلفة في الرؤيا يستفيد منها، وأكثر ما يفيد ذلك تدبر الأحاديث التي جاءت في الرؤيا عن النبي ﷺ وتفسير النبي ﷺ لها، تفسير الصحابة، يستفيد منها إذا كان عنده علم وعنده بصيرة يستفيد.\nولا ينبغي أن يقدم على التأويل إلا عن بصيرة وعن علم حتى لا يكذب على الله ولا على رسوله عليه الصلاة والسلام، فينبغي لمن أراد التفسير -تفسير الرؤيا وتعبيرها- أن يعتني بما جاء في السنة عن النبي ﷺ في تفسير الرؤيا، وما جاء عن الصحابة والسلف الصالح، وما ذكره العلماء المعتمدون كـابن القيم، شيخ الإسلام ابن تيمية وغيرهم من أهل العلم. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8508/مصادر-تعلم-تفسير-الاحلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_315/31508.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10340,"question":"أخيراً يسأل ويقول: كيف يستطيع المرء أن يتعلم تفسير الأحلام، وهل توجد كتب صحيحة في هذا المجال؟","title":"مصادر تعلم تفسير الأحلام","answer":"الجواب: يتعلمها من كتب العلماء التي ذكرت الأحاديث عن النبي ﷺ في الرؤيا وتفسيرها، مثل كتاب ابن القيم في إعلام الموقعين ذكر جملة من ذلك رحمه الله في الرؤيا، وفي كتب أخرى مؤلفة في الرؤيا يستفيد منها، وأكثر ما يفيد ذلك تدبر الأحاديث التي جاءت في الرؤيا عن النبي ﷺ وتفسير النبي ﷺ لها، تفسير الصحابة، يستفيد منها إذا كان عنده علم وعنده بصيرة يستفيد.\nولا ينبغي أن يقدم على التأويل إلا عن بصيرة وعن علم حتى لا يكذب على الله ولا على رسوله عليه الصلاة والسلام، فينبغي لمن أراد التفسير -تفسير الرؤيا وتعبيرها- أن يعتني بما جاء في السنة عن النبي ﷺ في تفسير الرؤيا، وما جاء عن الصحابة والسلف الصالح، وما ذكره العلماء المعتمدون كـابن القيم، شيخ الإسلام ابن تيمية وغيرهم من أهل العلم. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8508/مصادر-تعلم-تفسير-الاحلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_315/31508.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10382,"question":"يسأل سماحتكم فيقول: ما هي الكتب المفيدة والتي تعين على ترسيخ العقيدة الإسلامية الصحيحة في نفوس الناس؟","title":"أهم الكتب التي ينصح بها في العقيدة","answer":"الجواب: أعظمها وأنفعها وأصدقها كتاب الله، فيه الهدى والنور، فأنا أنصح كل مسلم وكل مسلمة أن يعتني بالقرآن، وأن يكثر من تلاوته، فإنه هو الدواء الناجع لجميع الذنوب، وجميع ما يخالف الشرع؛ لأن الله سبحانه يقول: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] .. قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44] .. وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ [الأنعام:155] ويقول سبحانه: وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَى لِلْمُسْلِمِينَ [النحل:89].\nفالوصية العناية بالقرآن تلاوة وتدبرًا وتعقلًا وعملًا، هذا هو العلاج هذا هو الدواء النافع، ثم كتب الحديث الصحيح، مراجعة الأحاديث الصحيحة، حتى يستفيد منها، مثل صحيح البخاري ، صحيح مسلم ، سنن أبي داود ، الترمذي ، النسائي ، ابن ماجة ، رياض الصالحين، الترغيب والترهيب، يسمع الأحاديث يستفيد، يعالج أمراض قلبه بما يسمع من أقوال النبي عليه الصلاة والسلام مع القرآن الكريم، ثم حضور المواعظ والمحاضرات المفيدة من العلماء المعروفين، والإصغاء إلى خطب الجمعة والاستفادة منها، كل هذا مما يعين على التوبة وعلى ترك الذنوب، كون المؤمن يعتني بسماع المحاضرات من أهل العلم، والندوات العلمية، وخطب الجمعة، يكون حاضر القلب، يستفيد مع العناية بالقرآن، والإكثار من تلاوته، وتدبر معانيه، والعناية بمراجعة الأحاديث الصحيحة، والاستفادة منها، هذا هو العلاج، مع الضراعة إلى الله وسؤاله أن الله يهديه وأن الله يصلح قلبه وعمله، وأن الله يرزقه البطانة الصالحة، والجلساء الصالحين، فإن الجلساء الصالحين من أعظم العون على الخير، كونه يتحرى الجلساء الصالحين والأصحاب الطيبين، ويتباعد جدًا عن أصحاب السوء، وعن أصحاب الشر. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8554/اهم-الكتب-التي-ينصح-بها-في-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_280/28007.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10461,"question":"يقول: نسأل سماحتكم عن أسماء الكتب المفيدة التي تقوي ديننا وتجعلنا نحافظ عليه، جزاكم الله خيراً؟","title":"أسماء بعض الكتب المفيدة التي تعين المسلم في دينه","answer":"الجواب: الكتب كثيرة، لكن أعظمها وأشرفها وأصدقها وأنفعها كتاب الله القرآن العظيم، نوصي الجميع بكتاب الله، هو أحسن كتاب وأصدق كتاب، وفيه الدلالة على كل خير، وفيه التوجيه إلى أسباب النجاة والسعادة، وفيه الترهيب من أسباب الهلاك.\nفنوصيك أيها السائل وجميع المسلمين والمسلمات بالعناية بالقرآن العظيم والإقبال عليه، والإكثار من تلاوته وتدبر معانيه والعمل بما فيه من الأوامر والنواهي، فهو كتاب الله فيه الهدى والنور، لا يَأْتِيهِ الْبَاطِلُ مِنْ بَيْنِ يَدَيْهِ وَلا مِنْ خَلْفِهِ تَنزِيلٌ مِنْ حَكِيمٍ حَمِيدٍ [فصلت:42] يقول الله فيه : إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] ويقول سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29] ويقول سبحانه: وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ [الأنعام:155] فهذا الكتاب العظيم فيه الهدى والنور، فيه الدلالة على الخير كله والتحذير من الشر كله، فالوصية لكل مسلم ولكل مسلمة العناية بالقرآن والإكثار من تلاوته وحفظه إذا تيسر ذلك، فهو أصل كل خير وينبوع كل خير.\nثم سنة الرسول ﷺ مثل البخاري و مسلم ، الإكثار من قراءتهما وتدبر معاني الأحاديث ومراجعة كلام أهل العلم في تفسيرها وشرحها، ثم السنن الأربعة: أبو داود و الترمذي و النسائي و ابن ماجة ، هذه الكتب من أحسن الكتب بعد الصحيحين، فالعناية بها والاستفادة منها مهم جداً في حق طلبة العلم، الاستفادة من السنن الأربع والعناية بها والإكثار من مراجعتها كل ذلك فيه خير عظيم، ثم بكتب العلماء مثل زاد المعاد لـابن القيم في هدي خير العباد، ومثل الفتاوى لشيخ الإسلام ابن تيمية ومثل في العقيدة: فتح المجيد شرح كتاب التوحيد .. مثل مجموعة التوحيد.. مثل تيسير العزيز الحميد للشيخ سليمان بن عبد الله شرح كتاب التوحيد.. مثل نفس كتاب التوحيد.. مثل كشف الشبهات.. ثلاثة الأصول.. العقيدة الواسطية لشيخ الإسلام ابن تيمية .. التدمرية والحموية كلاهما لشيخ الإسلام ابن تيمية ، هذه كتب مفيدة وعظيمة نافعة، ومثل شرح الطحاوية لـابن أبي العز أيضاً كتاب مفيد في العقيدة، مثل المنتقى في الحديث.. بلوغ المرام في الحديث، الأول: للمجد ابن تيمية والثاني للحافظ ابن حجر ، هذه الكتب أيضاً مفيدة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8645/اسماء-بعض-الكتب-المفيدة-التي-تعين-المسلم-في-دينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_320/32011.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10483,"question":"من جمهورية مصر العربية محافظة الدقهلية المستمع (فهمي . ش) بعث يسأل ويقول: لي زوج أخت يتعاطى الخمر، وحاولت مع كثيرين أنا وبعض الأقارب منعه من شرب الخمر إلا أنه لم يقبل النصح، وكان عنيفاً معنا، وهو يضرب زوجته التي هي أختي ويهيننا بالعبارات، وفي بعض الأحيان يخرجها وأولادها إلى الشارع، فما هو أفضل حل نتخذه مع هذا الرجل؟","title":"كيفية التعامل مع من يشرب الخمر ويضرب زوجته","answer":"الجواب: عليكم مداومة النصيحة بالكلام الطيب، والأسلوب الحسن لا بالعنف والشدة، واستعينوا بالله ثم ببعض إخوانكم الطيبين الذين يعظمهم ويقدرهم هو حتى يعينوكم على نصيحته وتوجيهه إلى الخير ولا تيئسوا، لا تيئسوا وادعوا له بظهر الغيب، قولوا: اللهم اهد فلان، اللهم أصلحه، اللهم أعذه من شر نفسه وشيطانه واصبروا، وعليكم بالحلم والصبر والكلام الطيب، والأسلوب الحسن لعل الله يهديه بأسبابكم، فيكون لكم مثل أجره، كما قال النبي ﷺ: من دل على خير فله مثل أجر فاعله ولا تيئسوا عليكم بالكلام الطيب والأسلوب الحسن، والتعاون مع إخوانكم الطيبين في زيارته ونصحه وتوجيهه إلى الخير، لعل الله يهديه بأسبابكم، ويقول النبي ﷺ: من دل على خير فله مثل أجر فاعله، وأنتم مشكورون مأجورون، أو كان هناك في البلد محكمة شرعية ولم يستجب ارفعوا به إلى المحكمة فيما يتعلق بإقامة الحد عليه، وفيما يتعلق بأمر زوجته.\nأما إذا كان ما فيه محكمة تحكم بالشرع، فعليكم النصح المستمر والتوجيه والتعاون مع إخوانكم الطيبين الذين يقدرهم ويرى لهم فضل، تعاونوا معهم في إرشاده وتوجيهه لعل الله يهديه بأسبابكم. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8658/كيفية-التعامل-مع-من-يشرب-الخمر-ويضرب-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_281/28110.mp3","categories":["الدعوة والدعاة"]},{"id":10484,"question":"من المدينة المنورة رسالة بعثت بها إحدى الأخوات تقول أم عاتكة، تسأل وتقول: هل يكفي في إنكار المنكر إهداء كتيب أو شريط لمن رأيت منهم المنكر، وهذا الشريط يتطرق إلى المنكر نفسه؟","title":"حكم الاكتفاء بإهداء الكتيب والشريط في إنكار المنكر","answer":"الجواب: هذا طيب ولكن لا يكفي، إذا كنت تستطيعين النصيحة والكلام الطيب فافعليهم هذا وهذا جميعًا، أما إذا كنت لا تستطيعين فإرسال الشريط والكتيب جيد ونافع وفيه خير كثير، ولكنه لا يغني عن إنكار المنكر والأمر بالمعروف، من استطاع أن يأمر بالمعروف وينهى عن المنكر فيفعل مع الكتيب ومع الشريط، كل هذا لعل الله ينفع بالجميع.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8659/حكم-الاكتفاء-باهداء-الكتيب-والشريط-في-انكار-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_281/28111.mp3","categories":["الدعوة والدعاة"]},{"id":10491,"question":"إحدى الأخوات تسأل وتقول: إذا كان لي أولاد أخ أو أولاد أخت ولكن لا أرى أن أهلهم يهتمون بهم من حيث التربية الإسلامية الصحيحة، فهم لا يأمرونهم بالصلاة مع أن كثيراً منهم قد بلغ العاشرة، فهل يجب علي أن أقوم بهذا الدور، أم كيف أتصرف علماً بأنهم ربما يغضبون من ضربي لهم إذا اقتضى الأمر الضرب؟","title":"ما واجب الخالة تجاه أولاد أختها الذين لا يصلون؟","answer":"الجواب: عليك المناصحة لهم، لآبائهم وأمهاتهم حتى يقوموا بالواجب، أنت لا تضربينهم لكن انصحي، انصحي آباءهم وأمهاتهم حتى يقوموا بالواجب، عليك النصيحة والأمر بالمعروف والنهي عن المنكر، والضرب على غيرك؛ لأن الرسول ﷺ قال: مروا أبناءكم بالصلاة لسبع، واضربوهم عليها لعشر، فالمأمور الآباء والأمهات، وأنت إن شاء الله تنصحين وتشيرين وترغبين وتحذرين.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8666/ما-واجب-الخالة-تجاه-اولاد-اختها-الذين-لا-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_281/28118.mp3","categories":["الدعوة والدعاة"]},{"id":10515,"question":"ننتقل إلى رسالة وصلت إلى البرنامج من حقل باعث الرسالة المستمع أبو أيوب، أبو أيوب يقول: أريد أن أدعو بالحكمة والموعظة الحسنة، لكن كيف أفعل؟ هل الشرع في إزالة المنكر عندما أراه هل يعتبر من الحكمة، أفيدوني جزاكم الله خيرًا؟","title":"كيفية الدعوة إلى الله بالحكمة والموعظة الحسنة","answer":"الجواب: الله يقول سبحانه في كتابه الكريم: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]، الحكمة: العلم، قال الله قال رسوله ووضعها في المحل المناسب، هذه الحكمة أن تكلم بالحق في الوقت المناسب والمحل المناسب، تؤدي هذه الأوامر بالعبارات الحسنة والألفاظ اللينة التي ليس فيها عنف، هذه الموعظة الحسنة قال الله قال رسوله، يا عبد الله؛ هذا لا يجوز، اتق الله، يرحمك الله، هذا يجب عليك هذا يجب تركه، بعبارات لينة، مع بيان الأدلة قال الله كذا، قال الرسول كذا عليه الصلاة والسلام، هكذا تكون الحكمة والموعظة الحسنة، بالكلام الواضح من كلام الله وكلام رسوله مع الرفق وعدم العنف والشدة أو السب أو نحو ذلك، بل يكون كلام واضح لين، ليس فيه عنف ولكن فيه الرفق والكلام الطيب، والجدال بالتي هي أحسن عند المجادلة، إذا جادل من فعل المنكر تجادله بالتي هي أحسن إلا من ظلم؛ لقوله تعالى: وَلا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ[العنكبوت:46]، من ظلم يستحق الجدال بمثل عمله. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8690/كيفية-الدعوة-الى-الله-بالحكمة-والموعظة-الحسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_283/28304.mp3","categories":["الدعوة والدعاة"]},{"id":10516,"question":"سماحة الشيخ هل هناك حد للأمر بالمعروف والنهي عن المنكر، أم أن الأمر على إطلاقه؟","title":"ضوابط الأمر بالمعروف والنهي عن المنكر ومراتبه","answer":"الجواب: النبي ﷺ فصل ذلك، قال: من رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه وذلك أضعف الإيمان، هذه حدوده، باليد عند القدرة، وهذا يكون للمسئولين من جهة الدولة الذين جعلت لهم الدولة السلطة في هذا الشيء، أو للإنسان مع أهل بيته ومع أولاده يستطيع هذا باليد، أو مع خدمه أو نحوه حيث قدر. الثاني: من ليس له سلطة وليس عنده قدرة فهذا باللسان، يقول: يا عبد الله! كذا هذا لا يجوز، هذا واجب عليك، هذا حرام عليك، اتق الله، هداك الله، أصلحك الله، وما أشبه ذلك. الثالث: القلب ما يقدر يتكلم ينكر بقلبه، ولا يحضر المنكر يفارق المنكر، ينكر .... ويكرهه بقلبه. نعم.\nالمقدم: إذاً الأمر بالمعروف والنهي عن المنكر درجات وكل بحسبه؟\nالشيخ: نعم، ويشترط في هذا أيضاً أن لا يكون هذا الإنكار يسبب أنكر منه، أن لا يكون هذا الإنكار يسبب وقوع ما هو أنكر، فإذا كان إنكاره لهذا المنكر يخشى منه منكر أكبر فليجتنب ذلك، حتى لا يقع الأكبر، إذا أنكر عليه مثلًا جلوسه في محل ما هو مناسب، أو أنكر عليه شرب الدخان أو ما أشبه ذلك شرب المسكر شرب الخمر مغايظة له، أو إذا أنكر يسب المسلم سب الله، ما كفاه سب المسلم سب الله، فهذا يترك حتى يعالج بطريقة أخرى، المقصود أنه يتحرى في إنكار المنكر أن يترتب عليه زوال المنكر، وعدم حصول ما هو أنكر منه، فإذا كان في جماعة لو أنكر عليهم حصل منهم ما هو أنكر، يتركهم إلى وقت آخر، أو إلى جهات أخرى تقوم عليهم. نعم.\nالمقدم: إذاً هناك حدود وهناك قواعد على الآمر بالمعروف والناهي عن المنكر أن يتبعها ويسير عليها؟\nالشيخ: نعم، وقد صرح أبو العباس ابن تيمية رحمه الله بهذا المعنى في كتاب: الحسبة، كتابه الذي سماه: الحسبة، صرح بهذا المعنى. نعم.\nالمقدم: جزاكم الله خيرًا يبدو لي أن الأمر بالمعروف والنهي عن المنكر علم مستقل بذاته سماحة الشيخ؟\nالجواب: نعم علم مستقل، علم مستقل يحتاج إلى عناية، والناس أقسام، فلابد من رعاية حصول المصلحة وزوال المضرة، فالمقصود من إنكار المنكر زوال الشر وحصول الخير، هذا المقصود، فإذا كان هذا الإنكار يترتب عليه زيادة الشر، يؤجله لا يفعل.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8691/ضوابط-الامر-بالمعروف-والنهي-عن-المنكر-ومراتبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_283/28305.mp3","categories":["الدعوة والدعاة"]},{"id":10517,"question":"ننتقل بعد هذا إلى رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، رمزت إلى اسمها بحروف (م. م) أختنا لها رسالة مطولة كلها شكوى وملاحظات على زوجها فهي تقول: أنا فتاة في الثامنة عشرة من عمري ملتزمة والحمد لله، وقد زوجني أبي وأنا عمري في السادسة عشرة من رجل عنده امرأتان ولديه خمسة عشر ولداً، أكبرهم في سني، وأنا أشكو من زوجي الذي آمره بأن يعفي لحيته طاعة لله ورسوله، ولكنه لم يفعل بل يقصرها على آخر شيء، ولولا كثرة الشيب لكان يحلقها بالموس، ولأنه يقول: إن الموس تكثر الشيب فاتخذ القص بدلًا من الحلق، وكلما أردت أن أكرر النصيحة قال: لا تتدخلين في شأني، علماً بأنني لم أنجب أبناء منه حتى الآن، فأخبرني يا سماحة الشيخ هل أطلب الطلاق من ذلكم الرجل أم أعيش وأصبر؟ وكيف تنصحونني جزاكم الله خيرًا، علماً بأنني أعتبره عاصٍ لله ولرسوله؟","title":"حكم طلب المرأة للطلاق لامتناع الزوج من إعفاء اللحية","answer":"الجواب: لقد أحسنت في إنكار المنكر جزاك الله خيراً، وفعلت ما يجب من إنكار المنكر، والله جل وعلا هو الذي يهدي من يشاء كما قال سبحانه: لَيْسَ عَلَيْكَ هُدَاهُمْ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [البقرة:272]، ويقول سبحانه: إِنَّكَ لا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْْ يَشَاءُ [القصص:56]، والواجب عليه أن يتقي الله، وأن يطيع الرسول ﷺ، فالرسول عليه السلام يقول: قصوا الشوارب وأعفوا اللحى، خالفوا المشركين، ويقول ﷺ: قصوا الشوارب ووفروا اللحى، خالفوا المشركين، فالواجب عليه أن يتقي الله وأن يطيع الرسول ﷺ، وأن يعفي لحيته ويكرمها ويوفرها طاعة لله ولرسوله، وحذرًا من غضب الله، فالواجب عليه أن يسمع ويطيع لأمر الله ورسوله، وأن يشكرك على ما فعلت من الخير، وأن يقبل منك النصيحة؛ لأنك فعلت ما ينبغي وما يجب.\nأما ما يتعلق بطلب الطلاق فهذا شيء يرجع إليك إذا رأيت المصلحة في طلب الطلاق فلا بأس، إذا كان استمر على حاله ولم تنجبي منه فلا مانع من طلب الطلاق لعل الله يرزقك من هو خير منه، ويرزقك أيضاً ذرية، فهذا عذر شرعي، لا بأس أن تطلبي الطلاق إذا سمح أن يطلق فهذا طيب، ولعل الله يرزقك بما هو أصلح منه. نعم.","link":"https://binbaz.org.sa/fatwas/8692/حكم-طلب-المراة-للطلاق-لامتناع-الزوج-من-اعفاء-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_283/28306.mp3","categories":["الطلاق","الأيمان والنذور","الأخلاق المذمومة","الدعوة والدعاة"]},{"id":10528,"question":"يقول في سؤال آخر: هل أفرق في معيشتي بين إخوتي الذين لا يصلون علمًا بأنهم أفقه مني كما يقول؟","title":"حكم مفارقة الإخوة الذين لا يصلون","answer":"الجواب: نعم ينبغي أن تكون على حدة، ما داموا لا يصلون لا تصحبهم ولا تجالسهم، بل يستحقون الهجر حتى يتوبوا إلى الله ويصلوا، وأنت خلك على حدة، طعامك يكون على حدة، اللهم إلا أن تقع صدفة في ضيافة أو دعوة أو نحو ذلك، فالشيء القليل العارض مع النصيحة ومع التوجيه لا يضر إن شاء الله. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8703/حكم-مفارقة-الاخوة-الذين-لا-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_283/28317.mp3","categories":["الدعوة والدعاة"]},{"id":10530,"question":"السائلة لها سؤال آخر تقول: كيف تكون المرأة داعية إلى الله عز وجل، وفي سبيل الله، في ظل ظروف أسرية تمنعها من الخروج من البيت لحضور الدروس أو المحاضرات؛ لأن الوالد يكرر دائمًا الآية الكريمة: وَقَرْنَ فِي بُيُوتِكُنَّ [الأحزاب:33] فما معنى القرار هنا سماحة الشيخ؟","title":"حكم منع المرأة من الدعوة إلى الله في مجامع النساء","answer":"الجواب: إذا كانت المرأة عندها علم تدعو إلى الله سبحانه ولو في بيتها، مع أهلها ومع الزوار حتى يتيسر لها الخروج إلى مجامع النساء.\nوالواجب على أبيها إذا كان عندها علم ألا يمنعها من الخروج إلى مجامع النساء، مع التستر والبعد عن أسباب الفتنة، والأصل في البقاء في البيوت هو الأصل هو الأسلم والأولى؛ لقوله جل وعلا: وَقَرْنَ فِي بُيُوتِكُنَّ [الأحزاب:33]؛ لأنه أبعد للمرأة عن الفتنة، لكن خروجها لحاجتها وخروجها للدعوة إلى الله، أو للتعلم، أو لصلة الرحم، أو لعيادة المريض، أو لتعزية المصاب كل هذا لا بأس به مشروع، وإنما المكروه خروجها من غير حاجة.\nأما إذا كان خروجها لأمر شرعي فهذا أمر مطلوب، والواجب على الآباء والأولياء أن يساعدوا على الخير، وإذا كانت المرأة صالحة ساعدوها على الخير.\nأما إذا كانت تتهم بأنها تخرج باسم الخير وهي تريد الشر هذا محل نظر ومحل اجتهاد، لكن ما داموا يعرفون أن خروجها خروج صالح ليس فيه شيء؛ وأنها تخرج إلى الدراسة التي ليس فيها اختلاط، أو إلى حضور حلقات العلم بين النساء، أو للدعوة إلى الله بين النساء، إذا كانوا يعلمون أن خروجها لا بأس به، فالواجب عدم منعها، والواجب أن تساعد على الخير، كما كان أزواج النبي صلى الله عليه وسلم يخرجن في المصالح العامة وفي المصالح الخاصة وهن المخاطبات ..... : وَقَرْنَ فِي بُيُوتِكُنَّ [الأحزاب:33] ومع هذا يخرجن، يخرجن لتعزية المصاب، ويخرجن لحفلات الأعراس، ويخرجن لغير هذا من الحاجات، وفيهن أسوة رضي الله عنهن وأرضاهن. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/8705/حكم-منع-المراة-من-الدعوة-الى-الله-في-مجامع-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28402.mp3","categories":["الدعوة والدعاة","قضايا المرأة"]},{"id":10531,"question":"السائل: حمدي مصري يقول في هذا  هناك رجل لا يجيد القراءة ولا الكتابة ولا يتفقه في الدين، هل يعذر بجهله أم لا، وإذا كان يعذر فما الدليل جزاكم الله خيرًا؟","title":"وجوب التفقه في الدين فيما لا يسع المسلم جهله","answer":"الجواب: الواجب عليه أن يتعلم، الواجب عليه أن يتعلم ويتبصر ويسأل أهل الذكر ويحضر حلقات العلم حتى يتعلم دينه؛ لأن الله سبحانه خلقه ليعبده: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] وهذه العبادة يجب أن يتفقه فيها وأن يعرفها من طريق أهل العلم، من طريق حلقات العلم، من طريق سماع خطب الجمعة والمحاضرات المفيدة، ويسأل أهل العلم حتى يعرف دينه، ما هي العبادة التي خلق لها، يسأل حتى يتبصر وحتى يتعلم وحتى يؤدي ما أوجب الله عليه على بصيرة، وليس له السكوت والإعراض، بل يجب أن يسأل ويتعلم ويتفقه حتى يعبد الله على بصيرة.\nيقول النبي ﷺ: من يرد الله به خيرًا يفقهه في الدين والله يقول: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43] نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8706/وجوب-التفقه-في-الدين-فيما-لا-يسع-المسلم-جهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28403.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10723,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الكويت، باعثها المستمع خالد صالح محمد المهيني مستشار، أخونا خالد يقول: عندما أقوم بتدريس مادة التربية الإسلامية للمرحلة الثانوية، وخلال عملي أحتاج إلى وسائل تقنيات للشرح مثال جهاز العرض العلوي، وهذا الجهاز أعرض عليه الآيات القرآنية ليتم شرحها للطلبة، ولكن إعداد هذه الشرائح يتطلب مني قطع صفحات من المصحف لإدخالها في الجهاز، ولا يمكن الاستغناء عن تلك الطريقة؛ لأنها تسهل عملي، فهل هناك إثم في هذه الناحية؟","title":"حكم تقطيع ورق المصحف وإدخالها في جهاز العرض للتعليم","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد:\nفهذا الإجراء الذي ذكره السائل فيه احتمال وليس بواضح، ونرى أن يرسل السائل رسالة موضحة لعمله أكثر من هذا، حتى ينظر في ذلك ويجاب على ضوء ذلك، نعم.\nالمقدم: يقول: طلب مني العامل الذي يعمل في القسم أن أقدم له المصحف الذي تنقصه بعض الصفحات، فقدمته له، ولكن بعد ذلك أحسست أنني أخطأت بذلك؛ لأن المصحف تنقصه بعض الصفحات، فكيف أعمل؟ هل أستعيده منه مع أن رسول الله ﷺ نهى عمر بن الخطاب رضي الله عنه أن يستعيد أعطيته، فقال عليه الصلاة والسلام: العائد في أعطيته كالكلب يعود في قيئه، أو كما قال ﷺ، فما الحل جزاكم الله خيراً؟\nالجواب: الواجب عليك أن تنبهه على الأخطاء حتى يسدد النقص، عليك أن تنبه الشخص العامل على مواضع الخطأ حتى يكتب ما سقط من المصحف، ويلحق في محله، وبذلك تبرأ الذمة إن شاء الله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8898/حكم-تقطيع-ورق-المصحف-وادخالها-في-جهاز-العرض-للتعليم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_344/34401.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10753,"question":"رسالة مطولة بعض الشيء من إحدى الأخوات المستمعات، تقول أختكم في الله الحائرة (أم عبد الله . س. ج) تقول: تزوجت من رجل يصلي ولله الحمد وأخلاقه طيبة ولله الحمد، ولكنني أرغب من زوجي أن يكون لديه حماس شديد بالنسبة للصلاة وأن يقوم الليل، وأن يكون حافظاً للقرآن الكريم أو بعضاً منه، وأن يكون مجاهداً في سبيل الله، وأن يكون عالماً بشعائر الدين، لكي يخبرني عن الحلال والحرام، ويكون رجلاً مثقفاً، حيث أنني أكثر منه علماً في ديني ولا أمدح نفسي، وَمَا أُوتِيتُمْ مِنَ الْعِلْمِ إِلَّا قَلِيلًا [الإسراء:85] وهذه الأسباب جعلتني أكره زوجي، ومنذ أن تزوجته وأنا أطلب منه الطلاق، وكراهيتي له تزيد يوماً بعد يوم، فهل يحق لي ذلك يا سماحة الشيخ! مع العلم أنني صليت صلاة الاستخارة عدة مرات قبل الزواج، ولكنني لم أعرف نتيجة الاستخارة فتزوجته، وأنا الآن نادمة على زواجي ذلك، فما هو الحل يا سماحة الشيخ! حيث إن الإنسان يعرف مع من يعاشر، وأنا أريد زوجي أن يكون معي في الجنة يوم القيامة، وأنا أعامله معاملة سيئة لكراهيتي له، فأنا خائفة من الله بالنسبة لهذه المعاملة، وهل أكون من الذين لم يصبروا على قضاء الله وقدره، أرجو إفادتي حول هذه القضايا؟ جزاكم الله خيراً.","title":"نصحية الزوجة لزوجها ضعيف الهمة في طلب العلم","answer":"الجواب: الواجب عليك أيها الأخت في الله الواجب عليك الصبر، وأن تنصحيه وترشديه بالكلام الطيب وترغبيه في التعلم والتفقه في الدين، كما أشرت إلى ذلك، أما عصيانه أو كراهته لكونه لم يجتهد فيما ذكرت من التعلم والتفقه وأن يكون من المسارعين ومن المبادرين إلى الصلاة ونحو ذلك، هذا لا يوجب بغضه أو طلب الطلاق، فلا يجوز لك طلب الطلاق، ما دام الرجل يصلي وليس هناك ما يوجب كفره من نواقض الإسلام، ولكنه ليس عنده المعلومات التي عندك وليس عنده التحمس إلى المسارعة والمسابقة إلى الصلاة، ولكنه يصلي والحمد لله.\nفالواجب عليك السمع والطاعة في المعروف، وعدم طلب الطلاق، والتعاون معه على الخير، من جهة حثه على المطالعة والمذاكرة وحضور حلقات العلم، وسماع هذا البرنامج نور على الدرب حتى يستفيد وحضور حلقات العلم إذا وجدت عندكم من علماء السنة وأهل الخير حتى يستفيد، أما طلب الطلاق فلا وجه له، وليس من اللازم أن يكون زوجك مثلك في العلم، قد يكون الزوج دون المرأة وقد تكون فوقها في العلم، وإذا من الله عليك بالعلم فأحسني إليه ووجهيه بالكلام الطيب والأسلوب الحسن، ورغبيه في الخير وساعديه بكل ما تستطيعين وشجعي أقاربه كأبيه أو أخيه حتى يرغبوه وحتى يساعدوه في التفقه في الدين والتعلم، ولا أنصحك أبداً أن تطلبي الطلاق بل لا يجوز لك ذلك، طلب الطلاق ليس هنا ما يوجب طلبه، ولا يسبب طلبه، وفي الحديث: أيما امرأة طلبت الطلاق من غيرما بأس لم ترح رائحة الجنة.\nفالواجب عليك الصبر والاحتساب والتعاون معه على الخير وإرشاده إلى الخير واحتساب الأجر في كل ما تبذلين في طريق تثقيفه وتفقيهه حتى يكون إن شاء الله كما طلبت وكما رغبت في العلم والفضل، وفق الله الجميع.\nالمقدم: اللهم آمين، جزاكم الله خيرا، النقص في الإنسان شيء وارد سماحة الشيخ، وقد يسيء الإنسان من حيث يعتقد أنه يحسن، أختنا طلبت ما طلبت من زوجها وربما طلبت منه فوق طاقته، أن يحفظ القرآن أن يقوم الليل أن يجاهد في سبيل الله، ربما أنه لا يستطيع هذا، أطمع بكلمة زائدة في هذا الموضوع؟\nالشيخ: على كل حال مثل هذه المطالب هو مخير فيها، حفظ القرآن ليس بواجب، والتهجد بالليل ليس بواجب، ولكن يسن له أن يحفظ ما تيسر من القرآن إذا أمكنه ذلك، يسن له التهجد بالليل والوتر ولو في أول الليل، كل هذا أمر مشروع، والجهاد في سبيل الله فيه تفصيل، إذا استطاع الجهاد وتمكن من الجهاد فالجهاد من أعظم القربات ومن أفضل الطاعات، وقد يكون فرض كفاية، وقد يكون فرض عين، وقد يكون سنة، ففيه تفصيل.\nفالمشروع لها أن تشجعه على الخير وأن تحثه على الخير، ولكن لا تطلب الطلاق من أجل هذا. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8919/نصحية-الزوجة-لزوجها-ضعيف-الهمة-في-طلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_346/34602.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10770,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من السودان وباعثها المستمع صالح طه علي من الزراقنة، الأخ صالح يقول في رسالته: عندنا في السودان ناس يدعون إلى الإسلام ويعملون لإعلاء كلمة الله وتطبيق شرع الله، ولكن تطالعنا صور بعضهم وهم من قادة هذه الدعوة بدون لحى أي: يحلقون اللحية، والرسول ﷺ أمر بإطلاق اللحى في عدة أحاديث، ما رأي سماحتكم في مخالفة هذا الأمر؟","title":"الحث على قبول الحق من الدعاة","answer":"الجواب: الداعي إلى الله جل وعلا والمعلم لعباد الله ليس بمعصوم، فإذا كان يدعو إلى الله جل وعلا ويرشد الناس إلى الخير فهو مشكور وله أجره العظيم، كما قال النبي ﷺ: من دل على خير فله مثل أجر فاعله، والله يقول سبحانه: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ [فصلت:33].\nفالدعوة إلى الله وإلى توحيده وإلى طاعة أوامره وترك نواهيه هذه هي سبيل الرسل، قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108] والداعي إلى الله قد يقع منه بعض المعاصي ليس بمعصوم، فلا تزهد فيه من أجل هذه المعصية اسمع ما يقوله من الحق قال الله وقال رسوله، واستفد من ذلك وانتفع بذلك وادع الله له أن يوفقه لتوفير لحيته وإكرامها وإعفائها، فلا شك أن حلق اللحية محرم ومنكر كما قال النبي ﷺ: قصوا الشوارب وأعفوا اللحى خالفوا المشركين، وقال عليه الصلاة والسلام: قصوا الشوارب ووفروا اللحى خالفوا المشركين، وقال في اللفظ الآخر: جزوا الشوارب وأرخوا اللحى خالفوا المجوس، كلها أحاديث صحيحة بعضها في الصحيحين وبعضها في صحيح مسلم .\nفالواجب على كل مسلم وإن كان من غير أهل العلم أن يعفيها وأن يوفرها وأهل العلم أولى بهذا؛ لأنهم الدعاة ولأنهم القدوة، فالواجب عليهم أن يوفروها وأن يحترموها طاعة لله ولرسوله، وعملاً بشرع الله، وحتى تقبل دعوتهم، وحتى لا يساء بهم الظن، لكن لو قصر في ذلك فإنك لا تترك الاستجابة لدعوته في الحق وعليك أن تقبل الدعوة في الحق، وإن كان صاحبها مقصراً في بعض الأمور، فليس الداعي إلى الله كاملاً ولا معصوماً، فقد يأمر بالمعروف وينهى عن المنكر ويدعو إلى الله وعنده بعض النقص، فاقبل منه فيما دعا إليه من الخير والهدى، وانصحه فيما قصر فيه، نصيحة المؤمن لأخيه، باللطف والأسلوب الحسن، وأنت مأجور وهو مأجور، هو مأجور على دعوته وعلى ما قام به من الخير، وأنت مأجور على النصيحة والتوجيه إلى الخير، ولا يمنعك تقصيره من أن تقبل دعوته في الخير، وأن تعينه على الخير، وفق الله الجميع.\nالمقدم: اللهم آمين. جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8943/الحث-على-قبول-الحق-من-الدعاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_348/34803.mp3","categories":["الدعوة والدعاة"]},{"id":10809,"question":"رسالة وصلت إلى البرنامج من المستمعة (أ. أ. الزاوي) من طرابلس في ليبيا، أختنا لها عدد من الأسئلة، من بينها سؤال تقول فيه: أرجو من سماحتكم أن تتفضلوا بإبداء رأيكم حول مؤلفات أبي الأعلى المودودي، وأبي الحسن الندوي، وسيد قطب.","title":"تقييم كتب أبي الأعلى المودودي وأبي الحسن الندوي وسيد قطب","answer":"الجواب:  كلها كتب مفيدة، كتب، هؤلاء الثلاثة -رحمهم الله- كلها كتب مفيدة، فيها خير كثير، ولا تخلو من بعض الأغلاط، كل إنسان يؤخذ من قوله ويترك، ليسوا معصومين، فطالب العلم إذا تأملها عرف ما فيها من الأخطاء، وما فيها من الحق، وهم -رحمهم الله- قد اجتهدوا إلى الخير، ودعوا إلى الخير، وصبروا على المشقة في ذلك، وأبو الحسن موجود -بحمد الله- وفيه الخير الكثير، ولكن ليس معصومًا، ولا غيره من العلماء، العصمة للرسل -عليهم الصلاة والسلام- فيما يبلغون عن الله، الرسل عصمهم الله في كل ما يبلغون عن الله، وهكذا الأنبياء، أما العلماء كل عالم يخطئ ويصيب، ولكن -بحمد الله- صوابهم أكثر، وقد أفادوا وأجادوا ونفعوا الناس. يقول مالك -رحمه الله- ابن أنس، إمام دار الهجرة في زمانه: ما منا إلا راد ومردود عليه إلا صاحب هذا القبر، يعني: الرسول، عليه الصلاة والسلام. فالمؤمن يطلب العلم، وهكذا المؤمنة تطلب العلم، وكل واحد يتفقه في الدين، ويتبصر، ويسأل عما أشكل عليه، يقرأ القرآن، يقرأ السنة، يعتني حتى يعرف الحق بأدلته، وحتى يعرف الغلط إذا غلط العالم، ولا يجوز أن يقال: هذا فلان العالم الجليل يؤخذ قوله كله من دون نظر! لا، بل لابد من النظر والعناية، وعرضها على الأدلة الشرعية، فما وافقها قبل، وما خالف الأدلة الشرعية ترك، وإن كان عظيمًا، وإن كان له أجر عظيم، وإن كان مجتهدًا في الخير، وإن كان مشهورًا. نعم.","link":"https://binbaz.org.sa/fatwas/8989/تقييم-كتب-ابي-الاعلى-المودودي-وابي-الحسن-الندوي-وسيد-قطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_353/35311.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10813,"question":"تقول: إن والدتي في أغلب الأحيان لا تؤدي الصلاة كما هو مطلوب، وعندما أنبهها لذلك تغضب مني كثيرًا، فهل علي إثم في ذلك؟","title":"واجب النصيحة للأم لتساهلها في كيفية أدائها للصلاة","answer":"الجواب:  لا، أنت مأجور، تنبيهها ومساعدتها على إقامة الصلاة في أوقاتها أمر لازم، وهو من باب إنكار المنكر، ومن باب الأمر بالمعروف، فأنت مأجور في ذلك، ولو غضبت عليك، عليك بالصبر والاحتساب والكلام الطيب، والأسلوب الحسن حتى تعينها على طاعة الله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8996/واجب-النصيحة-للام-لتساهلها-في-كيفية-اداىها-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_354/35407.mp3","categories":["الدعوة والدعاة"]},{"id":10819,"question":"تقول: إن والدتي في أغلب الأحيان لا تؤدي الصلاة كما هو مطلوب، وعندما أنبهها لذلك تغضب مني كثيرًا، فهل علي إثم في ذلك؟","title":"واجب النصيحة للأم لتساهلها في كيفية أدائها للصلاة","answer":"الجواب:  لا، أنت مأجور، تنبيهها ومساعدتها على إقامة الصلاة في أوقاتها أمر لازم، وهو من باب إنكار المنكر، ومن باب الأمر بالمعروف، فأنت مأجور في ذلك، ولو غضبت عليك، عليك بالصبر والاحتساب والكلام الطيب، والأسلوب الحسن حتى تعينها على طاعة الله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8996/واجب-النصيحة-للام-لتساهلها-في-كيفية-اداىها-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_354/35407.mp3","categories":["الدعوة والدعاة"]},{"id":10870,"question":"يقولان أيضًا -في سؤال مهم فيما أتصور سماحة الشيخ-: نحن نحب التزود من معين الدين الإسلامي، لكننا نجهل الكتب المفيدة في هذا المجال، نرجو من سماحتكم ترشيح بعض الكتب الموثوقة التي تساعد على التفقه في الدين، جزاكم الله خيرًا.","title":"أفضل الكتب التي ينصح بها للتفقه في الدين","answer":"الجواب:  أعظم كتاب، وأشرف كتاب، وأصدق كتاب يعلم الدين، ويرشد إلى أحكام الله، ويحصل به الفقه في الدين كتاب الله القرآن، هو أعظم كتاب، وهو أصدق كتاب، وأشرف كتاب، أنزل على أشرف نبي -عليه الصلاة والسلام- وفي أشرف بقعة في مكة والمدينة، وفي أفضل ليلة -ليلة القدر- فنوصي السائلة وغير السائلة بالعناية بكتاب الله  نوصي جميع المسلمين رجالًا ونساءً بالعناية بالقرآن، والتفقه فيه، والإكثار من تلاوته، ومراجعة كتب التفسير لمعرفة ما أشكل من ذلك، وسؤال أهل العلم عما أشكل أيضًا هذا هو أعظم كتاب، وأنفع كتاب، وأصدق كتاب، يقول سبحانه: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، ويقول -جل وعلا-: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]، ويقول سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29]، ويقول سبحانه: وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَى لِلْمُسْلِمِينَ [النحل:89]. فالواجب على المسلمين العناية بهذا الكتاب، والإقبال عليه والإكثار من تلاوته، وتدبر معانيه، والاستفادة مما بينه ربنا سبحانه من أوامر ونواهي وقصص عمن مضى من الأمم حتى يستفيد المؤمن والمؤمنة من كلام ربنا . ومن أحسن الكتب التي تعين على فهم الكتاب كتب التفسير المعروفة المأمونة، مثل: كتاب تفسير ابن جرير، تفسير البغوي، تفسير ابن كثير -رحمة الله عليهم- تفسير الشوكاني، تفسير القرطبي، كلها كتب مفيدة، لكن أحسنها هذه الثلاثة: تفسير ابن جرير، والبغوي، وابن كثير، وكتب أخرى مفيدة، مثل: القرطبي، والشوكاني، وكتب أخرى تفيد المؤمن مع التحرز مما فيها من الغلط. كذلك كتب الحديث فيها الخير العظيم، فليس بعد القرآن خير وأصح من أحاديث الرسول ﷺ هو المعلم، والمرشد، والمبين لما بينه الله -جل وعلا- كما قال سبحانه: وَالنَّجْمِ إِذَا هَوَى ۝ مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَى [النجم:1-2] يعني محمد -عليه الصلاة والسلام- وَمَا يَنْطِقُ عَنِ الْهَوَى ۝ إِنْ هُوَ إِلَّا وَحْيٌ يُوحَى [النجم:3-4]، فهو -عليه الصلاة والسلام- مفسر لكتاب الله، ومبين لمعانيه، وخير الهدي هديه، عليه الصلاة والسلام. فالمشروع للمؤمن والمؤمنة العناية بالسنة أيضًا مع القرآن، والحرص على فهم الأحاديث الصحيحة مثل صحيح البخاري، صحيح مسلم، وهكذا بقية الكتب التي ألفها أئمة الحديث، كـأبي داود والترمذي والنسائي وابن ماجة وموطأ مالك وغيرها من كتب السنة، لكن أصح الكتب وأعظمها وأنفعها صحيحا البخاري ومسلم. فينبغي أن تكون العناية بهما أكثر، والإقبال عليهما أكمل، ولا سيما طالب العلم، وطالبة العلم الذي يميز بين الصحيح والضعيف، ويفهم المعاني، فينبغي أن يعتني طالب العلم وطالبة العلم بهذين الكتابين العظيمين أكثر من غيرهما، صحيح البخاري، وصحيح مسلم . ومن الكتب المختصرة بلوغ المرام، كتاب مفيد نافع محرر للحافظ ابن حجر، وكتاب عمدة الحديث للحافظ عبدالغني بن عبدالواحد المقدسي، كتاب مفيد عظيم، كتاب المنتقى للمجد ابن تيمية، كتاب مفيد أيضًا وعظيم، يستفيد من هذه الكتب طالب العلم، وطالبة العلم، وما أشكل من ذلك يسأل عنه الطالب أهل العلم، ويراجع الكتب التي فيها بيان الصحيح من الضعيف، وفيها بيان مسائل الخلاف، كالمغني لـابن قدامة هو كتاب عظيم الفائدة. المقدم: هذا بالنسبة للفقه. الشيخ: الفقه... وبيان الراجح من كلام العلماء فيما اختلفوا فيه؛ لأنه كتاب عظيم يبين مسائل الخلاف والأدلة والمرجح والراجح، ومثل الفروع لـابن مفلح، شرح المهذب للنووي وأشباهه من الكتب التي تذكر خلاف العلماء، وتبين الراجح، وهذا بالنسبة إلى أهل العلم بالنسبة إلى من يميز بين الأقوال، ويعرف الأدلة؛ لأنه صاحب علم، وقد تفقه في الدين، وتبصر، وعرف كلام أهل العلم في الحديث الصحيح والضعيف، ومما يرجح به الخلاف في مسائل الخلاف. أما العامي وشبه العامي فيسألون أهل العلم الذين يثقون بهم من أهل السنة، يسألونهم عما أشكل عليه، ويعمل بما يرشدونه إليه إذا لم يكن عنده بصيرة وعلم يستطيع أخذ المسائل بأدلتها من كتب أهل العلم. ومن أحسن الكتب زاد المعاد لـابن القيم وهو كتاب جامع بين الحديث والفقه جميعًا، كتاب جامع زاد المعاد لـابن القيم -رحمه الله- وإغاثة اللهفان له أيضًا، إعلام الموقعين له أيضًا، كتب عظيمة فيها أحكام، وفيها علم عظيم، وفي العقيدة كتاب التوحيد، وفتح المجيد، والعقيدة الواسطية، كتاب التدمرية لشيخ الإسلام ابن تيمية، كتاب الحموية له أيضًا، هذه كتب عظيمة في العقيدة، شرح الطحاوية لـابن أبي العز كتاب عظيم، نسأل الله للجميع التوفيق، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ! ذكرتم بعض كتب التفسير، وهي من الكتب ذات العصر القديم، هل تتفضلون بذكر شيء من الكتب التي عنيت بدراسة القرآن وتفسيره، مما ألف في العصر الحديث؟ الشيخ: منها مثل ما تقدم فإن عهده قريب، الشوكاني عهده قريب في القرن الثالث عشر، في كتب مؤلفة أخيرًا فيها مثل (في ظلال القرآن) ومثل تفسير ابن سعدي -رحمه الله- هذه كتب مفيدة، وينبغي للمؤمن بخصوص تفسير السيد قطب ينبغي للمؤمن أن يتحرز مما فيه من الأغلاط، ويأخذ ما فيه من الخير والفائدة. وهكذا بقية التفاسير التي فيها، كل كتاب في الغالب لا يخلو من شيء، مثل الجلالين تفسير الجلالين، ومثل تفسير القرطبي، ومثل غيره من الكتب التي يقع فيها بعض التأويل، ينبغي للمؤمن أن يحذر ما فيها من الأخطاء ليسأل أهل العلم عما أشكل عليه، ويستفيد منها فيما وافقت الصواب فيه. المقدم: طيب طيب.. جزاكم الله خيرًا، بعد أن ذكرتم بعض التفاسير هل تتفضلون بذكر بعض الشروح للسنة؟ الشيخ: نعم فيه شروح كثيرة مثل فتح الباري على البخاري، وشرح النووي لـمسلم، ومثل نيل الأوطار للشوكاني، هذه كتب جيدة ومفيدة، فتح المجيد في العقيدة للشيخ عبدالرحمن بن حسن لكتاب التوحيد، شرح ابن أبي العز على العقيدة الطحاوية، كلها كتب مفيدة، وشروح جيدة، ولا يخلو بعضها من شيء، مثل فتح الباري، ومثل شرح مسلم لا يخلو من بعض الأغلاط في العقيدة على مذهب الأشاعرة، لكن طالب العلم ينبذ الخطأ، ويحذر الخطأ. وهكذا ما قد يقع في نيل الأوطار، وسبل السلام شرح بلوغ المرام وغيرها من الكتب، يأخذ ما فيها من الصواب، ويستعين بها على الفقه في الدين، وما فيها من خطأ يتركه إذا بان له، وإذا أشكل عليه يسأل أهل العلم، ويتذاكر مع أهل العلم، ومع زملائه الذين لهم بصيرة، ولهم فهم حتى يتجنب الخطأ، يستفيد مما وافق الصواب، نعم. المقدم: جزاكم الله خيرًا، هذه الكتب التي تفضلتم بذكرها سماحة الشيخ يبدو أنها لفئة معينة من المتعلمين، لكن ماذا عن المبتدئ الكتب التي تنصحون المبتدئ بقراءتها؟ الشيخ: المبتدئ ينبغي له أن يقرأ الكتب المعروفة التي ألفها المعروفون بالعقيدة الطيبة، والسلامة من الأخطاء في مؤلفاتهم حتى لا يقع في شيء من الخطأ، مثل العقيدة الواسطية لشيخ الإسلام ابن تيمية، مثل كتاب التوحيد للشيخ محمد بن عبدالوهاب، مثل ثلاثة الأصول كشف الشبهات، كتب مفيدة جيدة ينبغي لطالب العلم المبتدئ يحفظها، ومثل الأربعين النووية مع تتمتها لـابن رجب خمسين حديثًا يحفظها، هذه مفيدة ومختصرة، وعمدة الحديث كذلك للطلبة يحفظونها مختصرة أربعمائة حديث وكسور، وحاجة قليلة زيادة عن أربع، يحفظها طالب العلم، حفظناها في الصغر، ينبغي أن يحفظها طالب العلم في الثانوي والمتوسط. نعم. المقدم: جزاكم الله خيرًا، وبالنسبة للفقه؟ الجواب: مثل العمدة للموفق، العمدة للموفق في الفقه. المقدم: موفق ابن قدامة؟ الشيخ: ... مختصرة وجيدة مفيدة. نعم. المقدم: بالنسبة للمذاهب الأخرى يبدو أن هذا على المذهب الحنبلي بالنسبة للمذاهب الأخرى؟ الشيخ: والله ما تأملت يعني الكتب المختصرة للمذاهب الأخرى ما حصل لي تأمل لها، فيه أشياء نسمع عنها، لكن ما أستطيع أقول فيها شيئًا،  نعم؛ لأني لم أتأملها كثيرًا. نعم. المقدم: جزاكم الله خيرًا، شيء مهم بالنسبة للناس سماحة الشيخ! قد يقولون: إن هذه الكتب لا يسهل وصولها إلينا حول نشر مثل هذه الكتب القيمة؟ الشيخ: الذي نعلم أنها الكتب كلها تباع، كلها موجودة، وكلها تباع، كلها تباع، وكلها موجودة يمكن شراؤها من المكتبات، ما نعلم شيئًا من هذه مفقود، كلها موجودة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9051/افضل-الكتب-التي-ينصح-بها-للتفقه-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_358/35805.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10876,"question":"هل كتاب الطب النبوي لـابن قيم الجوزية كتاب نافع ومفيد؟","title":"تقييم كتاب الطب النبوي لابن القيم","answer":"الجواب:  نعم، كتاب الطب لـابن القيم والذهبي كلها كتب طيبة، كذلك لـابن مفلح في الآداب الشرعية كلها كتب مفيدة فيها أشياء كثيرة عن النبي ﷺ نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9049/تقييم-كتاب-الطب-النبوي-لابن-القيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_358/35803.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10922,"question":"قال ﷺ: من رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه، وذلك أضعف الإيمان ما هو حد تغيير المنكر باليد؟","title":"حد تغيير المنكر باليد وضوابطه","answer":"الجواب:  الحديث صحيح رواه مسلم في الصحيح، وروى مثله مسلم عن ابن مسعود  مثله في المعنى، والتغيير باليد معناه: إزالة المنكر، مثل: تفريق الجماعة الذين يجلسون على منكر، يفرقهم، أو يجلسون ويتخلفون عن الصلاة في الجماعة، يفرقهم ويلزمهم بالتوجه إلى المساجد، مثل: إتلاف الصورة، مثل: إراقة الخمر، كسر المزمار، كل هذا من التغيير باليد، ولكن هذا ليس لكل أحد، إنما هو لمن يقدر كالإنسان في بيته على أولاده، والأمير على من تحت يده، والسلطان في الرعية، هو الذي يأمر من يرعى من الرعية كالهيئة وأصحاب الحسبة والشرطة ونحوهم ممن يوكل إليهم مثل هذه الأمور. أما الإنسان الذي ليس له سلطة فحسبه أن يغير باللسان وبالقلب لا باليد؛ لأنه إذا غير باليد حصل فتن وشرور ومضاربات وشيء لا تحمد عاقبته، والدولة في مثل هذه البلاد المملكة السعودية تمنع من ذلك إلا من طريق من وكل إليه هذا الأمر كالهيئات ونحوهم ممن وكل إليهم الأمر، فالمؤمن في مثل هذا ينكر بلسانه في الأسواق وينصح بلسانه، ويوجه إلى الخير بلسانه، أما بيده فيكون لأهل الحسبة ممن وكل إليهم هذا الأمر، وليس لكل فرد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9094/حد-تغيير-المنكر-باليد-وضوابطه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_361/36104.mp3","categories":["الدعوة والدعاة"]},{"id":10974,"question":"يقول هذا السائل: أسأل عن كتاب الأذكار المنتخبة من كلام سيد الأبرار للنووي سماحة الشيخ؟","title":"تقييم كتاب الأذكار للنووي","answer":"الجواب:  كتاب جيد مفيد، وفيه بعض الأشياء الضعيفة، لكنه مفيد في الجملة، يستفاد منه في الجملة نعم.","link":"https://binbaz.org.sa/fatwas/9152/تقييم-كتاب-الاذكار-للنووي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28618.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":10978,"question":"له فقرة أخرى يقول: ما حدود هجران الأخ لأخيه، وإذا هجرت ولدي ثلاث أيام بلياليهن تأديبًا له على معصية، فهل هذا جائز؟","title":"حكم هجر صاحب المعصية","answer":"الجواب:  نعم الهجر بين الإخوان حده ثلاث، لقول النبي ﷺ: لا هجرة فوق ثلاث وفي اللفظ الآخر يقول ﷺ: لا يحل لمسلم أن يهجر أخاه فوق ثلاث، يلتقيان فيعرض هذا، ويعرض هذا، وخيرهما الذي يبدأ بالسلام يعني: في الحق الذي بين الناس، حقوق الدنيا، الخصومات أو غيرها، أما إذا كان هجرًا لله من أجل بدعة، أو معاصي ظاهرة، فهذا ليس له حد، فله أن يهجره حتى يتوب، وقد هجر النبي ﷺ كعب بن مالك وصاحبيه لما تخلفوا عن غزوة تبوك بغير عذر، هجرهم خمسين ليلة -عليه الصلاة والسلام- حتى تاب الله عليهم. المقصود أنه إذا كان لحقه خصومة بينك وبينه، أو سبه، أو شتمه، أو هجره لا بأس، لكن مدته ثلاثة أيام فأقل، أما إذا كان لحق الله؛ لأنه رجل مبتدع، أو أظهر المعاصي، ولم يقبل النصيحة هذا يهجر حتى يتوب. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9156/حكم-هجر-صاحب-المعصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28622.mp3","categories":["الدعوة والدعاة"]},{"id":11042,"question":"ما حكم وجود الكتب الشرعية من تفسير القرآن الكريم، أو خلاف ذلك من الأحاديث في مكتبتي في المنزل، علمًا بأنني أقتني هذه الكتب رغبة مني في بعض الكتب القيمة المفيدة لي ولأبنائي، لكن أبنائي صغار، وأنا أنشغل كثيرًا عنها، فهل علي شيء في هجر هذه الكتب؟","title":"حكم اقتناء الكتب وعدم قراءتها","answer":"الجواب:  ليس عليك شيء تحفظ لمصلحتها، إذا جاء أحد يطالع، يستفيد منها، أولادك يستفيدون منها -إن شاء الله- أنت على خير -إن شاء الله- لا بأس بذلك، نعم.","link":"https://binbaz.org.sa/fatwas/9220/حكم-اقتناء-الكتب-وعدم-قراءتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28724.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11058,"question":"بعد هذا ننتقل إلى المملكة المغربية لنستعرض رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين من هناك، يقول: باسم عبدالله، الأخ باسم أول سؤال له يقول: ما هي الكتب التي تنصحون بقراءتها؟","title":"التعريف بأهم ما ينصح بقراءته من الكتب","answer":"الجواب:  أعظم كتاب أنصحك وأنصح غيرك بقراءته القرآن العظيم، هو أعظم كتاب وأشرف كتاب، وأصدق كتاب كتاب الله العظيم، نوصيك ونوصي الإخوان جميعًا والأخوات بالإكثار من قراءته، تدبر معانيه، كل حرف بحسنة، والحسنة بعشر أمثالها، وفيه العلم العظيم، والدعوة إلى الخير، وإلى الأخلاق الفاضلة، والأعمال الصالحة، وفيه الترهيب والتحذير من كل ما نهى الله عنه، فنوصي الجميع بالإكثار من قراءة القرآن بالتدبر، والتعقل كما قال الله سبحانه: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]، ويقول سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29]. ثم الكتب التي فيها الأحاديث الصحيحة عن النبي ﷺ إذا كنت من أهل العلم مثل كتاب البخاري ومسلم، والكتب التي ألفت في الصحيح تستفيد منها، مثل عمدة الحديث للشيخ: عبدالغني بن عبدالواحد المقدسي، ومثل بلوغ المرام فيه خير كثير، وإن كان فيه أحاديث ضعيفة، ولكنها مبينة، كتاب جيد مفيد، بلوغ المرام، منتقى الأخبار لابن تيمية المجد.  هذه كتب مفيدة وإن كان فيها بعض الضعيف، لكن يعرف الضعيف بالتنبيه عليه من المؤلف ومن الشوكاني في نيله الذي هو شرح المنتقى، وبلوغ المرام قد بين المؤلف الأحاديث الضعيفة. وتسأل أهل العلم عما أشكل عليك، ومثل رياض الصالحين كتاب جيد مفيد، تقرؤه في بيتك، وعلى إخوانك، وعلى بيتك، وبينك وبين زملائك تستفيدون. وفي العقيدة مثل فتح المجيد للشيخ: عبدالرحمن بن حسن، كتاب التوحيد للشيخ: محمد بن عبدالوهاب، كشف الشبهات له أيضًا -رحمه الله- ثلاثة الأصول كتاب جيد للشيخ: محمد بن عبدالوهاب -رحمه الله- العقيدة الواسطية لشيخ الإسلام ابن تيمية، الكتب مفيدة للطالب والطالبة، ينبغي حفظها والاستفادة منها، فتح المجيد كتاب جيد شرح كتاب التوحيد، ينبغي الاستفادة منه، هكذا كتب العقيدة المعروفة السليمة، مثل شرح ابن أبي العز على متن الطحاوية، مثل الحموية لـشيخ الإسلام، التدمرية لـشيخ الإسلام، لمعة الاعتقاد للموفق، هذه كتب جيدة في العقيدة مثل تفسير ابن كثير، كتاب مفيد في التفسير، تفسير ابن كثير -رحمه الله- والبغوي، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9236/التعريف-باهم-ما-ينصح-بقراءته-من-الكتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_367/36709.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11076,"question":"سماحة الشيخ! أمامي الحقيقة رسالة طويلة من إحدى الأخوات من السودان رمزت لاسمها بـ (ن. م. ع) الحقيقة الرسالة مرتبطة ببعضها وطويلة تقول: أراها في غاية الأهمية وأرجو عرضها على سماحة الشيخ، تذكر بأنها فتاة تخرجت من جامعة سودانية إسلامية، وتخرجت من قسم الدراسات الإسلامية، ودرست في مجال الدعوة والآن هي موجودة في قرية من قرى السودان البعيدة، تقول: أهل منطقتي في حاجة ماسة إلى الدعوة والتفقه بالدين وخاصة العقيدة، لا يعرفون عن العقيدة الصحيحة شيئًا كثيرًا، والعقائد الباطلة منتشرة بصورة كبيرة، وبحكم وجودي في هذه المنطقة هل يجوز لي أن أعمل بالدعوة إلى الله مع العلم بأنني أدعو إلى الدعوة السلفية في رفقة جماعة تدعو إلى الدعوة السلفية، وعملي يا سماحة الشيخ وسط من النساء فقط بعيدًا عن الاختلاط مع الضوابط الشرعية الأخرى من حجاب وغيره، ومع العلم بأن هذه المناطق لا تبعد عن مكان وجودي كثيرًا بل مناطق قريبة جدًا يمكن السير إليها بالأقدام، وهل يشترط يا سماحة الشيخ المحرم خاصة المسافات الصغيرة، وليست سفرًا، مع العلم بأن هذه القرية آمنة مطمئنة لا تخاف المرأة فيها على نفسها، وتذهب للدعوة مع مجموعة نساء على العربة، أو الأقدام دون اختلاط، مع مراعاة الضوابط بعد أن تأخذ الإذن من الأهل، أحيانًا للتعليم وأحيانًا أخرى للتعلم لقلة الدعاة إلى الله من الرجال، وعدم وجود الداعيات من النساء، وأهل هذه المناطق في حاجة إلى الدعوة إلى الله، ثم تذكر أيضًا تقول: وهل المقصود من القرار في قوله تعالى: وَقَرْنَ فِي بُيُوتِكُنَّ [الأحزاب:33]، عدم السماح للمرأة بالخروج من البيت مطلقًا لا للتعلم، ولا للتعليم، مع العلم بأن الرجال لا يعرفون العلم المطلوب؟ وأخيرًا هل يعني أن لا نزور أرحامنا؟ نرجو من سماحة الشيخ التفضل بالإجابة.","title":"حكم وضوابط خروج المرأة للدعوة في أوساط النساء","answer":"الجواب:  القرار المطلوب هو بقاؤها في البيت، وأن لا تخرج إلا لمصلحة وحاجة، وإذا كانت ذات زوج فبإذن زوجها، وإذا كانت تخرج للدعوة والتعليم هذه حاجة عظيمة مطلوبة، فهي مشكورة ومأجورة إذا خرجت للدعوة والتعليم والتوجيه إلى الخير، وتعليم الناس الخير، فهذا عمل صالح، هي مأمورة به، والله يقول -جل وعلا-: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا [فصلت:33]، ويقول النبي ﷺ: من دل على خير فله مثل أجر فاعله فهي مشكورة ومأجورة، ولا حرج عليها في ذلك، لكن لا تسافر إلا بمحرم، ما دام في مسافات قليلة ليس فيها سفر، فهذا عمل صالح، ومطلوب، ومشكورة عليه، ولا حرج عليها في ذلك. نعم. المقدم: كم المسافة يا سماحة الشيخ عبدالعزيز؟ الشيخ: نعم. المقدم: المسافة كم تقريبًا؟ الجواب: ما يعد سفرًا يومًا وليلة للمطية، ثمانين كيلو للسيارة تقريبًا يقال له: سفر، ثمانين كيلو، وما يقاربها. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9254/حكم-وضوابط-خروج-المراة-للدعوة-في-اوساط-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_289/28902.mp3","categories":["الدعوة والدعاة"]},{"id":11114,"question":"أيضًا تسأل عن حكم قطيعة الرحم، لأسباب مثل الغيبة والنميمة، وما أشبه ذلك؟","title":"حكم قطع الرحم بسبب الغيبة والنميمة وغيرها من المعاصي","answer":"الجواب:  لا تجوز القطيعة، قطيعة الرحم من الكبائر، يقول النبي ﷺ: لا يدخل الجنة قاطع رحم، فالواجب صلة الرحم بالكلام، أو بالزيارة، أو بالمال على حسب المستطاع، ولا يجوز للمؤمن أن يقطع الرحم، ولا للمؤمنة، من أجل الغيبة، أو النميمة، لا تجوز قطيعة الرحم، فالذي يقع في الغيبة ينصح، أو في النميمة ينصح ويوجه إلى الخير: الدين النصيحة، والله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، ويقول -جل وعلا-: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]. فالذي يغتاب الناس، وينم عليهم من أقاربك تنصحه، لا تقطعه، تنصحه، وتنكر عليه عمله، وتوجهه إلى الخير، وتستعين بأقاربه الآخرين، أو أصدقائه أن ينصحوه حتى تكون الكلمة واحدة، وحتى يحصل التعاون على الخير، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9295/حكم-قطع-الرحم-بسبب-الغيبة-والنميمة-وغيرها-من-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_368/36813.mp3","categories":["الدعوة والدعاة","الأخلاق المذمومة"]},{"id":11214,"question":"في سؤال طويل مختصره أنها تقول: أود أن أعبر في هذه الرسالة عما أشعر به في هذه الأيام من ضيق لمن حولي من الناس؛ لكثرة فجورهم -كما تقول- وقلة حيائهم، وبعدهم عن الدين، ودائمًا أتساءل في نفسي هل هؤلاء الناس هم من عرفتهم منذ عام منذ عامين منذ نعومة أظفاري؟ والإجابة قطعًا: نعم، إذًا لماذا أشعر بالغربة بينهم، فلا يعجبني سلوكهم ولا ترضيني ميولهم؛ وذلك لأنها لا ترضي الله ورسوله؟ هذا ما شعرت بأنها الإجابة الصريحة على سؤالي، ولهذا فقد بعدت عن القريبات والصديقات، فهل من كلمة تتفضلون بها تثبتني على طريق الحق إن شاء الله، جزاكم الله خيرًا.","title":"الواجب تجاه العصاة والمنحرفين","answer":"الجواب:  نعم نعم، نوصيك بالصبر، والدعاء لهن بالتوفيق والهداية، ونصيحتهن بالكلام الطيب، والأسلوب الحسن، فقد صبر الرسل عليهم الصلاة والسلام، وعلى رأسهم نبينا وإمامنا محمد عليه الصلاة والسلام، قد أوذي ورأى من الكفر والفجور ما لم تري، وصبر على هذا، وأحسن إلى الناس، ورحمهم وعطف عليهم، مع إيذائهم له عليه الصلاة والسلام، قال الله جل وعلا: فَاصْبِرْ كَمَا صَبَرَ أُوْلُوا الْعَزْمِ مِنَ الرُّسُلِ وَلا تَسْتَعْجِلْ لَهُمْ [الأحقاف:35] قال سبحانه: وَاصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا [الطور:48] قال تعالى: فَاصْدَعْ بِمَا تُؤْمَرُ وَأَعْرِضْ عَنِ الْمُشْرِكِينَ [الحجر:94]. فالمؤمن يصبر ويحتسب، والله يقول: وَاصْبِرُوا إِنَّ اللَّهَ مَعَ الصَّابِرِينَ [الأنفال:46] ويقول سبحانه: إِنَّمَا يُوَفَّى الصَّابِرُونَ أَجْرَهُمْ بِغَيْرِ حِسَابٍ [الزمر:10] ويقول النبي ﷺ: ومن يتصبر يصبره الله، وما أعطي أحد عطاء خيرًا وأوسع من الصبر فاصبري وانصحيهن، وتوجهي لهم بالكلام الطيب، واستعيني بالله، ثم بمن ترين من الأخوات الطيبات، بنصيحتهن تعاونوا على البر والتقوى يكون معك من يساعدك في النصيحة والتوجيه والإرشاد، ولا تيئسن أبدًا، الله يقول: وَلا تَيْئَسُوا مِنْ رَوْحِ اللَّهِ [يوسف:87] ويقول: لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ [الزمر:53]. فعليكن بالصبر والنصيحة والاستمرار في الدعوة إلى الله، والإرشاد مع السؤال لهن بالتوفيق، سؤال الله هن لكن أخوات، يسأل الله لهن التوفيق والهداية والصلاح، وأن يمن عليهن بالتوبة، لا تجزعن ولا تيئسن أبدًا.  المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9396/الواجب-تجاه-العصاة-والمنحرفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37303.mp3","categories":["الدعوة والدعاة"]},{"id":11230,"question":"أختنا تقول: لدي رغبة شديدة في سلوك الطريقة المثلى للتفقه في الدين، فكيف أسلكها؟ وماذا أقرأ؟ وكيف أتفقه في الدين؟","title":"الطريقة المثلى للتفقه في الدين","answer":"الجواب:  نوصيك بالعناية بالقرآن الكريم، فهو أصل كل خير، وهو أصل العلم، نوصيك بالإكثار من تلاوة القرآن، والتدبر والتعقل لمعانيه، وقراءة الأحاديث الصحيحة مثل: عمدة الحديث للشيخ العلامة عبدالغني بن عبدالواحد المقدسي ، ففيها أحاديث عظيمة صحيحة، مثل: بلوغ المرام للحافظ ابن حجر كتاب جيد، قد أوضح فيه الأحاديث الصحيحة والضعيفة، فهما كتابان عظيمان، ونوصيك أيضًا باستماع برنامج نور على الدرب الذي يذاع من إذاعة القرآن كل ليلة، نوصيك باستماع هذا البرنامج فهو مفيد جدًا، ونوصيك بسؤال أهل العلم من طريق الهاتف، من طريق المكاتبة عما أشكل عليك، وفق الله الجميع. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9421/الطريقة-المثلى-للتفقه-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37318.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11275,"question":"إذا علمت بأمر ما هل أخبر به صديقي إذ رأيت ذلك الأمر في بيته -مثلًا- هل أخبره به، أو كيف تنصحونني؟ جزاكم الله خيرًا.","title":"واجب من رأى في بيت صديقه منكراً","answer":"الجواب:  إذا رأيت شيئًا من المنكرات في بيته تنصحه بينك وبينه، تقول له: رأيت كذا ورأيت كذا ليعالج ذلك حتى يعالج الأمر الذي وقع في البيت من باب التناصح والتعاون على البر والتقوى، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9465/واجب-من-راى-في-بيت-صديقه-منكرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37516.mp3","categories":["الدعوة والدعاة"]},{"id":11346,"question":"ما هو الفرق بين الدعوة إلى الله وبين الأمر بالمعروف والنهي عن المنكر؟","title":"ما الفرق بين الدعوة والأمر بالمعروف والنهي عن المنكر؟","answer":"الجواب:  الأمر بالمعروف والنهي عن المنكر دعوة إلى الله، لكن الآمر والناهي يستطيع أن يزيل المنكر ويلزم بالمعروف إذا كان عنده قدرة والداعي يبين، الداعي إلى الله يبين الأحكام الشرعية ويرشد إليها ويحذر من مخالفتها، ولهذا جمع الله بين الأمرين فقال سبحانه: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَأُوْلَئِكَ هُمُ الْمُفْلِحُونَ [آل عمران:104]، فالداعي يبين ويرشد الناس، والآمر مع الدعوة يلزم بالحق ويمنع من المنكر؛ لأن عنده سلطان وعنده قوة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9526/ما-الفرق-بين-الدعوة-والامر-بالمعروف-والنهي-عن-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37803.mp3","categories":["الدعوة والدعاة"]},{"id":11353,"question":"أيضًا المستمع محمد عبدالعزيز محمد من المملكة الأردنية الهاشمية إربد، يسأل ويقول: ما رأي سماحتكم في درس يلقى في كل يوم جمعة وبالتحديد قبل الأذان ويمتد إلى أن يرفع الأذان، هل هذا الدرس من سنة نبينا محمد ﷺ؟","title":"حكم إقامة درس قبل أذان الجمعة","answer":"الجواب:  لا أعلم أن فيه بأسًا، لا أعلم فيه بأسًا ويروى عن أبي هريرة  أنه كان يقوم بذلك، يروى عن أبي هريرة  أنه ... يقوم بهذا الدرس قبل دخول الخطيب وإذا أذن ترك ذلك، وإن ترك الناس يقرؤون القرآن ويذكرون الله ويدعون فهذا حسن -إن شاء الله- وإن فعله بعض الأحيان فهذا أيضًا أسهل، أما الاستمرار عليه كل يوم كل يوم فلعل تركه أولى؛ لأنه قد يشغل الناس عن قراءة القرآن وعن الدعاء والضراعة إلى الله والتسبيح والتهليل ونحو ذلك، قد يملون، قد يضعفون عن سماع الخطبة أيضًا خطبة الجمعة فلعل ذلك أولى، وإذا فعله بعض الأحيان فأرجو أن لا حرج فيه كما روي هذا عن أبي هريرة . نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9528/حكم-اقامة-درس-قبل-اذان-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37805.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11365,"question":"هذا السائل رمز لاسمه بـ (خالد أ. أ) الدمام يقول: لم أتعامل مع جاري وأبتعد عنه، ولم أتحدث معه وذلك من أجل الدين وليس من أجل أي هدف دنيوي، فبماذا تنصحونني؟ جزاكم الله خيرًا.","title":"حكم هجر الجار من أجل الدين","answer":"الجواب:  إذا كانوا قد أعلنوا المعاصي أو الكفر يستحقون الهجر، لكن إذا رأيت أن تنصحهم عما وقع منهم وعدم هجرهم ورأيت أن هذا أصلح، تنصحهم توجههم إلى الخير، تأمرهم بالمعروف وتنهاهم عن المنكر؛ لأن الله سبحانه يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، ويقول -جل وعلا-: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]، ويقول ﷺ في الحديث الصحيح: من رأى منكم منكرًا فليغيره بيده فإن لم يستطع فبلسانه فإن لم يستطع فبقلبه وذلك أضعف الإيمان فإذا رأيت توجيههم إلى الخير ونصيحتهم فأنت على خير عظيم، أما إذا يئست ولم يقبلوا منك النصح فهجرهم مستحب، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9547/حكم-هجر-الجار-من-اجل-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29308.mp3","categories":["الدعوة والدعاة"]},{"id":11397,"question":"جزاكم الله خيرًا يا سماحة الشيخ، (أ. أ. أ) يقول: أيهما أفضل لطالب علم الدعوة إلى الله، أو التفرغ لطلب العلم؟ جزاكم الله خيرًا.","title":"الأفضلية لطالب العلم","answer":"الجواب:  إذا كان من أهل العلم وعنده القدرة على الدعوة، عنده علم وبصيرة؛ فالأفضل له الدعوة. أما إن كان حتى الآن ليس عنده العلم الذي يعينه على الدعوة، عنده حاجة، يتفرغ لطلب العلم، ويتفقه في الدين؛ حتى يكون أهلًا للدعوة، وإقامة الأدلة الشرعية، أما إذا كان قد رزقه الله العلم، وقد تفقه في الدين، وعنده الأدلة الشرعية، فكونه يتفرغ للدعوة مع تعليم الناس العلم في المسجد، أو في بيته؛ يجمع بين الأمرين، فهذا خير عظيم، يقرأ في الأوقات المناسبة، أو يعلم الناس، أو يقرأ على العلماء، ويقوم بالدعوة في الأوقات الأخرى، نعم.","link":"https://binbaz.org.sa/fatwas/9575/الافضلية-لطالب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29317.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11433,"question":"تارك الصلاة الذي يعرف أن تركها كفر، هل يجوز لي أن أرد السلام عليه؟ مع العلم بأني نصحته كثيرًا.","title":"حكم رد السلام على تارك الصلاة عالمًا بحكم ذلك","answer":"الجواب:  يشرع هجره، المشروع هجره، وقال بعض أهل العلم: يجب هجره وجوبًا حتى يتوب، وإذا استمريت في المناصحة؛ لأنك ترجو هدايته؛ فلا حرج من غير مخالطة، ولا بشاشة، لكن مع النصيحة، تتصل به، تخوفه من الله، تدعوه إلى إقامة الصلاة، تحذره من مغبة عمله السيئ؛ لعل الله يهديه، وبالتعاون مع إخوانك في نصيحته من أقاربه، وغيرهم، فالتعاون في هذا مع الإخوة الطيبين ينفع الله به، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9615/حكم-رد-السلام-على-تارك-الصلاة-عالما-بحكم-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_294/29409.mp3","categories":["الدعوة والدعاة"]},{"id":11434,"question":"لي عم لا يصلي، ولا يصوم، وأنصحه، ولكن لا جدوى بالنسبة لي، هل أصله؟ أم أقطع الصلة به نهائيًا؟","title":"حكم قطيعة القريب الذي لا يصلي","answer":"الجواب:  هو يستحق الهجر، وإذا وصلته ترجو أن الله يهديه؛ لأنه فقير، وصلته بالمال، أو راجعته بين وقت وآخر للنصيحة والتوجيه، فأنت على خير عظيم بهذا القصد الطيب. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9616/حكم-قطيعة-القريب-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_294/29410.mp3","categories":["الدعوة والدعاة"]},{"id":11438,"question":"له أخ يقول عنه: أخي لا يصلي إلا إذا كان والدي في المنزل، ووالدي كثير السفر، وعند سفر والدي -وأحيانًا يمضي في سفره ثلاثة أشهر- ينقطع عن الصلاة، وكثيرًا ما يحصل بيننا جدال، فما هو الحل الأمثل للتعامل معه؟ جزاكم الله خيرًا.","title":"كيفية التعامل مع الأخ الذي لا يصلي","answer":"الجواب: النصيحة الدائمة، والحرص على القيام بالصلاة، وإذا كنت أكبر منه؛ فلا مانع أن تؤدبه، أو ترفع أمره إلى الهيئة، لكن مهما أمكن أن تنصحه أنت وأقاربك الذين يحترمهم ويقدرهم، تنصحونه وتوجهونه إلى الخير، وتخبرونه أنكم ستخبرون أباه إذا رجع لعمله الرديء؛ لعل الله يهديه بأسبابكم. فإذا لم تنفع فيه النصيحة، ولم يقبل؛ فارفعوا أمره إلى الهيئة، أو إلى الإمارة الطيبة إذا كانت تنفع؛ حتى يؤدب، ويوجه إلى الخير. لكن مهما أمكن قبل الرفع إلى الهيئة أو الإمارة مهما أمكن النصيحة، والتعاون مع أقاربك في نصيحته، والوعيد أنكم تخبرون أباه، مهما أمكن هذا؛ لعله ينفع، فهو أولى، فإذا دعت الحاجة إلى رفع أمره إلى الهيئة، أو الإمارة الصالحة؛ فهذا لا بأس به، بل واجب، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9620/كيفية-التعامل-مع-الاخ-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_294/29415.mp3","categories":["الدعوة والدعاة"]},{"id":11447,"question":"أحيانًا أحاول إقناع بعض الأقرباء، والأصدقاء بترك عمل سيئ، أو القيام بواجب، ولكن أرى أن أسلوبي لا يحقق شيئًا رغم جهدي في ذلك، أرجو نصحي على الطريقة الصحيحة للدعوة إلى الله؟","title":"الطريقة الصحيحة في الدعوة إلى الله","answer":"الجواب: ترشدهم بالآيات والأحاديث إن كنت تحفظها، بأسلوب حسن، ما هو بالشدة والعنف، لا . بالكلام الطيب، والأسلوب الحسن، يا عبدالله! يا فلان! يا أبا فلان! هذا لا يجوز، الواجب عليك كذا، قال الله كذا، قال الرسول كذا، حسب المعصية، إن كان يتأخر عن الصلاة؛ توصيه بالمحافظة، وتذكر له الآيات والأحاديث، إن كان يعق والديه؛ تحذره من عقوق الوالدين، وأن ذلك من أكبر الكبائر. كذلك إذا كان يتعاطى الربا، أو الشرب المسكر؛ تحذره، وإذا كان كلامك لا يؤثر عليه؛ تستعن بالله، ثم ببعض إخوانك الطيبين، تذهب أنت وإياهم إليه، أنت وأخوك الآخر، أو عمك، أو خالك، أو بعض الجيران الطيبين؛ حتى تنصحوه؛ لعله يستجيب من الجميع، لعله يقبل الحق، نعم.","link":"https://binbaz.org.sa/fatwas/9628/الطريقة-الصحيحة-في-الدعوة-الى-الله","audio":"","categories":["الدعوة والدعاة"]},{"id":11569,"question":"بعد هذا رسالة وصلت إلى البرنامج من بريدة في القصيم، باعثها مستمع رمز إلى اسمه بالحروف (ح. م. س) أخونا رسالته مطولة بعض الشيء، يقول فيها: إنني شاب متزوج، ولي ثلاثة أولاد أعيش في بيتي، وفي بيت والدي المتوفى مع والدتي وجدتي وإخوتي، ومشكلتي تتلخص: بأن أخي الأكبر الذي يسكن معنا في البيت لا يصلي، ولا يشهد الصلاة في المسجد في كل الأوقات، ويشرب الخمر أغلب الأوقات، وعاطل عن العمل، لقد تشاجرت معه كثيرًا، ولكن لا فائدة، بل يصرح بأنه لن يصلي، ولم تفد معه النصيحة، فقد فكرت في الخروج في البيت، ولكن والدتي بكت كثيرًا، واتهمتني بالعقوق وقالت: احمد ربك حتى لا يعاقبك الله بولد مثله، فضيلة الشيخ! إنني أعيش في حيرة، فهل يجوز لي الخروج من البيت، وترك والدتي؟ بالرغم من أنني أنا الذي أصرف على البيت، وإذا تغاضيت عنه من أجل والدتي، هل أكون شريكًا في الإثم والمعاصي؟وجهوني جزاكم الله خيرًا.","title":"ما النصيحة لمن ابتلي بأخ سكير لا يصلي؟","answer":"الجواب:  الذي لا يصلي كافر -نعوذ بالله- يقول النبي ﷺ في الحديث الصحيح: بين الرجل، وبين الكفر والشرك ترك الصلاة ويقول -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر، وشرب الخمر من أقبح الكبائر، وأعظم الذنوب، والله -جل وعلا- قال في الخمر: إنما الْخَمْرُ وَالْمَيْسِرُ وَالأَنصَابُ وَالأَزْلامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ [المائدة:90] وقد ثبت عنه ﷺ: أنه لعن الخمر، وشاربها وساقيها، وعاصرها ومعتصرها، وحاملها والمحمولة إليه، وبائعها ومشتريها، وآكل ثمنها نسأل الله العافية، وقال -عليه الصلاة والسلام-: لا يزني الزاني حين يزني وهو مؤمن، ولا يشرب الخمر حين يشربها وهو مؤمن فالخمر أم الخبائث، ومن أعظم القبائح والكبائر. وننصحك أن تستمر في نصيحته، وتخويفه من الله -عز وجل- بالأسلوب الحسن، والترغيب والترهيب، وأن تستعين على ذلك -أيضًا- بسؤال الله -جل وعلا- أن يهديه، وأن يشرح صدره للحق، اسأل ربك، سل ربك أن الله يهديه، وأن الله يعيذه من شر نفسه وهواه، وأن الله يلهمه الصواب، ويوفقه لقبول الحق، فهو أخوك له حق عليك، تسأل ربك له أن الله يهديه في أوقات الإجابة: في سجودك، وفي آخر الصلاة، وفي آخر الليل، سل ربك أن الله يهديه، ويعيذه من الشيطان، وهكذا تستعين عليه أيضًا بإخوانك في الله الطيبين، الذين قد يؤثرون عليه؛ حتى ينصحوه، ويوجهوه، ولا تخرج من البيت، اجلس مع والدتك، وأحسن إليها. فإن لم تفد فيه النصيحة، ولم يقبل، فارفع أمره إلى الهيئة، أو إلى المحكمة؛ حتى يقام عليه الحد، ارفع أمره إلى الهيئة؛ لعلها تعالج الموضوع، فإن لم يحصل ذلك فالمحكمة؛ لأن هذا أمر عظيم، ترك الصلاة، وشرب الخمر أمر عظيم، فالذي يجاهر بهذا، ولا يبالي؛ لا يترك إذا لم يقبل النصيحة، نسأل الله لنا ولك وله الهداية، ولجميع المسلمين. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9752/ما-النصيحة-لمن-ابتلي-باخ-سكير-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_386/38602.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":11591,"question":"رسالة بعث بها أحد الإخوة من اليمن، بل إحدى الأخوات، تقول: (أ. م) أختنا تقول: إذا كان الإنسان يعلم بعض أموره، فهل يجب عليه أن يعلمها للآخرين؟ جزاكم الله خيرًا.","title":"ضرورة بذل صاحب العلم ما عنده للآخرين","answer":"الجواب:  الله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] ويقول -جل وعلا-: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] فالواجب على كل من عنده علم أن يعلم أصحابه، وإخوانه، وأهل بيته، وأن يناصحهم، ويوصيهم بالخير، ويأمرهم بالمعروف، وينهاهم عن المنكر حسب علمه وطاقته: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ينصح أهل بيته، ينصح إخوانه، أولاده، جيرانه حسب ما عنده من العلم المعروف؛ لأن العلم علمان:  علم معروف عام مثل: معرفة الصلاة .. بر الوالدين .. أداء الزكاة .. صيام رمضان .. تحريم الخمر .. تحريم الزنا، هذه أمور معروفة. فالواجب على الإنسان ينصح من يرى منه تساهلًا في الصلاة، أو تهمة بالزنا، أو خمرًا، أو غيرها ينصح، ينصح من حوله من أقارب .. من جيران .. من جلساء، يتقي الله في ذلك، وينصح، ويأمر وينهى. لأن هذه أمور معلومة ما فيها شبهة، أما من ليس عنده علم لا، يتعلم أولًا، المسائل الأخرى التي قد تخفى، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9774/ضرورة-بذل-صاحب-العلم-ما-عنده-للاخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_386/38620.mp3","categories":["الدعوة والدعاة"]},{"id":11609,"question":"من سوريا رسالة بتوقيع مستمع يقول: (ع. أ. و) أخونا يسأل عن كتاب (حياة الصحابة) وأورد جملة من الآثار الموجودة في ذلكم الكتاب، يسأل عن صحتها، ما هو رأي سماحة الشيخ أولًا في الكتاب؟","title":"تقييم كتاب حياة الصحابة","answer":"الجواب:  الكتاب يجمع بين الغث والسمين، بين الصحيح والضعيف، فيستفاد منه فيما صح، وتراجع الكتب الأخرى، مثل صحيح البخاري، صحيح مسلم، رياض الصالحين، الترغيب والترهيب، منتقى الأخبار، بلوغ المرام، حتى يستفيد المؤمن من هذه الكتب، وقَلَّ كتاب غير كتاب الله إلا وقد يقع فيه بعض الشيء الضعيف والغلط.  فالحاصل أن المؤمن يستفيد من هذا الكتاب ما صح وثبت. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9792/تقييم-كتاب-حياة-الصحابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38803.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11707,"question":"ننتقل بعد هذا إلى الجمهورية العربية السورية دمشق لنقرأ رسالة بتوقيع أحد الإخوة من هناك رمز إلى اسمه بالحروف (ع. ن. م) أخونا له قضيتان، بل ثلاث قضايا، يقول في القضية الأولى: إذا أردنا دعوة إنسان ما إلى الدين الإسلامي كيف نبدأ معه الدعوة، وما هي الخطوات الرئيسية حتى يستجيب هذا الإنسان ويدخل الدين الإسلامي الحنيف؟ جزاكم الله خيرًا.","title":"كيفية دعوة غير المسلم إلى الإسلام","answer":"الجواب:  الخطوة الأولى: تبين فضل الإسلام، وأن الله بعث محمدًا ﷺ بدين الإسلام الذي بعث به الأنبياء الماضين والرسل كلهم، تبين له أن هذا هو دين الحق، وأن الله بعث محمدًا ﷺ بالحق، وأن على العاقل أن يجتهد في أسباب السلامة والحيطة لدينه حتى إذا مات مات على طريقة سليمة، وعلى دين مستقيم؛ فيفوز بالجنة والنجاة من النار، توضح، تشرح له الدين الإسلامي، وأنه طريق النجاة، وأنه الصراط المستقيم، وأن جميع الأديان الأخرى اليهودية والنصرانية كلها باطلة، وليس هناك دين حق إلا دين الإسلام، إِنَّ الدِّينَ عِنْدَ اللَّهِ الإِسْلامُ [آل عمران:19] لكن بالأسلوب الحسن، باللطف، والكلام الطيب، وترغبه في ذلك، وتحرص على أنه بحمد الله ميسر، ليس فيه صعوبة، ولا آصار، ولا أغلال، بل أعمال صالحة ميسرة -بحمد الله- حتى يقبل منك إن شاء الله، ويدخل الإسلام. أما إن كان مسلمًا، لكن عنده معاصي؛ تبين له شر المعاصي، وأخطارها، وأنها من أسباب قسوة القلب، وموت القلب، من أسباب غضب الله عليك، من أسباب أن تبقى عليها حتى تموت، تحذره من البقاء عليها، تحرضه على التوبة يعني: توصيه بالتوبة، والمسارعة إليها قبل أن يموت؛ لأن بقاءه على المعاصي من أسباب غضب الله، ومن أسباب سوء الخاتمة، ومن أسباب العذاب يوم القيامة، إلا من رحم الله. نعم. المقدم: بارك الله فيكم، هذه هي الخطوة الأولى والثانية لو تكرمتم؟ الشيخ: يشرح له الإسلام إذا كان كافر يشرح له الإسلام هو كذا وكذا. المقدم: يقول: إنه غير مسلم يريد .. الشيخ: يشرح له الإسلام، الإسلام: أن تشهد أن لا إله إلا الله، وأن محمدًا رسول الله، تبين له معنى شهادة: لا إله إلا الله وأن معناها: ألا يعبد إلا الله وحده، وأن لا يدعو معه لا صنمًا، ولا نبيًا، ولا قبرًا، ولا شجرًا، ولا حجرًا يخص العبادة بالله وحده، صلاته دعاءه ذبحه نذره صومه إلى غير ذلك. وكذلك يشهد: أن محمدًا رسول الله، يعني: يشهد أن محمد بن عبدالله بن عبدالمطلب الهاشمي القرشي هو رسول الله حقًا بعثه الله إلى الناس عامة، وختم به الأنبياء، وأنزل شريعة كاملة، من تمسك بها؛ فله الجنة، ومن ضيعها وتركها؛ فله النار. ويبين له بقية أركان الإسلام الصلاة والزكاة والصيام والحج وأركان الإيمان ويوصيه بأن يبادر إلى هذه الأشياء، ويستقيم على طاعة الله ورسوله، وإذا مات على هذا؛ فله الجنة. المقدم: الله المستعان الخطوة الثالثة لو تكرمتم. الشيخ: ..... كمال للثانية، يعني: يجتهد في توصيته بالأعمال الصالحات، والحرص على حفظ الوقت عن النقص عن الأشياء الذي لا نفع فيها، والحرص على عمارة الوقت بذكر الله، بالأعمال الصالحة بالتطوع، حتى تكون هذه الأعمال الصالحة جبرًا لما قد يقع من النقص في الفرائض، ومن أسباب علو الدرجات، وكثرة الحسنات، تكون أوقاتهم معمورة بالخيرات بالصلوات بالذكر قراءة القرآن صحبة الأخيار إلى غير ذلك، الدعوة إلى الله، الأمر بالمعروف النهي عن المنكر إلى غير هذا من وجوه الخير. المقدم: جزاكم الله خيرًا، وأحسن إليكم، بعض الناس يستعجل في بعض الأمور سماحة الشيخ، فربما ذكروا مثلًا أمورًا ربما تكون فرعية، كالالتزام بالحجاب الكامل بالنسبة للنساء، وكالالتزام بإعفاء اللحية من أول وهلة، وما أشبه ذلك، هل لسماحتكم من كلمة حول هذا الموضوع؟ الشيخ: هذه فروع إذا فعلها؛ فلا بأس، وإن أخرها إلى وقت آخر؛ فلا بأس، المهم الأصول حتى يدخل في الإسلام، أما الفروع الأخرى حلق اللحية، أو قصها، وكذلك الحجاب، كذلك ما يتعلق بالختان، وما أشبه ذلك، هذه لو أجلت لئلا ينفر من الإسلام، يكون التعليم بأصول الإسلام ومبانيه العظام، فإذا دخل في الإسلام بعد ذلك يرغب في بقية أعمال الإسلام ويرغب أيضًا.  المقدم: أحسن الله إليكم.. أحسن الله إليكم، وزادكم من توفيقه.","link":"https://binbaz.org.sa/fatwas/9893/كيفية-دعوة-غير-المسلم-الى-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_392/39206.mp3","categories":["الدعوة والدعاة"]},{"id":11718,"question":"سماحة الشيخ لو تكرمتم بنصيحة لأولئك الذين يستمعون إلى الأشرطة والندوات بحيث يكون هناك تركيز حتى لا يكون الفهم مقلوبًا؟","title":"ضرورة الرجوع إلى أهل العلم لتصحيح المفاهيم المغلوطة","answer":"الجواب:  نعم على كل من يسمع الأشرطة، ويشك في شيء من معناها أن يسأل أهل العلم، بالكتابة بالهاتف، لا يسكت على شيء يجهله، أو كان صاحب الشريط غير معروف، قد يغلط صاحب الشريط، قد يكون ليس معروفًا من أهل العلم، قد يكون من الطلبة الذين ما عندهم بصيرة في العلم، فإذا سمع الرجل، أو المرأة ما يشكل عليه، أو يظن أنه خطأ، أو من إنسان غير معروف من أهل العلم يسأل، يسأل المعروفين من أهل العلم، بالمكاتبة، أو بالهاتف بالتلفون عما أشكل عليه؛ لأن الله سبحانه يقول: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43]، وروي عنه ﷺ: أن قومًا أفتوا بغير علم، فقال -عليه الصلاة والسلام-: ألا سألوا إذ لم يعلموا؟! إنما شفاء العي السؤال. فالواجب على الرجل والمرأة، وعلى طالب العلم أن يتثبت في الأمور، وأن يسأل عما أشكل عليه بالمشافهة، بالمكاتبة، من طريق التلفون، لا يتأخر عن السؤال ولا يستحي (إن الله لا يستحي من الحق) فالسؤال مطلوب، والفائدة مطلوبة، والتعلم واجب حتى يعلم الإنسان ما أوجب الله عليه، وما حرم الله عليه بالأدلة الشرعية، والعامي يسأل أهل العلم، ويستفصل عما أشكل عليه من أهل العلم، ويتحرى أهل العلم المعروفين بالعلم والفضل والورع، ولا يسأل من هب ودب ممن لا يعرفهم، ولا يعلم ورعهم ولا علمهم، ولكن يتحرى سؤال أهل العلم المعروفين، إما بالسفر إليهم وسؤالهم مشافهة، أو بالمكاتبة، أو بالهاتف (التلفون) أو بالإبراق، أو بالفاكس أي طريق يمكنه أن يستعمله في هذا الباب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9901/ضرورة-الرجوع-الى-اهل-العلم-لتصحيح-المفاهيم-المغلوطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_299/29907.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11745,"question":"هذه رسالة بعث بها مستمع من سوريا يقول: إذا أردنا دعوة إنسان إلى الدين الإسلامي كيف نبدأ هذه الدعوة؟ وجهونا حول هذا الموضوع جزاكم الله خيرًا.","title":"توجيهات في كيفية دعوة غير المسلم","answer":"الجواب:  البداءة تبدأ بترغيبه في الإسلام، وبيان أن الإسلام هو دين الله الذي بعث به الرسل، وأنزل به الكتب، وبعث به آخر الأنبياء، وخاتمهم محمد -عليه الصلاة والسلام- وأن الواجب على جميع أهل الأرض الدخول في الإسلام، والالتزام به، هذا الواجب على جميع أهل الأرض، من اليهود والنصارى والشيوعيين وغيرهم، جميع أهل الأرض، رجالًا ونساء يجب عليهم الدخول في الإسلام، واعتناقه، والتمسك به، والثبات عليه؛ لأن الله خلق الخلق ليعبدوه، وهذه العبادة التي خلقوا لها هي الإسلام الذي بعث الله به الرسل، وبعث به محمد -عليه الصلاة والسلام- وجعل شريعته ناسخة لجميع الشرائع، ناسخة لشريعة التوراة والإنجيل وجميع ما في الأرض من تعبدات، شريعة محمد صﷺ ناسخة لذلك، يجب الأخذ بها، والتمسك بها على جميع أهل الأرض. فتبين له أن الإسلام هو دين الله، وأنه هو الذي بعث الله به محمدًا ﷺ وهو دين الأنبياء قبله جميعًا، وأصله وأساسه شهادة: أن لا إله إلا الله، وأن محمدًا رسول الله، فتعلمه الشهادتين أولًا، وتعلمه معناهما، ثم الصلاة والزكاة والصيام والحج وأركان الإيمان الستة، وتفهمه معناها، وتعلمه أن عليه البراءة من جميع الأديان المخالفة للإسلام من دين النصارى وغيرهم.  عليه أن يتبرأ من كل دين يخالف الإسلام، ويؤمن بأن عيسى هو عب الله ورسوله، وكلمته ألقاها إلى مريم، وروح منه إذا كان نصرانيًا تعلمه أن عيسى هو عبدالله ورسوله، خلقه الله من أنثى بلا ذكر، قال الله له: (كن فكان)، فالواجب الإيمان بأنه عبدالله ورسوله، وليس هو الله، وليس هو ابن الله، وليس هو ثالث ثلاثة، بل هو عبدالله ورسوله، خلقه الله من أنثى وهي مريم البتول الصديقة -رضي الله عنها- وليس له أب، قال الله له: كن فكان، فعلى العبد أن يؤمن بهذا، ويصدق بهذا، ويتبرأ من طريقة اليهود و النصارى في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/9927/توجيهات-في-كيفية-دعوة-غير-المسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39308.mp3","categories":["الدعوة والدعاة"]},{"id":11749,"question":"يقول: أنا شاب في الخامسة والعشرين، وبعد بلوغي هذا السن وفقني الله إلى حفظ أكثر من نصف القرآن، وأجد في نفسي الرغبة في إلقاء الخطبة يوم الجمعة، أرجو التوجيه من فضيلتكم، وأسماء المراجع التي أستعين بها، جزاكم الله خيرًا.","title":"كتب ينتفع بها الخطيب","answer":"الجواب:  إذا كان لديك القدرة، وسمحت لك الجهات المختصة؛ فلا بأس بذلك، لكن أنصحك أن تأخذ بعض الكتب التي ألفها العلماء، وتستعين بها في ذلك، مثل فقه الخطب للشيخ: محمد بن صالح بن عثيمين، والخطب للشيخ: محمد بن عبدالوهاب -رحمه الله- والشيخ: عبدالعزيز بن عبدالله بن الشيخ، وخطب أخرى للمشايخ لا بأس تستفيد منها إذا سمحت لك الجهة المختصة، وعينتك خطيبًا، أو سمحت لك أن تخطب في أي مسجد؛ فلا بأس أن تستعين بالكتب المؤلفة في هذا الباب، وإن كان لديك قدرة، وجمعت أحاديث في الباب، وكلمات طيبة تعرضها على بعض العلماء حتى يساعدوك في هذا الشيء، وتستعين برأيهم. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9931/كتب-ينتفع-بها-الخطيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39312.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11779,"question":"يسأل أيضًا ويقول: شخص سئل عن شيء يعرفه، فحلف بالله العظيم أنه لا يدري عن ذلكم الشيء، وهو الآن نادم أشد الندم على ما فعل، ما كفارة ذلك؟ وما الشيء الذي يجب عليه فعله؟ جزاكم الله خيرًا.","title":"حكم من كتم علماً","answer":"الجواب:  عليه التوبة إلى الله من .. عليه التوبة من كتمانه العلم، قد قال النبي ﷺ: من سئل عن علم، فكتمه؛ ألجمه الله يوم القيامة بلجام من نار إلا إذا كان ذلك الشيء يخشى من الإخبار به فتنة وشرًا عظيمًا، هو معذور، فإن كتم العلم إذا كان في كتمه مصلحة أكبر من إظهاره فلا بأس، مثلما قال النبي ﷺ لـمعاذ لما أخبره بحق الله على العباد، وحق العباد على الله، قال معاذ: أفلا أبشر الناس؟ قال: لا تبشرهم فيتكلوا ثم بشر بها معاذ، والنبي ﷺ بشر بذلك، وأخبر الأمة بذلك إبلاغًا للحجة، وإقامة للحجة. فالمقصود: إذا كان إخبارك بما سئلت عنه يترتب عليه شر تراه عظيمًا، وخطيرًا؛ فأنت معذور.","link":"https://binbaz.org.sa/fatwas/9965/حكم-من-كتم-علما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39503.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11784,"question":"بعد هذا رسالة بعث بها أحد الإخوة المستمعين يسأل جمعًا من الأسئلة، فيقول مثلًا: معظم أقاربي القريبين جدًا لي متكبرون، أصلهم ويقطعون، وأعطيهم ويحرمون، ولا يقدرون للمعروف قدرًا، وإذا وجهنا لهم النصائح لا يقبلون النصح، ويتكبرون على الحق ويسفهونه، ولا أدري كيف العمل معهم، ومجالسهم كلها غيبة ونميمة، ولا أرتاح في الجلوس معهم، أرجو أن توجهوني حيث أخشى أن أتعرض للإثم جزاكم الله خيرًا.","title":"حكم صلة القريب العاصي","answer":"الجواب:  ننصحك ونوصيك بأن تستمر في النصيحة مشافهة، أو مكاتبة، وتشجع أيضًا من يرجى أنهم يتأثرون به، وينتفعون بنصيحته، تشجع من كان كذلك على نصيحتهم، كأعمامهم وأخوالهم أو آبائهم أو أمهاتهم، لقول الله سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، ولقول الله : وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3]، وقول النبي ﷺ: ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه وصلها. فهذا هو الواصل الذي يصلهم وإن قطعوا، ويحسن إليهم وإن أساؤوا، وفي الحديث الآخر أنه جاءه -عليه الصلاة والسلام- رجل.. جاء إلى النبي ﷺ رجل فقال: يا رسول الله! إن لي قرابة أصلهم ويقطعونني، وأحسن إليهم ويسيؤون إلي، وأحلم عليهم، ويجهلون علي، فقال له النبي ﷺ: لئن كنت كما قلت لكأنما تسفهم المل يعني: الملة ولا يزال معك من الله عون عليهم ما دمت على ذلك فهذا مثلك يحسن ويسيؤون إليه، فأنت أبشر بالخير، وأحسن، واصبر، ولا يزال معك من الله عوين عليهم، ما دمت على هذه الحال. وأما مجالسهم فلا تحضرها، إذا كانت المجالس فيها المنكر، فيها الغيبة والنميمة والمنكرات الأخرى إن حضرت فأنكر، فإن قبلوا منك وإلا فقم. المقصود أنك لا تحضر مجالس الشر، لكن إن حضرت؛ فانصح، ووجه، وأمر بالمعروف وانه عن المنكر، فإن قبلوا، وإلا فقم، لا تحضر، لا تبقى، بارك الله فيك، ونفع بك. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9964/حكم-صلة-القريب-العاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39502.mp3","categories":["الآداب والأخلاق المحمودة","الدعوة والدعاة"]},{"id":11799,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من اليمن محافظة حجة، باعث الرسالة مستمع من هناك، يقول في رسالته: أنا أعيش في قرية يعم فيها الشرك والجهل، وكلما نصحت أهلها لا يسمعون لنصحي، فهم يقومون بالذبح، والنذر لغير الله  ويقولون لي عندما أمنعهم، أو أنصحهم: أنت مشرك بالله، ماذا أفعل، وهل أنا على حق، وهل أبتعد عنهم، أم أبقى في القرية مع مجاهدتي لنفسي، ولهم؟ جزاكم الله خيرًا.","title":"حكم البقاء في قرية يصر أهلها على الشرك","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه. أما بعد: فننصحك أيها الأخ بالبقاء معهم، والجهاد لنفسك ولهم بالتعليم والتوجيه، والإرشاد والنصيحة؛ لعل الله أن يهديهم بأسبابك، ولك مثل أجورهم إذا هداهم الله على يديك؛ لقول النبي ﷺ: من دل على خير؛ فله مثل أجر فاعله. فاصبر واحتسب، ولا تعجل، وادع الله لهم بالهداية، وأنت على خير عظيم، هكذا صبر الرسل -عليهم الصلاة والسلام- فتأس بالرسل -عليهم الصلاة والسلام- والله يقول: إِنَّمَا يُوَفَّى الصَّابِرُونَ أَجْرَهُمْ بِغَيْرِ حِسَابٍ [الزمر:10] قد أوذي نبينا ﷺ وأوذي الأنبياء، فصبروا، فكن أنت متأسٍ بهم -عليهم الصلاة والسلام- فإذا كان أهل هذه القرية يتعاطون الشرك، ودعاء الأموات، والاستغاثة بالأموات، وأصحاب القبور، أو النذر لهم، أو الذبح لهم؛ هذا شرك أكبر، هذا دين المشركين. فالواجب عليهم ترك ذلك، والتوبة إلى الله من ذلك، وعليك أن تنصحهم دائمًا، وأن تصبر حتى يهديهم الله بأسبابك، وأنت على خير عظيم، ولا تجزع، ولا تمل، ولا تغادر القرية إلا إذا وجد من يقوم مقامك، يحصل به المقصود، وإلا تبقى في القرية، واجتهد في الدعوة، واحرص على أن تلتمس من يساعدك، ويعينك على هذه الدعوة العظيمة، يسر الله أمرك، وبارك في جهودك، وهدى أصحابك. المقدم: اللهم آمين، اللهم آمين، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9983/حكم-البقاء-في-قرية-يصر-اهلها-على-الشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42301.mp3","categories":["الدعوة والدعاة"]},{"id":11803,"question":"لي أخ في العائلة يتعامل بالربا، نصحته كثيرًا، وعندما أنصحه يقول: سوف أنتهي عن هذا الأمر قريبًا، لكنه لا زال مواصلًا، هل أقاطعه؟ أو بماذا توجهونني؟ جزاكم الله خيرًا.","title":"حكم هجر من يتعامل بالربا رغم نصيحته","answer":"الجواب:  عليك أن تستمر في نصيحته؛ لعل الله أن يهديه بأسبابك، فإن أصر على عمله القبيح؛ فلك أن تهجره إذا رأيت المصلحة في ذلك، وإن رأيت أن المصلحة تقتضي الاستمرار في النصيحة، وعدم الهجر؛ فافعل ذلك؛ لأن الهجر علاج ودواء، فإذا كان ينفع؛ فافعله، وإن لم ينفع؛ فاستمر في النصيحة والدعوة إلى الخير، واستعن على ذلك أيضًا بإخوانك الطيبين ينصحونه، ولعل الله يهديه بأسبابكم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9987/حكم-هجر-من-يتعامل-بالربا-رغم-نصيحته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42305.mp3","categories":["الدعوة والدعاة"]},{"id":11809,"question":"إحدى الأخوات المستمعات من ليبيا تقول المرسلة (منى . م. ع) من بني غازي، تسأل وتقول: في الفترة المسائية، وخاصة بعد صلاة العشاء أقوم بقراءة كتابًا من الكتب التي تعنى بالأمور الدينية، كالعبادات والسيرة والمعاملات وغيرها، هذه القراءة قد تأخذ من وقتي ساعات، وأحيانًا أقرأ حتى بعد منتصف الليل، وسؤالي: هل هذه القراءة في الكتب الدينية هي من مجالس الذكر، أم أن قراءة القرآن، والتسبيح والاستغفار أفضل، كذكر الله، وخاصة في الليل؟ جزاكم الله خيرًا.","title":"الجمع بين قراءة القرآن وكتب العلم الشرعي","answer":"الجواب:  المؤمن والمؤمنة يجمع بين هذا كله، يقرأ القرآن في وقت يتدبر ويتعقل، ويقرأ كتب العلم، وكتب الحديث الشريف، وكتب الفقه للتعلم والتفقه في الدين، فلا يكفي هذا عن هذا، ولا هذا عن هذا، فإذا قرأت في الليل قراءة لا تضرك، ولا تمنعك من قيام الليل، ولا تسبب نومك عن صلاة الفجر؛ فكل هذا طيب. وإذا كان لك زوج؛ فلابد من مراعاة خاطره ورضاه، لا تشتغلي بشيء عنه، إلا بالفريضة التي فرضها الله، والرواتب التي شرعها الله، فإذا كنت لا زوج لك؛ فالحمد لله اجتهدي في الخير، تارة في القرآن، وتارة في كتب العلم المعتمدة، مثل صحيح البخاري، وصحيح مسلم، كتب أهل العلم المعروفة مثل كتب شيخ الإسلام ابن تيمية، ابن القيم، كتب الشروح الصالحة المعروفة، السنن الأربع، موطأ مالك، سنن الدارمي، وأشباه ذلك للاستفادة إذا كان عندك علم، وإذا كان عندك نقص؛ فاسألي أهل العلم أيضًا، لا تستقلي برأيك، اسألي عما أشكل عليك، وأنت على خير عظيم، وهذا من العلم، ومن الذكر الذي شرعه الله لعباده، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9993/الجمع-بين-قراءة-القران-وكتب-العلم-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42311.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11922,"question":"إحدى الأخوات المستمعات تقول: السائلة زهور، أختنا تقول: إنها تحب الدعوة إلى الله: ولكنها تخشى إذا قامت إلى ذلك أن تصاب بالعين، إذ أنها لاحظت أن كثيرًا من الناس قد أصيبوا بذلك؛ فأصبحوا يتكاسلون عن أداء العبادة، فما هو توجيه الشيخ؟ جزاكم الله خيرًا.","title":"حكم ترك الدعوة إلى الله خوف العين","answer":"الجواب:  هذا من تثبيط الشيطان -والعياذ بالله- عليها أن تقوم بالدعوة إذا كان عندها علم، عليها أن تقوم بالدعوة مثل الرجل ....... التعليم والإرشاد في أقاربها، وفي غيرهم ترجو ما عند الله، يقول النبي ﷺ: من دل على خير فله مثل أجر فاعله، وأعظم من هذا قوله سبحانه: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ أَنَا وَمَنِ اتَّبَعَنِي [يوسف:108]، وقوله سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكََ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَن [النحل:125]، فالرجل والمرأة إذا كان عندهما علم مشروع لهما الدعوة إلى الله، الناس ....... إلى الله والصبر على ذلك، ولا تخش العين، ولا غير ذلك من الأوهام .... الشيطان، فالعين أمرها بيد الله، تتوكل على الله، وتسأل ربها العافية. والرجل كذلك يسأل ربه العافية، ولا يصير إلا الخير -إن شاء الله- فعليه أن يتكل على الله، ويفعل الأسباب، وسوف لا يرى إلا الخير، يقول صباحًا ومساء: أعوذ بكلمات الله التامات من شر ما خلق، ولا يضره شيء .......... وإذا يقول: باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات صباحًا ومساء، ولا يضره شيء، يتعاطى ما شرع الله، آية الكرسي بعد كل صلاة يقرأ: قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1]، والمعوذتين بعد كل صلاة، يكرر السور الثلاث بعد المغرب والفجر ثلاث مرات كل هذه من أسباب العافية والسلامة من شر العين وغيرها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10106/حكم-ترك-الدعوة-الى-الله-خوف-العين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42623.mp3","categories":["الدعوة والدعاة"]},{"id":11931,"question":"يقول: أنا من أسرة تتكون من أكثر من عشرين فردًا، وعندما أحثهم على الصلاة جماعة لا يستجيبوا، فأصلي في بيتي وحدي، وجهوني ماذا أفعل معهم؟","title":"حكم الإقامة بين جماعة لا يصلون في الجماعة","answer":"الجواب:  عليك أن تأمرهم بالمعروف، وأن تنهاهم عن المنكر، ومن المعروف أن يؤدوا الصلاة في الجماعة في المساجد مع المسلمين، ومن المنكر تركهم ذلك، فعليك أن تنكر عليهم ذلك، وأن تأمرهم بالمعروف، وتنصحهم دائمًا، وتخبرهم أن هذا منكر لا يجوز، وأن هذه مشابهة لأهل النفاق، قال تعالى: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى [النساء:142]. فالله أوجب على الرجال أن يصلوا في الجماعة في المساجد، يقول النبي ﷺ: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر والعذر: هو المرض والخوف الذي يمنع من الخروج، ويقول أيضًا ﷺ لشخص أعمى استأذنه أن يصلي في بيته قال له الرسول ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب أعمى ليس له قائد يلائمه، يقول النبي ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم قال: فأجب. فإذا كان الأعمى الذي ليس له قائد يؤمر بالإجابة والتوجه إلى المسجد؛ فالبصير القادر من باب أولى، وعليك أنت أن تصلي في الجماعة، لا تصل في بيتك، عليك أن تصلي في الجماعة، وأن تنصحهم دائمًا الذين معك في البيت أن يصلوا في الجماعة؛ لأن هذا هو الواجب على الجميع. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10115/حكم-الاقامة-بين-جماعة-لا-يصلون-في-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_427/42708.mp3","categories":["الدعوة والدعاة","صلاة الجماعة"]},{"id":11953,"question":"المستمع (ع. ك) بعث يسأل ويقول: إذا كان أخي لا يصلي فهل لي أن أبدي له المودة؟ علمًا بأنني قد نصحته كثيرًا؟","title":"واجب الأخ تجاه أخيه الذي لا يصلي","answer":"الجواب:  عليك أن تنصحه كثيرًا، وأن تبدي له عدم المودة والبغضاء على عمله، ويشرع لك هجره أيضًا إذا لم يتب، حتى يتوب إلى الله، ويرجع عن عمله السيئ، وهذا من باب التعاون على البر والتقوى، وعليك أيضًا أن تستعين بإخوانك الآخرين وقراباتك عليه، لعل الله يهديه بأسبابكم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10138/واجب-الاخ-تجاه-اخيه-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42817.mp3","categories":["الدعوة والدعاة"]},{"id":11964,"question":"ما هي الطريقة الصحيحة لحفظ القرآن الكريم حتى لا ينساه المسلم، وخاصة المسلمة عندما تتركه لفترة عذرها؟","title":"وسائل تعين على حفظ القرآن الكريم","answer":"الجواب:  الطريقة التي يحفظ بها كتاب الله هي العناية بقراءته، وعدم الغفلة، بحيث يجعل الرجل، أو المرأة وقتًا مناسبًا يقرأ فيه كتاب الله، ويكرر فيه محفوظه؛ حتى لا ينساه، في الليل، أو في النهار في الوقت المناسب، فهذا هو السبب الذي يعينه الله به على حفظه، أما إذا أعرض وغفل؛ هذا من أسباب النسيان، لكن يجب على المرء أن يحرص على أسباب السعادة التي شرعها الله، وأوجبها عليه، وهذا من أسباب توفيق الله له في حفظ القرآن وغيره، إذا حرص على أداء الواجبات التي فرضها الله عليه، وحرص على ترك المحارم، ثم تحرى بعد ذلك ما يعينه على حفظ القرآن، وما يعينه على الاستكثار من النوافل، وما يعينه على قضاء حقوقه، وحقوق أهله، فإن الله يعينه بذلك؛ لأنه قدم حقه، واعتنى بحقه سبحانه من أداء الفرائض وترك المحارم. فإذا رتب جزءًا من الوقت؛ ليحفظ كتاب الله، وليدرسه كثيرًا؛ فإن الله يعينه بذلك على حفظ كتابه -جل وعلا- فهو  قد رتب المسببات على أسبابها، وإنما يؤتى العبد من غفلته وإعراضه وتساهله، فإذا جد في الطلب، واجتهد فيما يسبب حفظ كتاب الله من تكرار الدراسة، وحفظ الوقت، وعدم الإعراض والغفلة، فإن الله يعينه على ذلك، مع الضراعة إلى الله وسؤاله أن يعينه، وأن يوفقه لحفظ كتابه، وأن يكفيه شر العوارض، يعني يجتهد في الدعاء، يسأل ربه أن الله يوفقه ويعينه، وأن الله يقيه شر أسباب عدم الحفظ، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10149/وساىل-تعين-على-حفظ-القران-الكريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_429/42905.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":11978,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: المرسلة منيرة عبدالله من الرياض، أختنا تسأل وتقول: أرجو أن تشرحوا لنا حديث الرسول ﷺ والذي يقول: من رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه، وذلك أضعف الإيمان.","title":"مراتب إنكار المنكر","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فهذا الحديث من الأحاديث الصحيحة، قد خرجه مسلم -رحمه الله- في الصحيح، عن أبي سعيد الخدري  عن النبي ﷺ أنه قال: من رأى منكم منكرًا؛ فليغيره بيده، فإن لم يستطع؛ فبلسانه، فإن لم يستطع؛ فبقلبه، وذلك أضعف الإيمان معناه: أن المؤمن، وهكذا المؤمنة إذا رأيا المنكر؛ وجب تغييره باليد مع الاستطاعة، كالأمير في حدود صلاحياته، كالهيئة في حدود صلاحياتها، كالأب مع أهل بيته، والأخ مع أهل بيته، على حسب القدرة، كخمر يراق، آلة لهو تكسر، وما أشبه ذلك، فإن لم يستطع؛ فبلسانه؛ يقول: يا عبدالله! هذا لا يجوز، يا أمة الله! هذا لا يجوز، الواجب ترك هذا الشيء احذروا، فالله حرم عليكم هكذا، هكذا يجب على كل مؤمن ومؤمنة، يقول الله -جل وعلا-: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] والمنكر ما نهى الله عنه ورسوله، والمعروف ما أمر الله به ورسوله، فإن لم يستطع المؤمن، أو المؤمنة الإنكار باليد، ولا باللسان؛ فبالقلب، يكره بقلبه المنكر، يعلم الله من قلبه أنه يكرهه، ويحب زواله، ولا يحضر أهله، لا يحضر معهم، المجلس الذي فيه شرب الخمر لا يحضره، فيه آلات الملاهي، فيه الغيبة والنميمة، لا يحضره، ما دام لا يستطيع الإنكار لا بيده ولا بلسانه، هذا هو معنى الحديث، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم، إذًا كون إنكار المنكر درجات ينبغي لمنكر المنكر أن يتأمل تلك الدرجات؛ حتى لا يقع في الخطأ؟ الشيخ: نعم، عليه أن يتأمل حتى يقوم بما يلزمه، إذا كان ممن يستطيع كالهيئة المخولة في حدود تعليماتها أنكرت بالفعل، الأمير، الأب مع أهل بيته، السلطان، حسب القدرة، فالذي ليس عنده قدرة على الإنكار باليد؛ ينكر باللسان، يقول: لا، هذا لا يجوز، اتقوا الله! راقبوا الله! احذروا هذا الشيء! اتركوا هذا الشيء، ونحو هذا، بالأساليب الحسنة التي يعني يترتب عليها ترك المنكر والقناعة بلزوم الحق، فإذا عجز باليد واللسان؛ بقي القلب، يكره بقلبه، ويعلم الله من قلبه كراهة المنكر، ولا يحضر أهله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10163/مراتب-انكار-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_430/43001.mp3","categories":["الدعوة والدعاة"]},{"id":12003,"question":"يقول: أرجو إرشادي إلى بعض الكتب المفيدة في مجال العقيدة؟","title":"أهم كتب العقيدة","answer":"الجواب:  أعظم كتاب القرآن العظيم هو أصل الخير كله، نوصيك بالقرآن، أكثر من تلاوته، وفيه بيان العقيدة الصحيحة، بيان أسماء الله وصفاته، وبيان توحيده، وحقه على عباده، فالقرآن هو أفضل الكتب، وأصدقها، وخيرها، وفيه الهدى والنور، فعليك بكتاب الله أكثر من تلاوته، وحفظه، وتدبر معانيه، وفيه الشفاء والكفاية. ومن الكتب الطيبة: كتاب التوحيد للشيخ: محمد بن عبدالوهاب، فتح المجيد، العقيدة الواسطية لشيخ الإسلام: ابن تيمية، كشف الشبهات للشيخ: محمد بن عبدالوهاب، ثلاثة الأصول كل هذه طيبة، إذا اقتنيتها طيبة، منهاج السنة لشيخ الإسلام: ابن تيمية، كتاب الإيمان لشيخ الإسلام ابن تيمية ، كلها كتب مفيدة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10188/اهم-كتب-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43117.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12096,"question":"المستمع (م. م) من الرياض بعث يسأل سماحتكم ويقول: إذا كنت من المتابعين لهذا البرنامج، وأقرأ كتبا فقهية كثيرة، وأتعرض لأسئلة فقهية من الناس، وأكون أعرف الإجابة عليها، فما هو الأفضل كتمان ما أعرفه؛ خوفًا من عدم الدقة في النقل، أم الإجابة حسب ما سمعت؟ جزاكم الله خيرًا.","title":"واجب الشخص إذا سئل عن مسألة يعلمها","answer":"الجواب:  الواجب أن تجيب حسب ما سمعت لا تزيد، ولا تنقص، إذا كنت ضابطًا للفتوى، تقول: سمعت فلانًا أفتى بكذا وكذا، تنسب الفتوى إلى العالم الذي صدرت منه، إلا إذا كان المستفتي يستطيع أن يذهب إلى العالم، وهو منه قريب، وأنت تخشى أن يكون في كلامك شيء من الزيادة، أو النقص؛ فلا مانع أن تحتاط، وأن ترشده إلى العالم حتى يسأله. أما إذا كنت ما عندك شك، بل عندك يقين في الفتوى؛ تخبره بها إخبارًا أنك سمعت المفتي فلانًا قال كذا وكذا، أو العالم الفلاني قال: كذا وكذا، لأجل التعاون مع أخيك على الخير، والله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] فأنت إذا أخبرته؛ فقد أعنته على الخير، وكفيته المؤونة، لاسيما وقد يكون العالم بعيدًا عنه، وقد يكون عليه مشقة في الذهاب إليه. فالحاصل: أنه لا بأس أن تخبره بالفتوى التي أتقنتها وضبطتها وحفظتها بنصها وتنسبها إلى صاحبها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10281/واجب-الشخص-اذا-سىل-عن-مسالة-يعلمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_436/43610.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12102,"question":"تقول أيضًا في هذه الرسالة: إذا كانت زيارتنا لبعض المجتمعات تسبب الغيبة والنميمة وفضول الكلام، فهل نمتنع عن الزيارة؟","title":"حكم زيارة الأقارب إذا كانت مظنة الغيبة والنميمة","answer":"الجواب:  نعم. إذا كانت الزيارة فيها الغيبة والنميمة لا تجوز هذه الزيارة، لكن إذا تيسر النصيحة للمجتمعات، أو المجتمعين بترك الغيبة والنميمة؛ فالزيارة حينئذٍ مطلوبة لما فيها من إنكار المنكر، والدعوة إلى الخير، فإذا كان الرجل، أو المرأة إذا حصلت الزيارة؛ أنكر المنكر، ودعا إلى الله، وعلم الحاضرين، واستجابوا له؛ هذا طيب، فيه خير كثير، لكن إذا كانوا لا يستجيبون، بل يستمرون في الغيبة والنميمة، المشروع لك، والواجب عليك المفارقة حينئذٍ، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10287/حكم-زيارة-الاقارب-اذا-كانت-مظنة-الغيبة-والنميمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_437/43705.mp3","categories":["الدعوة والدعاة"]},{"id":12145,"question":"من جمهورية مصر العربية محافظة قنا المستمع حمادة عبدالرحمن بعث برسالة يقول: إن لي والدة كبيرة في السن تتلفظ أحيانًا ببعض الألفاظ التي لا تليق، كيف أعدل من مسلك والدتي؟ جزاكم الله خيرًا، وهل أكون آثمة إذا وقفت موقفًا حازمًا في بعض الأوقات؟","title":"كيفية تقييم أخلاق الأم السيئة","answer":"الجواب: إن كانت قد تغير عقلها؛ فلا شيء عليها، إذا كان قد تغير عقلها؛ خرفت؛ فلا يضرها ما تقول: مرفوع عنها القلم، ولا تشتغل بها، أما إن كان عقلها معها، فالواجب عليك النصيحة والإرشاد بالكلام الطيب، والأسلوب الحسن والرفق؛ لأنها أم، والأم حقها عظيم، والواجب من برها عظيم، فعليك أن تبرها، وأن ترفق بها، وأن تخاطبها بالتي هي أحسن، حتى يقل الشر، ويكثر الخير، وحتى تحفظ لسانها عما لا ينبغي، وإذا استعنت على ذلك بإخوانك، أو بأخوالك، أو بأخواتك، أو بأبيك، أو بغيرهم في نصيحتها، فهذا طيب؛ لأن ... ممن هو أكبر منك كأخيها، أو أبيها، أو خالها، يكون أقرب إلى النجاح، فأنت استعمل ما تستطيع من النصيحة منك، ومن غيرك، ولاسيما من تحترمهم أمك من أخوال، أو أعمام، أو أب، أو جد ينصحونها عما .... عنها الشر، بارك الله فيك، وهدى والدتك. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10330/كيفية-تقييم-اخلاق-الام-السيىة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_440/44002.mp3","categories":["الدعوة والدعاة"]},{"id":12164,"question":"كيف يكون النهي عن المنكر، وعندما يكون في مجلس يغتاب فيه إنسان، هل يكتفى بالسكوت، وعدم المشاركة في الحديث، أم يجب عليه ترك هذا المجلس، خصوصًا إذا كان يصعب ترك هذا المكان؟","title":"كيفية الإنكار في مجلس فيه غيبة","answer":"الجواب:  الواجب على من حضر المنكر من الرجال والنساء أن ينكر المنكر؛ لقول الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُوْلَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71] ويقول : كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللَّهِ [آل عمران:110] ويقول : وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَأُوْلَئِكَ هُمُ الْمُفْلِحُونَ [آل عمران:104] ويقول النبي ﷺ: من رأى منكم منكرًا؛ فليغيره بيده، فإن لم يستطع؛ فبلسانه، فإن لم يستطع؛ فبقلبه، وذلك أضعف الإيمان رواه مسلم في الصحيح، وهذا يعم الرجال والنساء جميعًا. وإنكار المنكر يقال: هذا منكر، هذا لا يجوز، اتق الله يا فلان! اتقوا الله أيها الناس! دعوا هذا، هذا لا يجوز لكم، باللسان إذا كان لا يستطيع باليد، أما إذا كان له قدرة باليد كالحسبة التي أمرت بذلك، وسمح لها بذلك، وكالأمير الذي يستطيع ذلك، وكصاحب البيت ينكر على أهل بيته، وعلى أولاده بيده، مثل: إراقة الخمر .. كسر المزمار .. كسر الصورة، هذا إنكار المنكر باليد، إراقة الخمر .. تفريق الناس الذين اجتمعوا على باطل، على منكر يفرقهم ويأمرهم بالتفرق حتى لا يقع المنكر، وإذا كان غيبة يقال: هذا حرام، لا يجوز لكم أن تغتابوا أخاكم، ولا أختكم في الله، الغيبة محرمة، والله يقول سبحانه: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] ، فإذا حضرت المرأة، أو الرجل مجلسًا فيه غيبة؛ وجب الإنكار مع الاستطاعة، وقال: هذا لا يجوز، هذا حرام، اتقوا الله يا ناس! توبوا إلى الله، ارجعوا إلى الله، دعوا عرض إخوانكم عرض أخواتكم، وإذا كان لا يستطيع يقوم لا يجلس مع أهل المنكر، يقوم عنهم ويغادر المجلس الذي فيه المنكر، الذي لا يستطيع تغييره، فإن استطاع تكلم، وأنكر المنكر بكلامه، فإن أجابوا وامتثلوا؛ فالحمد لله، وإلا غادر المكان، وابتعد عن محل المنكر، وليس له أن يغير بيده على وجه يحصل فيه فساد، وما هو أنكر، بل يكون هذا لغيره ممن أذن له بذلك من جهة الدولة، ومن جهة المسؤولين عن هذا الأمر، أما من لم يؤذن له فإنه ينكر باللسان، ويقول: قال الله: كذا، قال الرسول ﷺ: كذا، إذا كان عنده علم، إذا كان على بصيرة لا ينكر إلا على بصيرة. أما الجاهل الذي لا يعرف الحكم؛ فلا يتكلم، ولكن ما دام يعلم الحكم، ويعلم الحكم الشرعي، فينكر بالكلام الطيب، والأسلوب الحسن، وإقامة الأدلة، لعل الله يهدي به من فعل المنكر؛ حتى يدع المنكر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10350/كيفية-الانكار-في-مجلس-فيه-غيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_442/44202.mp3","categories":["الدعوة والدعاة"]},{"id":12211,"question":"إحدى الأخوات المستمعات من مدينة الطائف تقول: أختكم في الله نالة العسيري بعثت برسالة ضمنتها أربعة وعشرين سؤالًا، في أحد أسئلتها تسأل وتقول: ما حكم الأمر بالمعروف والنهي عن المنكر؟ وكيف يكون تغيير المنكر بالقلب كما ورد في الحديث المعروف مع التوضيح بالأمثلة ما أمكن؟ جزاكم الله خيرًا.","title":"حكم النهي عن المنكر وبيان ضابط الإنكار باليد واللسان","answer":"الجواب:  الأمر بالمعروف والنهي عن المنكر فرض على المسلمين رجالًا ونساء، وهو من أهم واجبات الإسلام، والمصلحة تدعو إلى ذلك، والناس في حاجة إلى القيام بهذا الواجب، قال الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُوْلَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71] هذا يدل على أنه فرض على الجميع، على المؤمنين والمؤمنات، وقد قال تعالى: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنََ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللَّهِ [آل عمران:110]، وقال : وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَأُوْلَئِكَ هُمُ الْمُفْلِحُونَ [آل عمران:104]. فالواجب على المسلمين -ولا سيما العلماء والأمراء والأعيان- الواجب عليهم أن يأمروا بالمعروف، وأن ينهوا عن المنكر، وهكذا يجب على النساء ولا سيما من لها أمر، ومن لها قدرة؛ فإن هذا متعين على الجميع، تأمر أهل بيتها، تأمر بناتها، خدمها، تأمر أخواتها، تأمر من ترى يقع منه المنكر، تأمره بالمعروف، وتنهاه عن المنكر، حتى تأمر الرجال، كما أن الرجل يأمر المرأة بالمعروف، وينهاها عن المنكر، كذلك المرأة تأمر الرجل زوجها وأخاها وابنها وغيرهم، تأمرهم بالمعروف، وتنهاهم عن المنكر، هذا واجب على الجميع، لكن بالكلام الطيب، والأسلوب الحسن الذي يرغب في الحق، ويسبب قبوله، ولا ينبغي الشدة في هذا؛ لأنها قد تنفر من قبول الحق، يقول الله -جل وعلا-: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]، ويقول سبحانه: وَلا تُجَادِلُوا أَهْلَ الْكِتَابِ [العنكبوت:46] وهم اليهود والنصارى وَلا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيََ أَحْسَنُ إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ [العنكبوت:46]، يعني إلا من ظلم فله جواب آخر، وقال تعالى: فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لانْفَضُّوا مِنْ حَوْلِكَ [آل عمران:159]. فالآمر والناهي يأمران بالمعروف .. يأمر بالمعروف، وينهى عن المنكر بالأسلوب الحسن، والكلمات المناسبة التي تدعو إلى قبول الحق، وترغب في الخضوع للاستجابة والإنكار ثلاث مراتب كما بينه النبي -عليه الصلاة والسلام- يقول -عليه الصلاة والسلام-: من رأى منكم منكرًا؛ فليغيره بيده، فإن لم يستطع؛ فبلسانه، فإن لم يستطع؛ فبقلبه، وذلك أضعف الإيمان. فباليد للأمراء، والرؤساء، وشيوخ القبائل، والهيئة التي أسند إليها ذلك، عليها أن تنكر باليد لإراقة الخمر، وتفريق المجتمعين على باطل، أمر الناس بالقوة إلى الصلاة، إذا أذن المؤذن أن يقوموا إلى الصلاة إلى أشباه ذلك، وهكذا صاحب البيت يأمر أولاده على بيته، وينكر عليهم المنكر باليد، وهكذا صاحبة البيت تنكر بيدها إذا رأت المنكر على أهل بيتها، إذا كان لها سلطان في البيت بإراقة الخمر إذا وجدته، بكسر آلات اللهو، إلى غير هذا من الإنكار باليد، إتلاف الدخان إذا وجد في البيت، إلى غير هذا إذا كان لها سلطان، قدرة كما يفعل الرجل، فمن عجز عن هذا كغالب الناس، وسائر الناس ينكر باللسان، ولا يقدم بيده إذا كان ذلك يسبب فتنًا ونزاعًا وشرًا بينه وبين الناس، بل يدع هذا لولاة الأمور، ومن أسند إليه الأمر، ولكن ينكر باللسان فقط، يا أخي! اتق الله، هذا لا يجوز، يا أمة الله! هذا لا يجوز، يرى رجلًا يتعاطى الخمر؛ ينكر عليه، يقول: هذا لا يجوز منكر حرام، يرى امرأة متبرجة سافرة في الأسواق؛ ينكر عليها، يقول: يا أمة الله اتقي الله، احتجبي، اتركي التبرج، يرى إنسانًا يسب، يتكلم بكذب وفحش؛ فينكر عليه، ويقول: يا عبدالله! اتق الله، لا يجوز السب والفحش، هكذا ينكر باللسان ما سمع من المنكر، أو شاهد من المنكر، لا فرق بين الرجل والمرأة في ذلك. أما من عجز عن ذلك لا يستطيع إنكاره لا باللسان ولا بالقلب ولا بالفعل، يخشى أن يضرب، أو يقتل، أو يسجن، ما يستطيع أن يتكلم في أي مكان؛ فإنه ينكر بقلبه، يكره المنكر بقلبه، ويفارق المكان، هذا إنكار بالقلب، يكره بقلبه المنكر ويتغير، يعلم الله من قلبه إنكاره والتغير عند رؤية المنكر، ويغادر المكان، إذا استطاع أن يغادر المكان؛ غادر المكان، ترك المكان؛ حتى لا يشاهد المنكر، هذا هو الإنكار بالقلب، كراهة المنكر، وبغضه، ومحبة إزالته، والمغادرة إذا استطاع أن يغادر المكان؛ حتى لا يشهد المنكر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10397/حكم-النهي-عن-المنكر-وبيان-ضابط-الانكار-باليد-واللسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_445/44506.mp3","categories":["الدعوة والدعاة"]},{"id":12212,"question":"حول الموضوع أيضًا تسأل أختنا وتقول: هل إذا قام الناس بالأمر بالمعروف والنهي عن المنكر يسقط الإثم عن الباقين، وهل يعد ترك هذا الأمر من الكبائر؟","title":"متى يكون الأمر بالمعروف والنهي عن المنكر فرض كفاية؟","answer":"الجواب:  نعم، إذا قام المسلمون في أي بلد بإنكار المنكر، قامت جماعة؛ سقط الإثم عن الباقين في البلد؛ لأن المقصود حصل، فإذا كان جماعة تصدوا لهذا الأمر، وأنكروا المنكر، وأزالوه؛ حصل لهم الأجر العظيم، وسقط الإثم عن الباقين في القرية، أو البلد، أو في القبيلة، لكن يبقى على القرية الثانية، وعلى المدينة الثانية واجبها، كل مدينة، وكل قرية، وكل قبيلة مسؤولة، فإذا قام جماعة في بلد من البلدان، أو قرية من القرى، أو قبيلة من القبائل بإنكار المنكر، وزال على أيديهم؛ سقط الإثم عن الباقين، وفاز المنكرون بالأجر العظيم، والخير الكثير، وهكذا كل قرية، وكل بلد، وكل قبيلة عليها أن تقوم بالواجب، وإذا قام به بعضها؛ سقط الإثم عن الباقين، نعم. المقدم: إذًا هو فرض كفاية والحالة هذه؟ الشيخ: هو فرض كفاية، لا، لكن إذا كان في مكان ما فيه إلا هو، ما في من ينكر له؛ وجب عينًا، يعني شاهد المنكر في حي من الأحياء ما عنده أحد، أو في قبيلة من القبائل ما عنده أحد ينكره؛ وجب عليه أن ينكره إذا استطاع ذلك بيده، أو لسانه، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا. من قسم هذا الأمر إلى ثلاثة أقسام -سماحة الشيخ- وقال: إن الإنكار باليد للسلطة، والإنكار باللسان للعلماء، والإنكار بالقلب لعامة الناس، ماذا تقولون؟! الشيخ: لا، ما هو بصحيح، ليس بصحيح؛ الإنكار باليد لمن قدر حتى غير العلماء، حتى غير الأمراء، من جعله له الأمراء كالهيئة التي تعين في البلاد لها ما عين لها من الإنكار باليد، وهكذا لو جعلوا لغير الهيئة أشخاصًا معينين غير الهيئة ينكرون لهم ذلك.  فالمقصود: أن من قدر باليد أنكر من جهة الأمراء، أو في بيته وقبيلته، المقصود: الحكم مناط بالاستطاعة، كما قاله النبي -عليه الصلاة والسلام- سواء كان شيخ قبيلة، أو أميرًا، أو رئيس حارة يستطيع أن يفعل ذلك بنفسه، أو قد وكل له ذلك من جهة ولاة الأمور؛ فهذا يستطيع بنفسه، وهكذا صاحب البيت الذي هو رئيس البيت، أو صاحب البيت يستطيع أن ينكر على أهل بيته بيده ما وقع عنده من المنكر، ثم البقية ينكرون باللسان، سواء علماء وإلا ما هم بعلماء حتى العامة ينكر باللسان إذا رأى منكرًا؛ لأن المنكرات بعضها ظاهر ما هو بخفي يعلمه العامة والخاصة، مثل تبرج النساء معروف عند الجميع، مثل السب والشتم معروف أنه منكر عند الجميع، مثل التخلف عن الصلاة كونه يجلس وقد أذن المؤذن وهو جالس، ما يقوم يصلي، يعرفه العامة والخاصة؛ ينكر عليه، وهكذا ما أشبه ذلك: الخمر معروف عند الجميع إذا عرف هذا المؤمن، ولو ما هو بعالم، عرف أن هذا منكر، وأنه يشربه هؤلاء ينكر عليهم، مثل حلق اللحية منكر معروف، يقول: يا أخي! اتق الله، أوفر لحيتك، لا تحلقها، لا تقصها، يقول النبي ﷺ: قصوا الشوارب، وأعفوا اللحى قصوا الشوارب، ووفروا اللحى؛ خالفوا المشركين مثل إسبال الثياب منكر معروف، يعرفه الخاصة والعامة، وإذا قال لأخيه: يا أخي! اتق الله؛ ارفع ثيابك لا تسبل هذا كلام حق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10398/متى-يكون-الامر-بالمعروف-والنهي-عن-المنكر-فرض-كفاية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_445/44507.mp3","categories":["الدعوة والدعاة"]},{"id":12280,"question":"سماحة الشيخ! يتعب كثير من المسلمين فيأتون إلى الديار المقدسة لأداء العمرة، أو لأداء الحج، لكنهم لا يستعدون لمعرفة الأحكام قبل التحرك من أماكنهم، هل تنصحون بشيء نحو هذا؟","title":"نصيحة في وجوب معرفة أحكام الحج والعمرة قبل النسك","answer":"الجواب: نعم الواجب على المؤمن إذا أراد الحج والعمرة أن يسأل أهل العلم في بلاده، أو في طريقه، يسألهم أهل العلم المعروفين المشهورين بالعلم والفضل ماذا يفعل، وإذا كان هناك منسك قد عرف أنه طيب، وأنه من مناسك أهل العلم؛ يستفيد منه، قد كتبنا في هذا منسكًا مختصرًا سميناه: التحقيق والإيضاح لكثير من مسائل الحج والعمرة والزيارة على ضوء الكتاب والسنة، وهو موجود مطبوع بالعربية، وغيرها يستفاد منه في هذا الباب، وهكذا المناسك الطيبة التي ألفها العلماء يستفاد منها. المقصود: أن على من أراد الحج والعمرة وهو ليس عنده علم أن يسأل أهل العلم؛ حتى تكون عنده يعني: حصيلة علمية يستفيد منها في حجه وعمرته قبل السفر، وإذا وصل إلى مكة كذلك يسأل أهل العلم ويأتي محل التوعية في الحج التابعة لنا يأخذ منهم المناسك منسكًا يستفيد منه، ويسأل الدعاة هناك عما أشكل عليه موجود في مكة الحمد لله وقت الحج، وهم جماعات كثيرة للدعوة في إمكانه أن يأتي محل التوعية في العزيزية، أو في منى، أو في عرفات يسألهم، عليه أن يأتيهم، ويسألهم عما أشكل عليه، ويطلب المنسك أيضًا حتى يعطى إياه، ويستفيد منه، نسأل الله للجميع الهداية. نعم.","link":"https://binbaz.org.sa/fatwas/10480/نصيحة-في-وجوب-معرفة-احكام-الحج-والعمرة-قبل-النسك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_451/45105.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12299,"question":"رسالة وصلت إلى البرنامج من تبوك وقعت إحدى الأخوات في نهايتها بقولها: أختكم في الله أم هديل، أم هديل تقول: أرجو من سماحة الشيخ أن يذكر لنا أهم الكتب التي تتحدث عن العقيدة والتوحيد، حيث لنا أمل في أن تكون شاملة وافية، حتى نكون على بينة ويقين؛ لأننا في حياتنا اليومية نردد كثيرًا من الألفاظ، أو الأفعال والمعتقدات التي تنقض التوحيد دون أن نشعر بذلك، مثلًا: الحلف بغير الله، وكذلك: التمائم، والاعتقاد بالأولياء، وما رأيكم في كتاب التوحيد الذي هو حق الله على العبيد، هل تنصحوننا بشرائه؟ جزاكم الله خيرًا.","title":"أهم كتب العقيدة الإسلامية الصحيحة","answer":"الجواب:  نعم، ننصح كل مسلم بشرائه، وكل مسلمة أيضًا كتاب (التوحيد) للشيخ الإمام محمد بن عبدالوهاب -رحمة الله عليه- وهو كتاب جيد مفيد، جمع فيه الأدلة من الكتاب والسنة على أشياء كثيرة من أمور الشرك، وأمور البدع والأشياء المحرمة، فهو كتاب مفيد جيد، ننصح باقتنائه وبحفظه. وهكذا شرحه المسمى: (فتح المجيد) لحفيده الشيخ عبدالرحمن بن حسن نوصي أيضًا باقتنائه وهو شرح مفيد. وهكذا شرحه الثاني: (تيسير العزيز الحميد) لحفيده الشيخ سليمان بن عبدالله بن محمد، فهو أيضًا شرح مفيد. وننصح أيضًا بكتاب: (كشف الشبهات) للشيخ محمد بن عبدالوهاب -رحمه الله- وهو كتاب مفيد أيضًا. وهكذا: (ثلاثة الأصول)، و(القواعد الأربع) للشيخ محمد، وهو كتاب مفيد ومختصر. وهكذا (القاعدة الجليلة في التوسل والوسيلة) لشيخ الإسلام ابن تيمية كتاب مفيد، وهكذا: (العقيدة الواسطية) له أيضًا كتاب مفيد في العقيدة الإسلامية السنية.  وننصح أيضًا بكتاب: (زاد المعاد في هدي خير العباد) للعلامة ابن القيم -رحمه الله- وهو كتاب عظيم، قد اشتمل على بيان العقيدة الصحيحة، والسيرة النبوية، وأحكامًا كثيرة في الصلاة وغيرها، وهو كتاب جيد ومفيد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10499/اهم-كتب-العقيدة-الاسلامية-الصحيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_453/45305.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12312,"question":"المستمع (بشير . ح. ح) من ليبيا بعث برسالةٍ ضمنها عددًا من الأسئلة، عرضنا بعضًا منها في حلقاتٍ مضت، وفي هذه الحلقة يسأل ويقول: أخي الأصغر مني، وهو بالغٌ، تاركٌ للصلاة، فهو لا يُصلي إلا صلاة الجمعة، ونصحته، ولكن بدون فائدةٍ، ماذا أفعل تجاهه؟ أرجو الإفادة، جزاكم الله خيرًا.","title":"كيفية التعامل مع الأخ الذي يترك الصلاة","answer":"الجواب: الواجب عليك نصيحته، والتكرار في ذلك، والجد في ذلك، لعل الله يهديه بأسبابك، ولا تملّ، ولا تيأس؛ لأن المسلم عليه النصيحة لغيره، وعليه التوجيه، والله يقول -جلَّ وعلا-: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] ويقول سبحانه: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ [فصلت:33].  فأحسن إليه بالنصيحة، واجتهد، وليكن ذلك عن صدقٍ، وعن عنايةٍ، تبين له أن ترك الصلاة كفرٌ، وأنه ضلالٌ، وأن الواجب على كل مُكلَّفٍ أن يتقي الله، وأن يُؤدي الصلاة إذا كان ينتسب إلى الإسلام، وإلا فلا صحةَ لدعواه الإسلام، فإن إسلامه بدون صلاةٍ ليس بإسلامٍ، يقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلمٌ في \"صحيحه\" ويقول -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمَن تركها؛ فقد كفر.  فالواجب على أخيك أن يتقي الله، وأن يصلي، وعليك أن تنصحه كثيرًا، وتُبلغه كثيرًا، لعل الله يهديه بأسبابك، فإن أصرَّ ولم يُبالِ؛ فعليك أن تهجره إذا رأيت الهجر أصلح، وإن رأيت عدم الهجر أصلح، وأن تستمر معه في الدعوة والتوجيه، مع كراهة عمله، وإظهار الكراهة والغضب على عمله؛ فلعل الله يهديه بأسبابك، وإن رأيت هجره أصلح، والبعد عنه؛ لأنه لم يمتثل، ولم يقبل النصيحة، ورجوت أن هذا الهجر يُؤثر عليه، لعل الله يهديه بأسباب ذلك؛ فاهجره، فالهجر الذي يفيد مطلوبٌ، مشروعٌ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10512/كيفية-التعامل-مع-الاخ-الذي-يترك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_454/45403.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":12354,"question":"مستمعة من الجزائر بعثت تسأل وتقول: لي أخ تارك للصلاة، مع أنه كان في صغره يحافظ عليها، ولكنه الآن تركها، وقد نصحته، وخوفته من تركها، فما هو توجيهكم، وبماذا تنصحونه؟ وجزاكم الله خيرًا.","title":"ما النصيحة تجاه الأخ التارك للصلاة؟","answer":"الجواب:  نسأل الله لنا وله الهداية، ننصح أخوك بأن يؤدي الصلاة، ويتقي الله، ويتوب إلى الله مما سلف، فإن ترك الصلاة كفر أكبر، يقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة ويقول -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. فالواجب عليه أن يصلي، وأن يتوب إلى الله مما سلف، وعليك بنصيحته، والاستمرار في نصيحته، فإن أصر؛ فالواجب هجره، المشروع لك هجره؛ حتى يتوب إلى الله، وإذا أمكن؛ رفع أمره إلى الهيئة، أو إلى المحكمة حتى ..... ما يلزم شرعًا، فعليك أن تفعلي ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10560/ما-النصيحة-تجاه-الاخ-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_399/39918.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":12455,"question":"من ليبيا رسالة بتوقيع إحدى الأخوات المستمعات تقول: المرسلة فائزة أحمد. الأخت فائزة تسأل وتقول: أمي لا تعرف القراءة، ولا تحفظ شيئًا من القرآن الكريم، وأنا حاولت تعليمها شيئًا من القرآن، لكنها تنسى، فما هو توجيهكم؟","title":"الحث على تعليم من لا يحسن قراءة الفاتحة","answer":"الجواب:  توجيهي لك أن تجتهدي في تعليمها، وإرشادها حتى تتعلم -إن شاء الله- ويكون لك مثل أجرها، فإن لم يتيسر ذلك؛ صحت صلاتها، والحمد لله: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وإذا تيسر تعليمها بدل القراءة: (سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله) كفى ذلك عند العجز عن تعلم الفاتحة، ولكن اجتهدي أنت ومن عندك من الأخوات الطيبات في تعليمها، وإرشادها؛ لعلها تستفيد، ويكون لكن مثل أجرها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10679/الحث-على-تعليم-من-لا-يحسن-قراءة-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_404/40420.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12460,"question":"يقول: دعوت أحد الأصدقاء للصلاة، فقال لي: عندما يهديني الله سأصلي، فدخلنا في مناقشة، فقال: إِنَّكَ لا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [القصص:56] واستمرينا في جدال حول هذا الموضوع، ما هو توجيه سماحتكم لنا في مثل هذا الحال؟ جزاكم الله خيرًا.","title":"واجب من دعي إلى فعل الواجبات وترك المنهيات","answer":"الجواب:  الواجب على من دعي إلى أداء الواجب أن يقول: سمعًا وطاعة، وأن يتقي الله، وأن يبادر إلى الاستجابة، ولا يقل: إذا هداني الله، الله أمرك بهذا وأرشدك إلى هذا، فقال: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] قال: وَأَقِيمُوا الصَّلاةَ [البقرة:43] فالواجب عليك إذا دعاك أخوك إلى الصلاة أن تقول: سمعًا وطاعة، وأن تبادر إلى الصلاة في المسجد مع إخوانك المسلمين.  وهكذا إذا دعاك إلى أداء الزكاة، أو صوم رمضان، أو ترك بدع، أو ترك شرب مسكر، أو ما أشبه ذلك، لا تقل: إذا الله هداني، لا قل: سمعًا وطاعة، جزاك الله خيرًا، وعليك الامتثال؛ لأن الله أمرك بهذا، وأمره هو أن ينكر عليك، ويعلمك، قال الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71] وذم الله من استكبر، فقال -جل وعلا- ذامًا لمن استكبر عن الحق: وَإِذَا قِيلَ لَهُ اتَّقِ اللَّهَ أَخَذَتْهُ الْعِزَّةُ بِالإِثْمِ فَحَسْبُهُ جَهَنَّمُ وَلَبِئْسَ الْمِهَادُ [البقرة:206] نسأل الله العافية. فالواجب عليك إذا قال لك أخوك: صل، أو دع صحبة الأشرار، أو دع الربا، أو دع الفواحش، أو أد الزكاة، أو ما أشبه ذلك أن تقول: جزاك الله خيرًا، إن شاء الله، أسأل الله أن يعينني، أسأل الله أن يهديني، جزاك الله خيرًا، أثابك الله، تشكره، تدعو له، وتبادر إلى الحق، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10676/واجب-من-دعي-الى-فعل-الواجبات-وترك-المنهيات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_404/40417.mp3","categories":["الدعوة والدعاة"]},{"id":12511,"question":"يسأل عن الأسلوب الذي يلتزمه المسلم حتى يسهل عليه حفظ القرآن الكريم؟","title":"الطرق والوسائل الميسرة لحفظ القرآن","answer":"الجواب:  أولًا: إخلاص النية لله، يكون قصده وجه الله... بتعلم القرآن، وبحفظ القرآن، يخلص لله في ذلك حتى يعينه مولاه : وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. فنوصي كل مؤمن ومؤمنة بالإخلاص في حفظ القرآن، وفي تعلم القرآن، وفي تعلم العلم، وفي جميع الأعمال الشرعية، نوصي الجميع بالإخلاص لله، وأن يكون القصد وجه الله، والدار الآخرة، ثم نوصيه بالجد والمثابرة في حفظ القرآن، وتحري الأوقات المناسبة في الليل، أو في النهار؛ لأن كل إنسان له ظروفه، فنوصي كل واحد يريد حفظ القرآن الكريم، أو الإكثار من تلاوته، نوصي كل واحد أن يتحرى الأوقات المناسبة، التي يكون فيها قلبه فارغًا يستطيع التدبر والتعقل، حتى يكون حفظه، وحتى تكون قراءته مثمرة، فينظر في ليله، وفي نهاره، ويختار الوقت المناسب لحفظ ما تيسر، أو لقراءة ما تيسر، بقلب حاضر، مقبل على الله، يريد الله، والدار الآخرة، يتدبر ويتعقل، كما قال الله سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29] وقال : أَفَلا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا [محمد:24]. فالمؤمن والمؤمنة يتحريان الأوقات المناسبة لحفظ القرآن، ولتلاوة القرآن حتى تكون القلوب حاضرة، وحتى يستفيد المؤمن والمؤمنة من قراءته، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10719/الطرق-والوساىل-الميسرة-لحفظ-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40713.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12513,"question":"يسأل سماحتكم فيقول: ما هي الكتب المفيدة التي إذا اعتمد عليها طالب العلم كفته عن البقية من الكتب؟","title":"الكتب الواجب على طالب العلم الاهتمام بها واقتناؤها","answer":"الجواب:  أعظم كتاب، وأهم كتاب: القرآن العظيم، هو أعظم الكتب، القرآن العظيم هو أهم كتاب، وأعظم كتاب، وأنفع كتاب، كتاب الله فيه الهدى والنور، كما قال الله سبحانه: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] وقال -جل وعلا-: وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَى لِلْمُسْلِمِينَ [النحل:89] وقال سبحانه: وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ [الأنعام:155] فأعظم الكتب، وأصدقها، وأنفعها، وأنفسها، وأكملها كتاب الله، فنوصي كل مسلم، وكل مسلمة في جميع الدنيا، نوصيهم بالعناية بالقرآن، نوصي الجميع بالعناية بكتاب الله حفظًا، وتدبرًا، وتعقلًا وعملًا، وسؤال أهل العلم عما أشكل في ذلك، وإذا كان طالب علم ينظر كتب التفسير حتى يستفيد مثل كتاب ابن جرير تفسير ابن جرير، تفسير ابن كثير، تفسير البغوي، تفسير الشوكاني، تفسير القرطبي، حتى يستفيد من هذه التفاسير من معاني كلام الله -عز وجل- يتعلم، ويستفيد من هذه الكتب. وكذلك كتب الحديث، كـالبخاري ومسلم والسنن الأربع، هذه الكتب العظيمة يستفيد منها، مثل منتقى الأخبار لابن تيمية، بلوغ المرام للحافظ ابن حجر، عمدة الحديث للشيخ عبدالغني بن عبدالواحد المقدسي، هذه كتب الحديث المهمة، وهكذا موطأ مالك، ومسند أحمد، وسنن الدارمي، كلها كتب مفيدة عظيمة. ولكن إذا كان ليس عنده علم يسأل أهل العلم، لا يعتمد على رأيه، بل طالب العلم الذي عنده فقه في الدين، وعنده علم يستفيد من هذه الكتب، وإذا كان عاميًا ليس عنده علم يتوصل به إلى معرفة الحديث الصحيح، والضعيف؛ فإنه يسأل أهل العلم، يسأل أهل العلم عما أشكل عليه، ويعتني بالقرآن، ويكثر من تلاوة القرآن بالتدبر والتعقل، ويسأل ربه التوفيق والهداية، والإعانة.  أما أهل العلم فإنهم ينظرون في هذه الكتب، ويستفيدون منها في تفسير كتاب الله، وفي معرفة الصحيح عن رسول الله ﷺ من الأحاديث، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10709/الكتب-الواجب-على-طالب-العلم-الاهتمام-بها-واقتناوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40716.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12514,"question":"يسأل سماحتكم فيقول: ما هي الكتب المفيدة التي إذا اعتمد عليها طالب العلم كفته عن البقية من الكتب؟","title":"الكتب الواجب على طالب العلم الاهتمام بها واقتناؤها","answer":"الجواب:  أعظم كتاب، وأهم كتاب: القرآن العظيم، هو أعظم الكتب، القرآن العظيم هو أهم كتاب، وأعظم كتاب، وأنفع كتاب، كتاب الله فيه الهدى والنور، كما قال الله سبحانه: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] وقال -جل وعلا-: وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَى لِلْمُسْلِمِينَ [النحل:89] وقال سبحانه: وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ [الأنعام:155] فأعظم الكتب، وأصدقها، وأنفعها، وأنفسها، وأكملها كتاب الله، فنوصي كل مسلم، وكل مسلمة في جميع الدنيا، نوصيهم بالعناية بالقرآن، نوصي الجميع بالعناية بكتاب الله حفظًا، وتدبرًا، وتعقلًا وعملًا، وسؤال أهل العلم عما أشكل في ذلك، وإذا كان طالب علم ينظر كتب التفسير حتى يستفيد مثل كتاب ابن جرير تفسير ابن جرير، تفسير ابن كثير، تفسير البغوي، تفسير الشوكاني، تفسير القرطبي، حتى يستفيد من هذه التفاسير من معاني كلام الله -عز وجل- يتعلم، ويستفيد من هذه الكتب. وكذلك كتب الحديث، كـالبخاري ومسلم والسنن الأربع، هذه الكتب العظيمة يستفيد منها، مثل منتقى الأخبار لابن تيمية، بلوغ المرام للحافظ ابن حجر، عمدة الحديث للشيخ عبدالغني بن عبدالواحد المقدسي، هذه كتب الحديث المهمة، وهكذا موطأ مالك، ومسند أحمد، وسنن الدارمي، كلها كتب مفيدة عظيمة. ولكن إذا كان ليس عنده علم يسأل أهل العلم، لا يعتمد على رأيه، بل طالب العلم الذي عنده فقه في الدين، وعنده علم يستفيد من هذه الكتب، وإذا كان عاميًا ليس عنده علم يتوصل به إلى معرفة الحديث الصحيح، والضعيف؛ فإنه يسأل أهل العلم، يسأل أهل العلم عما أشكل عليه، ويعتني بالقرآن، ويكثر من تلاوة القرآن بالتدبر والتعقل، ويسأل ربه التوفيق والهداية، والإعانة.  أما أهل العلم فإنهم ينظرون في هذه الكتب، ويستفيدون منها في تفسير كتاب الله، وفي معرفة الصحيح عن رسول الله ﷺ من الأحاديث، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10709/الكتب-الواجب-على-طالب-العلم-الاهتمام-بها-واقتناوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40716.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12515,"question":"يسأل عن الآداب التي يجب أن يلتزم بها حامل القرآن؟","title":"آداب حملة القرآن","answer":"الجواب:  يجب عليه أن يلتزم بالحكمة، وترك الخوض فيما لا يعنيه، وأن يكون كلامه مضبوطًا، إذا خاض الناس في الباطل؛ يحفظ لسانه، وإذا أكثر الناس الضحك؛ لزم الصمت، والحشمة حتى يكون معروفًا بسمته الحسن، وبأخلاقه الفاضلة، والبعد عن المشاركة في الباطل من الغيبة، أو النميمة، أو الخوض فيما لا يعني، تكون أوقاته محفوظة، ولسانه محفوظًا، إلا من الخير. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10720/اداب-حملة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40714.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12523,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع محمد خضير من مدينة حائل، الأخ محمد له جمع من الأسئلة في أحدها يقول: سماحة الشيخ! إنني قريب من التخرج من المرحلة الثانوية، فبماذا تنصحونني؟ وما هي نصيحتكم بالتوجه بعد التخرج؟ جزاكم الله خيرًا.","title":"توجيه بالالتحاق بكلية الشريعة بعد الثانوية","answer":"الجواب:  ننصحك بالالتحاق بكلية الشريعة، نوصيك بأن تجتهد في الالتحاق بكلية الشريعة، حتى تكمل الدراسة الجامعية، ثم التخصص بعدها، إن شاء الله، نسأل الله لك التوفيق والعون. المقدم: اللهم آمين جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10734/توجيه-بالالتحاق-بكلية-الشريعة-بعد-الثانوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_408/40813.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12580,"question":"من جمهورية مصر العربية، مدينة السلوم، محافظة مطروح، هذه رسالة بعث بها مستمع من هناك يقول: فتحي محمد مؤمن، الأخ فتحي ضمن رسالته جمعًا من الأسئلة في أحدها يقول: أنا أعيش في مكان يوجد فيه أناس يدعون أنهم من المسلمين، يصلون، ويزكون، ويصومون، ويحجون، ولكنهم يعتقدون في الأموات، ويقول: إن الولي الميت، أو الشيخ واسطة عند الله، ويتبركون به، ويستعينون بهذا الميت الولي، ويزورونه، وينذرون له النذر، ويشدون إليهم الرحال، وإذا نصحتهم قالوا: هؤلاء أولياء يجب التقرب إليهم، ويكرهون من يمنعهم، وينصحهم بأن لا يعبدون الأموات والأولياء، ماذا نفعل؟ وهل نتركهم على ما هم عليه؟ جزاكم الله خيرًا.","title":"واجب النصيحة لمعتقدي النفع في الأموات","answer":"الجواب:  هذه مصيبة عظيمة واقعة في بلدان كثيرة، والواجب على أهل العلم أن يرشدوا الناس إلى حقيقة التوحيد، وحقيقة الشرك، حتى يعلم هؤلاء العوام بطلان ما هم عليه، كونه يصلي ويحج ويصوم ويزكي، ثم يعبد غير الله، هذا يبطل عمله، قال تعالى: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] وقال سبحانه: وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ [الزمر:65] فدعاء الأموات والاستغاثة بالأموات، والنذر لهم، والذبح لهم؛ هذا شرك أكبر ينافي التوحيد الذي هو معنى لا إله إلا الله، وينافي ما دلت عليه الآيات من وجوب إخلاص العبادة لله، كما في قوله سبحانه: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] وقوله سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] وقوله : يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ[البقرة:21] .. وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] .. فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ ۝ أَلا لِلَّهِ الدِّينُ الْخَالِصُ [الزمر:2-3] .. فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] .. وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] وقال سبحانه: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلا يُنَبِّئُكَ مِثْلُ خَبِيرٍ [فاطر:14]  فجعل دعاءهم للأموات، والأصنام، والأشجار، والأحجار شركًا بالله، عز وجل. فالواجب تنبيه هؤلاء، وتحذيرهم، وحث العلماء على تنبيههم، وتحذيرهم، حتى يتبصروا، ويعلموا أنهم على باطل، وعلى شرك، وأن صلاتهم تحبط بذلك، وهكذا صومهم وزكاتهم، وحجهم، وأعمالهم الأخرى، حتى يخلصوا العبادة لله وحده، وقد بعث الله نبيه ﷺ إلى الناس ليخلصهم من هذا الشرك، فأقام في مكة عشر سنين يدعوهم إلى توحيد الله، وإلى ترك دعاء الأموات، والاستغاثة بالأموات، والأصنام، والأشجار، والأحجار، ويقول: يا قوم قولوا: لا إله إلا الله تفلحوا قبل أن تفرض الصلاة، فلما فرضت الصلاة في مكة؛ مكث بعد ذلك مدة يدعوهم إلى توحيد الله، ثم هاجر إلى المدينة، ولم يزل يدعو إلى الله، وإلى توحيده . فالواجب عليك يا أخي! أن تحرص على دعوة هؤلاء، وإرشادهم بالحكمة والصبر والأسلوب الحسن؛ لعل الله يهديهم بأسبابك، يقول النبي ﷺ: من دل على خير؛ فله مثل أجر فاعله ويقول ﷺ لعلي  لما بعثه إلى خيبر لدعوة اليهود يقول: فوالله لأن يهدي الله بك رجلًا واحدًا؛ خير لك من حمر النعم. فدعوة الأموات بقول: يا سيدي اشف مريضي، أو انصرني، أو المدد المدد يا فلان، أو بالنذر لهم، أو ما أشبه ذلك من أنواع العبادة، كله شرك بالله، وهكذا الذبح لهم، ذبح البقر، أو الغنم، أو الدجاج، أو غير ذلك، يقول الرسول ﷺ: لعن الله من ذبح لغير الله والله يقول سبحانه: قُلْ إِنَّ صَلاتِي وَنُسُكِي يعني: ذبحي: وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:162-163].  فالذبح لغير الله مثل الصلاة لغير الله، والذي يذبح للأموات يتقرب إليهم مثل الذي يصلي لهم، وهكذا من ينذر لهم القرابين، إن شفى الله مريضي؛ فللسيد فلان كذا، فله ذبيحة، له ثور، وله كذا، أو يا سيدي البدوي اشف مريضي، أو المدد المدد، أو يا سيدي الحسين، أو يا شيخ عبد القادر ، أو يا رسول الله اشف مريضي، أو انصرنا، أو ما أشبه ذلك كل هذا من الشرك الأكبر. فالواجب الحذر، والواجب على أهل العلم أينما كانوا أن يبلغوا الناس ذلك، وأن ينصحوهم، وأن يرشدوهم إلى الحق والصواب، وأن يصبروا على جهلهم، وأذاهم؛ حتى يتعلموا، حتى يستفيدوا، هكذا كان الرسل يصبرون، وهم أفضل الخلق -عليهم الصلاة والسلام- أولاهم أقوامهم، فربما قتلوهم على ذلك، ومع هذا صبروا -عليهم الصلاة والسلام- وبلغوا الرسالة، وأدوا الأمانة؛ حتى قبضهم الله -عليهم الصلاة والسلام- وخاتمهم نبينا محمد ﷺ وهو أفضلهم، قد صبر على قومه ثلاثة وعشرين سنة، وهو يدعوهم إلى الله حتى هدى الله على يديه من هدى، وحتى أكمل الله به الدين، وأتم عليه النعمة. فالواجب التأسي به في ذلك -عليه الصلاة والسلام- والصبر على الدعوة والتوجيه والإرشاد؛ رجاء ما عند الله من المثوبة. نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/10796/واجب-النصيحة-لمعتقدي-النفع-في-الاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_412/41211.mp3","categories":["الدعوة والدعاة"]},{"id":12601,"question":"تقول أيضًا في سؤال آخر: زوجة ابني تعمل مدرسة، ولا تستجيب لنصحي من ناحية اللباس، ومن ناحية العبادات، هل إذا تدخلت في شؤون ولدي وزوجته أكون مخطئة، علمًا بأنني أنصحهم لوجه الله ؟ وإذا كانوا لا يمتثلون لأوامري، هل لي الحق أن أخرجهم من منزلي، أم لا؟ جزاكم الله خير الجزاء.","title":"ما موقف الأم من إصرار زوجة ولدها على المنكر؟","answer":"الجواب:  أنت مأجورة في نصيحتهم، وهذا هو الواجب على المؤمن والمؤمنة الأمر بالمعروف والنهي عن المنكر، إذا كانت الزوجة تتعاطى ما حرم الله من عدم التستر، وعدم العناية بالتستر، أو تتساهل بما أوجب الله عليها من الصلاة، أو غير ذلك، فالواجب إنكار المنكر، فإذا لم تستجب، أو لم يستجب زوجها؛ فعليك إخراجهما إلى بيت آخر، يستقل بنفسه حتى تسلمي من معرة منكراتهما، وحتى تبرأ ذمتك من أمرهما. فالحاصل أن الواجب عليك أمرهما بالمعروف، ونهيهما عن المنكر، فإن استجابا؛ فالحمد لله، وإلا أخرجيهما من عندك، حتى تسلمي من تبعتهما، وما يفعلان من المنكرات. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10811/ما-موقف-الام-من-اصرار-زوجة-ولدها-على-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_413/41313.mp3","categories":["الدعوة والدعاة"]},{"id":12608,"question":"نحن نعيش في مجتمع يكثر فيه الدجل والشعوذة والشركيات كبناء القباب على القبور، وكذلك دعاء الأموات لتفريج الكروب، هل يشرع أولًا في مجتمع كهذا الدعوة إلى التوحيد، وتصحيح العقائد من أدران الشرك، والاهتمام بتربية الفرد تربية دينية؛ حتى يصبح عضوًا صالحًا في المجتمع، أم يشرع المناداة بتطبيق أحكام الشريعة الإسلامية، كما تفعل كثير من الجماعات الإسلامية؟","title":"واجب الدعاة في المجتمع الذي يكثر فيه الشرك","answer":"الجواب:  إذا كنت في بلد إسلامي، وبين مسلمين تعلمهم ما جهلوا من الشرك وغيره من المعاصي، أما إذا كنت في بلد كافرة بين النصارى، وبين اليهود، وبين الوثنيين الذين لا يعرفون الإسلام، ولا يدعون الإسلام، فإنك تبدؤهم بالتوحيد، تدعوهم إلى توحيد الله، فإذا أسلموا، ودخلوا في دين الله، تعلمهم الصلاة والزكاة، وغير ذلك، كما أمر النبي معاذًا بذلك لما بعثه إلى اليمن، عليه الصلاة والسلام.  أما إذا كنت بين المسلمين في مصر، في الشام، في الأردن، في السعودية، في أي مكان، فإنك تنكر عليهم ما وقع منهم من شرك، أو غيره، وتعلمهم دينهم، وتعلمهم ما جهلوا، وتبصرهم بالحق الذي جهلوه، سواء كان شركًا، أو تهاونًا بالصلاة، أو عقوقًا للوالدين، أو تعاطيًا للربا، أو غير ذلك مما يقع من بعض المسلمين، نعم. المقدم: جزاكم الله خيرًا، إذًا يختلف الحال بين كونه في بلد إسلامي، وغير إسلامي؟ الشيخ: نعم يختلف.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10821/واجب-الدعاة-في-المجتمع-الذي-يكثر-فيه-الشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41409.mp3","categories":["الدعوة والدعاة"]},{"id":12623,"question":"نحن نعيش في مجتمع يكثر فيه الدجل والشعوذة والشركيات كبناء القباب على القبور، وكذلك دعاء الأموات لتفريج الكروب، هل يشرع أولًا في مجتمع كهذا الدعوة إلى التوحيد، وتصحيح العقائد من أدران الشرك، والاهتمام بتربية الفرد تربية دينية؛ حتى يصبح عضوًا صالحًا في المجتمع، أم يشرع المناداة بتطبيق أحكام الشريعة الإسلامية، كما تفعل كثير من الجماعات الإسلامية؟","title":"واجب الدعاة في المجتمع الذي يكثر فيه الشرك","answer":"الجواب:  إذا كنت في بلد إسلامي، وبين مسلمين تعلمهم ما جهلوا من الشرك وغيره من المعاصي، أما إذا كنت في بلد كافرة بين النصارى، وبين اليهود، وبين الوثنيين الذين لا يعرفون الإسلام، ولا يدعون الإسلام، فإنك تبدؤهم بالتوحيد، تدعوهم إلى توحيد الله، فإذا أسلموا، ودخلوا في دين الله، تعلمهم الصلاة والزكاة، وغير ذلك، كما أمر النبي معاذًا بذلك لما بعثه إلى اليمن، عليه الصلاة والسلام.  أما إذا كنت بين المسلمين في مصر، في الشام، في الأردن، في السعودية، في أي مكان، فإنك تنكر عليهم ما وقع منهم من شرك، أو غيره، وتعلمهم دينهم، وتعلمهم ما جهلوا، وتبصرهم بالحق الذي جهلوه، سواء كان شركًا، أو تهاونًا بالصلاة، أو عقوقًا للوالدين، أو تعاطيًا للربا، أو غير ذلك مما يقع من بعض المسلمين، نعم. المقدم: جزاكم الله خيرًا، إذًا يختلف الحال بين كونه في بلد إسلامي، وغير إسلامي؟ الشيخ: نعم يختلف.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10821/واجب-الدعاة-في-المجتمع-الذي-يكثر-فيه-الشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41409.mp3","categories":["الدعوة والدعاة"]},{"id":12658,"question":"يقول: نحن عشرة من أسرة واحدة، فينا البعض لم يصل نصحتهم، ولم يستجيبوا حتى الآن، هل أواصل الأكل والشرب والسكن معهم، أم بم تنصحونني؟","title":"كيفية التعامل مع الأقرباء الذين لا يصلون","answer":"الجواب:  تعمل بالأصلح إن كان هجرهم أصلح؛ فاهجرهم، ولا تكن معهم، ولا تسكن معهم، وإن كان بقاؤك معهم للدعوة والتوجيه أصلح فيما تعتقد، فلا مانع من البقاء معهم للدعوة والتوجيه، لعل الله يهديهم بأسبابك. أما إذا كانوا مستهترين، ولا يبالون بنصيحتك؛ فالواجب هجرهم.... المشروع لك هجرهم، وعدم البقاء معهم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10868/كيفية-التعامل-مع-الاقرباء-الذين-لا-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45810.mp3","categories":["الدعوة والدعاة"]},{"id":12669,"question":"ما هي موجبات نشر الصلاح في أمة محمد ﷺ وماذا عن قمع البدع في هذا المضمار؟","title":"دور العلماء والأمراء في نشر الصلاح في المجتمع","answer":"الجواب:  الواجب على العلماء، وعلى ولاة الأمور نشر ما يصلح الأمة، وأن يعلموا دينهم، وأن يبصروا بما يجب عليهم في صلاتهم وزكاتهم وصومهم وحجهم، بل في عقيدتهم، وهي الأساس، وفي كل شيء. فالواجب على الأمراء والعلماء أن ينشروا دين الله، وأن يبصروا الناس من طريق العلم، قال الله وقال رسوله، وأن يشجعوا الدعاة إلى الله على نشر الحق والدعوة إليه، وعلى تحذير الناس مما حرم الله عليهم في خطب الجمعة، وفي المحاضرات والندوات وفي المجالس العامة وفي كل مناسبة. هكذا يجب على أهل العلم، وعلى الأمراء إذا كانوا من أهل العلم، أو بواسطة العلماء، إذا كان الأمراء من أهل العلم، فعلوا وإلا فعليهم أن يأمروا أهل العلم، ويشجعوهم، ويسهلوا طريقهم في نشر العلم، ودعوة الناس إلى الخير، وترشيدهم؛ لأن الله خلق الخلق ليعبدوه، وأمرهم بذلك، ولا طريق إلى العبادة إلا بالتفهيم والتعليم والتفقيه، حتى يعلم كل مسلم ما يجب عليه، وحتى تعلم كل مسلمة ما يجب عليها، من طريق أهل العلم من طريق الخطابة، من يوم الجمعة وغيرها، من طريق الكتابة، من طريق المصالح العامة من طريق الإذاعة، من طريق الصحافة، من طريق التلفاز، كل هذه الطرق ينبغي أن تعمر بالدعوة إلى الله، والتوجيه إلى الخير. وفي إذاعة القرآن فوائد كثيرة، إذاعة القرآن في المملكة العربية السعودية فيها فوائد جمة، فأنصح جميع إخواني أن يستفيدوا من هذه الإذاعة إذاعة القرآن، الرجال والنساء في المملكة وخارجها، أنصح الجميع في المملكة وخارجها رجالًا ونساء أن يستفيدوا من إذاعة القرآن؛ وما فيها من المواعظ، وقراءة القرآن بالترتيل والتجويد، وما فيها من المحاضرات والتوجيهات، وما فيها من برنامج نور على الدرب، هذا البرنامج فيه فائدة عظيمة، ويقوم عليه جماعة من أهل العلم من أهل السنة والجماعة. فأنصح جميع المسلمين في كل مكان أن يستفيدوا من هذا البرنامج، ومن إذاعة القرآن، وأنصح جميع إخواني من العلماء في كل مكان في الجزيرة، وفي خارج الجزيرة في كل مكان أنصحهم أن ينشروا العلم، وأن يبلغوا الناس ما أوجب الله عليهم، وأن يعنوا بالعقيدة أكمل من غيرها، حتى يعلم الناس حقيقة التوحيد، وحتى يعرفوا حقيقة الشرك، وحتى يؤمنوا بالله الإيمان الصحيح، وحتى يؤمنوا بأسمائه وصفاته على الوجه الذي يليق به، وحتى يعبدوه وحده، دون كل ما سواه، وحتى يعلموا حكم ما يفعله عباد القبور من دعوة الأموات والاستغاثة بالأموات، والنذر لهم، وأن هذا هو الشرك الأكبر، وهو دين المشركين أبي جهل وأشباه. فنصيحتي لأهل العلم، في كل مكان في كل دولة، نصيحتي لعلماء السنة، لعلماء الحق، نصيحتي لهم أن يتقوا الله، وأن يعلموا العباد دين الله، وأن ينشروا بينهم ما قاله الله ورسوله، في العقيدة، وفي بقية الأحكام في الصلاة والزكاة والصوم والحج والجهاد والبر -بر الوالدين- وصلة الرحم والأمر بالمعروف والنهي عن المنكر، وفي بيان دليل ما حرم الله عليه من المعاصي، والتحذير منها، الله يقول سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] ويقول سبحانه: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا وَقَالَ إِنَّنِي مِنَ الْمُسْلِمِينَ[فصلت:33] ويقول سبحانه لنبيه -عليه الصلاة والسلام-: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108] يعني: على علم أَنَا وَمَنِ اتَّبَعَنِي [يوسف:108] فأتباع النبي ﷺ هم الدعاة إلى الله على بصيرة، وهم القدوة، وهم خلفاء الرسل. فالواجب على جميع العلماء -علماء الشريعة- عليهم أن يتقوا الله، وأن ينشروا العلم بين الناس، وأن يجتهدوا في إيضاح الأحكام بالدليل، قال الله، وقال رسوله، وأن يحذروا القول على الله بغير علم، وأن يحذروا التساهل في ذلك والتكاسل، بل يجب الصدع بالحق، ونشر الحق بالأساليب الحسنة، والكلمات الواضحة التي يفهمها المخاطبون، ولكل قوم لغتهم، فإذا كان في بلد لهم لغة غير العربية؛ حدثهم بها، ونصحهم بها، كردية، أو إنجليزية، أو فرنسية أو غير ذلك. يحدث كل قوم بما يعرفون، قال تعالى:  وَمَا أَرْسَلْنَا مِنْ رَسُولٍ إِلَّا بِلِسَانِ قَوْمِهِ [إبراهيم:4] ويقول علي  أمير المؤمنين علي بن أبي طالب -رضي الله تعالى عنه-:  \"حدثوا الناس بما يعرفون، أتحبون أن يكذب الله ورسوله؟!\".  المعنى: بلغوهم العلم بالألفاظ واللغات التي يفهمونها حتى يفهموا الحق على بصيرة، ويقول النبي ﷺ: من دل على خير؛ فله مثل أجر فاعله فأنت أيها العالم على خير عظيم، ترشد الناس، وتنفعهم، وتبرئ ذمتك، وتنشر دين الله، ويكون لك مثل أجورهم، هذا خير عظيم، وفضل كبير. أسأل الله أن يوفقنا وجميع إخواننا من أهل العلم وغيرهم لما يرضيه، وأن يعيذنا جميعًا من شرور أنفسنا، ومن سيئات أعمالنا، وأن يمنحنا جميعًا الفقه في دينه، والثبات عليه، إنه -جل وعلا- جواد كريم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10879/دور-العلماء-والامراء-في-نشر-الصلاح-في-المجتمع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_416/41603.mp3","categories":["الدعوة والدعاة"]},{"id":12688,"question":"بعد هذا رسالة وصلت إلى البرنامج من ليبيا بتوقيع إحدى الأخوات المستمعات، تقول المرسلة سلمى، الأخت سلمى لها سؤال تقول فيه: بالنسبة لخروج المرأة خارج بيتها لضرورة، حول هذا الموضوع المهم، أقول: بأننا مجموعة من بنات مسلمات، وأننا نذهب إلى أحد المساجد في مدينتنا، وهو يبعد عن البيت حوالي ربع ساعة مشيًا على الأقدام، ونذهب في الأسبوع أربعة أيام، ونتعلم الفقه والسيرة، فهل هذا يعتبر من الضرورة، جزاكم الله خيرًا؟","title":"حكم ذهاب المرأة للمسجد من أجل تعلم أمور دينها","answer":"الجواب:  هذا كله طيب، مثل هذا يؤدي إلى التفقه في الدين، هذا أمر مطلوب إلا إذا تيسر في مدرسة عندكم من يفقهكن، ويعلمكن طيب، وإذا دعت الحاجة إلى حضور حلقات العلم في المساجد حتى تسمعن الفائدة والعلم؛ فهذا أمر مطلوب، قد يجب، وقد يتأكد، إذا دعت الحاجة إليه وجب. فالحاصل: أن الخروج إلى المساجد لطلب العلم، والتفقه في الدين، أمر مطلوب شرعًا ما بين مستحب، أو واجب، على الرجال والنساء جميعًا. أما إذا تيسر للنساء التفقه في بيوتهن، أو في مدارس خاصة؛ كفى ذلك، والحمد لله، وإلا فعليهن أن يتفقهن في الدين، وأن يتعلمن شرع الله، ولو بالخروج إلى مسجد بعيد ساعة، كربع ساعة، أو أكثر للتفقه في الدين، ويكون معها من أخواتها من يساعدها على ذلك؛ حتى لا تستوحش من الطريق، أو لا تفتن في الطريق، أو يكون معها زوجها أو أخوها، إذا كان هناك حاجة إلى ذلك، وإن كان الطريق آمنًا، ولا خوف؛ فلا بأس أن تخرج وحدها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10898/حكم-ذهاب-المراة-للمسجد-من-اجل-تعلم-امور-دينها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41716.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12735,"question":"رسالة وصلت إلى البرنامج من الجمهورية العراقية، باعثها مستمع من هناك يقول خالد عبدالله حسن، الأخ خالد له جمع من الأسئلة من بينها سؤال يقول: سمعت بالوهابية، فمن هم؟","title":"التعريف بالوهابية","answer":"الجواب:  الوهابية هم أتباع الشيخ الإمام: محمد بن عبدالوهاب بن سليمان بن علي التميمي الحنبلي المتوفى سنة ست ومائتين وألف من الهجرة، كانت وفاته -رحمه الله- سنة ست ومائتين وألف من الهجرة في الدرعية، وقبره معروف هناك، وقد قام بالدعوة إلى الله في النصف الثاني من القرن الثاني عشر، في نجد الدرعية، وما حولها، دعا إلى توحيد الله، وأنكر على الناس التعلق بالقبور والأموات والأصنام، وتصديق الكهان والمنجمين، وعبادة الأشجار والأحجار على طريقة السلف الصالح، على الطريقة التي بعث الله بها نبيه محمد -عليه الصلاة والسلام- وعلى الطريقة التي درج عليها أصحابه، فدعا إلى الله، ودعا معه العلماء الذين وفقهم الله لمعرفة الحق، من أقاربه وأولاده وغيرهم، وأظهر الله به الدين وأزال به الشر من نجد وما حولها، ثم انتشرت دعوته في اليمن والشام والعراق ومصر والهند وغير ذلك. وعرف المحققون صحة دعوته واستقامتها، وأنه على الهدى والطريق القويم، وأنه في الحقيقة مجدد لما اندرس من معالم الإسلام، وليس مبتدعًا، وليس له دين جديد، ولا مذهب جديد، إنما دعا إلى توحيد الله، واتباع شريعته، والسير على منهج السلف الصالح من الصحابة، ومن سلك سبيلهم، هذا هو مذهب الوهابية، ساروا على منهج الرسول ﷺ وأتباعه من الصحابة، ومن بعدهم من أهل العلم والإيمان.  ولكن لهم خصوم، فكذب عليهم الكذابون حتى يستبيحوا دماءهم، كذبوا عليهم وقالوا: إنهم مذهب خامس، وأنهم يسبون الرسول ﷺ ويسبون الصحابة، وكلها كذب، كله باطل، بل هم من أحب الناس للرسول ﷺ وهم على طريق الصحابة، والرسول أحب إليهم من أنفسهم وأولادهم وأموالهم، وهم يدعون إلى ما دعا إليه الرسول ﷺ يدعون إلى توحيد الله، واتباع شريعته، وتعظيم أمره ونهيه، والسير على منهج الرسول ﷺ وكتبهم طافحة بذلك، كتب الشيخ محمد، وأتباعه واضحة في ذلك، من قرأها؛ عرف ذلك، كتاب التوحيد، فتح المجيد، كشف الشبهات، ثلاثة الأصول، كذلك تيسير العزيز الحميد لحفيده سليمان بن عبدالله ، وكذلك الدرر السنية في فتاوى أهل نجد واضحة في ذلك. وهكذا كتبهم الأخرى ورسائلهم الأخرى كلها تبين ما هم عليه من الهدى والحق، وكلها تبين كذب أعدائهم، وخصومهم من الصوفية، وغير الصوفية، ومن عباد القبور الذين كذبوا عليهم؛ لأنهم أنكروا عليهم عبادة القبور، فكذبوا عليه، فخصومهم هم عباد القبور، أو جهلة ما عرفوا الحقيقة، وصدقوا عباد القبور. أما أهل العلم والإيمان في مصر والشام والعراق وغير ذلك فقد عرفوا صحة ما هم عليه، وشهدوا لهم بالحق، كالشيخ محمد رشيد رضا، وغيرهم ممن عرف دعوتهم -رحمة الله عليهم- وشهد لهم بالحق من علماء الإسلام في مصر والشام والعراق وغير ذلك. نعم. المقدم: جزاكم الله خيرًا.  المقدم: إذًا نشر كتبهم ألا يزيل هذه الغمة سماحة الشيخ؟ الشيخ: لا شك، وقد نشرت، والحمد لله، وعمت الأوطان، وانتشرت بحمد الله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10949/التعريف-بالوهابية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_461/46106.mp3","categories":["الدعوة والدعاة"]},{"id":12759,"question":"هل ترون تقديم قراءة التفسير على حفظ القرآن؟","title":"الجمع بين حفظ القرآن ودراسة تفسيره","answer":"الجواب:  كله خير، كونه يتعاهد القرآن ولو نظرًا؛ هذا مطلوب، وإذا تيسر له الحفظ؛ فهذا مطلوب، مع التفقه في القرآن، وقراءة التفسير، وكتب الحديث، وحضور حلقات العلم، يجمع بين هذا وهذا؛ لأن حفظ القرآن وحده لا يكفي، بل لا بد من حضور حلقات العلم، ومراجعة التفسير لمعرفة معنى الآيات؛ حتى يستفيد بالقراءة. فالمؤمن مطلوب منه العناية بالقرآن، والعلم، والتفقه في الدين، مع العناية بالقرآن، والإكثار من تلاوته، وتدبر معانيه، وإذا تيسر له حفظه؛ فهذا خير إلى خير، أو حفظ بعضه، لكن ليس بواجب الحفظ إنما هو مستحب مطلوب إذا تيسر. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10973/الجمع-بين-حفظ-القران-ودراسة-تفسيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41908.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12777,"question":"يقول: سماحة الشيخ أرجو أن توجهوني إلى بعض الكتب التي أقرؤها كيما أستفيد منها، وتفيدني في أمور ديني ودنياي؟ جزاكم الله خيرًا.","title":"الكتب التي ينصح بها طالب العلم","answer":"الجواب:  أنصحك بالعناية بكتاب الله القرآن، فهو أعظم كتاب، وأشرف كتاب وأصدق كتاب، فأوصيك وجميع المسلمين من الرجال والنساء بالعناية بالقرآن، والإكثار من تلاوته، وتدبر معانيه، والسؤال عما أشكل عليك، قال الله : كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29] وقال ﷺ: اقرؤوا القرآن؛ فإنه يأتي شفيعًا لأصحابه يوم القيامة ويقول ﷺ: خيركم من تعلم القرآن وعلمه فنوصي جميع إخواني المسلمين بالعناية بالقرآن تلاوة، وتدبرًا وعملًا به، إذ المقصود العمل، التلاوة والتدبر وسيلة للعمل، والمقصود العمل، فنوصي الجميع بالإكثار من تلاوته بالتدبر، والتعقل، والعمل، والسؤال عما أشكل عليك من أهل العلم، ومراجعة كتب التفسير المعروفة الطيبة إذا كنت تستطيع ذلك مثل تفسير ابن جرير والبغوي وابن كثير والشوكاني ، كتب مفيدة. ومن الكتب النافعة الصحيحان: البخاري ومسلم، إذا كنت تستطيع ذلك، عندك علم عندك بصيرة، ومن الكتب المفيدة -أيضًا- كتب أهل السنة، كتب أهل السنة فيها الخير الكثير، مثل موطأ مالك -رحمه الله- السنن الأربع، كل هذه.. كتب الحديث، كتب أهل السنة. كذلك كتب أهل العلم المعروفين بالخير، والعلم النافع، مثل المغني لابن قدامة -رحمه الله- والمقنع له أيضًا، شرح المهذب للنووي ، الروضة للنووي، كتب مفيدة.. البداية لابن رشد، وما أشبه ذلك من الكتب المفيدة.  ومن كتب العقيدة، كتب السلف أيضًا منها كتب شيخ الإسلام ابن تيمية -رحمه الله- فهي كتب مفيدة كالحموية، والتدمرية، والواسطية، كتب الشيخ محمد بن عبدالوهاب -رحمه الله- مفيدة، مثل كتاب التوحيد، كشف الشبهات، ثلاثة الأصول، وهكذا شرح التوحيد لحفيده الشيخ عبدالرحمن بن حسن، وحفيده الثاني الشيخ سليمان بن عبدالله، فتح المجيد للشيخ عبدالرحمن ، وتيسير العزيز الحميد للشيخ سليمان، هذه كتب عظيمة ومفيدة، فنوصي العناية بها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10991/الكتب-التي-ينصح-بها-طالب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_420/42004.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12799,"question":"رسالة وصلت إلى البرنامج من المستمع فاضل حميد غربي من قرية سموم قضاء سامراء العراق في رسالته أكثر من سؤال في أحدها يقول: إنني كثيرًا ما أرشد والدتي إلى الصلاة، وأقول لها: صلي، لكنها تغضب علي باليومين والثلاثة، وتصلي أحيانًا، وتنقطع أحيانًا، بم تنصحونني والحال ما ذكر، جزاكم الله خيرًا؟","title":"كيفية نصيحة الأم التي لا تواظب على الصلاة","answer":"الجواب:  ننصحك بالاستمرار في نصيحتها بالكلام الطيب، والأسلوب الحسن، مع الدعاء لها في صلاتك، وفي غير صلاتك أن الله يهديها، ويوفقها للاستقامة على الحق، والمحافظة على الصلاة في أوقاتها، ولا تسأم، ولا تمل، واجتهد في نصيحتها في جميع الأوقات، لكن باللطف، والكلام الطيب، والأسلوب الحسن، لا بالشدة والعنف؛ لأن حقها عظيم، وعليك مع هذا أن تدعو لها في صلاتك في السجود، وفي آخر الصلاة قبل السلام، وفي الليل، وفي آخر الليل، وفي غير هذا من الأوقات، تدعو لها أن الله يمن عليها بالهداية، وأن الله يشرح صدرها للحق، وأن يمن عليها بالمحافظة على الصلاة. وإذا استعنت بغيرك من أبيك إن كان موجودًا، أو إخوتك الآخرين، أو أخوالك أن يساعدوك على ذلك في نصيحتها بالأسلوب الحسن؛ فهذا شيء طيب، ولعل الله أن يهديها بأسبابكم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11013/كيفية-نصيحة-الام-التي-لا-تواظب-على-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_462/46204.mp3","categories":["الدعوة والدعاة"]},{"id":12881,"question":"الأخت: آمنة عشيلي من اللاذقية في سوريا بعثت برسالة مطولة كلها ثناء وتقدير ومحبة لسماحة الشيخ، وتنتهي رسالتها بسؤال تقول فيه: ما هو رأي سماحتكم في كتاب صفة صلاة النبي ﷺ للشيخ: محمد ناصر الدين الألباني؟","title":"تقييم في كتاب صفة صلاة النبي للألباني","answer":"الجواب:  هذا كتاب طيب مفيد، والشيخ: ناصر الدين الألباني رجل علامة فاضل، وله اجتهاد عظيم في إحياء السنة، وبيان الصحيح من الضعيف، فهو مشكور على جهوده، جزاه الله خيرًا، وضاعف مثوبته، وكل أحد قد يخطئ، ليس أحد معصومًا من الخطأ من العلماء، قد يقع له بعض الأخطاء، وبعض الغلط في بعض المؤلفات، وهكذا غيره من العلماء الذين هم أكبر منه قد يقع له بعض الأخطاء، ومما وقع في صفة صلاة النبي ﷺ من الخطأ قوله: إن الإنسان بعد الرفع من الركوع يسدل يديه، هذا خطأ، والصواب: أنه يضمهما على صدره كما فعل قبل الركوع؛ لأن هذا هو المحفوظ في الأحاديث الصحيحة عن النبي -عليه الصلاة والسلام-: أنه كان إذا صلى وضع يمينه على شماله حال قيامه في الصلاة وهذا يعم ما قبل الركوع وما بعد الركوع، وكذلك حديث سهل بن سعد عن النبي ﷺ أنه قال: كنا نؤمر أن يضع الرجل يده اليمنى على ذراعه اليسرى في الصلاة. ومعلوم أن في الصلاة في حال الركوع يضع يديه على ركبتيه، وفي حال السجود على الأرض، وفي حال الجلوس على فخذيه، أو ركبتيه، ما بقي إلا حال الوقوف، وهو في حال الوقوف يضع يمنيه على شماله، على الكف والرسغ والساعد، والساعد هو الذراع. هذا هو مما يؤخذ على المؤلف وفقه الله، ومثلما تقدم كل أحد يقع منه بعض الزلل، والرجل مشكور على أعماله الطيبة، وعلى جهوده الطيبة، وعلى عنايته بالسنة، فجزاه الله خيرًا، وزادنا وإياكم وإياه من الخير والهدى، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11096/تقييم-في-كتاب-صفة-صلاة-النبي-للالباني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_466/46613.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":12903,"question":"السؤال الأخير الذي نعرضه لأخينا في هذه الحلقة يقول: زوجتي لا تصلي، وبناتي أيضًا، ولا يتحجبون، فماذا أفعل؟ وجهوني، جزاكم الله خيرًا.","title":"كيفية التعامل مع زوجة وبنات لا يصلين","answer":"الجواب:  الواجب عليك نصيحة الزوجة، والبنات، وتأديبهن على ترك الصلاة حتى يستقمن، هذا واجب عليك، الصلاة عمود الإسلام، وهي الركن الثاني من أركان الإسلام الخمسة، وهي أعظم الأركان بعد الشهادتين، من حفظها؛ حفظ دينه، ومن ضيعها؛ فهو لما سواها أضيع، والله يقول سبحانه: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] ويقول -جل وعلا-: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43] ويقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُوْلَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71]. فالواجب على المؤمنين والمؤمنات التناصح، والتآمر بالمعروف، والتناهي عن المنكر، وزوجتك وبناتك من أحق الناس بنصيحتك وإرشادك، وأمرك لهن بالمعروف، ونهيك لهن عن المنكر، ولا يجوز التساهل في هذا أبدًا، ولو بالضرب، ولو بضرب الزوجة ضربًا غير مبرح، وضرب البنات ضربًا غير مبرح حتى يستقمن؛ لأن هذه الصلاة عمود الإسلام، من تركها؛ كفر -نسأل الله العافية- يقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر نسأل الله العافية. فاتق الله يا أيها السائل! واحرص على هداية زوجتك وبناتك، واستعن على ذلك أيضًا بأقاربك، مثل أخوال بناتك، إخوان الزوجة، أبيها، أعمامها يساعدونك، اتفق معهم على أن يساعدوك على زوجتك، وعلى بناتك؛ حتى يقمن الصلاة؛ حتى يستقمن في دينهن، لا تساهل في هذا الأمر. فإن لم تستقم؛ ففارقها، طلقها، ولا يجوز بقاؤها معك، وهي لا تصلي، بل إما أن تتوب، وإما أن تفارقها، وهكذا البنات لابد من تأديبهن؛ حتى يتبن إلى الله، حتى يستقمن على الصلاة، نعم. المقدم: جزاكم الله خيرًا. ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/11118/كيفية-التعامل-مع-زوجة-وبنات-لا-يصلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_468/46805.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":12984,"question":"سؤالها الأخير يقول: إذا كان الوالد يحل المحرمات كالخمر، ولعب القمار، وعدم مراعاة العائلة، والاهتمام بها، بالإضافة إلى أنه لا يعمل، ويدعي المرض -والله أعلم- وتصرفاته هذه أدت إلى أن قامت العائلة بمقاطعته، وعدم احترامه، مع العلم أن الكثير من هذه العائلة يقيم الصلاة، ويؤتي الزكاة، ويعرف حدود الله، ومع ذلك فإن تصرفات هذا الأب تنسيهم في لحظة الغضب قول الله تعالى: وَبِالْوَالِدَيْنِ إِحْسَانًا [البقرة:83]  كيفية التعامل مع هذا الأب، والتصرف معه بما يرضي الله، وعدم مخالفة قول الله تعالى: وَبِالْوَالِدَيْنِ إِحْسَانًا [البقرة:83] لأني ذكرت أعلاه أن أفراد العائلة في حيرة مع هذا الأب؟ أفيدونا مأجورين جزاكم الله خيرًا.","title":"كيفية التعامل مع الوالد المقارف للمعاصي","answer":"الجواب:  الواجب مناصحته مناصحته، والدعاء له بظهر الغيب أن الله يهديه، ويرده إلى الصواب، مع الرفق به؛ لأن الله -جل وعلا- قال للولد في حق والديه الكافرين : وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا وَاتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَيَّ [لقمان:15] فأمر أن يصحب والديه بالمعروف، وإن كانا كافرين. فهكذا اليوم إذا كان الوالد كافرًا، أو عنده معاصٍ ظاهرة؛ فلا يجوز للولد أن يقاطعه، ولا أن يسبه، ولكن يرفق به، ويصاحبه بالمعروف، بالدعاء له، والنصيحة له، والدعاء له بظهر الغيب، أن الله يهديه، والاستعانة على ذلك أيضًا ببعض الأقارب الطيبين؛ لعل الله يهديه بأسبابهم، ولا يقاطعه، ولا يعقه، بل يصبر ويحتسب حتى يجعل الله فرجًا ومخرجًا، وإذا كان محتاجًا؛ أنفق عليه. والحاصل: والخلاصة أنه يرفق به، ويدعو له بظهر الغيب بالهداية، ولا يسبه، ولا يقطعه من الزيارة، ولا من البر، بل يبره، ويحسن إليه، ولا يعقه حتى يهديه الله، أو يميته الله، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11201/كيفية-التعامل-مع-الوالد-المقارف-للمعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_470/47012.mp3","categories":["الدعوة والدعاة"]},{"id":12995,"question":"هذه السائلة تذكر بأنها فتاة تصلي وتصوم وتحفظ من كتاب الله ثلاثة عشر جزءًا، تقول: وأنا أتابع لكي أحفظه -إن شاء الله- ولكن أشعر بأنني أنسى، ولكنني -إن شاء الله- سأعيد الحفظ والمراجعة مرة ثانية بعد حفظه لأول مرة، فهل إذا مت قبل المراجعة، أو قبل مراجعة القرآن مرة ثانية، هل أتذكره يوم القيامة، يوم يقول الله  للعبد: اقرأ وارتق، ورتل كما كنت ترتل في الدنيا وهل أجازى على حفظي إياه لأول مرة إن نسيته، علمًا بأنني مواظبة على تلاوة القرآن الكريم، جزاكم الله خيرًا؟","title":"الحرص على عدم نسيان القرآن الكريم بعد حفظه","answer":"الجواب:  إذا حرصت على الحفظ، واجتهدت في ذلك، وبذلت الوسع؛ فنرجو لك التوفيق في الآخرة، أما إذا حصل التساهل، وعدم المبالاة؛ فهذا خطر عظيم، لكن إذا بذل المؤمن والمؤمنة الوسع في حفظ كتاب الله، واجتهد كل منهما في ذلك؛ فالله سبحانه هو الجواد الكريم الذي يعين عبده، ويوفق عبده، ويجازيه على عمله الطيب . فالوصية الجد في ذلك، والحرص على ذلك، والله سبحانه هو الموفق الهادي، جل وعلا. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11212/الحرص-على-عدم-نسيان-القران-الكريم-بعد-حفظه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_504/50408.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13022,"question":"يسألن عن الكتب التالية لو تكرمتم سماحة الشيخ: أولًا: فقه المرأة المسلمة؟","title":"تقييم كتاب (فقه المرأة المسلمة)","answer":"الجواب:  لا أعلم عن هذا الكتاب شيئًا، من ألفه؟ المقدم: الدكتور إبراهيم الجمل . الشيخ: ما أعرف عنه شيئًا. نعم.","link":"https://binbaz.org.sa/fatwas/11239/تقييم-كتاب-فقه-المراة-المسلمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47202.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13023,"question":"عجائب وغرائب الجن لبدر الدين عبدالله .","title":"تقييم كتاب (عجائب وغرائب الجن)","answer":"الجواب: لا أعلم عنه شيئًا، أقول: لا أعرف عنه شيئًا، نعم.","link":"https://binbaz.org.sa/fatwas/11240/تقييم-كتاب-عجاىب-وغراىب-الجن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47203.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13024,"question":"عقيدة المؤمن للشيخ: أبو بكر جابر الجزائري .","title":"تقييم كتاب (عقيدة المؤمن) لأبي بكر الجزائري","answer":"الجواب:  هذا كتاب لا بأس به، جيد. نعم. المقدم: بارك الله فيكم، إذًا تنصحون الأخوات بقراءته. الشيخ: .... عقيدة المؤمن طيب، وهكذا ننصح الأخوات بقراءة كتب شيخ الإسلام ابن تيمية وابن القيم ، وأعظم من ذلك، وأكبر، أنصحهن بالقرآن، العناية بالقرآن الكريم، والإكثار من تلاوة القرآن، فهو كتاب الله العظيم، وهو أصل كل خير، وهو ينبوع السعادة. فأنصح كل مؤمن، وكل مؤمنة بالعناية بكتاب الله، والإكثار من تلاوة كتاب الله أكثر من كل شيء، مع التدبر والتعقل والاستفادة، وسؤال الله التفقه في معانيه، وأن يبصر القاري في معانيه، ويعلمه ما ينفعه، مع سؤال أهل العلم عما أشكل، ومطالعة كتب التفسير؛ حتى يستفيد المؤمن والمؤمنة. وهكذا السنة سنة الرسول ﷺ فهي الوحي الثاني، وهي المفسرة للقرآن، فهي مقدمة بعد القرآن على كل شيء، مثل البخاري صحيح البخاري صحيح مسلم، والكتب المختصرة من ذلك، مثل بلوغ المرام، مثل عمدة الحديث، مثل منتقى الأخبار، كل هذه كتب مفيدة وعظيمة تنفع المؤمن، والمؤمن والمؤمنة إذا أشكل عليهما شيء؛ يسألان أهل العلم، ويراجعان كتب الشروح التي تكلمت على الأحاديث الضعيفة؛ حتى يستفيد الجميع. ولا مانع من قراءة كتب أهل العلم المفيدة التي عرف أهلها بحسن العقيدة، مثل كتب شيخ الإسلام ابن تيمية وابن القيم، كتب أئمة الدعوة كالشيخ: محمد بن عبدالوهاب، وتلاميذه، وأنصاره، مثل كتاب التوحيد، مثل كشف الشبهات، ثلاثة الأصول، آداب المشي إلى الصلاة، مختصر السيرة النبوية، كل هذه للشيخ: محمد -رحمه الله- مثل العقيدة الواسطية لـشيخ الإسلام ، التدمرية، الحموية لشيخ الإسلام ابن تيمية، مثل كتاب الإيمان له أيضًا، منهاج السنة له أيضًا، الفتاوى المعروفة، مثل زاد المعاد لابن القيم -رحمه الله- شفاء العليل لابن القيم -رحمه الله- إعلام الموقعين لابن القيم -رحمه الله- حادي الأرواح له أيضًا، وهكذا كتبه الأخرى كلها مفيدة وجيدة. وهكذا كتب أهل العلم المعروفين بالعقيدة الطيبة، مراجعتها والاستفادة منها أمر طيب مطلوب، ولكن تكون العناية بالقرآن، وبالأحاديث أكثر وأكبر وأعظم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11241/تقييم-كتاب-عقيدة-المومن-لابي-بكر-الجزاىري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_472/47204.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13100,"question":"السائل يقول: ما هي الآداب التي ينبغي لطالب العلم أن يتحلى بها؟","title":"من آداب طالب العلم","answer":"الجواب:  الآداب الشرعية، التحلي بالتواضع، وبذل السلام، ورد السلام، والتوجيه إلى الخير، والنصيحة، والأمر بالمعروف، والنهي عن المنكر .. صلة الرحم .. إكرام الجار .. كف الأذى عن الجار.. هكذا.. هذه الصفات هي علامات الخير، وعلامات السعادة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11317/من-اداب-طالب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_508/50810.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13215,"question":"هذا السائل العتيبي الدوادمي من السر يقول: سماحة الشيخ! إذا كان أبي وأخي يقصرون في الصلاة، فأرشدوني إلى الطريقة الأفضل لنصحهم، وتوجيههم، ماذا أعمل تجاههم؟","title":"دورنا تجاه من يقصر في الصلاة من الأقارب","answer":"الجواب:  عليك النصيحة المستمرة، وتخويفهم من الله -جل وعلا- لعل الله ينفع بك، وكذلك تستعين بالطيبين من أقاربك، وجيرانك ينصحونهم، الله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] ولا تمل، ولا تيئس، انصحهم .. وجههم إلى الخير، وخوفهم من الله -جل وعلا- وأبشر بالخير العظيم. وهكذا من يساعدك من إخوانك، من جيران، أو أقارب على هذا الخير، أنتم على خير كثير، وهذا من باب التعاون على البر والتقوى، ومن باب الأمر بالمعروف والنهي عن المنكر، ومن باب التواصي بالحق، والله لا يضيع عمل عامل  نعم.","link":"https://binbaz.org.sa/fatwas/11491/دورنا-تجاه-من-يقصر-في-الصلاة-من-الاقارب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52006.mp3","categories":["الدعوة والدعاة"]},{"id":13232,"question":"السائلة تقول: ما حكم خروج الفتاة بدون علم والدها للدعوة إلى الله، أو لزيارة المرضى، وفعل الخيرات، هذا مع أن الوالد لا يمنعها من ذلك، وهل إذا افترضنا أنه يمنعها، هل تخرج للدعوة، أم لا، جزاكم الله خيرًا؟","title":"حكم خروج البنت للدعوة إلى الله دون إذن والدها","answer":"الجواب:  نعم. لها الخروج للدعوة، وزيارة الأقارب، وعيادة المريض بالتحفظ، والعفة، والتستر، والحجاب لا بأس، وإن لم تستأذن والدها، إلا إذا كان في خروجها خطر؛ فلابد من إذن والدها، وأخذ رأيه في الكيفية التي تخرج بها حتى لا تقع في الخطر؛ لأن والدها مسؤول عنها. وهكذا إخوتها، فإذا كان خروجها لا يترتب عليه شر في خروجها لعيادة المريض، أو سماع المواعظ، أو سماع خطبة الجمعة، إذا كان خروجها مضبوطًا متسترة، وليس هناك ما يوجب التهمة؛ فلا بأس. أما إذا كانت تخشى أن تتهم؛ فينبغي لها أن تحذر، وألا تخرج إلا بإذن، ويكون معها من يصحبها من أخواتها، من زوجة أبيها، من غيرهن من النساء الثقات؛ حتى لا تتهم بالسوء، نعم.  المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11513/حكم-خروج-البنت-للدعوة-الى-الله-دون-اذن-والدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52015.mp3","categories":["الدعوة والدعاة"]},{"id":13317,"question":"هذا السائل طالب من الجامعة يقول في سؤاله الذي كتبه باختصار، يقول: سماحة الشيخ! ما هي السبل المعينة للداعي إلى الله  وهل الدعوة خاصة بأناس معينين، حيث أنني أريد أن أدعو إلى الله بحكمة وبصيرة، ولكن معرفتي بالأمور الشرعية قليلة جدًا، وجهوني بذلك يا سماحة الشيخ في ضوء هذا السؤال؟","title":"السبل المعينة في الدعوة إلى الله","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالدعوة إلى الله سبحانه هي منهج الرسل -عليهم الصلاة والسلام- فإن الله بعثهم دعاة للحق، وهداة للخلق بما أوحى إليهم  وعلى رأسهم خاتمهم، وإمامهم نبينا محمد -عليه الصلاة والسلام- فقد قال الله له: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] وقال سبحانه: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ أَنَا وَمَنِ اتَّبَعَنِي وَسُبْحَانَ اللَّهِ وَمَا أَنَا مِنَ الْمُشْرِكِينَ [يوسف:108]. وسبل الدعوة هي توجيه الناس إلى الخير بالخطابة، والمواعظ، والكتابة، والمشافهة الخاصة، ومن طريق الهاتف، ومن أي طريق يوصل به الداعية الحق إلى المدعوين، ليس لذاك حد محدود، بل متى أمكن الداعي إلى الله -جل وعلا- أي طريق يوصل به الحق مما أباحه الله، ومما شرعه الله؛ فعل ذلك؛ لأن المقصود هو إيصال الحق إلى الناس، والحرص على هدايتهم، وعلى قبولهم للحق، من طريق الآيات القرآنية، والأحاديث النبوية، فهو يعظهم بآيات الله، ويتلو عليهم كتاب الله، ويتلو عليهم السنة، ويفقههم في المعنى حسب الطاقة. ولكن ليس له أن يدعو إلا على علم، الذي ليس عنده علم ليس له أن يدعو على جهالة قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108] المعنى: على علم، فالجاهل يجتهد حتى يتعلم، فإذا تعلم، وكان على بصيرة؛ دعا غيره على حسب ما عنده من العلم والبصيرة، أما الجهلة فلا يجوز الدعاء، الجاهل لا يجوز له أن يدعو وهو جاهل، بل ذلك محرم، قال الله سبحانه: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [الأعراف:33]، فجعل القول عليه بغير علم فوق مرتبة الشرك -نسأل الله العافية- وقال في وصف الشيطان: إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [البقرة:169]. فالواجب على الدعاة إلى الله -سبحانه- أن يكونوا على بصيرة، على علم، وأن يتواصوا ... الطرق والسبل الطيبة الجائزة التي توصل الحق إلى المدعوين، وتوضحه لهم تلاوة وكتابة، وغير ذلك مما يتيسر به إيصال الحق إليهم، وللداعي مثل أجر من هداه الله على يديه كما قال ﷺ: من دل على خير؛ فله مثل أجر فاعله من دعا إلى هدى؛ كان له من الأجر مثل أجور من تبعه، لا ينقص ذلك من أجورهم شيئًا. والناس بحاجة إلى الدعوة، بل هي ضرورة إلى الدعوة في كل زمان، ولكن بعض الناس أشد حاجة من بعض في المدن، والقرى، فالذين عندهم علماء، وعندهم موجهون، حاجتهم أقل من حاجة الذين ليس عندهم أحد. فعلى العلماء أينما كانوا أن يوجهوا الناس، ويرشدوا الناس إلى الحق، ويبصروهم بدين الله  ولهم مثل أجور من هداه الله على أيديهم، وعليهم أن يتوجهوا إلى البلدان والقرى التي ليس فيها دعاة؛ حتى يقوموا بالواجب حسب طاقتهم، وهكذا في القبائل قبائل العرب التي ليس فيها من يوجههم للخير، يجب على ولاة الأمور أن يوجهوا لهم الدعاة حتى يبصروهم ويرشدوهم إلى الحق. نعم. المقدم: جزاكم الله خيرًا على هذا التوجيه يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11603/السبل-المعينة-في-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_521/52101.mp3","categories":["الدعوة والدعاة"]},{"id":13411,"question":"هذا السائل للبرنامج يقول في هذا السؤال الذي رمز لاسمه بـ (أ. أ) يقول: سؤالي عن المواعظ والخطب التي نسمعها من بعض المحدثين -هداهم الله- حيث يخرج منهم كلام حاد وعنيف على بعض من صدرت منه مخالفة، والبعض من الناس تحصل هذه المخالفة منه عن طريق الجهل، هل هذا مشروع؟","title":"الحث على الرفق في الدعوة إلى الله","answer":"الجواب: السنة للواعظ والمذكر الرفق، واستعمال الأسلوب الحسن، والترغيب والترهيب، والجدال بالتي هي أحسن، هذا هو السنة، قال الله تعالى: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] حتى يقبل الناس الحق، وحتى يخضعوا لسماع الخير، وحتى يطمئنوا، ولا يجوز في مثل هذا التعنيف والتشديد؛ لأن هذا ينفر من سماع المواعظ والذكرى. وقد قال النبي ﷺ: من يحرم الرفق يحرم الخير كله وقد قال الله -جل وعلا- في وصف نبيه ﷺ: فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لانْفَضُّوا مِنْ حَوْلِكَ [آل عمران:159] فما دام المستمعون يصغون إلى الحديث، ويستفيدون فالحمد الله، عليه أن يستمر، ويراعي الأسلوب الحسن، والرفق رجاء أن ينفعهم الله بما يسمعون. أما من تعدى وظلم؛ فله شأن آخر، في كتابه، وفي عقابه لما يستحق كما قال الله -جل وعلا-: وَلا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ [العنكبوت:46] من ظلم منهم له عقاب يليق به، لكن الداعي يستعمل الرفق في دعوته، وإذا دعت الحاجة إلى الشدة في بعض المنكرات؛ لأن صاحبها قد ظلم، وتعدى، وكابر؛ فلا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11701/الحث-على-الرفق-في-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_516/51606.mp3","categories":["الدعوة والدعاة"]},{"id":13459,"question":"في أسئلة هذه السائلة (ع. ع. م) من الأردن تقول: سماحة الشيخ! رجل لا يصلي، ويأكل الربا، فهل يجوز للابن أن يسكن في بيت والده؟ وهل تقبل هدية الذي لا يصلي؟ أو يصلي ولكن يأكل الربا إذا كنا نعلم عن حاله ذلك، وإذا كنا لا نعلم فهل نسأل عن حاله قبل قبول الهدية؟ وجهونا في ذلك.","title":"كيفية التعامل مع تارك الصلاة وآكل الربا","answer":"الجواب: الذي لا يصلي ينكر عليه، ترك الصلاة كفر -نعوذ بالله- أكبر، يقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر فالأمر عظيم، فالذي لا يصلي ينكر عليه، وينصح، ويوجه إلى الخير، فإن استقام وإلا رفع أمره إلى ولي الأمر حتى يستتاب، فإن تاب وإلا قتل، ويستحق الهجر، وألا يكلم حتى يتوب إلى الله . وهكذا من يأكل الربا قد تعاطى معصية، يستحق أن يهجر عليها، لكن ينصح ويوجه إلى الخير؛ لعله يدع الربا، هذا هو الواجب على إخوانه المسلمين من أقاربه، وغيرهم أن ينصحوه ويوجهوه؛ لأن أكل الربا من المحرمات، والرسول ﷺ: لعن آكل الربا وموكله والله يقول -جل وعلا-: وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا [البقرة:275] ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا إِنْ كُنتُمْ مُؤْمِنِينَ ۝ فَإِنْ لَمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِنَ اللَّهِ وَرَسُولِهِ [البقرة:278-279] فالواجب الحذر.  ومن أصر على أكل الربا أو تخلف عن الصلاة استحق أن يهجر، واستحق أن يؤدب حتى يتوب إلى الله  نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11762/كيفية-التعامل-مع-تارك-الصلاة-واكل-الربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51707.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":13506,"question":"السائل (م. ع. ع) من حلب يقول في هذا  أنا طالب في المرحلة الثانوية الفرع العلمي، وقد شغلني تحصيل العلوم الدنيوية عن التفقه في دين الله، فهل أنا آثم على ذلك يا سماحة الشيخ؟","title":"حكم الانشغال بالعلوم الدنيوية وترك التفقه في الدين","answer":"الجواب: نعم، يجب عليك أن تتفقه في دينك، يجب أن تتعلم، ولا تشغل بالعلوم الدنيوية عن العلوم الدينية، الله أوجب عليك أن تعبده ولا طريق إلى العبادة إلا بالفهم والعلم، فعليك أن تتعلم ما تعرف به دينك، والعبادة التي خلقت لها؛ لقوله سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ الذاريات:56] عليك أن تعرف هذه العبادة، وأن تؤديها كما أمر الله، يقول النبي ﷺ: من يرد الله به خيرًا؛ يفقهه في الدين. فلا بد من أن تتعلم ما تحصل لك به الفقه في الدين حتى تؤدي ما أوجب الله عليك عن بصيرة، وحتى تترك ما حرم الله عليك على بصيرة، هذا هو الواجب، الواجب أن تعرف من دينك ما لا يسعك جهله، تعرف ما أوجب الله عليك، وما حرم عليك؛ حتى تؤدي الواجب؛ وحتى تبتعد عن المحرم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11827/حكم-الانشغال-بالعلوم-الدنيوية-وترك-التفقه-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53109.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13539,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، وقع في نهايتها توقيعًا غير مقروء، كل الرسالة وفيها ستة أسئلة تدور حول تارك الصلاة، ولا سيما إذا كان أبًا أو عمًا، وتارك الصلاة هذا قد يصلي الجمعة فقط، وقد يصلي بعض الفروض، ويترك الفروض الأخرى.ويسأل سماحة الشيخ هل يجوز تقبيل رؤوسهم، وهل يجوز بدؤهم بالسلام، ويرجو التوجيه حول هذا الموضوع الخطير؛ لأنه يلاحظ انتشاره في الكثير من المحلات. جزاكم الله خيرًا.","title":"هل يجوز تقبيل رأس تارك الصلاة؟","answer":"الجواب: ترك الصلاة جريمة عظيمة ومنكر شنيع، وقد اختلف العلماء -رحمة الله عليهم- في كفر صاحبه إذا لم يجحد وجوبها، وإنما تكاسلًا، فعله تكاسلًا وتهاونًا، فقال بعضهم: يكون كفرًا أصغر، وقال بعضهم: بل يكفر كفرًا أكبر، وهذا هو الصواب، ولو صلى الجمعة بعض الأحيان، ولو صلى بعض الأوقات؛ لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها؛ فقد كفر؛ وقوله ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة. فالصواب: أنه يكون كفرًا أكبر، لكن إذا كان التارك الوالدين، أو أحدهما فإنك ترفق بهما، وتنصحهما، كما قال الله  في الكافرين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] لأن الوالد له حق عظيم، ولو كان كافرًا عليك أن ترفق به، وأن تصحبه بالمعروف؛ لعل الله يهديه بأسبابك، ولو قبلت رأسه ترجو أن الله يهديه بسبب ذلك؛ فلا بأس بذلك، هذا من المعروف وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] والدعاء له أن الله يوفقه، ويهديه، ويشرح صدره إلى الحق، والإنفاق عليه إذا كان محتاجًا، كل ذلك من أسباب هدايته. أما غير الوالدين إذا لم يقبل الحق؛ فإنه يهجر، يستحق الهجر، لا تجاب دعوته إلى عرس، ولا غيره، ولا يدعى إلى وليمة، ولا يصافح، ولا يسلم عليه، بل يهجر حتى يتوب، وينبغي أن يرفع أمره إلى ولي الأمر إذا كان في بلاد إسلامية، يرفع أمره إلى ولي الأمر حتى يستتاب، فإن تاب وإلا وجب قتله عند جمهور أهل العلم.","link":"https://binbaz.org.sa/fatwas/11853/هل-يجوز-تقبيل-راس-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_479/47909.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":13568,"question":"هذه التي رمزت لاسمها بـ (أ. أ) تقول: بأنها فتاة في الثلاثين من العمر متزوجة، وأم لأطفال، ومتزوجة من رجل ملتزم بالشرع الإسلامي، والحمد لله والمنة على ذلك، تقول: ولكن مشكلتي في أن لي إخوانًا وأخوات يوجد في بيوتهم منكرات، وزوجي يمنعني من زيارتهم، ويقول: لا يجوز لك أن تقومي بزيارتهم، أو تذهبي إليهم، ويقول لي: بأنه سمع من المشايخ: بأنه لا يجوز الذهاب إلى من لديهم منكرات في بيوتهم، ولا الصلة لرحمهم في ذلك إلا بالتلفون، فوجهونا سماحة الشيخ.","title":"حكم منع الزوجة من زيارة أقاربها لوجود منكرات","answer":"الجواب: لا شك أن وجود المنكرات في البيت إذا كانت ظاهرة ما هي بمستورة يستحق أهلها الهجر، من أبدى المعاصي، وأظهر المعاصي يستحق الهجر، إما سنة وإما واجب، اختلف العلماء هل الهجر سنة، أو واجب؟ قال بعضهم: يجب إذا كان يترتب عليه ترك المنكرات، أما إذا لم يترتب عليه ترك المنكرات؛ فهو سنة مؤكدة. وقال بعضهم: بل يجب مطلقًا، قد هجر النبي ﷺ ثلاثة من الصحابة تخلفوا عن الغزو بغير عذر، هجرهم خمسين ليلة حتى تاب الله عليهم، وهجرهم الصحابة، فالذي يبدي المعاصي، ويظهرها، ولا يبالي؛ يستحق الهجر، سواءً كان أخًا، أو عمًا، أو غير ذلك، وهكذا من يكون في بيته المعاصي الظاهرة من شرب الخمر ظاهرًا، أو تعاطي الزنا ظاهرًا، أو ما أشبه ذلك ممن يتعاطى المعاصي الظاهرة؛ يستحق الهجر، وأما من يستتر، ولا يبدي المعاصي، بل يخفيها؛ فأمره إلى الله -جل وعلا- ولكن الحكم يتعلق بمن يظهر المعاصي، يقول ابن عبدالقوي -رحمه الله- في هذا المعنى:","link":"https://binbaz.org.sa/fatwas/11892/حكم-منع-الزوجة-من-زيارة-اقاربها-لوجود-منكرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_522/52210.mp3","categories":["الدعوة والدعاة","قضايا المرأة"]},{"id":13660,"question":"تقول هذه السائلة من حضرموت من اليمن (م. م) تقول: بعض الأخوات يرفضن القيام بالدعوة إلى الله في مجال النساء بحجة أنهن يخفن أن يقلن ما لا يعلمن؛ فيتحملن بذلك الإثم، وإثم غيرهن، هل من توجيه في ذلك؟","title":"حكم ترك الدعوة بحجة الخوف من القول بغير علم","answer":"الجواب: الواجب الدعوة إلى الله، والتعليم إذا كانت المرأة عندها علم، وأما إذا كان ما عندها علم ما يجوز لها أن تتكلم؛ لأن الله -جل وعلا- يقول: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108] ويقول -جل وعلا-: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [الأعراف:33]. فليس لأحد أن يقول على الله بغير علم، لا رجل، ولا امرأة، لكن المرأة إذا كان عندها علم الواجب عليها أن تنقل العلم لأخواتها في الله من جيرانها، من جليساتها، من أهل بيتها، ترشد الناس، تعلم الناس، كما كان أصحاب النبي ﷺ رجالًا، ونساء، يرشدون، ويعلمون. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11994/حكم-ترك-الدعوة-بحجة-الخوف-من-القول-بغير-علم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_529/52903.mp3","categories":["الدعوة والدعاة","قضايا المرأة"]},{"id":13661,"question":"في سؤال لها تقول هذه السائلة: هل هناك شرح موجز، ومبسط لكتاب عمدة الأحكام، وما هي الكتب الفقهية التي تنصحوننا بقراءتها؟ وجزاكم الله خيرًا.","title":"كتب ينصح بحفظها وقراءتها","answer":"الجواب: عمدة الحديث لها شروح لابن دقيق العيد، ولغيره من العلماء، الشيخ عبدالعزيز بن فيصل -رحمه الله- الشيخ عبدالله بن بسام، لها شروح طيبة مفيدة، وهي أحاديث واضحة بحمد الله، فالذي يحفظها يعلم معانيها بسهولة، أحاديث واضحة، عربية واضحة، ولها شروح -بحمد الله- مفيدة، ونفس الأحاديث مشروحة في مسلم، وفي البخاري؛ لأنها من أحاديث الصحيحين. فأنا أوصي بحفظ عمدة الحديث كتاب جيد، للشيخ عبدالغني بن عبدالواحد المقدسي، حفظ هذا الكتاب مهم جدًا ومفيد، هكذا بلوغ المرام للحافظ ابن حجر ، هكذا الأربعون النووية، وتكميلها لابن رجب كلها خمسون حديثًا مفيدة من جوامع الكلم أوصي بحفظها، كذلك عمدة الفقه للموفق مختصرة، وكذلك زاد المستقنع للشيخ موسى الحجاوي، كتاب مفيد في الفقه مختصر. ومن الكتب التي ينبغي أن يهتم بها في العقيدة: كتاب التوحيد، وكشف الشبهات، وثلاثة الأصول، والقواعد الأربع، كلها للشيخ محمد بن عبدالوهاب -رحمه الله- مفيدة في العقيدة، كذلك العقيدة الواسطية لشيخ الإسلام ابن تيمية في العقيدة كتاب مهم، نوصي بحفظ هذه الكتب، والعناية بها، والمذاكرة فيها مع الرجال والنساء؛ لأنها مفيدة وواضحة ليس فيها تعقيد. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11995/كتب-ينصح-بحفظها-وقراءتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_529/52904.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13695,"question":"السائلة سمية محمد من اليمن لها مجموعة من الأسئلة تقول سماحة الشيخ: هل يحرم على المؤمن أن يقرأ كتبًا غير إسلامية، وغيرها من الكتب التي ليس فيها شيء عن الإسلام؟","title":"حكم قراءة الكتب غير الإسلامية","answer":"الجواب: إذا كانت الكتب فيها شيء ينفع؛ لا بأس بقراءتها، ولو في أمور الدنيا، إن كان من الطب، والكتب الأخرى في معادن، في أشياء تنفع؛ فلا بأس، إذا كانت في شيء مباح. أما الكتب التي في أشياء تضل الناس، وتلبس على الناس دينهم، مثل كتب أهل الكلام؛ هذه لا يجوز النظر فيها، ولا قراءتها؛ لأن كتب أهل الكلام تدعو إلى الشر والبدعة، والتحلل من الدين، والشك في دين الله، فالواجب الحذر منها.  أما كتب تتكلم عن مصالح الذهب، فوائد الفضة، فوائد البترول، فوائد كذا، فوائد كذا.. من المباحات هذه تنفع الأطباء وتنفع غيرهم؛ فلا حرج في ذلك، وهكذا الكتب التي تتكلم عن الزراعة، عن مصالح الزراعة، عن فوائد لحم الإبل.. لحم الغنم، الشيء الذي فيه فائدة؛ لا بأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12066/حكم-قراءة-الكتب-غير-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54502.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13781,"question":"رسالة وصلت إلى البرنامج من المستمع هنداوي إبراهيم مقيم في العراق حاليًا، أخونا يقول: ما هي كتب الفقه التي ترون أن نقرأها؟ وأرشدوني لو تكرمتم إلى بعض كتب السيرة الصحيحة.","title":"كتب ينصح بقراءتها في الفقه","answer":"الجواب: كتب الفقه كثيرة، ولكن من أحسنها فيما نعلم: المغني للموفق ابن قدامة، وهو كتاب عظيم مطول، وشرح المهذب للنووي وتكملته هذان كتابان عظيمان، ومن المختصرات زاد المستقنع للحجاوي في مذهب الحنابلة، وهو كتاب مفيد وعليه شرح حواشي مفيدة، والعمدة للموفق كتاب مختصر في الفقه الموفق ابن قدامة. أما كتب المذاهب الثلاثة المالكية الحنفية الشافعية المختصرة فلا أذكر الآن شيئاً من مختصراتها التي أحول عليها، وفي إمكانك سؤال بعض أهل العلم الذين يعرفون شيئاً منها ليرشدوك إلى ما تريد، ولكن أنصحك بأن تعتني بكتب الحديث المختصرة مثل عمدة الحديث للشيخ عبد الغني بن عبد الواحد المقدسي، ومثل بلوغ المرام للحافظ ابن حجر، والأربعين النووية وتتمتها للحافظ ابن رجب، هذه كتب مفيدة وعظيمة النفع، وإذا حفظت معها العمدة للموفق في الفقه لتعينك على بعض المسائل أو ما يماثلها من كتب الفقه من المذاهب الأخرى المختصرة المفيدة فهذا حسن تستعين بها على معرفة المسائل ثم على معرفة حكمها في الدليل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12143/كتب-ينصح-بقراءتها-في-الفقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_601/60104.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13788,"question":"السائل جمال صالح من اليمن يقول: كيفية إقناع الناس في طريق الدعوة كيف يتحتم ذلك، وما هي الأسس السليمة للدعوة إلى الله؟","title":"هل يلزم إقناع الناس عند الدعوة إلى الله؟","answer":"الجواب: إقناع الناس قد لا يتيسر، لكن الذي على الداعية البيان، يبين ويوضح والله هو الذي يهدي من يشاء، قال الله جل وعلا: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]، وقال تعالى: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا [فصلت:33]، وقال سبحانه: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ أَنَا وَمَنِ اتَّبَعَنِي [يوسف:108]، وقال جل وعلا: وَمَا كَانَ اللَّهُ لِيُضِلَّ قَوْمًا بَعْدَ إِذْ هَدَاهُمْ حَتَّى يُبَيِّنَ لَهُمْ مَا يَتَّقُونَ [التوبة:115]، ما قال: حتى يتبين، قال: حتى يبين لهم ما يتقون.\nفالمقصود البيان والإيضاح، والله يقول: هَذَا بَلاغٌ لِلنَّاسِ [إبراهيم:52]، هَذَا بَيَانٌ لِلنَّاسِ [آل عمران:138]، فالمقصود البلاغ والبيان، والله هو الذي يهدي من يشاء، يقول سبحانه: لَيْسَ عَلَيْكَ هُدَاهُمْ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [البقرة:272]، فليس من شرط الدعوة أن تقنعه، قد يكون مكابر قد يكون معاند لا يقنع، وإن كان الكلام مقنعًا والإيضاح مقنعًا لكن قد لا يقتنع، قد يقول: ما اقتنعت، فلا يلتفت إلى قوله، متى بلغ وأنذر وحذر وجبت عليه الحجة ووجب أخذه بها ولا يلتفت إلى قوله: أنا ما قنعت، إنما المقصود البيان، فمتى أبلغ الحجة وبين له الأمر وجب أن يعامل بمقتضى ذلك، فإن كان لا يصلي وجب أن يعامل بما يقتضيه الحكم الشرعي من قتله إن لم يتب، وإن كان يسب الله ورسوله أو يتعاطى أمورًا من الردة عومل بما يستحق وهكذا في جميع المسائل يعامل بما يستحق بعد البيان والإيضاح، ولو قال: إني لم أقتنع، يبين له باللغة التي يفهمها. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12149/هل-يلزم-اقناع-الناس-عند-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53002.mp3","categories":["الدعوة والدعاة"]},{"id":13819,"question":"هذا سائل للبرنامج يقول في هذا  هناك شخص يحدث ويقرأ في كتاب بعد أذان العشاء حتى إقامة الصلاة، فعندما يقرأ الحديث يشرح بعض ألفاظه ويأتي ببعض الكلام العامي، وقد يضحك الجلوس أو المستمعين في المسجد من خلال هذا الكلام، وإن لم يكن قصده ذلك، وإنما قصده أن يفهم المستمعين الحديث، فهل في ذلك شيء؟ يا سماحة الشيخ.","title":"حكم شرح الحديث النبوي بالألفاظ العامية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن المشروع للمدرس والمذكر أن يوضح للمخاطبين ما يريد بالأساليب الواضحة التي يفهمونها؛ لأن المقصود نصيحتهم وتوجيههم إلى الخير، فيحدثهم بما يعرفون، مثل ما قال علي : \"حدثوا الناس بما يعرفون أتحبون أن يكذب الله ورسوله؟\"، ويشرع له تجنب الألفاظ التي قد تضحك الناس ويأتي بألفاظ أخرى توضح المراد من دون أن تسبب إضحاكًا أو لعبًا أو ما أشبه ذلك مما يخالف المطلوب في هذا المقام العظيم.\nالمقصود: أن المحاضر أو المدرس أو الواعظ يتحرى الألفاظ الواضحة التي يعرفها الناس ويفهمونها؛ لأن المقصود وعظهم وتذكيرهم وتفهيمهم ودعوتهم إلى الخير، أما الألفاظ التي قد تسبب ضحكًا أو استغرابًا فالمشروع له تجنبها.\nالمقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12182/حكم-شرح-الحديث-النبوي-بالالفاظ-العامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53701.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13863,"question":"المستمع (ن. ن. ن) بعث بعدد من الأسئلة يسأل في أحد أسئلته عن الكيفية الصحيحة للأمر بالمعروف والنهي عن المنكر، وما هي الحكمة المقصودة في مثل هذا المقام؟","title":"الكيفية الصحيحة في الأمر بالمعروف والنهي عن المنكر","answer":"الجواب: هذا سؤال عظيم وجدير بالعناية؛ لأن الأمر بالمعروف أو النهي عن المنكر من أهم الواجبات ومن فرائض الإسلام، ولأن القيام بذلك من أهل العلم والإيمان والبصيرة من أعظم الأسباب في صلاح المجتمع وسلامته من عقاب الله سبحانه واستقامته على الصراط المستقيم.\nولهذا يقول سبحانه: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللَّهِ [آل عمران:110] فجعلهم خير أمة بسبب هذه الأعمال الطيبة، وقال سبحانه: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَأُوْلَئِكَ هُمُ الْمُفْلِحُونَ [آل عمران:104] وصفهم بالفلاح لهذا الأمر العظيم لدعوتهم إلى الخير وأمرهم بالمعروف ونهيهم عن المنكر، فجعلهم مفلحين بعملهم الطيب، والفلاح: هو الحصول على كل خير، الحصول على أسباب السعادة، وقال : وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُوْلَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71] فوعدهم الرحمة على أعمالهم الطيبة التي منها الأمر بالمعروف والنهي عن المنكر.\nوهذا يدل على أن هذا هو الواجب على المؤمنين والمؤمنات ليس خاصًا بأحد دون أحد، بل هذا هو الواجب على المؤمنين والمؤمنات وهو من صفاتهم العظيمة وأخلاقهم الكريمة لكن يكون بالحكمة، يكون بالعلم لا بالجهل ولا بالعنف والشدة ولكن بالعلم، يأمر بالمعروف وينهى عن المنكر عن علم وعن بصيرة بما أمر الله به وما نهى الله عنه، فالمعروف هو ما أمر الله به ورسوله، والمنكر هو ما نهى الله عنه ورسوله.\nفالواجب على الآمر الناهي أن يكون ذا بصيرة أن يكون على علم سواء كان رجل أو امرأة لابد أن يكون على علم وإلا فليمسك حتى لا يأمر بالمنكر أو ينهى عن المعروف، قال تعالى: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108] يعني: على علم، ويقول سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] والدعوة إلى الله من جنس الأمر بالمعروف والنهي عن المنكر؛ لأنه بيان الحق وإظهاره للناس، فالآمر كذلك يدعو إلى الله والناهي كذلك إلا أن الآمر والناهي قد يكون عنده من السلطة ما يردع المنكر ويلزم بالمعروف، والداعي إلى الله أوسع من ذلك يبين للناس ويرشدهم إلى الحق وقد لا تكون عنده سلطة للإلزام.\nفالحاصل أن الواجب على الداعي إلى الله والآمر بالمعروف والناهي عن المنكر أن يكون على علم وأن يكون على بينة وعلى بصيرة حتى لا يأمر بما يخالف الشرع، وحتى لا ينهى عما هو موافق للشرع. والواجب أيضًا أن يكون برفق وعدم عنف وعدم كلمات بذيئة، بل يكون بكلام طيب وأسلوب حسن ورفق كما قال الله : فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لانْفَضُّوا مِنْ حَوْلِكَ [آل عمران:159] وقال سبحانه لـموسى وهارون لما بعثهما إلى فرعون: فَقُولا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى [طه:44] فالآمر الناهي يرفق بالناس ويأمر بالألفاظ الحسنة وينهاهم بالألفاظ الحسنة حتى يكون ذلك أقرب إلى قبول أمره ونهيه والاستفادة من ذلك إلا من ظلم وتعدى وأبى فهذا له أسلوب آخر من التعنيف والتأديب إذا لم يلتزم بالأمر بالمعروف ولم ينته عن المنكر، أما في أول الأمر فإنه يخاطبهم بالتي هي أحسن ويرشدهم وينصحهم حتى يلتزموا الحق، فمن عاند وأبى فله حال أخرى من جهة إجراء ما يستحق من تعنيف ومن تشديد وتأديب أو سجن أو غير ذلك مما يقتضيه الشرع المطهر، والله المستعان. نعم.\nالمقدم: الله المستعان على كل حال، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12237/الكيفية-الصحيحة-في-الامر-بالمعروف-والنهي-عن-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_603/60308.mp3","categories":["الدعوة والدعاة","نصائح وتوجيهات"]},{"id":13866,"question":"المستمع (ن. ن. ن) بعث بعدد من الأسئلة يسأل في أحد أسئلته عن الكيفية الصحيحة للأمر بالمعروف والنهي عن المنكر، وما هي الحكمة المقصودة في مثل هذا المقام؟","title":"الكيفية الصحيحة في الأمر بالمعروف والنهي عن المنكر","answer":"الجواب: هذا سؤال عظيم وجدير بالعناية؛ لأن الأمر بالمعروف أو النهي عن المنكر من أهم الواجبات ومن فرائض الإسلام، ولأن القيام بذلك من أهل العلم والإيمان والبصيرة من أعظم الأسباب في صلاح المجتمع وسلامته من عقاب الله سبحانه واستقامته على الصراط المستقيم.\nولهذا يقول سبحانه: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللَّهِ [آل عمران:110] فجعلهم خير أمة بسبب هذه الأعمال الطيبة، وقال سبحانه: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَأُوْلَئِكَ هُمُ الْمُفْلِحُونَ [آل عمران:104] وصفهم بالفلاح لهذا الأمر العظيم لدعوتهم إلى الخير وأمرهم بالمعروف ونهيهم عن المنكر، فجعلهم مفلحين بعملهم الطيب، والفلاح: هو الحصول على كل خير، الحصول على أسباب السعادة، وقال : وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُوْلَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71] فوعدهم الرحمة على أعمالهم الطيبة التي منها الأمر بالمعروف والنهي عن المنكر.\nوهذا يدل على أن هذا هو الواجب على المؤمنين والمؤمنات ليس خاصًا بأحد دون أحد، بل هذا هو الواجب على المؤمنين والمؤمنات وهو من صفاتهم العظيمة وأخلاقهم الكريمة لكن يكون بالحكمة، يكون بالعلم لا بالجهل ولا بالعنف والشدة ولكن بالعلم، يأمر بالمعروف وينهى عن المنكر عن علم وعن بصيرة بما أمر الله به وما نهى الله عنه، فالمعروف هو ما أمر الله به ورسوله، والمنكر هو ما نهى الله عنه ورسوله.\nفالواجب على الآمر الناهي أن يكون ذا بصيرة أن يكون على علم سواء كان رجل أو امرأة لابد أن يكون على علم وإلا فليمسك حتى لا يأمر بالمنكر أو ينهى عن المعروف، قال تعالى: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108] يعني: على علم، ويقول سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] والدعوة إلى الله من جنس الأمر بالمعروف والنهي عن المنكر؛ لأنه بيان الحق وإظهاره للناس، فالآمر كذلك يدعو إلى الله والناهي كذلك إلا أن الآمر والناهي قد يكون عنده من السلطة ما يردع المنكر ويلزم بالمعروف، والداعي إلى الله أوسع من ذلك يبين للناس ويرشدهم إلى الحق وقد لا تكون عنده سلطة للإلزام.\nفالحاصل أن الواجب على الداعي إلى الله والآمر بالمعروف والناهي عن المنكر أن يكون على علم وأن يكون على بينة وعلى بصيرة حتى لا يأمر بما يخالف الشرع، وحتى لا ينهى عما هو موافق للشرع. والواجب أيضًا أن يكون برفق وعدم عنف وعدم كلمات بذيئة، بل يكون بكلام طيب وأسلوب حسن ورفق كما قال الله : فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لانْفَضُّوا مِنْ حَوْلِكَ [آل عمران:159] وقال سبحانه لـموسى وهارون لما بعثهما إلى فرعون: فَقُولا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى [طه:44] فالآمر الناهي يرفق بالناس ويأمر بالألفاظ الحسنة وينهاهم بالألفاظ الحسنة حتى يكون ذلك أقرب إلى قبول أمره ونهيه والاستفادة من ذلك إلا من ظلم وتعدى وأبى فهذا له أسلوب آخر من التعنيف والتأديب إذا لم يلتزم بالأمر بالمعروف ولم ينته عن المنكر، أما في أول الأمر فإنه يخاطبهم بالتي هي أحسن ويرشدهم وينصحهم حتى يلتزموا الحق، فمن عاند وأبى فله حال أخرى من جهة إجراء ما يستحق من تعنيف ومن تشديد وتأديب أو سجن أو غير ذلك مما يقتضيه الشرع المطهر، والله المستعان. نعم.\nالمقدم: الله المستعان على كل حال، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12237/الكيفية-الصحيحة-في-الامر-بالمعروف-والنهي-عن-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_603/60308.mp3","categories":["الدعوة والدعاة","نصائح وتوجيهات"]},{"id":13900,"question":"السائل عبدالله عبدالرحمن من ليبيا له مجموعة من الأسئلة يقول: أريد أن أتفقه في الدين وأنا طالب علم شرعي، فحبذا لو ذكر لنا سماحة الشيخ عبد العزيز بعض الكتب في الفقه التي توصونني بقراءتها؟","title":"كتب يُنصح طالب العلم بها","answer":"الجواب: نوصيك بالقرآن الكريم، والإكثار من تلاوته، فهو أعظم كتاب وأشرف كتاب، وفيه العلم العظيم؛ يعلمك أصول دينك، ويعلمك الأحكام الشرعية في صلاتك وغيرها، فنوصيك بالقرآن الكريم والإكثار من تلاوته، وتدبر معانيه، ثم نوصيك أيضًا بالسنة؛ حفظ ما تيسر من السنة مثل: بلوغ المرام ... مثل: عمدة الحديث، فهذان كتابان عظيمان مختصران وفائدتهما عظيمة؛ فنوصيك بحفظ ما تيسر منهما، أو بحفظهما جميعًا، مع الأربعين النووية وتتمتها لابن رجب خمسين حديثًا من جوامع الكلم فائدتها عظيمة، ونوصيك بكتب العقيدة مثل كتاب التوحيد .. كشف الشبهات للشيخ محمد بن عبد الوهاب رحمه الله، ثلاثة الأصول، والأربع القواعد له أيضًا، العقيدة الواسطية لشيخ الإسلام ابن تيمية كتاب عظيم مفيد في العقيدة، نوصي جميع الطلبة بهذه الكتب؛ لأنها مفيدة جدًا والحاجة إليها ماسة، ونوصي الجميع أيضًا بكتب شيخ الإسلام ابن تيمية الأخرى مثل: التدمرية والحموية، ومثل كتب ابن القيم رحمه الله فإنه من أهل السنة والجماعة، ومثل: شرح الطحاوية لابن أبي العز كتاب عظيم مفيد، كتاب التوحيد لابن خزيمة. وأما الفقه فكتبه كثيرة فإذا حفظ مثل زاد المستقنع للحجاوي مثل: كتاب الفقه للموفق أو دليل الطالب، المقصود: إذا تيسر له أحد الكتب المؤلفة في الفقه للأئمة المعروفين من أهل السنة فلا بأس يستعين بها على فهم النصوص يستعين بهذا الكتاب لكن لا يقلد ولا يتعصب وإنما يستعين به على فهم النصوص فهذا لا بأس به، زاد المستقنع .. دليل الطالب وما أشبه ذلك من الكتب التي ألفت في الفقه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12282/كتب-ينصح-طالب-العلم-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53813.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":13973,"question":"السائل أخونا من الجزائر الحقيقة له بقية أسئلة يقول في سؤاله الثاني: ما كيفية الدعوة إلى الله ؟ وما هي الشروط التي يجب أن تتوفر في الداعي إلى الله ؟ وهل الدعوة إلى الله واجبة؟ جزاكم الله خيرًا.","title":"كيفية الدعوة إلى الله والصفات المطلوبة في الداعية","answer":"الجواب: نعم، الكيفية بينها الرب ، قال سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ[النحل:125] هكذا السنة، قال جل وعلا: فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لانْفَضُّوا مِنْ حَوْلِكَ[آل عمران:159] وقال الله لموسى وهارون لما بعثهما إلى فرعون: فَقُولا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى[طه:44]. فالسنة للداعي أن يرفق وأن يجمع بالحكمة بالعلم، قال الله .. قال الرسول، ويعتني بالموعظة الحسنة .. الترغيب والترهيب، يذكر ما جاء من الوعيد في المعاصي وما جاء من الأجر العظيم والخير الكثير في الطاعات، ويجادل بالتي هي أحسن عند وجود الشبه والاشتباه، يجادل بالتي هي أحسن وبالبيان الواضح ولا يشدد بل يرفق؛ لأن هذا أقرب إلى القبول والتأثر. ولا بد من شرط البصيرة شرط العلم، لا بد أن يكون الداعي عنده علم وعنده بصيرة، قال الله جل وعلا: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ[يوسف:108] فالواجب على الداعية إلى الله أن يكون على بصيرة .. على علم، وأن يرفق في دعوته ويجادل بالتي هي أحسن حتى لا ينفر الناس من الحق.\nوالواجب عليه أيضًا أن لا يخالف قوله فعله ولا فعله قوله، أن يقول الحق وأن يكون من أسرع الناس إليه، وأن ينهى عن الباطل وأن يكون من أبعد الناس من الباطل، هكذا يكون الداعي إلى الله؛ يدعو إلى الحق ويسارع إليه ويتخلق به، وينهى عن الباطل ويحذره ويبتعد عنه، ويرفق في دعوته، ويجتهد في ذكر الآيات والأحاديث؛ لأن ذلك يؤثر في القلوب ويسبب القبول.\nوالواجب عليه أن يكون من أسرع الناس إلى ما يدعو إليه، ومن أبعد الناس عما ينهى عنه، من الواجبات والمحرمات، فيكون أسرع الناس إلى كل واجب يدعو إليه، ومن أبعد الناس عن كل محرم ينهى عنه؛ حتى يتأسى بقوله وفعله، قال الله جل وعلا: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ[الأحزاب:21] فهو ﷺ كان يدعو ويعمل، فهو داعية إلى الله بقوله وفعله عليه الصلاة والسلام، فهكذا الدعاة، المشروع لهم أن يكونوا دعاة إلى الله بأفعالهم وأقوالهم، وأن يكونوا على بصيرة، وأن يحذروا القول على الله بغير علم. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12390/كيفية-الدعوة-الى-الله-والصفات-المطلوبة-في-الداعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_539/53904.mp3","categories":["الدعوة والدعاة"]},{"id":14018,"question":"رسالة وصلت إلى البرنامج من المستمع السيد حسن أحمد مصري مقيم في العراق، أخونا يسأل عن كتاب بدائع الزهور في وقائع الدهور، هل ما جاء في هذا الكتاب يعتبر من الصحيح؟","title":"تقييم كتاب: بدائع الزهور في وقائع الدهور","answer":"الجواب: لا، لا يعتمد، هذا الكتاب خرافي لا يعتمد ولا يعول عليه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12436/تقييم-كتاب-بداىع-الزهور-في-وقاىع-الدهور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_611/61106.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":14033,"question":"شيخ عبد العزيز! ما أشد حاجتنا إلى السؤال عن أمور ديننا، ألا ترون أنه يجب أن يكون هناك أشخاص متفرغون، همهم إفتاء الناس فيما يرد إليهم من أسئلة ولو عبر الهاتف.","title":"حاجة الأمة إلى من يبصرها بأمور دينها","answer":"الجواب: هذا من أهم المهمات، وهذا البرنامج من هذا القبيل، هذا البرنامج والحمد لله برنامج (نور على الدرب) هو قائم بهذه المهمة، وإذا تيسر من العلماء من يقوم بذلك أيضًا؛ كالعون لهذا البرنامج، فهذا خير عظيم.\nوالمقصود أن هذا البرنامج بحمد الله فيه خير عظيم، وقد يكون أدى فرض الكفاية، وإذا تيسر من العلماء -في المساجد وفي بيوتهم- من يفتي الناس -إذا كان عنده علم وبصيرة- بما قاله الله ورسوله؛ فهذا خير إلى خير، ومما يخفف على هذا البرنامج أيضًا.\nفالحاصل: أن هذا البرنامج فيه خير عظيم والحمد لله، وقد قام بواجب كبير في إفتاء الناس من الداخل والخارج، وفي حل المشاكل بالأدلة الشرعية؛ فنسأل الله أن يوفق القائمين عليه وأن يعينهم، وأن يمنحهم البصيرة والإخلاص والصدق، وأن يوفق المسلمين جميعًا في كل مكان لما فيه رضاه، ولما فيه صلاحهم ونجاتهم، وأن يوفق علماء المسلمين في كل مكان وفي كل بلد لأداء الواجب، وتوجيه الناس إلى الخير، وتعليمهم ما ينفعهم في دينهم، مع العناية بما قاله الله ورسوله، وأن تكون الفتوى على ضوء كلام الله وكلام رسوله عليه الصلاة والسلام، لا بالآراء المجردة، والله المستعان.\nالمقدم: الله المستعان، جزاكم الله خيرًا، إنما لا ترون أن يتفرغ شخص لهذا الموضوع أيضًا شيخ عبد العزيز ، دعمًا لهذا البرنامج؟\nالشيخ: إذا تيسر هذا طيب، إذا تيسر من هو أهل لذلك من أهل العلم والبصيرة في بيته أو في أي مكان؛ فجزاه الله خيرًا، طيب، الناس في حاجة إلى آلاف المفتين والموجهين، وفي حاجة في كل مكان. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12456/حاجة-الامة-الى-من-يبصرها-بامور-دينها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_607/60703.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":14202,"question":"للأخ (س. ع. م. ل) من الحبشة سؤال آخر يقول فيه: إنني كثيرًا ما أندفع للدعوة إلى الله  لكنني ألاحظ على نفسي عدم الامتثال لكل ما أقول وهذا يجعلني في حيرة وقلق، فبماذا تنصحونني؟ جزاكم الله خيرًا.","title":"توجيه لمن يدعو إلى الله ولا يطبق كل ما يقول","answer":"الجواب: ننصحك أن تستعين بالله في الدعوة وفي العمل، وأن تجاهد نفسك حتى تعمل بما أوجب الله، وحتى تنتهي عما حرم الله، وحتى تكون من أسبق الناس إلى ما تدعو إليه من الخير، وحتى تكون من أبعد الناس عما تنهى عنه من الشر، حتى لا يحتج عليك من تدعوه إلى الله، وحتى لا يقول: لو كان هذا صادقًا لما خالف قوله عمله وعمله قوله، الله يقول سبحانه: يَا أَيُّهَا الَّذِينَ آَمَنُوا لِمَ تَقُولُونَ مَا لا تَفْعَلُونَ  ۝  كَبُرَ مَقْتًا عِنْدَ اللَّهِ أَنْ تَقُولُوا مَا لا تَفْعَلُونَ[الصف:2، 3]، وينكر على بني إسرائيل ويقول لهم سبحانه: أَتَأْمُرُونَ النَّاسَ بِالْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنْتُمْ تَتْلُونَ الْكِتَابَ أَفَلا تَعْقِلُونَ[البقرة:44]. فعليك يا أخي أن لا تجبن وأن لا تضعف عن الدعوة إذا كان عندك علم تدعو إلى الله على حسب علمك وبصيرتك، وعليك أن تحذر القول على الله بغير علم، عليك أن تتفقه في الدين، وأن تتبصر، وأن تدعو إلى الله على بصيرة كما قال سبحانه: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ[يوسف:108]. فإذا كان عندك علم فادع إلى الله على حسب العلم الذي عندك من كتاب الله وسنة رسوله عليه الصلاة والسلام. وعليك أن تسأل أهل العلم المعروفين بالخير والفضل والبصيرة عما أشكل عليك، وأن تجتهد في تدبر كتاب الله والإكثار من قراءته، وهكذا السنة تجتهد في حفظ ما تيسر منها وتتعقل مراد النبي ﷺ، وتذاكر أهل العلم في ذلك حتى تكون على بينة. وعليك مع ذلك أن تعمل بما أوجب الله عليك، وأن تحذر ما حرم الله عليك، عليك أن لا تكون كالفتيلة يضيء للناس ويحرق نفسه، اتق الله لا تضئ للناس وتحرق نفسك، ولكن أضئ للناس ونور للناس واعمل بطاعة ربك واحذر معصيته . جعلنا الله وإياك من الهداة المهتدين. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12662/توجيه-لمن-يدعو-الى-الله-ولا-يطبق-كل-ما-يقول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_616/61604.mp3","categories":["الدعوة والدعاة","نصائح وتوجيهات"]},{"id":14243,"question":"سماحة الشيخ! بالنسبة للوعظ عند القبور ما رأيكم فيه؟","title":"حكم الوعظ عند القبور","answer":"الجواب: الوعظ لا بأس به، النبي وعظ عند القبر، جاء عنه ﷺ من حديث علي ومن حديث البراء بن عازب أنه وعظ الناس عند القبر وهم ينتظرون، وعظهم وذكرهم عليه الصلاة والسلام.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12700/حكم-الوعظ-عند-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53014.mp3","categories":["الدعوة والدعاة","أحكام المقابر"]},{"id":14259,"question":"أحد الإخوة المستمعين بعث يسأل ويرجو رأيكم شيخ عبد العزيز في كتاب روح الصلاة في الإسلام للمؤلف عفيف عبد الفتاح طبارة؟","title":"استفسار حول كتاب روح الصلاة في الإسلام","answer":"الجواب: لا أعلم حال الكتاب المذكور؛ لأني لم أقرأه، قد سمعت عنه ولكن لم أقرأه فلا أستطيع أن أحكم عليه بشيء. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12759/استفسار-حول-كتاب-روح-الصلاة-في-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_621/62108.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":14271,"question":"من الجمهورية العراقية ذي قار رسالة بعث بها مستمع من هناك هو (ع. ع. ناصر منصور الخلاوي) أخونا له جمع من الأسئلة فيسأل مثلًا ويقول: أرجو أن تنصحوني لقراءة بعض الكتب بعد كتاب الله وبعض كتب السنة لنبينا محمد ﷺ؟","title":"أرجو أن تنصحوني ببعض الكتب بعد الكتاب والسنة","answer":"الجواب: اللهم صل عليه وآله، ننصحك بقراءة الكتب المعتمدة المعروفة لأهل العلم والبصيرة والسنة والعقيدة الصالحة مثل كتب شيخ الإسلام ابن تيمية كتب ابن القيم رحمه الله كتب الحافظ ابن رجب كتب ابن كثير وأشباههم من أهل العلم والبصيرة، فإذا راجعت مثل كتاب اقتضاء الصراط المستقيم لشيخ الإسلام ابن تيمية الفتاوى لشيخ الإسلام ابن تيمية، زاد المعاد في هدي خير العباد لابن القيم، جامع العلوم والحكم في شرح الأربعين النووية للحافظ ابن رجب، تفسير ابن كثير، تفسير البغوي، تفسير ابن جرير، تفسير الشوكاني، فتح المجيد في شرح كتاب التوحيد للشيخ عبد الرحمن بن حسن، المجموعة المهمة: المجموعة النجدية في التوحيد ومسائل الدين والعقيدة، كل هذه كتب عظيمة ومفيدة، رياض الصالحين من كتب السنة كتاب مفيد، الوابل الصيب لابن القيم في الكلم الطيب. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12725/ارجو-ان-تنصحوني-ببعض-الكتب-بعد-الكتاب-والسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_617/61713.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":14411,"question":"السائل إبراهيم أبو حامد، يقول في هذا  سماحة الشيخ ما هو واجب المربين والمعلمين تجاه طلابهم؟ وهل هم أمانة يسألون عنها يوم القيامة؟","title":"واجب المربين والمعلمين تجاه طلابهم","answer":"الجواب: نعم، المربي والمعلم يجب عليه أن ينصح للمتعلم، والمربى يجب أن ينصح له ويوجهه إلى الخير، ويتقي الله فيه؛ لأنه أمانة، فالواجب على المربي والمعلم تقوى الله، وأن يجتهد في تربية الأولاد والأيتام والأطفال، وأن يحسن تعليمهم، وأن يتقي الله في ذلك، وأن يعلمهم مما علمه الله بالطريقة الشرعية، ومن ذلك تفقيههم في الصلاة وأمرهم بالصلاة إذا بلغوا سبعًا، وضربهم عليها إذا بلغوا عشرًا، كل هذا مما يجب على الولي وعلى المعلم أن يوجه الطلبة إلى هذا الخير، وإذا كان لم يؤذن له في الضرب يضربهم وليهم، إذا بلغوا عشرًا ولم يصلوا. فالحاصل: أن على الولي وعلى المعلم توجيه الطلبة من الرجال والنساء الطالبات والطلبة، وعليه تعليم الجميع، وتثقيف الجميع في الدين، حتى يتعلموا ما أوجب الله عليهم، وما حرم عليهم، الله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12893/واجب-المربين-والمعلمين-تجاه-طلابهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55308.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":14429,"question":"ما هي الصفات الواجب توفرها في الداعي المسلم لدعوة ملحد أو يهودي، أو نصراني، أي: هل باستطاعة أي مسلم أن يكون داعيًا إلى الله؟","title":"الصفات الواجب توافرها في الداعية","answer":"الجواب: ليس في استطاعة كل مسلم إلا بعد التعلم، الدعوة إلى الله تحتاج إلى علم، وتحتاج إلى لغة المخاطب أيضًا، والله يقول سبحانه: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ[يوسف:108] يعني: على علم، فمن أراد أن يدعو الناس إلى الله فليتعلم وليتفقه في الدين، وليعتني بالقرآن الكريم وتفسيره ومعرفة معانيه؛ وليحضر عند أهل العلم، يحضر حلقات العلم، يسأل أهل العلم عما أشكل عليه، حتى يصلح للدعوة، فإذا وجد من نفسه قوة على ذلك، واستشار من يطمئن إليه من أساتذته حتى يصلح للدعوة وحتى يوجهه إلى ما ينبغي، وحتى يشير عليه بما ينبغي أن يستعمل، فإذا وجد من نفسه القدرة؛ لأن عنده حصيلة من الأدلة الشرعية من الكتاب والسنة في أي موضوع من المواضيع التي يريد أن يدعو إليها، أو يناقش فيها فيتكلم، وإذا كانت لغة المدعو غير العربية فلا بد أن يستعين بمن يفهم اللغة من الثقات حتى يكون واسطة بينه وبينه في توجيه الخير، وإرشاده إلى الحق باللغة التي يفهمها، بواسطة من يعرف اللغة المذكورة من الثقات المعروفين بالعلم والفضل، وإذا كان الداعي يعرف اللغة، فهذا نعمة كبيرة، يدعو إلى الله باللغة التي يفهمها، ويعرفها المخاطب. وبكل حال فالصفات التي يجب توافرها في الداعي هي أن يكون عنده علم وعنده حلم وبصيرة حتى يدعو إلى الله على بينة وبرفق ولين، وبأسلوب يؤثر على المدعو، وأن يكون في نفسه صالحًا حتى لا يحتج عليه المدعو يقول: أنت تدعوني إلى كذا وأنت فاسد، تخالف أقوالك أعمالك، وأعمالك أقوالك، ينبغي له أن يكون حريصًا على أن يعمل بما يدعو إليه، وأن يحذر ما ينهى عنه، فالداعي يمثل دعوته بأفعاله وأخلاقه وسيرته مع الناس. وينبغي أيضًا أن تكون عنده حصيلة محفوظة من الأحاديث الصحيحة، ومن آثار السلف الصالح الذين قاموا بالدعوة حتى يتأسى بهم، مع كتاب الله  والعناية بحفظه وتدبر معانيه، والاستعانة بكلام أئمة التفسير المعروفين، بالعلم والفضل والعقيدة الصالحة، كالإمام ابن جرير والبغوي وابن كثير وغيرهم من أئمة التفسير الذين يستفاد من كلامهم في تفسير كلام الله . فالحاصل: أنه لا بد من بصيرة، ولا بد من أخلاق فاضلة، أن يكون ذا خلق كريم في حلمه وقوله وعمله وأساليبه حتى لا يجد المدعو ثغرة يدخل منها عليه لينتقصه أو ليهجن دعوته، ويقول: إنك لست كما تقول، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12917/الصفات-الواجب-توافرها-في-الداعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_631/nour_63103.mp3","categories":["نصائح وتوجيهات","الدعوة والدعاة"]},{"id":14436,"question":"سماحة الشيخ، كأنها تفرق بين دعوة الملحد ودعوة اليهودي، ودعوة النصراني هل هناك صفات معينة؟","title":"مراعاة الفروق بين أهل الكتاب والملحدين في الدعوة","answer":"الجواب: نعم، لا شك، اليهودي والنصراني عندهم إيمان بالآخرة، عندهم إيمان بالرسل، وإن كان إيمانهم مدخولًا، وإن كان لا ينفعهم؛ لأنهم خلطوا كفرًا وإيمانًا، لكن دعوتهم أسهل؛ لأنهم يخاطبون بكتب التي نزلت على الأنبياء، يخاطبون بالإيمان باليوم الآخر، وأن الواجب الإعداد لليوم الآخر، وأن الواجب طاعة الرسل، هم يعرفون طاعة الرسل لازمة، وأن محمدًا من الرسل -عليه الصلاة والسلام-، وتقام الحجج على رسالته -عليه الصلاة والسلام-، ويدعون إلى الإيمان به، واتباع شريعته، وأنه ليس هناك نجاة إلا باتباع محمد -عليه الصلاة والسلام-. فالحجة قائمة على اليهود والنصارى لما عندهم من العلم السابق من عهد الأنبياء، وإنما حملهم على الترك الهوى والحسد والبغي، ولا سيما اليهود، فإنهم أمة الحسد، وأمة البغي، وأمة الغضب، وأمة العناد، وهكذا أئمة النصارى الذين عرفوا الحق، ولكن آثروا الدنيا على الآخرة، فصاروا مشابهين لليهود في عنادهم وفي جحدهم الحق وهم يعلمون، نسأل الله العافية. لكن الغالب على النصارى الضلال والجهل، هم يحتاجوا إلى التعليم والتوجيه بالأدلة الشرعية حتى يدخل في الحق، وعنده أصل الإيمان بالآخرة، أصل الإيمان بوجود الله، وإن كان إيمانًا فاسدًا مشوشًا لا ينفعه في الآخرة؛ لأن اليهود اعتقدوا العزير ابن الله، والنصارى اعتقدوا المسيح ابن الله، وهو ثالث ثلاثة، وعندهم أيضًا غلو في أحبارهم ورهبانهم، كلهم عندهم غلو في أحبارهم ورهبانهم، وعندهم أنواع من التحريف والشر، لكنهم أسهل، دعوتهم أسهل من دعوة الملحد الشيوعي.  أما الملحد يحتاج إلى إقامة الأدلة على وجود الله، وعلى صحة ما جاءت به الرسل من العقل الذي يفهمه هو، فدعوته تحتاج إلى مزيد من البصيرة والحكمة والتجارب، ومعرفة سنن الله في عباده، وما فطر عليه العباد، حتى يخاطبه بمقتضى الفطرة والعقل، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12920/مراعاة-الفروق-بين-اهل-الكتاب-والملحدين-في-الدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_631/nour_63104.mp3","categories":["الدعوة والدعاة"]},{"id":14642,"question":"يسأل -سماحة الشيخ- عن كتاب الروح لـابن القيم؟","title":"توجيه عن كتاب الروح لابن القيم","answer":"الجواب: كتاب مفيد عظيم الفائدة، فيه علم جم، ومسائل مفيدة، وفيه بعض الأشياء المرجوحة، طالب العلم إذا قرأه يعرف الراجح من المرجوح، ولكنه كتاب مفيد جدًا في بابه، وفيه علم كثير، وتحقيقات كثيرة، ينتفع بها طالب العلم، ولكن ليس كل ما في الكتاب صحيحًا؛ لأن كل عالم يخطئ ويصيب، وكل عالم يؤخذ من قوله ويترك إلا الرسول -عليه الصلاة والسلام-، فهناك مرائي وأشياء ذكرها قد لا يتابع عليها، وكذلك ترجيحه لبعض المسائل قد لا يتابع عليه  ورحمه، ولكن هذا يحتاج إلى علم. فالذي يراجع الكتاب، ويقرأ الكتاب إذا كان ذا علم، وذا بصيرة، سوف يفهم ما يقوم عليه الدليل، وما لا يقوم عليه الدليل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13152/توجيه-عن-كتاب-الروح-لابن-القيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_627/nour_62708.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":14745,"question":"أريد أن أسأل عن التوسع في عدد حلقات طلب العلم في المساجد سماحة الشيخ، في القرى، في المدن الصغيرة، وفي المدن الكبيرة أيضًا.","title":"مشروعية التوسع في حلقات العلم في المدن","answer":"الجواب: ينبغي إذا تيسر العلماء، ينبغي التوسع في ذلك، ولو كان في كل مسجد؛ لأن كل مسجد جماعته في حاجة إلى التعلم والفائدة، فإذا وجد في البلد علماء فالمشروع لهم أن يعلموا الناس من طريق الحلقات، ومن طريق الدروس بعد العصر، أو بعد المغرب، أو بعد العشاء؛ حتى يستفيدوا، وكلٌ على حسب طاقته، الذي يستطيع الحلقة يقيم الحلقة، والذي لا يستطيعها ولو بالدرس بعد صلاة العصر أو غيرها، ولو درسًا مختصرًا؛ فإنه مع الدوام ينفع الله به ولو قليلًا، والذي لا يستطيع يتوسط في حق من يستطيع، ويشير عليه، وينصحه أن يقوم بهذا الدرس، أو بهذه الحلقة، إذا كان أهلًا لذلك، عنده من علم الكتاب والسنة ما يؤهله لذلك، وإذا كان في البلد عالمان، صار كل واحد في ناحية من البلد، وإذا كانوا ثلاثة هكذا، أو أربعة، أو أكثر، كلٌ إنسان يكون في حيٍ من الأحياء، وفي مسجدٍ واسع، حتى يعلم الناس، وحتى يفقه الناس، نعم. المقدم: جزاكم الله خيرًا.\nالواقع هذا الموضوع يحتاج إلى مزيدٍ من الطرح، ومزيدٍ من العناية، ولا سيما وأن الناس -سماحة الشيخ- يشكون أحيانًا كيف يقضون أوقات فراغهم؟ الشيخ: لا شك أن هذا موضوعٌ جديرٌ بالعناية، من الدولة، ومن العلماء، ومن الناس، فعلى الدولة أن تقوم بذلك، وأن تؤكد على العلماء أن يقوموا بهذا، ولو بالإلزام، ولو بفرض مرتبات لمن ليس له راتب يقوم بحاله، ويحتاج إلى راتب حتى يقوم بهذه المهمة، في القرى والأمصار، وعلى العلماء فيما بينهم أن يقوموا بهذا الواجب حسب طاقتهم، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] في الأوقات التي يستطيعونها، ولو في وقتٍ قصير، فإن التكرار ينفع الله به، ولو كانت المدة غير طويلة، في الوقت المناسب، بعد العصر، أو بعد المغرب، أو بعد العشاء، أو بعد الفجر، فإن الجلسة ولو كانت غير طويلة، بالتعليم والتوجيه ينفع الله بها الناس، عملاً بقوله تعالى: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، نعم. المقدم: جزاكم الله خيرًا، آمل أن نتمكن من العودة إلى هذا الموضوع في حلقاتٍ قادمة سماحة الشيخ.\nالشيخ: إن شاء الله.","link":"https://binbaz.org.sa/fatwas/13298/مشروعية-التوسع-في-حلقات-العلم-في-المدن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_641/nour_64110.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":14777,"question":"أخونا يسأل ويقول: هل حلقات العلم بعد العشاء تعتبر قيام ليل؟","title":"هل حلقات العلم بعد العشاء من قيام الليل؟","answer":"الجواب: الحلقات في العلم بعد العشاء قربة وطاعة، ولكنها لا تغني عن قيام الليل، ولكنها أفضل من قيام الليل. المقدم: أفضل؟ الشيخ: طلب العلم أفضل من قيام الليل، كونه يطلب العلم، ولو فاته قيام الليل، أفضل له من قيام الليل، مع بقائه في الجهل، فحلقات العلم أمرها عظيم، وفوائدها كبيرة، لا تعدلها بقية التطوعات، لكن إذا تيسر له الجمع بين الأمرين، يحضر حلقات العلم، أو ما تيسر منها، ويقوم من الليل ما تيسر، ولو بثلاث ركعات، أو خمس ركعات، كان هذا أفضل، جمعًا بين المصلحتين، كفعل النبي ﷺ، وفعل الصحابة -رضي الله عنهم-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13292/هل-حلقات-العلم-بعد-العشاء-من-قيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_641/nour_64107.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":14843,"question":"يسأل سؤال آخر ويقول: بعض العامة يقولون: إن سيدي فلان قد ظهر من قبره نور، وإن سيدي فلان يضع الجمر على لسانه فلا يحرقه، وإن سيدي فلان نادى ولده في بلد آخر فسمعه ابنه ولبى النداء، وإن الكاهن فلان سئل عن بهيمة مسروقة فدل على مكانها، وعندما نقول لهم: بأن هذه من أفعال الشيطان، بعضهم يكذب وينكر ذلك، والبعض يقول أقوالًا قبيحة، فهل نتجنبهم؛ لأنهم يسخرون من أهل التوحيد ودعاته؟أم نجابههم رغم ما سنتعرض له من أذى وسخرية؟أفيدونا، جزاكم الله خيرًا.","title":"وجوب الإنكار على المشعوذين والكهان","answer":"الجواب: كل هذا خرافات، يجب الإنكار على من فعله، ولا يجوز التساهل في ذلك، وعليكم الصبر، وأن يكون الكلام بالحكمة، والأسلوب الحسن؛ لعل الله أن يهديهم بأسبابكم، فإن هذه من شعوذة الشيطان، وتزيينه للباطل، خرج من قبر فلان نور، أو أنه كلم أباه في المحل الفلاني، وأجاب، أو أن البهيمة وجدت في محل كذا، هذه من أعمال الشياطين، والشياطين يتناقلون الأخبار، ويوصي بعضهم بعضًا بالباطل، فلا يجوز الاحتجاج بهم، ولا الاغترار بهم. والكهنة هم عباد الشياطين، لهم أصحاب من الجن يخبرونهم ويخبرون الناس، والنبي  قال: من أتى كاهنًا فصدقه بما يقول فقد كفر بما أنزل على محمد ﷺ فلا يجوز التصديق بهذه الخرافات، ولا يجوز الأخذ بها، بل يجب إنكارها، والتحذير منها، الله المستعان، نعم. المقدم: الله المستعان.","link":"https://binbaz.org.sa/fatwas/13351/وجوب-الانكار-على-المشعوذين-والكهان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_644/nour_64407.mp3","categories":["الدعوة والدعاة"]},{"id":15208,"question":"هذا السائل من تشاد، يقول في هذا  سماحة الشيخ، كنت أقوم بزيارة أهل الخير والعلماء والمشايخ، ولكنني أحيانًا أقوم بزيارة بيوت أهل البدع، وقصدي بذلك أن أدعوهم إلى طريق السعادة وإلى طريق السنة، هل يكون هذا فيه إثم؟ مأجورين.","title":"حكم زيارة أهل البدع من أجل دعوتهم","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فزيارة أهل العلم والإيمان من أهل السنة والجماعة، وزيارة الإخوان في الله قربة وطاعة، أما زيارة أهل البدع فلا تجوز زيارتهم على سبيل المؤانسة والمحبة، ونحو ذلك. أما إذا زارهم طالب العلم للموعظة والتذكير والتحذير من البدعة؛ هذا مشكور ومأجور؛ لأن هذا من باب الدعوة إلى الله، من باب الأمر بالمعروف والنهي عن المنكر، فإذا زرت هؤلاء الذين عندهم شيء من البدع زرتهم للدعوة إلى الله والنصيحة والتوجيه، فأنت مأجور، وينبغي أن لا تدع ذلك إذا كان فيه فائدة، أما إذا أصروا ولم يستجيبوا فدعهم.","link":"https://binbaz.org.sa/fatwas/13707/حكم-زيارة-اهل-البدع-من-اجل-دعوتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_565/56501.mp3","categories":["البدع والمحدثات","الدعوة والدعاة"]},{"id":15417,"question":"هذا آخر سؤال في حلقتنا اليوم من السائل محمد حمد الرحال، من الإمارات العربية، أبو ظبي، يقول: لي إخوة وأقارب لكنهم للأسف الشديد لا يصلون، ولا يقيمون حدود الله، فهل علي أن أقاطعهم؟ فكلما آمرهم بمعروف، أو أنهاهم عن منكر يهزؤون مني، ويسخرون، ويقولون: هل تريد أن تصلح الناس جميعًا؟ وقد كرهوا هم مجالستي، وقاطعوني، فماذا علي أن أفعل تجاههم؟","title":"توجيه لمن يسخر منه أقاربه عند نصحهم","answer":"الجواب: عليك أن تهجرهم وتقاطعهم ما داموا لم يقبلوا النصيحة، وهم على الحال التي ذكرت من قطعهم الصلاة، وبعدهم عن الخير، فينبغي لك أن تهجرهم، وأن تقاطعهم حتى يهديهم الله، هذا هو الواجب، بل هذا هو السنة المؤكدة، وبعض أهل العلم يرى وجوب ذلك وجوب المهاجرة والقطيعة لهم لضلالهم، وبعدهم عن الخير. لكن إذا اتصلت بهم بعض الأحيان، رجاء أن يهديهم الله بالدعوة والتوجيه والإرشاد فلا بأس، وإن يئست منهم فلا مانع من هجرهم ومباعدتهم بالكلية، وقد هجر النبي ﷺ ثلاثة من الصحابة؛ لما تركوا الغزوة معه بغير عذر.  فالحاصل: أن هؤلاء ينبغي أن يهجروا وعلى الأقل يكون هجرهم سنة مؤكدة حتى يهديهم الله، ويردهم إلى الصواب.\nنسأل الله لنا ولهم الهداية. المقدم: اللهم آمين، جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/13928/توجيه-لمن-يسخر-منه-اقاربه-عند-نصحهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_684/nour_68417.mp3","categories":["نصائح وتوجيهات","الدعوة والدعاة"]},{"id":15434,"question":"سماحة الشيخ -حفظكم الله-: ما هي الكتب التي ترشدون المسلمين في قراءتها الكتب؟ والوسائل التي تجعل المسلم على عقيدة سليمة وصحيحة؟","title":"ما الكتب التي ترشدون المسلمين بقراءتها؟","answer":"الجواب: أعظمها القرآن العظيم، يتدبر القرآن فيه الهدى والنور، إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] فالواجب على طالب العلم، وعلى حامل القرآن أن يتدبره ويتعقله، وإذا كان لا يقرأ يستمع يستفيد من القارئ، ومن إذاعة القرآن الكريم؛ حتى يستفيد من كلام الله، فيه الهدى والدعوة إلى مكارم الأخلاق، إلى توحيد الله والإخلاص له، إلى المحافظة على الصلاة، إلى الصدقة، إلى الإكثار من الذكر -ذكر الله-، الإكثار من الاستغفار، التحذير من المعاصي، القرآن فيه الهدى والنور. وهكذا أحاديث الرسول ﷺ يعتني بها، يحفظ ما تيسر منها، يسمعها، مثل: رياض الصالحين، الترغيب والترهيب، غيرها من كتب الحديث التي في أيدي المسلمين حتى يستفيد منها، وهكذا يسأل أهل العلم عما أشكل عليه، لا يسكت يسأل أهل العلم، الله يقول: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43] يسأل العلماء عما أشكل عليه، ثم يعمل بما أوجب الله، وينتهي عما حرم الله، نعم.","link":"https://binbaz.org.sa/fatwas/13953/ما-الكتب-التي-ترشدون-المسلمين-بقراءتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_568/56804.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":15535,"question":"هذا سائل للبرنامج يقول: ما نصيحتكم يا سماحة الشيخ، لطالب العلم المبتدئ من حيث حفظ المتون؟ مع العلم بأنه يحفظ القرآن كاملًا، والحمد لله.","title":"المتون التي ينصح طالب العلم بحفظها","answer":"الجواب: نصيحتنا له يحفظ المتون المهمة، مثل: كتاب التوحيد، كشف الشبهات، ثلاثة الأصول، العقيدة الواسطية لشيخ الإسلام ابن تيمية، والكتب الأولى للشيخ محمد بن عبد الوهاب: كتاب التوحيد كتاب عظيم، ثلاثة الأصول مع القواعد الأربع، فيها فائدة للشيخ -رحمه الله-، كشف الشبهات التي يتشبث بها عباد القبور، كونه يحفظها طيب، حتى يعرف الشبهات التي يشبه بها عباد القبور، والرد عليها، كذلك العقيدة الواسطية في بيان عقيدة أهل السنة والجماعة، كتاب مختصر جليل طيب. وفي الحديث: عمدة الحديث، بلوغ المرام كتابان جيدان، والأربعين النووية، وتتمتها لابن رجب خمسون حديثًا مهمة من جوامع الكلم، ننصح بحفظ هذه. وفي الفقه: مثل زاد المستقنع، كتاب جيد في الفقه، ومثل عمدة الفقه للموفق -رحمه الله- صاحب المغني، كتابان مختصران في الفقه جيدان، نعم.","link":"https://binbaz.org.sa/fatwas/14078/المتون-التي-ينصح-طالب-العلم-بحفظها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69117.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":15601,"question":"يقول: إنني أسكن مع مجموعة من الناس، وعند أذان الفجر أنبههم بحلول وقت الصلاة، فلا يقوموا لأدائها، فماذا علي في ذلك؟جزاكم الله خيرًا.","title":"الواجب على من يسكن مع أناس لا يصلون الفجر","answer":"الجواب: الواجب عليك نصيحتهم، وتحذيرهم من هذه المعصية، فإن استجابوا؛ وإلا فاتركهم واهجرهم، واترك النوم معهم؛ لأن ترك الصلاة في الجماعة معصية، وتركها في الوقت أعظم وأكبر، فالواجب عليك نصيحتهم، والإنكار عليهم؛ فإن استجابوا وقاموا لصلاة الفجر في وقتها، وإلا فعليك أن تهجرهم، وتغادر المكان، وألا تكون صاحبًا لهم، ولا مجالسًا لهم؛ لئلا يجروك إلى شرهم، نسأل الله العافية والسلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14135/الواجب-على-من-يسكن-مع-اناس-لا-يصلون-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70503.mp3","categories":["الدعوة والدعاة"]},{"id":15642,"question":"سؤاله الثاني يقول: لي جار لا يصلي ولا يصوم، ويشرب الخمر، ويلعب الميسر، وقد نصحته مرارًا، وتسبب ذلك في سوء تفاهم بيني وبينه، وقال: إني أعرف كل نصائحك، فما الحكم في مثل هذا الجار ومعاشرته والإحسان إليه بما أوصانا به رسول الله ﷺ؟ فهل أحسن جواره ولا دخل لي بعمله هذا؟ علمًا بأنه قد يستلف مني بعض النقود بحجة حاجة أولاده، ثم أعرف بعد ذلك أنه استغلها في لعب القمار، وقد يردها لي من مكسبه من ذلك اللعب، فهل يجوز لي أخذها منه وهذا هو مصدره؟","title":"واجب المسلم تجاه جاره المجاهر بالمعاصي","answer":"الجواب: هذا الجار جار سوء، والواجب هجره والاستمرار في الإنكار عليه ونصيحته؛ لعل الله يهديه، والاستعانة في ذلك أيضًا بخيرة أقاربه وجيرانك الآخرين، حتى تجتمعوا على نصيحته، وحتى ترشدوه إلى الخير والصواب؛ لعل الله يهديه بأسبابكم؛ لأن من ترك الصلاة كفر، نعوذ بالله من ذلك، وقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر وقال -عليه الصلاة والسلام-: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في صحيحه. وهذا الرجل لا يصلي ولا يصوم ويشرب الخمر، ويلعب القمار قد جمع شرًا كثيرًا نعوذ بالله، فهو جدير بالهجر لكفره وفسقه وشره الكثير، ولكن إذا كان فقيرًا فلا مانع أن تحسن إلى أهل بيته لا بيده هو، ولكن تعطي أهل بيته الفقراء المحاويج من زوجته وأولاده وبناته تحسن إليهم بما تيسر، أما هو فلا تعطه شيئًا؛ لأنه يستعين به على ما حرم الله، ولكن تعطي أهل بيته ما استطعت بواسطة أهل بيتك أو غيرهم إذا كانوا فقراء محاويج. ولا تؤذه بشيء؛ لأنه جار، وتحسن إليه بالنصيحة والدعوة إلى الله، فحق الجار النصيحة، وبذل المعروف، لكن هذا الرجل يحتاج مع النصيحة إلى الهجر لكفره وإعلانه المعاصي والخبث، نسأل الله العافية، نعم. المقدم: بالنسبة لوفائه الدين من دخل لعب القمار؟ الشيخ: أما قضاء الدين فلا تسأل خذ دينك ولا تسأل، إذا أعطاك الدين لا تسأل ما دمت لا تعلم أنه من القمار، ولا من غيره لا تسأل، خذ دينك، والحمد لله، نعم. المقدم: لو فرضنا أنه توفي وترك مالًا من هذا الدخل أو من هذا الباب؟\nالشيخ: ورثته يرثونه.\nالمقدم: يرثون هذا المال وليس عليهم شيء....؟\nالشيخ: إلا إذا علموا أن هذا مال فلان، أو هذا مال فلان يردونه إليه، أن هذا مال فلان أخذه بالقمار يردونه إليه، أن هذا ثمن خمر يتصدقون به، وإذا كانوا محاويج فهم أهل الصدقة. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14187/واجب-المسلم-تجاه-جاره-المجاهر-بالمعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_697/nour_69702.mp3","categories":["الدعوة والدعاة"]},{"id":15649,"question":"من القصيم بريدة، هذه رسالة بعثت بها إحدى الأخوات من هناك، تقول أختكم أم هبة عبد الهادي، أختنا عرضنا لها سؤالًا في حلقات مضت من هذا البرنامج، وفي هذه الحلقة تسأل سماحتكم فتقول: لي جارة تقوم بالاختلاط بالرجال، ولا ترتدي الحجاب الشرعي الذي أمر الله تعالى به، وهي دائمًا تغتاب الناس، وقد قمت بنصحها ودعوتها إلى الطريق الصحيح، ولكنها لم تستجب حتى الآن، فماذا علي؟جزاكم الله خيرًا. وهل أقاطعها؟","title":"توجيه لمن لها جارة ترتكب بعض المعاصي","answer":"الجواب: عليك أن تنصحيها كثيرًا، وتخوفيها من الله ؛ فإن اختلاطها بالرجال على وجه يثير الفتنة هذا لا يجوز، وهكذا عدم ارتدائها الحجاب، فالواجب عليها الحذر من هذا الأمر، عليها التستر والحجاب والبعد عن الاختلاط الضار، أما اختلاط لا يضر: كالبيع في السوق في محل النساء، أو تشتري حاجتها من السوق، أو تبيع حاجة في السوق مع التحفظ، ومع الحجاب، ومع التستر، هذا لا بأس به، تشتري حاجتها، وتبيع شيئًا في السوق، وإذا كان للنساء سوق خاص باعت فيه واشترت، بعدًا عن الخطر والخلطة بالرجال. أما الغيبة فشرها عظيم، الغيبة منكرة وجريمة، ومن كبائر الذنوب، فالواجب تحذيرها من ذلك، وذكيرها بقول الله سبحانه: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] وهي ذكرك أخاك بما يكره، الغيبة: ذكر الإنسان بما يكره من رجل أو امرأة، أنه بخيل، أنه بذيء اللسان، أنه يأكل الحرام، أن يذكر بشيء يكرهه، هذه هي الغيبة، فالواجب نصيحتها والإكثار عليها في ذلك، وتخويفها من الله ؛ لعلها تهتدي فيكون لك مثل أجرها، فإن أصرت فالمشروع أن تقاطعيها وتهجريها، إذا أصرت ولم تقبل؛ فالمشروع لك هجرها، والبعد عنها؛ لأنها قد تجرك إلى عملها الخبيث، وعملها السيئ، وهجر من أظهر المعصية ولم يقبل النصيحة مشروع، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14185/توجيه-لمن-لها-جارة-ترتكب-بعض-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70512.mp3","categories":["الدعوة والدعاة","نصائح وتوجيهات","قضايا المرأة"]},{"id":15653,"question":"هذه عدة أسئلة من الأخت المستمعة (م. هـ. أ) من مكة المكرمة، سؤالها الأول تقول: هناك بعض الكتب الخاصة بالأذكار والأدعية الواردة عن رسول الله ﷺ منها مثلًا: كتاب الدعاء المستجاب، وقد وجدت فيه أدعية لكل يوم من أيام الأسبوع، فهناك أدعية وأذكار ليوم الجمعة، وأخرى ليوم السبت.. وهكذا، فهل الالتزام بهذه الأذكار بدعة أم هو من السنة؟","title":"ما صحة ما تضمنه كتاب الدعاء المستجاب؟","answer":"الجواب:  هذا كتاب غير معتمد، وصاحبه حاطب ليل، يجمع الغث والسمين، والصحيح والضعيف والموضوع، فلا يعتمد عليه، ولا يجوز أن يخصص أي يوم أو أي ليلة بشيء إلا بدليل عن المعصوم -عليه الصلاة والسلام-. فالكتاب هذا لا يعتمد عليه، ولكن تراجع الكتب الأخرى، فما ثبت عن رسول الله -عليه الصلاة والسلام- من أذكار الصباح أو المساء أو أدعية تقال في الصباح أو المساء، شرع ذلك وما لا فلا.  وأما هذا الكتاب وهو الدعاء المستجاب فلا يعتمد عليه؛ لأن صاحبه ليس بأهل لذلك؛ ولأنه يجمع بين الغث والسمين، والصحيح والضعيف والموضوع، فلا يعتمد على هذا الكتاب، نعم.","link":"https://binbaz.org.sa/fatwas/14196/ما-صحة-ما-تضمنه-كتاب-الدعاء-المستجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_699/nour_69902.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":15731,"question":"رجل له أرحام يتخلفون عن أداء الصلاة جماعةً في المسجد، ويقعون في كثير من المعاصي والمنكرات، فكيف يمكن لهذا الرجل أن يصل أرحامه وهم مقيمون على تلك المحرمات؟ وكيف يمكن كذلك أن يبر والديه إذا كانوا كذلك في هذه الحال؟","title":"كيفية صلة الأرحام إذا كانوا عصاة","answer":"الجواب: السنة له أن يصلهم بالمال إذا كانوا فقراء، ويحسن إليهم، وعليه أن ينصحهم أيضًا، ويوجههم إلى الخير، ويأمرهم بالمعروف، وينهاهم عن المنكر؛ لا يسكت، سواءً كان ذلك مع الوالدين، أو مع الإخوة، أو أخوال، أو أعمام، أو غيرهم، الواجب عليه دعوتهم إلى الله، ونصيحتهم، وأمرهم بالمعروف، ونهيهم عن المنكر باللطف والرفق والأسلوب الحسن؛ لعل الله ينفع به؛ لعل الله يهديهم بأسبابه، وإذا كانوا فقراء ساعدهم، وتألف قلوبهم بالمال إذا كان عنده قدرة يعطيهم من المال، وإذا كان عنده زكاة أعطاهم من الزكاة، إذا كانوا ليسوا بآباء ولا بأولاد إنما هم إخوة أو أعمام أو نحو ذلك. المقصود: إنه يتألفهم بالمال إذا كانوا ليسوا بوالديه، ولا من أولاده، يتألفهم بالمال، وبالكلام الطيب، وإذا كانوا من والديه أو من أولاده بالكلام الطيب، والأسلوب الحسن، يجتهد في دعوتهم إلى الله، والرفق بهم، ونصيحتهم، وبيان سوء ما فعلوا، ويستعين في ذلك أيضًا بأقاربه الآخرين كإخوته أو أعمامه حتى يساعدوك في هذا الأمر؛ لعل الله يهدي هؤلاء بأسبابهم، لأنه إذا كان وحده قد لا يستجيبون له، فإذا كان مع بعض أقاربه لعلهم يستجيبون، وإلا الدعوة تنفع، فإذا صمموا على المنكر، ولم يستجيبوا له فله هجرهم، لكن يعمل الأصلح مهما أمكن، نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/14297/كيفية-صلة-الارحام-اذا-كانوا-عصاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_574/57415.mp3","categories":["نصائح وتوجيهات","الدعوة والدعاة"]},{"id":15734,"question":"سماحة الشيخ، هذه السائلة أم خالد من البحرين، تقول: سماحة الشيخ، أود أن أستفسر منكم عن الكتب؛ فأنا -ولله الحمد- شابة ملتزمة، أود أن أقرأ في العقيدة؛ فما هي الكتب التي تنصحونني أولًا في العقيدة؟ وهذا هو سؤالي الأول.","title":"الكتب التي ينصح بها في العقيدة وغيرها","answer":"الجواب: كتاب ثلاثة الأصول للشيخ محمد بن عبد الوهاب، وأربع القواعد، كتاب التوحيد له -رحمه الله-، وكشف الشبهات؛ هذه مختصرات طيبة، والعقيدة الواسطية لشيخ الإسلام ابن تيمية هذه ننصحك بحفظها طيبة. وفي الحديث الأربعين النووية؛ لأنها مختصرة، اثنين وأربعين حديث، معها ثمانية ابن رجب الجميع خمسون من جوامع الكلم، نوصيك بحفظها، وإذا تيسر أن تحفظي عمدة الحديث لشيخ عبد الغني بن سرور المقدسي، طيب، أو بلوغ المرام للحافظ ابن حجر، طيب. وفي الفقه مثل زاد المستقنع، أو دليل الطالب، أو عمدة الفقه للموفق، كتب مفيدة نافعة في الفقه، يستعان بها على معرفة المسائل حتى يقام عليها الدليل، نعم. المقدم: وفي الفقه يا سماحة الشيخ.\nالشيخ: زاد المستقنع، وهو للحجاوي، أو عمدة الفقه للموفق بن قدامة، أو دليل الطالب، أو غيرها من الكتب الطيبة الصغيرة المفيدة في الفقه.\nالمقدم: والتفسير يا سماحة الشيخ، حفظكم الله. الشيخ: التفسير نوصي بمراجعة تفسير ابن كثير، تفسير طيب مفيد، وابن جرير، والبغوي، تفسير ابن سعدي، تفسير الشنقيطي -رحمة الله عليهم-، الجلالين مفيد، لكن فيه بعض الأغلاط، إذا كان طالب العلم يفهمها لا بأس، نعم.","link":"https://binbaz.org.sa/fatwas/14311/الكتب-التي-ينصح-بها-في-العقيدة-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_574/57418.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":15816,"question":"القضية هامة سماحة الشيخ كما تقدرون -جزاكم الله خيرًا-، هل تنصحون إخوتنا المستمعين بقراءة كتب معينة كيما يكونوا على العقيدة السليمة الصحيحة؟","title":"الحث على قراءة الكتب النافعة لتصحيح العقيدة","answer":"الجواب: نعم، ننصح الجميع بقراءة القرآن، هو أصدق كتاب، وأعظم كتاب، وأنفع كتاب، وهو كلام الله ، ننصح جميع المسلمين من الرجال والنساء في كل مكان أن يعتنوا بالقرآن، وأن يكثروا من تلاوته بالتدبر والتعقل، وإذا تيسر حفظه فهو نعمة عظيمة، يقول الله : كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ[ص:29] ويقول سبحانه: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ[الإسراء:9] يعني: للطريقة التي هي أشد الطرق وأقومها وأهداها، ويقول سبحانه: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ[فصلت:44] ويقول سبحانه: وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَى لِلْمُسْلِمِينَ[النحل:89].  فالقرآن العظيم هو أصل كل خير، وهو الصراط المستقيم، وهو الذي يهدي به الله من اتبع رضوانه سبل السلام، فالواجب على أهل الإسلام أن يعتنوا به، ويتدبروه، ويتعقلوه، وأن يوضحوا للناس معانيه، على العلماء أن يوضحوا للناس معانيه حتى يتفقهوا في ذلك، وحتى يستقيموا على ذلك. كما ننصح أيضًا العلماء، وطلبة العلم بقراءة التفاسير المأمونة الطيبة كتفسير ابن جرير، وتفسير ابن كثير والبغوي وأشباهها حتى يعلموا الناس الخير، وحتى يرشدوهم إلى ما قد يخفى عليهم من كتاب الله، فطالب العلم إذا أشكل عليه شيء من القرآن يراجع كتب التفسير المعتمدة حتى يستفيد، وإذا كان عاميًا يسأل أهل العلم الذين عنده، أو في بلاد أخرى بالمكاتبة، أو من طريق الهاتف -التلفون- يسألهم عما أشكل عليه. فالقرآن هو الهادي إلى الصراط المستقيم، هو أصدق الكتب وأنفعها وأعظمها، وهو كتاب الله ، فالواجب تدبره وتعقله، والعمل بما فيه. ثم سنة الرسول ﷺ فيها الهدى والنور، فيها بيان ما في كتاب الله، فيها الدعوة إلى كل خير، فالرسول ﷺ هو المبين عن الله، والدال على كل خير -عليه الصلاة والسلام-، فعلى المسلمين الاعتصام بكتاب الله، وسنة الرسول ﷺ والدعوة إليهما، والتبشير بهما، وبيان معانيهما، على العلماء أن يبينوا ذلك، وأن يوضحوا للعامة ما يجب عليهم، وما يخفى عليهم، حتى يكون الجميع على بصيرة. ومن ذلك كتب أهل السنة والجماعة تفيد وتعين مثل كتب السلف الصالح؛ البخاري، ومسلم، وسنن أبي داود، والترمذي، والنسائي، وابن ماجه، وسنن الدارمي، ومسند أحمد، كتب مفيدة يعلمها العلماء، ويستفيد العلماء منها، وهكذا كتب أهل السنة بعدهم مثل شيخ الإسلام ابن تيمية، ابن القيم، ابن كثير؛ لأن كتبهم مفيدة عظيمة جيدة. ومثل كتب أئمة الدعوة في نجد في القرن الثاني عشر الشيخ محمد بن عبد الوهاب، وأتباعه من العلماء الذين دعوا إلى الله، ونشروا التوحيد، ونشروا السنة، في وقت الغربة، في القرن الثاني عشر وما بعده، كتبهم عظيمة ومفيدة، ومنها كتاب التوحيد وفتح المجيد، ومنها الدرر السنية التي جمع فيها فتاواهم، كلها مفيدة وعظيمة، ومنها شرح كتاب التوحيد للشيخ سليمان بن عبد الله أيضًا، ومنها مجموعة التوحيد فيها فوائد عظيمة، ومنها ردود للمشايخ مثل رد الشيخ عبد اللطيف بن عبد الرحمن والشيخ عبد الرحمن بن حسن والشيخ سليمان بن سمحان ، وكتب أخرى كلها جيدة ومفيدة، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم، إذًا تنصحون المسلم والحال ما ذكر أن يجعل جزءًا من دخله الشهري كيما يشتري الكتب النافعة التي تفيده في عقيدته وثقافته الدينية؟ الشيخ: نعم، نوصي كل طالب علم، وكل مؤمن بالعناية بالقرآن، والإكثار من تلاوته في الليل والنهار بالتدبر والتعقل، وسؤال أهل العلم عما أشكل عليه، وحفظ ما تيسر من كتاب الله، كما نوصيه أيضًا بشراء الكتب الطيبة التي ذكرنا بعضها حتى يستفيد منها طالب العلم تكون في مكتبته إذا كان طالب علم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14403/الحث-على-قراءة-الكتب-النافعة-لتصحيح-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_744/nour_74402.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":15841,"question":"من أسئلة هذا السائل في سؤاله الثاني يقول: هل حفظ متون الكتب المختصرة في فنون العلم ضروري لطالب العلم، أم يكفي الفهم والفقه مثل: كتاب بلوغ المرام، ألفية ابن مالك في النحو والصرف؟ علمًا بأن الوقت لا يسمح بالجمع بين المصلحتين، وكذلك الحال مع حفظ القرآن والتضلع بتفسيره.","title":"أهمية حفظ القرآن والمتون العلمية لطالب العلم","answer":"الجواب: المهم فهم المعاني والحفظ للمعاني والأحكام، وإذا تيسر له حفظ المتون هذا خير عظيم، كما يشرع له حفظ القرآن، لكن إذا لم يتيسر فالمهم أن يكثر من تلاوته، وأن يفهم المعنى، ويعمل بالحكم الشرعي، وإن لم يحفظ المتون، وإن لم يحفظ القرآن، لكن إذا تيسر حفظ القرآن، وتيسر حفظ البلوغ -بلوغ المرام-، عمدة الحديث، زاد المستقنع في الفقه، ألفية ابن مالك في النحو، هذا خير عظيم؛ لأن هذا يعينه على الفهم، وإذا تيسر له الفهم، ولم يتيسر له الحفظ فلا بأس، والحمد لله. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14432/اهمية-حفظ-القران-والمتون-العلمية-لطالب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_576/57602.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":15842,"question":"من أسئلة هذا السائل -سماحة الشيخ- يقول: كيف الجمع بين الرفق بالناس في الدعوة إلى الله، والحكمة في ذلك، مع تطبيق هذه الآيات: أُفٍّ لَكُمْ وَلِمَا تَعْبُدُونَ مِنْ دُونِ اللَّهِ [الأنبياء:67]، وَبَدَا بَيْنَنَا وَبَيْنَكُمُ الْعَدَاوَةُ وَالْبَغْضَاءُ [الممتحنة:4] وهل البغض في الله يكفي بالقلب، أم لا بد من إظهاره في كل الظروف والأحوال في مجال الدعوة إلى الله؟","title":"كيفية الجمع بين الرفق في الدعوة والبغض لأعداء الله","answer":"الجواب: الرفق في الدعوة لا ينافي هذا، الله -جل وعلا- قال: قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِي إِبْرَاهِيمَ وَالَّذِينَ مَعَهُ إِذْ قَالُوا لِقَوْمِهِمْ إِنَّا بُرَآءُ مِنْكُمْ وَمِمَّا تَعْبُدُونَ مِنْ دُونِ اللَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ الْعَدَاوَةُ وَالْبَغْضَاءُ أَبَدًا حَتَّى تُؤْمِنُوا بِاللَّهِ وَحْدَهُ [الممتحنة:4] وقال عن إبراهيم أنه قال لقومه: أُفٍّ لَكُمْ وَلِمَا تَعْبُدُونَ مِنْ دُونِ اللَّهِ أَفَلا تَعْقِلُونَ [الأنبياء:67]. فالإنسان إذا علم ودعا إلى الله وأرشد، ولم يستجب له، يصرح لهم -يصرح لهم بالعداوة والبغضاء-؛ لأنه أدى ما عليه، وهذا ما ينافي الحكمة، لا يسبهم، ولا يلعنهم، ولكن يدعو إلى الله، ويدعو لهم بالهداية، وإذا صرح لهم بالعداوة والبغضاء؛ لأن هذا ديننا يوجب البغضاء والعداوة من المسلم للكافر، كما أمر الله نبيه وخليله إبراهيم أن يقول ذلك، وليقل: تبًا لآلهتكم، إذا كانت من الأصنام ونحوها، تبًا لها، وإذا كانت من الأموات الكفار تبًا لهم، وإذا كان المعبودون أنبياء أو صالحين لا، لا يقول هذا، يقول: هم برآء منكم، الأنبياء والصالحون برآء من عابديهم من دون الله، هم يتبرؤون من عابديهم. فالواجب على الداعي إلى الله أن يكون عنده حكمة، يرفق في الدعوة، ويرشد إلى الله بالكلام الطيب، والأسلوب الحسن، مع بيان بطلان عبادة غير الله، وأن الكفار أعداء للمسلمين، وبينهم البغضاء والعداوة، هذا واجبهم، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14433/كيفية-الجمع-بين-الرفق-في-الدعوة-والبغض-لاعداء-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_576/57603.mp3","categories":["الدعوة والدعاة"]},{"id":15913,"question":"يسأل سؤالًا آخر سماحة الشيخ فيقول: هل تجوز قراءة كتب تفسير الأحلام، والاعتبار بما فيها؟جزاكم الله خيرًا.","title":"حكم قراءة كتب تفسير الأحلام","answer":"الجواب: لا أعلم حرجًا في قراءة كتب التفسير، ابن سيرين وغيره، كتب الأحلام يستفيد منها طالب العلم، لكن لا يعتمد عليها، بل بالأدلة، لا بد ينظر إلى الأدلة، ويتعلم، وينظر القرائن، وإذا أشكل عليه لا يجزم، يقول: لعل المراد كذا، إذا رأى رؤيا طيبة حمد الله عليها، مثل: رأى أنه يتفقه في الدين، رأى أنه دخل الجنة، هذا يحمد الله على ذلك، رأى أنه بار بوالديه، رأى أنه يحافظ على الصلوات، كل هذا خير، يحمد الله على ذلك. فإن رأى ما يكره، كأن يرى أنه سقط في بئر، أو أنه قتل، أو أنه يشرب الخمر، أو ما أشبه ذلك، هذه من الشيطان، إذا رأى أمره النبي ﷺ أن يتفل عن يساره ثلاثًا، ويقول: أعوذ بالله من الشيطان، ومن شر ما رأيت -ثلاث مرات- ثم ينقلب على جنبه الآخر؛ فإنها لا تضره، ولا يخبر بها أحدًا. فالذي يعبر الرؤيا ينظر ما قاله النبي ﷺ، يعرف الأحاديث الواردة، يستفيد من الكتب، لكن لا يعتمد على قول فلان وفلان، يعتمد على الأحاديث والدلائل الشرعية، والقرائن الشرعية لتفيده، ويتثبت في الأمور، ولا يعبر الرؤيا إلا عن بصيرة، وإذا شك، يقول: لعل كذا، لعل كذا، والنبي ﷺ لما سئل عن الرؤيا الصالحة، قال: يحمد الله عليها إذا رأى ما يحب، أو ما يسره، قال: يحمد الله، ويخبر بها من أحب ولما سئل عن إذا رأى الإنسان ما يكره، قال ﷺ: إذا رأى أحدكم ما يكره فلينفث عن يساره ثلاثًا، ويتعوذ بالله من الشيطان، ومن شر ما رأى -ثلاث مرات-، ثم ينقلب على جنبه الآخر، فإنها لا تضره، ولا يخبر بها أحدًا هذا منهج عظيم بينه النبي ﷺ. أيها المسلم وأيها المسلمة؛ إذا رأى الإنسان ما يحب مثل يرى أنه يصلي على الوجه الشرعي، يرى أنه يتعلم علمًا يتفقه في الدين، يرى أنه دخل الجنة، وما أشبه ذلك من المرائي الطيبة، يرى أنه يجالس الصالحين والأخيار، يرى أنه في حلقات العلم، هذه رؤية طيبة، يحمد الله، يقول: الحمد لله، إذا استيقظ، الحمد لله، يسر بهذا الشيء، يخبر بها أحبابه ومن أحب، لا بأس. أما إذا رأى ما يكره، رأى أنه يضرب، أو يتوعد، أو أنه مع الأشرار، أو أنه دخل النار، أو أنه مريض، أو ما أشبه ذلك من الأشياء المكروهة، إذا استيقظ فزع منها، كرهها، فالرسول ﷺ قد أوصاه أنه: يتفل عن يساره ثلاث مرات، ويقول: أعوذ بالله من الشيطانن، ومن شر ما رأيت -ثلاث مرات-، ثم ينقلب على جنبه الآخر؛ فإنها لا تضره، ولا يخبر بها أحدًا. وبين ﷺ أن هذه من الشيطان، أن هذه الرؤيا من الشيطان؛ ليحزن الإنسان؛ ليؤذيه، يريه هذه الرؤية ليحزنه ليؤذيه، فلا ينبغي أن يقر الشيطان ويسره، لا؛ بل ينبغي له أن يكون عدوًا للشيطان، يتعوذ بالله من الشيطان، يتفل عن يساره ثلاث مرات، ويتعوذ بالله من الشيطان، ومن شر ما رأى، حتى يغيظ الشيطان، ثم ينقلب على جنبه الآخر، كما أمر النبي ﷺ، ولا يخبر به، لا يقول: رأيت رأيت، يتركها، فإنها لا تضره، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14507/حكم-قراءة-كتب-تفسير-الاحلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_708/nour_70804.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16095,"question":"إبراهيم أبو حامد من الرياض يقول: ما حكم الشرع فيمن يقول بأنه غير مقتنع بالحجاب الشرعي؟","title":"توجيه لمن يقول إنه غير مقتنع بالحجاب الشرعي","answer":"الجواب: يعلَّم من قال: إنه غير مقتنع، يعلم أنه الحجاب الشرعي مأمور به، والله يقول -جل وعلا-: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، ويقول سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنّ.. [النور:31] إلى آخره. فالحجاب الشرعي جاء به النص، وهو أيضًا من وسائل العفة والسلامة، وعدم الحجاب من وسائل الفتن، فالذي لم يقتنع؛ يعلم، يوجه إلى الخير، نعم. وحديث أسماء -الذي يروى عن أسماء- أن النبي ﷺ قال لها: إذا بلغت المحيض؛ لم يحل أن يرى منها إلا هذا وهذا، وأشار إلى وجهه وكفيه حديث ضعيف، لا يصح عن النبي ﷺ نعم.","link":"https://binbaz.org.sa/fatwas/14737/توجيه-لمن-يقول-انه-غير-مقتنع-بالحجاب-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57915.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16150,"question":"يقول: أسكن مع أبناء عمي، ونأكل ونشرب، والأسرة كذلك نأكل ونشرب جميعًا، لكنهم لا يصلون، نصحتهم كثيرًا فلم يستجيبوا لي، كيف يكون العمل؟ جزاكم الله خيرًا.","title":"حكم الأكل والشرب مع من لا يصلون","answer":"الجواب: الواجب عليك نصيحتهم، وإنكار المنكر، هذا منكر عظيم؛ لأن الصلاة عمود الإسلام، وهي الركن الأعظم من أركان الإسلام الخمسة بعد الشهادتين، فيقول فيها النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة ويقول -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر، الصلاة أمرها عظيم.  فالواجب نصيحتهم، والإنكار عليهم، فإن استجابوا فالحمد لله، وإلا فلا تجالسهم، لكن لا مانع من تكرار النصيحة إذا طمعت في هدايتهم، تكرر النصيحة مع عدم اتخاذهم أصحابًا، وجلساء، لكن تكرر النصيحة، والدعوة إلى الله؛ لعل الله يهديهم بأسبابك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14805/حكم-الاكل-والشرب-مع-من-لا-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_750/nour_75002.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":16204,"question":"يقول: هل يجب على من يحفظ القرآن الكريم، هل يجب عليه أن يحفظ التفسير كاملًا أيضًا؟ أم أن الإنسان مخير في هذا؟ جزاكم الله خيرًا.","title":"حكم دراسة التفسير لمن يحفظ القرآن","answer":"الجواب: لا، لا يلزمه، حتى حفظ القرآن مستحب، لكن يحفظ من القرآن ما يسر الله له، حتى يصلي به، والواجب حفظ الفاتحة الحمد لله رب العالمين وحفظ ما سواها مستحب للمؤمن، يحفظ ما تيسر حتى يقرأ به في الصلاة، وفي غير الصلاة، وإذا يسر الله له حفظ الكتاب كله، حفظ القرآن العظيم؛ فهذا خير عظيم، وفائدة عظيمة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14908/حكم-دراسة-التفسير-لمن-يحفظ-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_806/nour_80616.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16231,"question":"آخر سؤال لها تقول فيه: والدي للأسف الشديد لا يصلي، ويقوم أحيانًا بإعطائي بعض النقود في المناسبات، كالأعياد مثلًا، فهل يجوز لي أخذها؟ وإذا أخذتها، وتصدقت بها؛ فهل تصح الصدقة، أم لا؟ جزاكم الله خيرًا.","title":"حكم قبول العطية من أب لا يصلي","answer":"الجواب: لا بأس بأخذ الدراهم من والدك، ولا بأس بالصدقة بها، أو الانتفاع بها، لا حرج في ذلك، مع النصيحة لوالدك بالكلام الطيب.. تخويفه من الله -جل وعلا- .. حثه على الصلاة.. كذلك تشجيع أعمامك -إن كان لك أعمام- أو إخوة كبار ينصحونه، أو جيران جيدين ينصحونه، لا تغفلي، ولا يغفل إخوانك، ولا أعمامك، عليكم أن تتقوا الله فيه، وأن تنصحوه، وأن تستمروا في ذلك، أما هديته فاقبلوها، لا حرج في ذلك. نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14911/حكم-قبول-العطية-من-اب-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75118.mp3","categories":["الهبة والعطية","الدعوة والدعاة"]},{"id":16276,"question":"في سؤال له آخر يقول: تعرفون -بارك الله فيكم- أن الكتب الدينية قد كثرت في هذه الأيام، وتجدنا حائرين عند شراء أي كتاب، خاصةً أن بعض المؤلفين قد أثنى على كتبه ثناءً بالغًا لغرض الربح -والله أعلم- فأرجو التفضل من سماحتكم بأن تفيدونا عن بعض الكتب الموثوق بها، أو الطريقة التي نشتري بها كتبنا التي نرجع إليها في بعض المسائل، أو الاطلاع، جزاكم الله خيرًا.","title":"ما ينصح بقراءته من الكتب","answer":"الجواب: تسأل أهل العلم إذا أردت أن تشتري كتابًا، تسأل أهل العلم في بلدك، تسألهم، أهل العلم المعروفين بالاستقامة، وحسن السيرة، والعلم، والفضل، تسألهم عن الكتب التي تريد لعلهم يفيدونك. وأنا أذكر لك بعض الكتب، لكن أهمها، وأعظمها العناية بالقرآن، هو أفضل كتاب، وأصدق كتاب، وأشرف كتاب كتاب الله، نوصيك بالقرآن، نوصيك أنت وكل مسلم، نوصيك بالقرآن، ونوصي كل مسلم، وكل مسلمة بالعناية بالقرآن، والإكثار من تلاوته، وحفظ ما تيسر منه، وتدبر لمعانيه عند القراءة، فهو كتاب الله العظيم، فيه الهدى والنور، فيه العلم العظيم، يقول الله : إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44] ويقول سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29] ويقول سبحانه: وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ [الأنعام:155]. فنوصي الجميع جميع المسلمين رجالاً ونساء، نوصيهم جميعًا بالعناية بالقرآن، بالإكثار من تلاوته، وتعلمه، وسؤال أهل العلم عن معناه، والإكثار من مراجعة كتب التفسير الموثوقة، كتفسير ابن كثير، والبغوي، وابن جرير، والشوكاني، هذه الكتب العظيمة، وأشباهها يجب على المؤمن، وطالب العلم يعتني بها، ويكثر من تلاوة القرآن في الأوقات المناسبة، ويتدبر، ويتعقل، ويراجع كتب التفسير عما أشكل عليه، ويسأل أهل العلم. ثم كتب الحديث، نوصيك بكتب الحديث، مثل الصحيحين للبخاري ومسلم، مثل رياض الصالحين، مثل المنتقى لابن تيمية منتقى الأخبار، مثل بلوغ المرام كتب جيدة، عمدة الحديث للشيخ عبدالغني المقدسي كتب جيدة، نوصيك بها، والاستفادة منها، مثل زاد المعاد لابن القيم في هدي خير العباد كتاب عظيم، وزاد المعاد في هدي خير العباد للعلامة ابن القيم -رحمه الله- كتاب مفيد جيد، فيه أحكام، وأدلة من الحديث الشريف، والآيات فيه خير كثير، نسأل الله للجميع التوفيق والهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14991/ما-ينصح-بقراءته-من-الكتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_809/nour_80913.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16293,"question":"أخونا يقول: إنني أريد أن أكون أحد الدعاة إلى الله، وأدعو بالحق، وبالعلم، وبالمعرفة، بماذا تنصحونني في ذلك؟ جزاكم الله كل خير؟","title":"نصيحة لمن أراد الدعوة إلى الله","answer":"الجواب: ننصحك بالجد في طلب العلم، والتفقه في الدين، والدعوة إلى الله  لأنك مسؤول مأمور بالدعوة إلى الله، إذا كان عندك علم، الله يقول سبحانه: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108]. فعليك أن تدعو إلى الله، وترشد الناس إلى الخير في بيتك، وفي جماعتك، وفي مسجدك، وفي قبيلتك حسب طاقتك، لكن إذا كان عندك علم من كلام الله، وكلام رسوله ﷺ وعرضت ذلك على أهل العلم، وأذنوا لك ووجهوك، فأنت اجتهد اجتهد، واعمل، واحرص على الخير، وأبشر بالخير، والعاقبة الحميدة. وإن كان ليس عندك علم، فلا تقل على الله ما لا تعلم، ولا تتكلم بغير علم، واسأل أهل العلم حتى يوجهوك، ويبصروك، وإذا أحببت أن تكتب لنا في ذلك أرشدناك، إن شاء الله.","link":"https://binbaz.org.sa/fatwas/14981/نصيحة-لمن-اراد-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_753/nour_753003.mp3","categories":["الدعوة والدعاة"]},{"id":16295,"question":"أخونا يقول: إنني أريد أن أكون أحد الدعاة إلى الله، وأدعو بالحق، وبالعلم، وبالمعرفة، بماذا تنصحونني في ذلك؟ جزاكم الله كل خير؟","title":"نصيحة لمن أراد الدعوة إلى الله","answer":"الجواب: ننصحك بالجد في طلب العلم، والتفقه في الدين، والدعوة إلى الله  لأنك مسؤول مأمور بالدعوة إلى الله، إذا كان عندك علم، الله يقول سبحانه: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108]. فعليك أن تدعو إلى الله، وترشد الناس إلى الخير في بيتك، وفي جماعتك، وفي مسجدك، وفي قبيلتك حسب طاقتك، لكن إذا كان عندك علم من كلام الله، وكلام رسوله ﷺ وعرضت ذلك على أهل العلم، وأذنوا لك ووجهوك، فأنت اجتهد اجتهد، واعمل، واحرص على الخير، وأبشر بالخير، والعاقبة الحميدة. وإن كان ليس عندك علم، فلا تقل على الله ما لا تعلم، ولا تتكلم بغير علم، واسأل أهل العلم حتى يوجهوك، ويبصروك، وإذا أحببت أن تكتب لنا في ذلك أرشدناك، إن شاء الله.","link":"https://binbaz.org.sa/fatwas/14981/نصيحة-لمن-اراد-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_753/nour_753003.mp3","categories":["الدعوة والدعاة"]},{"id":16357,"question":"أولى رسائل هذه الحلقة، رسالة وصلت إلى البرنامج من دمشق باعثها أحد الإخوة المستمعين من هناك رمز إلى اسمه بالحروف (أ. ن) أخونا يسأل سماحتكم أولًا عن كتاب: حلية الأولياء ما هو رأيكم فيه؟ وما هو توجيهكم للمهتمين بمثل هذا الكتاب؟ جزاكم الله خيرًا.","title":"حكم قراءة طلبة العلم المبتدئين لكتاب حلية الأولياء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فكتاب حلية الأولياء كتاب معروف لصاحبه الحافظ أبي نعيم، وهو كتاب يجمع الضعيف والصحيح والموضوع، فينبغي ألا يقرأه إلا أهل العلم الذين يعرفون درجات الحديث، ويميزون بين الغث والسمين. أما هذا الكتاب فهو لا يصلح للعامة، وطلبة العلم الذين لم يصلوا إلى حد التمييز بين الضعيف والصحيح، وننصح طلبة العلم، وإخواننا جميعًا أن يقرؤوا الكتب المفيدة الصحيحة، مثل صحيح البخاري، صحيح مسلم، رياض الصالحين كتاب مفيد، الترغيب والترهيب مفيد، وفيه أحاديث ضعيفة، لكن نبه عليها صاحب الترغيب، نبه عليها، فإذا قال: يروى، أو روي هي علامة الضعيف، والصحيح يجزم بها، ولا يقول فيها روي. المقصود: أني أنصح إخواني أن يتحروا الكتب المعروفة التي اعتنى أصحابها بالأحاديث الصحيحة، كالصحيحين، ورياض الصالحين، الترغيب والترهيب، منتقى الأخبار لابن تيمية المجد بلوغ المرام وحفظ البلوغ للحافظ ابن حجر، كلها أحاديث مفيدة وإن كان فيها أحاديث ضعيفة، لكن نبه عليها الحافظ نبه على الضعيف، والمنتقى الأحاديث الضعيفة قليلة، وطالب العلم يستطيع يعرف الضعيف من شرح المنتقى للشوكاني مفيد، كذلك عمدة الحديث للشيخ عبدالغني بن عبدالواحد المقدسي كتاب عظيم ومفيد، وأحاديثه صحيحة. أما مثل حلية الأولياء فهذا لا يصلح إلا لأهل العلم الذين يميزون بين الصحيح والسقيم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15052/حكم-قراءة-طلبة-العلم-المبتدىين-لكتاب-حلية-الاولياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_715/nour_71501.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16378,"question":"يقول: أريد حفظ القرآن الكريم، لكنني لم أستطع؛ نظرًا لمشاغل الحياة، فما هو توجيهكم؟","title":"توجيه لمن أراد حفظ كتاب الله","answer":"الجواب: الحفظ للقرآن ليس بواجب، لكنه مستحب، فإذا تيسر لك الحفظ؛ فالحمد لله، وإلا فلا حرج عليك، ولا شك أن الحفظ من نعم الله العظيمة، فإذا تيسر للمؤمن حفظ القرآن، أو المؤمنة، فهذا من نعم الله العظيمة. والمقصود من ذلك: التدبر، أن تكثر من قراءته، فإذا تيسر لك الحفظ؛ فهذه نعمة كبيرة، وإلا فعليك بالقراءة من المصحف، مع التدبر، والتعقل؛ لأن المقصود من إنزاله: العمل به، وقراءته بالتدبر، والتعقل من أسباب فهمه، ومن أسباب العمل به. فالمشروع للجميع -من الرجال والنساء- العناية بالقرآن، والإكثار من تلاوته، وتدبر معانيه، والتفقه فيه، والعمل بما دل عليه من فعل الأوامر، وترك النواهي، والاعتبار بما قص الله علينا من أخبار الماضين؛ حتى نحذر أعمالهم الخبيثة، وحتى نعمل ما يكون سببًا لمرضاة ربنا، ونجاتنا في الدنيا والآخرة، يقول سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29] ويقول سبحانه في كتابه العظيم: أَفَلا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا [محمد:24]، ويقول -جل وعلا-: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9].  فالمشروع لكل مؤمن ومؤمنة العناية بالقرآن، والإكثار من تلاوته بالتدبر، والتعقل، والتفهم، ومراجعة كتب التفسير للفائدة، وسؤال أهل العلم عما يشكل، والعمل. المقصود: العمل، أن تعمل بطاعة ربك، وأن تؤدي فرائضه، وأن تحذر محارمه عن بصيرة، وعن علم، وعن رغبة فيما عند الله، وحذر من عقابه  ولك بكل حرف حسنة، والحسنة بعشر أمثالها، كما صح به الحديث عن رسول الله ﷺ يقول -عليه الصلاة والسلام-: من قرأ حرفًا من القرآن؛ فله به حسنة، والحسنة بعشر أمثالها هذه من نعم الله العظيمة أن يحصل لك الخير العظيم بقراءة كتاب الله، من العلم والعمل، وهذه الحسنات العظيمة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15079/توجيه-لمن-اراد-حفظ-كتاب-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75409.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16382,"question":"رجل أمر زوجته بارتداء الحجاب الشرعي فأبت، ماذا يفعل؟","title":"توجيه للزوج الذي ترفض زوجته الحجاب","answer":"الجواب: يستمر في نصيحتها، ويتعاون مع أهلها في ذلك؛ لعل الله يهديها بأسبابه؛ لأن هذه معصية، فعليه أن يستمر في النصيحة، ولا مانع من تأديبه لها على ذلك تأديبًا لا يضرها، بضرب غير مبرح من باب إنكار المنكر، إذا كانت لا تبالي بذلك عند الأجناب، عند الرجل الأجنبي، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15089/توجيه-للزوج-الذي-ترفض-زوجته-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75412.mp3","categories":["الدعوة والدعاة","الآداب والأخلاق المحمودة","اللباس والزينة"]},{"id":16462,"question":"يسأل سماحتكم رأيكم في كتاب الروح لابن القيم ؟","title":"تقييم كتاب الروح لابن القيم","answer":"الجواب: كتاب الروح لابن القيم كتاب عظيم، كتاب عظيم الفائدة، ولكن وقع فيه بعض التساهل في حكايات المرائي المنامية، وبعض التساهل في بعض الأحكام، ولعله كان من أول كتبه رحمه الله، ومن ذلك ما ذكر من إهداء القرب إهداء القرآن للموتى، قراءة القرآن هذا فيه نظر. فالمقصود: أنه كتاب عظيم ومفيد، ولكن فيه بعض الأشياء التي تلاحظ عليه، فالواجب أن توزن بالأدلة الشرعية، الواجب أن توزن بالأدلة الشرعية، والمرائي المنامية لا يعتمد عليها في الأحكام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15214/تقييم-كتاب-الروح-لابن-القيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_813/nour_81312.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16503,"question":"لعل سماحتكم يتفضل بكلمة للمجتمع ككل؟","title":"نصيحة مهمة لعامة الأمة","answer":"الجواب: هذه وصية للجميع، للشباب وغير الشباب، الوصية لجميع الدعاة إلى الله من الرجال والنساء، الوصية لجميع الآمرين بالمعروف، والناهين عن المنكر من الرجال والنساء في كل مكان من أرض الله، الواجب على الجميع تحري الحق، وتحري الأسلوب الحسن، والصبر في ذلك والرفق، وأن يقول عن علم، وعن بصيرة. يجب الحذر من القول على الله بغير علم، لا من الرجال، ولا من النساء، ويجب أن يسلك المسلك الذي يرجى من ورائه حصول المنفعة، حصول الخير، قبول الحق، وذلك بسلوك الطريق الذي رسمه النبي ﷺ ودل عليه كتاب الله  في الدعوة إلى الله، والأمر بالمعروف والنهي عن المنكر. هذا هو الذي يرجى من ورائه الخير العظيم للمجتمع كله، رجاله ونسائه، كما قال مولانا سبحانه في كتابه العظيم يخاطب نبيه ﷺ والمراد الأمة كلها: ادْعُ إِلَى سَبِيلِ رَبِّكَ [النحل:125] يعني: إلى دين ربك، بِالْحِكْمَةِ [النحل:125] وهي: العلم، قال الله، قال رسوله وَالْمَوْعِظَةِ الْحَسَنَةِ [النحل:125] الترغيب والترهيب بالكلام الطيب، قال الله كذا، قال الرسول ﷺ كذا، وعد الله من فعل كذا الجنة، وعده كذا، توعد الله من فعل كذا النار، يعني يذكر الآيات والنصوص. وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] يعني: بالأسلوب الحسن بالرفق. يقول النبي ﷺ: إن الرفق لا يكون في شيء إلا زانه، ولا ينزع من شيء إلا شانه ويقول -عليه الصلاة والسلام-: من يحرم الرفق يحرم الخير كله ويقول -جل وعلا-: وَلا تُجَادِلُوا أَهْلَ الْكِتَابِ [العنكبوت:46] يعني: اليهود والنصارى، إِلَّا بِالَّتِي هِيَ أَحْسَنُ إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ [العنكبوت:46]. والظالم يعامل بما يستحق إذا ظلم، وتعدى، وضرب، أو سب، يعامل بما يستحق، ومن عفا؛ فأجره على الله، لكن ما دام لم يتعد، ولم يظلم؛ تدعوه بالتي هي أحسن، بالكلام الطيب، قال الله كذا، قال الرسول ﷺ كذا، يا أخي! كذا المسلم يا أخي! كذا، يا أخي! افعل كذا، أوصيك بكذا .. قال الله كذا، قال الرسول ﷺ كذا، حتى يلين قلبه، ويرغبه في الخير. ولا يخاطبه بالعنف والشدة، أو يقول: يا جاهل! أو يا حمار! أو يا مغرور! أو يا متكبر! أو يا كافر! لا، يأتي بالعبارات الطيبة، يا أخي! إن كان مسلمًا، أو يا فلان! إن كان كافرًا، يا عبدالله! أو يا أبا فلان، مثلما قال النبي ﷺ لعبدالله بن أبي يا أبا الحباب -وهو منافق- يرغبه في الخير، يخاطبه بالاسم المناسب، باسمه أو بكنيته، يدعوه إلى الله. ولا يخاطبه أبدًا بالألفاظ المنكرة؛ لأنها تنفر عن الحق، وربما قال له مثلما قال، إذا قال له: يا مغرور! قال: أنت المغرور، وإذا قال له: يا جاهل! قال: أنت الجاهل، وإذا قال: يا فاجر! قال: أنت الفاجر، وإذا قال: يا كافر! قال: أنت الكافر، هذا يسبب المشاكل، ولكن بالكلام الطيب، والأسلوب الحسن، تقبل الدعوة، ويقبل الحق، وتؤدى الفريضة، يؤدى الواجب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15238/نصيحة-مهمة-لعامة-الامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_814/nour_81401.mp3","categories":["الدعوة والدعاة"]},{"id":16506,"question":"لعل سماحتكم يتفضل بكلمة للمجتمع ككل؟","title":"نصيحة مهمة لعامة الأمة","answer":"الجواب: هذه وصية للجميع، للشباب وغير الشباب، الوصية لجميع الدعاة إلى الله من الرجال والنساء، الوصية لجميع الآمرين بالمعروف، والناهين عن المنكر من الرجال والنساء في كل مكان من أرض الله، الواجب على الجميع تحري الحق، وتحري الأسلوب الحسن، والصبر في ذلك والرفق، وأن يقول عن علم، وعن بصيرة. يجب الحذر من القول على الله بغير علم، لا من الرجال، ولا من النساء، ويجب أن يسلك المسلك الذي يرجى من ورائه حصول المنفعة، حصول الخير، قبول الحق، وذلك بسلوك الطريق الذي رسمه النبي ﷺ ودل عليه كتاب الله  في الدعوة إلى الله، والأمر بالمعروف والنهي عن المنكر. هذا هو الذي يرجى من ورائه الخير العظيم للمجتمع كله، رجاله ونسائه، كما قال مولانا سبحانه في كتابه العظيم يخاطب نبيه ﷺ والمراد الأمة كلها: ادْعُ إِلَى سَبِيلِ رَبِّكَ [النحل:125] يعني: إلى دين ربك، بِالْحِكْمَةِ [النحل:125] وهي: العلم، قال الله، قال رسوله وَالْمَوْعِظَةِ الْحَسَنَةِ [النحل:125] الترغيب والترهيب بالكلام الطيب، قال الله كذا، قال الرسول ﷺ كذا، وعد الله من فعل كذا الجنة، وعده كذا، توعد الله من فعل كذا النار، يعني يذكر الآيات والنصوص. وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] يعني: بالأسلوب الحسن بالرفق. يقول النبي ﷺ: إن الرفق لا يكون في شيء إلا زانه، ولا ينزع من شيء إلا شانه ويقول -عليه الصلاة والسلام-: من يحرم الرفق يحرم الخير كله ويقول -جل وعلا-: وَلا تُجَادِلُوا أَهْلَ الْكِتَابِ [العنكبوت:46] يعني: اليهود والنصارى، إِلَّا بِالَّتِي هِيَ أَحْسَنُ إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ [العنكبوت:46]. والظالم يعامل بما يستحق إذا ظلم، وتعدى، وضرب، أو سب، يعامل بما يستحق، ومن عفا؛ فأجره على الله، لكن ما دام لم يتعد، ولم يظلم؛ تدعوه بالتي هي أحسن، بالكلام الطيب، قال الله كذا، قال الرسول ﷺ كذا، يا أخي! كذا المسلم يا أخي! كذا، يا أخي! افعل كذا، أوصيك بكذا .. قال الله كذا، قال الرسول ﷺ كذا، حتى يلين قلبه، ويرغبه في الخير. ولا يخاطبه بالعنف والشدة، أو يقول: يا جاهل! أو يا حمار! أو يا مغرور! أو يا متكبر! أو يا كافر! لا، يأتي بالعبارات الطيبة، يا أخي! إن كان مسلمًا، أو يا فلان! إن كان كافرًا، يا عبدالله! أو يا أبا فلان، مثلما قال النبي ﷺ لعبدالله بن أبي يا أبا الحباب -وهو منافق- يرغبه في الخير، يخاطبه بالاسم المناسب، باسمه أو بكنيته، يدعوه إلى الله. ولا يخاطبه أبدًا بالألفاظ المنكرة؛ لأنها تنفر عن الحق، وربما قال له مثلما قال، إذا قال له: يا مغرور! قال: أنت المغرور، وإذا قال له: يا جاهل! قال: أنت الجاهل، وإذا قال: يا فاجر! قال: أنت الفاجر، وإذا قال: يا كافر! قال: أنت الكافر، هذا يسبب المشاكل، ولكن بالكلام الطيب، والأسلوب الحسن، تقبل الدعوة، ويقبل الحق، وتؤدى الفريضة، يؤدى الواجب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15238/نصيحة-مهمة-لعامة-الامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_814/nour_81401.mp3","categories":["الدعوة والدعاة"]},{"id":16508,"question":"هل من كلمة أيضًا للشباب الذين بدؤوا هذا الالتزام، وبدؤوا يمارسون الدعوة إلى الله، ويلتزمون بأحكام السنن، هل من كلمة يتفضل بها سماحة الشيخ؟","title":"وصية للشباب والدعاة بالحكمة في الدعوة إلى الله","answer":"الجواب: نعم نوصيهم بتقوى الله، وأن يشكروا الله على ما من به عليهم من الالتزام بطاعة الله ورسوله، ونوصيهم بعدم العجلة في الأمور، وعدم التشديد الذي لا يوافق الشرع، بل نوصيهم بالتثبت، والتوسط في الأمور، وعدم الغلو، وعدم الجفاء، لا هذا ولا هذا، الواجب التوسط في الأمور، فلا غلو ولا جفاء، لا إفراط ولا تفريط، بل إذا التزم بالحق بإعفاء لحيته، والصلاة في الجماعة بالطمأنينة، بعدم الإسبال، بعدم حلق اللحية يستقيم على ذلك، ويسأل ربه العون والتوفيق.  ولا يعنف على الآخرين بشدة، بل يدعوهم إلى الله بالحكمة، والكلام الطيب، يا أخي! الرسول ﷺ أمر بإعفاء اللحى، يا أخي! نوصيك بإعفائها، يا أخي! لا تسبل ثيابك، الرسول ﷺ نهى عن الإسبال، نهى عن الخيلاء بالكلام الطيب، والأسلوب الحسن الذي يرجى من ورائه قبول الحق، والتأثر، فإن الشدة قد يحصل بها التنفير، والمخاصمة، والنزاع، ولكن بالكلام الطيب، والأسلوب الحسن يحصل الخير الكثير، يقول الله : ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] هكذا أرشدنا مولانا . ويقول -جل وعلا- في كتابه العظيم، في وصف النبي ﷺ: فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لانْفَضُّوا مِنْ حَوْلِكَ [آل عمران:159] ويقول الله لموسى وهارون لما بعثهما إلى فرعون، قال سبحانه: فَقُولا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى [طه:44] ويقول سبحانه في جدال أهل الكتاب اليهود والنصارى: وَلا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ [العنكبوت:46] فإذا كان اليهود والنصارى يجادلون بالتي هي أحسن، فكيف بالمسلم؟! من باب أولى. فوصيتي للشباب وغير الشباب لجميع من يأمر بالمعروف وينهى عن المنكر، لجميع الدعاة إلى الله، وصيتي للجميع الرفق في الأمور كلها، والجدال بالتي هي أحسن، وتحري الأسلوب الجيد اللين؛ لعل الله ينفع بذلك. كما نوصي بالحذر من العنف، والشدة والكلام البذي؛ فإن هذا ينفر من الحق، وربما سبب خصومة، ونزاعًا، ومقاتلة ومضاربة، والمؤمن قصده الخير، والداعي إلى الله قصده الخير، فينبغي سلوك أسباب الخير، الواجب على الداعي إلى الله، والآمر والناهي أن يسلك المسالك التي تعينه على حصول الخير، وتعين إخوانه على قبول الحق، نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15265/وصية-للشباب-والدعاة-بالحكمة-في-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_814/nour_81411.mp3","categories":["الدعوة والدعاة","نصائح وتوجيهات"]},{"id":16542,"question":"نعود مع بداية هذه الحلقة إلى رسالة وصلت إلينا من الأردن، صاحبها نسي أن يذكر اسمه، عرضنا جزءًا من أسئلتها في حلقة مضت، وفي هذه الحلقة يسأل عن قضية بين امرأة وأخيها، يقول: إن هناك امرأة تشكو من أخ لها قاسٍ، وتصفه بأوصاف سيئة، وتقول: إنه يهددها بالتسبب في طلاقها من زوجها، وترجو التوجيه، جزاكم الله خيرًا، وكيف تقابل مثل هذا الأخ؟","title":"وصية لامرأة تشكو من سوء معاملة أخيها لها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالذي أنصح به هذه المرأة أن تستعمل الأسلوب الحسن مع أخيها، والكلام الطيب، وأن تدعو له بظهر الغيب، أن الله يوفقه، ويهديه، ويعيذه من الشيطان، ومن ظلمها، وظلم زوجها، وتسأل عن الأسباب التي تسبب المشاكل حتى تحل، وإذا تيسر أن يتوسط بينهما أعمام، أو أخوال، أو جيران طيبون، يصلحون بينهما؛ فهذا طيب. على كل حال أوصيها بالرفق، والكلام الطيب، والأسلوب الحسن، والتحمل، والصبر حتى يحل الله المشكلة بينهما، إلا أن يكون الزوج غير طيب في دينه، وأن أخاها يريد منها مفارقته لفساد دينه، كونه ما يصلي، أو لكونه يسب الدين، أو لكونه صاحب معاصي ظاهرة، فيكون أخوها في هذا مصيبًا ناصحًا لها، فإذا طلبت من هذا الزوج أن يستقيم أو يطلقها إن كان مسلمًا، أما إن كان لا يصلي، أو كان عنده شيء من نواقض الإسلام من سب الدين، أو التعلق بعبادة القبور، فهذا لا يجوز بقاؤها معه، وهي مسلمة، وأخوها ناصح لها، فيجب عليها أن تفارقه، وأن تطلب من المحكمة التفريق بينهما، وأن لا يقربها إذا كان كافرًا، لا يقربها أبدًا، لا بجماع، ولا غيره حتى يتوب الله عليه. فالحاصل: أنه إذا كان هناك أمور دينية ينقمها الأخ على الزوج، فينبغي لها أن تتصل بولاة الأمور في المحكمة، وتعرض مشكلتها مع الزوج على المحكمة، والمحكمة تنظر في الأمر، إن كان مسلمًا؛ نصحته المحكمة بالتوبة إلى الله من معاصيه، وإن كان كافرًا؛ نصحته المحكمة بالتوبة، والرجوع إلى الله، ومن تاب؛ تاب الله عليه، وبالرفق والحكمة، والرجوع إلى ما شرع الله تنتهي المشاكل، وتحل المشاكل -بإذن الله- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15266/وصية-لامراة-تشكو-من-سوء-معاملة-اخيها-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_815/nour_81501.mp3","categories":["الدعوة والدعاة","نصائح وتوجيهات","قضايا المرأة"]},{"id":16662,"question":"سماحة الشيخ هذا سائل يقول: كيف نجمع بين الحديث الذي فيما معناه: بأن من ستر مسلمًا ستره الله يوم القيامة، وبين فريضة الأمر بالمعروف والنهي عن المنكر؟","title":"الجمع بين الأمر بالمعروف وستر المذنبين","answer":"الجواب: تأمره، وتستر عليه، إذا رأيته يتعاطى ما حرم الله من خمر، أو نحوه؛ تستر عليه، ما تقول: رأيت فلانًا يشرب الخمر، تأمره بالمعروف، وتنهاه عن المنكر، تنصحه، وتوصيه بالخير، ولا تفضحه عند الناس، إلا إذا هو فضح نفسه، هو الذي يشرب الخمر عند الناس، فضح نفسه، من أعلن المعاصي؛ ما له غيبة، هو الذي فضح نفسه، لكن إذا كان يتستر في بيته، ورأيته صادفته؛ لا تكشف ستره، لا تعلن أمره، يقول النبي ﷺ: من ستر مسلمًا ستره الله في الدنيا والآخرة لكن تنصحه، تأمره بالمعروف، وتنهاه عن المنكر، ولا تفضحه، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15395/الجمع-بين-الامر-بالمعروف-وستر-المذنبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58319.mp3","categories":["شروح الحديث","الدعوة والدعاة"]},{"id":16672,"question":"الرسالة التالية وصلت إلى البرنامج من اليمن وباعثتها إحدى الأخوات المستمعات تقول: المرسلة أم أيمن عبدالله علي يحيى سعيد من اليمن تعز، رسالتها طويلة بعض الشيء سماحة الشيخ تقول: أنا أستمع إلى برنامج (نور على الدرب) دائمًا، ولي سؤال إذا سمحتم بعرضه، والإجابة عليه: أنا امرأة متزوجة، وعندي أربعة أولاد، وقد هداني الله إلى الصلاة والصيام، وقد علمت أولادي الصلاة، والصيام منذ كانت أعمارهم سبع سنوات، وقد كان زوجي مسافرًا لفترة طويلة، وعندما عاد، واستقر بدأت الحياة تدب فينا من جديد، لكن زوجي منذ عرفته -منذ ستة عشرة سنة- وهو يتهاون بصلاة الفجر، هذا أمامي، وأما عندما كان مسافرًا فالله يعلم، وهو لا يصلي الفجر دائمًا إذا سمعه، أو لم يسمعه، وقد نصحته بأن لا يتهاون بصلاة الفجر، فكان يغضب مني، ويتشاجر معي ويقول: إنه سوف يقضي عندما يستيقظ بعد شروق الشمس، وأنا أتألم لذلك؛ لأنه قدوتنا في البيت، وأيضًا يتهاون أحيانًا بصلاة الجمعة، وأنا أنصحه بعدم التهاون بصلاة الجمعة، ولكنه يغضب مني، ويحاول التشاجر معي، ولكن أبتعد عن التشاجر معه أمام أولادي، وأكتم الغضب في قلبي، وقد أحسست بكراهية وبغضاء تجاهه؛ بسبب تهاونه بالصلاة، فهل علي إثم في كراهيته، وعدم الرغبة في النظر إليه،؟ومعذرة لطول السؤال، جزاكم الله خيرًا.","title":"واجب المرأة تجاه زوجها المتساهل بالصلاة","answer":"الجواب: لقد أحسنت -جزاك الله خيرًا- في تربية الأولاد، وتعليمهم، والاجتهاد في أسباب صلاحهم، وهذا هو الواجب عليك، ولك عند الله الأجر العظيم. كما أنك أحسنت في نصيحة زوجك، والإكثار عليه في المحافظة على صلاة الفجر، وصلاة الجمعة، وهذا هو الواجب عليك، وعلى أمثالك، النصيحة للزوج والنصيحة للأولاد، والأمر بالمعروف، والنهي عن المنكر، يقول الله  في كتابه المبين القرآن: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُوْلَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71] هؤلاء المرحومون في الدنيا والآخرة، وأنت منهم -إن شاء الله- لحرصك على الخير. والله -جل وعلا- أخبر عن المؤمنين والمؤمنات جميعًا الذكور والإناث، كلهم مأمورون، وكلهم يجب عليهم أن يأمروا بالمعروف، وينهوا عن المنكر، ويقيموا الصلاة، ويؤتوا الزكاة ويطيعوا الله ورسوله. ويقول سبحانه: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3] فالتواصي بالحق واجب مع الأولاد، ومع الزوج، ومع الأقارب، ومع الجيران، ومع المسلمين جميعًا، يجب على الرجال والنساء جميعًا أن يتواصوا بالحق، والصبر عليه، وبذلك تصلح المجتمعات، وتصلح الأسر، ويستقيم أمر الله في عباد الله، ويظهر الحق. ويقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ[المائدة:2] فالواجب عليك الاستمرار في نصيحته، وأنت مأجورة في بغضك له، وكراهتك له؛ لأنه أتى منكرًا عظيمًا، بل كفرًا؛ لأن من تعمد ترك الصلاة عمدًا؛ يكفر بذلك، وهكذا من تعمد ترك الجمعة. فالواجب على زوجك أن يتقي الله، وأن يحافظ على صلاة الجمعة، وعلى صلاة الفجر كبقية الصلوات، وأنا أخشى عليه -إن كان كاذبًا- أن يكون كافرًا إذا كان لا يصلي الفجر، أو لا يصلي الجمعة، يقول النبي ﷺ: لينتهين أقوام عن تركهم الجمعات؛ أو ليختمن الله على قلوبهم، ثم ليكونن من الغافلين رواه مسلم في الصحيح، ويقول ﷺ: من ترك ثلاث جمع بغير عذر؛ طبع الله على قلبه ويقول -عليه الصلاة والسلام-: بين الرجل، وبين الكفر والشرك ترك الصلاة رواه مسلم في صحيحه، ويقول أيضًا -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر. فأنت شددي عليه، ولا يقربك حتى يستقيم، وإلا فاعتزليه بالكلية، واذهبي إلى أهلك، أو في بيت وحدك أنت وأولادك، وأنت أحق بأولادك منه؛ لأن مثلهم يربيهم على الشر، فأنت أولى بأولادك، وعليك أن تستمري في النصيحة لهذا الزوج مع منع نفسك منه؛ حتى يتوب إلى الله، وحتى يرجع إلى الحق، وحتى يحافظ على الصلوات كلها، نسأل الله له الهداية، وأن يمن عليه بالتوبة، ونسأل الله لك المزيد من التوفيق، وعظيم الأجر، وأن ينفع بجهودك، ودعوتك ونصيحتك، وأن يجعلك مباركة أينما كنت، وأن يهديه لقبول نصيحتك، والهداية بما يعينه على الخير، وبما يعينه على ترك الشر، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، سماحة الشيخ! هذه المرأة تقرب من المثالية! الشيخ: الله أكبر، جزاها الله خيرًا، نعم. المقدم: ولا بد لسماحتكم من كلمة إلى كل زوجة تؤمن بالله.  الشيخ: نعم، نعم، على كل زوجة أن تتقي الله، وأن تعين زوجها على طاعة الله، وألا تتساهل معه، وألا تداهنه، وعلى الزوج كذلك أن يتقي الله في زوجته، وأن يعينها على طاعة الله، وأن يلزمها بالصلاة في وقتها، كل منهما عليه أن يعين الآخر، وأن ينصح الآخر. يقول الله لنبيه ﷺ: وَأْمُرْ أَهْلَكَ بِالصَّلاةِ وَاصْطَبِرْ عَلَيْهَا [طه:132] ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا النَّاسُ وَالْحِجَارَةُ [التحريم:6] فالواجب على جميع الأسرة التعاون على الخير، الزوج والزوجة، والأب، والأم، والأخ، والابن، والبنت، كلهم يتعاونون، يجب على الجميع أن يتعاونوا على البر والتقوى، وأن يتواصوا بالحق، فالزوج يأمر زوجته، ويلزمها بالحق، ولو بالتأديب، والزوجة كذلك تنصح زوجها، وتعينه على الحق، وإذا لم يستجب؛ استحق منها الهجر فيما أظهر من المعاصي. والهجر ثلاثة أيام في القول، وإذا كان كفرًا؛ وجب عليها فراقه: كترك الصلاة، أو سب الدين، هذا يكون كفرًا من سب الدين، أو سب الرسول، أو ترك الصلاة يكون كافرًا، يجب عليها أن تتركه، وأن تذهب إلى أهلها، وتمنعه من نفسها. وكذلك إذا كان يجحد شيئًا مما حرمه الله؛ كأن يستحل الخمر، أو الزنا، ويراه حلالًا، أو يرى أن الصلاة ما هي بواجبة يقول: ما هي بواجبة، ما علينا صلاة، أو ما علينا زكاة، .. يكون هذا كفرًا أكبر، أو يستهزئ بالدين: يسخر بالصلاة، أو يسخر بالإسلام، أو يسخر بالزكاة، أو يسخر بالرسول، ويستهزئ به؛ كل هذا كفر أكبر، وردة عن الإسلام، نعوذ بالله. المقصود: الواجب على الزوجين، وعلى الأسرة كلها: التناصح، والتعاون على البر والتقوى، والتواصي بالحق، والصبر في ذلك، والله -جل وعلا- يعينهم إذا صدقوا، وأخلصوا، يعينهم، ويوفقهم، وينفع بجهودهم، هكذا سنته في عباده، أنه سبحانه يوفق من أخلص له، ويعينه، كما قال : وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3]، ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم، وتقبل منكم.","link":"https://binbaz.org.sa/fatwas/15414/واجب-المراة-تجاه-زوجها-المتساهل-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_760/nour_76003.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة","قضايا المرأة"]},{"id":16690,"question":"تسأل عن بعض الكتب لو تكرمتم سماحة الشيخ، وتطلب رأي سماحتكم فيها، فذكرت مثلًا كتاب (تحفة العروس)؟","title":"ما ينصح باقتنائه ومطالعته من الكتب؟","answer":"الجواب: الكتب تختلف، وأحسنها، وأصدقها، وأعظمها، وأوجبها كتاب الله، القرآن هو أحسن كتاب، وأصدق كتاب، وأعظم كتاب، وهو أصل الدين وأساسه، فنصيحتي لكل مسلم ومسلمة العناية بالقرآن تلاوة، وتدبرًا، وحفظًا، وفهمًا، وعملًا، فهو أحسن كتاب، وأصدق كتاب. وأوصي كل مسلم ومسلمة بالعناية بكتاب الله، وحفظ ما تيسر منه، وقراءته نظرًا بالتدبر، والتعقل، والعمل، وإذا تيسر حفظه فذلك فضل عظيم، مع الإكثار من التلاوة، والتدبر، والتعقل، والفهم، والمذاكرة مع العلماء والزملاء في المعاني، ومراجعة كتب التفسير المعتمدة، كابن جرير، وابن كثير، والبغوي، ونحوها لمعرفة المعاني من كتاب الله . ثم يلي ذلك كتب السنة، كتب الحديث الشريف، وأولاها، وأصحها الصحيحان، صحيح البخاري، وصحيح مسلم، فهما أصح الكتب بعد القرآن العظيم، ثم السنن الأربع؛ سنن أبي داود، والترمذي، والنسائي، وابن ماجة فهي كتب عظيمة في الحديث الشريف، ولكنها ليست .... الصحيحين، بل هي دون الصحيحين؛ لأن فيها بعض الأحاديث الضعيفة. ويلتحق بذلك مسند أحمد -رحمه الله- وموطأ مالك، وسنن الدارمي، والدارقطني، وصحيح الحاكم، وصحيح ابن حبان، هذه كتب مفيدة عظيمة، لكن فيها الضعيف، وفيها الصحيح، وطالب العلم يجتهد في معرفة الصحيح، ويسأل أهل العلم، ويجتهد في معرفة المصطلح، وما قاله العلماء في بيان الحديث الصحيح، والضعيف حتى يكون على بينة، وعلى بصيرة.  ومن الكتب التي ينبغي أن يعتنى بها: كتب العقيدة؛ لأنها تعين على فهم كتاب الله، وسنة رسوله ﷺ التي ألفها أهل العلم من أهل السنة، مثل كتاب التوحيد لابن خزيمة، مثل كتاب الدارمي في الرد على بشر المريسي، مثل كتاب السنة لعبدالله بن أحمد بن حنبل، مثل منهاج السنة لشيخ الإسلام ابن تيمية في الرد على الرافضة، ومثل زاد المعاد لابن القيم في بيان هدي النبي ﷺ في العبادات وغيرها، مثل فتح المجيد للشيخ عبدالرحمن بن حسن آل الشيخ شرح كتاب التوحيد، ومثل كتاب التوحيد، كذلك كتاب عظيم كتاب التوحيد، كشف الشبهات، ثلاثة الأصول للشيخ محمد عبدالوهاب -رحمه الله- العقيدة الواسطية لشيخ الإسلام ابن تيمية، وهكذا الحموية والتدمرية له أيضًا -رحمه الله- كلها كتب عظيمة، ينبغي أن تقتنى، ويعتنى بها، وهكذا شرح الطحاوية لابن أبي العز، كتاب جيد وعظيم، نسأل الله للجميع التوفيق، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15452/ما-ينصح-باقتناىه-ومطالعته-من-الكتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_820/nour_82006.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16822,"question":"يقول سماحة الشيخ في سؤال آخر: لي خالة تجاوزت العقد الثالث من عمرها، لكنها لا تصلي بالرغم من أنها طيبة المعشر، حميدة الخصال، ولقد أمرتها، ولكن لم تمتثل لأمري، فما هو توجيهكم نحوها؟ وما هو توجيهكم لها؟ جزاكم الله خيرًا.","title":"ما كيفية التعامل مع أقارب لا يصلون؟","answer":"الجواب: الواجب عليها أن تصلي؛ لأن الصلاة عمود الإسلام، وهي فرض على كل مسلم ومسلمة، وهي الركن الثاني من أركان الإسلام الخمسة، قال الله -جل وعلا-: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238] وقال سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ [النور:56] وقال -جل وعلا-: قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلاتِهِمْ خَاشِعُونَ.. [المؤمنون:1-2] إلى أن قال في آخر الآيات: وَالَّذِينَ هُمْ عَلَى صَلَوَاتِهِمْ يُحَافِظُونَ ۝ أُوْلَئِكَ هُمُ الْوَارِثُونَ ۝ الَّذِينَ يَرِثُونَ الْفِرْدَوْسَ هُمْ فِيهَا خَالِدُونَ [المؤمنون:9-11] وهذا يعم الرجال، والنساء جميعًا. وقال النبي ﷺ: رأس الأمر الإسلام، وعموده الصلاة وقال -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر. فالواجب عليها أن تصلي الصلوات الخمس، وأن تحافظ عليها في أوقاتها، وعليكم أن تنصحوها دائمًا، وعلى أبيها، وأمها، وأعمامها، وأخوالها، وإخوتها عليهم أن ينصحوها، وأن يجتهدوا في ذلك؛ لأن هذا واجب الجميع، وإذا أصرت؛ فالواجب تأديبها من أبيها، وإخوتها الكبار، ولو بالضرب حتى تستقيم، حتى تصلي؛ لأن من ترك الصلاة يستتاب، فإن تاب وإلا قتل، كافرًا -نسأل الله العافية- من الرجال والنساء. فالواجب عليها أن تستمع أمر الله، وأن تبادر إلى الصلاة، وعلى أقاربها أن ينصحوها، وعلى أبيها، أو جدها، أو إخوتها الكبار أن يقوموا عليها في ذلك بالصدق، والقوة، ولو بالتأديب، والضرب حتى تستقيم. وينبغي أيضًا هجرها إذا كان الهجر ينفع، تهجر: كعدم الكلام معها، وعدم السلام عليها، وعدم زيارتها، لكن الأب، ونحوه ما يكفي منه الهجر، بل يجب أن يقوم بما يجب من التأديب، والإلزام، أبوها، وكذا جدها، وكذا أخوها. المقصود: أن على الأقارب العناية بهذا الأمر، والنصيحة؛ لأن هجرها قد يسبب بقاءها على حالها الباطلة، لكن العناية بها، والحرص على استقامتها هذا هو الواجب على الجميع، ولو بالتأديب، والضرب من أبيها، أو أخيها الكبير؛ حتى تستقيم، حتى تصلي، نسأل الله لنا ولها الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا. سماحة الشيخ! ماهو توجيهكم إذا كان لهذه المرأة زوج؟ الشيخ: زوجها إذا كان يصلي ما يحل له أن تبقى معه، يجب أن يفارقها، إن لم تهتد، ولم تتب؛ عليه أن يفارقها؛ لأن ترك الصلاة كفر أكبر، فعليه أن يفارقها بالكلية؛ حتى تتوب، وفي إمكانه أن يؤدبها أيضًا، أن يؤدبها على ذلك؛ لأن هذا من المنكرات العظيمة، فإذا أدبها لحقه، وعصيانها له، فتأديبها لحق الله الذي هو أهم الواجبات، وأعظم الفروض بعد التوحيد، وهو الصلاة أمر مهم. المقدم: جزاكم الله خيرًا، سماحة الشيخ! ماهو رأيكم في الهدية في بداية الأمر لمثل هذه؟ الشيخ: إذا كان قريبها، أو زوجها يرى أن إعطاءها شيئًا من المال يعين على ذلك، يفعل لا بأس، وهذا من باب الإعانة على الخير، إذا أهدى إليها شيئًا، أو أهدى إليها أخوها، أو ابن أخيها، أو أختها هدية من المال؛ لتهتدي فهذا طيب، هذا من التأليف من تأليف القلوب. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15578/ما-كيفية-التعامل-مع-اقارب-لا-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_763/nour_76313.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":16886,"question":"رجل له زوجة، ونصحها بالصلاة عدة مرات، ولم تجب لنصيحته، علمًا بأنها لا تفقه شيئًا من القرآن والسنة، فما حكم ذلك في الإسلام؟ جزاكم الله خيرًا.","title":"ما كيفية نصح الزوجة التي تترك الصلاة لجهلها؟","answer":"الجواب: عليه أن يستمر في نصيحتها، ويعلمها، أقول: عليه الاستمرار في النصيحة، والتعليم، ولا ييأس، ولكن يكون بالكلام الطيب، والأسلوب الحسن، والرفق، وشيئًا شيئًا قليلًا قليلًا حتى تتعلم ما أوجب الله عليها وما حرم الله عليها سبحانه ..... المقدم: وموضوع الصلاة؟ الشيخ: نعم؟ المقدم: يقول: إنها لا تصلي؟ الشيخ: التوبة، التوبة تكفي. المقدم: إذا أبت أن تتوب كما يقول في السؤال؟ يقول: إنها أبت أن تتوب؟ الشيخ: في إمكانه إذا كان له قدرة أن يؤدبها على ذلك حتى تستقيم، وتصلي: كالزوج، والأب، والجد، ونحو ذلك، والأخ الكبير، مع الحرص عليها بالتوجيه، والإرشاد، والترغيب في الخير، والتحذير من النار، وله أن يؤدبها إذا استطاع بضربات تمنعها من الباطل، وتعينها على أداء الحق، نعم. المقدم: إذًا لو استخدم الضرب، والهجر، وما إلى ذلك؟ الشيخ: الذي يرى فيه المصلحة حتى تتم التوبة، والعمل الصالح. المقدم: جزاكم الله خيرًا. إذًا لا يقدم على الطلاق حتى يسلك هذه الطرق. الشيخ: نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15645/ما-كيفية-نصح-الزوجة-التي-تترك-الصلاة-لجهلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_765/nour_76503.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":16916,"question":"رسالة أخرى من الإخوة: مجدي رمزي حافظ، وحارث عبد المنعم السعدي، وأشرف عاطف مختار، مصريون مقيمون في العراق، إخوتنا لهم جمع من الأسئلة، يسألون ويقولون: نعلم أن الكتب الصحيحة الستة كتب خيرة، فالرجاء أن تفيدونا: هل تختلف هذه الكتب من طبعةٍ إلى أخرى؛ لأنني -ونظرًا لكثرة الكتب- لم أعرف ما هو الصحيح فيها، الرجاء أن تفيدونا عن ذلك؟ جزاكم الله خيرًا.","title":"كيفية اختيار أفضل طبعات الكتب المفيدة","answer":"الجواب: نعم، تختلف، الطبعات بعضها رديء، بعضها فيه أغلاط، فينبغي لطالب العلم أن يختار الطباعة الجيدة، ويسأل أهل العلم الذين يعرفهم عن الطبعات الجيدة؛ حتى يستعملها، ويشتريها، ليست الطبعات على حدٍ سواء، لا في الصحيحين، ولا في السنن الأربع، ولا في غيرها من الكتب، حتى القرآن قد يقع فيه غلط من الطابعين، فطالب العلم .. يكون عنده انتباه، وعنده بصيرة، حتى لا يقتني إلا الطبعة الجيدة التي عرفها العلماء بالصحة، والسلامة من الأخطاء، وفي إمكانك إمكان كل واحدٍ منكم أن يسأل عن الطبعة الجيدة، إذا كان عنده قصور، ما يعرف، يسأل أهل العلم، يقول: عندي طبعة كذا، طبعة حق فلان، من كتاب التفسير لابن كثير، من كتاب البخاري، كتاب مسلم، كتاب سنن للترمذي، إلى غيره، يسأل أهل العلم الذي يعرفونه، الذين يعرفهم؛ حتى يدلوه ويرشدوه على الطبعة الجيدة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15684/كيفية-اختيار-افضل-طبعات-الكتب-المفيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_826/nour_82604.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16951,"question":"يسأل أخونا (ع. ف. غ) هذا السؤال فيقول: هل دعوة الشيخ محمد بن عبدالوهاب مذهب خاص؟ وهل ما يقال عن دعوته من ترك عبادة القبور، ودعوة الأموات يعد جفاءً للصالحين؟","title":"التعريف بدعوة الشيخ محمد بن عبد الوهاب","answer":"الجواب: الشيخ محمد بن عبد الوهاب -رحمه الله- من علماء السنة، ومن علماء أهل الحق، ودعوته ليست مذهبًا خامسًا، وإنما هي دعوة إلى العقيدة السلفية، وإلى ما كان عليه سلف الأمة من الصحابة وأتباعهم، فهو يدعو إلى توحيد الله، واتباع شريعته، وتعظيم أمره ونهيه، وليس يدعو إلى مذهبٍ جديد، كما يزعمه الجهلة، أو خصومه المعادون، عباد الأوثان، إنما دعا إلى عبادة الله وحده.  وقد كانت دعوته في القرن الثاني عشر، في النصف الثاني من القرن الثاني عشر، وتوفي -رحمه الله- سنة ستٍ ومائتين وألف في أول القرن الثالث عشر. وكتبه موجودة، تبين عقيدته، مثل: كتاب التوحيد، مثل: كشف الشبهات، مثل: ثلاثة الأصول، كلها تبين دعوته، وأنه دعا إلى توحيد الله، وإخلاص العبادة لله، وألا يدعى مع الله أحد، لا ملك، ولا رسول، ولا صنم، ولا جن، ولا إنس، بل العبادة حق الله وحده، وكان في الأحكام الفقهية على مذهب الإمام أحمد بن حنبل -رحمه الله- إلا إذا ترجح عنده بالدليل قول آخر ذهب إليه. أما ما رماه به خصومه، أو الجهلة بأنه مذهب خامس، أو أنه يحتقر الصالحين والأنبياء، فهذا كله باطل، وليس في ترك الإشراك بهم احتقار لهم، ولا تنقص لهم، فالأنبياء كلهم جاؤوا بالدعوة إلى توحيد الله، والنهي عن دعوة الأولياء والصالحين، وليس متنقص الأنبياء والصالحين، وإنما المتنقص لهم الذي دعاهم من دون الله، وظن أنهم يرضون بهذا، وهم لا يرضون بأن يعبدوا مع الله، بل نهوا الناس عن ذلك، قال الله تعالى: وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولًا أَنِ اُعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ [النحل:36] وقال سبحانه: وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَسُولٍ إِلَّا نُوحِي إِلَيْهِ أَنَّهُ لا إِلَهَ إِلَّا أَنَا فَاعْبُدُون [الأنبياء:25]. فالرسل كلهم -عليهم الصلاة والسلام- دعوا إلى توحيد الله، وإخلاص العبادة له -جل وعلا- وإلى اتباع الرسول فيما جاء به، وهكذا نبينا محمد ﷺ دعا إلى توحيد الله، وتعظيم أمره ونهيه، وهكذا العلماء من أهل السنة والجماعة دعوا إلى ما دعا إليه الرسول ﷺ من توحيد الله، والإخلاص له، كمالك، والشافعي، وأحمد، وأبي حنيفة، والثوري، والأوزاعي، وغيرهم من أئمة الإسلام، كلهم دعوا إلى توحيد الله، وإخلاص العبادة له -جل وعلا- وطاعة الأوامر التي جاء بها الرسول ﷺ وترك النواهي، فهذا هو الحق، وهذا هو دين الله. والشيخ محمد -رحمه الله- ابن عبدالوهاب دعا إلى ما دعوا إليه، دعا إلى توحيد الله، وإلى طاعة الله فيما أمر، وترك ما نهى عنه، واتباع القرآن والسنة، وترك ما خالف ذلك، فليس له مذهب خامس، وليس له دعوة خامسة، بل هو يدعو إلى ما دعا إليه الرسول ﷺ ودعا إليه الصحابة، ودعا إليه أئمة الإسلام، بالأقوال، والأعمال، والعقيدة، هذا هو الحق الذي لا ريب فيه، ومن قرأ كتبه؛ عرف ذلك، والله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15736/التعريف-بدعوة-الشيخ-محمد-بن-عبد-الوهاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_828/nour_82803.mp3","categories":["الدعوة والدعاة"]},{"id":16956,"question":"يسأل أخونا (ع. ف. غ) هذا السؤال فيقول: هل دعوة الشيخ محمد بن عبدالوهاب مذهب خاص؟ وهل ما يقال عن دعوته من ترك عبادة القبور، ودعوة الأموات يعد جفاءً للصالحين؟","title":"التعريف بدعوة الشيخ محمد بن عبد الوهاب","answer":"الجواب: الشيخ محمد بن عبد الوهاب -رحمه الله- من علماء السنة، ومن علماء أهل الحق، ودعوته ليست مذهبًا خامسًا، وإنما هي دعوة إلى العقيدة السلفية، وإلى ما كان عليه سلف الأمة من الصحابة وأتباعهم، فهو يدعو إلى توحيد الله، واتباع شريعته، وتعظيم أمره ونهيه، وليس يدعو إلى مذهبٍ جديد، كما يزعمه الجهلة، أو خصومه المعادون، عباد الأوثان، إنما دعا إلى عبادة الله وحده.  وقد كانت دعوته في القرن الثاني عشر، في النصف الثاني من القرن الثاني عشر، وتوفي -رحمه الله- سنة ستٍ ومائتين وألف في أول القرن الثالث عشر. وكتبه موجودة، تبين عقيدته، مثل: كتاب التوحيد، مثل: كشف الشبهات، مثل: ثلاثة الأصول، كلها تبين دعوته، وأنه دعا إلى توحيد الله، وإخلاص العبادة لله، وألا يدعى مع الله أحد، لا ملك، ولا رسول، ولا صنم، ولا جن، ولا إنس، بل العبادة حق الله وحده، وكان في الأحكام الفقهية على مذهب الإمام أحمد بن حنبل -رحمه الله- إلا إذا ترجح عنده بالدليل قول آخر ذهب إليه. أما ما رماه به خصومه، أو الجهلة بأنه مذهب خامس، أو أنه يحتقر الصالحين والأنبياء، فهذا كله باطل، وليس في ترك الإشراك بهم احتقار لهم، ولا تنقص لهم، فالأنبياء كلهم جاؤوا بالدعوة إلى توحيد الله، والنهي عن دعوة الأولياء والصالحين، وليس متنقص الأنبياء والصالحين، وإنما المتنقص لهم الذي دعاهم من دون الله، وظن أنهم يرضون بهذا، وهم لا يرضون بأن يعبدوا مع الله، بل نهوا الناس عن ذلك، قال الله تعالى: وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولًا أَنِ اُعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ [النحل:36] وقال سبحانه: وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَسُولٍ إِلَّا نُوحِي إِلَيْهِ أَنَّهُ لا إِلَهَ إِلَّا أَنَا فَاعْبُدُون [الأنبياء:25]. فالرسل كلهم -عليهم الصلاة والسلام- دعوا إلى توحيد الله، وإخلاص العبادة له -جل وعلا- وإلى اتباع الرسول فيما جاء به، وهكذا نبينا محمد ﷺ دعا إلى توحيد الله، وتعظيم أمره ونهيه، وهكذا العلماء من أهل السنة والجماعة دعوا إلى ما دعا إليه الرسول ﷺ من توحيد الله، والإخلاص له، كمالك، والشافعي، وأحمد، وأبي حنيفة، والثوري، والأوزاعي، وغيرهم من أئمة الإسلام، كلهم دعوا إلى توحيد الله، وإخلاص العبادة له -جل وعلا- وطاعة الأوامر التي جاء بها الرسول ﷺ وترك النواهي، فهذا هو الحق، وهذا هو دين الله. والشيخ محمد -رحمه الله- ابن عبدالوهاب دعا إلى ما دعوا إليه، دعا إلى توحيد الله، وإلى طاعة الله فيما أمر، وترك ما نهى عنه، واتباع القرآن والسنة، وترك ما خالف ذلك، فليس له مذهب خامس، وليس له دعوة خامسة، بل هو يدعو إلى ما دعا إليه الرسول ﷺ ودعا إليه الصحابة، ودعا إليه أئمة الإسلام، بالأقوال، والأعمال، والعقيدة، هذا هو الحق الذي لا ريب فيه، ومن قرأ كتبه؛ عرف ذلك، والله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15736/التعريف-بدعوة-الشيخ-محمد-بن-عبد-الوهاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_828/nour_82803.mp3","categories":["الدعوة والدعاة"]},{"id":16964,"question":"يقول: أسأل سماحتكم عمن قرأ القرآن كاملًا، وحفظه كذلك، ولكنه لم يعمل بشيء منه كما ذكر، فما حكم الإسلام في هذا الرجل؟ جزاكم الله خيرًا.","title":"حكم من يحفظ القرآن دون أن يمتثل تعاليمه","answer":"الجواب: يقول النبي ﷺ: القرآن حجة لك أو عليك فهو حجة لمن عمل به، وهو من أسباب دخوله الجنة، وحجة على من لم يعمل به، وهو من أسباب دخوله النار، ويقول ﷺ: اقرؤوا القرآن فإنه يأتي يوم القيامة شفيعًا لأصحابه يعني: العاملين به، وفي اللفظ الآخر: يدعى بالقرآن وأهله الذين يعملون به تقدمه سورة البقرة، وآل عمران، تحاجان عن أصحابهما.  ورأى -حين أسري به- رجلًا يرضخ رأسه بالحجر، عليه رجل واقف يرضخه بالحجر، وكلما تدهور الحجر ذهب وأخذه، ورجع رأسه إلى حاله، والتأم رأسه، فضربه مرة أخرى، وهكذا، يعذب، قال: لأنه رجل آتاه الله القرآن، فنام عنه بالليل، ولم يعمل به في النهار نسأل الله العافية. فالمقصود: أن من عمل به؛ فهو حجة له، ومن أسباب سعادته، ومن حفظه، قرأه ولم يعمل به؛ فهو من أسباب عذابه، وغضب الله عليه، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15761/حكم-من-يحفظ-القران-دون-ان-يمتثل-تعاليمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_766/nour_76604.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":16967,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين من المنطقة الشرقية، يقول محمد بن علي عيساوي الأخ محمد له جمع من الأسئلة في أحدها يقول: والد لدي، لكنه لم يصل أبدًا، بعد أن نصحناه، وعلمناه، وهجرناه، وكلمناه، وبينا له بأن عقوبة تارك الصلاة الكفر، وله عذاب شديد، لكن دون جدوى، هل إذا قدر الله وتوفي يحق له أن يرثه؟ أفيدونا جزاكم الله خيرًا.","title":"حكم هجر الأولاد لوالدهم التارك للصلاة","answer":"الجواب: الوالد له حق عظيم، سواءً كان رجلًا، أو امرأة، الوالد والوالدة، فالواجب النصيحة، والإرشاد، والمخاطبة الحسنة، ولو كان تاركًا للصلاة، ولو كان كافرًا بأي كفر، لا بد من الصبر، والاستمرار في النصيحة، والتوجيه، وعدم الهجر، لا تهجره، لا يجوز لك هجره، الله يقول سبحانه في كتابه العظيم: وَإِنْ جَاهَدَاكَ [لقمان:15] يعني الوالدين عَلى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] أمره بأن يصاحبهما في الدنيا معروفًا، وألا يطيعهما في المعصية، ولا في الكفر، ولهذا قال بعده: وَاتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَيَّ [لقمان:15]. فالمقصود: أن الواجب عليك أيها الولد أن تتقي الله، وأن تنصح والدك أنت وإخوانك، ومن يساعدكم من أهل الخير بنصيحته، وتوجيهه، وعدم اليأس، لكن لا تهجره، ولا تؤذه، ولا ترفع الصوت عليه، ولكن تنصحه بالكلام الطيب، والأسلوب الحسن، كما أنت مأمور بذلك، يقول الله -جل وعلا-: وَوَصَّيْنَا الإِنْسَانَ بِوَالِدَيْهِ حُسْنًا وَإِنْ جَاهَدَاكَ لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُمَا [العنكبوت:8] ويقول -جل وعلا-: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14] ثم قال بعدها: وَإِنْ جَاهَدَاكَ عَلى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا وَاتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَيَّ [لقمان:15]. فأنت مأمور بأن تصاحبهما بالمعروف، بالكلام الطيب، لكن مع النصيحة.. مع التوجيه.. مع الإرشاد، عملًا بقول ربك -جل وعلا-: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ [لقمان:14] وقوله: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] وقد يهديهما الله على يديك، ويكون لك بذلك الخير العظيم، والأجر الكبير، وقد قال الله : وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء:24]. فلا تيأس يا أخي، وترك الصلاة لا شك أنه كفر، وهو كفر أكبر على أصح قولي العلماء، كفر أكبر، وإذا مات على ترك الصلاة لا يرثه المسلم من أولاده، وإنما يكون للكفرة من أقاربه الذين مثله. وقال آخرون من أهل العلم: إنه لبيت المال؛ لأنه مرتد، فيكون ماله لبيت المال، لا لمن كان كافرًا من جماعته، بل يؤخذ ماله، ويوصل لبيت المال؛ لأنه ليس من الكفار الأصليين، وليس من المسلمين، والمرتد يكون ماله فيئًا لبيت مال المسلمين، يصرف في مصالح المسلمين، وهذا قول قوي وجيد، ولعله الأقرب والأولى، فلا يعطاها الكفار، ولا يعطاها المسلمون، ولكن يصرف لبيت المال. إذا ارتد بترك الصلاة، أو بسب الدين، أو بشيء من أنواع الكفر والضلال الأخرى؛ فإنه لا يصلى عليه، ولا يغسل، ولا يدفن مع المسلمين، ويكون ماله فيئًا لبيت مال المسلمين، ومصالح المسلمين، وإذا رأى ولي الأمر أن يعطيه أولاده المسلمين تقديرًا لجهودهم، وأعمالهم في نصيحته، ولئلا يحرموا منه؛ فلا بأس إذا رأى ولي الأمر ذلك مساعدة لهم على التثبيت في الإسلام، وتأليف قلوبهم، هذا أمر حسن. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15764/حكم-هجر-الاولاد-لوالدهم-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_766/nour_76605.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":17135,"question":"السائل من سوريا يقول: سماحة الشيخ! أنا أريد أن أتفقه في أمور ديني وخصوصًا في العقيدة، فما الكتب التي توصونني وزملائي بقراءتها في كتب العقيدة؟ مأجورين.","title":"كتب ينصح بقراءتها في العقيدة","answer":"الجواب: أوصيك وكل مسلم بالقرآن، هو كتاب العقيدة العظيمة، نوصيك بالقرآن الكريم، والإكثار من تلاوته، وتدبر معانيه، وحفظه إذا تيسر، هو كتاب الله، هو أعظم كتاب، وأصدق كتاب، وهو فيه بيان العقيدة التي أمر الله بها عباده من التوحيد، والأسماء، والصفات.. وغير ذلك، فعليكم بالإكثار من قراءة القرآن، الإكثار من تدبره، وتدبر معانيه، والسؤال عما أشكل عليكم، فهو كتاب الله، فيه الهدى والنور، وهكذا الحديث عن الرسول ﷺ إذا تيسر، مثل كتاب الأربعين النووية، وتتمته لابن رجب خمسين حديثًا، إذا تيسر لك حفظها فيها أحاديث جيدة، كذلك عمدة الحديث للشيخ عبدالغني، عمدة الحديث فيها أحاديث صحيحة تحفظها، والعقيدة الواسطية لشيخ الإسلام ابن تيمية كتابٌ طيب عقيدة طيبة، ملخصة من الكتاب والسنة، كتاب عظيم، كتاب التوحيد للشيخ محمد بن عبدالوهاب -رحمه الله- ثلاثة الأصول للشيخ محمد، ثلاثة الأصول، والقواعد الأربع، كل هذه كتبٌ طيبة، كشف الشبهات للشيخ محمد أيضًا، كتابٌ طيب. نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15958/كتب-ينصح-بقراءتها-في-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58926.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":17174,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من المستمع: رقيب محمود محمد علي، أخونا يبدو أنه سوداني، وقد عرضنا بعض أسئلة له في حلقة مضت من حلقات هذا البرنامج، أما في هذه الحلقة، فيسأل سماحتكم، فيقول: يوجد لدينا بعض الإخوان يقعون في بعض الشرك، ويقول: بأن الولي، أو الرجل الصالح هذا الذي يميل إليه أنه يعلم الغيب، أو أن لديه بعض الغيبيات، هل يجوز أن نجلس مع أمثال هؤلاء؟ جزاكم الله خيرًا.","title":"حكم الجلوس مع من يعتقد علم الغيب في الأولياء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فهذا وأشباهه لا يجوز الجلوس إليهم إلا على سبيل الدعوة، والتعليم، والإرشاد، والنصيحة؛ لأن دعاء الأولياء، والاستغاثة بالأولياء -وهم أصحاب القبور أو الغائبون- من الشرك الأكبر، الذي جاءت الرسل -عليهم الصلاة والسلام- بالنهي عنه، ودل القرآن الكريم على النهي عنه، وأنه من الشرك الأكبر. فدعاؤهم، والاستغاثة بهم، والنذر لهم، والذبح لهم، كل هذا من الشرك الأكبر، الطواف بقبورهم، كل هذا من الشرك الأكبر، واعتقاد أنهم يعلمون الغيب، هذا كفر أكبر، فليس يعلم الغيب إلا الله وحده سبحانه، فالرسل، وغيرهم لا يعلمون الغيب، إنما يعلمه الله، إلا ما علمهم الله إياه، كما قد علمهم أشياء من أمر الآخرة، وأمر آخر الزمان، وما مضى من الزمان فليس لهم من علم الغيب إلا ما علمهم الله إياه، كما قال الله  في كتابه العظيم: قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ [النمل:65] ويقول : وَعِنْدَهُ مَفَاتِحُ الْغَيْبِ لا يَعْلَمُهَا إِلَّا هُوَ [الأنعام:59] ويقول لنبيه ﷺ يقول للناس: قُلْ لا أَمْلِكُ لِنَفْسِي نَفْعًا وَلا ضَرًّا إِلَّا مَا شَاءَ اللَّهُ وَلَوْ كُنتُ أَعْلَمُ الْغَيْبَ لاسْتَكْثَرْتُ مِنَ الْخَيْرِ وَمَا مَسَّنِيَ السُّوءُ إِنْ أَنَا إِلَّا نَذِيرٌ وَبَشِيرٌ لِقَوْمٍ يُؤْمِنُونَ [الأعراف:188] هكذا يقول ﷺ يخبرهم أنه نذير وبشير، ليس عالمًا بالغيب، ويقول -جل وعلا- يأمر نبيه أن يعلم الناس: قُلْ لا أَقُولُ لَكُمْ عِندِي خَزَائِنُ اللَّهِ وَلا أَعْلَمُ الْغَيْبَ وَلا أَقُولُ لَكُمْ إِنِّي مَلَكٌ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَى إِلَيَّ [الأنعام:50]. فعلم الغيب إلى الله سبحانه، ومن قال: إن هذا الولي الفلاني ابن عربي، أو الحسين  أو علي  أو الشيخ: عبدالقادر الجيلاني، أو غيرهم، من قال: إن هؤلاء، أو غيرهم يعلمون الغيب؛ فقد كفر، وأشرك، وكذب الله  وهكذا من زار قبور هؤلاء؛ ليدعوهم، أو يستغيث بهم، أو دعاهم من بعيد عن قبورهم في أي مكان، دعاهم، واستغاث بهم، ونذر لهم، أو اعتقد أنهم ينفعون، أو يضرون، أو أنهم يعلمون الغيب، أو أنهم يستجيبون لمن دعاهم بكشف الضر، وجلب النفع، أو ما أشبه ذلك، هذا هو الشرك الأكبر، هذا دين الجاهلية، دين قريش في حال جهلها، وكفرها، هذا دين أبي جهل، وأشباهه. فدعاء الأموات، والاستغاثة بالأموات، والذبح للأموات، وطلبهم الشفاء، وهكذا طلب الغائبين من الجن، أو الملائكة، أو غيرهم كله من الشرك الأكبر، فالواجب الحذر من ذلك غاية الحذر. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16030/حكم-الجلوس-مع-من-يعتقد-علم-الغيب-في-الاولياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72301.mp3","categories":["الدعوة والدعاة","نواقض الإسلام"]},{"id":17227,"question":"هذا سائل للبرنامج، أرسل يستفسر عن هذا الحديث يا سماحة الشيخ، يقول: ما هو ضابط الأمر بالمعروف، والنهي عن المنكر، حفظكم الله؟","title":"ضابط الأمر بالمعروف والنهي عن المنكر","answer":"الجواب: سمعت الله يقول: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُوْلَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71] هذا وصف المؤمنين والمؤمنات، يأمرون بالمعروف، ويـنهون عن المنكر، ومعنى الأمر بالمعروف: إذا رأيت من لا يصلي في الجماعة؛ تأمره بالمعروف، الصلاة في الجماعة معروف، وتركها منكر، فتأمره بالمعروف، وهو: صلاة في الجماعة، وتنهى عن المنكر، وهو: التخلف عنها. وإذا رأيت الذي يشرب الدخان؛ تأمره بترك الدخان، وتنهاه عن شربه، فالأمر بالترك، أمرٌ بالمعروف، والنهي عن شربه، نهيٌ عن المنكر، وإذا رأيت الذي يحلق لحيته، أو يقصرها، تقل له: اتق الله، وفر اللحية، هذا أمرٌ بالمعروف، لا تحلقها، هذا نهيٌ عن المنكر، وإذا رأيت الذي يعق والديه، تنهاه عن ذلك، تقل له: اتق الله، بر والديك، أحسن إليهما، لا تعقهما، فالأمر بالبر؛ أمرٌ بالمعروف، والنهي عن العقوق؛ نهي عن المنكر. وإذا رأيت الذي يشرب الخمر، تنهاه، هذا نهيٌ عن المنكر، تقل له: اتق الله، راقب الله، اترك الخمر، هذا نهيٌ عن المنكر، وإذا رأيت الذي يسبل ثيابه، يجرها تحت الكعب، تقل: اتق الله، ارفع ثيابك، الإسبال محرم، منكر، اتق الله، راقب الله، هذا من النهي عن المنكر. نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16053/ضابط-الامر-بالمعروف-والنهي-عن-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59104.mp3","categories":["الدعوة والدعاة"]},{"id":17253,"question":"هذا أخونا السائل عبد السلام قداريه من الجزائر، يقول في هذا السؤال حفظكم الله: سماحة الشيخ! كيف يكون طلب العلم الدنيوي مثل الرياضيات، والفيزياء، والكيمياء، كيف يكون علمًا في سبيل الله؟ وهل الأحاديث الشريفة التي تحث على طلب العلم مثل: من سلك طريقًا يبتغي فيه علمًا؛ سهل الله له طريقًا إلى الجنة تعني العلم الأخروي فقط؟ أم العلم الدنيوي، والأخروي معًا؟ والسائل من الجزائر.","title":"ما العلم الذي وردت فيه الفضائل؟","answer":"الجواب: الأظهر من النصوص أن المراد بالأحاديث العلم الشرعي قوله ﷺ: من يرد الله به خيرًا يفقهه في الدين من سلك طريقًا يلتمس فيه علمًا؛ سهل الله له به طريقًا إلى الجنة المراد بالعلم إذا أطلق في النصوص العلم الشرعي؛ علم الكتاب والسنة، علم الأحكام، علم ما أمر الله به، وما شرع الله لعباده، وما نهاهم عنه، وعلوم الدنيا إذا كانت تنفع الناس لا بأس بها، علوم الدنيا من الطب، والحساب وغيرها، إذا تعلمها لينفع بها نفسه، وينفع بها الناس؛ لا بأس بها من باب المباح، أما العلوم الشرعية فهي سنة، وقربة، وإذا كانت تتعلق بالواجبات وجبت، فالنصوص التي فيها الحث على العلم المراد بها العلم الشرعي. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16085/ما-العلم-الذي-وردت-فيه-الفضاىل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59207.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":17272,"question":"سماحة الشيخ! هناك أناس يتصدرون للفتيا بغير علم كقول صاحبنا لهذه المسكينة: إنه لا أجر لك في صيام عشرة أيام من رجب، وعشرة أيام من شعبان، فما هو توجيهكم للناس حول هذا؟ جزاكم الله خيرًا.","title":"خطر الفتوى بغير علم","answer":"الجواب: الفتوى بغير علم منكر عظيم، وهو مما حرمه الله على عباده، وجعل مرتبته فوق الشرك، قال سبحانه في سورة الأعراف: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [الأعراف:33] فالواجب على طالب العلم أن يتقي الله، وأن يحذر القول على الله بغير علم، وإذا كان هذا في حق طالب العلم فكيف بغيره، لا يجوز لأحد أن يفتي بغير علم، لا رجل، ولا امرأة، ولا طالب علم، ولا غيره، يجب على المؤمن أن يتقي الله، وأن يخاف الله سبحانه، وألا يتكلم في الحلال والحرام إلا بعلم، قال الله سبحانه: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108] يعني: على علم. وأخبر سبحانه في سورة البقرة أن الفتوى بغير علم مما يأمر به الشيطان، قال تعالى: يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الأَرْضِ حَلالًا طَيِّبًا وَلا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ ۝ إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [البقرة:169] هذا من أمر الشيطان، يأمر الناس أن يقولوا على الله ما لا يعلمون. فالواجب على كل مؤمن ومؤمنة الحذر من طاعة الشيطان في القول على الله بغير علم، والفتوى بغير علم، لا في العبادات، ولا في غيرها، يقول الله سبحانه: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43] فالفتوى تكون من أهل الذكر، يعني: من أهل العلم بالقرآن العظيم، والسنة المطهرة، العلماء بكتاب الله، وسنة رسوله ﷺ وهم الذين يفتون الناس، وهم الذين يسألون، نسأل الله للجميع الهداية، نسأل الله لنا ولإخواننا جميعًا الهداية. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16115/خطر-الفتوى-بغير-علم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_768/nour_76808.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":17357,"question":"تقول: انتشرت النميمة، والغيبة، والقيل، والقال بين جميع الناس، وبقيت -والحالة هذه- في البيت، لا أخرج مع الأهل لزيارتهم، بل جلست مع إخواني في البيت، فهل أصير قاطعة للرحم، أرجو أن تنصحون الذين ينقلون الكلام من شخص..الشيخ: أعد.. أعد..المقدم: تقول: انتشرت النميمة، والغيبة، والقيل، والقال بين الناس، فبقيت في البيت لا أخرج مع الأهل لزيارة أحد، بل جلست مع إخواني في البيت فهل أصير قاطعة للرحم؟ أرجو أن تنصحون الذين ينقلون الكلام من شخص إلى شخص آخر، فيصير بينهم مشاكل بسبب نقل الكلام، جزاكم الله خيرًا.","title":"حكم ترك زيارة الأقارب بسبب المنكرات","answer":"الجواب: خروجك مع الوالدة، ومع أخواتك الطيبات إلى الجيران، أو إلى الأقارب لا حرج فيه، وإذا رأيت شيئًا من المنكر أنكريه بالكلام الطيب، والأسلوب الحسن كما قال النبي ﷺ: الدين النصيحة والله يقول في كتابه الكريم: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]. وإياك والعزلة، والشذوذ إلا عند الضرورة، إذا رأيت أن من خرجوا إليه عندهم منكر لا يزيلونه، ولا يقبلون منك، فلا تخرجي معهم، أما سوء الظن، وتشديد الأمور من دون منكر ترينه فلا ينبغي منك، بل اخرجي مع الوالدة، مع أخواتك للجيران، أو لعيادة المريض، أو صلة الرحم ما دام الخروج لا يترتب عليه منكر، بالتستر، والحجاب والعناية، وما دام المزورون ليس عندهم منكر، أو عندهم منكر، لكن إذا حضرت زال، وقبلوا منك النصيحة، فأنت على خير عظيم، أما الخروج إلى محل فيه منكر لا يزول، ولو بحضورك، لا تخرجي له، ولا تكوني معهم فيه، وعليك نفسك، ودينك، نسأل الله للجميع التوفيق. أما النميمة فهي محرمة، ولم يزل العلماء ينصحون عنها الناس، ويحذرون منها الناس، فنقل الكلام السيئ من شخص إلى شخص، أو من جماعة إلى جماعة، أو من قبيلة إلى قبيلة، هذا منكر، وهذا يسمى النميمة، ولا يجوز، والواجب الحذر منه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16198/حكم-ترك-زيارة-الاقارب-بسبب-المنكرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_834/nour_83402.mp3","categories":["الأخلاق المذمومة","الدعوة والدعاة"]},{"id":17418,"question":"سماحة الشيخ! من حوطة بني تميم السائل الذي رمز لاسمه بـ (ف. ش. ك) يذكر بأنه شاب يبلغ من العمر الخامسة عشرة، ويرغب في طلب العلم الشرعي، فما هي نصيحتكم سماحة الشيخ لمثل هذا؟ وما هي الأمور التي لابد أن يعملها، ويتمثل بها؟ يقول: علمًا بأن مدينتنا قليلة من الدعاة، وطلبة العلم، جزاكم الله خيرًا.","title":"بيان كيفية طلب العلم","answer":"الجواب: نوصيه بطلب العلم في المدارس التي فتحتها الحكومة المتوسطة، والثانوي، أو المعاهد العلمية ... يجتهد حتى يلحق بها، وإذا كان عندهم حلقات علم لأهل العلم من القضاة، أو غيرهم يحضر حلقات العلم إذا تيسر في الليل، أو في النهار يجمع بين هذا وهذا، يلتحق بالمدارس النظامية، ويجتهد، ويقرأ على العلماء في بلده إذا كان عندهم حلقات علم في الليل، أو في النهار، يحضر الحلقات، ويستفيد، ويجتهد في حفظ القرآن الكريم، وحفظ الكتب النافعة، مثل كتاب التوحيد، كشف الشبهات، ثلاثة الأصول، والقواعد الأربع للشيخ محمد -رحمه الله- محمد بن عبد الوهاب، وكذلك العقيدة الواسطية لشيخ الإسلام ابن تيمية، هذه كتب جيدة مهمة يحفظها، ومثل الأربعين النووية، وتكملتها لابن رجب خمسين حديثًا من جوامع الكلم، يحفظ هذه الأحاديث العظيمة، والنافعة.  على كل حال، فالوصية لهذا الشاب أن يجتهد في طلب العلم في المدارس النظامية، وعلى المشايخ إذا كان عنده من يقرأ عليه من المشايخ في حلقات العلم، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16293/بيان-كيفية-طلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77119.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":17422,"question":"سماحة الشيخ! من حوطة بني تميم السائل الذي رمز لاسمه بـ (ف. ش. ك) يذكر بأنه شاب يبلغ من العمر الخامسة عشرة، ويرغب في طلب العلم الشرعي، فما هي نصيحتكم سماحة الشيخ لمثل هذا؟ وما هي الأمور التي لابد أن يعملها، ويتمثل بها؟ يقول: علمًا بأن مدينتنا قليلة من الدعاة، وطلبة العلم، جزاكم الله خيرًا.","title":"بيان كيفية طلب العلم","answer":"الجواب: نوصيه بطلب العلم في المدارس التي فتحتها الحكومة المتوسطة، والثانوي، أو المعاهد العلمية ... يجتهد حتى يلحق بها، وإذا كان عندهم حلقات علم لأهل العلم من القضاة، أو غيرهم يحضر حلقات العلم إذا تيسر في الليل، أو في النهار يجمع بين هذا وهذا، يلتحق بالمدارس النظامية، ويجتهد، ويقرأ على العلماء في بلده إذا كان عندهم حلقات علم في الليل، أو في النهار، يحضر الحلقات، ويستفيد، ويجتهد في حفظ القرآن الكريم، وحفظ الكتب النافعة، مثل كتاب التوحيد، كشف الشبهات، ثلاثة الأصول، والقواعد الأربع للشيخ محمد -رحمه الله- محمد بن عبد الوهاب، وكذلك العقيدة الواسطية لشيخ الإسلام ابن تيمية، هذه كتب جيدة مهمة يحفظها، ومثل الأربعين النووية، وتكملتها لابن رجب خمسين حديثًا من جوامع الكلم، يحفظ هذه الأحاديث العظيمة، والنافعة.  على كل حال، فالوصية لهذا الشاب أن يجتهد في طلب العلم في المدارس النظامية، وعلى المشايخ إذا كان عنده من يقرأ عليه من المشايخ في حلقات العلم، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16293/بيان-كيفية-طلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77119.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":17444,"question":"رسالة من الطالب (خالد . م. ص. غ) من المملكة، أخونا يقول: أنا طالب علم، انتهيت من الثانوية، في قريتي لا يوجد فرع للجامعة التي أسكن فيها، لذلك فأنا مضطر للسفر إلى مدينة تبعد عن قريتنا ما يقرب من ستمائة كيلو مترًا، أبي غير موافق على سفري، فهل إذا سافرت للدراسة والوالد غير راضٍ أكون آثمًا؟ أو لا؟","title":"حكم السفر لطلب العلم بدون موافقة الأب","answer":"الجواب: هذا فيه تفصيل: فإن كان الوالد في حاجة إليك؛ فالواجب عليك أن تبقى عند والدك، وتقوم بحاجته، فبره واجب، والمزيد من طلب العلم مستحب، وفي إمكانك أن تزداد من العلم من طريق سماع نور على الدرب، وسماع المحاضرات التي تذاع من إذاعة القرآن، وسماع العلم من المحاضرات في بلدك، وخطبة الجمعة في بلدك. أما إذا كان الوالد عنده من يقوم بحاجاته من إخوانك، ولا يحتاج إليك، فإنك لا حرج عليك أن تسافر لإكمال العلم، والواجب على أبيك أن يساعدك في هذا، وألا يحرجك؛ لأن طلب العلم من أهم المهمات، ومن أفضل القربات، والنبي  قال: إنما الطاعة في المعروف وليس من المعروف أن يمنعك من طلب العلم بدون حق، ودون حاجة، أما إذا كان محتاجًا لك فبره أوجب، نسأل الله للجميع التوفيق.  المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16299/حكم-السفر-لطلب-العلم-بدون-موافقة-الاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83603.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":17495,"question":"هذا سائل الذي رمز لاسمه بأخوكم (م. خ) يقول: سماحة الشيخ! ما هي الشروط التي يجب أن تتوفر في الداعية إذا أراد أن يدعو إلى الله ؟ وهل يدعو الإنسان بأقل قدر من العلم أم يجب أن يتعلم بعض العلوم الشرعية؟ وما هي هذه العلوم سماحة الشيخ مأجورين؟","title":"اشتراط العلم في الداعية","answer":"الشيخ: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفإن الداعي إلى الله لا بد أن يكون على بصيرة؛ لأن الله يقول جل وعلا: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ[يوسف:108] لا بد أن يكون عنده علم، لا بد أن يكون عنده علم من القرآن العظيم، والسنة المطهرة، فإذا كان عنده علم وبصيرة من الأدلة القرآنية، والأدلة الحديثية عن الرسول ﷺ فإنه يدعو إلى الله حسب علمه سواء كان متخرجًا من كليات الشريعة، أو كليات الدعوة، أو كليات الحديث، أو كليات في القرآن، أو درس في المساجد على العلماء.\nفالمقصود: إذا كان عنده علم بالقرآن والسنة فإنه يدعو إلى الله، ويعلم الناس دينهم، ويرشدهم إلى توحيد الله وعبادته، ويعلمهم ما أوجب الله عليهم، ويحذرهم ما حرم الله عليهم، ويرغب ويرهب كما شرع الله، وإذا كان ما عنده علم فليس له الكلام فيما لا يعلم، لكن الإنسان إذا كان عنده علم في بعض الأشياء دعا إليها، مثلما يدعو المؤمن إخوانه إلى الصلاة وإن كان عامي؛ لأن الصلاة معلومة، يدعوهم إلى الصلاة والمحافظة عليها في الجماعة، يدعوهم إلى بر الوالدين، هذا شيء معروف، يدعوهم إلى أداء الزكاة هذا شيء معروف، يدعوهم إلى صيام رمضان هذا شيء معروف، حتى ولو العامي يجتهد مع أهله، ومع إخوانه في العناية بهذه الأمور، كذلك يحذر من الزنا.. من الريبة.. من الربا.. من عقوق الوالدين.. من شرب الخمر، هذه أمور معلومة، لكن الأشياء التي قد تخفى تحتاج إلى علم فلا يتكلم فيها إلا صاحب العلم. أما الأمور الواضحة المعروفة من الدين بالضرورة هذه يتكلم فيها العالم وغير العالم، فالإنسان في أهل بيته، ومع جيرانه؛ ينصحهم في الأمور الظاهرة، تحذيرهم مما حرم الله الحث على أداء الصلاة في الجماعة .. الحث على بر الوالدين في صلة الرحم، هذه أمور معلومة بحمد الله. لكن ليس للداعي إلى الله أن يتكلم فيما لا يعلم، بل يجب أن يتحرى ما دل عليه القرآن، والسنة؛ حتى يكون في دعوته على بصيرة كما قال الله سبحانه: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ[يوسف:108]، والله يقول جل وعلا: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ[الأعراف:33]، فجعل القول عليه بغير علم في القمة فوق الشرك لعظم خطره، وأخبر سبحانه أن الشيطان يأمر بذلك فقال عن الشيطان: إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ[البقرة:169]. فالشيطان يدعو الناس إلى الكلام بغير علم والدعوة بالجهل، وهذا منكر عظيم، بل الداعي إلى الله يجب أن يتثبت ويجب أن يتعلم حتى يكون على بينة وعلى بصيرة مما يدعو إليه، وفيما ينهى عنه، لكن الأمور الظاهرة المعروفة من الدين بالضرورة فهذه يدعو إليها العالم وغير العالم مثلما تقدم، كالتحذير من الزنا.. التحذير من العقوق.. التحذير من قطيعة الرحم.. التحذير من الربا هذا أمر معلوم، كذلك يدعو إلى الصلاة في الجماعة .. يدعو إخوانه، وجيرانه، وأهل بيته، يحذرهم من الغيبة، والنميمة، كل هذه أمور معروفة. نعم.\nالمقدم: أحسن الله إليكم وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16407/اشتراط-العلم-في-الداعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_774/nour_77401.mp3","categories":["الدعوة والدعاة"]},{"id":17634,"question":"رسالة وصلت إلى البرنامج من المستمع عبد الرزاق محمد صالح العلمي من اليمن-بيحان يقول في رسالته: ما حكم من سكن مع مجموعة من الشباب لكنهم لا يصلون صلاة الصبح في وقتها بل يتركونها حتى قيامهم للعمل ثم يصلون، أمرهم بهذا ولم يستجيبوا؟ ويسأل توجيهكم، جزاكم الله خيرًا.","title":"حكم السكن مع أناس يؤخرون صلاة الصبح","answer":"الجواب: الواجب أمرهم بالمعروف ونهيهم عن المنكر والإنكار عليهم وتحذيرهم من مغبة ذلك فإنه لا يجوز تأخير الصلاة عن وقتها، الله كتب على المسلمين الصلاة مؤقتة إِنَّ الصَّلاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَوْقُوتًا [النساء:103]، وأمر أن تؤدى في وقتها، أمر الله أن تؤدى في وقتها وهكذا رسوله عليه الصلاة والسلام يقول جل وعلا: أَقِمِ الصَّلاةَ لِدُلُوكِ الشَّمْسِ إِلَى غَسَقِ اللَّيْلِ وَقُرْآنَ الْفَجْرِ [الإسراء:78] يعني: صلاة الفجر إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا [الإسراء:78]. فالواجب أن تؤدى في الوقت ولا يجوز للمسلم أن يؤخر صلاة الفجر إلى بعد طلوع الشمس حتى يقوم لعمله، بل يجب عليه أن يصليها في الوقت، وإذا تعمد ذلك يكفر عند جمع من أهل العلم إذا تعمد ذلك قصد ذلك كفر عند جمع من العلماء، لقوله ﷺ في الحديث الصحيح: بين الرجل وبين الكفر والشرك ترك الصلاة. ومن أخرها عن الوقت عمدًا فقد تركها، ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، فالواجب الحذر الواجب على المؤمن أن يحذر هذه المحارم العظيمة، ولو قيل بعدم كفره يجب عليه أن يحذر؛ لأنها معصية عظيمة وكبيرة عظيمة حتى ولو قلنا بعدم الكفر مع أن القول القوي والقول الراجح كفر من ترك الصلاة، وإن لم يجحد وجوبها؛ لهذا الحديث الصحيح وما جاء في معناه يقول ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، رواه مسلم في الصحيح. فالذي ترك الصبح حتى طلعت الشمس قد تعمد تركها، وإذا ترك العصر حتى غابت الشمس قد تعمد تركها، وإذا ترك العشاء حتى غاب طلع الفجر فقد تعمد تركها، يقال له: إنه ما صلى، ويقال له: ترك الصلاة، وإذا ترك الخمس جميعًا صار أشد في الكفر، فالذي يترك واحدة أو ثنتين حكمه حكم من ترك الجميع، والله يقول سبحانه: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238]، يعني: حافظوا عليها في وقتها، يجب أن يحافظ عليها في وقتها، ولا يجوز التشبه بأهل النفاق. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16564/حكم-السكن-مع-اناس-يوخرون-صلاة-الصبح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_844/nour_84406.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":17732,"question":"تقول السائلة سماحة الشيخ! كثيرًا ما آمر بالمعروف وأنهى عن المنكر وبعد ذلك أشعر بالندم؛ لأنني أحيانًا أجد الأذى، فهل ندمي محبط للأجر؟","title":"هل الندم على الأمر بالمعروف محبط للأجر؟","answer":"الجواب: ينبغي أن تستمري في هذا الخير العظيم؛ لأن الأمر بالمعروف والنهي عن المنكر سنة مشروعة للمؤمنين جميعًا بل واجب، لقول الله : وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ[التوبة:71] هذا وصف المؤمنين والمؤمنات، فالواجب على المؤمنة والواجب على المؤمن الأمر بالمعروف والنهي عن المنكر مع الاستطاعة حيث استطاع.\nوالندم على هذا بعض الأحيان هذا من الشيطان، ندمك في هذا هذا من الشيطان ونرجو أن لا يحبط به عملك الطيب لكن هذا من الشيطان تعوذي بالله من الشيطان ولا تلتفتي لهذا الندم واستمري في الخير.\nالمقدم: أحسن الله إليكم وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16704/هل-الندم-على-الامر-بالمعروف-محبط-للاجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_777/nour_77705.mp3","categories":["الدعوة والدعاة"]},{"id":17738,"question":"سماحة الشيخ هذه السائلة للبرنامج تقول: ما حكم قبول الهدايا من الطالبات؟ جزاكم الله خيرًا.","title":"حكم قبول الهدايا من الطلاب","answer":"الجواب: الأقرب- والله أعلم- أنه لا ينبغي قبولها؛ لأنها قد تكون رشوة، فالذي ينبغي ترك القبول، وتعليمهم عدم الإهداء؛ لأن الهدية إذا جاءت المعلمة أو المعلم قد تفضي به إلى الغش والمحاباة لهذا الذي أهدى، فالأحوط والذي ينبغي ترك ذلك.","link":"https://binbaz.org.sa/fatwas/16694/حكم-قبول-الهدايا-من-الطلاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59604.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":17766,"question":"نبدأ هذا اللقاء الطيب المبارك برسالة الجزائر (س. ح) رمز لاسمه بهذا الاسم البليدة يقول في هذا  سماحة الشيخ! ما هو العلم الواجب؟ هل هو الديني؟ أم الدنيوي؟ أم معًا؟ أفيدونا مأجورين وجزاكم الله خيرًا.","title":"العلم الواجب على المكلف","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفإن العلم علمان: علم ديني، وعلم دنيوي.\nفالعلم الديني واجب على كل مكلف أن يتعلم ما أوجب الله عليه، وما حرم الله عليه، وما لا يسعه جهله كما نص على ذلك أهل العلم، فالواجب على كل مكلف من الرجال والنساء أن يتعلم ما أوجب الله عليه، وأن يتفقه في دينه فيعرف ما أوجب الله من صلاة وغيرها ويعرف ما حرم الله عليه من الشرك وغيره حتى يعبد ربه على بصيرة، ويعبر كثير من أهل العلم بقولهم: يجب على المكلف أن يتعلم من دينه ما لا يسعه جهله، والمعنى: أن يتعلم ما أوجب الله عليه، وما حرم الله عليه، فيتعلم معنى لا إله إلا الله وايش معناها، وايش معنى شهادة أن محمدًا رسول الله، ما هي الصلاة؟ ما هي الزكاة؟ ما هو صوم رمضان؟ ما هو الحج؟ يتعلم هذه الأشياء اللي أوجبها الله عليه.\nويتعلم الأشياء اللي حرم الله ما هو الزنا؟ ما هو الربا؟ ما هو المسكر؟ يتعلم حتى يعرف الواجب فيؤديه، وحتى يعرف المحرم فيجتنبه حسب الطاقة فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16] يتعلم حسب الطاقة بسؤال أهل العلم بقراءة القرآن، والتفقه فيه، بقراءة الأحاديث عن النبي ﷺ، بحضور حلقات العلم، بالسؤال من طريق المكاتبة، من طريق التلفون، يجتهد حسب الطاقة، يلزمه أن يتعلم حسب الطاقة، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]، لا يسكت ولا يرضى بالجهل بل يتعلم؛ لأنه مخلوق لعبادة الله كما قال الله سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ[الذاريات:56] مأمورون بذلك، يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ[البقرة:21]، فهذه العبادة التي خلق لها وهو مأمور بها يجب أن يعرفها، ما هي العبادة؟ يجب أن يتعلم حتى يعرف هذه العبادة التي خلق لها، وأوجبها الله عليه، وهي: أداء فرائض الله، وترك محارم الله.\nوأصلها وأساسها توحيد الله، والإخلاص له، والإيمان به وبرسوله محمد ﷺ، والإيمان بكل ما أخبر الله به ورسوله مما كان وما يكون من أمر الآخرة، والجنة والنار، والحساب والجزاء، وما مضى من خلق الله آدم، وبعث الرسل يؤمن بكل ما أخبر الله به ورسوله عن بصيرة، ويعلم أن هذا حق، ويعمل فيؤدي ما أوجب الله، وينتهي عما حرم الله، هذا واجب عليه حسب الطاقة من طريق حلقات العلم، من طريق تدبر القرآن، من طريق حفظ السنة، من طريق سؤال أهل العلم، من طريق المكاتبة ... إلى غير ذلك، لا يغفل ولا يتساهل.\nأما القسم الثاني: علوم الدنيا فيتعلم منها ما يعينه على كسب المعيشة، على سد فاقته حتى يقوم بما أوجب الله عليه، كيف يبيع، كيف يشتري، كيف يعمل ما يسبب الرزق الذي يقوم بحاله، لا يجلس في بيته وبس، لا بد يتعلم الشيء الذي يستعين به على طاعة ربه، أي علم .... ويباح يحصل به له الرزق الكافي الحمد لله، وإذا لم يعرف يسأل، يسأل أهل البصيرة من جيرانه ... من أقربائه ... من زملائه حتى يتعلم شيئًا ينتفع به بيع أو شراء، أو يؤجر نفسه، أو يحتطب أو يحش، كانوا في عهد النبي ﷺ يتعلمون، وكثير منهم يذهب إلى البرية، ويأتي بالحطب، يأتي بالحشيش يبيع، وينقذ نفسه وينقذ من تحت يده، وبعضهم يذهب ويحمل الحطب ونحوه، ويأتي ويبيع ويتصدق على الفقراء لما أمر النبي ﷺ بالصدقة صار كثير من الصحابة يحمل على ظهره لحاجات الناس، ثم يتصدق بالأجرة، فعلى المسلم أن يتعلم من الدنيا ما يعينه على سد خلته وحاجته في كسوة وطعام وسكن وغير ذلك، ويتعلم ما يعينه على القيام بحاجة أهله.\nفعليه علمان وعملان: علم الآخرة وهو الأهم وهو الأوجب أن يتعلم دينه، ويتفقه في دينه، ويعمل بما أوجب الله عليه، وينتهي عما حرم الله عليه، وعليه أيضًا علم ثاني وعمل ثاني وهو التعلم لما يحصل به الرزق والكفاف، والقيام بحاجة أهله من أمور الدنيا، ويعمل بذلك من كونه يحتطب، كونه يحتش، كونه يبيع، كونه يشتري، كونه يؤجر نفسه ... إلى غير هذا يتعلم الأسباب التي يحصل بها الرزق الكافي الذي يقوم بحاله، وحال من تحت يديه، والله ولي التوفيق.\nالمقدم: جزاكم الله عنا وعن المسلمين خير الجزاء سماحة الشيخ! تعلم العلوم الأخرى يا سماحة الشيخ الفيزياء.. الكيمياء وغيرها؟\nالشيخ: الشيء اللي ينفع الناس ولا فيه محذور يتعلمه، حساب.. فيزياء الشيء اللي فيه مصلحة للمسلمين يتعلمه، ولا حرج فيه، إذا لم يكن فيه محذور شرعًا، فالعلوم التي يستعان بها على أمر الدين أو الدنيا وليس فيها منكر لا بأس به سواء كانت من علوم الأولين، أو من علوم الآخرين، أي علم ينفع الناس وليس فيه ما يغضب الله، ليس فيه ربا، وليس فيه معصية، وليس فيه غش للناس إنما هي علوم تنفع، ويحتاجها بعض الناس، وليس فيها غش لأحد، ولا ظلم لأحد، ولا ركوب لمعصية لا حرج فيها والحمد لله.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16749/العلم-الواجب-على-المكلف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77801.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":17774,"question":"على بركة الله نبدأ هذا اللقاء بسؤال السائلة (ع. ع. د) من جازان، تقول سماحة الشيخ: تذكر بأنها لها أخ يبلغ من العمر خمسة عشر سنة تارك للصلاة، تقول السائلة: وإخواني لا يتعاملون معه إلا بالضرب، حتى يصلي مجبرًا، وعلى ذلك فهو شديد العقوق لوالديه، فما رأي سماحتكم في التعامل معه؟ وما هي الطريقة الصحيحة التي نتعامل معه مأجورين؟","title":"كيفية التعامل مع الأخ التارك للصلاة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفما دام الرجل قد بلغ خمسة عشر سنة فقد أحسن إخوانه في تأديبه وضربه حتى يستقيم حتى يصلي، .. رجل مكلف الآن، فالواجب أن يستتاب، يرفع أمره إلى المحكمة، فإن تاب واستقام وإلا استحق القتل.\nفالوصية أن تجتهدوا في توجيهه إلى الخير، وحثه على التوبة، وعلى إخوانه أن يجتهدوا في توجيهه إلى الخير ونصيحته وتأديبه؛ حتى يستقيم، حتى يصلي مع المسلمين في بيوت الله، وإلا فمن ترك الصلاة كفر واستحق القتل، فإن استقام وإلا يرفع أمره إلى المحكمة؛ حتى توجد فيه حكم الله جل وعلا، نسأل الله لنا وله الهداية، نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16755/كيفية-التعامل-مع-الاخ-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59626.mp3","categories":["الدعوة والدعاة"]},{"id":17954,"question":"هذا السائل عوض أحمد القرني يستفسر ويقول سماحة الشيخ: ما هي أفضل الكتب التي تنصحوننا باقتنائها في قصص الأنبياء وفي حياة الصحابة؟","title":"كتب ينصح باقتنائها","answer":"الجواب: الكتب كثيرة لكن من أفضل الكتب للاقتناء تفسير ابن كثير، وتفسير ابن جرير، وتفسير البغوي، والشوكاني هذه كلها كتب مفيدة نافعة.\nوفي الحديث: الصحيحان؛ صحيح البخاري وصحيح مسلم، منتقى الأخبار، بلوغ المرام، عمدة الحديث، جامع العلوم والحكم لابن رجب، هذه كتب مفيدة، فتح المجيد في العقيدة للشيخ عبد الرحمن بن حسن، كتاب التوحيد للشيخ محمد بن عبد الوهاب رحمه الله، كشف الشبهات للشيخ محمد رحمه الله، ثلاثة الأصول وشروط الصلاة، والقواعد الأربع للشيخ محمد رحمه الله كتاب صغير مفيد جدًا، والعقيدة الواسطية لشيخ الإسلام ابن تيمية رحمه الله، الترغيب والترهيب للحافظ المنذري، رياض الصالحين للنووي رحمه الله، هذه كتب مفيدة، التخويف من النار للحافظ ابن رجب، أهوال القبور للحافظ ابن رجب فيه مواعظ وتذكير. نعم.\nالمقدم: أحسن الله إليك وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16970/كتب-ينصح-باقتناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78016.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":17983,"question":"هل يجوز للإنسان المسلم الاشتغال بالعلوم الدنيوية، كالفيزياء، والرياضيات، والكيمياء، بحيث لا تشغله عن الصلاة، وعن ذكر الله؟","title":"حكم اشتغال المسلم بالعلوم الدنيوية","answer":"الجواب: لا حرج، الاشتغال بالعلوم الدنيوية التي قد ينتفع بها الإنسان؛ هذا لا حرج فيه. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16991/حكم-اشتغال-المسلم-بالعلوم-الدنيوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_729/nour_72905.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18168,"question":"رسالة وصلت إلى البرنامج من المستمع (ع. م. ع) يقول فيها: يزورنا أحيانًا بعض الناس التاركين للصلاة ولكن دائم النصيحة لهم والإلحاح عليهم ، ومع ذلك ترق قلوبهم ، فهل لهم حق الضيافة؟ وماذا علي أن أفعل نحوهم جزاكم الله خيرًا.","title":"حكم ضيافة تارك الصلاة المُصِرِّ على ذلك","answer":"الجواب: قد أحسنت في نصيحتهم وأمرهم بالمعروف وإرشادهم إلى الخير ، وإذا لم يتوبوا ولو يرعووا فالواجب هجرهم وعدم إجابة دعوتهم وعدم دعوتهم إلى بيتك ، وعدم اتخاذهم أصحابًا وأصدقاء ، معارفهم من الزيارة ؛ . وفور ترك الصلاة كفر بنص الرسول عليه الصلاة والسلام. والصحيح أنه كفر أكبر ، هذا صحيح من الصحيح  ، وخرج الإمام أحمد وأهل السنن الأربع بإسناد صحيح عن بريدة  عن النبي عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر . هؤلاء الذين عرفتهم بترك الصلاة وقد تكرر منك النصح لهم ، ثم لم يستجيبوا وفهمهم جديرون بالهجر والإنكار وإظهار البغضاء لهم حتى يرجعوا عن باطلهم ، وليس لهم حق الضيافة إذا جاء إليك ؛ لأنهم مرتدون بهذا العمل وقد نصحتهم وكررتهم عليهم ، وليسوا ضيوفًا بذلك ، هؤلاء وأرادوا ذلك أرادوا هذه الزيارة التي أنت تكرههم من أجل ما هم عليه من الباطل ، بخلاف الضيف الكافر الذي لم يقدم له نصح ولم يجر بينك وبينه مذاكرة في هذا الأمر ، فهذا حق الضيافة مع النصيحة. أما بالنسبة لك ، فهكذا عليك أن تشير إلى أن هذا لا يعني أن عليك أن تنكر عليه وأن تهجره حتى يتوب إلى الله ومعهروف ومعهروف عن المنكر ، كما قال عليه الصلاة والسلام: من دل على خير فله مثل أجر فاعله  وقد هجر النبي ، أقل من هذا ، فإن مالك  الأنصاري وصاحبيه لما تخلفوا عن غزوة تبوك وهم قادرون على المشاركة في الغزو وقد أبلغوا وعرفوا وجوب النفير فتخلفوا بدون عذر ، خمسين ليلة ، حتى تاب الله عليهم ، فكيف بحال من ترك الصلاة عمداً بغير عذر شرعي وبغير حق بلقيم التساهل والتهاون بأمرها وهو جدير بالهجر وجدير بالعداوة والبغضاء. \nوجلست تبجيل ، وجل مرة أخرى. : فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ  [التوبة: 5]. ثم قال: إن نهيت عن قتل المصلين  وثبت عنه عليه الصلاة والسلام قال: أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا وأني رسول الله ويقيموا الصلاة ويؤتوا الزكاة ، ورسول فعلوا ذلك عصموا مني دماءهم وأموالهم إلا بحق الإسلام وحسابهم على الله   متفق على صحته. والخلاصة: أن من ترك الصلاة عمدًا عدوانًا من غير جحد لوجوبها ؛ يبدو أنه كافرًا في أصح قولي العلماء وعلى أمر المسلمين استتابته ، أما إن كان جاحداً في أصح أقوال أهل العلم ، أما إن كان جاحداً لوجوبها لا يؤمن ؛ يجد كافه عند جميع العلماء ولو صلى متى جحد الوجوب كفر إجماعاً ، ولو فعلها نسأل الله العافية والسلامة. نعم.","link":"https://binbaz.org.sa/fatwas/17234/حكم-ضيافة-تارك-الصلاة-المصر-على-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_855/nour_85504.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":18174,"question":"نعود في هذه الحلقة إلى رسالة إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (ز. ع. م) أختنا عرضنا بعضًا من أسئلتها في حلقة مضت، وفي هذه الحلقة تسأل وتقول: إذا ذهبت إلى جيراني وتحدثت معهم بأن ما يفعلوه هذا حرام لا يزوروني بعد ذلك، هل يجب علي أن أزورهم مرة أخرى؟ أم أنقطع عنهم أيضًا؟ أفيدوني جزاكم الله كل خير.","title":"حكم السكوت عن المنكر بحجة عدم التنفير","answer":"الجواب: ينبغي لك أن تزوريهم، وأن تحسني إليهم بالنصيحة والتوجيه باللطف والكلام الطيب، والأسلوب الحسن عملاً بقول الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]، وقوله ﷺ: من رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه وذلك أضعف الإيمان وقوله جل وعلا في كتابه العظيم: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2]. فإذا قطعوك فلا تقطعيهم، أحسني إليهم أنت ولك الأجر، فأحسني وانصحي ووجهي إلى الخير، واعملي بقول النبي ﷺ: الدين النصيحة ولا يضرك عدم زيارتهم لك أنت تزورينهم وتنصحينهم ما دمت تستطيعين ذلك، ولك الأجر من الله  وأبشري بالخير العظيم والعاقبة الحميدة.","link":"https://binbaz.org.sa/fatwas/17220/حكم-السكوت-عن-المنكر-بحجة-عدم-التنفير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_854/nour_85405.mp3","categories":["الدعوة والدعاة"]},{"id":18303,"question":"ننتقل إلى رسالة أخرى وموضوع آخر، الرسالة من إحدى الأخوات المستمعات تقول (مريم . ن. ع. م) أختنا لها زميلات في الكلية تصفهن بأوصاف قاسية بعض الشيء سماحة الشيخ، وتعاني كثيرًا من مشاهدتها لأحوالهن، وترجو من سماحتكم التوجيه.","title":"واجب النصيحة بين المسلمات بعضهن لبعض","answer":"الجواب: عليك -أيها الأخت في الله- أن تنصحي أخواتك والطالبات اللاتي يدرسن عليك، وتسألي الله لهم التوفيق والهداية، هذا هو الذي بيدك، وقد ثبت عن رسول عليه الصلاة والسلام أنه قال: الدين النصيحة، لمن يا رسول الله؟ قال: لله ولكتابه ولرسوله ولأئمة المسلمين وعامتهم وهذا يشمل الرجال والنساء، والمدرسات والطالبات والمدرسين والطلبة فعليك أن تنصحي وتوجهي إلى الخير وإذا كان في يدك قدرة على تأديب من يستحق التأديب فافعلي كبنتك وطالباتك.. ونحو ذلك والله جل وعلا لا يكلف نفسًا إلا وسعها، ويقول سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. وإذا كان في الإمكان رفع أمر بعض البنات إلى أوليائهن ليقوموا بالتأديب والتوجيه والإلزام بالحق هذا كذلك من الأمر بالمعروف والنهي عن المنكر. فعليك أن تتقي الله وعليك أن تواصلي النصيحة والدعوة والتوجيه إلى الخير وأن تدعي المولى سبحانه لهن بالتوفيق في صلاتك وفي سائر أوقاتك لأن هذا مما ينفع الله به، دعوة المؤمن لأخيه ودعوة المؤمنة لأخيها أو أختها في الله بظهر الغيب هذا من أعظم الإحسان وهو من أسباب الإجابة. نعم.","link":"https://binbaz.org.sa/fatwas/17357/واجب-النصيحة-بين-المسلمات-بعضهن-لبعض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_858/nour_85802.mp3","categories":["الدعوة والدعاة","قضايا المرأة"]},{"id":18396,"question":"بسبب دراسة الطب تركت عائلتي -والدي- وأنا الآن أعيش في بيت أخي، وهذا الأخ هداه الله لا يحرص على أداء الصلاة، ولا أقول: إنه لا يصلي، فإنني أراه أحيانًا يؤديها، ولكن الملاحظ عليه بصفة عامة هو عدم الاهتمام بهذا الركن العظيم، علمًا بأنني لا أستطيع نصحه بسبب فارق السن ولأسباب أخرى.فهل يجوز لي أن أستمر في العيش معه لمواصلة الدراسة والتي بقي على تخرجي منها حوالي ثلاث سنوات إن شاء الله؟ أم علي أن أبحث عن سكن آخر كسكن الجامعة -مثلاً-؟أم علي أن أترك الدراسة وأعود إلى أهلي؟ أرجو إرشادي وإخراجي من حيرتي، وجزاكم الله خيرًا.","title":"كيفية التعامل مع الأخ الكبير التارك للصلاة","answer":"الجواب: إن الواجب عليك أن تنصحيه وإن كنت أصغر منه، فإن الله جل وعلا يقول: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]، هذا واجب الجميع، المؤمنين والمؤمنات، وليس في هذا فرق بين الكبير والصغير، فعليك أن تنصحي أخاك وأن تخوفيه من الله ؛ لأن الصلاة عمود الإسلام ومن تركها كفر، كما قال عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، خرجه الإمام أحمد وأهل السنن بإسناد صحيح، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة، خرجه الإمام مسلم في صحيحه، وقال أيضاً عليه الصلاة والسلام: رأس الأمر الإسلام وعموده الصلاة، وذروة سنامه الجهاد في سبيل الله، خرجه الإمام أحمد وغيره بإسناد صحيح عن معاذ . والأحاديث في هذا كثيرة، والقرآن الكريم فيه من ذلك الآيات الكثيرة، كقوله سبحانه: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238]، قوله : وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ [البقرة:43]، وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ [النور:56]، وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلاةَ وَيُؤْتُوا الزَّكَاةَ وَذَلِكَ دِينُ الْقَيِّمَةِ [البينة:5]، فعليك أن تنصحيه وأن تبيني له إنكارك عليه هذا العمل لعله يهتدي بأسبابك فيكن لك مثل أجوره. والرجل ينصح المرأة والمرأة تنصح الرجل وإن اختلفا في السن، ولاسيما هو أخوك فله حق عليك من جهة واجب الدين ومن جهة واجب الرحم، فإن استقام فالحمد لله، وإلا فنصيحتي لك أن لا تبقي عنده لئلا يضرك، ولئلا تبتلي بالتأسي به فيقسو قلبك، فنصيحتي لك أن تنتقلي إلى السكن الجامعي إذا تيسر ذلك وإلا فترك الدراسة، ولا تبقي عند رجل يتهاون بالصلاة ولا يرفع بها رأسًا، فإن هذا يضرك في دينك وربما يسبب لك شرًا عظيمًا وعاقبة وخيمة، نسأل الله لك التوفيق وحسن العاقبة ولأخيك الهداية. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/17491/كيفية-التعامل-مع-الاخ-الكبير-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_863/nour_86306.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":18398,"question":"هذا المستمع من اليمن صنعاء يقول يا سماحة الشيخ: هل يجوز الخروج لطلب العلم بدون إذن الوالدين، إذا كان الطالب لا يتمكن من تحصيل العلم في بلد الوالدين، علمًا بأن له إخوة قد يقومون بخدمة الوالدين؟ وجهونا في ضوء ذلك.","title":"حكم استئذان الوالدين في السفر لطلب العلم","answer":"الجواب: نعم، إذا كان هناك من يقوم بخدمتهما يخرج في طلب العلم يلزمه الخروج لطلب العلم والتفقه في الدين، أما إذا كانا في حاجة إليه وضرورة إليه فيبقى عندهما ويطلب العلم في البلد، يجمع بين المصلحتين. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17462/حكم-استىذان-الوالدين-في-السفر-لطلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91330.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18418,"question":"سماحة الشيخ! هذا السائل عيظة يقول في هذا  في بعض المساجد، وخاصة بعد صلاة العصر يقرأ الإمام أو أحد الإخوة عدة أحاديث من رياض الصالحين في كل ليلة، فهل هذا العمل من البدعة؟","title":"حكم إقامة الدروس العلمية في المساجد بعد الصلوات","answer":"الجواب: ليس هذا بدعة، هذا من التذكير والتعليم؛ لأن هذا من باب تعليم الجماعة وإرشادهم إلى ما ينبغي لهم، الدروس في المسجد بعد العصر، أو بعد العشاء، أو في أي وقت لتعليم الجماعة وتعليم الحاضرين هذا كله مطلوب، نعم، هذا من باب التعليم. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17500/حكم-اقامة-الدروس-العلمية-في-المساجد-بعد-الصلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91338.mp3","categories":["الدعوة والدعاة"]},{"id":18644,"question":"رسالة وصلت إلى البرنامج من المستمع: (س. ع. د) أخونا قضيته في الواقع أيضًا نهايتها يطلب من سماحة الشيخ إذا أمكن أن ترسل له بعض الكتب، كتفسير ابن كثير، وفتح الباري، وصحيح مسلم، والفتاوى الكبرى، إذا أمكن ذلك شيخ عبد العزيز.","title":"طلب إرسال بعض الكتب","answer":"الجواب: لا مانع من إرسال الكتب بعد أن ترسل كتابًا -رسالة منك إليّ مصحوبة بمؤهلاتك- وبعد هذا ننظر في الموضوع، هل مؤهلاته موجودة الآن مؤهلاته؟ المقدم: لم يرفق شيء. الشيخ: لا بد من إرفاق المؤهلات، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17759/طلب-ارسال-بعض-الكتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_919/nour_91904.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18714,"question":"أيضًا بقي لها سؤال واحد شيخ عبد العزيز، تشكو فيه من شباب تعرفهم، تقول: إنهم عصاة، ولا يصلون، وتذكر أيضًا بعض سيئاتهم، وهم محارمها، ويسكنون معها في نفس المنزل، وترجو منكم توجيهها كيف تتصرف؟","title":"كيف تعامل المرأة محارمها التاركين للصلاة؟","answer":"الجواب: الواجب نصيحتهم، وتحذيرهم مما حرم الله، وإخبارهم بأن الصلاة عمود الإسلام، وأن تركها كفر أكبر في أصح قولي العلماء، وإن لم يجحدوا وجوبها، مع وجوب التحرز منهم، والحذر من شرهم؛ لأن من عصى الله، وترك الصلاة لا يؤمن شره. فنوصيك -أيتها الأخت في الله- أن تحذري شرهم، وإذا تيسر لك فراقهم، والانتقال عنهم إلى بيت آخر، إلى أمك، أو أخ صالح، أو عم صالح، أو خال صالح، فهو أسلم لك من هؤلاء، فإن كنت مضطرة إلى البقاء معهم، فاحذريهم، واحذري شرهم، مع دوام النصيحة والتوجيه إلى الخير، وتخويفهم من الله  واستعيني على ذلك أيضًا بأهل الخير من أقاربك حتى ينصحوهم، نسأل الله لنا ولهم الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17780/كيف-تعامل-المراة-محارمها-التاركين-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_920/nour_92002.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة","قضايا المرأة"]},{"id":18735,"question":"السائل والذي أرسل بمجموعة من الأسئلة صالح سعد من اليمن، يقول في هذا  كثيرًا سماحة الشيخ ما نسمع عن العقيدة الواسطية، فلا ندري ما معنى الواسطية، فهل يعني بذلك: العقيدة الصحيحة، أم ماذا يعني؟وجهونا في ضوء سؤالنا فنحن مجموعة من طلاب العلم.","title":"معنى \"العقيدة الواسطية\"","answer":"الجواب: العقيدة الواسطية كتاب ألفه أبو العباس أحمد بن عبد الحليم بن عبد السلام ابن تيمية الحراني، الملقب بشيخ الإسلام ابن تيمية، والملقب تقي الدين، المولود سنة إحدى وستين وستمائة، والمتوفى سنة ثمان وعشرين وسبعمائة، وهو من الأئمة المجتهدين، ومن أهل السنة والجماعة، بل هو من أئمة أهل السنة والجماعة -رحمه الله- وله المؤلفات الكثيرة منها: منهاج السنة في الرد على المعتزلة والرافضة، ومنها: كتابه اقتضاء الصراط المستقيم مخالفة أصحاب الجحيم، ومنها: كتابه العقيدة الواسطية. سميت الواسطية؛ لأنه كتبها إلى أهل واسط في العراق، كتبها إليهم، فقيل لها: الواسطية؛ لأنه كتبها إلى جماعة سألوه من أهل واسط، فقيل لها: الواسطية، وله رسالة أخرى في العقيدة يقال لها: الحموية، كتبها إلى أهل حماة في الشام، وله رسالة أخرى ثالثة في الصفات تسمى التدمرية، كتبها إلى أهل تدمر في بلاد الشام. هذا أسباب التسمية، واسطية؛ لأن العقيدة كتبت إلى أهل واسط، وحموية؛ عقيدة كتبت إلى أهل حماة، وتدمرية عقيدة كتبت إلى أهل تدمر، وهي كتب ثلاثة عظيمة في عقيدة أهل السنة والجماعة مفيدة، نوصي بقراءتها، والاستفادة منها، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17862/معنى-العقيدة-الواسطية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_789/nour_78913.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18738,"question":"تقول أختنا: إنها تعرف إحدى النساء، واكتشفت أنها لا تصلي إلا في رمضان، وتسأل: هل تستمر معها كصديقة لها، أو تقاطعها؟","title":"حكم صحبة تارك الصلاة","answer":"الجواب: الواجب نصيحتها، وتعليمها ما ينفعها، وإفهامها أن الصلاة فرض دائمًا، في رمضان وفي غيره، وأنها عمود الإسلام، وأنها واجبة على المرأة المكلفة أن تصليها، وأن تحافظ عليها كالرجل، في رمضان أو في غيره، وأن تركها للصلاة في غير رمضان كفر أكبر -نعوذ بالله- كما قال النبي -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح، وقال -عليه الصلاة والسلام-: رأس الأمر الإسلام، وعموده الصلاة، وذروة سنامه الجهاد في سبيل الله. فالصلاة عمود الإسلام، وأعظم أركانه بعد الشهادتين، فالتي لا تصلي كالرجل الذي لا يصلي سواءً بسواء، كلاهما كافر، حتى يتوبا إلى الله، ويرجعا من عملهما السيئ، فإن هداها الله، واستجابت لك؛ وتابت إلى الله، فلا مانع من اتخاذها صديقة، والبقاء على صحبتها. أما إن أصرت على ترك الصلاة فهي كافرة؛ ويجب عليك أن تعاديها في الله، وأن تقاطعيها، وأن لا تقربيها بالكلية، لا تجيبي دعوتها، ولا تدعيها إلى زيارتك، ولو زارتك لا تقابليها، ولا تسلمي عليها، حتى ترجع عما هي عليه من الباطل، وحتى تتوب إلى الله ؛ لأن عملها عظيم، عظيم النكارة، عظيم الشر، عملها كفر -نسأل الله العافية والسلامة- والمسلم واجبه النصيحة لإخوانه في الله، وأخواته في الله، فإذا كانت لا تقبل النصيحة، ولا تنتفع بالنصيحة؛ وجبت المقاطعة، نسأل الله لنا ولها الهداية، ونسأل الله لك التوفيق في نصيحتها. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/17881/حكم-صحبة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_875/nour_87508.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":18739,"question":"أخت تقول: المرسلة: (ن. م) تسأل سؤالين، في سؤالها الأول تقول: إنني ممن يستمعون لبرنامجكم هذا والحمد لله، وأقوم بتسجيل كل حلقة على شريط؛ لكي يكون مرجعًا لي، ولمن يريد حل مشكلة قد تعرض لها، أو حكم يتمنوه، فهل هذا العمل أستمر عليه أم لا؟ علمًا بأنني أنظم تسجيل الحلقات؛ لكي لا يكون اختلاط في الحروف.","title":"الاهتمام بحلقات نور على الدرب وتسجيلها","answer":"الجواب:   هذا عمل طيب، وأنت مأجورة، شكر الله لك سعيك؛ لأن هذا من باب تحصيل العلم، ومن باب حفظ العلم لك ولغيرك، تسجيل مثل هذه البرامج فيه خير كثير، وفيه فائدة كثيرة، فاستمري على هذا، وأبشري بالخير. \nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17879/الاهتمام-بحلقات-نور-على-الدرب-وتسجيلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_875/nour_87507.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18753,"question":"يقول سماحة الشيخ: ما رأي سماحتكم في الوعظ عند القبور؟","title":"حكم الوعظ عند القبور","answer":"الجواب: الوعظ عند القبور مستحب إذا تيسر ذلك؛ لأن الرسول ﷺ وعظ عند القبور، ثبت من حديث علي  ومن حديث البراء بن عازب أن النبي وعظهم عند القبور -عليه الصلاة والسلام- وعظ الحاضرين عند القبور، فإذا حضر بعض أهل العلم ووعظ الناس عند القبر، عند انتظارهم الدفن، أو عند وقوفهم للدفن ذكرهم بالله حسن كله طيب.","link":"https://binbaz.org.sa/fatwas/17878/حكم-الوعظ-عند-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79007.mp3","categories":["أحكام المقابر","الدعوة والدعاة"]},{"id":18775,"question":"سماحة الشيخ يستفسر عن كتاب الدعاء المستجاب في الحديث والكتاب يقول: ورد فيه مجموعة من الأحاديث، وأورد هذا الحديث الذي ذكرتم عنه، ويقول أيضًا ورد فيه هذا الحديث قال النبي ﷺ: من قلم أظافره يوم الجمعة وقي من السوء مثلها","title":"تقييم كتاب الدعاء المستجاب","answer":"الجواب: هذا كتاب لا يعتمد عليه؛ لأنه يروي الغث والسمين، لا يعتمد عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17901/تقييم-كتاب-الدعاء-المستجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79107.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18806,"question":"ننتقل إلى رسالة أخرى، ومواضع أخرى سماحة الشيخ، الرسالة وصلت إلى البرنامج من الأخ (ر. أ. ف) من العراق، أخونا له مجموعة من الأسئلة، من بينها سؤال يقول: سمعت: أن الساكت عن الحق شيطان أخرس، هل هذا صحيح؟","title":"معنى: (الساكت عن الحق شيطان أخرس)","answer":"الجواب: نعم، هذا قاله بعض السلف، ليس حديثًا عن النبي ﷺ، إنما قاله بعض العلماء، قالوا: \"الساكت عن الحق شيطان أخرس، والناطق بالباطل شيطان ناطق\"، فالذي يقول الباطل، ويدعو إلى الباطل؛ هذا من الشياطين الناطقين. والذي يسكت عن الحق مع القدرة، ولا يأمر بالمعروف، ولا ينهى عن المنكر، ولا يغير ما يجب تغييره ويسكت وهو يستطيع أن يتكلم؛ هذا يقال له: شيطان أخرس، من شياطين الإنس يعني؛ لأن الواجب على المؤمن إنكار الباطل والدعوة إلى المعروف، وإذا استطاع هذا وجب عليه، كما قال الله -جل وعلا-: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَأُوْلَئِكَ هُمُ الْمُفْلِحُونَ [آل عمران:104] وقال سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]. وقال النبي ﷺ: إن الناس إذا رأوا المنكر فلم يغيروه؛ أوشك أن يعمهم الله بعقابه وقال -عليه الصلاة والسلام-: من رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه؛ وذلك أضعف الإيمان خرجه الإمام مسلم في صحيحه. هذا يبين لنا وجوب إنكار المنكر على حسب الطاقة: باليد، ثم اللسان، ثم القلب، فالذي يسكت عن إنكار المنكر، وهو قادر ليس له مانع؛ هذا هو الشيطان الأخرس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17956/معنى-الساكت-عن-الحق-شيطان-اخرس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_877/nour_87706.mp3","categories":["الدعوة والدعاة"]},{"id":18819,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول: أخوكم في الله (م. م. ع) أخونا يسأل ويقول: إذا كان للإنسان المسلم أخ أو أخت تاركة للصلاة بالكلية، وقدم ما يلزم من النصح، ولكن دون جدوى، فهل يجوز له أن يلجأ إلى أسلوب المقاطعة؟ وما هو حدود معاملة تارك الصلاة لو كان ذا قرابة في ديننا الحنيف؟أفيدوني، جزاكم الله خيرًا.","title":"كيفية التعامل مع الأقارب التاركين للصلاة","answer":"الجواب: إذا ترك الأخ أو الأخت أو غيرهما من الأقارب الصلاة، فالواجب النصيحة والتوجيه والصبر على ذلك؛ فإن أجاب من ترك الصلاة وهداه الله وتاب، فالحمد لله، وإلا وجبت مقاطعته وهجره، فلا تستجاب دعوته من وليمة ولا غيرها، ولا يدعى لوليمة، ولا يسلم عليه، ولا يرد عليه السلام، حتى يتوب إلى الله؛ لأن جريمته عظيمة، وهي ردة عن الإسلام في أصح قولي العلماء. ترك الصلاة، والتعمد لذلك ردة عن الإسلام؛ لقوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح؛ ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر ولأحاديث أخرى جاءت في المعنى، والله يقول سبحانه عن أهل النار: مَا سَلَكَكُمْ فِي سَقَرَ  ۝  قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ [المدثر:42-43]، فبدؤوا أعمال الخبث التي دخلوا بها النار بدؤوها بترك الصلاة، نسأل الله العافية. فالواجب على المؤمن مع أقربائه إذا تركوا الصلاة أن ينصحهم، وأن يوجههم إلى الخير، وأن يوجه أيضًا بعض إخوانه الطيبين إلى أن ينصحوهم ويوجهوهم؛ لأن الله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]. فالتعاون على البر والتقوى من أهم المهمات، فإن هداهم الله سبحانه وتابوا، فالحمد لله، وإلا وجبت مقاطعتهم وهجرتهم حتى يستقيموا ويتوبوا، هذا هو الواجب على المسلمين إلا الوالدين، فالوالدان لهما شأن آخر؛ لأن الله قال سبحانه في حق الوالدين الكافرين، قال: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا[لقمان:15] فالوالدن لهما حق عظيم، ولو كانا كافرين، يصبر عليهما، ويحسن إليهما، ويرفق بهما، ويدعوهما إلى الله، لعل الله يهديهما بأسبابه، ولا يعجل، ولو استمرا في الكفر عليه أن ينصحهما، وأن يوجههما إلى الخير، ويستعين على ذلك بمن يرى من أقاربه وإخوانه وأحبابه لعل الله يهديهما بأسبابه. فلو استمرا على الكفر لم يقطع النصيحة، ولم يقطع الإحسان، بل يستمر في نصيحته وإحسانه حتى يسلما، أو يموتا، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17952/كيفية-التعامل-مع-الاقارب-التاركين-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_921/nour_92106.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":18851,"question":"يسأل أخونا أيضًا ويقول: هل كتاب رياض السامعين وبستان الواعظين صحيح، ذلكم أني رأيت فيه كثيرًا من الترهيب الشديد؟","title":"تقييم كتاب رياض السامعين وبستان الواعظين","answer":"الجواب: لست أعرف الكتاب المذكور، ليس عندي علم بالكتاب المذكور، ولكن يغني عنه رياض الصالحين؛ فإنه كتاب جليل، كتاب طيب، وأغلبه صحيح، فالاستفادة من رياض الصالحين أولى؛ لأنه كتاب معروف عند أهل العلم، وهو كتاب مفيد، فينبغي الاعتياض عن هذا برياض الصالحين. أما هذا الكتاب فلا أعرفه، فإذا تفضل السائل بإرسال هذا الكتاب، وإلا سوف نسأل عنه -إن شاء الله- وبعد ذلك نتكلم عنه -إن شاء الله- في حلقة تأتي -إن شاء الله- وسنعمد -إن شاء الله- من يلتمسه؛ حتى نتكلم عنه بما يقتضيه الحال، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18013/تقييم-كتاب-رياض-السامعين-وبستان-الواعظين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_879/nour_87907.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18890,"question":"يسأل سماحتكم مجموعة من الكتب، أولًا : الكتب التي تبحث في العقيدة.","title":"ما الكتب التي ينصح بقراءتها في العقيدة؟","answer":"الجواب: ... فتح المجيد للشيخ عبد الرحمن بن حسن، تيسير العزيز الحميد للشيخ سليمان بن عبد الله، التدمرية لشيخ الإسلام ابن تيمية، الحموية لشيخ الإسلام ابن تيمية أيضًا، العقيدة الواسطية له أيضًا، زاد المعاد لابن القيم -رحمه الله- إغاثة اللهفان لابن القيم -رحمه الله- الصواعق المرسلة لابن القيم -رحمه الله- اجتماع الجيوش الإسلامية لابن القيم -رحمه الله- كتاب التوحيد للشيخ محمد بن عبد الوهاب، ثلاثة الأصول، كشف الشبهات له أيضًا -رحمه الله- كل هذه كتب عظيمة مفيدة. الطحاوية وشرحها لابن أبي العز، كلها طيبة في العقيدة، وأعظم ذلك وأكبرها القرآن العظيم، هو أعظم وأكبر، وهو أصدق كتاب، وأعظم كتاب، كتاب الله القرآن، هو كتاب عقيدة، وكتاب أحكام، فنوصي كل مسلم ومسلمة بالعناية بالقرآن، والإكثار من تلاوته، وتدبر معانيه، ففيه العلم العظيم بالعقيدة والأحكام الشرعية. وهكذا أحاديث الرسول ﷺ كتب الحديث الشريف الصحيحين: البخاري ومسلم، مثل رياض الصالحين، منتقى الأخبار لابن تيمية، بلوغ المرام للحافظ ابن حجر، كتب جيدة عظيمة في الحديث، عمدة الحديث للشيخ: عبد الغني بن عبد الواحد المقدسي، كتاب عظيم، نعم. المقدم: جزاكم الله خيرًا، أيضًا يسأل سماحتكم عناوين لبعض كتب الفقه. الشيخ: كتب الفقه كثيرة، لكن من أفضلها، كتاب المغني للموفق عبد الله بن قدامة، والمجموع للنووي -رحمه الله-، والمقنع للموفق -رحمه الله- عبد الله بن قدامة، كشاف القناع والمنتهى للحنابلة، شرح الزاد الروض المربع للحنابلة، وحاشيته لابن أبي القاسم، كل هذه كتب مفيدة، نعم. المقدم: جزاكم الله خيرًا. الحديث؟ الجواب: تقدم بيانه، نعم. المقدم: السيرة؟ الشيخ: سيرة ابن إسحاق، سيرة ابن هشام، زاد المعاد لابن القيم، كلها فيها السيرة النبوية، كتاب الشيخ عبد الله بن محمد بن عبد الوهاب السيرة النبوية، وكتاب الشيخ محمد -رحمه الله- أيضاً، السيرة النبوية كلها مطبوعة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18033/ما-الكتب-التي-ينصح-بقراءتها-في-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73620.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18904,"question":"إحدى الأخوات المستمعات بعثت برسالة تقول فيها: إنني امرأة مسلمة، ومن بلد عربي، مقيمة بالمملكة في قرية من قراها، وإنني متحجبة، وأقضي فرائضي على أكمل وجه، ولله الحمد، يوجد لدينا رجل يسكن جارنا، وفي نفس المصلحة التي يشتغل فيها زوجي، وهو من نفس البلد الذي نحن منه، وجنسيتنا واحدة، ولكنه يدين بـالمسيحية، وسؤالي:إن والدته حضرت زيارة للمملكة، وتريد أن تزور ابنها من المنطقة التي نحن فيها، علمًا بأنه يسكن عازبًا مع مجموعة من الرجال فقط، وقال لزوجي: إنه يريد أن يجيء بها في بيتنا لمدة أسبوع، وزوجي لا يدري ماذا يقول له؛ لأنه لا يوجد سوى نحن من بلده في هذه المنطقة، وإنه محرج أن يقول له: لا، هل نكرمها باعتبارها ضيفة ولأول مرة تحضر لدينا؟وهل يجوز لي أن أشاركها في الأكل والشرب، وأطبخ لها إذا كان ذلك في نهار رمضان وأنا صائمة، أم ماذا أفعل؟إنني في حيرة من أمري، أفيدوني جزاكم الله خيرًا، أختكم في الله: (ع. ع. س).","title":"حكم استضافة المسلم للكافر في بيته","answer":"الجواب: المشروع في هذا إكرام الضيف، ودعوته إلى الله، وتعليمه الإسلام؛ لعل الله يهديه بأسبابكم، فإذا جاءت المرأة فلعل دعوتها، ودعوة ابنها من أسباب هدايتها، فإذا وصلت إليكم، فأكرموها؛ لأنها ضيف، وادعوها للإسلام، ورغبوها في الخير، ورغبوا ولدها في الخير؛ لعل الله أن يهديها ويهدي ولدها بأسبابكم. أما في حال رمضان فلا، لا تعينوها على هذا، بل قدموا لها الشيء الذي تحتاجه، وهي تخدم نفسها، وعليك أن تتعذري لها بأنك لا تستطيعين أن تخدميها بما يخالف شرع الله؛ لأن الواجب على الكافر الدخول في الإسلام، وهو مخاطب بفروع الإسلام، والصلاة والصيام من فروع الإسلام، فليس لك أن تقدمي لها الغداء أو القهوة أو الشاي، بل هي تخدم نفسها في هذا، وتعتذري بأن هذا هو الذي عليك، يكون عندها طعامها وعندها المطبخ، وعندها.. فإذا كان زيارتها ومجيئها في رمضان؛ فهي تخدم نفسها بالشيء الذي تريده، أما أنت فلا، لا تقدمي لها الشيء الذي معناه الأكل أو الشرب، أما إن كان في غير رمضان فالأمر واسع، ولكن يجب أن تنصحوا من عنده ولدها أن يبعده إلى بلاده، وألا يستخدمه؛ لأن الرسول ﷺ أمر بإخراج الكفار من هذه الجزيرة، ونص على النصارى أيضًا بإخراج اليهود والنصارى من هذه الجزيرة؛ لأنهم كفار مثل بقية المشركين، وإن كانوا أهل جزية، لكنهم كلهم كفار. فالواجب إخراجهم من هذه الجزيرة، وعدم استقدامهم لها، لا في حال زراعة، ولا بناء، ولا طب، ولا غير ذلك، إلا عند الضرورة القصوى من جهة ولاة الأمور، إذا رأوا ولاة الأمور ضرورة لبعض الكفار لمصلحة المسلمين في طب أو نحوه، فهذا شيء خاص يتعلق بولاة الأمور، مع مراعاة المصلحة العامة، ومع مراعاة التقليل من ذلك، والحرص على الاستغناء عنهم بالمسلمين، أما الأفراد والعامة وجميع الناس؛ فالواجب عليهم ألا يستقدموا الكفرة، وأن يعتاضوا عنهم بالمسلمين؛ تنفيذًا لأمر النبي ﷺ في إخراجهم من هذه الجزيرة، وألا يجتمع فيها دينان. المقدم: إذًا فليرحبوا بهذه الضيفة؛ وليدعوها إلى الإسلام كما تفضلتم؟ الشيخ: نعم، يحسنون إليها، ويدعوها إلى الإسلام، وولدها أيضًا، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18054/حكم-استضافة-المسلم-للكافر-في-بيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_881/nour_88106.mp3","categories":["الدعوة والدعاة"]},{"id":18915,"question":"هذه الأخت السائلة، أرسلت بمجموعة من الأسئلة تقول: سماحة الشيخ، أرجو إرشادي إلى بعض الكتب التي تنصحون بقراءتها في الأحاديث القدسية.","title":"بعض الكتب التي ينصح بقراءتها في الحديث","answer":"الجواب: ننصحك بالعناية بالقرآن، والإكثار من قراءة القرآن، فهو كتاب الله، فيه الهدى والنور، فنوصيك وغيرك بالإكثار من قراءة القرآن، والكتب الصحيحة مثل كتاب رياض الصالحين، وبلوغ المرام، وعمدة الحديث، ومنتقى الأخبار، تستفيدون منها، هذه كتب حديث أغلبها جيد وصحيح، فاستفيدوا منها، ولكن عليكم بالقرآن أكثر، أكثروا من قراءة القرآن بالتدبر والتعقل ليلًا ونهارًا، وإذا راجعتم كتب الحديث كرياض الصالحين، منتقى الأخبار، بلوغ المرام، عمدة الحديث، صحيح البخاري، صحيح مسلم، هذا فيه خير عظيم، فائدة كبيرة. المقدم: أحسن الله إليكم، وبارك فيكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18093/بعض-الكتب-التي-ينصح-بقراءتها-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88220.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18953,"question":"يقول بالنسبة للكتب التي تنصحوننا في قراءتها في هذه المجالس سماحة الشيخ؟","title":"ما الكتب التي تنصحون بقراءتها؟","answer":"الجواب: أعظم كتاب القرآن أنصحك بالقرآن العظيم، ننصح جميع المسلمين بالعناية بالقرآن، والإكثار من تلاوته، فهو كتاب الله فيه الهدى والنور، كما قال سبحانه: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ[الإسراء:9] قال تعالى: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ[فصلت:44] وقال سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ[ص:29] قال سبحانه: أَفَلا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا[محمد:24]. فنوصي جميع المسلمين رجالًا ونساءً نوصيهم بالقرآن، نوصيهم بالإكثار من تلاوته، وتدبر معانيه، وحفظه، أو ما تيسر منه، فهو كتاب الله فيه الهدى والنور، فيه الدعوة إلى مكارم الأخلاق، ومحاسن الأعمال، فيه الدعوة إلى فعل ما أوجب الله، وترك ما حرم الله، فيه قصص الأنبياء والمرسلين، فيه قصص الأخيار حتى يتأسى بهم، فيه قصص الأشرار حتى تجتنب أعمالهم. ثم كتب الحديث الشريف كالصحيحين للبخاري، ومسلم، السنن الأربعة لمن كان عنده علم يقرأ فيهما. وأما المبتدئ -طالب العلم المبتدئ- فنوصيه بمثل المختصرات التي يستطيع حفظها مثل بلوغ المرام، مثل كتاب التوحيد، العقيدة الواسطية، ثلاثة الأصول، الأربع القواعد للشيخ محمد بن عبد الوهاب -رحمه الله- كتاب التوحيد، وثلاثة الأصول، والقواعد الأربع للشيخ محمد بن عبد الوهاب -رحمه الله- كشف الشبهات كذلك له -رحمه الله-، العقيدة الواسطية لشيخ الإسلام ابن تيمية، بلوغ المرام للحافظ ابن حجر، عمدة الحديث للحافظ الشيخ عبد الغني بن سرور المقدسي، هذه كتب ينبغي حفظها، تفيد تنفع؛ لأنها كتب مهمة، نعم. المقدم: أحسن الله إليكم سماحة الشيخ على هذا التوجيه الطيب المبارك.","link":"https://binbaz.org.sa/fatwas/18144/ما-الكتب-التي-تنصحون-بقراءتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_792/nour_79210.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18964,"question":"السائلة تقول: في حديث ما معناه بأن: \"من طلب العلم لغير وجه الله؛ فإنه يتبوأ مقعده من النار\" تقول: حيث أنني صممت أن أكمل دراستي الجامعية، وكان ذلك أيضًا رغبة والدي، فكانت الأفكار تراودني في أثناء الدراسة أن لا أكمل ذلك، ولكنني عزمت بشدة أن أكمل لأحقق رغبة والدي، وأجلب له الفرح بذلك، فهل ينطبق علي حكم الحديث؟","title":"حكم طلب العلم لغير وجه الله","answer":"الجواب: عليك التوبة إلى الله، الواجب طلب العلم لابتغاء وجه الله، هذا هو الواجب، ولا ينبغي طلب العلم للوظيفة أو لإرضاء فلان أو فلان، بل الواجب أن يكون طلب العلم ابتغاء وجه الله، يقول النبي ﷺ: ثلاثة هم أول من تسعر بهم النار: رجل تعلم العلم ليقال له: عالم، وتفقه ليقال: فقيه نسأل الله العافية. فالمقصود: أن الواجب على المؤمن في عباداته كلها، ومنها طلب العلم أن يتعلم ابتغاء وجه الله؛ ليعرف دينه؛ ليتبصر في دينه؛ ليعرف ما أوجب الله عليه، وما حرم الله عليه، والوظائف تبع، لكن المقصود تعلمه ليتفقه في الدين؛ ليعرف ما شرع الله له؛ ليعلم ما أوجب الله عليه، وما حرم الله عليه حتى يكون على بصيرة في دينه. المقدم: سماحة الشيخ، بماذا توجهون طلاب العلم وطالبات العلم للتزود من العلم الشرعي؟ الشيخ: نصيحتي للجميع العناية بطلب العلم الشرعي، والتفقه في القرآن والسنة، والسؤال عما أشكل، وإذا تعلم مع هذا أمورًا أخرى في أمور الدنيا فلا بأس، لكن ليهتم بالتفقه في الدين يقول النبي ﷺ: من يرد الله به خيرًا يفقهه في الدين، ويقول ﷺ: من سلك طريقًا يلتمس فيه علمًا سهل الله له به طريقًا إلى الجنة نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/18104/حكم-طلب-العلم-لغير-وجه-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88225.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":18980,"question":"سماحة الشيخ هذه الفتاوى التي بدأت تنتشر في الصحف والمجلات، سواءً كانت الصحف من الداخل، أو الخارج قد يعتمد عليها بعض المسلمين، هل لكم من توجيه؟","title":"التحذير من الفتاوى التي لا تستند إلى دليل","answer":"الجواب: الواجب عدم الاعتماد على الفتاوى التي تنشر في الصحف، أو تذاع في الإذاعة، أو في التلفاز، حتى يتأكد المؤمن ممن نسبت إليه، فإذا تأكد منه وهو أهل للفتوى فلا بأس؛ لأن كثيرًا من الناس قد يكذب الآن، وقد يلبس عليه، فإذا سمع المؤمن أو المؤمنة فتوى، فالواجب أن يتثبت في ذلك، وألا يجزم بذلك إلا إذا سمعها من صوت المفتي، وهو يعرف صوته، وإلا فلا بد من سؤال المفتي بالهاتف أو بالكتابة حتى يتحقق أنها صدرت منه. وقد علمنا أن كثيرًا من الناس يكذبون علي وعلى غيري في فتاوى كثيرة، كما كذبوا على النبي ﷺ وعلى الصحابة، فالذي وقع في الأول من الكذب على النبي ﷺ وعلى الصحابة لا يستغرب أن يقع في وقتنا هذا من باب أولى.  فالواجب في مثل هذا التثبت، وعدم تصديق من يقول: قال فلان، وقال فلان، وأفتى فلان، وأفتى فلان. وهكذا ما ينشر في الصحف قد يحرف، وقد لا يكون على وجهه، وقد يكون مكذوبًا، هذا كله يوجب على المؤمن والمؤمنة التثبت فيما يذاع وينشر من الفتاوى، وفيما ينقله الناس، حتى يتأكد من وقف على الفتوى من مشافهة صاحبها وسؤاله، هل صدرت منه هذه الفتوى، سواء كانت مشافهة أو بالكتابة أو بالهاتف، حتى يستيقن الأمر وحتى يحتاط لدينه، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.\nإذًا: إذا كانت الفتوى بصوت المفتي فهي المعتمدة؟ الشيخ: نعم يزول الإشكال، إذا سمع صوته يفهمه جيدًا، يزول الإشكال، أما إذا اشتبه عليه صوته فليسأل أيضًا. المقدم: إذًا توجيهكم بالنسبة لتلكم الفتاوى في الصحف والمجلات المتعددة. الشيخ: مثلما تقدم. المقدم: وهو؟ الشيخ: الواجب ألا يعتمد عليها إلا بعد التثبت من صدورها ممن أفتى بها، وبعد العلم بأنه أهل لذلك. المقدم: أيوه، إذًا يجب معرفة من هو المفتي. الشيخ: نعم. المقدم: فإن كان أهلًا للفتوى اعتمدت فتواه، وإن لم يكن فالأمر غير ذلك. الشيخ: بعد سؤاله، والتأكد أنها صدرت منه. المقدم: بارك الله فيكم، وجزاكم الله خيرًا. الشيخ: وإياكم.","link":"https://binbaz.org.sa/fatwas/18128/التحذير-من-الفتاوى-التي-لا-تستند-الى-دليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_925/nour_92503.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19023,"question":"رسالة من أحد المستمعين فيها بعض الطول فهمت منها شيخ عبد العزيز أنه كثير الخجل، ولا يستطيع أن يؤم الناس رغم أنه في بعض الحالات يكون الأقرأ في فريضة من الفرائض، وإذا وجه إليه سؤال يرتعش كما يقول، ويرجو من سماحتكم التوجيه والنصح.","title":"توجيه لمن يمنعه الخجل من إمامة الناس وتعليمهم","answer":"الجواب: الواجب على المؤمن وعلى طالب العلم أن تكون عنده الهمة العالية، والقوة والنشاط في إبلاغ الخير، والدعوة إلى الخير، وتعليم الجاهل، وإرشاد الضال، والأمر بالمعروف والنهي عن المنكر، هذا هو الواجب وهذا هو الذي ينبغي للمؤمن، يقول النبي ﷺ: المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف وفي كلٍ خير لكن المؤمن القوي الذي يعلم الناس ويصلي بهم إذا احتاجوا ويقرأ عليهم العلم ويرشدهم ويأمرهم بالمعروف وينهى عن المنكر أفضل من المؤمن الضعيف العاجز الذي لا يستطيع أن يبذل ما ينفعهم. ووصيتي لهذا السائل أن يتقي الله وأن تكون همته عالية، وأن يؤم الناس إذا كان أفضل الموجودين ورغبوا إليه أن يؤم الناس وليبادر بذلك، وأن يظهر علمه إن كان عنده علم، وأن يفتي السائل بما عنده من العلم عن الله وعن رسوله وألا يخجل، فليس هذا محل خجل، الخجل للجاهل والفاعل المعصية. أما من يعلم الناس الخير ويفتيهم بالعلم الشرعي ويسعى في مصالحهم، فلا يليق به أن يخجل ولا ينبغي له أن يجبن، ولا يليق به أن يتأخر، بل ينبغي له أن يتقدم، وأن يكون في المقدمة في كل شيء، حتى ينفع الناس ويرشدهم ويكون إمامًا في الخير، والله المستعان. نعم. المقدم: الله المستعان، جزاكم الله خيرًا. سماحة الشيخ! في الختام: أتوجه لكم بالشكر الجزيل بعد شكر الله  على تفضلكم بإجابة السادة المستمعين، وآمل أن يتجدد اللقاء وأنتم على خير. الشيخ: نسأل الله ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/18193/توجيه-لمن-يمنعه-الخجل-من-امامة-الناس-وتعليمهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_927/nour_92709.mp3","categories":["الدعوة والدعاة"]},{"id":19097,"question":"سؤالها الأخير تقول: ما هو رأي سماحتكم في كتاب: مشاهد القيامة في القرآن، لـسيد قطب؟","title":"تقييم كتاب: مشاهد القيامة في القرآن لـسيد قطب","answer":"الجواب: لم أقرأه، ولكن فيما بلغني عنه أنه لا بأس به، كتب الـسيد قطب مفيدة ونافعة، وليس معناها أن ليس فيها خطأ، كل عالم له بعض الأخطاء والأغلاط، لكني لم أقرأ الكتاب وهو فيما بلغني كتاب مفيد ومؤثر، رحم الله مؤلفه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18304/تقييم-كتاب-مشاهد-القيامة-في-القران-لـسيد-قطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_884/nour_88410.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19101,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع محمد سعيد محمود من الجمهورية العراقية، وهو مصري الجنسية، أخونا بدأ رسالته بقوله: السادة الأساتذة الكرام وعلماءنا ومعلمينا الأفاضل في برنامج: نور على الدرب، سلام الله عليكم ورحمته وبركاته.. وبعد، قرأت في كتاب يسمى بدائع الزهور في وقائع الدهور: لما دخل نبي الله يعقوب إلى مصر مشى العسكر بين يديه حتى وصل إلى قصر ابنه يوسف حيث كان وزير وعزيز مصر في ذلك الوقت، وعندما دخل القصر رفع يوسف أباه وخالته على سريره، وأمر العسكر أن يسجدوا لهما، وكان ذلك عادة أهل مصر في التحية.فهل سجود التحية مباح في مثل هذه المواقف؟ أرجو من سيادتكم تفسيرًا عن ذلك حفظكم الله وزادكم من علمه ونفعنا بكم والمسلمين، آمين.","title":"ما تقييم كتاب: بدائع الزهور؟، وحكم السجود لغير الله للتحية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فينبغي أن يعلم أن هذا الكتاب وهو بدائع الزهور ليس من الكتب المعتمدة، بل هو حاطب ليل، يذكر الغث والسمين، والصحيح والباطل، فلا يعتمد عليه، وأخبار بني إسرائيل أخبار قديمة، لا يعتمد عليها إلا ما ثبت عن الله أو عن رسوله محمد عليه الصلاة والسلام، ونص القرآن أن يوسف عليه الصلاة والسلام رفع أبويه على العرش، وهما أبوه وأمه لا خالته، بل أبوه وأمه؛ لأن الله قال: وَرَفَعَ أَبَوَيْهِ عَلَى الْعَرْشِ وَخَرُّوا لَهُ سُجَّدًا [يوسف:100]. وكانت السجدة ذلك الوقت مباحة للإكرام والتحية، وليست للعبادة، وكما سجد الملائكة لـآدم إكرامًا وتعظيمًا لا عبادة، فهذه السجدة ليست من باب العبادة ولكن من باب التحية والإكرام، وهي جائزة في شرع من قبلنا، ولكن في شريعة محمد عليه الصلاة والسلام ممنوع ذلك، ولهذا ثبت عنه عليه الصلاة والسلام أنه قال: لو كنت آمرًا أحدًا أن يسجد لأحد لأمرت المرأة أن تسجد لزوجها لعظم حقه عليها. وبين أن السجود لله ، فلا يسجد إلا لله وحده ، وقال  في آخر سورة النجم: فَاسْجُدُوا لِلَّهِ وَاعْبُدُوا [النجم:62]، وقال في سورة اقرأ: وَاسْجُدْ وَاقْتَرِبْ [العلق:19] ، فالسجود لله وحده، وشريعة محمد عليه الصلاة والسلام هي أكمل الشرائع وأتمها، فلا يجوز فيها السجود لغير الله، لا تحية ولا عبادة، أما العبادة فلا تصح إلا لله وحده في جميع الشرائع؛ لأن الله جل وعلا قال: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23]، قال سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]. فالعبادة حق الله وحده في كل زمان ومكان، ولكن كان السجود فيما مضى يستعمل تحية وإكرامًا كما فعل أبوي يوسف وإخوته، وكما فعلت الملائكة لـآدم هذا من باب التحية والإكرام وليس من باب العبادة، أما في شريعة محمد عليه الصلاة والسلام فإن الله  منع من ذلك، وجعل السجود لله وحده  ولا يجوز أن يسجد لأحد، لا للأنبياء ولا غيرهم، حتى محمد عليه الصلاة والسلام منع أن يسجد له أحد، وأخبر أن السجود لله وحده  فعلم بهذا أن جميع أنواع العبادة كلها لله وحده  ومن أعظمها السجود، فإنه ذل وانكسار لله  فهو من أفضل العبادات، فلا يصرف لغيره من الناس لا للأنبياء ولا للجن ولا للإنس، ولا غيرهم، والله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18299/ما-تقييم-كتاب-بداىع-الزهور-وحكم-السجود-لغير-الله-للتحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_884/nour_88406.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19128,"question":"من هم أهل الفتوى الذين يجب على عامة المسلمين الأخذ بفتواهم، ولنا أخ في الله مؤمن مسلم وسلوكه جيد في الدين، وفي الحياة العامة، ولكنه ليس متفقهًا في الدين لدرجة أن يفتي، وفي بعض المسائل يفتينا ويقول: هذا على مسئوليتي، فهل نأخذ بفتواه أم لا، وهل من حقه أن يفتي أم لا؟","title":"تعريف أهل الفتوى","answer":"الجواب: أهل الفتوى هم الذين قد تفقهوا في كتاب الله وسنة رسوله عليه الصلاة والسلام، وحصلت لهم معرفة جيدة بما أحل الله، وما حرم الله، وما أوجب الله، وشهد لهم أهل العلم والفقه والخير، عن المعرفة، وأنهم أهل لأن يفتوا، ولا ينبغي أن يستفتى كل أحد، ولو انتسب إلى الدين أو إلى العبادة، أو إلى العلم حتى يسأل عنه أهل العلم، ويتبصر السائل بواسطة العارفين به، والذين يطمئن إليهم أنهم أهل علم حتى يذكروا له أنه أهل للفتوى وأهل لأن يفتي في الحلال والحرام ونحو ذلك. المقصود أن هذا يحتاج إلى تثبت في الأمر، وعدم تساهل، فليس كل من انتسب إلى الدين، أو إلى العبادة، أو إلى العلم يصلح لذلك، بل لا بد من فقه في الدين وتبصر، ولا بد من ورع وتقوى لله، ولا بد من حذر من التساهل في الفتوى والجرأة عليها بغير علم وبغير حق، ولا حول ولا قوة إلا بالله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18310/تعريف-اهل-الفتوى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_885/nour_88504.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19167,"question":"أخونا يسأل أيضًا سماحة الشيخ ويقول: يوجد طائفة من الناس إذا دعوناهم إلى الله  وإلى ترك الشرك بالله اتهمونا بالوهابية، كيف نواجههم لو تكرمتم؟","title":"ما يفعله من يتهم بالوهابية لدعوته إلى التوحيد؟","answer":"الجواب: يُعلَّمون، الوهابية ما هنا مذهب الوهابي، إنما هو طاعة الله ورسوله، الوهابية تدعو إلى ما قاله الله ورسوله، الشيخ محمد بن عبد الوهاب رحمه الله الذي تنسب إليه الوهابية هو رجل قام في النصف الثاني من القرن الثاني عشر يدعو الناس إلى ما قاله الله ورسوله، يدعو الناس إلى عقيدة السلف الصالح، إلى اتباع رسول الله ﷺ والسير على منهج أصحابه في الأقوال والأعمال. فهو حنبلي المذهب ولكنه وفقه الله لدعوة الناس إلى إصلاح العقيدة وترك الشرك بالله  وترك البدع والخرافات التي قام بها، وتخلق بها المتصوفة أو أصحاب الكلام، فهو يدعو إلى عقيدة السلف الصالح في العمل وفي العقيدة، وينهى عما عليه أهل الكلام من بدع، وما عليه بعض الصوفية الذين خرجوا عن طريق الصواب إلى البدع، فليس له مذهب يخالف مذهب أهل السنة والجماعة، بل هو يدعو إلى مذهب أهل السنة والجماعة فقط. فإذا دعوت أحدًا إلى التوحيد ونهيته عن الشرك، فقالوا: الوهابية فقل: نعم، أنا وهابي وأنا محمدي أدعوكم إلى طاعة الله وشرعه، أدعوكم إلى توحيد الله. فإذا كان من دعا إلى توحيد الله وهابي، فأنا وهابي، وإذا كان من دعا إلى توحيد الله ناصبي فأنا ناصبي، وإذا كان من دعا إلى توحيد الله شيعي فأنا شيعي، المهم الدعوة إلى ما كان عليه رسول الله ﷺ وأصحابه، والتلقيب بالذي ينفر به الناس عن الدعوة لا قيمة له. الواجب على المؤمن أن يتقي الله، وأن يستقيم على أمر الله، ولو قال الناس له ما قالوا، ولو قالوا: منافق، ولو قالوا: وهابي، ولو قالوا: شيعي، ولو قالوا كذا، إذا عرف أنه يدعو إلى توحيد الله وإلى طاعة الله ورسوله كما قال الله ورسوله، فلا يضره المشاغبون والمنفرون بالألقاب التي يخترعونها له، كما أن الرسول ﷺ قال له الكفار: صابئ، وقالوا له: مجنون، وقالوا له: شاعر، وقالوا: كاهن، وقالوا: ساحر، ما ضره ذلك، استمر في دعوته إلى الله، وعلم الناس توحيد الله، ولم يبال بقولهم له: إنك ساحر أو كاهن أو ما أشبه ذلك. فهكذا أتباع الحق، لا يضرهم إذا قيل لهم: وهابي، أو قيل لهم كذا أو قيل لهم كذا، أو قيل: مشدد، أو قيل: منفر، أو قيل: متطرف، أو متعمق، أو كذا أو كذا يلقبونه حتى ينفروا منه الناس، لا ما يضرهم هذا، عليه أن يصبر وعليه أن يوضح للناس الحق وأنه ليس عنده شيء يخالف شرع الله المطهر الذي جاء به محمد عليه الصلاة والسلام. فالوهابية هم هذا، الوهابية دعاة إلى توحيد الله وإلى طاعة الله ورسوله، وليس لهم مذهب جديد، إنما هم دعاة إلى توحيد الله، وإلى اتباع رسوله محمد ﷺ، وهم في الفقه في الغالب على مذهب الحنابلة، إلا إذا وجدوا شيئًا في المذهب الحنبلي يخالف الأرجح من أقوال العلماء، لوجود الدليل الذي يؤيد ما قاله الآخرون، أخذوا بالدليل. نعم.","link":"https://binbaz.org.sa/fatwas/18383/ما-يفعله-من-يتهم-بالوهابية-لدعوته-الى-التوحيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_887/nour_88708.mp3","categories":["الدعوة والدعاة"]},{"id":19172,"question":"أخونا أيضًا يقول: إن نظام وقوانين الشهادات تسبب في تعطيل كثير من العلم النافع، فلم يوجد المدرس الكفء الصالح الذي يربي النشء تربية حقيقية، وأصبح الطالب لا يهمه إلا حمل الشهادة بغض النظر عن دينه وعقيدته، وفقهه وخلقه، إلى درجة أن بعض الطلبة، بل أيضًا بعض المدرسين لا يعرف كيف يصلي على الجنازة، وأكثرهم لا يصلون الصلوات الخمس، وإذا صلى بعضهم صلى بعض الصلوات وترك البعض الآخر.و ما هو الواجب على المدرسين نحو أنفسهم وطلبتهم؛ لأن أغلب الطلبة يتمثلون في مدرسيهم، ويأخذون عنهم الكثير مما هم عليه من الجهل بشرع الله، والإهمال في عبادة الله، والعادات والتقاليد المخالفة لدين الله، والسؤال أيضًا: ما هو الواجب على الطلبة نحو أنفسهم، وما هو الواجب على ولاة الأمور تجاه الطلبة؟جزاكم الله خيرًا.","title":"ما هو الواجب على المدرسين نحو أنفسهم وطلبتهم؟","answer":"الجواب: التنظيم الذي وقع في الناس منذ دهر طويل حصل به مصالح جمة، من تنشيط الطلبة وترغيبهم في طلب العلم، وأخذ الشهادات التي تشجعهم على طلب العلم، والاستعانة بها على الوظائف وعلى مصالحهم الدنيوية، فيه مصالح، وفيه مضار؛ لأن كثيرًا من الطلبة لا يطلب العلم للآخرة، وإنما يطلبه للدنيا، ومصالحها وفوائدها، ووظائفها، ففيه خير وشر، فمن طلب العلم لله من طريق النظم المتبعة، فأخذ الشهادات واستعان بها على طاعة الله، وتفقه في الدين نفع الله به الأمة، وصارت هذه الشهادات عونًا له وزادًا له على أداء المهمة، وعلى دعوة الناس إلى الخير، وعلى أن يقدر ويعرف له فضله، ومن استعان بها على الدنيا ونسي الآخرة، صارت حظه من الدنيا ولم يكن له من الآخرة.. ولم يكن له في الآخرة نصيب إذا لم يعمل للآخرة ولم يكدح لها. فالحاصل أن هذه الشهادات التي يأخذها الطالب وهذه التنظيمات التي يسير عليها الطالب تنفع المجد الصالح الطيب الذي يريد الآخرة، تنفعه وتعينه، والآخر الذي لا يريد الآخرة ما تزيده إلا خبالًا، ولا تزيده قربًا من الله ؛ لأنه ما أراد بها الآخرة، وإنما أراد بها الدنيا، وحظها العاجل، وقد يوفق بعض الناس فيتعلم للدنيا ثم يهديه الله ويتعلم للآخرة، ويستفيد كما قال بعض السلف: طلبنا العلم لغير الله فأبى أن يكون إلا لله. فالواجب على المدرسين أن يتقوا الله، وأن يلتزموا بالإسلام، وبأخلاق الإسلام، وأعمال الإسلام، حتى يكونوا قدوة للطلبة، ولاسيما من يدرس العلوم الشرعية، فإن الواجب عليه أن يكون أقرب الناس إلى الخير، وأكملهم في الخير، وأسبق الناس إلى طاعة الله ورسوله، وأبعد الناس عن معصية الله ورسوله، حتى يتأسى به تلاميذه، وحتى يقتدوا به في الخير. والواجب على الأستاذ أيضًا أن يكون حريصًا على تفقيه الطلبة وتشجيعهم على الخير، وترغيبهم فيه، وأن يحثهم على طاعة الله ورسوله، ويحذرهم من معصية الله ورسوله، وأن يحثهم على التأسي بالرسول ﷺ وبأصحابه الكرام، وبأهل الخير، وأن يحذرهم من التأسي بأهل الشر، فهو يحثهم باللسان ويحثهم بالعمل، يكون قدوة صالحة في عمله، ومع ذلك هو يرغبهم ويحثهم بلسانه، فيجمع بين الأمرين، بين التشجيع القولي، والتشجيع العملي، فيرون من أعماله وسيرته ما يسرهم وما يعينهم على طاعة الله ورسوله، ويسمعون منه الدرس وفي غير الدرس من الكلام الطيب والتوجيه الصالح، والأمر بالمعروف والنهي عن المنكر ما يسرهم ويعينهم على طاعة الله ورسوله، هذا هو الواجب على الجميع. وعلى الطالب أن يتقي الله، عليه أن يتقي الله وألا تكون همه.. وألا يكون همه الشهادة، بل عليه أن يتقي الله حتى يستعين بالشهادة على طاعة الله ورسوله، وحتى يستعين بالشهادة على نفع العباد في توجيههم إلى الخير، وأمرهم بالمعروف، ونهيهم عن المنكر، وتعليم جاهلهم، وإرشاد ضالهم إلى غير ذلك، لا تكن الشهادة وسيلة فقط للدنيا، لا، بل عليه أن يستعملها في أمر الدين والدنيا، يستعين بها على طاعة الله، وينتفع بها في الوظيفة التي يوظف بسببها حتى ينتفع في دنياه وأخراه. فهذه الدور العلمية من معاهد ومدارس وجامعات، أنشئت للعلم في بلاد المسلمين، ولتعليم الناس ولتوجيه الناس إلى الخير، فعلى القائمين عليها أن ينصحوا لله ولعباده، وأن يجتهدوا في توجيه الناس إلى الخير، وإرشادهم إليه، وعلى الطالب أن يتقي الله وأن يجتهد في طلب العلم النافع، وأن يجتهد أيضًا في سؤال أهل العلم، والاستفادة من آرائهم، وأن يكون متواضعًا، يريد العلم، يريد الفقه في الدين، وعليه أن يعمل بعلمه في أقواله وأفعاله، عليه أن يعمل، تعرف عليه آثار العلم في خشيته لله، وفي قيامه بأمر الله، وفي محافظته على طاعة الله، وفي بره لوالديه، وفي صلته لأرحامه، وفي إكرامه لجاره، وفي غير هذا من أعمال الخير، ولاسيما الصلاة في المحافظة عليها، والمسارعة إليها في الجماعة والخشوع فيها، هكذا يكون الطالب الصالح المجد. وعلى المدرس أن يعتني بالطلبة ويوجههم، وأن يكون قدوة صالحة كما تقدم لهم في الخير كله، ونسأل الله للجميع الهداية والتوفيق. المقدم: اللهم آمين، نفع الله بكم.","link":"https://binbaz.org.sa/fatwas/18369/ما-هو-الواجب-على-المدرسين-نحو-انفسهم-وطلبتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_887/nour_88703.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19176,"question":"السؤال لأخينا مقبل بن حسن يقول: لقد ظهرت الصحوة الإسلامية المحمدية بحمد الله تعالى في هذه الآونة الأخيرة رغم كثرة الملحدين والمنافقين وأعداء السنة من الدجالين والخرافيين والصوفية والحزبيين، و ما هي الوقاية من هذه الفرق الضالة وخطرها؟ ثانيًا: ماذا يجب على الآباء نحو أبنائهم وزوجاتهم؟","title":"توجيهات للصحوة المباركة","answer":"الجواب: أولاً: الواجب على الدعاة في هذه الصحوة المباركة، واليقظة المباركة، الواجب عليهم دائمًا دائمًا الأخذ بالحكمة والرفق، وأن لا يجابهوا الناس بالعنف، حتى لا يكثر أعداؤهم وخصومهم، الواجب أن تكون الدعوة بالرفق والحكمة والأسلوب الحسن، والحرص على تجنب الاصطدام بالناس مهما أمكن؛ لأن الرسول ﷺ أوصى بالرفق، والله يقول في كتابه الكريم: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125]، قال سبحانه: وَلا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ [العنكبوت:46]، وقال عليه الصلاة والسلام: من يحرم الرفق يحرم الخير كله، وقال عليه الصلاة والسلام: إن الرفق لا يكون في شيء إلا زانه، ولا ينزع من شيء إلا شانه والله يقول سبحانه: فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لانْفَضُّوا مِنْ حَوْلِكَ [آل عمران:159]. فعلى الدعاة أن يلزموا الحلم والصبر والتحمل، ولو آذاهم من آذاهم، وأن يحرصوا على بذل العلم، وتوجيه الناس إلى الخير، وعلى من هداه الله أن يتحمل ولا يكون عنيفًا مع والده، ولا مع إخوته، ولا مع أخواته، بل يكون بالحلم والرفق في توجيههم إلى الخير وتعليمهم، وإرشادهم ونصيحتهم حتى يقبل منه، وحتى لا ينفروا منه، وحتى لا يتسلط عليه أقاربه، عليه بالحلم والرفق في دعوته، وفي نصيحته، وفي جهاده للمنكر، حتى يكون ذلك أقرب إلى الامتثال والاستفادة منه في حق أهله وجيرانه وأصحابه. والواجب على أبيه وعلى أمه وعلى إخوته أن يعينوه على الخير، وأن يرفقوا به، وإذا رأوا منه شدة وصلفًا نصحوه، ووجهوه بالتي هي أحسن، حتى يهدأ وحتى يكون على الطريق السوي في دعوته ونصيحته، وتوجيهه غيره. فالمقصود التعاون بين الجميع، التعاون على البر والتقوى، فإذا اشتد هو نصحوه بالرفق والحكمة، ولا يزيدونه في شدته عنفًا بل ينصحونه ويوجهونه ويرفقون به، ولا يقاطعونه، وهو كذلك عليه أن يرفق ويعتني بإخوانه حتى لا يكون منه ما ينفرهم منه، يأتي بالأساليب الطيبة، واللينة، والعبارات الحسنة، ويدعو لهم بالتوفيق والخير، هكذا يكون لطيفًا في دعوته، حسن الكلام، طيب الأسلوب، وعلى والديه أن يعينوه وألا ينفروا منه، وألا يثبطوه وهكذا إخوته، وهكذا أعمامه، هكذا جيرانه، إذا رأوا منه شدة لينوه، وحثوه على الرفق، لكن لا يمنعوه من الدعوة، ولا يشددوا عليه، ولا ينفروه، ولا يتركوه بل يساعدونه على الخير. هكذا يجب التعاون؛ لأن الله سبحانه يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، ويقول سبحانه: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3]. والقاعدة: أن الإنسان إذا أسلم بعد كفره قد يكون عنده شدة، وهكذا إذا اهتدى بعد فسقه أو بعد جهله، قد يكون عنده شدة يريد أن يطبق، لكن عليه أن يرفق وعليه أن يحلم، وعليه أن يتصبر، الرسول ﷺ صبر، مكث في مكة ثلاثة عشر سنة مع الكفار، صبر حتى أعانه الله، وحتى يسر الله له الهجرة، وعنده المنافقون في المدينة، وصبر عليهم، فينبغي لك التأسي بالرسول ﷺ، وقد قال الله فيه في حقه، وهو في المدينة في موضع سلطانه: فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ [آل عمران:159]، والآية مدنية، وله السلطان في المدينة، ومع هذا رفق بهم، ولم يشدد عليهم، بل دعا بالرفق والحكمة، وعنده اليهود قبل أن ينفوا، وعنده المنافقون. فالواجب الصبر كما صبر النبي ﷺ والحلم كما حلم عليه الصلاة والسلام، والرفق كما رفق، واللين كما لان، ففي سيرته الخير والبركة، في سيرته ﷺ الخير والبركة، وقد قال الله لـموسى و هارون لما بعثهما إلى فرعون ، وفرعون ألعن الناس وأخبث الناس، قال لهما: فَقُولا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى [طه:44] ، وقال الله: وَلا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ [العنكبوت:46]، وأهل الكتاب من هم؟ اليهود و النصارى ، كفار، ومع هذا قال الله: لا تجادلوهم إلا بالتي هي أحسن، يعني: بالرفق والحكمة حتى يقبلوا، حتى لا ينفروا من الحق، فهكذا إخوانك المسلمون، عليك بالرفق بهم، هم خير من الكفار، وأولى بالرفق من الكفار، فعليك بالرفق والحكمة، لعلهم يقبلون، ولعلهم يستجيبوا لدعوتك، ولعلهم يساعدونك في الخير، ولا ينفروا منك، نسأل الله للجميع الهداية والتوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18361/توجيهات-للصحوة-المباركة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_887/nour_88702.mp3","categories":["الدعوة والدعاة"]},{"id":19179,"question":"أولى رسائل هذه الحلقة رسالة مطولة جدًا وباعثها أخ لنا يقول: مقبل بن حسن بن عدي الصلاحي بعدن، أخونا يسأل عن مجموعة من القضايا، فيقول في قضيته الأولى: لقد اختفى الوعظ والإرشاد عن بعض المساجد في المملكة وقد آلمنا ذلكم كثيرًا، فهل من تعليل لهذا؟ وجهونا جزاكم الله خيرًا.","title":"علة اختفاء الوعظ والإرشاد عن بعض المساجد","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فلا ريب أن الوعظ والإرشاد من أهم المهمات، والمسلمون في أشد الحاجة إلى ذلك، بل وغير المسلمين في أشد الحاجة إلى ذلك، ولكن بسبب قلة الدعاة واشتغال الناس في أمور أخرى من التدريس والشئون الإدارية وغير ذلك قد يتأخر الداعية عن المسجد وقتًا طويلًا لكثرة المساجد وقلة الدعاة، فهذا هو السبب، وإني أنصح جميع المدرسين المتأهلين من أهل العلم ومن خريجي كلية الشريعة وكلية أصول الدين أنصحهم جميعًا أن يتقوا الله وأن يشاركوا في الدعوة، وأن يشاركوا في الوعظ والتذكير في المساجد، حتى يسدوا الخلل والنقص الذي يحصل من الدعاة، فالدعاة بالنسبة إلى كثرة المساجد قليلون، وإن كنا نتطلب دعاة حتى يتعينوا عندنا ونريد ذلك ونحرص على ذلك، لكن ليس كل ما يريده الإنسان يحصل له؛ لأن إخواننا المتخرجين كثير منهم يرغب أن يكون مدرسًا أو في عمل إداري؛ لأنه أسهل عليه من الدعوة. فالمساجد كثيرة والدعاة قليلون، فلهذا قد يتأخر مجيء الداعية إلى المسجد كما ذكر السائل، وإن كانوا بحمد الله يمرون على المساجد ويقومون بالدعوة في غالب المساجد، لكن قد يتأخر بعضهم عن بعض المساجد، وقد تكون بعض المساجد في أطراف البلد، فلا يأتيها الداعية إلا في أوقات متفاوتة، ولكن لمثل ما تقدم أنصح إخواني المدرسين وأهل العلم من القضاة وغيرهم أنصحهم جميعًا أن يتقوا الله وأن يشاركوا في الدعوة إلى الله، ووعظ الناس وتذكيرهم، والإجابة عن أسئلتهم؛ لأن هذا واجب الجميع، وحق على الجميع، نسأل الله أن يوفق الجميع. المقدم: اللهم آمين، المتطوع للدعوة إلى الله سماحة الشيخ هل من شروط تشترط؟ الشيخ: نعم، إذا كان متخرجًا من كلية الشريعة أو كلية أصول الدين أو كلية الحديث في الجامعة الإسلامية، أو كلية القرآن، هذا يعطى البطاقة، أو شهد له بعض أهل العلم بأنه صالح لذلك، ممن درس على المشايخ وصارت له دربة في الوعظ والتذكير، ويصلح للفتوى يعطى أيضًا بطاقة بذلك، ومن لا يشهد له بهذا لا يعطى البطاقة، مثل خريجي كلية اللغة، أو كلية العلوم الاجتماعية، أو كليات الطب أو ما أشبه ذلك، لا يعطون؛ لأنهم ليسوا أهلًا لهذا المقام في الغالب. نعم. المقدم: إذًا: لا بد من هذه البطاقة سماحة الشيخ؟ الشيخ: لا بد من هذه البطاقة بالنسبة إلينا، أما بالنسبة إلى ما يقوم به هو من الدعوة في جماعته، أو فيمن يسمح له بذلك من إخوانه، فهذا مسموح له فيه وجزاه الله خيرًا، لكن من حيث الرياسة العامة التي أنا عليها لا نستطيع أن نعطي إنسانًا بطاقة على أن يقوم بالدعوة إلا إذا كان قد تأهل لها، فيما نعتقد من جهة تخرجه من كلية الشريعة، أو كلية أصول الدين أو ما في حكمهما، أو وجود شهادة بيده من أهل العلم تشهد له بأنه أهل للدعوة، وأهل للفتوى، نعم، لكن المدرسون في الغالب، المدرسون والقضاة في الغالب هؤلاء عندهم ما يعينهم على ذلك، ويمكنهم من ذلك؛ لأنهم مدرسون من خريجي كلية الشريعة، وكلية أصول الدين، ومن العلماء المعروفين، يستطيعون أن يقوموا بالدعوة، وإن كان ما معهم بطاقة، وإذا أرادوا بطاقة أعطيناهم بطاقة، لكن العالم المشهور ما يحتاج بطاقة في المملكة، لكن لو أراد بطاقة أعطيناه، بالنسبة إلى بعض المساجد التي قد تجهله. نعم. المقدم: نعم من لم يكن من هذا البلد سماحة الشيخ ويريد أن يدعو إلى الله يستغل وجوده في هذه البلاد فيدعو إلى الله كيف يكون التصرف؟ الشيخ: التعليمات تمنع من ذلك، التعليمات التي من جهة الدولة تمنع أن يعطى بطاقة إلا إذا كان يحمل الجنسية السعودية. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18357/علة-اختفاء-الوعظ-والارشاد-عن-بعض-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_887/nour_88701.mp3","categories":["الدعوة والدعاة"]},{"id":19231,"question":"المستمع سعيد بن عبد الحميد أحمد بعث يسأل ويقول: لي صديق تارك للصلاة، وقد قدمت له النصيحة ولم يستجب بل قابل ذلك بالقطيعة بيني وبينه، فما هو توجيهكم لي؟ جزاكم الله خيرًا.","title":"الواجب تجاه تارك الصلاة","answer":"الجواب: قد أحسنت فيما فعلت، وأديت الواجب في النصيحة، والواجب أن يهجر هو، فإذا قطعك فأنت تقطعه أيضًا؛ لأنه هو يستحق الهجر، قد هجر النبي ﷺ ثلاثة من الصحابة لما تأخروا عن غزوة تبوك بغير عذر، فالذي يتأخر عن الصلاة ولا يصلي من باب أولى؛ لأن ترك الصلاة كفر أكبر، فالواجب هجره إذا لم يقبل النصيحة، ورفع أمره إلى ولي الأمر إذا كان في بلاد تحكم بالإسلام رفع أمره إلى ولي الأمر حتى يعاقب بما يستحق، وحتى يستتاب، فإن تاب وإلا وجب قتله إذا ترك الصلاة؛ لأن الله يقول سبحانه: فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ [التوبة:5]، فدل على أن الذي لا يؤدي الصلاة لا يخلى سبيله بل يرفع أمره إلى ولي الأمر، إلى المحكمة، إلى الهيئة هيئة الأمر بالمعروف والنهي عن المنكر؛ حتى تنظر في أمره، وأنت قد أديت ما عليك بنصيحته وتوجيهه إلى الخير. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18417/الواجب-تجاه-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_738/nour_73804.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":19242,"question":"كثير من السادة المستمعين يسأل سماحة الشيخ ومن بينهم أحد الإخوة المستمعين يقول عبد الحي عثمان حماد سوداني مقيم في الرياض، أخونا يسأل مع مجموعة من المستمعين الذي يهتمون بالدعوة إلى الله ويقولون: هل لنا أن نرتاد الأماكن المحرمة التي نعرف أنه يرتادها أناس مسلمون للدعوة إلى الله؟","title":"حكم ارتياد الأماكن المحرمة والمبتدع فيها للدعوة إلى الله","answer":"الجواب: نعم. بل يشرع أن يقصدها الدعاة كالقهاوي التي يكون فيها من يتعاطى ما حرم الله أو المجالس التي يكون فيها أخلاط، فإذا قصدهم.. دعاهم إلى الله ورغبهم في الخير وحذرهم من محارم الله كالخمر والتدخين وحلق اللحى واختلاط النساء بالرجال، فإذا فعل هذا يكون قد أحسن؛ لأنه ما قصدها ليتخذها محلًا له أو لمشاركتهم في أعمالهم القبيحة أو لاتخاذهم أصحابًا لا، إنما قصد ذلك ليعظهم ويذكرهم ويأمرهم بالمعروف وينهاهم عن المنكر، فهو محسن وله أجره العظيم. وقد ثبت عن رسول الله عليه الصلاة والسلام أنه توجه ذات يوم إلى سعد بن عبادة سيد الخزرج  ليعوده وهو مريض، فمر على مجلس فيه أخلاط من اليهود ومن المسلمين ومن عبدة الأوثان وهو على حمار، فنزل عن دابته عليه الصلاة والسلام، ووقف عليهم وتلا عليهم القرآن ودعاهم إلى الإسلام، وذكرهم بالله  وهم بهذه الصفة فيهم الأخلاط.. فيهم اليهود وفيهم وثنيون وفيهم مسلمون. فدل ذلك على أن قصد هذه المجالس التي فيها الأخلاط للدعوة والتوجيه أمر مطلوب، وأن فيه خيرًا كثيرًا ومصالح جمة؛ ولأن كثيرًا منهم لا يتحرى مجالس العلم ولا حلقات العلم، بل قد تمر عليه الشهور أو الأعوام ما سمع المواعظ؛ لأنه ليس من أهل الصلاة وليس من أهل حلقات العلم، وقد يكون كافرًا ليس من أهل الإسلام، فإذا سمع النصيحة هداه الله وانشرح قلبه، وصار لهذا الداعي مثل أجره، وقد يكون عاصيًا فاسقًا فيهديه الله بسبب هذه النصيحة، ويدع ما هو عليه من الباطل، فأنا أرى أن زيارة هذه الأماكن لقصد الدعوة أمر مطلوب. نعم. المقدم: جزاكم الله خيرًا، وما أشبه أماكن العزاء بهذا سماحة الشيخ؟ الشيخ: كذلك مكان العزاء إذا زارهم للنصيحة والتوجيه لا بأس بذلك، وهكذا لو أتى احتفالًا بالأعياد.. بالموالد، الناس الذين يحتفلون بالمولد مثلًا. مولد الرسول ﷺ أو مولد البدوي أو مولد الحسين أو مولد فاطمة في بعض البلدان التي تقيم هذه الحفلات إذا اختلط بهم لقصد الدعوة والتوجيه فقط، لا لأجل الرضا بعملهم أو تكثير سوادهم، على وجه لا يفهم منه أنه يوافقهم، ولا يظهر منه لأحد أنه موافق على هذه البدعة، ولكن على وجه يعلم منه أنه أراد النصيحة، ويصرح بذلك ويقول: أنا جئتكم للنصيحة فقط، لا لأنني موافق على هذا الاحتفال بل أنا أنصحكم أن لا تعودوا إليه، وأن تعتاضوا عنه بالاحتفال الشرعي.. بحلقات العلم ودروس العلم والمواعظ. أما إيجاد احتفالات لم يشرعها الله في هذه الموالد هذا شيء لا أصل له وهو من البدع، فأنا جئتكم ناصحًا ومذكرًا، لا موافقًا ولا مؤيدًا لهذا العمل الذي يخالف شرع الله، وقد قال الله سبحانه: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21]، وقال النبي الكريم عليه الصلاة والسلام: من عمل عملًا ليس عليه أمرنا فهو رد، يعني: فهو مردود، خرجه الإمام مسلم في صحيحه ، وخرجه البخاري رحمه الله في الصحيح تعليقًا مجزومًا به، وقال أيضًا عليه الصلاة والسلام في خطبة يوم الجمعة: أما بعد.. فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلاله، زاد النسائي بإسناد صحيح: وكل ضلالة في النار. فالنبي في خطبة الجمعة عليه الصلاة والسلام يحذر الناس من هذه البدع؛ لأن البدع متى ظهرت في الناس ضيعوا بأسبابها السنن، وقست قلوبهم، وصاروا بهذا معترضين على شرع الله، كأنه سبحانه لم يكمل هذا الشرع، وكأن رسوله لم يبلغ، والله يقول جل وعلا: الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ [المائدة:3]، فليس لهذه البدع محل، وقد أكمل الله الدين وأتم النعمة، فالاحتفال بالموالد مثلًا أو الاحتفال بليلة الإسراء والمعراج أو الاحتفال بليلة النصف من شعبان أو ما أشبه هذا من البدع كل ذلك منكر. فمن حضر عندهم لبيان الحق وإنكار البدعة وإرشادهم إلى الصواب ونصيحتهم يرجو ما عند الله ويوضح ذلك وأنه جاء لهذا الأمر حتى لا يظن أحد لا يعلم أنه جاء مؤيدًا أو مشاركًا في هذا الأمر، بل يبين على رءوس الأشهاد أنه جاء للدعوة والإرشاد لا للموافقة والتأييد، وفق الله الجميع. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18433/حكم-ارتياد-الاماكن-المحرمة-والمبتدع-فيها-للدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_891/nour_89104.mp3","categories":["الدعوة والدعاة"]},{"id":19258,"question":"يسأل سماحتكم، ما هي أفضل الكتب في العقيدة؟","title":"أفضل الكتب في العقيدة","answer":"الجواب: أفضل الكتب وأصحها: القرآن العظيم فقد بين العقيدة الصحيحة، فالقرآن هو كتاب الله وأصدق كتاب، وأفضل كتاب، وأعظم كتاب فيه بيان العقيدة الصحيحة، بيان أسماء الله صفاته وتوحيده والإخلاص له  هو أعظم كتاب. ثم يليه بعد ذلك: البخاري ومسلم الصحيحان هي أعظم الكتب المفيدة من كتب الحديث بعد القرآن؛ لأن فيها أحاديث الرسول ﷺ الصحيحة فالصحيحان: صحيح البخاري وصحيح مسلم هما أصح الكتب وأنفعها بعد كتاب الله  . ثم بقية الكتب المعروفة، سنن أبي داود والترمذي والنسائي وابن ماجة وموطأ مالك، وسنن الدارمي كتب جيدة مفيدة، وإن كان فيها بعض الأحاديث الضعيفة لكنها كتب مفيدة عظيمة. وكتب العقيدة كثيرة لكن منها ما ألفه السلف الصالح مثل: عثمان بن سعيد الدارمي في الرد على الجهمية، مثل كتاب عبد الله بن أحمد بن حنبل في بيان السنة والرد على أهل البدع مثل كتاب التوحيد لابن خزيمة فيه عن التوحيد والرد على أهل البدع، وأشباهه من الكتب المفيدة، مثل الطحاوية وشرحها، ومثل لمعة الاعتقاد للموفق، والعقيدة الواسطية، والتدمرية، والحموية لشيخ الإسلام ابن تيمية كلها في العقيدة، وكتاب التوحيد للشيخ محمد بن عبد الوهاب رحمه الله، كتاب عظيم ومفيد، كشف الشبهات في العقيدة كذلك للشيخ محمد بن عبد الوهاب رحمه الله، الثلاثة الأصول، كتاب مختصر جيد في العقيدة للشيخ محمد رحمه الله. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18451/افضل-الكتب-في-العقيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73904.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19259,"question":"رسالة من أحد الإخوة المستمعين آثر عدم ذكر اسمه، عرضنا له مجموعة من الأسئلة في حلقة مضت، وبقي له في هذه الحلقة سؤال واحد يقول: إن بعض الأقارب لا يصلون، هل زيارتهم ومجاملتهم واجبة؛ علمًا أننا ننصحهم، ولكنهم يحاولون الهرب من الموضوع، ولا يتأثرون؟ وجهونا جزاكم الله خيرًا.","title":"ما كيفية معاملة مَن لا يصلي أو يفعل المنكر؟","answer":"الجواب: إذا كان قريبك، أو جارك؛ لا يصلي فالواجب نصيحته منك ومن إخوانك تنصحونه بالكلام الطيب، والتخويف من الله، وأن الصلاة عمود الإسلام، وأن تركها كفر بالله  أكبر، على الصحيح من أقوال العلماء، وإن لم يجحد وجوبها. فالصلاة عمود الإسلام، وفيها الخير العظيم، والأجر الكبير، فعليك أن تنصح قريبك أو جارك، وتجتهد في ذلك منك ومن إخوانك؛ لأن الله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى[المائدة:2] فإذا كان معك بعض إخوانك تكون النصيحة أكثر وأجدى، فإن أبوا ولم يقبلوا استحقوا الهجر؛ يجب هجرهم عند جمع من أهل العلم. وقال جماعة: يستحب هجرهم، فبكل حال هجرهم مشروع إلا إذا رأيت أن الاتصال بهم بين وقت وآخر للدعوة أنفع فلا بأس للدعوة إلى الله والإرشاد والنصيحة لعلهم يهتدون. وهكذا من تعرفه من جيرانك يتساهل يظهر شرب الخمر، أو يعامل بالربا، أو تعرف منه منكرًا آخر قد أظهره وبيَّنه للناس، ولم يبال، ولم يستح؛ يجب نصحه وتوجيهه إلى الخير، وتخويفه من الله  منك ومن بعض إخوانك تعاونوا على البر والتقوى، إذا كانت النصيحة من اثنين أو ثلاثة يكون أنفع لعله يتأثر، وتكرارها عليه كذلك لعله يستجيب. فإن أصر ولم يبال استحق أن يهجر كما هجر النبي ﷺ ثلاثة من الصحابة: كعب بن مالك وصاحباه هجرهم النبي ﷺ خمسين ليلة؛ لأنهم تخلفوا عن غزوة تبوك بغير عذر شرعي، وقد أمرهم بالغزو عليه الصلاة والسلام استنفرهم. فإذا كان الصحابة إذا حصل منهم معصية يهجرون فغيرهم من باب أولى، في المعصية الظاهرة أما الذي بينه وبين ربه الله الذي يعلمها  المستورة، لكن المقصود المعصية الظاهرة كترك الصلاة، والتعامل بالربا، وشرب الخمر علانية وما أشبه ذلك يستحق الهجر على ذلك إلا أن يستجيب ويهتدي فالحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18453/ما-كيفية-معاملة-من-لا-يصلي-او-يفعل-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_800/nour_80004.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":19304,"question":"ننتقل إلى رسالة أخرى وصلت إلى البرنامج من قطر، منطقة دخان، وباعثها أخ لنا من هناك يقول: عبد الله محمد الماحي -فيما يبدو- أخونا يسأل ويقول: هل هناك كتب تتحدث عن الملائكة، أرجو إعلامي بأيسرها حصولًا وفهمًا؟ جزاكم الله خيرًا.","title":"كتب تتكلم عن الملائكة","answer":"الجواب: أعظمها وأحسنها وأصدقها كتاب الله، ففيه البيان الكثير عن الملائكة وأعمالهم عليهم الصلاة والسلام ثم الأحاديث عن رسول الله ﷺ صحيح البخاري عقد للملائكة بابًا مستقلًا في كتابه الصحيح، وهكذا صحيح مسلم وهكذا السنن كلها فيها جملة أحاديث عن الملائكة وأخبار الملائكة عليهم الصلاة والسلام. ثم كتب أهل العلم فيما يتعلق بالملائكة وفي سيرة النبي عليه الصلاة والسلام، ومن أحسن ذلك صحيح البخاري وصحيح مسلم، ثم السنن الأربع فيما يتعلق بالملائكة، ثم ما كتب أهل العلم، ومن أحسن ذلك زاد المعاد في هدي خير العباد لابن القيم رحمه الله فإنه ذكر في الملائكة ما يشفي ويكفي رحمه الله.  المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18509/كتب-تتكلم-عن-الملاىكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_894/nour_89408.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19369,"question":"تسأل أيضًا عن كتاب سبل السلام؟","title":"تقييم كتاب (سبل السلام) للصنعاني","answer":"الجواب: كتاب سبل السلام معروف أيضًا، وهو للأمير محمد بن إسماعيل الصنعاني، وأصله لمؤلف مغربي وهو كتاب جيد مفيد على بلوغ المرام، وليس بشاف الشرح فيه نقص من جهة الشرح، ولكنه مفيد. المقدم: طيب جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18588/تقييم-كتاب-سبل-السلام-للصنعاني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_943/nour_94302.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19370,"question":"نعود في بداية هذه الحلقة إلى رسالة إحدى الأخوات المستمعات من العيون في الأحساء، هي: نوال سعد، أختنا نوال عرضنا بعض أسئلتها في حلقة مضت، وبقي لها في هذه الحلقة سؤالان تسأل في سؤالها الأول عن كتاب الترغيب والترهيب؟","title":"تقييم كتاب (الترغيب والترهيب) للمنذري","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله، وأصحابه، ومن اهتدى بهداه، أما بعد: فكتاب الترغيب كتاب مشهور معروف للحافظ المنذري، مشتمل على أحاديث كثيرة فيها الصحيح، وفيها الضعيف، وفيها الحسن، وقد أشار في كتابه إلى الضعيف بقوله: وروي، إذا لم يجزم به بل حكاه بصيغة التمريض، فذلك إشارة منه إلى أنه من الأحاديث الضعيفة، وهو كتاب مفيد وعظيم رحم الله مؤلفه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18587/تقييم-كتاب-الترغيب-والترهيب-للمنذري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_943/nour_94301.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19426,"question":"المستمعة (ب. ع) من الرياض عرضنا جزءًا من أسئلة لها في حلقة مضت وفي هذه الحلقة نرجو أن نستكمل ما تبقى من أسئلتها فتسأل هذا السؤال وتقول:هل يجوز للفتاة أن تقوم بنصح أقاربها من الرجال من غير المحارم وقراءة القرآن عليهم مرتلاً مجودًا بصوت حسن، علمًا أن ذلك لو كان فإن الفتاة ستقوم بالتحجب الكامل للوجه واليدين والقدمين، وأعني بذلك الغطاء الكامل لأنحاء الجسم بحيث لا يخرج منها إلا صوتها رغبة في الدعوة إلى الله؟","title":"حكم نصح المرأة لأقاربها وقراءة القرآن عليهم","answer":"الجواب: نعم يشرع لها النصح لأقاربها، سواء كانت فتاة شابة أو متوسطة أو كبيرة السن، النصيحة مطلوبة من الجميع، يقول النبي ﷺ: الدين النصيحة، الدين النصيحة، الدين النصيحة قيل: لمن يا رسول الله؟! قال: لله ولكتابه ولرسوله ولأئمة المسلمين وعامتهم هذا يشمل الرجال والنساء. وفي الصحيحين عن جرير بن عبد الله البجلي  قال: بايعت النبي ﷺ على إقام الصلاة وإيتاء الزكاة والنصح لكل مسلم. فلا مانع أن تنصح الفتاة إخوانها، وأقاربها، وبني عمها، وجيرانها من دون تكسر في الصوت ولا تغنج في الصوت ولا خضوع، بل تقرأ ما تقرأ من الأحاديث أو الآيات قراءة متوسطة ليس فيها شيء يفتن فيها ويسبب الفتنة بها أو وقوع ما لا تحمد عقباه، بل تقرأ قراءة عادية ليس فيها تكلف وليس فيها خضوع بالقول، إنما قراءة مستقيمة إذا دعت الحاجة إلى قراءة آية أو قراءة حديث للوعظ والتذكير كما قال الله جل وعلا: وَذَكِّرْ فَإِنَّ الذِّكْرَى تَنفَعُ الْمُؤْمِنِينَ [الذاريات:55] أو قرأت يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ [البقرة:278] يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَقُولُوا قَوْلًا سَدِيدًا [الأحزاب:70] يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ [النساء:1] وأشباه ذلك. المقصود إذا قرأت بعض الآيات للنصيحة القراءة العادية فلا بأس، وإن كانت تخشى الفتنة فلا تقرأ تنصح من دون قراءة، اتقوا الله، اتركوا هذا، هذا لا يجوز، الدخان لا يجوز ، شرب المسكر لا يجوز ، النميمة الغيبة لا تجوز ما في حاجة إلى أن تقرأ إذا كانت تخشى الفتنة بصوتها فإنها تنصحهم من دون حاجة، وإن قرأت قراءة عابرة قراءة ليس فيها فتنة فلا بأس بذلك. والحاصل أن هذا يرجع إلى ما تعلمه هي، وما يغلب على ظنها إن كانت تخشى فتنة فإنها لا ترتل القراءة المرتلة وتأمر وتنهى وتنصح من دون حاجة إلى قراءة مرتلة بالتجويد وتذكر الأحاديث بالصوت العادي؛ لأن الله جل وعلا قال: يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32] فقد يطمع بعض الناس إذا رأى رقة صوتها وحسن صوتها، قد يطمع بعض الناس في مغازلتها من بعض الجهات أو فعل شيء يؤذيها. فالحاصل أنها تعمل بما هو أحوط ولا حاجة إلى أن تفعل شيئًا قد يضرها، والنصيحة لا تتوقف على هذا في إمكانها أن تنصح وتأمر وتنهى من دون حاجة إلى قراءة آيات، بل تخبرهم بأمر الله ورسوله والحمد لله.  المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18660/حكم-نصح-المراة-لاقاربها-وقراءة-القران-عليهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_937/nour_93706.mp3","categories":["الدعوة والدعاة"]},{"id":19524,"question":"يا سماحة الشيخ! هذه السائلة تقول: هل للمرأة أن تذهب لطلب العلم، وما هي المواد الشرعية التي تنصحون بدراستها؟","title":"حكم طلب العلم للمرأة وكيفية ذلك","answer":"الجواب: نعم، يشرع لها بل يجب عليها أن تتعلم لسماع العلم من طريق الإذاعة، من طريق إذاعة القرآن، من طريق زيارة النساء المعلمات، حضور مجالس العلم التي تستطيع حضورها مع التستر حتى تسمع الفائدة والعلم، سؤال أهل العلم بالتلفون، أو بالمكاتبة، كل هذا من طلب العلم، النبي  يقول: من يرد الله به خيرًا يفقهه في الدين فإذا كان هناك امرأة تعلم النساء وجب عليها أن تذهب إليها مع النساء للتعلم، والتفقه في الدين، وإذا كان هناك حلقات علم للرجال، وحولها مجالس للنساء، محلات نساء خاصة يسمعن العلم تذهب تسمع العلم مع التستر والتحفظ، والبعد عن أسباب الفتنة، وإذا سألت من طريق الهاتف، من طريق التلفون أو المكاتبة تسأل أهل العلم عما أشكل عليها كل هذا من أسباب تحصيل العلم، والله يقول جل وعلا في كتابه العظيم: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16] . المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18779/حكم-طلب-العلم-للمراة-وكيفية-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94618.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19537,"question":"هذه رسالة وصلت من الجزائر العاصمة الأخت (ج.ب) تقول في هذا  امرأة تبلغ من العمر خمسين سنة، ولم تصل طيلة حياتها أبدًا حتى يومنا هذا، ولم تقض ما أفطرت من رمضان أثناء الحيض أبدًا، ماذا يجب عليها أن تفعل إذا أرادت التوبة، وهل تصوم جميع تلك السنين التي أفطرتها من رمضان أثناء الحيض ولم تقض مع العلم بأنها لم تكن تصلي وما تزال لا تصلي حتى الآن، وهذه المرأة قريبة لأمي، وجارة لنا في نفس الوقت، كيف ننصحها لكي تتوب إلى الله؛ لأننا نصحناها عدة مرات بدون جدوى، لقد نصحناها برفق، وبالتي هي أحسن هل نكون بريئين من ذمتها إذا لم تتوب، وجهوها مأجورين؟","title":"حكم القريب الذي لا يصلي رغم نصحه","answer":"الجواب: الواجب نصيحتها وإخبارها بأنها إذا تابت تاب الله عليها، عليها التوبة مما مضى، ويسقط عنها الصوم، والصلاة الماضي، عليها التوبة الصادقة بالندم على ما مضى، والإقلاع من ذلك، والعزم أن لا تعود في ذلك، مع الضراعة إلى الله، وسؤاله أن يقبل منها توبتها، وعليها أن تصلي، وتصوم بعد التوبة، إلا في وقت الحيض فالله أسقط عنها الصلاة، فإذا جاء الحيض فلا صلاة عليها، وإذا جاء الحيض في رمضان أفطرت وقضت. فالواجب أن تعلموها وأن ترشدوها، وأن تنصحوها، ومن تاب تاب الله عليه يقول الله جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا[التحريم:8] ويقول جل وعلا في كتابه العزيز: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ[النور:31] ويقول النبي ﷺ: التائب من الذنب كمن لا ذنب له، فإذا تابت عفا الله عنها، وليس عليها قضاء لا للصلاة، ولا للصوم، عليها التوبة فقط، ولا قضاء عليها، وعليها أن تجتهد في المستقبل في المحافظة على الصلوات، والصيام. المقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/18789/حكم-القريب-الذي-لا-يصلي-رغم-نصحه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94622.mp3","categories":["حكم الصلاة وأهميتها","الدعوة والدعاة"]},{"id":19581,"question":"كيف يمكن للمرأة أن تطلب العلم وهي في منزلها؟ وهل قراءة الكتب وسماع المحاضرات عبر الأشرطة يعتبر من طلب العلم؟","title":"كيفية طلب المرأة للعلم","answer":"الجواب: نعم، سماع الأشرطة، والندوات العلمية، ونور على الدرب من إذاعة القرآن، كل هذا من طلب العلم، قراءة الكتب المفيدة، وسؤال أهل العلم من طريق الهاتف، أو من طريق المكاتبة هذا كله من سبل العلم، ومن تحصيل العلم؛ لأن الله يقول سبحانه: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ[النحل:43]، ويقول ﷺ: من سلك طريقًا يلتمس فيه علمًا سهل الله له به طريقًا إلى الجنة، ولم يحدد طريقًا دون طريق. فسؤال أهل العلم من طريق الهاتف، ومن طريق المكاتبة أو المشافهة كله من طلب العلم، وقراءة الكتب المفيدة من طلب العلم، وسماع القرآن، والإكثار من قراءة القرآن من أعظم سبل العلم؛ لأن القرآن هو كتاب الله، هو أعظم دليل على العلم، وهو أعظم مرشد، فينبغي الإكثار من قراءة القرآن بالتدبر، والتعقل، والسؤال عما أشكل، كل هذا من طرق العلم. وإذاعة القرآن من أفضل الأسباب، أنا أوصي بالعناية بإذاعة القرآن لسماع ما يذاع فيها من العلوم النافعة، ونور على الدرب، والمواضيع الكثيرة. نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/18857/كيفية-طلب-المراة-للعلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94731.mp3","categories":["الدعوة والدعاة","العالم والمتعلم"]},{"id":19623,"question":"تقول هذه السائلة لي أخت عاقة لأمها، وعندما أحاول أن أنصحها تقوم بشتمي، ومخاصمتي، وهي التي تبدأ بالمخاصمة، فكيف أتصرف معها مع العلم بأنني لا أكلمها إلا قليلًا جدًا، ولا تقبل النصيحة، وترى نفسها على الطريق المستقيم، وهي خلاف ذلك؟","title":"كيفية تصرف الأخت مع أختها العاقة لوالدتها والتي لا تقبل النصيحة","answer":"الجواب: عليك النصيحة بالكلام الطيب، والأسلوب الحسن، قولي: يا فلانة اتقي الله، بر أمك من أهم الواجبات، اصبري عليها وأحسني إليها بالكلام الطيب، والأسلوب الحسن، يا فلانة! يا أختي فلانة! اتقي الله، راقبي الله، ولو زعلت، ولو ما رضيت؛ لأن الله يقول: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة: 71] وعقوقها لأمها منكر، وأنتِ إن شاء الله من المؤمنات فأنكري عليها، وعلميها بالأسلوب الحسن، والكلام الطيب، وإذا تيسر أن تنصحي بعض أقاربك ينصحونها كإخوتها، أو أخوالها، أو أبيها إن كان أبوها موجودًا حتى ينصحوها معك، حتى يساعدوك عليها. نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18892/كيفية-تصرف-الاخت-مع-اختها-العاقة-لوالدتها-والتي-لا-تقبل-النصيحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94823.mp3","categories":["الدعوة والدعاة"]},{"id":19706,"question":"بعد هذا ننتقل إلى حفر الباطن من المنطق الشرقية، عبر رسالة بعث بها المستمع محمد طه إبراهيم، الأخ محمد يقول: لو تكرمتم سماحة الشيخ دلوني على الكتب الفقهية التي أستفيد منها في ديني ودنياي؟","title":"بعض الكتب الفقهية المفيدة","answer":"الجواب:\nنعم، كتب الفقه كثيرة لكن من أحسنها الحاشية لابن جاسم الشيخ عبد الرحمن بن جاسم على الروض المربع في شرح زاد المستقنع، وهي مطبوعة وموجودة ومن أحسنها، المقنع للموفق ابن قدامة عليه حاشية للشيخ سليمان بن عبد الله آل الشيخ جيدة مفيدة، ومن أحسنها العمدة للموفق مختصرة في الفقه، لعبد الله بن أحمد بن قدامة صاحب المغني، ومن أحسنها دليل الطالب وشرحه منار السبيل شرح الدليل وعليه تخريج لأخينا في الله العلامة الشيخ محمد ناصر الدين الألباني هذه كلها كتب مفيدة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/26341/بعض-الكتب-الفقهية-المفيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/%D8%A8%D8%B9%D8%B6%20%D8%A7%D9%84%D9%83%D8%AA%D8%A8%20%D8%A7%D9%84%D9%81%D9%82%D9%87%D9%8A%D8%A9%20%D8%A7%D9%84%D9%85%D9%81%D9%8A%D8%AF%D8%A9.MP3","categories":["الدعوة والدعاة","العالم والمتعلم"]}]
